object Main extends App {

  val Array(n ,x) = readLine.trim.split(' ').map(_.toInt)
  val tests = Array.tabulate(n){_ ⇒
    val Array(b, l, u) = readLine.trim.split(' ').map(_.toLong)
    Test(b, l, u)
  }.sortBy{test ⇒
    (x - test.score) * test.upper + test.score * test.lower
  }(Ordering.Long.reverse)
  val default = tests.map{test ⇒ -test.score * test.lower}.sum
  var min = 0L
  var max = x * n.toLong
  while (min < max) {
    val mid = (max + min) / 2
    if (canWin(tests, x, mid)) {
      max = mid
    }else {
      min = mid + 1
    }
  }
  println(min)
  def canWin(tests: Array[Test], x: Int, time: Long): Boolean = {
    if (tests.length * x <= time) { return true}
    val full = (time / x).toInt
    val fullScore = (0 until full).map{i ⇒ tests(i).upper * x - tests(i).score * (tests(i).upper - tests(i).lower)}.sum
    var rest = time % x
    for ((test, i) ← tests.zipWithIndex){
      val base = if (i < full) fullScore - (tests(i).upper * x - tests(i).score * (tests(i).upper - tests(i).lower)) + (tests(full).upper * x - tests(full).score * (tests(full).upper - tests(full).lower)) else fullScore

      val add = if (rest >= test.score) test.upper * (rest - test.score) + test.lower * test.score else test.lower * rest
      if (base + add + default >= 0) return true
    }
    false
  }
  case class Test(score: Long, lower: Long, upper: Long)
}

object Main {
  import java.io.{BufferedReader, InputStream, InputStreamReader}
  import java.util.StringTokenizer
  import scala.reflect.ClassTag

  def main(args: Array[String]): Unit = {
    val out = new java.io.PrintWriter(System.out)
    new Main(out, new InputReader(System.in)).solve()
    out.flush()
  }

  private val oj = System.getenv("ATCODER_DEBUG") == null
  def DEBUG(f: => Unit): Unit = {
    if (!oj){ f }
  }
  def debug(as: Array[Boolean]): Unit = if (!oj){ debug(as.map(x => if(x) "1" else "0").mkString) }
  def debug(as: Array[Int]): Unit = if (!oj){ debug(as.mkString(" ")) }
  def debug(as: Array[Long]): Unit =if (!oj){ debug(as.mkString(" ")) }
  def debugDim(m: Array[Array[Long]]): Unit = if (!oj){
    REP(m.length) { i =>
      debug(m(i))
    }
  }
  def debugDimFlip(m: Array[Array[Long]]): Unit = if (!oj){
    REP(m(0).length) { j =>
      REP(m.length) { i =>
        System.err.print(m(i)(j))
        System.err.print(" ")
      }
      System.err.println()
    }
  }
  def debug(s: => String): Unit = DEBUG {
    System.err.println(s)
  }
  def debugL(num: => Long): Unit = DEBUG {
    System.err.println(num)
  }

  class InputReader(val stream: InputStream) {
    private val reader = new BufferedReader(new InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer = _

    def next(): String = {
      while (tokenizer == null || !tokenizer.hasMoreTokens)
        tokenizer = new StringTokenizer(reader.readLine)
      tokenizer.nextToken
    }

    def nextInt(): Int = Integer.parseInt(next())
    def nextLong(): Long = java.lang.Long.parseLong(next())
    def nextChar(): Char = next().charAt(0)

    def ni(): Int = nextInt()
    def nl(): Long = nextLong()
    def nc(): Char = nextChar()
    def ns(): String = next()
    def ns(n: Int): Array[Char] = ns().toCharArray
    def na(n: Int, offset: Int = 0): Array[Int] = map(n)(_ => ni() + offset)
    def na2(n: Int, offset: Int = 0): (Array[Int], Array[Int]) = {
      val A1, A2 = Array.ofDim[Int](n)
      REP(n) { i =>
        A1(i) = ni() + offset
        A2(i) = ni() + offset
      }
      (A1, A2)
    }
    def nm(n: Int, m: Int): Array[Array[Int]] = {
      val A = Array.ofDim[Int](n, m)
      REP(n) { i =>
        REP(m) { j =>
          A(i)(j) = ni()
        }
      }
      A
    }
    def nal(n: Int): Array[Long] = map(n)(_ => nl())
    def nm_c(n: Int, m: Int): Array[Array[Char]] = map(n) (_ => ns(m))
  }

  def REP(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = offset
    val N = n + offset
    while(i < N) { f(i); i += 1 }
  }
  def REP_r(n: Int, offset: Int = 0)(f: Int => Unit): Unit = {
    var i = n - 1 + offset
    while(i >= offset) { f(i); i -= 1 }
  }
  def TO(from: Int, to: Int)(f: Int => Unit): Unit = {
    REP(to - from + 1, from) { i =>
      f(i)
    }
  }
  def map[@specialized A: ClassTag](n: Int, offset: Int = 0)(f: Int => A): Array[A] = {
    val res = Array.ofDim[A](n)
    REP(n)(i => res(i) = f(i + offset))
    res
  }

  def sumL(as: Array[Int]): Long = {
    var s = 0L
    REP(as.length)(i => s += as(i))
    s
  }
  def cumSum(as: Array[Int]): Array[Long] = {
    val cum = Array.ofDim[Long](as.length + 1)
    REP(as.length) { i =>
      cum(i + 1) = cum(i) + as(i)
    }
    cum
  }
}

case class Question(b: Int, l: Int, u: Int)
case class Val(i: Int, v: Long)

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  def solve(): Unit = {
    import java.util.Comparator
    val N, X = ni()

    var sum = 0L

    val forX = Array.ofDim[Val](N)
    val questions = Array.ofDim[Question](N)

    REP(N) { i =>
      val b, l, u = ni()
      forX(i) = Val(i, l.toLong * b + (X - b).toLong * u)
      questions(i) = Question(b, l, u)
      sum += b.toLong * l
    }

    debug(s"sum:$sum")

    sort(forX, new Comparator[Val] {
      override def compare(o1: Val, o2: Val): Int = -java.lang.Long.compare(o1.v, o2.v)
    })

    val forXSum = Array.ofDim[Long](N + 1)
    REP(N) { i =>
      forXSum(i + 1) = forXSum(i) + forX(i).v
    }

    debug(forX.mkString(" "))
    debug(forXSum)

    def test(a: Long): Boolean = {
      debug(s"a:$a")
      val p = (a / X).toInt
      val cnt = a % X

      REP(N) { ii =>
        val i = forX(ii).i
        val q = questions(i)
        val remain = if (cnt <= q.b) {
          cnt * q.l
        } else {
          q.b.toLong * q.l + (cnt - q.b) * q.u
        }

        val sumX = if (ii < p) {
          forXSum(p + 1) - forX(ii).v
        } else {
          forXSum(p)
        }

        debug(s"sumX:$sumX remain:$remain")
        if (sumX + remain >= sum) return true
      }

      false
    }

    val ans = findMin(test, 0L, sumL(questions.map(_.b)))
    out.println(ans)
  }

  /**
    * 単調増加
    * (l, h] 方式
    */
  def findMin(f: Long => Boolean, min: Long, max: Long): Long = {
    var l = min - 1
    var h = max
    while(h - l > 1) {
      val x = (h + l) / 2
      if (f(x)) h = x
      else l = x
    }
    h
  }
}

