case class Question(b: Int, l: Int, u: Int)
case class Entry(i: Int, v: Long)
case class Val(i: Int, v: Long)

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  // toIntとか+7とかするならvalにしろ
  @inline private def MOD = 1000000007

  def solve(): Unit = {
    import java.util.Comparator
    val N, X = ni()

    var sum = 0L

    val forX = Array.ofDim[Val](N)
    val questions = Array.ofDim[Question](N)

    REP(N) { i =>
      val b, l, u = ni()
      forX(i) = Val(i, l.toLong * b + (X - b).toLong * u)
      questions(i) = Question(b, l, u)
      sum += b.toLong * l
    }

    debug(s"sum:$sum")

    sort(forX, new Comparator[Val] {
      override def compare(o1: Val, o2: Val): Int = -java.lang.Long.compare(o1.v, o2.v)
    })

    val forXSum = Array.ofDim[Long](N + 1)
    REP(N) { i =>
      forXSum(i + 1) = forXSum(i) + forX(i).v
    }

    debug(forX.mkString(" "))
    debug(forXSum)

    def test(a: Long): Boolean = {
      val p = a / X
      val cnt = a % X

      if (p >= N) return true

      val needs = sum - forXSum(p.toInt)

      debug(s"a: $a p:$p cnt:$cnt needs:$needs")

      if (needs <= 0) true
      else if (cnt == 0) false
      else {
        var mx: Entry = null
        TO(p.toInt, N - 1) { ii =>
          val i = forX(ii).i
          val q = questions(i)
          val entry = if (cnt <= q.b) {
            Entry(i, cnt * q.l)
          } else {
            val v = q.b.toLong * q.l + (cnt - q.b) * q.u
            Entry(i, v)
          }
          debug(s"i:$i entry:$entry")
          if (mx == null || entry.v > mx.v) mx = entry
        }

        val e = mx
        debug(s"cnt:$cnt e:$e")
        needs <= e.v
      }
    }

    val ans = findMin(test, 0L, sumL(questions.map(_.b)))
    out.println(ans)
  }

  /**
    * 単調増加
    * (l, h] 方式
    */
  def findMin(f: Long => Boolean, min: Long, max: Long): Long = {
    var l = min - 1
    var h = max
    while(h - l > 1) {
      val x = (h + l) / 2
      if (f(x)) h = x
      else l = x
    }
    h
  }
}

