  scanf("%d%lld",&n,&m);
  for (i=0; i<n; i++) {
    scanf("%lld%d%d",&b[i],&l[i],&u[i]);
    s+=b[i]*l[i];
    c[i]=(m-b[i])*u[i]+b[i]*l[i];
    ri+=b[i];
    k[i]=i;
  }
  if (s==0) { puts("0"); return 0; }
  sort(k,k+n,cmpc);
  while (le<ri) {
