            ll single = a[i].b <= small ? 1LL * a[i].u * small - 1LL * (a[i].u - a[i].l) * a[i].b : 1LL * a[i].l * small;
            if (i <= full) {
                ans = max(ans, sum - a[i].s + single);
            }else {
                ans = max(ans, sum - a[full].s + single);
            }
        }
        return ans >= need;
    };

    ll l = 0, r = 1LL * n * m;
    while (l < r) {
        ll mid = (l + r) >> 1;
        if (check(mid)) {
            r = mid;
        }else {
            l = mid + 1;
        }
    }
    cout << r << endl;

    #ifdef LOCAL
        #if __cplusplus >= 201103L
        auto end = steady_clock::now();
        duration<double> time_span = duration_cast<duration<double>>(end - start);;
        printf("Total time: %.6fs\n", time_span.count());
        #endif
    #endif
    return 0;
}

