const int MAXN = 105000;
const double eps = 1e-9;

int n, x;
int b[MAXN], low[MAXN], up[MAXN];
long long total;

bool can(long long mid) {
  if (mid == 0) {
    return total == 0;
  }

  vector < pair<double, int> > v;
  long long tm = mid > x ? x : mid;
  for (int i = 0; i < n; i++) {
    double ratio = 0.0;
    if (tm < b[i]) {
      ratio = low[i];
    } else {
      ratio = 1.0 * (1ll * low[i] * b[i] + 1ll * (tm - b[i]) * up[i]) / tm;
    }
    v.push_back({ratio, i});
  }

  sort(all(v));
  reverse(all(v));
  set <int> used;

  double rem = total;
  for (int i = 0; i < n; i++) {
    mid -= tm;
    rem += v[i].first * tm;
    used.insert(v[i].second);
    if (mid == 0 || (tm == x && mid < x)) {
      break;
    }
  }

  if (mid == 0) {
    return rem + eps >= 0.0;
  }

  v.clear();
  tm = mid;
  for (int i = 0; i < n; i++) {
    if (used.count(i)) {
      continue;
    }
    double ratio = 0.0;
    if (tm < b[i]) {
      ratio = low[i];
    } else {
      ratio = 1.0 * (1ll * low[i] * b[i] + 1ll * (tm - b[i]) * up[i]) / tm;
    }
    v.push_back({ratio, i});
  }
  sort(all(v));
  reverse(all(v));

  for (int i = 0; i < sz(v); i++) {
    mid -= tm;
    rem += v[i].first * tm;
    used.insert(v[i].second);
    if (mid == 0 || (tm == x && mid < x)) {
      break;
    }
  }

  return rem + eps >= 0.0;
}

