class test {
public:
	ll b, l, u;
	ll dif() const {
		ll mt = min(tim, x);
		ll r1 = (mt * u + l * b - u * b);
		ll r2 = (mt * l);
		return max(r1, r2);
	}
	bool operator<(const test& e) const {
		if (dif() == e.dif()) {
			return b < e.b;
		}
		return dif() > e.dif();
	}
};

vector<test> t;

ll maxdiff(ll time) {
	tim = time;
	sort(t.begin(), t.end());
	ll ret = 0;
	ll time_remain = time;
	auto itr = t.begin();
	for (; itr != t.end() && time_remain >= x; itr++) {
		time_remain -= x;
		ret += itr->dif();
	}
	if (itr == t.end()) return ret;
	tim = time_remain;
	sort(itr, t.end());
	ret += itr->dif();
	return ret;
}

