  rep(i,n) {
    s[i+1] = s[i] + ps[i].first;
  }

  // return true when A can win with k.
  auto check = [&](ll k) {
    ll q = k/x;
    ll r = k-q*x;
    rep(i,n) {
      P p = ps[i];
      ll idx = p.second;

      ll now = di(idx,r); // D+loss
      if (i < q) { // add sum of [0,q+1) except for idx.
        now += s[q+1];
        now -= p.first;
      } else {
        now += s[q]; // add sum of [0,q)
      }
      // TODO:
      if (now - loss >= 0) { return true; }
    }
    return false;
  };

  ll lt = -1, rt = n*x;
  while (rt-lt > 1) {
    ll m = (lt+rt)/2;
    if (check(m)) {
      rt = m;
    } else {
      lt = m;
    }
  }
  // Here, r is min ok.
  cout << rt << endl;
}

