    bool operator < (const Exam &e) {
        LL c0 = 1ll*X*r - 1ll*b*(r-l);
        LL c1 = 1ll*X*e.r - 1ll*e.b*(e.r-e.l);
        return c0 > c1;
    }
}E[N];

bool ok(LL days) {
    LL full = days/X, extra = days%X;
    if(full == n) return 1;
    for(int i = 1; i <= n; i++) {
        LL cur_X = 1ll*(X-E[i].b)*E[i].r;
        LL cur_0 = -1ll*E[i].b*E[i].l;
        LL D = 0;
        if(i <= full) D += pre_X[full+1] - cur_X + pre_0[full+2];
        else D += pre_X[full] + pre_0[full+1] - cur_0;
        if(extra <= E[i].b) D += 1ll*(extra-E[i].b)*E[i].l;
        else D += 1ll*(extra-E[i].b)*E[i].r;
        if(D >= 0) return 1;
    }
    return 0;
}

