            //cout << (u[idx]*(rem-b[idx])) << endl;
        }
        sort(v.begin(), v.end(), greater<P>());
        score += v[0].first;

        //もうひとパターン
        ll score1 = 0, score2 = 0;
        vector<P> v1, v2;
        for(int i = 0; i <= m; i++){
            score1 += p[i].first;
            score2 += p[i].first;
        }
        for(int i = 0; i <= m; i++){
            int idx = p[i].second;
            v1.push_back(P(-u[idx]*X+u[idx]*rem, idx));
            v2.push_back(P(-u[idx]*X+l[idx]*rem, idx));
