using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

void solve(long long N, long long X, vector<long long> b, vector<long long> l, vector<long long> u){
	priority_queue<P> que;
	ll a = 0, t = 0, res = 0;
	for(ll i = 0 ; i <= N-1 ; i++){
		a += b[i]*l[i];
	}
	for(ll i = 0 ; i <= N-1 ; i++){
		que.push(P(u[i], i));
	}
	while (!que.empty()) {
		P p = que.top(); que.pop();
		ll v = p.second;
		a += b[v]*(u[v]-l[v]);
		// cout << b[v] << endl;
		if (t + X*u[v] < a) {
			t = X*u[v];
			res += X;
		} else {
			res += (a-t+u[v]-1)/u[v];
			break;
		}
	}
	cout << res << endl;
}

