int main() {
    int n, x; cin >> n >> x;
    long long b[n], l[n], u[n];
    for (int i = 0; i < n; i++) cin >> b[i] >> l[i] >> u[i];
    vector<int> v(n);
    iota(v.begin(), v.end(), 0);
    sort(v.begin(), v.end(),
         [&](int i, int j) {
             return (u[i] - l[i]) * b[i] - u[i] * x > (u[j] - l[j]) * b[j] - u[j] * x;
         });
    long long sum = 0, ans = 0;
    for (int i = n-1; i >= 0; i--) sum -= l[i] * b[i];
    // cerr << sum << endl;
    for (int i = n-1; i >= 0; i--) {
        int j = v[i];
        long long tmp = u[j] * (x - b[j]) + l[j] * b[j];
        // cerr << tmp << endl;
        if (sum + tmp < 0) sum += tmp, ans += x;
        else {
            long long add = 1LL<<60;
            do {
                j = v[i];
                if (sum + l[j] * b[j] >= 0) {
                    add = min(add, (-sum + l[j] - 1) / l[j]);
                } else {
                    long long amt = -(l[j] * b[j] + sum);
                    // cerr << "amt " << amt << endl;
                    add = min(add, b[j] + (amt + u[j] - 1) / u[j]);
                }
            } while (i--);
            ans += add;
            break;
        }
        // cerr << ans << endl;
    }
    cout << ans << endl;
}

