struct info{
    info(){
        check = false;
    }

    long long b;
    long long l;
    long long u;
    long long d;
    long long min_b;
    bool check;
};


bool comp(const info& l, const info& r){
    if(l.d == r.d){
        l.l < r.l;
    }
    return l.d > r.d;
}

bool comp2(const info& l, const info& r){
    return l.l > r.l;
}


int main(int argc, char* argv[]){
    int N, X;
    cin >> N >> X;
    vector<info> info_vec(N);

    int b;
    int l;
    int u;

    long long b_sum = 0;

    for(int i = 0; i < N; ++i){
        cin >> b >> l >> u;

        info_vec[i].b = b;
        info_vec[i].u = u;
        info_vec[i].l = l;
        info_vec[i].d = (X - b) * u;
        info_vec[i].min_b = l * b;

        b_sum += info_vec[i].min_b;
    }

    std::sort(info_vec.begin(), info_vec.end(), comp);

    long long time_sum = 0;
    int i;
    long long last_time = 0;

    for(i = 0; i < N; ++i){
        b_sum -= info_vec[i].min_b;

        if(b_sum <= info_vec[i].d){
            last_time = info_vec[i].b + ceil(b_sum / (double)info_vec[i].u);
            b_sum += info_vec[i].min_b;
            break;
        }
        else{
            time_sum += X;
            b_sum -= info_vec[i].d;
            info_vec[i].check = true;
        }
    }

    if(b_sum != 0){
        std::sort(info_vec.begin(), info_vec.end(), comp2);
        for(i = 0; i < N; ++i){
            if(info_vec[i].check)continue;

            long long time_cand = ceil(b_sum / (double)info_vec[i].l);

            time_sum += min(time_cand, last_time);
            break;
        }
    }

    cout << time_sum;

}

