#include <bits/stdc++.h>
using namespace std;

int N, X;
vector<vector<int>> A;

bool check(long long m)
{
    long long score_a = 0;
    long long score_b = 0;

    long long cnt = m / X;
    if(cnt >= N)
        return true;

    for(auto i = 0; i < cnt; ++i)
    {
        score_a += (long long)X * A[i][2];
        score_b += (long long)A[i][0] * A[i][2];   
    }

    long long max_val = -1;
    auto max_idx = -1;
    for(auto i = cnt; i < N; ++i)
    {
        long long candi = (long long)(m % X) * A[i][1];
        if(m % X > A[i][0])
            candi = (long long)(m % X) * A[i][2] - (long long)A[i][0] * (A[i][2] - A[i][1]);

        if(candi > max_val) {
            max_val = candi;
            max_idx = i;
        }
    }

    for(auto i = cnt; i < N; ++i)
    {
        if(i == max_idx) {
            if(m % X > A[i][0]) {
                score_a += (long long)(m % X) * A[i][2];
                score_b += (long long)A[i][0] * A[i][2];
            }
            else {
                score_a += (long long)(m % X) * A[i][1];
                score_b += (long long)A[i][0] * A[i][1];
            }
        }
        else {
            score_b += (long long)A[i][0] * A[i][1];
        }
    }

    return score_a >= score_b;
}

void solve()
{
    cin >> N >> X;

    A = vector<vector<int>>(N, vector<int>(3));

    for(auto i = 0; i < N; ++i)
    {
        cin >> A[i][0] >> A[i][1] >> A[i][2];
    }

    sort(A.begin(), A.end(), [](const vector<int>& lhs, const vector<int>& rhs) {
        return -((long long)X - lhs[0]) * lhs[2] < -((long long)X - rhs[0]) * rhs[2];
    });

    long long l = -1;
    long long r = (long long)N * X;

    while(l+1 < r) {
        long long m = (l+r) / 2;
        if(check(m))
            r = m;
        else
            l = m;
    }

    cout << r << endl;
}

int main()
{
    cin.sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    solve();
}

