		ll cs = (mc - 1 <= i ? ps[mc - 1] : ps[mc] - a[i].first);
		if (cs + b[j] * l[j] >= res)
			ans = min(ans, (res - cs + l[j] - 1) / l[j] + (mc - 1) * x);
		else if (cs + b[j] * l[j] + (x - b[j]) * r[j] >= res) {
			ans = min(ans, (res - cs - b[j] * l[j] + b[j] * r[j] + r[j] - 1) / r[j] + (mc - 1) * x);
		}
	}
	cout << ans;
}

