  // dump(w.size());
  // for(int i = x - 2; i >= 0; i--) {
  //   w[i].second = min(w[i].second, w[i + 1].second);
  // }

  if(d == 0) ans = res;

  for(int i = 0; i < n; i++) if(used[i] == 0) {
    ll ok = x, ng = 0;
    while(abs(ok - ng) > 1) {
      ll mid = (ok + ng) >> 1;
      ll L = min(mid, b[i]);
      ll k = 0;
      k += L * l[i];
      k += u[i] * (mid - L);
      if(k >= d) ok = mid; else ng = mid;
    }
    ans = min(ans, res + ok);

    if(fff) {
      auto rr = res + x;
      {
        ll f = d - (l[i] * b[i] + u[i] * (x - b[i]));
        f *= -1;
        ll ok = 0, ng = x + 1;
