class Solve {
public:
    Int N, X;
    vector<Int> b, l, u;

    void sort_blu() {
        vector<Int> idx(N);
        iota(all(idx), 0);

        sort(all(idx), [&](Int i, Int j) {
            Int lval = (X - b[i]) * u[i] + b[i] * l[i];
            Int rval = (X - b[j]) * u[j] + b[j] * l[j];

            return lval > rval;
        });


        vector<Int> bb, ll, uu;
        for (auto e : idx) {
            bb.push_back(b[e]);
            ll.push_back(l[e]);
            uu.push_back(u[e]);
        }
        b = bb;
        l = ll;
        u = uu;
    }

    bool judge(Int z) {
        Int base = 0;
        for (int i = 0; i < N; ++i) {
            base -= l[i] * b[i];
        }

        Int m = z % X; //tyuutohanpa na tokoro
        Int d = (z - m) / X; //all toru, d <= N

        auto f = [&](int i, Int x) {
            if (x < b[i]) {
                return x * l[i];
            }
            return b[i] * l[i] + (x - b[i]) * u[i];
        };

        if (m == 0) {
            Int val = base;
            for (int i = 0; i < d; ++i) {
                val += f(i, X);
            }
            return val >= 0;
        }


        Int sum = 0;
        for (int i = 0; i < d; ++i) {
            sum += f(i, X);
        }

        for (int i = 0; i < N; ++i) {
            // i is tyutohanpa number
            Int val = sum + base;
            if (i < d) {
                val -= f(i, X);
                val += f(d, X);
            }
            val += f(i, m);
            if (val >= 0) return true;
        }
        return false;
    }

    void solve() {
        cin >> N >> X;
        for (int i = 0; i < N; ++i) {
            b.push_back(0);
            l.push_back(0);
            u.push_back(0);
            cin >> b.back() >> l.back() >> u.back();
        }
        sort_blu();

        Int ng = 0;
        Int ok = N * X;
        while (ok - ng > 1) {
            Int mid = (ok + ng) / 2;
            if (judge(mid)) {
                ok = mid;
            } else {
                ng = mid;
            }
        }

        cout << ok << endl;

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

