bool judge(ll m)
{
    priority_queue<node>q;
    ll sum=0;
    for(int i=1;i<=n;i++)
    {
        if(m>=a[i].b)
        {
            sum+=(min(m,(ll)x)-a[i].b)*a[i].r;
            a[i].v=(min(m,(ll)x)-a[i].b)*a[i].r;
            a[i].a=min(m,(ll)x);
            m-=a[i].a;
            q.push(a[i]);
        }
        else
        {
            while(!q.empty()&&q.top().a==0) q.pop();
            if(q.empty())
            {
                sum-=(ll)a[i].b*a[i].l;
                continue;
            }
            node now=q.top();q.pop();
            if(now.v+(min(m,(ll)x)-a[i].b)*a[i].l<(min((ll)x,now.a+m)-a[i].b)*a[i].r+(now.a+m-min((ll)x,now.a+m)-now.b)*now.l)
            {
                ll x=now.a+m-min((ll)x,now.a+m),y=min((ll)x,now.a+m);
                sum=sum-now.v;
                now.v=(now.a+m-min((ll)x,now.a+m)-now.b)*now.l;a[i].v=(min((ll)x,now.a+m)-a[i].b)*a[i].r;
                sum+=now.v+a[i].v;
                m=m+now.a-x-y;
                now.a=x;
                a[i].a=y;
                q.push(now);
                q.push(a[i]);
