  return r * (x - b) + b * l;
}

ll bs(ll rem, ll x, ll b, ll l, ll r) {
  ll bl = 0, br = x + 1;
  while(br - bl > 1) {
    ll mid = (bl + br) / 2;
    if(f(mid, b, l, r) > rem) {
      br = mid;
    } else {
      bl = mid;
    }
  }
  return bl;
}

