{
    return a.tt > b.tt;
}

bool can(ll t)
{
    ll full = t / x;
    ll more = t % x;
    for (int i = 0; i < a.size(); i++)
        a[i].tt = (x - a[i].b) * a[i].r + a[i].b ;
    sort(a.begin(), a.end(), comp);
    ll we = 0, he = 0;
    for (int i = 0; i < full; i++)
    {
        we += x * a[i].r;
        he += a[i].b * a[i].r;
    }
    for (int i = full; i < n; i++)
    {
        he += a[i].l * a[i].b;
    }
    for (int i = full; i < n; i++)
    {
        //if (more >= a[i].b)
        //{
            he += (a[i].r - a[i].l) * a[i].b;
            we += a[i].r * more;
            if (we >= he)
                return 1;
            we -= a[i].r * more;
            he -= (a[i].r - a[i].l) * a[i].b;
        //}
        //else
        //{
            we += a[i].l * more;
            if (we >= he)
                return 1;
            we -= a[i].l * more;
        //}
    }
    if (full != n)
    {
        we += x * a[full].r;
        he += a[full].b * a[full].r;
    }
    for (int i = 0; i < full; i++)
    {
        we -= x * a[i].r;
        we += more * a[i].r;
        if (we >= he)
            return 1;
        we -= more * a[i].r;
        we += x * a[i].r;

        we -= x * a[i].r;
        we += more * a[i].l;
        he -= (a[i].r - a[i].l) * a[i].b;
        if (we >= he)
            return 1;
        we += x * a[i].r;
        we -= more * a[i].l;
        he += (a[i].r - a[i].l) * a[i].b;
    }
    return 0;
}

