	scanf("%d%lld", &n, &X);
	for (int i = 1; i <= n; ++i) {
		scanf("%lld%lld%lld", b + i, l + i, u + i);
		all -= b[i] * l[i];
		val[i] = (X - b[i]) * u[i] + b[i] * l[i];
	}

	for (int i = 1; i <= n; ++i) {
		id[i] = i;
	}
	std::sort(id + 1, id + n + 1, [&](const int &x, const int &y) { return val[x] > val[y]; });
	int64 sum = 0LL;
	for (int i = 1; i <= n; ++i) {
		sum += val[id[i]];
		if (sum + all >= 0) {
			pos = i - 1;
			sum -= val[id[i]];
			break;
		}
		in[id[i]] = true;
	}

	all = sum + all;
	int64 ans = (pos + 1) * X;
	for (int i = 1; i <= n; ++i) {
