bool check(int x) {
    int ans1 = 0, ans2 = 0;
    for (int i = 1; i <= n; i++) {
        if (x >= s[i].b) {
            if (x >= m) {
                ans1 += m * s[i].r;
                ans2 += s[i].b * s[i].r;
                x -= m;
            } else {
                ans1 += x * s[i].r;
                ans2 += s[i].b * s[i].r;
                x = 0;
            }
        } else {
            ans1 += x * s[i].l;
            ans2 += s[i].b * s[i].l;
            x = 0;
        }
    }
    if (ans1 >= ans2)
        return 1;
    return 0;
}

