inline ll read()
{
	ll x=0,w=1; char c=getchar();
	while(c<'0'||c>'9') {if(c=='-') w=-1; c=getchar();}
	while(c<='9'&&c>='0') {x=(x<<1)+(x<<3)+c-'0'; c=getchar();}
	return w==1?x:-x;
}

ll n,X;
struct node{ll b,l,r,val;}p[maxn];

inline bool cmp(node a,node b){return a.val>b.val;}

inline bool jud(ll x)
{
	ll nw=x,tmp=0,f=n+1;
	for(int i=1;i<=n;i++)
	{
		if(nw>=X)
		{
			tmp+=(X-p[i].b)*p[i].r;
			nw-=X;
		}
		else
		{
			f=i;
			break;
		}
	}
	if(p[f].b>=nw) tmp-=(p[f].b-nw)*p[f].l;
	else tmp+=(nw-p[f].b)*p[f].r;
	for(int i=f+1;i<=n;i++) tmp-=p[i].b*p[i].l;
	if(tmp>=0) return true; return false;
}

