ll cur;
ll res;

ll Get(int ind, int y)
{
    if (y <= b[ind]) return ll(l[ind]) * y;
    return ll(y - b[ind]) * u[ind] + ll(l[ind]) * b[ind];
}

int main()
{
    scanf("%d %d", &n, &x);
    for (int i = 0; i < n; i++) {
        scanf("%d %d %d", &b[i], &l[i], &u[i]);
        cur -= ll(b[i]) * l[i];
        seq[i] = lli(ll(b[i]) * l[i] + ll(x - b[i]) * u[i], i);
    }
    sort(seq, seq + n);
    for (int i = n - 1; i >= 0; i--)
        if (cur + seq[i].first >= 0) {
            int ans = x;
            for (int j = i; j >= 0; j--)
                if (cur + seq[j].first >= 0) {
                    int lef = 0, rig = x;
                    while (lef <= rig) {
                        int mid = lef + rig >> 1;
                        if (cur + Get(seq[j].second, mid) >= 0)
                            rig = mid - 1;
                        else lef = mid + 1;
                    }
                    ans = min(ans, rig + 1);
                }
            res += ans;
            break;
        } else { cur += seq[i].first; res += x; }
    cout << res << endl;
