void solve(long long N, long long X, std::vector<long long> b, std::vector<long long> l, std::vector<long long> u){
  ll lf=-1,rt=accumulate(b.begin(),b.end(),0);
  vector<int> m100(b.size());
  iota(m100.begin(),m100.end(),0);
  sort(m100.begin(),m100.end(),[&](int x,int y){
    return (l[x]*b[x]+u[x]*(X-b[x]))>(l[y]*b[y]+u[y]*(X-b[y]));
  });
  vector<pll> p;
  REP(N){
    p.push_back(pll(l[i]*b[i]+u[i]*(X-b[i]),i));
  }
  sort(p.begin(),p.end(),greater<pll>());
  vector<ll> sump;
  sump.push_back(0);
  REP(N){
    sump.push_back(sump.back()+p[i].first);
  }
  dump(p);
  dump(sump);
  ll bsum=0;
  REP(N){
    bsum+=b[i]*l[i];
  }
  while(lf+1<rt){
    ll mid=(lf+rt)/2;
    ll ans=0;
    REP(N){
      ll sum=0;
      if(i<mid/X){
        sum=sump[mid/X+1]-p[i].first;
      }else{
        sum=sump[mid/X];
      }
      ll idx=p[i].second;
      if(mid%X<b[idx]){
        sum+=(mid%X)*l[idx];
      }else{
