bool spfa(ll s,ll t)
{
    queue<ll>q;
    for(ll i=0;i<=2*n+10;i++){
        dis[i]=inf;
        vis[i]=0;
        pre[i]=-1;
    }
    dis[s]=0;
    vis[s]=true;
    q.push(s);
    while(!q.empty())
    {
        ll u=q.front();
        q.pop();
        vis[u]=false;
        for(ll i=head[u]; i; i=e[i].next)
        {
            ll v= e[i].to;
            if( e[i].cap>e[i].flow&&dis[v]>dis[u]+e[i].cost)
            {
                dis[v]=dis[u]+e[i].cost;
                pre[v]=i;
                if(!vis[v])
                {
                    vis[v]=true;
                    q.push(v);
                }
            }
        }
    }
    if(pre[t]==-1)
        return false;
    else return true;
}
ll cost=0;
ll mcmf(ll s,ll t)
{
    ll flow=0;
    cost=0;
    while(spfa(s,t))
    {
        ll minn=INF;
        for(ll i=pre[t]; i!=-1; i=pre[e[i^1].to])
        {
            if(minn> e[i].cap- e[i].flow)
            {
                minn=e[i].cap- e[i].flow;
            }
        }
        for(ll i=pre[t]; i!=-1; i=pre[e[i^1].to])
        {
            e[i].flow+=minn;
            e[i^1].flow-=minn;
            cost+=e[i].cost*minn;
        }
        flow+=minn;
    }
    return flow;
}
