    for (int i = 0; i < n; i++)
    {
        cin >> bs[i] >> ls[i] >> us[i];
        diff_ab -= bs[i] * ls[i];
    }

    vector<pair<int64_t, int64_t>> scores(n);
    for (int i = 0; i < n; i++)
    {
        scores[i].first = us[i] * x - bs[i] * (us[i] - ls[i]);
        scores[i].second = i;
    }
    sort(scores.begin(), scores.end(), greater<>());

    vector<bool> selected(n, false);
    int64_t ans = 0;

    for (auto s : scores)
    {
        int64_t diff, idx;
        tie(diff, idx) = s;

        if (0 <= diff_ab + diff)
        {
            break;
        }
        else
        {
            diff_ab += diff;
            selected[idx] = true;
        }
        ans += x;
    }

    auto match = [&](int index, int time, int64_t target) {
        if (time <= bs[index])
        {
            return 0 <= target + ls[index] * time;
        }
        else
        {
            return 0 <= target - bs[index] * (us[index] - ls[index]) + us[index] * time;
        }
    };

    auto binary_search = [&](int index, int target) {
        int64_t left = 0;
        int64_t right = x;
        if (match(index, left, target))
        {
            return left;
        }
        if (!match(index, right, target))
        {
            return right + 1;
        }
        for (int i = 0; i < 32; i++)
        {
            int middle = (left + right) / 2;
            (match(index, middle, target) ? right : left) = middle;
        }
        return right;
    };

    int64_t min_time = numeric_limits<int64_t>::max();
    for (int i = 0; i < n; i++)
    {
        if (!selected[i])
        {
            min_time = min(min_time, binary_search(i, diff_ab));
        }
    }
    assert(min_time <= x);
    ans += min_time;

    cout << ans << endl;
}

