typedef long long ll;

int b[MN], l[MN], r[MN];
ll v[MN];
int p[MN];
int n, x;

bool cmp(int a, int b) {return v[a] > v[b];}

ll solve(ll t)
{
	ll ans = -1e18, B = 0;
	ll cnt = t / x, lst = t % x;

	for(int I = 1; I <= n; I++) {int i = p[I]; B += 1ll * b[i] * l[i];}

	ll tot = 0;
	for(int I = 1; I <= cnt; I++) {int i = p[I]; tot += v[i];}

	if(lst == 0) return tot - B;

	tot += v[p[cnt + 1]];
	for(int I = 1; I <= n; I++)
	{
		int i = p[I];
		ll val = std::max(1ll * lst * l[i], 1ll * lst * r[i] - 1ll * (r[i] - l[i]) * b[i]);
		if(I > cnt) ans = std::max(ans, tot - v[p[cnt + 1]] + val);
		else ans = std::max(ans, tot - v[i] + val);
	}
	return ans - B;
}

