bool cmp(int x, int y) {
	return s[x] > s[y];
}
ll calc(int pos, ll t) {
	if (t <= b[pos]) return t * l[pos];
	else return b[pos] * l[pos] + (t - b[pos]) * r[pos];
}
ll check(ll t) {
	ll ans = 0, sum = 0;
	int lft = t % x;
	if (lft == 0) lft = x;
	int cnt = (t - lft) / x;
	assert(cnt < n);
	for (int i = 1; i <= cnt; i++)
		sum += s[p[i]];
	for (int i = cnt + 1; i <= n; i++)
		chkmax(ans, sum + calc(p[i], lft));
	sum += s[p[cnt + 1]];
	for (int i = 1; i <= cnt; i++)
		chkmax(ans, sum - s[p[i]] + calc(p[i], lft));
	return ans;
}
