				if(X + N >= Y + M) ans = true;

				N = x * r[A] - x * r[p] + B * r[p];
				M = b[p] * r[p] - b[p] * r[p] + b[A] * r[A] - b[A] * l[A];
				if(X + N >= Y + M) ans = true;
			}
		}
		return ans;
	};
	i64 ok = x * n, ng = -1;
	while(std::abs(ok - ng) > 1) {
		i64 mid = (ok + ng) >> 1;

		if(check(mid)) ok = mid;
		else ng = mid;
	}
