bool check(ll y) {
  ll q = y/x;
  ll r = y - q*x;

  ll s = accumulate(total,total+q,0LL,[](ll a, pli p2) { return a + p2.fst; });

  ll res = 0;
  forn(i,n) {
    int j = total[i].snd;

    if (i < q) {
      s -= total[i].fst;
      s += total[q].fst;
    }

    ll lc = min(r,b[j]);

    chmax(res, s + l[j]*lc + u[j]*(r-lc));

    if (i < q) {
      s += total[i].fst;
      s -= total[q].fst;
    }
  }

  return res + d >= 0;
}

