struct Test {
    i64 i;
    i64 b;
    i64 l;
    i64 u;
    Test(i64 ii, i64 bb, i64 ll, i64 uu) : i(ii), b(bb), l(ll), u(uu) {}
};

template<>
struct Formatter<Test> {
    static ostream& write_str(ostream& out, const Test& t) {
        return WRITE_STR(out, TUPLE(t.i,t.b,t.l,t.u));
    }
    static ostream& write_repr(ostream& out, const Test& t) {
        return WRITE_REPR(out, TUPLE(t.i,t.b,t.l,t.u));
    }
};

void solve() {
    i64 N = RD();
    i64 X = RD();

    vector<Test> ts;
    ts.reserve(N);
    REP(i, N) {
        i64 b = RD();
        i64 l = RD();
        i64 u = RD();
        ts.emplace_back(i, b, l, u);
    }
    DBG(ts);

    i64 bsum_orig = 0;
    for(const auto& t : ts) {
        bsum_orig += t.l * t.b;
    }
    DBG(bsum_orig);

    auto is_ok = [N,X,&ts,bsum_orig](i64 x) {
        auto comp1 = LT_ON([X](const Test& t) {
            //return (X-t.b) * t.u;
            return t.u*X - t.u*t.b + t.l*t.b;
        });
        auto comp2 = LT_ON([](const Test& t) {
            return t.l;
        });

        priority_queue<Test,vector<Test>,decltype(comp1)> que1(begin(ts), end(ts), comp1);
        priority_queue<Test,vector<Test>,decltype(comp2)> que2(begin(ts), end(ts), comp2);
        BoolArray used(N, false);
        i64 bsum = bsum_orig;

        i64 asum = 0;
        for(;;) {
            DBG(x, asum, bsum);
            if(asum >= bsum) return true;

            const auto t1 = que1.top();
            if(x >= X) {
                asum += t1.u * X;
                bsum += (t1.u-t1.l) * t1.b;
                x -= X;
                used[t1.i] = true;
                que1.pop();
            }
            else {
                if(asum + t1.u*x >= bsum + (t1.u-t1.l)*t1.b) return true;

                while(used[que2.top().i]) que2.pop();
                const auto t2 = que2.top();
                if(asum + t2.l*x >= bsum) return true;
                return false;
            }
        }
    };

    i64 ans = 1 + bisect_integer(0, 10'000'000'001, [is_ok](i64 x) { return !is_ok(x); });

#if 0
