        B += data.b*data.l;
    }

    auto solve = [&](long k) {
        auto q = k/X;
        auto sum = 0;
        for (int i = 0; i < q; i++) {
            sum += datas[i].value(X);
        }
        auto r = k%X;
        auto& data = datas[q];
        if (r <= data.b) {
            sum += data.l*r;
        } else {
            sum += data.l*data.b + data.u*(r-data.b);
        }
        return sum >= B;
    };

    long l = 1, r = N*X;
    long ans = r;
    while (l <= r) {
        auto c = (l+r)/2;
        if (solve(c)) {
            r = c-1;
            ans = c;
        } else {
            l = c+1;
        }
    }
    cout << ans << endl;

    return 0;
