        Update(1, 0, n - 1, i, false);
        lli got = Get(1, 0, n - 1, cur + seq[i].first);
        int lef = 0, rig = x;
        while (lef <= rig) {
            int mid = lef + rig >> 1;
            if (cur + got.first + Get(seq[i].second, mid) >= 0)
                rig = mid - 1;
            else lef = mid + 1;
        }
        res = min(res, ll(x) * got.second + ll(rig + 1));
        Update(1, 0, n - 1, i, true);
    }
    cout << res << endl;
    return 0;
}

