    long long d = k - b[i];
    long long w = (d > 0) ? d * rb[i] : d * lb[i];
    return w;
  };

  vector<long long> all(n), none(n);
  for (int i = 0; i < n; i++) {
    all[i] = f(x, i);
    none[i] = f(0, i);
  }

  vector<pair<long long, int>> c(n);
  for (int i = 0; i < n; i++) {
    c[i] = {all[i] - none[i], i};
  }
  sort(c.rbegin(), c.rend());
  vector<long long> presum(n + 1);
  for (int i = 0; i < n; i++) {
    presum[i + 1] = presum[i] + c[i].first;
  }
  long long sumnone = 0;
  for (int i = 0; i < n; i++) {
    sumnone += none[i];
  }

  auto sum = [&](int firstk, int skip) { // skip index in c
    long long wn = sumnone - none[c[skip].second];
    long long wa = presum[firstk];
    if (skip < firstk) {
      wa = presum[firstk + 1] - c[skip].first;
    }
    return wa + wn;
  };

  auto test = [&](long long m) {
    long long k = m / x, r = m % x;
    if (r == 0) {
      return sumnone + presum[k];
    }
