const int maxn = (int) 2e5 + 20;

#define LL long long

LL n, x;
LL B[maxn], L[maxn], R[maxn];
LL sum[maxn];
int rk[maxn];

LL tot;

int cmp(int x, int y)
{
    if(sum[x] != sum[y]) return sum[x] > sum[y];
    return B[x] < B[y];
}

bool vis[maxn];

int gao(LL score)
{
    LL tmp = tot;

    for(int i = 0; i < n; i++) vis[i] = 0;

    for(int i = 0; i < n && score >= x; i++)
    {
        int id = rk[i];

        score -= x;
        vis[id] = 1;
        tmp += sum[id];
    }

    LL mx = 0;
    for(int i = 0; i < n; i++)
    {
        if(vis[i]) continue;

        LL t = 0;
        if(score >= B[i]) t = (score - B[i]) * R[i] + B[i] * L[i];
        else t = score * L[i];

        mx = max(mx, t);
    }

    tmp += mx;
    return tmp >= 0;
}

void work()
{
    cin >>n >>x;

    tot = 0;
    for(int i = 0; i < n; i++)
    {
        cin >>B[i] >>L[i] >>R[i];

        tot -= B[i] * L[i];
        rk[i] = i;
        sum[i] = (x - B[i]) * R[i] + B[i] * L[i];
    }

    sort(rk, rk + n, cmp);

    LL l = 0, r = n * x, mid, ans = -1;

    while(l <= r)
    {
        mid = (l + r) / 2;

        if(gao(mid))
        {
            r = mid - 1;
            ans = mid;
        }
        else
        {
            l = mid + 1;
        }
    }

    cout <<ans <<endl;

}

