bool C(ll t){
	priority_queue<P>que;
	memset(used,0,sizeof(used));
	rep(i,n)que.push(P(b[i]*l[i]+(x-b[i])*u[i],i));
	ll S=sum;
	while(t>=x){
		if(que.empty())return true;
		auto p=que.top();que.pop();
