int main(){
	int N;
	ll X,b[100001],l[100001],u[100001];
	scan(N>>X);
	priority_queue<pair<pll,pll> > ULB;
	ll iniscore=0;
	rep(i,N){
		ll u,l,b;
		scan(b>>l>>u);
		ULB.push({{u*(X-b)+l*b,-l},{b,-u}});
		iniscore-=b*l;
	}
	ll Tmin=0,Tmax=X*N;
	while(Tmin+1<Tmax){
		ll Tmid=(Tmin+Tmax)/2;
		ll T=Tmid;
		priority_queue<pair<pll,pll> > ULBnow=ULB;
		ll loselmax=0;
		ll score=iniscore;
		int flag=0;
		//printf("T:%lld score:%lld\n",Tmid,score);
		while(!ULBnow.empty()){
			if(T>=X){
				pair<pll,pll> ulb=ULBnow.top();
				ULBnow.pop();
				ll point=ulb.first.first,l=-ulb.first.second,b=ulb.second.first,u=-ulb.second.second;
				score+=point;
				T-=X;
				//printf("u:%lld l:%lld b:%lld point:%lld score:%lld T:%lld\n",u,l,b,point,score,T);
			}
			else{
				ll pmax=0;
