					pair<pll,pll> ulb=ULBnow.top();
					ULBnow.pop();
					ll point=ulb.first.first,l=-ulb.first.second,b=ulb.second.first,u=-ulb.second.second;
					pmax=max(pmax,l*min(T,b)+max((T-b)*u,0LL));
				}
				score+=pmax;
				T=0;
				//printf("pmax:%lld score:%lld T:%lld\n",pmax,score,T);
			}
			if(score>=0){
				flag=1;
				break;
			}

		}
		//printf("T:%lld score:%lld win:%d\n",Tmid,score,flag);
		if(flag){
			Tmax=Tmid;
		}
		else{
			Tmin=Tmid;
		}
	}
	prin(Tmax);
	return 0;
}

