    S[i] = S[i-1] + blu[i-1][3];
    if(S[i] + D >= 0) over = min(over, i);
  }
  for(int i=0;i<N;i++){
    ll itr, st=-1;
    if(over >= i+1) {
      if(lower_bound(S.begin(), S.end(), -D)!=S.end()){
