          st += at/blu[i][1] + (at%blu[i][1]==0?0:1);
        }else{
          st += blu[i][0];
          at -= blu[i][1] * blu[i][0];
          st += at/blu[i][2] + (at%blu[i][2]==0?0:1);
        }
        //std::cout << st << '\n';
        ans = (ans>=st?st:ans);
      }
    }else{
      itr = lower_bound(S.begin(), S.end(), -D - blu[i][3]) - S.begin();
      st = itr * X;
      //std::cout << itr << '\n';
      if(S[itr] + D + blu[i][3] >= 0){
