const int mod=924844033,MAX=1503*1503;
const ll INF=1LL<<60;
struct data{
    ll b;
    ll l;
    ll r;
};

int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N,X;cin>>N>>X;

    vector<data> S(N);
    ll need=0;

    for(int i=0;i<N;i++){
        cin>>S[i].b>>S[i].l>>S[i].r;
        need+=S[i].b*S[i].l;
    }

    sort(all(S),[&](data a,data b){
        return a.r*(X-a.b)+a.b*a.l>b.r*(X-b.b)+b.b*b.l;
    });

    vector<ll> sum(N+1);
    for(int i=1;i<=N;i++){
        sum[i]=sum[i-1]+S[i-1].r*(X-S[i-1].b)+S[i-1].b*S[i-1].l;
    }

    ll ans=INF;
    for(int i=0;i<N;i++){
        ll diff=S[i].r*(X-S[i].b)+S[i].b*S[i].l;
        auto it=upper_bound(all(sum),need);
        ll re=it-sum.begin()-1;
        if(re>=i){
            if(S[i].b*S[i].l>=need-((*it)-diff)){
                ans=min(ans,re*X+(need-((*it)-diff)+S[i].l-1)/S[i].l);
                //cout<<re<<" "<<(need-((*it)-diff)+S[i].l-1)/S[i].l<<endl;
            }else{
                ans=min(ans,re*X+(need+S[i].b*(S[i].r-S[i].l)-((*it)-diff)+S[i].r-1)/S[i].r);
            }
        }else{
            it--;
            re=it-sum.begin()-1;
            diff=0;

            if(S[i].b*S[i].l>=need-((*it)-diff)){
                ans=min(ans,re*X+(need-((*it)-diff)+S[i].l-1)/S[i].l);
                //cout<<re<<" "<<(need-((*it)-diff)+S[i].l-1)/S[i].l<<endl;
            }else{
                ans=min(ans,re*X+(need+S[i].b*(S[i].r-S[i].l)-((*it)-diff)+S[i].r-1)/S[i].r);
            }
        }
    }

    cout<<ans<<endl;
}

