int main() {
    ll N, X;
    cin >> N >> X;
    V<TLL> blu(N);
    for (ll i = 0; i < N; i++) {
        ll b, l, u;
        cin >> b >> l >> u;
        blu[i] = make_tuple(b, l, u);
    }

    auto score = [&](TLL t) {
        ll b, l, u;
        tie(b, l, u) = t;
        return u * (X - b) + l * b;
    };

    sort(ALL(blu), [&](TLL a, TLL b) { return score(a) > score(b); });
    DEBUG(blu);

    ll ok = X * N, ng = -1;
    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        ll ost = 0, osa = 0;
        ll mod = (mid % X == 0 ? X : mid % X);
        ll cnt = (mid - mod) / X;
        for (ll i = 0; i < N; i++) {
            ll b, l, u;
            tie(b, l, u) = blu[i];
            if (i < cnt) {
                ost += X * u;
                osa += b * u;
            } else {
                osa += b * l;
            }
        }

        bool over = false;
        for (ll i = 0; i < N; i++) {
            ll st = ost;
            ll sa = osa;
            if (i < cnt) {
                ll b, l, u;
                tie(b, l, u) = blu[i];
                st -= X * u;
                sa -= b * u;
                tie(b, l, u) = blu[cnt];
                st += X * u;
                sa -= b * l;
                sa += b * u;
            } else {
                ll b, l;
                tie(b, l, ignore) = blu[i];
                sa -= b * l;
            }
            ll b, l, u;
            tie(b, l, u) = blu[i];
            ll v = (b < mod ? u : l);
            st += v * mod;
            sa += v * b;
            if (sa <= st) {
                over = true;
                // break;
            }
        }
        (over ? ok : ng) = mid;
    }

    cout << ok << endl;
    return 0;
}

