bool comp(T& l, T& r){
  return (X-l.b)*(l.u) > (X-r.b)*(r.u);
}

int main(void){
  cin >> N >> X;
  vector<T> v(N);
  ll A = 0,B = 0;
  int i;REP(i,N){
    cin >> v[i].b >> v[i].l >> v[i].u;
    B += v[i].b * v[i].l;
  }
  sort(v.begin(),v.end(),comp);
  ll ans = 0;
  int index = 0;
  REP(i,N){
    if(A + X*v[i].u >= B + v[i].b*(v[i].u - v[i].l)){
      index = i;
      A += X*v[i].u;
      B += v[i].b*(v[i].u - v[i].l);
      break;
    }
    A += X*v[i].u;
    B += v[i].b*(v[i].u - v[i].l);
    ans += X;
  }

  ll minimum = X;
  REP(i,N){
    ll remain = B-A;
    if(i<=index){
      remain += X*v[i].u;
      remain -= v[i].b*(v[i].u - v[i].l);
    }else{
      remain += X*v[index].u;
      remain -= v[index].b*(v[index].u - v[index].l);
    }
    ll s,e,c;
    if(v[i].b*v[i].l < remain){
      s = v[i].b;
