const int maxn = (int) 2e5 + 20;

#define LL long long

LL n, x;
LL B[maxn], L[maxn], R[maxn];
LL sum[maxn];
LL tsum[maxn];
int rk[maxn];


bool vis[maxn];


int gao(LL score)
{
    LL tot = 0;
    LL les = score % x;
    for(int i = 0; i < n; i++)
    {
        rk[i] = i;
        vis[i] = 0;
        tot -= B[i] * L[i];

        sum[i] = (x - B[i]) * R[i] + B[i] * L[i];

        if(les >= B[i]) tsum[i] = (les - B[i]) * R[i] + B[i] * L[i];
        else tsum[i] = les * L[i];
    }

    sort(rk, rk + n, [](int x, int y){
         if(sum[x] == sum[y]) return tsum[x] < tsum[y];
         return sum[x] > sum[y];
         });

    int k = score / x;
    LL pre = 0;
    for(int i = 0; i < k; i++) pre += sum[rk[i]];
    LL k1 = k < n ? sum[rk[k]] : 0;

    LL mx = 0;
    for(int i = 0; i < n; i++)
    {
        if(i < k) mx = max(mx, pre + k1 - sum[rk[i]] + tsum[rk[i]]);
        else mx = max(mx, pre + tsum[rk[i]]);
    }

    return tot + mx >= 0;
}

