            ll r=X*l[i];
            pair<ll,ll> ret=seg.query(1,1,sz,need-r);
            ll more=min(X,(ret.S+r-need)/l[i]);
            ans=min(ans,X-more+1LL*ret.F*X);
        }
        ll cost=b[i]*(u[i]-l[i]);
        ll r=X*u[i];
        pair<ll,ll> ret=seg.query(1,1,sz,need+cost-r);
        ll more=min(X,(ret.S+r-need-cost)/u[i]);
        ans=min(ans,X-more+1LL*ret.F*X);
        seg.update(1,1,sz,id,1);
    }
    printf("%lld\n",ans);
    return 0;
}

