}

ll cul2(ll i,ll t){
    if(t<=A[i].F){return t*A[i].S.F;}
    return t*A[i].S.S-A[i].F*(A[i].S.S-A[i].S.F);
}

bool can(ll z){
    //cout<<"!"<<z<<endl;
    priority_queue<pll> Q;
    vector<bool> used(n,false);
