using namespace std;

typedef long long ll;

ll N, X;
vector<ll> b, l, u;
vector<tuple<ll, ll, ll, ll>> v;

bool C(ll Y){
    ll sm = 0;
    ll M = Y / X;
    ll R = Y % X;
    for(int i=0; i<N; i++){
        ll a2, b2, l2, u2;
        tie(a2, b2, l2, u2) = v[i];
        if(i < N-M) sm += l2*(-b2);
        else sm += u2*(X-b2);
    }
    if(R == 0)
        return sm >= 0;

    for(int i=0; i<N; i++){
        ll a2, b2, l2, u2;
        tie(a2, b2, l2, u2) = v[i];
        ll sm2 = sm;

        if(i < N-M){
            sm2 -= l2*(-b2);
            if(R >= b2) sm2 += u2*(R-b2);
            else sm2 += l2*(R-b2);
            if(sm2 >= 0) return true;
        }
        if(i == N-M-1){
            sm += u2*(X-b2);
        }
        if(i >= N-M){
            sm2 -= u2*(X-b2);
            if(R >= b2) sm2 += u2*(R-b2);
            else sm2 += l2*(R-b2);
            if(sm2 >= 0) return true;
        }
    }
    return false;
}

