    ll whole = spent / cap;
    ll sum = 0;
    for(int j = 1; j <= n; j++) {
        int i = p[j];
        if (j <= whole) sum += ra[i][1] * (cap - b[i]);
        else sum -= ra[i][0] * b[i];
    }
    ll rem = spent % cap;
    if (rem == 0) return sum >= 0;

    for(int j = 1; j <= n; j++) {
        ll nSum = sum;
        int i = p[j];
        if (j <= whole) {
            int sub = p[whole + 1];
            nSum += -ra[i][1] * (cap - b[i]) 
                + ra[sub][1] * (cap - b[sub]) + ra[sub][0] * b[sub];
        } else nSum += ra[i][0] * b[i];
        nSum += max(ra[i][0] * (rem - b[i]), ra[i][1] * (rem - b[i]));
        if (nSum >= 0) return 1;
    }
    return 0;
}
