using namespace std;

struct Test {
	int64_t b;
	int64_t l;
	int64_t u;
	int64_t pmin;
	int64_t gmax;
	int i;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int64_t n, x; cin >> n >> x;

	int64_t penalty = 0;
	vector<Test> tests(n);
	{
		int i = 0;
		for (auto& test : tests) {
			cin >> test.b >> test.l >> test.u;
			test.pmin = test.b * test.l;
			test.gmax = (x - test.b) * test.u + test.pmin;
			test.i = i;

			penalty += test.pmin;
			i++;
		}
	}

	sort(tests.begin(), tests.end(), [](const Test& lhs, const Test& rhs) {
		return lhs.gmax > rhs.gmax;
	});

	int64_t min_s = INT64_MAX;
	for (auto rem : tests) {
		int64_t cur_remp = penalty - rem.gmax;

		int64_t s = 0;
		{
			auto it = tests.begin();
			while (it != tests.end() &&  0 <= cur_remp) {
				if (it->i == rem.i) {
					it++;
					continue;
				}

				cur_remp -= it->gmax;
				s += x;

				it++;
			}
		}

		cur_remp += rem.gmax;

		if (cur_remp < 0) continue;

		if (cur_remp < rem.pmin) {
			s += (cur_remp + rem.l - 1) / rem.l;
		}
		else {
			s += rem.b + (cur_remp - rem.pmin + rem.u - 1) / rem.u;
		}

		min_s = min(min_s, s);
	}


	cout << min_s << endl;


	return 0;
}

