const ll N = (int)1e5 + 9;
ll n;
ll X;

ll b[N], l[N], r[N];
bool ok[N];

bool is(ll T){
    ll k = T/(ll)X;
    ll sum = 0;
    for(ll i = 0 ; i < n ; i ++ )
        ok[i] = false;
    vector<pii> vls;
    for(ll i = 0 ; i < n; i ++ ){
        vls.push_back(mp((X-b[i]) * r[i], i));
    }
    sort(vls.begin(), vls.end());
    ll rem = T % (ll)X;
    reverse(vls.begin(), vls.end());
    for(ll i = 0 ; i < k ; i ++ ){
        sum += vls[i].fi;
        ok[vls[i].se] = true;
    }
    ll ddd = 0;
    for(ll i = 0 ; i < n ; i ++ ){
        if(ok[i])
            continue;
        ddd += -b[i] * l[i];
    }
    ll mx = -(ll)1e18;
    ll cur;
    for(ll i = 0 ; i < n ; i ++ ){
        if(ok[i])
            continue;
        cur = b[i] * l[i];
        if(rem != b[i]){
            if(rem < b[i]){
                cur += (rem - b[i]) * l[i];
            }
            else{
                cur += (rem - b[i]) * r[i];
            }
        }
        mx = max(mx, cur);
    }
    if(mx != -(ll)1e18)ddd += mx;
    sum += ddd;
    return sum >= 0;
}

