			Best.pop_back();
			ans += X;
		}
		LL tmp = X;
		rep(i, Best.size()) {
			LL pt = Best.back().first;
			UL p = Best.back().second;
			if (leaved > pt) continue;
			LL t = 0;
			LL b, l, u;
			b = Test[p].first;
			l = Test[p].second.first;
			u = Test[p].second.second;
			if (leaved == 0) {}
			else if (b * l >= leaved) {
				t = (leaved + l - 1) / l;
			}
			else {
				LL nleaved = leaved - b * l;
				t += b;
				t += (nleaved + u - 1) / u;
			}
			tmp = min(tmp, t);
		}
		ans += tmp;
		cout << ans << endl;
	}

	Problem();
};
