    sort(e.begin(), e.end());
    for (int i = n - 1; i >= 0; i--) {
        loss[i] = loss[i + 1] + e[i].l * e[i].b;
    }

    if (loss[0] == 0) {
        cout << 0 << "\n";
        return 0;
    }
    for (int i = 0; i < n; i++) {
        prof[i] = e[i].fpr();
        if (i) {
            prof[i] += prof[i - 1];
        }
    }

    int pos = -1;
    for (int i = 0; i < n; i++) {
        if (prof[i] >= loss[0]) {
            pos = i;
            break;
        }
    }

    assert(pos != -1);
    ll ans = 1e18;
    for (int i = 0; i < n; i++) {
        for (int j = pos - 2; j <= pos + 2; j++) {
            if (j >= n) {
                continue;
            }
            if (j >= i) {
                continue;
            }
            if (j < -1) {
                continue;
            }
