                ll cprof = sprof;
                ll delta = mg - e[i].b;
                ll cf = (delta > 0) ? e[i].u : e[i].l;
                if (cprof + cf * delta >= loss[0]) {
                    rg = mg;
                } else {
                    lg = mg;
                }
            }
            if (rg != X + 1) {
                ans = min(ans, cost + rg);
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

