    vector< pair<int, int> > vec;
    for (int i = 0; i < n; ++i) vec.pb( { 1LL * (r[i] - l[i]) * b[i] - 1LL * x * r[i], i } );
    sort(vec.begin(), vec.end() );
    int lst = lim / x; lim %= x;

    if (lst < n) {
        int sum = 0, minn = inf;
        for (int i = 0; i <= lst; ++i) sum += vec[i].fi;
        for (int i = 0; i < n; ++i) {
            int tmp;
            if (lim >= b[ vec[i].se ]) tmp = (r[ vec[i].se ] - l[ vec[i].se ]) * b[ vec[i].se ] - lim * r[ vec[i].se ];
            else tmp = -lim * l[ vec[i].se ];
            if (i <= lst) minn = min(minn, sum - vec[i].fi + tmp);
