using namespace std;
long long bscore[100001];
long long lbound[100001];
long long rbound[100001];
pair <long long, long long> totalearn[100001];

long long rem(int i, int am) {
	if (am <= bscore[i])
		return lbound[i] * am;
	else return lbound[i] * bscore[i] + (am - bscore[i]) * rbound[i];
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);
	int n;
	long long x;
	long long bwork = 0;
	cin >> n >> x;
	for (int i = 0; i < n; i++) {
		cin >> bscore[i] >> lbound[i] >> rbound[i];
		bwork += (bscore[i] * lbound[i]);
		totalearn[i] = make_pair(bscore[i] * lbound[i] + (x - bscore[i]) * rbound[i], i);
	}

	sort(totalearn, totalearn + n);
	for (int i = n - 2; i >= 0; i--) {
		totalearn[i].first += totalearn[i + 1].first;
		//cout << totalearn[i].first << ' ';
	}// cout << '\n';
	//cout << "TOTAL WORK: " << bwork << '\n';
	long long bestans = n * x;
	for (int i = 0; i < n; i++) {
		long long curbest = n * x; 
		int s = 0;
		int e = n - 1;
		while (s <= e) {
			int m = (s + e) / 2;
			long long totsum = totalearn[n - m].first;
			if (n - m <= i && m != n) {
				totsum = totalearn[n - m - 1].first - (totalearn[i].first - totalearn[i + 1].first);
			}
			if (totsum + totalearn[i].first - totalearn[i + 1].first >= bwork) {
				e = m - 1;
				long long lx = 0;
				long long rx = x;
				long long bestselect = x;
				while (lx <= rx) {
					int mx = (lx + rx) >> 1;
					if (rem(totalearn[i].second, mx) >= bwork - totsum) {
						rx = mx - 1;
						bestselect = mx;
					}
					else lx = mx + 1;
				}
				curbest = min(curbest, bestselect + m * x);
			}
			else s = m + 1;
			//cout << m << ' ' << totsum << '\n';
		}
		bestans = min(bestans, curbest);
	}
	cout << bestans << '\n';
}

