//vector<int> dx = {1,-1,0,0};
ll N, X;
vector<ll> B(100010), l(100010), u(100010);
ll Asum;

vector<pair<ll, int>> uX(100010, {-INFL, -1});

bool win(ll sum){
  ll Tsum = 0;
  int cnt = 0;
  while(sum >= X && cnt < N){
    Tsum += uX[cnt].first;
    cnt++;
    sum -= X;
    if(Tsum >= Asum){
      return 1;
    }
  }
  vector<int> xs;
  for(int i = cnt; i < N; i++){
    xs.push_back(uX[i].second);
  }
  ll T = Tsum;
  for(int i = 0; i < xs.size(); i++){
    int I = xs[i];
    Tsum = T;
    Tsum += sum * l[I];
    if(Tsum >= Asum) return 1;
    Tsum += (sum-B[I]) * (u[I] - l[I]);
    if(Tsum >= Asum) return 1;
  }
  return 0;
}

int main(void){
  cin >> N >> X;
  for(int i = 0; i < N; i++){
    cin >> B[i] >> l[i] >> u[i];
    Asum += B[i] * l[i];
    uX[i].first = X * u[i] - B[i] * (u[i] - l[i]);
    uX[i].second = i;

  }
  sort(uX.begin(), uX.end());
  reverse(uX.begin(), uX.end());
  ll ng = -1, ok = INFL;
  ll mid;
  while(ok - ng > 1){
    mid = (ng + ok) / 2;
    if(win(mid)){
      ok = mid;
    }else{
      ng = mid;
    }

  }
  cout << ok << endl;

}

