using namespace std;
typedef long long ll;

struct hoge {
    ll h0; ll num, l0;
};

bool comp(hoge &a, hoge &b){
    if(a.h0!=b.h0) return a.h0 > b.h0;
    if(a.l0!=b.l0) return a.l0 < b.l0;
    return a.num < b.num;
}

ll N, X;
ll b[100100], l[100100], u[100100];
hoge h[100100]; 
ll st;

bool ok(ll s){
    ll n=0LL;
    ll now=st;
    while(s >= X){
        now += h[n].h0;
        s -=X;
        n++;
    }
    //s増えた時のmaxを求める
    ll smax=0;
    for(ll i=n; i<N; i++){
        ll j=h[i].num;
        if(b[j] <s ){
            smax =max(smax,b[j]*l[j]+ (s-b[j])*u[j] );
        }
        else{
            smax =max(smax, l[j]*s);
        }
    }
    if(now+smax >=0) return true;
    return false;
}

int main(){
    cin  >> N >> X;
    for(ll i=0LL; i<N; i++){
        cin >> b[i] >> l[i] >> u[i];
        h[i].h0=  b[i]*l[i]+(X-b[i])*u[i];
        h[i].num=i;
        h[i].l0=l[i];
        st -= b[i]*l[i];
    }
    sort(h,h+N,comp);

//    cout << st << endl;
//    for(int i=0; i<N; i++){
//        cout << h[i].h0 << endl;
//    }

    ll lb=-1, ub=(ll) N*X;
    while(ub-lb >1){
        ll mid=(lb+ub)/2;
        if(ok(mid)){
            ub=mid;
        }
        else{
            lb=mid;
        }
    }
    cout << ub << endl;
}

