const int N = 1e5 + 7;

struct TFunction{
	int b, l, u;

	TFunction() {}
	TFunction(int b, int l, int u): b(b), l(l), u(u) {}

	long long get(int x){
		if (x <= b)
			return 1LL * l * (x - b);
		return 1LL * u * (x - b);
	}
}f[N];

int n, x;
long long tot;
long long pre[N], suf[N];

bool check(long long k){
	long long div = k / x;
	long long rem = k - div * x;

	if (rem == 0){
		rem = x;
		div--;
	}

	long long mx = -(long long)1e18;

	for (int i = 1; i <= n; i++)
		if (i <= div)
			mx = max(mx, pre[div + 1] + suf[div + 2] - f[i].get(x) + f[i].get(rem));
		else
			mx = max(mx, pre[div] + suf[div + 1] - f[i].get(0) + f[i].get(rem));
	// db(mx)
	return mx >= 0;
}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);

	cin >> n >> x;
	for (int i = 1; i <= n; i++){
		cin >> f[i].b >> f[i].l >> f[i].u;
	}

	sort(f + 1, f + n + 1, [](TFunction &a, TFunction &b){
		return (a.b*a.l+(x-a.b)*(a.u))>(b.b*b.l+(x-b.b)*(b.u));
	});

	// for (int i = 1; i <= n; i++)
	// 	db(f[i].b _ f[i].l)

	for (int i = 1; i <= n; i++)
		pre[i] = pre[i - 1] + f[i].get(x);

	for (int i = n; i >= 1; i--)
		suf[i] = suf[i + 1] + f[i].get(0);

	// db(check(19))

	long long l = 0;
	long long r = 1LL * n * x;

	while (l <= r){
		long long mid = l + r >> 1;
		if (check(mid))
			r = mid - 1;
		else
			l = mid + 1;
	}

	cout << l;
}

