int main()
{
	n=ty(),lim=ty();

	lint riva=0;
	for(int i=1;i<=n;i++)
	{
		lint b=ty(),l=ty(),r=ty();
		riva+=b*l,p[i]=cxk(l,r,b,b*l+r*(lim-b));
	}

	sort(p+1,p+n+1);

	lint taka=0,ans=0;int loc=0;
	for(int i=1;i<=n;i++)
	{
		if(taka+p[i].val>=riva){loc=i-1;break;}
		taka+=p[i].val,ans+=lim;
	}

	lint sans=ans+lim;
	for(int i=1;i<=n;i++)
	{
		lint sval=taka;
		if(i<=loc)sval-=p[i].val,sval+=p[loc+1].val;
		lint l=0,r=lim,ret=lim+1;
		while(r>=l)
