using ll = long long;

bool C(ll t, vector<int>b, vector<int>l, vector<int>u, int N, int X){
    // 重要度はl_iかu_iの2択
    // とりあえず満点取った時の効果が大きい順にとっていって端数を調整
    // 満点を取るのに必要な時間は一定
    vector<pair<ll,ll>> kouka(N);
    for (ll i = 0; i < N; ++i) {
        ll temp = u[i] * (X - b[i]) + b[i] * l[i];
        kouka[i] = make_pair(temp, i);
    }
    vector<int> flag(N,0); // 満点を取ったら1にする
    ll score = 0;
    for (int i = 0; i < N; ++i) {
        score = score - l[i] * b[i];
    }
    sort(kouka.begin(), kouka.end(), greater<pair<ll,ll>>());
    for (int i = 0; i < N; ++i) {
        if(score + kouka[i].first <= 0){
            t = t-X;
            score = score + kouka[i].first;
            flag[kouka[i].second] = 1;
        }else{
            break;
        }
    }
    if(t < 0) return false;
    if(t >= X) return true;
    if(score == 0) return true;
    for (int i = 0; i < N; ++i) {
        if(flag[i] == 0){
            ll temp2 = 0;
            if(t > b[i]){
                temp2 = u[i] * (t - b[i]) + b[i] * l[i];
            }else{
                temp2 = t * l[i];
            }
            if(temp2 + score >= 0){
                return true;
            }
        }
    }
    return false;
}

int main() {
    int N, X;
    cin >> N >> X;
    vector<int>b(N);
