#define DEBUG(x) cerr << #x << ": " << (x) << endl;

const int N = 1e5 + 5;
int n, x, B[N], L[N], U[N];
LL Gain[N], margin = 0;
map<LL, vector<int>> M;

bool check(LL budget) {
  vector<int> I(n + 1);
  vector<LL> S(n + 1);
  iota(I.begin(), I.end(), 0);
  sort(I.begin() + 1, I.end(), [&](int i, int j) { return Gain[i] > Gain[j]; });
  FI(i, 1, n) S[i] = S[i - 1] + Gain[I[i]];
  int r = budget % x, q = budget / x;
  if (r == 0) {
    return S[q] >= margin;
  }
  LL ans = 0;
  FI(i, 1, n) {
    if (i - 1 > q) break;
    LL gain;
    if (r <= B[I[i]]) {
      gain = 1LL * L[I[i]] * r;
    } else {
      gain = 1LL * U[I[i]] * (r - B[I[i]]) + 1LL * L[I[i]] * B[I[i]];
    }
    gain += S[i - 1];
    gain += S[q + 1] - S[i];
    ans = max(ans, gain);
  }
  return ans >= margin;
}

int main() {
  cin >> n >> x;
  FI(i, 1, n) scanf("%d%d%d", &B[i], &L[i], &U[i]);
  FI(i, 1, n) margin += 1LL * L[i] * B[i];
  FI(i, 1, n) Gain[i] = 1LL * U[i] * (x - B[i]) + 1LL * L[i] * B[i];
  FI(i, 1, n) M[Gain[i]].push_back(i);
  LL l = 0, r = 1LL * x * n;
  while (l + 1 < r) {
    LL m = (l + r + 1) / 2;
    if (check(m))
      r = m;
    else
      l = m;
  }
  cout << r << endl;
}

