    std::vector<ll> id(n);
    ll sum = 0;
    for (int i = 0; i < n; i++) {
        std::cin >> b[i]>>l[i]>>u[i];
        id[i] = i;
        sum += b[i]*l[i];
    }
    sort(id.begin(),id.end(),comp);



    ll now = -1;

    vector<ll> d(n);
    vector<ll> d_sum(n);
    // std::cout << sum<<" sum" << std::endl;
    for (int i = 0; i < n; i++) {
        d[i] = (x-b[id[i]])*u[id[i]]+b[id[i]]*l[id[i]];

        if(i>0){
            d_sum[i] = d_sum[i-1]+d[i];
        }else{
            d_sum[i] = d[i];
        }
        // std::cout << i<<" "<<d_sum[i] << std::endl;
        if(d_sum[i] >= sum && now == -1){
            now = i;
        }
