int64_t X;

struct TItem {
    int64_t b;
    int64_t l;
    int64_t r;
    int64_t sum;
    TItem(int _b, int _l, int _r) : b(_b), l(_l), r(_r), sum(r * (X - b) + b * l)
    {}
};


inline int64_t getsum(const vector<int64_t>& sums, const int my, const int idx) {
    if (idx < 0)
        return 0;
    auto res = sums[idx + 1];
    if (my <= idx)
        res -= (sums[my + 1] - sums[my]);
    return res;
}

int main()
{
//    freopen("in.txt","r", stdin);
//    freopen("out.txt", "w", stdout);
//    cin.tie(0);
//    cout << fixed << setprecision(20);
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n >> X;

    vector<TItem> a;
    int64_t need = 0;
    for (int i = 0; i < n; ++i) {
        int b,l,u;
        cin >> b >> l >> u;
        a.emplace_back(b, l, u);
        need += b * l;
    }

    sort(begin(a), end(a), [](const TItem& lhs, const TItem& rhs) {return lhs.sum > rhs.sum;});

    vector<int64_t> sums(n + 1, 0);
    for (int i = 1; i <= n; ++i)
        sums[i] = sums[i - 1] + a[i - 1].sum;

    int64_t ans = X * n;

    for (int i = 0; i < n; ++i) {
        int64_t curval = a[i].sum;

        int r = n;
        int l = -2;
        while (r - l > 1) {
            int mid = (l + r) >> 1;
            if (getsum(sums, i, mid) + curval >= need)
                r = mid;
            else
                l = mid;
        }
        for(int t = max(-1, r - 10); t < min(n, r + 11); ++t) {
            int64_t curneed = need - getsum(sums, i, t);
            if (curneed < 0)
                curneed = 0;
            int64_t curadd = 0;
            if (a[i].b * a[i].l >= curneed) {
                curadd = (curneed + a[i].l - 1) / a[i].l;
            } else {
                curneed -= a[i].b * a[i].l;
                curadd = a[i].b;
                auto coef = (curneed + a[i].r - 1) / a[i].r;
                curadd += coef;
                if (coef > X - a[i].b)
                    continue;
            }
            ans = min(ans, curadd + (t + 1) * X);
        }
    }
    cout << ans << endl;
}

