  }
  while(lf+1<rt){
    ll mid=(lf+rt)/2;
    ll ans=0;
    if(mid%X)REP(N){
      ll sum=0;

      if(i<mid/X){
        sum=sump[mid/X+1]-p[i].first;
      }else{
        sum=sump[mid/X];
      }
      ll idx=p[i].second;
      if(mid%X<b[idx]){
        sum+=(mid%X)*l[idx];
      }else{
        sum+=(mid%X-b[idx])*u[idx]+b[idx]*l[idx];
      }
      ans=max(ans,sum);
