const int maxn = 1e5 + 5;
int b[maxn];
int l[maxn], u[maxn];
ll sum[maxn];
ll pre[maxn];

bool cmp(int i, int j){
    return sum[i] < sum[j];
}

int id[maxn];

int main(){
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
    cin >> n >> X;
    ll base = 0;
    for(int i = 1;i <= n;i++){
        cin >> b[i] >> l[i] >> u[i];
        base += -1LL * b[i] * l[i];
        sum[i] = 1LL * b[i] * l[i] + 1LL * u[i] * (X - b[i]); 
        id[i] = i;
    }
    sort(id + 1, id + 1 + n, cmp);
    pre[0] = 0;
    for(int i = 1;i <= n;i++){
        pre[i] = pre[i - 1] + sum[id[i]];
    }
    ll L = 0, R = 1LL * X * n;
    while(L < R){
        ll mid = (L + R) / 2;
        ll x = mid / X;
        ll y = mid - 1LL * X * x;
        bool flag = false;
        for(int i = 1;i <= n;i++){
            ll tmp = 0;
            int j = id[i];
            if(y <= b[j]){
                tmp = y * l[j];
            }else{
                tmp = 1LL * b[j] * l[j] + 1LL * (y - b[j]) * u[j];
            }
            if(i <= n - x){
                tmp += pre[n] - pre[n - x];
            }else{
                tmp += pre[n] - pre[n - x - 1] - sum[j];
            }
            if(tmp + base >= 0){
                flag = true;
            }
        }
        if(flag){
            R = mid;
        }else{
            L = mid + 1;
        }
    }
    cout << L << endl;
    return 0;
}

