			if(b <= p[i].b) ss=ss+sf[a+1]-p[i].f+b*p[i].l;
			else ss=ss+sf[a+1]-p[i].f+p[i].b*p[i].l+(b-p[i].b)*p[i].r;
		}
		else{
			if(b <= p[i].b) ss=ss+sf[a]+b*p[i].l;
			else ss=ss+sf[a]+p[i].b*p[i].l+(b-p[i].b)*p[i].r;
		}
		if(ss >= 0) return 1;
	}
	return 0;
}

