const int N = 100100;
int n;
ll a[N][3];
pli b[N];
bool used[N];
ll X;
ll S;

bool solve(ll H) {
	int k = H / X;
	H %= X;
	for (int i = 0; i < n; i++)
		used[i] = false;
	ll cur = S;
	for (int i = 0; i < k; i++) {
		used[b[i].second] = true;
		cur -= b[i].first;
	}
	if (cur <= 0) return true;
	if (H == 0) return false;
	for (int i = 0; i < n; i++) {
		ll nw = cur;
		if (used[i]) {
			nw += a[i][2] * (X - a[i][0]) + a[i][1] * a[i][0];
			nw -= b[k].first;
		}
		nw -= a[i][0] * a[i][1];
		if (H < a[i][0]) {
			nw -= (H - a[i][0]) * a[i][1];
		} else {
			nw -= (H - a[i][0]) * a[i][2];
		}
		if (nw <= 0) return true;
	}
	return false;
}

