    int A, b, l, u;

    tie( A, b, l, u ) = Q.top();

    A *= -1;
    //cout<<A<<' '<<b<<' '<<l<<' '<<u<<endl;
    int naS = aS + X * u;

    int nbS = bS - b * l + b * u;

    if( nbS <= naS ) break;

    aS = naS;
    bS = nbS;
    ans += X;

    Q.pop();

  }  
  //cout<<aS<<' '<<ans<<endl;
  if( !Q.empty() ){

    int minplus = X;

    while( !Q.empty() ){

      int A, b, l, u;

      tie( A, b, l, u ) = Q.top(); Q.pop();

      A *= -1;

      int naS = aS + X * u;

      int nbS = bS - b * l + b * u;

      int naS2 = aS + b * l;

      if( naS2 >= bS ){

	int L = 0, R = b + 1;

	while( L + 1 < R ){

	  int M = ( L + R ) / 2;

	  naS = aS + M * l;
	  nbS = bS;

	  if( naS < nbS ) L = M;
	  else R = M;

	}
	if( R == b + 1 ) R = b;
	minplus = min( minplus, R );

      }

      if( naS >= nbS ){

	int L = b + 1, R = X + 1;

	while( L + 1 < R ){

	  int M = ( L + R ) / 2;

	  naS = aS + M * u;
	  nbS = bS - b * l + b * u;

	  if( naS < nbS ) L = M;
	  else R = M;

	}
	if( R == X + 1 ) R = X;
	minplus = min( minplus, R );

      }

    }

    ans += minplus;

  }

  cout<<ans<<endl;

  return 0;
}

