LL N, X;
vector<LL> b, l, u, x, ord;
LL sumb;

bool check(LL k)
{
   LL q = k / X, p = k % X;

   LL sumx = 0;
   LL idx = 0;
   vector<bool> used(N, false);

   for (LL i = 0; i < q; ++i) {
      sumx += x[ord[i]];
      used[ord[i]] = true;
   }


   if (sumb <= sumx) {
      return true;
   }

   for (LL i = 0; i < N; ++i) {
      LL tmps = sumx;
      if (used[i]) {
         tmps -= x[i];
         tmps += x[ord[q]];
      }

      LL z = 0;
      if (p <= b[i]) {
         z = p * l[i];
      } else {
         z = b[i] * l[i] + (p - b[i]) * u[i];
      }

      if (sumb <= tmps + z) {
         return true;
      }
   }

   return false;
}


LL binary_search(LL MIN, LL MAX)
{
   LL l = MIN-1, r = MAX;
   while (r - l > 1) {
      LL m = (l + r) / 2;
      if (check(m)) {
         r = m;
      } else {
         l = m;
      }
   }
   return r;
}

