ll Asum = 0;

bool win(ll canUse){
	if(canUse >= X * N) return 1;
  int r = canUse % X, p = canUse / X;
  for(int i = 0; i < N; i++){
    ll score = 0;
		score += max(r * get<3>(s[i]) - get<1>(s[i]) * (get<3>(s[i]) - get<2>(s[i])), r * get<2>(s[i]));
		if(score >= Asum && p == 0) return 1;
		if(i+1 <= p){
			score += S[p+1] - (X * get<3>(s[i]) - get<1>(s[i]) * (get<3>(s[i]) - get<2>(s[i])));
		}else{
			score += S[p];
		}
		if(score >= Asum) return 1;
  }
  return 0;
}

