const int MAXN = 100111;

int64 N, X;
int64 B[MAXN], L[MAXN], R[MAXN];

int64 other;

vector<pair<int64, int64>> cand;

int64 Gain(int64 i, int64 t) {
    if (t <= B[i]) {
        return (int64)t * L[i];
    } else {
        return (int64)B[i] * L[i] + (int64)(t - B[i]) * R[i];
    }
}

bool Go(int64 T) {
    vector<bool> used(N);

    int64 cur = other;

    if (cur >= 0)
        return true;

    for (int i = 0; i < N; i++) {
        if (T >= X) {
            T -= X;
            cur += cand[i].first;
            used[cand[i].second] = true;

            if (cur >= 0)
                return true;
        } else {
            break;
        }
    }

    int64 bst = 0;

    for (int i = 0; i < N; i++) {
        if (!used[i]) {
            bst = max(bst, Gain(i, T));
        }
    }

    return cur + bst >= 0;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> X;
    for (int i = 0; i < N; i++) {
        cin >> B[i] >> L[i] >> R[i];
        other -= (int64)B[i] * L[i]; 
    }

    int64 l = 0, r = (int64)N * X, m(0), sol(0);

    for (int i = 0; i < N; i++) {
        cand.emplace_back(Gain(i, X), i);
    }

    sort(cand.rbegin(), cand.rend());

    while (l <= r) {
        m = (l + r) >> 1;
        if (Go(m)) {
            sol = m;
            r = m - 1;
        } else {
            l = m + 1;
        }
    }

    cout << sol << "\n";

    return 0;
}

