	ll cur=0;
	int t=0;
	for(;t<n && cur+al[ind[t]]<=sum; ++t) cur+=al[ind[t]];
	out(ind,fst,snd,al,t,cur,sum,1);
	ll re=1ll*x*n;
	auto upd=[&](int i,ll rem){
						 if(fst[i].X*fst[i].Y>=rem){
							 MN(re,t*x+(rem+fst[i].Y-1)/fst[i].Y);
						 }else{
							 rem-=fst[i].X*fst[i].Y;
							 if(snd[i].X*snd[i].Y<rem) return;
							 MN(re,t*x+fst[i].X+(rem+snd[i].Y-1)/snd[i].Y);
						 }
					 };
	{
		reps(ii,t,n){
			ll rem=sum-cur;
			int i=ind[ii];
			upd(i,rem);
		}
	}
	int T=t;
	rrep(i,T){
		for(;t<n && cur+al[ind[t]]<=sum+al[ind[i]];++t) cur+=al[ind[t]];
		upd(ind[i],sum-cur+al[ind[i]]);
	}
