ll pref[maxN];
signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    //freopen("input.txt", "r", stdin);
    cin >> n >> x;
    for (int i = 1; i <= n; i++) {
        cin >> b[i] >> l[i] >> u[i];
    }
    ll S = 0;
    vector < pair < ll, int > > f;
    for (int i = 1; i <= n; i++) {
        S += l[i] * b[i];
        f.emplace_back(b[i] * (l[i] - u[i]) + x * u[i], i);
    }
    sort(f.begin(), f.end());
    reverse(f.begin(), f.end());
    pref[0] = 0;
    for (int i = 1; i <= n; i++) {
        pref[i] = pref[i - 1] + f[i - 1].first;
    }
    ll best = 1e18;
    for (int who = 0; who < n; who++) {
        ll total = pref[who];
        if (total >= S) {
            best = min(best, who * x);
            continue;
        }
        int le = who - 1;
        int r = n - 1;
        int ind = f[who].second;
        if (pref[r + 1] - pref[who + 1] + total + l[ind] * (b[ind]) < S) continue;
        while (r - le > 1) {
            int mid = (le + r) / 2;
            if (pref[mid + 1] - pref[who + 1] + total + l[ind] * b[ind] >= S) r = mid;
            else le = mid;
        }
        int where = r;
        ll diff = S - (pref[where + 1] - pref[who + 1] + total);
        if (diff + l[ind] * b[ind] < 0) {
            //cout << diff + l[ind] * b[ind] << " gggg "  << who << " here" << endl;
          //  assert(false);
        }
        //assert(diff >= 0);
        ll pp = ((diff + l[ind] - 1) / (l[ind]));
        if (diff < 0) {
            best = min(best, (where) * x);
            continue;
        }
        if (pp >= 0 && pp <= b[ind]) {
            best = min(best, (where) * x + pp);
        }
    }
    for (int who = 0; who < n; who++) {
        ll total = pref[who];
        if (total >= S) {
            best = min(best, who * x);
            continue;
        }
        int le = who - 1;
        int r = n - 1;
        int ind = f[who].second;
        if (pref[r + 1] - pref[who + 1] + total + f[who].first < S) continue;
        while (r - le > 1) {
            int mid = (le + r) / 2;
            if (pref[mid + 1] - pref[who + 1] + total + f[who].first >= S) r = mid;
            else le = mid;
        }
        int where = r;
        ll diff = S - (pref[where + 1] - pref[who + 1] + total) + (b[ind] * (u[ind] - l[ind]));
        ll pp = ((diff + u[ind] - 1) / (u[ind]));
        if (diff < 0) {
            best = min(best, (where) * x);
            continue;
        }
        if (pp >= b[ind] && pp <= x) {
            best = min(best, (where) * x + pp);
        }
    }
    cout << best;
    return 0;
}

