        sum = SUM[p+1] - vec[idx[i]];
      } else {
        sum = SUM[p];
      }
      sum += l[idx[i]] * min(b[idx[i]], q) + u[idx[i]] * max(0ll, q-b[idx[i]]);
      mx = max(mx, sum);
    }
    if(mx >= D) right = mid;
    else left = mid;
  }
  cout << right << endl;
}

