bool is_win(ll A) {
	const int q = (int)(A / X);
	const int r = A % X;

	for (int i = 0; i < N; i++)
	{
		ll ans = 0;

		ans += r > b[i] ? (ll)u[i] * (r - b[i]) : - (ll)l[i] * (b[i] - r);

		if (i < q) {
			ans += sumX[q + 1];
			ans += sum0[q + 1];
			ans -= (ll)u[i] * (X - b[i]);
		}
		else {
			ans += sumX[q];
			ans += sum0[q];
			ans -= - (ll)l[i] * b[i];
		}

		if (ans >= 0)
			return true;
	}

	return false;
}

