	for (int i = 1; i <= n; i++)
		scanf("%d%d%d", &A[i].b, &A[i].l, &A[i].r);
	sort(A + 1, A + n + 1, cmp);
	for (int i = 1; i <= n; i++)
		pre[i] = pre[i - 1] + calc(A[i]);
	ll lef = 0, righ = (ll)n * K - 1, ch = n * K;
	while (lef <= righ)
	{
		ll mid = (lef + righ) / 2;
		if (check(mid)) {ch = mid; righ = mid - 1;}
		else lef = mid + 1;
	}
	printf("%lld\n", ch);
	return 0;
}

