bool comp(T& l, T& r){
  return (X-l.b)*l.u > (X-r.b)*r.u;
}

int main(void){
  ;cin >> N >> X;
  vector<T> v(N);
  ll A = 0,B = 0;
  int i;REP(i,N){
    cin >> v[i].b >> v[i].l >> v[i].u;
    B += v[i].b * v[i].l;
  }
  sort(v.begin(),v.end(),comp);
  ll ans = 0;
  REP(i,N){
    if(A + X*v[i].u >= B + v[i].b*(v[i].u - v[i].l)){
      break;
    }
    A += X*v[i].u;
    B += v[i].b*(v[i].u - v[i].l);
    v[i].is_max = true;
    ans += X;
  }
  ll min = X;
  REP(i,N){
    if(v[i].is_max)continue;
    ll remain = B-A;
    ll s,e,c;
    if(v[i].b*v[i].l < remain){
      s = v[i].b;
      e = X;
      remain += v[i].b*(v[i].u - v[i].l);
      c = v[i].u;
    }else{
      s = 0;
      e = v[i].b;
      c = v[i].l;
    }
    while(e-s>=2){
      ll mid = (s+e)/2;
      if(mid*c < remain) s = mid;
      else e = mid;
    }
    if(e<min) min = e;
  }
  ans += min;
  cout << ans << endl;
  return 0;
}

