}

inline ll calc(ll x,ll y){
	if(x>=y)return sum[x];
	return sum[x]+val[rk[y]];
}

inline ll doit(ll k,ll rem){
	if(rem<0)return 0;
	if(rem<=l[k]*b[k])return (rem+l[k]-1)/l[k];
	return b[k]+(rem-b[k]*l[k]+r[k]-1)/r[k];
}

int main(){
