bool isOK(ll m) {
  ll D = 0;
  REP(i, n) {
    D -= ls[i] * bs[i];
  }
  ll r = m % X;
  if(r != 0) {
    REP(i1, n) { // is[i1]は中途半端な点取る
      int ii1 = is[i1];
      ll DD = D;
      if(i1 < m/X) {
        DD += cs[m/X+1] - (ls[ii1]*bs[ii1]+us[ii1]*(X-bs[ii1]));
      } else {
        DD += cs[m/X];
      }
      if(r <= bs[ii1]) {
        DD += ls[ii1]*r;
      } else {
        DD += ls[ii1]*bs[ii1] + us[ii1]*(r-bs[ii1]);
      }
      if(DD >= 0) {
        // cerr << "> " << m << " " << i1 << " " << D << " " << DD << endl;
        return true;
