using namespace std;

long long X;

class Data{
public:
    long long b;
    long long l;
    long long u;

    long long value()const{
        return X * u - b * (u - l);
    }

    long long cnt(long long rest){
        if(rest <= b * l){
            return (rest + l - 1) / l;
        }
        else{
            rest += (long long)b * (u - l);
            return (rest + l - 1) / l;
        }

        return 0;
    }
};

bool compare(const Data& lhs, const Data& rhs){
    return (lhs.value() > rhs.value());
}

int main(){

    int N;
    cin >> N >> X;

    vector<Data> data(N);
    long long b, l, u;
    long long rest = 0;
    for(int i = 0; i < N; i++){
        cin >> b >> l >> u;
        rest += b * l;
        Data temp;
        temp.b = b;
        temp.l = l;
        temp.u = u;
        data[i] = temp;
    }

    sort(data.begin(), data.end(), compare);

    long long time = 0;
    int index = 0;
    long long sameValueIndex = -1;
    long long sameValue = -1;
    while(rest > 0){
        Data temp = data[index];
        long long point = temp.value();

        if(point != sameValue){
            sameValue = point;
            sameValueIndex = index;
        }

        if(point > rest){
            break;
        }
        else{
            time += X;
            rest -= point;
            index++;
        }
    }

    if(rest > 0){
        int sameValueEnd = sameValueIndex;
        for(int i = sameValueIndex + 1; i < N; i++){
            Data temp = data[index];
            long long point = temp.value();
            if(point == sameValue){
                sameValueEnd = i;
            }
            else{
                break;
            }
        }

        long long minCnt = 1e18;
        for(int i = sameValueIndex; i <= sameValueEnd; i++){
            Data temp = data[i];
            minCnt = min(minCnt, temp.cnt(rest));
        }

        time += minCnt;
    }

    cout << time << endl;

    return 0;
}

