typedef long long i64;
const int NMAX = 100010;

struct Str {
	int vmin, vmax, other;
	i64 sp, suma;
	bool operator< (const Str& oth) {
		return sp > oth.sp;
	}
};
Str exams[NMAX];
int n, X;
i64 to_win;

void calc_exams()
{
	for (int i = 1; i <= n; i++) {
		i64 sact = 1LL * exams[i].other * exams[i].vmin;
		to_win += sact;
		sact += 1LL * (X - exams[i].other) * exams[i].vmax;
		exams[i].sp = sact;
	}
	sort(exams + 1, exams + n + 1);
	for (int i = 1; i <= n; i++)
		exams[i].suma = exams[i].sp, exams[i].sp += exams[i - 1].sp;
}

i64 TryExam(int id)
{
	// vreau sa iau cat mai putin din examul id
	int ans = 0, ok = 1;
	auto verif = [&](int poz) {
		return exams[poz].sp - (id <= poz ? exams[id].suma : 0);
	};
	for (int p = 1; p; p = (ok ? 2 * p : p / 2)) {
		if (ans + p <= n && verif(ans + p) < to_win - exams[id].suma)
			ans += p;
		else
			ok = 0;
	}
	if (verif(ans) < to_win - exams[id].suma)
		ans++;

	i64 tact = 1LL * (ans - (id <= ans ? 1 : 0)) * X;
	i64 left = to_win - verif(ans);
	if (left < 0)
		return tact;
	if (1LL * exams[id].vmin * exams[id].other >= left)
		tact += (left + exams[id].vmin - 1) / exams[id].vmin;
	else {
		tact += exams[id].other;
		left -= 1LL * exams[id].vmin * exams[id].other;
		tact += (left + exams[id].vmax - 1) / exams[id].vmax;
	}
	return tact;
}

