        while(place < line.size()){
            bline.push_back(line[place]);
            ++place;
        }
        LL nans = INF;
        REP(i, bline.size()){
            LL d = (sum - bline[i].b * bline[i].l + bline[i].b * bline[i].u + bline[i].u - 1) /bline[i].u;
            if(d > X)continue;
            nans = min(nans, d);
        }
        REP(i, bline.size()){
            LL d = (sum + bline[i].l - 1) / bline[i].l;
            if(d > bline[i].b)continue;
            nans = min(nans, d);
        }
        ans += nans;
    }
    cout << ans << endl;
    return 0;
}

