	scanf("%d %d", &n, &x);
	for(int i = 0; i < n; i++)
		scanf("%d %d %d", &t[i].b, &t[i].l, &t[i].u);
	sort(t, t + n);

	long long L = 0, R = 1LL * x * n;
	while(L < R){
		long long mid = (L + R) / 2;

		if(check(mid))R = mid;
		else L = mid + 1;
	}
	printf("%lld\n", L);

	return 0;
}

