ll n, x, hm;

struct test {
    ll b, l, u;
    bool operator< (const test &o) const {
        if((b*l + (x - b)*u) != (o.b*o.l + (x - o.b)*o.u))
            return (b*l + (x - b)*u) > (o.b*o.l + (x - o.b)*o.u);
        ll y = (hm >= b ? b*l + (hm - b)*u : hm*l);
        ll z = (hm >= o.b ? o.b*o.l + (hm - o.b)*o.u : hm*o.l);
        return y < z;
    }
};
vector<test> tests;

bool can(ll hrs) {
    hm = hrs % x;
    ll score = 0;
    int i = 0;
    sort(tests.begin(), tests.end());
    for(i = 0; i < n; i++)
        score -= tests[i].b * tests[i].l;
    for(i = 0; i < n; i++) {
        if(hrs < x) break;
        test t = tests[i];
        score += (t.b*t.l + (x - t.b)*t.u);
        hrs -= x;
    }
    ll bestEx = 0;
    for(int j = i; j < n; j++) {
        test t = tests[j];
        ll tmp = ((hrs >= t.b) ? (t.b*t.l + (hrs - t.b)*t.u) : hrs*t.l);
        bestEx = max(tmp, bestEx);
    }
    score += bestEx;
    return score >= 0ll;
}

