ll b[N], l[N], r[N];

bool ok(ll md){
    ll k = md / x;
    ll rem = md % x;
    vector<pii> sr;
    ll take = 0;
    for(int i = 0 ; i < n ; i ++ ){
        sr.push_back(mp((x - b[i]) * r[i] + l[i] * b[i], i));
        take += l[i] * b[i];
    }
    sort(sr.begin(), sr.end());
    reverse(sr.begin(), sr.end()); 
    ll tok = 0;
    ll toki = 0;
    for(int i = 0 ; i < n; i ++ ){
        if(i < k)tok += sr[i].fi;
        if(i <= k)toki += sr[i].fi;
    }
    int id;
    ll add;
    for(int i = 0 ; i < n ; i ++ ){
        id = sr[i].se;
        if(i < k){
            add = toki - sr[i].fi - take + l[id] * b[id];
            if(rem < b[id])
                add += (rem - b[id]) * l[id];
            else
                add += (rem - b[id]) * r[id];
            if(add >= 0)
                return true;
        }
        else{
            add = tok - take + l[id] * b[id];
            if(rem < b[id])
                add += (rem - b[id]) * l[id];
            else
                add += (rem - b[id]) * r[id];
            if(add >= 0)
                return true;
        }
    }
    return false;
}

int main(){
    fastIO;
