    for(int i = 0 ; i < n ; i ++ ){
        cin >> b[i] >> l[i] >> r[i];
    }
    ll L = 0, R = n * 1ll * x;
    ll M;
    while(L < R){
        M = (L + R) / 2;
        if(!ok(M)){
            L = M + 1;
        }
        else{
            R = M;
        }
    }
    cout << R << "\n";
    return 0;
}

