bool check(long long xx)
{
	long long lim = xx / x;
	int i;
	long long suma = 0, sumb = 0;
	for(i = 1; i <= lim + 1; i++)
	{
		suma += x * a[i].u;
		sumb += a[i].b * a[i].u;
	}
	for(i = lim + 2; i <= n; i++)
		sumb += a[i].b * a[i].l;
	long long last = xx - lim * x;
	long long sum;
	for(i = 1; i <= n; i++)
	{
		if(i <= lim)
			sum = -x * a[i].u + a[i].b * (a[i].u - a[i].l);
		else
			sum = -x * a[lim + 1].u + a[lim + 1].b * (a[lim + 1].u - a[lim + 1].l);
		long long sum1 = last * a[i].u - a[i].b * (a[i].u - a[i].l);
		long long sum2 = last * a[i].l;
		if(suma + sum1 + sum >= sumb)
			return true;
		if(suma + sum2 + sum >= sumb)
			return true;
	}
	return false;
}
