// 100点とったときの利得
long calcGainMax(long X, long i, vector<long> &enemy, vector<long> &lower, vector<long> &upper) {
  return X * upper[i] - enemy[i] * (upper[i] - lower[i]);
}

// 利得をarg減らすと何点減らせるか
long sabori(long removedGain, long X, long enemy, long lower, long upper) {
  // enemyより上の点を取りつつ条件を満たせる
  long reducedAtUpper = removedGain / upper;
  if (X - reducedAtUpper >= enemy) return reducedAtUpper;
  // enemyより下の点を
  long downer = removedGain - upper * (X - enemy);
  long reducedAtDowner = (X - enemy) + downer / lower;
  if (reducedAtDowner <= X) return reducedAtDowner;
  return X;
}

int main(void) {
  cout.precision(12);

  // N: テスト数
  // X: 満点
  long N, X;
  cin >> N >> X;

  // enemy: 青木くんが取る店
  // lower: 重要度の下限（以上）
  // upper: 重要度の上限（以下）
  vector<long> enemy(N), lower(N), upper(N);
  rep (i, N) cin >> enemy[i] >> lower[i] >> upper[i];

  // 重要素最低のときのenemyの得点
  long enemyBase = 0;
  rep (i, N) {
    enemyBase += enemy[i] * lower[i];
  }

  // 利得, テスト番号
  vector<pair<long, long>> gainMaxs(N);
  rep (i, N) gainMaxs[i] = make_pair(calcGainMax(X, i, enemy, lower, upper), i);

  sort(gainMaxs.rbegin(), gainMaxs.rend());

  unordered_set<long> usedTests;
  long result = 0;

  for (auto it: gainMaxs) {
    if (enemyBase <= 0) break;
    enemyBase -= it.first;
    usedTests.insert(it.second);
    result += X;
  }

  vector<long> reduceTime;
  for (auto it: usedTests) reduceTime.push_back(sabori(-enemyBase, X, enemy[it], lower[it], upper[it]));
  sort(reduceTime.rbegin(), reduceTime.rend());

  if (reduceTime.size() > 0) {
    result -= reduceTime[0];
  }

  cout << result << endl;
  return 0;
}

