#include <bits/stdc++.h>

using namespace std;
#define int long long

const int N = 100010;

int n, x;
tuple<int, int, int> a[N];
long long sumB[N];
long long sumA[N];

long long get(long long tot) {
    long long num = tot / x;
    tot %= x;
    long long res = -(1ll << 60);
    for (int i = num + 1; i <= n; i++) {
        long long ans = 0;
        if (i <= num) {
            ans += sumB[n] - sumB[num + 1] + sumA[num + 1];
            ans -= 1ll * get<2>(a[i]) * (x - get<0>(a[i]));
            if (tot <= get<0>(a[i])) {
                ans += 1ll * get<1>(a[i]) * (tot - get<0>(a[i]));
            } else {
                ans += 1ll * get<2>(a[i]) * (tot - get<0>(a[i]));
            }
        } else {
            ans += sumA[num] + sumB[n] - sumB[num];
            ans += 1ll * get<1>(a[i]) * get<0>(a[i]);
            if (tot <= get<0>(a[i])) {
                ans += 1ll * (tot - get<0>(a[i])) * get<1>(a[i]);
            } else {
                ans += 1ll * (tot - get<0>(a[i])) * get<2>(a[i]);
            }
        }
        res = max(res, ans);
    }
    return res;
}

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n >> x;
    for (int i = 1; i <= n; i++) {
        int b, l, u;
        cin >> b >> l >> u;
        a[i] = make_tuple(b, l, u);
    }
    sort(a + 1, a + n + 1, [&](tuple<int, int, int> u, tuple<int, int, int> v) {
        int b1, l1, u1, b2, l2, u2;
        tie(b1, l1, u1) = u;
        tie(b2, l2, u2) = v;
        return 1ll * u1 * (x - b1) > 1ll * u2 * (x - b2);
    });
    for (int i = 1; i <= n; i++) {
        sumB[i] = sumB[i - 1] - 1ll * get<1>(a[i]) * get<0>(a[i]);
        sumA[i] = sumA[i - 1] + 1ll * get<2>(a[i]) * (x - get<0>(a[i]));
