ll  F[N];

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    int n;  cin >> n;
    int X;  cin >> X;

    auto cal = [&](pii A)   {
        int c = A.X;
        int l = A.Y.X;
        int r = A.Y.Y;

        return  1ll * r * (X - c) + 1ll * l * c;
    };

    vector<pii> arr;

    ll  Sum = 0;

    for(int i = 0 ; i < n ; ++i)    {
        int b;  cin >> b;
        int l;  cin >> l;
        int r;  cin >> r;

        arr.pb(b,ii(l,r));
        Sum += 1ll * l * b;
    }

    sort(all(arr),[&](const pii&A,const pii&B)  {   return  cal(A) > cal(B);    });

    for(int i = 0 ; i < n ; ++i)    {
        F[i] = cal(arr[i]);
        if (i)
            F[i] += F[i - 1];
    }

    ll  L = 0;
    ll  R = 1ll * n * X;

    while (L < R)   {
        ll  M = (L + R) / 2;
        int cnt = M / X;
        int rem = M % X;

        assert(cnt < n);

        bool ok = 0;

        for(int i = 0 ; i < n ; ++i)    {
            ll  C = F[cnt];

            if (i >= cnt)   C -= cal(arr[cnt]);
            else            C -= cal(arr[i]);

            if (arr[i].X >= rem)    C += 1ll * arr[i].Y.X * (rem - arr[i].X);
            else                    C += 1ll * arr[i].Y.Y * (rem - arr[i].X);

            C -= Sum;
            C += 1ll * arr[i].Y.X * arr[i].X;

            if (C >= 0) {
                ok = 1;
                break;
            }
        }
        if (ok) R = M;
        else    L = M + 1;
    }
    cout << L << endl;
}

