bool solve(){
    int nn, xx;
    input(nn, xx);
    vector<int> bb(nn), ll(nn), uu(nn);
    pararell_input(nn, bb, ll, uu);

    i64 n = nn;
    i64 x = xx;
    vector<i64> b, l, u;
    for(int i = 0; i < n; ++i){
        b.emplace_back(bb[i]);
        l.emplace_back(ll[i]);
        u.emplace_back(uu[i]);
    }
    i64 b_sum = 0;
    for(i64 i = 0; i < n; ++i)
        b_sum += b[i] * l[i];

    vector<i64> ful_adv(n);
    vector<pair<pair<i64,i64>,i64>> ful_adv_p;
    for(i64 i = 0; i < n; ++i){
        ful_adv[i] = u[i] * x - (u[i] - l[i]) * b[i];
        ful_adv_p.emplace_back(make_pair(ful_adv[i], l[i]), i);
    }
    sort(ful_adv_p.begin(), ful_adv_p.end(), greater<pair<pair<i64,i64>,i64>>());

    auto f = [&](i64 val){
        i64 cnt = min(val / x, n);
        i64 mod = (cnt == n ? 0 : val % x);
        i64 adv = 0;
        i64 dif = b_sum;
        i64 mod_adv = 0;
        bitset<100007> bs;

        for(i64 i = 0; i < cnt; ++i){
            adv += ful_adv_p[i].first.first;
            if(adv >= dif)
                return true;
            bs.set(ful_adv_p[i].second);
        }
        for(i64 i = 0; i < n; ++i){
