void solve(long long N, long long X, std::vector<long long> b,
           std::vector<long long> l, std::vector<long long> u) {
  priority_queue<pll> points;
  rep(i, 0, N) { points.push(mp((X - b[i]) * u[i] + b[i] * l[i], i)); }

  ll tWinPoints = 0;
  rep(i, 0, N) { tWinPoints -= b[i] * l[i]; }

  ll ans = 0;
  vector<bool> checked(N);
  while (tWinPoints < 0) {
    auto p = points.top();
    ll point = p.first;
    ll i = p.second;
    points.pop();

    ll addPoint = point;
    if (abs(tWinPoints) >= addPoint) {
      tWinPoints += addPoint;
      ans += X;
      checked[i] = true;
    } else {
      break;
    }
  }

  if (tWinPoints < 0) {
    priority_queue<pll> points;
    rep(i, 0, N) {
      if (!checked[i]) {
        points.push(mp((X - b[i]) * l[i] + b[i] * l[i], i));
      }
    }

    auto p = points.top();
    ll point = p.first;
    ll i = p.second;
    ans += ceil(-tWinPoints / (double)l[i]);
  }

  print(ans);
}

