#define SIZE 200010

ll N, X;
ll B[SIZE], L[SIZE], U[SIZE];
vector<pair<ll,int> > vec;

bool check(ll x){
  bool used[SIZE] = {};
  ll sum = 0;

  for(int i=0;i<x/X;i++){
    used[vec[i].second] = true;
    sum += vec[i].first;
  }

  for(int i=0;i<N;i++){
    sum -= B[i] * L[i];
  }

  ll y = 0, z = 0;

  x = x % X;

  for(int i=0;i<N;i++){
    if(used[vec[i].second]) continue;
    z = max(z, vec[i].first);
  }

  debug(sum);

  for(int i=0;i<N;i++){
    int e = vec[i].second;
    if (used[e]) {
      ll r = -vec[i].first + z;
      if (x >= B[e]) {
        r += (ll)B[e] * L[e] + (ll)U[e] * (x - B[e]);
      } else {
        r += (ll)x * L[e];
      }

      y = max(y, r);
    } else {
      if (x >= B[e]) {
        y = max(y, (ll)B[e] * L[e] + (ll)U[e] * (x - B[e]));
      } else {
        y = max(y, (ll)x * L[e]);
      }
    }
  }

  sum += y;

  return sum >= 0;
}

