const int N=1e5+5;

int n,x,b[N],l[N],u[N],ord[N];
ll val[N];

bool cmp(int x,int y) {return val[x]>val[y];}

ll chk_mx(ll k) {
	ll sum=0;
	fo(i,1,k/x) sum+=val[ord[i]];
	ll mx=0,ret=k%x;
	fo(i,k/x+1,n) {
		int z=ord[i];
		ll cnt=(ret<=b[z])?ret*l[z]:(ll)b[z]*l[z]+(ret-b[z])*u[z];
		mx=max(mx,cnt);
	}
	return sum+mx;
}

int main() {
	n=read();x=read();
	fo(i,1,n) b[i]=read(),l[i]=read(),u[i]=read();
	fo(i,1,n) val[i]=(ll)l[i]*b[i]+(ll)(x-b[i])*u[i];
	fo(i,1,n) ord[i]=i;sort(ord+1,ord+n+1,cmp);
	ll d=0;fo(i,1,n) d+=(ll)l[i]*b[i];
	ll L=0,R=0,ans=0;fo(i,1,n) R+=b[i];
	while (L<=R) {
		ll mid=L+R>>1;
		if (chk_mx(mid)>=d) ans=mid,R=mid-1;
		else L=mid+1;
	}
	printf("%lld\n",ans);
	return 0;
}

