  rep(i,M){
    sum+=ls[i].add;
  }

  ll pen=-sum;
  if(pen<=0)return true;

  res=INF;
  repl(i,M,N){
    ll cb=ls[i].b,cl=ls[i].l,cu=ls[i].u;
    ll x;
    if(cb*cl>=pen){
      x=(pen+cl-1)/cl;
    }else{
      x=((pen-cb*cl+cu-1)/cu) + cb;
    }
    minch(res,x);
  }

  return res<=X;
}

