bool judge(ll lim){
  vector<int> used(N,0);


  ll aoki=0;
  ll taka=0;
  for(int i=0;i<N;i++){
    aoki+=L[i]*B[i];
  }

  ll opnum=lim;
  int uvnum=0;

  for(int i=0;i<N;i++){
      //int now=uv[i].second;
      int now=vv[i].second;
      if(opnum>=X){
          used[now]=1;
          taka+=R[now]*X;
          aoki-=L[now]*B[now];
          aoki+=R[now]*B[now];
          opnum-=X;
      }else break;
  }

  vector<pair<ll,int>> v;
  for(int i=0;i<N;i++){
      if(used[i]) continue;
      if(B[i]>=opnum){
          v.push_back(mkp(opnum*L[i],B[i]));
      }else{
          v.push_back(mkp(R[i]*(opnum-B[i])+L[i]*B[i],B[i]));
      }
  }

  if(v.size()==0){
      if(taka>=aoki) return true;
      else return false;
  }

  sort(v.begin(),v.end());
  reverse(v.begin(),v.end());
  taka+=v[0].first;

  if(taka>=aoki) return true;
  else return false;
}

