ll base = 0;
typedef tuple<ll, ll, ll, ll> test;
vector<test> V;
ll sum[100010];

bool solve(ll T)
{
  ll cnt = T / X;
  ll x = T % X;
  ll ans = -1000000000000000;
  for (auto i = 0; i < N; i++)
  {
    ll t, b, l, u;
    tie(t, b, l, u) = V[i];
    ll tmp = 0;
    if (x >= b)
    {
      tmp = l * b + u * (x - b);
    }
    else
    {
      tmp = l * x;
    }
    if (i < cnt)
    {
      ans = max(ans, sum[cnt + 1] - t + tmp);
    }
    else
    {
      ans = max(ans, sum[cnt] + tmp);
    }
  }
  return (ans >= 0);
}

