  bool operator< (Test &r) {
    return mx > r.mx;
  }
};

Test p[100002]; bool vs[100002];

long long fullScore(int i){
  return 1LL * L[i] * B[i] + 1LL * U[i] * (X - B[i]);
}

int reqScore(int i, long long now){
  if(now + 1LL * L[i] * B[i] >= 0){
    return (L[i] - now - 1) / L[i];
  }

  now += 1LL * L[i] * B[i];
  return B[i] + (U[i] - now - 1) / U[i];
}

int main(){
  int N, X; scanf("%d%d", &N, &X); ::X = X;

  for(int i = 1; i <= N; i++){
    scanf("%d%d%d", &B[i], &L[i], &U[i]);
  }

  long long now = 0;
  for(int i = 1; i <= N; i++) now -= 1LL * L[i] * B[i];

  for(int i = 1; i <= N; i++) p[i] = { i, fullScore(i) };

  sort(p + 1, p + N + 1);

  int wall = 0; long long ans = 0;

  for(int i = 1; i <= N; i++){
    if(now + p[i].mx < 0){
      ans += X; now += p[i].mx; vs[p[i].i] = true;
    }
    else{ wall = p[i].i; break; }
  }

  int lst = X;

  for(int i = 1; i <= N; i++){
    if(vs[i]){
      lst = min(lst, reqScore(i, now - fullScore(i) + fullScore(wall)));
    }
    else if(now + fullScore(i) >= 0){
      lst = min(lst, reqScore(i, now));
    }
  }

  printf("%lld\n", ans + lst);
  return 0;
}

