// template

bool f(int time, vector<tuple<int, int, int> > BLU, int X) {
	int N = BLU.size();
	vector<int> times(N);
	priority_queue<pair<int, int>> que;
	REP(i, N) {
		int b, l, u; tie(b, l, u) = BLU[i];
		que.emplace(u * (X - b) + l * b, i);
	}

	while (time >= X) {
		auto top = que.top(); que.pop();
		int index = top.second;
		times[index] = X;
		time -= X;
	}

	que = priority_queue<pair<int, int>>();
	REP(i, N) if (times[i] == 0) {
		int b, l, u; tie(b, l, u) = BLU[i];
		if (time > b) {
			que.emplace(u * (time - b) + l * b, i);
		}
		else {
			que.emplace(l * time, i);
		}
	}

	int index = que.top().second;
	times[index] = time;

	int A = 0;
	int B = 0;
	REP(i, times.size()) {
		int b, l, u; tie(b, l, u) = BLU[i];
		if (b < times[i]) {
			A += u * times[i];
			B += u * b;
		}
		else {
			A += l * times[i];
			B += l * b;
		}
	}

	return A >= B;
}

void solve() {
	int N, X; cin >> N >> X;
	vector<tuple<int, int, int >> BLU;
	REP(i, N) {
		int b, l, u;
		cin >> b >> l >> u;
		BLU.emplace_back(b, l, u);
	}

	int ng = 0;
	int ok = N * X;

	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if (f(mid, BLU, X)) {
			ok = mid;
		}
		else {
			ng = mid;
		}
	}
	cout << ok << endl;
}

