void chemthan() {
    int n, x; cin >> n >> x;
    vi b(n), l(n), u(n);
    FOR(i, 0, n) cin >> b[i] >> l[i] >> u[i];
    vi vals;
    FOR(i, 0, n) {
        vals.pb(i);
    }
    long long lo = 0, hi = LINF;
    while (lo < hi) {
        long long mi = lo + hi >> 1;
        long long num = mi / x;
        long long r = mi % x;
        int found = 0;
        if (n <= num) {
            found = 1;
        }
        else {
            sort(all(vals), [&] (int i, int j) {
                    return (long long) (x - b[i]) * u[i] - (long long) b[j] * l[j] > (long long) (x - b[j]) * u[j] - (long long) b[i] * l[i];
                    }
                );
            long long sum = 0, sum2 = 0, mx = -1;
            FOR(i, 0, num) {
                int j = vals[i];
                sum += (long long) (x - b[j]) * u[j];
            }
            FOR(i, num, n) {
                int j = vals[i];
                sum2 += (long long) -b[j] * l[j];
            }
            FOR(i, 0, n) {
                int j = vals[i];
                if (i < num) {
                    sum -= (long long) (x - b[j]) * u[j];
                    int k = vals[num];
                    sum += (long long) (x - b[k]) * u[k];
                    sum2 -= (long long) -b[k] * l[k];
                }
                else {
                    sum2 -= (long long) -b[j] * l[j];
                }

                chkmax(mx, sum + (long long) (r - b[j]) * u[j] + sum2);
                chkmax(mx, sum + (long long) (r - b[j]) * l[j] + sum2);

                if (i < num) {
                    sum += (long long) (x - b[j]) * u[j];
                    int k = vals[num];
                    sum -= (long long) (x - b[k]) * u[k];
                    sum2 += (long long) -b[k] * l[k];
                }
                else {
                    sum2 += (long long) -b[j] * l[j];
                }
            }
            if (0 <= mx) {
                found = 1;
            }
        }
        if (!found) {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
    cout << (lo + hi >> 1) << "\n";
}

