using namespace std;

using ll = long long;

const int MAXN = 3e5;
int N;
ll X;
ll B[MAXN], L[MAXN], U[MAXN];
ll tots[MAXN];

ll base;
int inds[MAXN];

ll get_cost(int ind, ll A) {
	if (A <= B[ind]) {
		return A * L[ind];
	} else {
		return B[ind] * L[ind] + (A - B[ind]) * U[ind];
	}
}

bool is_good(ll v) {
	// let's decide from which sequence we will take r first terms
	// then, we will take q largest sequences besides it

	int q = v / X;
	int r = v - q * X;

	ll sum = base;
	for (int i = 0; i < q; i++) {
		sum += tots[inds[i]];
	}
	for (int i = 0; i < N; i++) {
		ll nsum = sum + get_cost(inds[i], r);
		if (i < q) {
			nsum -= tots[inds[i]];
			nsum += tots[inds[q]];
		}
		if (nsum >= 0) {
			return true;
		}
	}

	return false;
}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> X;
	for (int i = 0; i < N; i++) {
		cin >> B[i] >> L[i] >> U[i];
		base += -L[i] * B[i];
		tots[i] = B[i] * L[i] + (X - B[i]) * U[i];
	}

	iota(inds, inds + N, 0);
	sort(inds, inds + N, [&](int i, int j) { return tots[i] > tots[j]; });

	ll mi = -1, ma = X * N;
	while (ma - mi > 1) {
		ll md = (mi + ma) / 2;
		if (is_good(md)) {
			ma = md;
		} else {
			mi = md;
		}
	}
	cout << ma << endl;

	return 0;
}

