#include <bits/stdc++.h>
using namespace std;

#define int long long

const int MAX_N = 100 * 1000 + 5;
int n, X, b[MAX_N], l[MAX_N], u[MAX_N], id[MAX_N];

void read_input() {
	cin >> n >> X;
	for (int i = 0; i < n; i++)
		cin >> b[i] >> l[i] >> u[i];
}

int get(int i) {
	return u[i] * (X - b[i]) + b[i] * l[i];
}

bool cmp(int i, int j) {
	return get(i) > get(j);
}

void solve() {
	iota(id, id + n, 0);
	sort(id, id + n, cmp);
	int sum = 0;
	for (int i = 0; i < n; i++)
		sum += b[i] * l[i];
	int ans = 0;
	for (int t = 0; t < n && sum; t++) {
		int i = id[t];
		int tmp = (X - b[i]) * u[i] + b[i] * l[i];
		if (sum >= tmp) {
			sum -= tmp;
			ans += X;
		}
		else {
			int mn = 1e15;
			for (int p = t; p < n; p++) {
				int j = id[p];
				mn = min(mn, min((sum + l[j] - 1) / l[j], (sum - l[j] * b[j] + u[j] - 1) / u[j] + b[j]));
			}
			sum -= tmp;
			for (int p = 0; p < t; p++) {
				int j = id[p];
				sum += X * u[j];
				mn = min(mn, min((sum + u[j] - 1) / u[j], (sum - u[j] * b[j] + l[j] - 1) / l[j] + b[j]));
				sum -= X * u[j];
			}
			ans += mn;
			break;
		}
	}
	cout << ans;
}

int32_t main() {
	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	read_input();
	solve();
}

