signed main() {
	cin >> n >> x;
	priority_queue<P>p;
	int res = 0;
	for (int i = 0; i < n; i++) {
		cin >> a[i].b >> a[i].l >> a[i].u;
		p.push(P{ i,(x - a[i].b) * a[i].u });
		res += a[i].b * a[i].l;
	}
	int sum = 0, m = 0;
	while (res > sum) {
		P t = p.top(); p.pop();
		int k = sum + a[t.pos].u * x;
		int r = res + a[t.pos].b * (a[t.pos].u - a[t.pos].l);
		if (r > k) {
			sum += a[t.pos].u * x;
			res += a[t.pos].b * (a[t.pos].u - a[t.pos].l);
			m++;
		}
		else break;
	}
	while (!p.empty()) p.pop();
	priority_queue<P, vector<P>, greater<P>>q;
	for (int i = 0; i < n; i++) {
		p.push(P{ i,a[i].u * (x - a[i].b) });
	}
	sum = 0, res = 0;
	for (int i = 0; i < m; i++) {
		b[p.top().pos] = 1;
		sum += p.top().cost;
		q.push(P{ p.top().pos,p.top().cost });
		p.pop();
	}
	for (int i = 0; i < n; i++) {
		if (!b[i]) {
			res += a[i].l * a[i].b;
		}
	}
	int ans = Inf;
	for (int i = 0; i < n; i++) {
		while (!q.empty()&&b[q.top().pos] == 0) {
			q.pop();
			continue;
		}
		while (!p.empty()&&b[p.top().pos] == 1) {
			p.pop();
			continue;
		}
		if (b[i]) {
			b[i] = 0;
			b[p.top().pos] = 1;
			sum += p.top().cost;
			sum -= a[i].u * (x - a[i].b);
			res -= a[p.top().pos].l * a[p.top().pos].b;
			res += a[i].l * a[i].b;
			q.push(p.top());
			p.pop();
		}
	loop:;
		while (!p.empty()&&p.top().pos == i) {
			p.pop();
			continue;
		}
		while (!q.empty() && q.top().pos == i) {
			q.pop();
			continue;
		}
		while (!q.empty() && b[q.top().pos] == 0) {
			q.pop();
			continue;
		}
		while (!p.empty() && b[p.top().pos] == 1) {
			p.pop();
			continue;
		}
		if (!p.empty()&&!q.empty()&&p.top().cost > q.top().cost) {
			P t = p.top();
			P r = q.top();
			p.pop(); q.pop();
			p.push(r);
			q.push(t);
			goto loop;
		}
		int ok = x, ng = 0, t;
		while (ok - ng > 1) {
			t = (ok + ng) / 2;
			if ((t - a[i].b) * a[i].u >= res - a[i].b * a[i].l - sum) {
				ok = t;
