			}
			if ((t - a[i].b) * a[i].l >= res - a[i].b * a[i].l - sum) {
				ok = t;
				continue;
			}
			ng = t;
		}
		if ((ok - a[i].b) * a[i].u >= res - a[i].b * a[i].l - sum) {
			ans = min(ans, ok + m * x);
		}
		if ((ok - a[i].b) * a[i].l >= res - a[i].b * a[i].l - sum) {
			ans = min(ans, ok + m * x);
		}
