using namespace std;

int main() {
  int n;
  ll x;
  scan(n, x);
  vll b(n), l(n), u(n);
  rep (i, n) {
    scan(b[i], l[i], u[i]);
  }

  ll debt = 0;
  rep (i, n) {
    debt += b[i] * l[i];
  }

  vvll pred(n, vll(5));
  rep (i, n) {
    pred[i][0] = b[i] * l[i] + (x - b[i]) * u[i];
    pred[i][1] = i;
    pred[i][2] = b[i];
    pred[i][3] = l[i];
    pred[i][4] = u[i];
  }
  sort(all(pred), greater<vll>());
  debug(pred);

  vll accum(n+1, 0);
  rep (i, n) {
    accum[i+1] = accum[i] + pred[i][0];
  }
  ll ans = n * x;
  rep (i, n) {
    ll thre = debt - pred[i][0];
    ll ng = 0;
    ll ok = n;
    if (thre <= 0) {
      ok = 0;
    } else {
      while (ok - ng > 1) {
        ll mid = (ng + ok) / 2;
        if ((mid <= i && accum[mid] >= thre) || (mid > i && accum[mid] - pred[i][0] >= thre)) {
          ok = mid;
        } else {
          ng = mid;
        }
      }
    }
    ll rest = debt - accum[ok];
    if (ok > i) {
      rest += pred[i][0];
    }
    ll rest_min;
    if (pred[i][2] * pred[i][3] >= rest) {
      rest_min = (rest + pred[i][3] - 1) / pred[i][3];
    } else {
      rest_min = pred[i][2] + (rest - pred[i][2] * pred[i][3] + pred[i][4] - 1) / pred[i][4];
    }
    rest_min = max(0LL, min(x, rest_min));
    debug3(i, rest_min, ok);
    ans = min(ans, rest_min + x * (ok > i ? ok - 1 : ok));
  }
  print(ans);

  return 0;
}

