pair<ll,int> p[100005];
int main(){
	ll n,x; cin >> n>> x;
	vector<ll> b(n),l(n),u(n);
	cinf(n,b,l,u);
	ll sum=0;
	for(int i=0;i<n;i++){
		p[i]=pair<ll,int>((x-b[i])*u[i]+b[i]*l[i],i);
		sum-=b[i]*l[i];
	}
	sort(p,p+n);
	ll ret=0;
	int last=0;
	for(int i=n-1;i>=0;i--){
		if(sum+p[i].first>=0){
			ret+=(ll) (n-i-1)*(ll)x;
			last=i+1;
			break;
		}
		sum+=p[i].first;
	}
	ll Min=x;
	sum=-sum;
	for(int i=0;i<last;i++){
		int v=p[i].second;
		Min=min(Min,(sum+l[v]-1)/l[v]);
		ll nsum=sum+b[v]*(u[v]-l[v]);
		Min=min(Min,(nsum+u[v]-1)/u[v]);
	}
	for(int i=last;i<n;i++){
		int v=p[i].second;
		ll nsum=sum+p[i].first-p[last-1].first;
		Min=min(Min,(nsum+l[v]-1)/l[v]);
		ll nsum2=nsum+b[v]*(u[v]-l[v]);
		Min=min(Min,(nsum2+u[v]-1)/u[v]);
