template <typename T>
std::vector<size_t> sort_indexes(const std::vector<T> &v) {
  std::vector<size_t> idx(v.size());
  std::iota(idx.begin(), idx.end(), 0);
  std::sort(idx.begin(), idx.end(), [&v](size_t i1, size_t i2) {return v[i1] > v[i2];});
  return idx;
}
int main() {
  int n,x;
  std::cin >> n >> x;
  std::vector<int> value(n);
  std::vector<Inp> inputs;
  inputs.reserve(n);
  ll sum_cost = 0;
  rep(i,n) {
    int b,l,u;
    std::cin >> b >> l >> u;
    value[i] = (x-b)*u+b*l;
    inputs.emplace_back(b,l,u);
    sum_cost+=b*l;
  }
  std::vector<size_t> idx = sort_indexes<int>(value);
  int i = 0;
  for(;sum_cost>0;i++) {
    sum_cost-=value[idx[i]];
  }
  i--;
  ll sum_time = x*i;
  sum_cost+=value[idx[i]];
  ll minx = x;
  for(int j=i;j<n;j++) {
    minx = std::min(minx,(sum_cost-inputs[idx[j]].b*inputs[idx[j]].l)/inputs[idx[j]].u+inputs[idx[j]].b);
  }
  sum_time += minx;
  std::cout << sum_time << "\n";
  return 0;
}

