int main(int argc, char const *argv[]) {
  ll N, X, D=0;
  std::cin >> N >> X;
  vvl blu = vv(N, 4, 0, ll);
  for(int i=0;i<N;i++) {
    std::cin >> blu[i][0] >> blu[i][1] >> blu[i][2];
    D -= blu[i][0] * blu[i][1];
    blu[i][3] = blu[i][0] * blu[i][1] + (X - blu[i][0]) * blu[i][2];
  }
  ll ans=1000000000000000;
  //sort
  sort(blu.begin(), blu.end(), [](vector<ll> &a, vector<ll> &b){
    return a[3] > b[3];
  });
  for(int i=0;i<N;i++){
    pair<ll, ll> su = make_pair(0, 0);
    for(int j=0;j<N;j++){
      if(j==i) continue;
      if(D + su.second + blu[i][3] >= 0) break;
      su.second += blu[j][3];
      su.first += X;
      if(D + su.second +  blu[i][3] >= 0) break;
    }
    if(su.second + blu[i][3] + D >= 0){
      ll reg = su.first;
      reg += (abs(D + su.second)<=blu[i][0]*blu[i][1]
        ?abs(D + su.second)/blu[i][1]+((D + su.second)%blu[i][1]==0?0:1)
        :blu[i][0] + abs(D + su.second + blu[i][0]*blu[i][1])/blu[i][2]) + ((D + su.second + blu[i][0]*blu[i][1])%blu[i][2]==0?0:1);
      ans = (ans>reg?reg:ans);
    }
  }
  std::cout << ans << '\n';
  return 0;
}

