constexpr int INF = (1<<30);
constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;
constexpr ll MOD = (ll)((1E+9)+7);

int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N,X;
  IN(N,X);
  vll b(N), l(N), u(N);
  vpll VP(2*N);
  REP(i,N){
    IN(b[i], l[i], u[i]);
    VP[i].first = u[i]*b[i] - l[i]*b[i] - u[i]*X;
    VP[i].second = i;
    VP[i+N].first = -l[i]*X;
    VP[i+N].second = i + N;
  }

  sort(ALL(VP));

  /*
  REP(i,2*N){
    printf("%d %d %d\n", i, VP[i].first, VP[i].second);
  }
  */

  ll T_point=0, A_point=0;

  REP(i,N){
    A_point += b[i]*l[i];
  }

  ll ans = 0;
  vll flag(N, true);

  ll pos = 0;
  while(T_point<A_point){
    ll i = VP[pos].second;
    pos++;
    if(flag[i%N]==false) continue;

    //printf("%d %d %d\n", i, T_point, A_point);
    if(i<N){
      A_point += b[i]*(u[i]-l[i]);
      T_point += u[i]*X;
    }else{
      T_point += l[i%N]*X;
    }
    if(T_point<A_point){
      ans += X;
      flag[i%N] = false;
    }else{
      if(i<N){
        A_point -= b[i]*(u[i]-l[i]);
        T_point -= u[i]*X;
      }else{
        T_point -= l[i%N]*X;
      }

      ll X_add_min = X;

      for(int j=0; j<N; ++j){
        if(flag[j]==false) continue;
        ll coef = b[j]*(u[j]-l[j]);
        if(T_point+u[j]*X < A_point+coef) continue;
        ll X_tmp = (A_point - T_point + coef)/u[j];
        while(T_point+u[j]*X_tmp < A_point+coef) X_tmp++;
        X_add_min = min(X_add_min, X_tmp);

        if(T_point+l[j]*X < A_point) continue;
        ll X_tmp2 = (A_point - T_point) / l[j];
        while(T_point+l[j]*X_tmp2 < A_point) X_tmp2++;
        X_add_min = min(X_add_min, X_tmp2);

      }

      ans += X_add_min;

      break;
    }
  }

  OUT(ans);

  return 0;
}

#include <bits/stdc++.h>

using namespace std;

int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    long N, X; cin>>N>>X;
    struct Data {
        long b, l, u;
        Data() {
            cin>>b>>l>>u;
        }
        long value(long x) {
            return b*l+(x-b)*u;
        }
    };
    vector<Data> datas(N);
    sort(datas.begin(), datas.end(), [X](auto l, auto r) {return l.value(X) > r.value(X);});
    long B = 0;
    for (auto& data : datas) {
        B += data.b*data.l;
    }

    auto solve = [&](long k) {
        long max_sum = 0;
        for (int n = 0; n < N; n++){
            auto q = k/X;
            long sum = 0;
            for (int i = 0, c = 0; c < q; i++) {
                if (i == n)
                    continue;
                c++;
                sum += datas[i].value(X);
            }
            auto r = k%X;
            auto& data = datas[q];
            if (r <= data.b) {
                sum += data.l*r;
            } else {
                sum += data.l*data.b + data.u*(r-data.b);
            }
            max_sum = max(max_sum, sum);
        }
        return max_sum >= B;
    };

    long l = 1, r = N*X;
    long ans = r;
    while (l <= r) {
        auto c = (l+r)/2;
        if (solve(c)) {
            r = c-1;
            ans = c;
        } else {
            l = c+1;
        }
    }
    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

#define REP(i,n) for(ll (i) = (0);(i) < (n);++i)
#define REV(i,n) for(ll (i) = (n) - 1;(i) >= 0;--i)
#define PB push_back
#define EB emplace_back
#define MP make_pair
#define FI first
#define SE second
#define SHOW1d(v,n) {REP(WW,n)cerr << v[WW] << ' ';cerr << endl << endl;}
#define SHOW2d(v,WW,HH) {REP(W_,WW){REP(H_,HH)cerr << v[W_][H_] << ' ';cerr << endl;}cerr << endl;}
#define ALL(v) v.begin(),v.end()
#define Decimal fixed<<setprecision(20)
#define INF 1000000000
#define LLINF 1000000000000000000LL
#define MOD 998244353

typedef long long ll;
typedef pair<ll,ll> P;

ll calPoint(pair<P, P> test, ll place){
	ll ret = 0;
	if(place < test.FI.SE){
		return test.SE.FI * place;
	}
	ret += test.FI.SE * test.SE.FI;
	return ret + test.SE.SE * (place - test.FI.SE);
}

bool check(vector<pair<P, P>> &v, ll mid, ll now, ll x, ll n){
	ll cou = mid / x;
	ll amari = mid % x;
	if(cou == v.size())return true;

	REP(i, cou){
		now += v[i].FI.FI;
	}
	REP(i, n){
		ll point = calPoint(v[i], amari);
		if(i < cou){
			now -= v[i].FI.FI;
			now += v[cou].FI.FI + point;
			if(now >= 0)return true;
			now += v[i].FI.FI;
			now -= v[cou].FI.FI + point;
		}
		else {
			now += point;
			if(now >= 0)return true;
			now -= point;
		}
	}

	return false;

}

int main(){
	cin.tie(0);cout.tie(0);ios::sync_with_stdio(false);

	ll n, x;cin >> n >> x;
	vector<pair<P, P>> v;
	ll now = 0;
	REP(i, n){
		ll b, l , r;cin >> b >> l >> r;
		v.EB(MP(l * b + r * (x - b), b), MP(l, r));
		now -= l * b;
	}

	sort(ALL(v), greater<pair<P, P>>());

	ll l = -1;
	ll r = x * n;
	while(r - l > 1){
		ll mid = (l + r) / 2;
		if(check(v, mid, now, x, n))r = mid;
		else l = mid;
	}

	cout << r << endl;

	return 0;
}

