int main() {
    ll n, x;
    cin >> n >> x;
    VL b(n), l(n), u(n);
    vector<PL> p(n);
    REP(i,n){
        b[i] = in(), l[i] = in(), u[i] = in();
        p[i].first = -(u[i] * (x - b[i]) + l[i] * b[i]);
        p[i].second = i;
    }
    sort(ALL(p));

    VL bb(b), lll(l), uu(u);
    REP(i,n){
        int j = p[i].second;
        b[i] = bb[j];
        l[i] = lll[j];
        u[i] = uu[j];
    }

    VL su(n + 1), sl(n + 1);
    REP(i,n){
        su[i + 1] = su[i] + u[i] * (x - b[i]);
        sl[i + 1] = sl[i] + l[i] * b[i];
    }

    ll ok = n * x, ng = -1;
    while (ok - ng > 1){
        ll c = (ok + ng) / 2;
        ll p = c / x;
        ll q = c % x;
        bool found = false;
        REP(i,n){
            ll tmp = 0;
            if (i < p){
                tmp = su[p + 1] - (sl[n] - sl[p + 1]) - u[i] * (x - b[i]);
            }else{
                tmp = su[p] - (sl[n] - sl[p]) + l[i] * b[i];
            }
            if (q >= b[i]) tmp += u[i] * (q - b[i]);
            else tmp -= l[i] * (b[i] - q);
            if (tmp >= 0) found = true;
        }
        if (found) ok = c;
        else ng = c;
    }
    cout << ok << endl;

    return 0;
}

