	int b[n], L[n], R[n], d[n];
	for(int i = 0; i < n; i++) {
		cin >> b[i] >> L[i] >> R[i];
		d[i] = R[i] * (x - b[i]) - L[i] * b[i];
	}
	int p[n];
	iota(p, p + n, 0);
	sort(p, p + n, [&](int x, int y) {
		return d[x] > d[y];
	});
	int sum = 0;
	for(int i = 0; i < n; i++) {
		sum -= L[i] * b[i];
	}
	set<pair<int, int>> Ri, Li;
	for(int i = 0; i < n; i++) {
		Ri.insert({R[i], i});
		Li.insert({L[i], i});
	}
	int ans = x * n;
	for(int it = 0; it < n; it++) {
		int i = p[it];
		int Lj = prev(end(Li))->first;
		// sum + L[j] * k >= 0
		int k1 = (-sum + Lj - 1) / Lj;
		if(k1 <= x) {
			ans = min(ans, x * i + k1);
		}
		int k2 = b[i] + (-sum - L[i] * b[i] + R[i] - 1) / R[i];
		if(k2 <= x) {
			ans = min(ans, x * i + k2);
		}
		sum += R[i] * (x - b[i]) + L[i] * b[i];
		Ri.erase({R[i], i});
		Li.erase({L[i], i});
	}
	cout << ans << endl;
	return 0;
}

