long long n,x;
int cmp(stu aa,stu bb){
    return aa.u*(x-aa.b)>bb.u*(x-bb.b);
}

int check(long long mid)
{

    long long p=mid%x;long long q=mid/x;
    for (long long i=0;i<n;i++)
    {
        long long dis=0;
        if (p!=0){
        if(p>s[i].b){
            dis+=p*s[i].u;
            dis-=s[i].b*s[i].u;
        }else{
            dis+=p*s[i].l;
            dis-=s[i].b*s[i].l;
        }
        }
        long long tmp=q;long long now=0;
        while(tmp){
            if (p!=0 && now==i){now++;continue;}
            tmp--;
            dis+=x*s[now].u;
            dis-=s[now].b*s[now].u;
            now++;
        }
        for (long long j=now;j<n;j++)
        {
            if(p!=0 && j==i) continue;
            dis-=s[j].b*s[j].l;
        }
        if (dis>=0)
        {
            return 1;
        }
    }


    return 0;
}

