typedef long long ll;

const int maxn = 1e5 + 7;

int n, x;

struct node {
  ll b, l, u, sorce;
  friend bool operator < (const node& x, const node& y) {
    if (x.sorce == y.sorce) return 1;
    return x.sorce > y.sorce;
  }
} a[maxn];

ll check(ll t) {
  ll tim = t / x;
  ll res = t - tim * x;
  ll sum = 0;
  for (int i = 1; i <= tim; i++) {
    sum += a[i].sorce;
  }
  ll ans = 0;
  ans = sum;
  for (int i = 1; i <= n; i++) {
    ll now = 0;
    if (res <= a[i].b) 
      now = res * a[i].l;
    else 
      now = a[i].b * a[i].l + (res - a[i].b) * a[i].u;
    if (i <= tim) ans = max(ans, sum - a[i].sorce + now + a[tim + 1].sorce);
    else ans = max(ans, sum + now);
  }
  return ans;
}


int main() {
  scanf("%d%d", &n, &x);
  ll goal = 0, maxx = 0;
  for (int i = 1; i <= n; i++) {
    scanf("%lld%lld%lld", &a[i].b, &a[i].l, &a[i].u);
    maxx += a[i].b;
    goal += a[i].b * a[i].l;
    a[i].sorce = a[i].b * a[i].l + (x - a[i].b) * a[i].u;
  }
  sort(a + 1, a + n + 1);
  ll l = 0, r = n * x;
  while (l < r) {
    ll mid = (l + r) / 2;
    if (check(mid) >= goal) r = mid;
    else l = mid + 1;
  }
  printf("%lld\n", l);
}

