long long n, x, cur = 0;
vector<vector<long long>> tests;

bool check(long long k){

    long long complete = k / x;
    long long other = k - complete * x;

    if(complete >= n) return 1;

    long long cursum = cur;

    for(int i = n - 1; i >= 0; --i){
        if(complete > 0){
            --complete; cursum += tests[i][0];
        } else {
            if(cursum + tests[i][3] * (other - tests[i][1]) + tests[i][1] * tests[i][2] >= 0)
                return 1;
            if(cursum + tests[i][2] * other >= 0)
                return 1;
        }
    }

    return 0;
}

