typedef long long ll;
const int maxn = 1e5 + 100;
struct node {
    ll index, sum;
    ll l, u, b;
} s[maxn];
ll n, x;

ll fun(ll mid) {
    ll a = mid / x;
    ll b = mid % x;
    ll ret = 0;
    for (int i = 0; i < a; i++) {
        ret += s[i].sum;
    }
    if (b == 0) return ret;
    ll sum = 0;
    int index = 0;
    for (int i = 0; i < n; i++) {
        if (b > s[i].b) {
            if ((b - s[i].b) * s[i].u + s[i].b * s[i].l > sum) {
                sum = (b - s[i].b) * s[i].u + s[i].b * s[i].l;
                index = i;
            }
        } else {
            if (b * s[i].l > sum) {
                sum = b * s[i].l;
                index = i;
            }
        }
    }
    ll sum1 = 0;
    for (int i = a; i < n; i++) {
        if (b > s[i].b) sum1 = max(sum1, (b - s[i].b) * s[i].u + s[i].b * s[i].l);
        else sum1 = max(sum1, b * s[i].l);
    }
    if (index >= a) return ret + sum;
    else return max(ret - s[index].sum + sum + s[a].sum, ret + sum1);
}


bool cmp(node a, node b) {
    return a.sum > b.sum;
}

int main() {
    scanf("%lld %lld", &n, &x);
    ll sum = 0;
    for (int i = 0; i < n; i++) {
        scanf("%lld %lld %lld", &s[i].b, &s[i].l, &s[i].u);
        sum -= s[i].b * s[i].l;
        s[i].sum = s[i].b * s[i].l + s[i].u * (x - s[i].b);
    }
    sort(s, s + n, cmp);
    ll l = 0, r = n * x, mid;
    while (l < r) {
        mid = (l + r) / 2;
        if (fun(mid) + sum >= 0) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    printf("%lld\n", l);
    return 0;
}

