  for (const auto i : rep(0, n)) {
    lim[i] = cost(i, x);
  }
  std::vector<usize> idx(n);
  std::iota(idx.begin(), idx.end(), static_cast<usize>(0));
  std::sort(idx.begin(), idx.end(),
            [&lim](const usize l, const usize r) { return lim[l] > lim[r]; });

  const auto is_ok = [&](u64 s) {
    u64 ret = static_cast<u64>(0);
    u64 temp = static_cast<u64>(0);
    usize q = static_cast<usize>(0);
    while (s >= x) {
      temp += lim[idx[q]];
      s -= x;
      ++q;
