bool isok(ll mid) {
    ll q = mid / x, r = mid % x;
    ll sum = d0;
    rep(i, q) {
        sum -= tests[i].D(0);
        sum += tests[i].D(x);
    }
    rep(i, n) {
        ll s = sum;
        if(i < q) {
            s -= tests[i].D(x);
            s += tests[i].D(r);
            s -= tests[q].D(0);
            s += tests[q].D(x);
        } else {
            s -= tests[i].D(0);
            s += tests[i].D(r);
        }
        if(s >= 0) return true;
    }
    return false;
}

