int N;
ll X;
ll B[MAXN];
ll L[MAXN], U[MAXN];
pair <ll, int> ord[MAXN];

ll ntime (int i, ll v)
{
    if (B[i] * L[i] >= v)
        return (v - 1) / L[i] + 1;
    v -= B[i] * L[i];
    return (v - 1) / U[i] + 1 + B[i];
}

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N >> X;

    ll cscore = 0;
    for (int i = 0; i < N; i++)
    {
        cin >> B[i] >> L[i] >> U[i];
        cscore += B[i] * L[i];
        ord[i] = make_pair (B[i] * L[i] + (X - B[i]) * U[i], i);
    }
    if (cscore == 0)
    {
        cout << "0\n";
        exit(0);
    }

    sort (ord, ord + N);
    reverse (ord, ord + N);

    ll ctot = 0;
    int cv = 0;
    while (ctot < cscore)
    {
        ctot += ord[cv].first;
        cv++;
    }

    ll ans = cv * X;
    for (int i = 0; i < cv; i++)
        ans = min (ans, (cv - 1) * X + ntime (ord[i].second, cscore - (ctot - ord[i].first)));

    cv--;
    ctot -= ord[cv].first;
    for (int i = cv; i < N; i++)
        ans = min (ans, cv * X + ntime (ord[i].second, cscore - ctot));
    cout << ans << "\n";
}

