    for (int i = 0; i < n; i++) {
        pq.push(mp((x-b[i])*u[i]+b[i]*l[i],i));
    }
    vector<bool> ff(1<<17,false);
    LL s=0,t=0;
    for (int i = 0; i < (m+x-1LL)/x; i++) {
        P p=pq.top();pq.pop();
        if(m%x!=0&&i==(m+x-1LL)/x-1LL){
            int nx = p.sc;
            LL e = m%x;
            if(e>=b[nx]){
                s+=e*u[nx];
                t+=b[nx]*u[nx];
                ff[nx]=true;
            }
            else{
                s+=e*l[nx];
                t+=b[nx]*l[nx];
                ff[nx]=true;
            }
        }
        else{
            int nx = p.sc;
            s+=x*u[nx];
            t+=b[nx]*u[nx];
            ff[nx]=true;
        }
    }
    for (int i = 0; i < n; i++) {
        if(ff[i]) continue;
        t+=l[i]*b[i];
    }
    return s>=t;
}


