int N, X;

struct node
{
	int b;
	int l;
	int u;
	node(int v1, int v2, int v3) : b(v1), l(v2), u(v3) {}
	node() {}
	bool operator<(const node r) const {
		return u * (X - b) - l * b > r.u * (X - r.b) - r.l * r.b;
	}
	bool operator>(const node r) const {
		return r < *this;
	}
	bool operator>=(const node r) const {
		return !(*this < r);
	}
	bool operator<=(const node r) const {
		return !(r < *this);
	}
	bool operator==(const node r) const {
		return !(r < *this) && !(*this < r);
	}
	bool operator!=(const node r) const {
		return (r < *this) || (*this < r);
	}
	int calcma() {
		return u * (X - b);
	}
};

vector<node> A;
int res = 1e18;

int isok(int x)
{
	int hi = 0;
	rep(i, x) {
		hi += A[i].calcma();
	}
	reps(i, x, N) {
		hi -= A[i].l * A[i].b;
	}
	if(hi >= 0) {
		chmin(res, x * X);
		return true;
	}
	hi = -hi;
	int mi = 1e9;
	reps(i, x, N) {
		int t = hi - A[i].l * A[i].b + A[i].u * A[i].b;
		t = (t + A[i].u - 1) / A[i].u;
		if (t <= X) {
			chmin(mi, t);
		}
		t = hi;
		t = (t + A[i].l - 1) / A[i].l;
		if (t <= A[i].b) {
			chmin(mi, t);
		}
	}
	if (mi == 1e9) return false;
	res = min(res, mi + x * X);
	return true;
}

