bool C(ll t, vector<ll>b, vector<ll>l, vector<ll>u, ll N, ll X){
    // 重要度はl_iかu_iの2択
    // とりあえず満点取った時の効果が大きい順にとっていって端数を調整
    // 満点を取るのに必要な時間は一定
    vector<pair<ll,int>> kouka(N);
    for (int i = 0; i < N; ++i) {
        ll temp = X - b[i];
        temp *= u[i];
        ll bl = b[i] * l[i];
        temp += bl;
        kouka[i] = make_pair(temp, i);
    }
    vector<int> flag(N,0); // 満点を取ったら1にする
    ll score = 0;
    for (int i = 0; i < N; ++i) {
        ll bl = b[i] * l[i];
        score -= bl;
    }
    sort(kouka.begin(), kouka.end(), greater<pair<ll,int>>());
    for (int i = 0; i < N; ++i) {
        if(score + kouka[i].first <= 0){
            t = t-X;
            score += kouka[i].first;
            flag[kouka[i].second] = 1;
        }else{
            break;
        }
    }
    if(t < 0) return false;
    for (int i = 0; i < N; ++i) {
        if(flag[i] == 0){
            ll temp2 = 0;
            if(t > b[i]){
                temp2 = t - b[i];
                temp2 *= u[i];
                ll bl = b[i] * l[i];
                temp2 += bl;
            }else{
                temp2 = t * l[i];
            }
            if(temp2 + score >= 0){
                return true;
            }
        }
    }
    return false;
}

int main() {
    ll N, X;
    cin >> N >> X;
    vector<ll>b(N);
    vector<ll>l(N);
    vector<ll>u(N);
    for (int i = 0; i < N; ++i) {
      cin >> b[i] >> l[i] >> u[i];
    }

    // llで2ぶたん
    ll lb=0, ub = N * X + 1;
    while( ub-lb > 1 ){
        ll mid = (lb+ub)/2;
        if(C(mid, b, l, u, N, X)){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    cout << ub;
    return 0;
}

