    for(ll i = 0; i < N; i++){
        cin >> vec[i].b >> vec[i].l >> vec[i].u;
        vec[i].fx = vec[i].f(X);
        base -= vec[i].b * vec[i].l;
    }
    sort(vec.begin(), vec.end(), greater<test>());
    ll ng = -1, ok = N * X;
    while(ng + 1 < ok){
        ll p = (ng + ok) / 2;
        ll sum = 0, x = p, tmp = 0;
        for(ll i = 0; i < N; i++){
            if(x >= X){
                sum += vec[i].f(X);
                x -= X;
            }
            else{
                tmp = max(tmp, vec[i].f(x));
            }
