struct Subject {
  long long b, l, u;
  long long if_max, if_empty, if_remain;
  Subject() : b(), l(), u() {}
  void init() {
    if_max = (x - b) * u;
    if_empty = -l * b;
  }
  void set_remain(long long rem) {
    if_remain = rem - b;
    if (if_remain >= 0) if_remain *= u;
    else if_remain *= l;
  }
};
signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
