  long long lo = -1, hi = x * n;
  while (hi - lo > 1) {
    long long mid = (lo + hi) / 2;
    long long delta = 0;
    int full = mid / x;
    long long rem = mid % x;
    for (int i = 0; i < n; i++) {
      if (i < full) {
        delta += s[i].if_max;
