      extra = min(extra, (goal + L[order[i]] - 1) / L[order[i]]);
    } else {
      extra = min(extra, (goal - (ll)arr[order[i]] * L[order[i]] + R[order[i]] - 1) / R[order[i]] + arr[order[i]]);
    }
  }
  cout << ans + extra << endl;
  return 0;
}

