int main() {
	ll N, X;
	cin >> N >> X;
	vector<ll> b(N), l(N), u(N);
	for (int i = 0; i < N; ++i) {
		cin >> b[i] >> l[i] >> u[i];
	}

	vector<P> v(N);
	ll sum = 0;
	for (int i = 0; i < N; ++i) {
		v[i] = P(u[i]*(X - b[i]) + l[i]*b[i], i);
		sum -= l[i]*b[i];
	}
	sort(v.rbegin(), v.rend());

	vector<ll> d(N, 0);
	for (int i = 0; i < N; ++i) {
		if (i > 0) { d[i] += d[i - 1]; }
		d[i] += v[i].first;
	}

	vector<set<int>> memo(N);
	for (int i = 0; i < N; ++i) {
		if (i > 0) { memo[i] = memo[i - 1]; }
		memo[i].insert(v[i].second);
	}

	ll res = 1e18;
	for (int i = 0; i < N; ++i) {
		int idx = v[i].second;
		ll ok = N - 1, ng = -1;
		ll add = u[idx]*(X - b[idx]) + l[idx]*b[idx];
		while (ok - ng > 1) {
			int m = (ok + ng) / 2;
			ll tmp = d[m];
			if (m < i) { tmp += add; }

			if (tmp + sum >= 0) { ok = m; }
			else { ng = m; }
		}
		ll base = d[ok];
		ll tmp = (ok + 1) * X;
		if (memo[ok].count(idx) == 1) {
			base -= add;
			tmp -= X;
		}
		ok = X;
		ng = -1;
		while (ok - ng > 1) {
			ll m = (ok + ng) / 2;
			if (m >= b[idx]) { add = u[idx]*(m - b[idx]) + l[idx]*b[idx]; }
			else { add = l[idx]*m; }

			if (base + add + sum >= 0) { ok = m; }
			else { ng = m; }
		}
		tmp += ok;
		res = min(res, tmp);
	}
	cout << res << endl;

	return 0;
}

