	rep(i,n){
		ll b,l,u; cin>>b>>l>>u;
		ll score=b*l+(X-b)*u;
		v.push_back((sub){score,b,l,u});
		aoki+=b*l;
	}
	sort(all(v));
	rui[0]=0;
	for(int i=0;i<n;i++)rui[i+1]=rui[i]+v[i].score;
	ll ans=1e17;
	for(int i=0;i<n;i++){
		ll l=-1,r=n,mid;
		while(l<r-1){
			mid=(l+r)>>1;
			(rangesum(mid,i)<=aoki?l:r)=mid;
		}
		if(v[l].score<v[i].score){
			ll L=i,R=l;
			while(L<R-1){
				mid=(L+R)>>1;
				(v[mid].score==v[i].score?L:R)=mid;
			}
			l=L;
		}
		ll rem=aoki-rangesum(l,i);
		ll cost=(l+1-(i<=l))*X;
		if(rem<=v[i].b*v[i].l+(X-v[i].b)*v[i].u){
			if(rem>=v[i].b*v[i].l){
				rem-=v[i].b*v[i].l;
				cost+=v[i].b;
				cost+=(rem+v[i].u-1)/v[i].u;
			}
			else{
				cost+=(rem+v[i].l-1)/v[i].l;
			}
			chmin(ans,cost);
		}
	}
	cout<<ans<<endl;
}

