    ll hisScore = 0;
    for (int i = 0; i < n; ++i) {
        cin >> b[i] >> l[i] >> u[i];
        hisScore += 1LL * b[i] * l[i];
    }


    ll lo = 0;
    ll hi = 1LL * n * X;
    while (lo < hi) {
        const ll mid = (lo + hi) / 2;

        TopK topK(mid / X);
        for (int i = 0; i < n; ++i)
            topK.insert(1LL * b[i] * l[i] + 1LL * (X - b[i]) * u[i]); // copy/paste

        ll mx = 0;
        for (int i = 0; i < n; ++i) {
            topK.erase(1LL * b[i] * l[i] + 1LL * (X - b[i]) * u[i]); // copy/paste

            const ll here = mid % X < b[i] ? 1LL * (mid % X) * l[i] : 1LL * b[i] * l[i] + 1LL * (mid % X - b[i]) * u[i];
            mx = max(mx, topK.sum + here);
            topK.insert(1LL * b[i] * l[i] + 1LL * (X - b[i]) * u[i]); // copy/paste
        }

        if (mx >= hisScore)
            hi = mid;
        else
            lo = mid + 1;
    }

    cout << lo;

    return 0;
}

