        ll q = X*get<2>(d) - get<0>(d)*(get<2>(d)-get<1>(d));
        if (p > q) return true;
        else return false;
    });

    ll aoki = 0, takahashi = 0, ans = 0;
    for (int i=0;i<N;i++) aoki += get<0>(b[i])*get<1>(b[i]);
