#define SIZE 200010

int N, X;
ll B[SIZE], L[SIZE], U[SIZE];
vector<pair<ll,int> > vec;

bool check(ll x){
  bool used[SIZE] = {};
  ll sum = 0;

  for(int i=0;i<x/X;i++){
    used[vec[i].second] = true;
    sum += vec[i].first;
  }

  for(int i=0;i<N;i++){
    if(!used[i]){
      sum -= B[i] * L[i];
    }
  }

  ll y = 0;

  x = x % X;

  debug(sum);

  for(int i=0;i<N;i++){
    if (used[i]) continue;

    if (x >= B[i]) {
      y = max(y, (ll)B[i] * L[i] + (ll)U[i] * (x - B[i]));
    } else {
      y = max(y, (ll)x * L[i]);
    }
  }

  sum += y;

  return sum >= 0;
}

int main(){

  scanf("%d%d", &N, &X);

  for(int i=0;i<N;i++){
    scanf("%lld%lld%lld", B+i, L+i, U+i);
