  ll l = 0, r = (ll)X * N;

  for(int i=0;i<N;i++){
    ll t = (ll)(X - B[i]) * U[i];
    vec.push_back({t, i});
  }

  sort(vec.begin(), vec.end(), greater<pair<ll,int> >());

  while(l < r){
    ll mid = (l+r)/2;

    if(check(mid)) {
      r = mid;
    } else {
      l = mid + 1;
    }
  }

  cout << l << endl;

  return 0;
}

