const int MAX = 100001;

struct Test {
    int idx;
    long long opp;
    long long lower, upper;
};

struct Increase {
    int which;
    long long value, hours;
    bool operator < (const Increase& r) const {
        if (value * r.hours == r.value * hours)
            return hours > r.hours;
        return value * r.hours < r.value * hours;
    }
};

int n, m;
Test a[MAX], b[MAX];

bool cmp1(Test t1, Test t2) {
    return t1.lower != t2.lower ? t1.lower > t2.lower : t1.upper > t2.upper;
}

bool cmp2(Test t1, Test t2) {
    return t1.upper != t2.upper ? t1.upper > t2.upper : t1.lower > t2.lower;
}

bool eval(long long rem) {
    long long sum = 0;
    for (int i = 0; i < n; i++)
        sum -= a[i].opp * a[i].lower;

    /*
    priority_queue <Increase> q;
    for (int i = 0; i < n; i++) {
        Increase inc;
        inc.type = 0;
        inc.which = i;
        inc.hours = a[i].opp > 0 ? a[i].opp : m;
        inc.value = a[i].opp > 0 ? a[i].lower : a[i].upper;
        q.push(inc);
    }

    while (!q.empty() && rem > 0) {
        Increase inc = q.top(); q.pop();

    }
    */

    priority_queue <Increase> q;
    for (int i = 0; i < n; i++) {
        Increase inc;
        inc.which = i;
        inc.hours = min(rem, (long long)m);
        if (inc.hours <= a[i].opp) {
            inc.value = a[i].lower * inc.hours;
        } else {
            inc.value = (inc.hours - a[i].opp) * a[i].upper + (a[i].opp * a[i].lower);
        }
        q.push(inc);
    }


    while (!q.empty() && rem > 0) {
        Increase inc = q.top(); q.pop();
        if (inc.hours > rem) {
            inc.hours = rem;
            if (inc.hours <= a[inc.which].opp) {
                inc.value = a[inc.which].lower * inc.hours;
            } else {
                inc.value = (inc.hours - a[inc.which].opp) * a[inc.which].upper +
                            (a[inc.which].opp * a[inc.which].lower);
            }
            q.push(inc);
        } else {
            rem -= inc.hours;
            sum += inc.value;
        }
    }
    return sum >= 0;
}

long long solve() {
    for (int i = 0; i < n; i++)
        b[i] = a[i];
    sort(a, a + n, cmp1);
    sort(b, b + n, cmp2);

    long long oppTotal = 0;
    for (int i = 0; i < n; i++)
        oppTotal += a[i].opp;

    long long left = 0, right = oppTotal;
    while (left <= right) {
        long long mid = (left + right) / 2;
        eval(mid) ? right = mid - 1 : left = mid + 1;
    }
    return right + 1;
}

int main(void) {
//	in = fopen("C.in", "rt");

	fscanf(in, "%d %d", &n, &m);
	for (int i = 0; i < n; i++) {
	    a[i].idx = i;
	    fscanf(in, "%lld %lld %lld", &a[i].opp, &a[i].lower, &a[i].upper);
    }

    fprintf(out, "%lld\n", solve());

	return 0;
}

