/**** main function ****/

ll n, x, b[100000], l[100000], u[100000], asum, tsum, ans;
P p[100000];
ll used[100000]; // 0: no, 1: yet, 2: yes

bool check(ll s) {
  ll y = s/x, m = s%x;
  tsum = 0;
  for (ll i = 0; i < y; i++) tsum += p[i].first;
  if (m == 0) return tsum >= asum;
  ll temp = 0;
  for (ll i = y; i < n; i++) {
    ll num = p[i].second;
    temp = max(temp, u[num] * m - (u[num]-l[num])*b[num]);
    temp = max(temp, l[num] * m);
  }
  if (tsum + temp >= asum) return true;
  if (y == n) return false;
  tsum += p[y].first;
  ll temp2 = -INF;
  for (ll i = 0; i < y; i++) {
    ll num = p[i].second;
    temp2 = max(temp2, u[num] * m - (u[num]-l[num])*b[num] - p[i].first);
    temp2 = max(temp2, l[num] * m - p[i].first);
  }
  return tsum + temp2 >= asum;
}

int main() {
  scanf("%lld%lld", &n, &x);
  for (ll i = 0; i < n; i++) {
    scanf("%lld%lld%lld", &b[i], &l[i], &u[i]);
    p[i] = P(u[i]*x-(u[i]-l[i])*b[i], i);
    asum += l[i] * b[i];
  }
  sort(p, p+n, greater<P>());
  //check(2539);
  printf("%lld\n", binarySearch(check, n*x, 0));
}

