using ii64 = pair<i64, i64>;

struct Study
{
	i64 hour;
	i64 reduce;
	i64 b, l, u;

	bool operator<(const Study& r) const
	{
		return reduce * r.hour < r.reduce* hour;
	}
};

int main()
{
	i64 n, x;
	scanf("%lld %lld", &n, &x);

	vector<Study> study(n + 1);
	i64 need = 0;

	for (int i = 1; i <= n; i++)
	{
		scanf("%lld %lld %lld", &study[i].b, &study[i].l, &study[i].u);
		study[i].hour = x;
		study[i].reduce = study[i].l * study[i].b + study[i].u * (x - study[i].b);
		need += study[i].l * study[i].b;
	}

	sort(study.begin() + 1, study.end());

	vector<i64> reduceSum(n + 2);

	for (int i = 1; i <= n; i++)
		reduceSum[i] += reduceSum[i - 1] + study[i].reduce;

	reduceSum[n + 1] = reduceSum[n];

	i64 hour = 0;
	i64 lo = 0, hi = x * n;

	while (lo <= hi)
	{
		i64 mid = (lo + hi) / 2;
		i64 remain = mid;
		i64 make = 0;
		i64 c = remain / x;
		i64 t = remain % x;

		for (int i = 1; i <= n; i++)
		{
			//i 번째를 cut으로 쓰고, 나머지에서 최대한 큰거 고르기
			i64 now = 0;

			if (t >= study[i].b)
				now += study[i].l * study[i].b + study[i].u * (t - study[i].b);
			else
				now += study[i].l * t;

			if (i >= n - c)
			{
				now += reduceSum[n] - reduceSum[i];
				now += reduceSum[i - 1] - reduceSum[n - c - 1];
			}
			else
			{
				now += reduceSum[n] - reduceSum[n - c];
			}

			make = max(make, now);
		}


		if (make >= need)
		{
			hour = mid;
			hi = mid - 1;
		}
		else
		{
			lo = mid + 1;
		}
	}

	printf("%lld\n", hour);

	return 0;
}

