        }

        sort(a.begin(), a.end(), [](auto& lhs, auto& rhs) {
            return (x - get<0>(lhs)) * get<2>(lhs) < (x - get<0>(rhs)) * get<2>(rhs);
        });

        for (int i = 0; i < n; i++) {
            tie(b[i], l[i], u[i]) = a[i];
        }
