	// Choose the overall biggest
	return (K-a.f)*a.s.s > (K-b.f)*b.s.s;
}

bool mem[MAXN];
ll val[MAXN];
ll offset;

ll ask(ll X){
	ll num_complete = X/K;
	ll leftover = X%K;
	// cout<<num_complete<<'\n';

	if (num_complete >= N)return 1;

	memset(mem,0,sizeof(mem));
	ll cur = 0;

	for (ll i=0;i<num_complete;++i){
		auto x = V[i];
		cur += val[i];
		mem[i] = 1;
	}
	ll extra = val[num_complete];
	// cout<<cur<<' '<<extra<<'\n';
	ll res = -1e18;

	for (ll i=0;i<N;++i){
		auto x = V[i];
		ll of = x.f*x.s.f;
		ll tmp = 0;
		if (mem[i] == 1){
			tmp -= val[i];
			tmp += extra;
		}
		if (leftover > V[i].f){
			tmp += (leftover - x.f) * x.s.s + of;
		}else{
			tmp += leftover * x.s.f;
		}
		res = max(res, tmp);
	}

	cur -= offset;
	return cur+res;
}

