int rk[maxn];

int cmp(int lhs, int rhs)
{
    return s[lhs] > s[rhs];
}

bool vis[maxn];

bool gao(LL score)
{
    for(int i = 0; i < n; i++) vis[i] = 0;
    LL tmp = sum;

    for(int i = 0; i < n && score >= x; i++)
    {
        int id = rk[i];
        score -= x;

        tmp += s[id];
        vis[id] = 1;
    }



    LL mx = 0;

    for(int i = 0; i < n; i++)
    {
        if(vis[i]) continue;

        LL t;
        if(score >= b[i]) t = b[i] * l[i] + (score - b[i]) * r[i];
        else t = score * l[i];
        mx = max(mx, t);
    }

    tmp += mx;

    return tmp >= 0;
}

