int main(){
	std::priority_queue<Node>aaa;
	LL sum=0,ans=0;
	scanf("%d%d",&n,&X);
	for(int i=1;i<=n;++i){
		scanf("%d%d%d",b+i,c[0]+i,c[1]+i);
		sum+=b[i]*1ll*c[0][i],aaa.push(Node(i));
	}
	while("Jumbo AK NOI"){
		Node x=aaa.top();aaa.pop();
		if(x.val>c[0][x.id] && x.cnt*x.val>sum){
			if(b[x.id]*1ll*c[0][x.id]>=sum){x.val=c[0][x.id],aaa.push(x);continue;}
			else {
				int now=(sum+b[x.id]*1ll*(c[1][x.id]-c[0][x.id])+c[1][x.id]-1)/c[1][x.id];
				if(now!=x.cnt){x.val=sum*1.0/now,x.cnt=now;aaa.push(x);continue;}
