struct LazySegmentTree {
private:
	int n;
	vector<int> node, lazy;
	vector<bool> lazyFlag;

public:
	LazySegmentTree(vector<int> v) {
		int sz = (int)v.size();
		n = 1; while (n < sz) n *= 2;
		node.resize(2 * n - 1);
		lazy.resize(2 * n - 1, INT_MAX);
		lazyFlag.resize(2 * n - 1, false);

		for (int i = 0; i<sz; i++) node[i + n - 1] = v[i];
		for (int i = n - 2; i >= 0; i--) node[i] = min(node[i * 2 + 1], node[i * 2 + 2]);
	}

	void lazyEvaluate(int k, int l, int r) {
		if (lazyFlag[k]) {
			node[k] = lazy[k];
			if (r - l > 1) {
				lazy[k * 2 + 1] = lazy[k * 2 + 2] = lazy[k];
				lazyFlag[k * 2 + 1] = lazyFlag[k * 2 + 2] = true;
			}
			lazyFlag[k] = false;
		}
	}

	void update(int a, int b, int x, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		lazyEvaluate(k, l, r);
		if (b <= l || r <= a) return;
		if (a <= l && r <= b) {
			lazy[k] = x;
			lazyFlag[k] = true;
			lazyEvaluate(k, l, r);
		}
		else {
			update(a, b, x, 2 * k + 1, l, (l + r) / 2);
			update(a, b, x, 2 * k + 2, (l + r) / 2, r);
			node[k] = min(node[2 * k + 1], node[2 * k + 2]);
		}
	}

	int find(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		lazyEvaluate(k, l, r);
		if (b <= l || r <= a) return INT_MAX;
		if (a <= l && r <= b) return node[k];
		int vl = find(a, b, 2 * k + 1, l, (l + r) / 2);
		int vr = find(a, b, 2 * k + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
};
signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(16);
	long long n, x;
	cin >> n >> x;
	p sor[100004];
	long long b[100003];
	p weight[100004];
	long long kijun = 0;
	for (int i = 0; i < n; i++) {
		cin >> b[i] >> weight[i].first >> weight[i].second;
		sor[i] = p(weight[i].first*b[i] + (x - b[i])*weight[i].second, i);
		kijun += weight[i].first*b[i];
	}
	sort(sor, sor + n);
	long long ans = 0;
	long long tmp = 0;
	int now;
	for (int i = n - 1; i >= 0; i--) {
		tmp += sor[i].first;
		ans += x;
		if (tmp >= kijun) {
			now = i;
			break;
		}
	}
	long long zz = 0;
	for (int i = n - 1; i >= now; i--) {
		int po = sor[i].second;
		long long z = 0;
		long long tmp2 = tmp;
		if (tmp2 - weight[po].second*(x - b[po]) >= kijun) {
			tmp2 -= weight[po].second*(x - b[po]);
