                best = mul;
                best_idx = i;
                score = offset - (x-get<0>(tests[i]))*get<2>(tests[i]) - mul*get<2>(tests[i]);
            }
        }
        if(score>=0)ok=mid;
 else       ng = mid;
        continue;
        next_ok : ok = mid;
    }

    cout << manten*x + ok << endl;

    return 0;
}
    return 0;
}

