using namespace std;
using ll = long long;

struct P {
    bool operator<(const P &p) const {
        return e > p.e;
    }
    ll e;
    int b, l, u;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, x;
    cin >> n >> x;

    vector<P> p(n);
    ll B = 0;
    for (int i = 0; i < n; i++) {
        int b, l, u;
        cin >> b >> l >> u;

        B += (ll)l * b;
        p[i] = { (ll)l * b + (ll)u * (x - b), b, l, u };
    }
    sort(p.begin(), p.end());

    ll r = 0;
    int i0 = 0;
    for (int i = 0; i < n; i++) {
        ll t = B - p[i].e;
        if (t < 0) break;
        B = t;
        r += x;
        i0 = i + 1;
    }

    //以降は、フルには取らない
    if (B > 0) {
        ll s = x;
        for (int i = i0; i < n; i++) {
            ll t;
            ll y = (ll)p[i].l * p[i].b;
            if (B <= y) {
                t = (B + p[i].l - 1) / p[i].l;
            } else {
                t = (B - y + p[i].u - 1) / p[i].u + p[i].b;
            }
            s = min(s, t);
        }
        for (int i = 0; i < i0; i++) {
            B += p[i].e - p[i0].e;
            ll t;
            ll y = (ll)p[i].l * p[i].b;
            if (B <= y) {
                t = (B + p[i].l - 1) / p[i].l;
            } else {
                t = (B - y + p[i].u - 1) / p[i].u + p[i].b;
            }
            s = min(s, t);
            B -= p[i].e - p[i0].e;
        }
        r += s;
    }

    cout << r << endl;

    //引き分けにするときはどうでもよく、勝つときはuを、負けるときはlを選ぶ
    //青木君が高得点を取るとわかっているテストは捨てるのが普通 しかしlが大きいかもしれない
    //高橋君の点数がb未満のときは1時間勉強する毎にlずつAが増える b以上のときはuずつ増える Xまでしか増やせない
    //X点取ったときの効率を求める X点取るにはX時間の勉強 gainはl*b+u*(X-b)=u*X-b*(u-l) 途中まで取っても効率は上がらない
    //フルに取らない b以下しかとらないならlの大きい順にやればいい 以下はuの領域まで行く必要があるケースを考える
    //bがすごく高いけど、uもすごく魅力的なケースはあるかも lも関係してくる
    //全部は取らないわけだが、長くとるほど効率がよくなる（悪くならない）
    //uまで行くのが2つ以上になるとは思えないが それどころか1つだけになるんじゃ？
    //効率で抜かれたらもう抜き返せないから
    //残りのB以上を得るためにどれか一つを選ぶ
    //全部取るとやりすぎなので、効率の悪い他のテストで全部取るという戦略があるか？いや、メリットがない 勉強時間がXで同じなのでデメリットしかない
    //少しとる効率がすごくいいため全体を取るのは他へゆずるということはあるか？ありそう
    //少しと全体でトレードオフになる 困った とりあえずの解は求まっているのでこれより上を探す
    //フルに取ったやつのどれかを外し、そこから少しだけ取る 答えの上界が求まっているのでフルに取る数が増えることはない
    //

    return 0;
}

