#include <bits/stdc++.h>
#define M 200010
#define PLL pair <ll, ll>
#define x first
#define y second

using namespace std;

typedef long long ll;

int n, X;

ll B[M], L[M], U[M];

struct node {
	ll A, B;
	node() {A = 0, B = 1;}
	node(ll _1, ll _2) {A = _1, B = _2;}
};

ll need = 0;

PLL Pr[M];

ll Sum[M], W[M];

bool cmp(PLL A, PLL B) {return A.x > B.x;}

ll check(ll x, ll forb, ll w) {
	ll fin = 0;
	if(forb <= x) fin = Sum[x + 1] - Pr[forb].x; else fin = Sum[x];
	if(fin > need) return X * x;
	if(fin + Pr[forb].x < need) return 1e18 + x;
	if(fin + L[w] * B[w] >= need) {
		ll res = need - fin;
		return X * x + res / L[w] + (res % L[w] != 0);
	} else {
		ll res = need - fin - L[w] * B[w];
		return X * x + B[w] + res / U[w] + (res % U[w] != 0);
	} 
}

int main() {
	scanf("%d%d", &n, &X);
	for(int i = 1; i <= n; i++) scanf("%lld%lld%lld", &B[i], &L[i], &U[i]), need += B[i] * L[i], Pr[i] = PLL((U[i] * (X - B[i]) + L[i] * B[i]), i);
	sort(Pr + 1, Pr + n + 1, cmp);
	for(int i = 1; i <= n; i++) Sum[i] = Sum[i - 1] + Pr[i].x, W[Pr[i].y] = i;
	ll ans = 1e18;
	for(int i = 1; i <= n; i++) {
		int w = W[i];
		ll l = 0, r = n - 1, nw = 0;
		for(; l <= r; ) {
			int md = (l + r) / 2;
			ll fin = w <= md ? Sum[md + 1] - Pr[w].x : Sum[md];
			if(fin > need) r = md - 1; else nw = md, l = md + 1;
		}
		for(int j = max(nw - 3, 0); j <= min(nw + 3, n - 1); j++)
		ans = min(ans, check(j, w, i));
	}
	printf("%lld\n", ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using ull = unsigned long long;
using ld = long double;
#define REP(NAME, NUM) for (int NAME = 0; NAME < (NUM); ++NAME)
#define BREP(NAME, NUM) for (int NAME = (NUM)-1; NAME >= 0; --NAME)
#define ALL(NAME) (NAME).begin(), (NAME).end()

#define cMOD 1000000007ULL
#define cINF ((1ull<<62)-1)
#define cINFINT ((1<<30)-1)


int main()
{
	ll n,x; cin >> n >> x;
	vector<ll> b(n),l(n),u(n);
	REP(i,n) cin>>b[i]>>l[i]>>u[i];
	vector<pair<ll,ll>> k(n);
	ll sum = 0;
	REP(i,n)
	{
		k[i].first = l[i]*b[i]+u[i]*(x-b[i]);
		k[i].second = i;
		sum += l[i]*b[i];
	}
	sort( ALL(k), greater<pair<ll,ll>>() );

	ll time = 0, score = 0;
	vector<bool> perfect(n,false);
	REP(i,k.size())
	{
		auto idx = k[i].second;
		if( score + k[i].first > sum )
		{
			break;
		}
		time += x;
		score += k[i].first;
		perfect[idx] = true;
	}
	const ll leftScore = sum - score;
	ll min_time = 100000000;
	if(leftScore == 0)
	{
		min_time = 0;
	}
	else
	{
		REP(i,n) if( !perfect[i] )
		{
			ll t;
			if( l[i] * b[i] >= leftScore )
			{
				t = (leftScore-1) / l[i] +1;
			}
			else
			{
				t += b[i];
				auto ss = leftScore - l[i]*b[i];
				t += (ss-1) / u[i] +1;
			}
			min_time = min( min_time, t );
		}
	}
	cout << time+min_time << endl;
	return 0;
}

