bool ok(ll cnt) {
	ll want = cnt / x;
	cnt %= x;
	if(want >= n)
		return true;
	if(want == 0) {
		ll maxi = 0;
		for (int i = 0; i < n; i++)
			if(cnt >= b[i])
				maxi = max(maxi, cnt * r[i] - b[i] * r[i] + b[i] * l[i]);
			else
				maxi = max(maxi, cnt * l[i]);
		return maxi >= enemy;
	}
	vector<ll> vec;
	for (int i = 0; i < n; i++)
		vec.push_back(x * r[i] - b[i] * r[i] + b[i] * l[i]);
	sort(vec.begin(), vec.end(), greater<ll>());
	ll S = 0, maxi = 0;
	for (int i = 0; i < want; i++)
		S += vec[i];
	for (int i = 0; i < n; i++)
		if(x * r[i] - b[i] * r[i] + b[i] * l[i] < vec[want - 1]) {
			if(cnt >= b[i])
				maxi = max(maxi, S + cnt * r[i] - b[i] * r[i] + b[i] * l[i]);
			else
				maxi = max(maxi, S + cnt * l[i]);
		}
		else {
			ll help = S - (x * r[i] - b[i] * r[i] + b[i] * l[i]) + vec[want];
			if(cnt >= b[i])
				maxi = max(maxi, help + cnt * r[i] - b[i] * r[i] + b[i] * l[i]);
			else
				maxi = max(maxi, help + cnt * l[i]);
		}
	return maxi >= enemy;
}

