int n, X;
struct anode{
	int b, l, r;
	anode() {}
	anode(int _b, int _l, int _r):b(_b), l(_l), r(_r) {}
}a[maxn];

inline bool check(ll k) {
	int t1 = k / X;
	int t2 = k % X;
	ll tmp = 0;
	for(int i = 1;i <= t1;i ++) {
		tmp = (ll)tmp + (X - a[i].b) * a[i].r;
	}
	for(int i = t1 + 2;i <= n;i ++) {
		tmp = (ll)tmp - (ll)a[i].b * a[i].l;
	}
	if(t2 > a[t1 + 1].b) tmp = (ll)tmp + (t2 - a[t1 + 1].b) * a[t1 + 1].r;
	else tmp = (ll)tmp - (a[t1 + 1].b - t2) * a[t1 + 1].l;
	return tmp >= 0;
}

inline bool cmp(anode a, anode b) {
	ll t1 = (ll)(X - a.b) * a.r + a.b * a.l;
	ll t2 = (ll)(X - b.b) * b.r + b.b * b.l;
	return t1 > t2;
}

int main() {
	scanf("%d%d", &n, &X);
	for(int i = 1;i <= n;i ++) {
		int x, y, z;
		scanf("%d%d%d", &x, &y, &z);
		a[i] = anode(x,y,z);
	}
	sort(a + 1,a + n + 1,cmp);
	ll L = 0, R = 1LL * X * n, Ans = -1;
	if(DEBUG) check(2540);
	while(L <= R) {
		ll mid = (L + R) >> 1;
		if(check(mid)) R = mid - 1, Ans = mid;
		else L = mid + 1;
	}
	printf("%lld\n", Ans);
	return 0;
}

