int main(void)
{
  LL n,x;
  cin >> n >> x;
  vector<LL> b(n),l(n),u(n);
  REP(i,n) cin >> b[i] >> l[i] >> u[i];
  LL ao = 0;
  REP(i,n) ao += b[i] * l[i];
  vector<pair<LL,LL> > gain;
  REP(i,n) gain.emplace_back(x*u[i]-b[i]*u[i]+b[i]*l[i], i);
  sort(gain.rbegin(),gain.rend());
  LL tmp = ao;
  LL subs = 0;
  while(tmp>gain[subs].first) {
    tmp -= gain[subs].first;
    ++subs;
  }
  LL lst = x;
  FOR(i, subs, n) {
    LL index = gain[i].second;
    lst = min(lst, (tmp-1)/l[index]+1);
    LL ttt = tmp - b[index]*l[index];
    if(ttt >= 0) lst = min(lst, (ttt-1)/u[index]+1+b[index]);
  }
  LL answer = subs*x + lst;
  tmp -= gain[subs].first;
  ++subs;
  LL amari = -tmp;
  LL amat = 0;
  REP(i, subs) {
    LL index = gain[i].second;
    amat = max(amat, amari/u[index]);
  }
  answer = min(answer,subs*x-amat);

  cout << answer << endl;
  return 0;
}

