int used[100000+10];
int counter;

bool isOK(ll m) {
  ++counter;
  ll score1 = 0;
  ll score2 = 0;
  for(int i = 0; m >= X; ++i) {
    score1 += X * us[is[i]];
    m -= X;
    score2 += bs[is[i]] * us[is[i]];
    used[is[i]] = counter;
  }
  REP(i, n) {
    if(used[i] != counter) {
      score2 += bs[i] * ls[i];
    }
  }
  // どこに残りを振るかは全探索しちゃえ
  REP(i, n) {
    if(used[i] != counter) {
      if(m <= bs[i]) {
        score1 += m * ls[i];
        if(score1 >= score2) {
          return true;
        }
        score1 -= m * ls[i];
      } else {
        score2 += bs[i] * (us[i] - ls[i]);
        score1 += m * us[i];
        if(score1 >= score2) {
          return true;
        }
        score2 -= bs[i] * (us[i] - ls[i]);
        score1 -= m * us[i];
      }
    }
  }
  return false;
}

