#include <bits/stdc++.h>
#define f first
#define s second
using namespace std;
using ll = long long;
using ii = pair<int, int>;
constexpr int MN = 1e5+5;

ll N, X, b[MN], l[MN], u[MN];
bitset<MN> used;

bool solve(int M) {
	ll goal = 0;
	for (int i = 0; i < N; ++i) goal += b[i]*l[i];

	priority_queue<ii> pq;
	for (int i = 0; i < N; ++i) pq.emplace(X*u[i]-b[i]*u[i]+b[i]*l[i], i);

	ll sum = 0, cost = 0;
	used.reset();
	for (int i = 0; i < M/X; ++i) {
		sum += pq.top().f;
		cost += X;
		used[pq.top().s] = 1;
		pq.pop();
	}
	for (int i = 0; i < N; ++i) {
		if (used[i]) {
			if (sum-(X*u[i]-b[i]*u[i]+b[i]*l[i])+((M-cost)*u[i]-b[i]*u[i]+b[i]*l[i])+pq.top().f >= goal) return 1;
		}
		else {
			if (sum+(M-cost)*u[i]-b[i]*u[i]+b[i]*l[i] >= goal) return 1;
		}
	}
	return 0;
}

