	for (int i = 0; i < N; ++i) cin >> b[i] >> l[i] >> u[i];

	ll x = 0, y = N*X;
	while (x < y) {
		ll m = (x+y)/2;
		solve(m) ? y = m : x = m+1;
	}
	cout << y;
}

