template<typename T> bool chmin(T &a, const T &b) { return a > b ? a = b, true : false; }
template<typename T> bool chmax(T &a, const T &b) { return a < b ? a = b, true : false; }

const int maxN = 100000 + 233;
int n;
LL X;
LL b[maxN], l[maxN], u[maxN];

LL got(int i, LL t) {
	if(t <= b[i]) return t * l[i];
	else return t * u[i] - (u[i] - l[i]) * b[i];
}

LL check(LL T) {
	vector< pair<LL, int> > vp;
	for(int i = 1; i <= n; ++i)
		vp.emplace_back(got(i, X), i);
	sort(vp.begin(), vp.end());

	int cnt = T / X;
	LL res = T % X;

	if(cnt == n) {
		LL ans = 0;
		for(int i = 1; i <= n; ++i) ans += got(i, X);
		return ans;
	}

	LL base = 0;
	LL mxd = -vp.back().first;
	while(cnt--) {
		base += vp.back().first;
		int i = vp.back().second;
		chmax(mxd, got(i, res) - got(i, X));
		vp.pop_back();
	}
	mxd += vp.back().first;
	while(vp.size()) {
		int i = vp.back().second;
		chmax(mxd, got(i, res));
		vp.pop_back();
	}
	return base + mxd;
}

int main() {
	ios::sync_with_stdio(false);
	cin >> n >> X;
	for(int i = 1; i <= n; ++i) cin >> b[i] >> l[i] >> u[i];
	LL L = 0, R = std::accumulate(b + 1, b + n + 1, 0LL);
	LL sum = 0;
	for(int i = 1; i <= n; ++i) sum += l[i] * b[i];
	while(L < R) {
		LL M = (L + R) >> 1;
		if(check(M) >= sum) R = M;
		else L = M + 1;
	}
	cout << L << endl;
	return 0;
}

