vector<pair<long long, int> > g;


long long get(int i, int ost) {
	long long val = 1LL * (b[i] - ost) * ls[i];
	if (ost >= b[i]) {
		val = -1LL * (ost - b[i]) * u[i];
	}
	return val;
}	

bool check(long long mid) {
	long long ans = 0;
	long long cnt = mid / x;
	for (int i = 0; i < cnt; i++) {
		ans += 1LL * (x - b[g[i].second]) * u[g[i].second];
	}
	long long ost = mid % x;
	long long add = 4e18;
	int pos = -1;
	for (int i = cnt; i < n; i++) {
		long long val = get(g[i].second, ost);
		chkmin(add, val);
		if (add == val) {
			pos = i;
		}
	}
	ans -= add;
	for (int i = cnt; i < n; i++) {
		if (pos != i) {
			ans -= 1LL * b[g[i].second] * ls[g[i].second];
		}
	}
	long long res = ans;
	ans = 0;
	add = 4e18;
	for (int i = 0; i <= cnt; i++) {
		ans += 1LL * (x - b[g[i].second]) * u[g[i].second];
		long long val = get(g[i].second, ost);
		chkmin(add, val + 1LL * (x - b[g[i].second]) * u[g[i].second]);
	}
	ans -= add;
	for (int i = cnt + 1; i < n; i++) {
		ans -= 1LL * b[g[i].second] * ls[g[i].second];
	}
	chkmax(res, ans);
	return res >= 0;
	//score[i] * (cnt - b[i]);
}


