ll n,x;

bool isOK(ll mid, VLL &b, VLL &minN, VLL &maxN){
  // 満点を取れるかずは mid/x
  // テストで高橋くんが満点を取る場合は、maxN(u側)を採用する
  // 高橋くんはなるべくお得なテストで満点を取りたい
  // お得の評価 maxN[i] * ( x - b[i])
  // が多い順に取っていけば良い
  vector<pair<ll,int>> score(n);
  rep(i,n){
    score[i] = make_pair( maxN[i] * (x - b[i]) , i  );
  }
  sort(all(score));
  reverse(all(score));

  ll plus = 0;
  ll minus = 0;
  rep(i,mid/x){
    plus += x * maxN[score[i].second];
    minus -= b[score[i].second] * maxN[score[i].second];
  }

  //これは全て高橋が0点を取った場合のスコア plus2,minus2に入る
  ll minus2 = 0;
  FOR(i,mid/x,n){
    int idx = score[i].second;
    minus2 -= b[idx] * minN[idx];
  }
  ll maxSum = -1e15;
  ll amari = mid % x;
  FOR(i,mid/x,n){
    int idx = score[i].second;
    minus2 += minN[idx] * b[idx];
    if( b[idx] <= amari ){
      // maxを採用する
      maxSum = max((maxN[idx] * amari) + minus2 - maxN[idx] * b[idx] , maxSum);
    }else{
      //minを採用する
      maxSum = max((minN[idx] * amari) + minus2 - minN[idx] * b[idx] , maxSum);
    }
    minus2 -= minN[idx] * b[idx];
  }

  return (((plus + minus + maxSum) >= 0));
}
int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> x;
    VLL b(n), minN(n), maxN(n);
    rep(i,n){
      cin >> b[i] >> minN[i] >> maxN[i];
      // rp.push_back(make_pair( maxN[i] , i ));
    }

    ll right = x * n;
    ll left = 0;
    //cout << "hi" << endl;

    /* どんな二分探索でもここの書き方を変えずにできる！ */
    while (right - left > 1) {
        ll mid = (right + left) / 2LL;
        if (isOK(mid, b, minN, maxN)) right = mid;
        else left = mid;
    }

    cout << right << endl;
    return 0;
}

