const int MX=100100;
int n,i,it,l[MX],u[MX],k[MX],w[MX];
long long m,s,le,ri,h,b[MX],c[MX];
bool cmpc(int i, int j) { return c[i]>c[j]; }
long long solve(int h) {
  long long res=0,z=h%m,cur=0;
  ++it;
  for (i=0; i<h/m; i++) {
    w[k[i]]=it;
    res+=c[k[i]];
  }
  long long nxt=(i>=n)?0:c[k[i]];
  if (z) {
    for (i=0; i<n; i++) if (w[i]!=it)
      cur=max(cur,(z<=b[i])?l[i]*z:(b[i]*l[i]+(z-b[i])*u[i]));
    else
      cur=max(cur,((z<=b[i])?l[i]*z:(b[i]*l[i]+(z-b[i])*u[i]))-c[i]+nxt);
  }
  return res+cur;
}
int main() {
  scanf("%d%lld",&n,&m);
  for (i=0; i<n; i++) {
    scanf("%lld%d%d",&b[i],&l[i],&u[i]);
    s+=b[i]*l[i];
    c[i]=(m-b[i])*u[i]+b[i]*l[i];
    ri+=b[i];
    k[i]=i;
  }
  if (s==0) { puts("0"); return 0; }
  sort(k,k+n,cmpc);
  while (le<ri) {
    h=(le+ri)/2;
    long long lll=solve(h);
    if (lll>=s) ri=h; else le=h+1;
  }
  printf("%lld\n",ri);
  return 0;
}

