bool ch(int d){
	if(d==0)return 0;
	if(d==n*X)return 1;
		int wa=0;

	if(d%X==0){

		for(int i=0;i<d/X;i++){
			wa+=p[i];
		}
		for(int i=d/X;i<n;i++){
			wa+=q[i];
		}

		return wa>=0;
	}


	int defo=0;

	int pp=d/X;
	int qq=n-1-pp;

	for(int i=0;i<=pp;i++)defo+=p[i];
	for(int i=n-1;i>=n-(qq+1);i--)defo+=q[i];

	int sa=d%X;



	for(int i=0;i<n;i++){
		int wa=0;
		if(sa>b[i])wa=r[i]*(sa-b[i]);
		else wa=l[i]*(sa-b[i]);

		wa+=defo;

		if(i<=pp){
			wa-=p[i];
			wa-=q[pp];
		}
		else{
			wa-=p[pp];
			wa-=q[i];
		}
		if(wa>=0)return 1;
	}
	return 0;

}

