ll D;
vector<pll> Sum;
vector<bool> used;

bool criterion(ll k) {
    used.assign(N, false);
    ll res = 0;
    ll q = k / X, r = k % X;

    rep(i, q) {
        res += Sum[i].F;
        used[Sum[i].S] = true;
    }

    ll num = 0;
    rep(i, N) {
        ll tmp = (r <= b[i] ? l[i] * r :
                  l[i] * b[i] + u[i] * (r - b[i]));
        if(used[i]){
            tmp += Sum[q].F - Sum[i].F;
        }
        chmax(num, tmp);
    }

    res += num;

    return res >= D;
}

