{
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout << fixed << setprecision(20);
  INT(n); INT(X);
  vector<ll> b(n), l(n), u(n); rep(i, n)cin >> b[i] >> l[i] >> u[i];
  vector<int> c(n); rep(i, n)c[i] = i;
  sort(all(c), [&](int i, int j){
      if(u[i] + l[i] != u[j] + l[j])return u[i] + l[i] > u[j] + l[j];
      return l[i] > l[j];
      });
  ll sum = 0; rep(i, n)sum += b[i];
  ll res = linf;
  vector<ll> g(n + 1, 0); rep(i, n)g[i] = u[c[i]] * (X - b[c[i]]);
  vector<ll> lo(n + 1, 0); rep(i, n)lo[i] = l[c[i]] * (- b[c[i]]);
  vector<ll> gs(n + 1, 0); rep(i, n)gs[i] = X - b[c[i]];
  vector<ll> los(n + 1, 0); rep(i, n)los[i] = (- b[c[i]]);
  FOR(i, 1, n){
    g[i] += g[i-1];
    gs[i] += gs[i-1];
  }
  for(int i = n - 2; i >= 0; i--){
    lo[i] += lo[i+1];
    los[i] += los[i+1];
  }
  for(int i = 0; i < n; i++){
    ll ans = g[i] + lo[i+1];
    ll num = gs[i] + los[i+1] + sum;
    if(ans >= 0){
      int j = i;
      ll tmp = min(X - b[c[j]], ans / u[c[j]]);
      ans -= tmp * u[c[j]];
      num -= tmp;
      if(ans >= 0)res = min(res, num);
    }else{
      int j = i + 1;
      if(j < n){
        ll tmp = min(b[c[j]], (-ans + l[c[j]] - 1) / l[c[j]]);
        ans += tmp * l[c[j]];
        num += tmp;
        if(ans >= 0)res = min(res, num);
      }
    }
  }
  cout << res << endl;
  return 0;
}

