int32_t main() {
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout << fixed << setprecision(11);
  cerr << fixed << setprecision(6);

  int n, x;
  cin >> n >> x;

  vi bi(n), li(n), ui(n);
  for (int i = 0; i < n; ++i) {
    cin >> bi[i] >> li[i] >> ui[i];
  }

  vector<ll> score_inc(n);
  vector<ll> score(n);
  for (int i = 0; i < n; ++i) {
    score[i] = (ll)ui[i] * (x - bi[i]);
    score_inc[i] = (ll)ui[i] * x - (ll)(ui[i] - li[i]) * bi[i];
  }
  vector<int> order(n);
  iota(ALL(order), 0);
  sort(ALL(order), [&](int lhs, int rhs) {
        return score_inc[lhs] > score_inc[rhs];
        //return score[lhs] > score[rhs];
      });

  debug(score_inc, order);

  auto CanWin = [&](ll tm) {
    const int num_taken = min<ll>(n, tm / x);
    ll tot_score = 0;
    vector<bool> is_taken(n);
    for (int i = 0; i < num_taken; ++i) {
      const int v = order[i];
      is_taken[v] = true;
      tot_score += score[v];
    }
    //if (tot_score >= 0) { return true; }
    ll next_taken = num_taken < n ? score_inc[order[num_taken]] : 0ll;
    debug(tm, tot_score, next_taken);

    int rem_tm = tm % x;
    ll best_diff = 0;
    for (int i = 0; i < n; ++i) {
      const ll start = (ll)li[i] * (-bi[i]);
      ll coef = (rem_tm >= bi[i]) ? ui[i] : li[i];
      ll best = coef * (rem_tm - bi[i]);
      debug(i, best, score_inc[i], next_taken);
      if (is_taken[i]) {
        best -= score_inc[i];
        best += next_taken;
      } else {
        tot_score += start;
      }
      maxi(best_diff, best - start);
    }
    debug(tot_score, best_diff);

    tot_score += best_diff;
    return tot_score >= 0;
  };

  ll min_x = -1, max_x = 1e12;

  while (max_x - min_x > 1) {
    auto mid_x = (min_x + max_x) / 2;
    if (CanWin(mid_x)) {
      max_x = mid_x;
    } else {
      min_x = mid_x;
    }
  }

  cout << max_x << "\n";
}

