bool judge(ll lim){
  vector<int> used(N,0);


  ll aoki=0;
  ll taka=0;
  for(int i=0;i<N;i++){
    aoki+=L[i]*B[i];
  }

  ll opnum=lim;
  int uvnum=0;

  for(int i=0;i<N;i++){
      //int now=uv[i].second;
      int now=vv[i].second;
      if(opnum>=X){
          used[now]=1;
          taka+=R[now]*X;
          aoki-=L[now]*B[now];
          aoki+=R[now]*B[now];
          opnum-=X;
      }else{
          uvnum=i;
          break;
      }
  }

  for(int i=0;i<N;i++){
      ll t=taka,a=aoki;
      if(used[i]){
          t-=R[i]*X;
          a+=L[i]*B[i];
          a-=R[i]*B[i];

          if(opnum<=B[i]){
              t+=opnum*L[i];
          }else{
              t+=R[i]*(opnum-B[i])+L[i]*B[i];
          }

          int now=vv[uvnum].second;
          t+=R[now]*X;
          a-=L[now]*B[now];
          a+=R[now]*B[now];
      }else{
          if(opnum<=B[i]){
              t+=opnum*L[i];
          }else{
              t+=R[i]*(opnum-B[i])+L[i]*B[i];
          }
      }
      if(t>=a) return true;
  }

  if(taka>=aoki) return true;
  else return false;
}

