        return 0;
    }

    for(int i=0; i<N; i++){
        v[i] = make_tuple(u[i]*X-(u[i]-l[i])*b[i], b[i], l[i], u[i]);
    }
    sort(v.begin(), v.end());

    ll ub = N*X;
    ll lb = 0;
    while(ub - lb > 1){
        ll mid = (lb + ub) / 2;
        if(C(mid)) ub = mid;
        else lb = mid;
    }
    cout << ub << endl;
    return 0;
}

