const int maxn = 100100;
struct E {
  ll b, l, u;

  ll delta(ll x) const {
    return calc(x) - calc(0);
  }

  ll calc(ll a) const {
    return (a >= b ? u : l) * (a - b);
  }
};
E a[maxn];
ll prx[maxn];
ll pr0[maxn];
ll x;
int n;

bool operator<(const E& e1, const E& e2) {
  return e1.delta(x) > e2.delta(x);
}

ll calc_except(int l, int r, int id, ll* pr) {
  ll res = pr[r] - pr[l];
  if (l <= id && id < r) {
    res -= pr[id + 1] - pr[id];
  }
  return res;
}

ll calc(int id, ll C) {
  ll cnt = C / x;
  ll rem = C % x;
  int bd = id >= cnt ? cnt : cnt + 1;
  ll score = calc_except(0, bd, id, prx) + calc_except(bd, n, id, pr0) + a[id].calc(rem);
  return score;
}

