long long N, X;
long long L[1<20], R[1<<20], B[1<<20], csum[1<<20];

long long min_score = 0;
vector<pair<long long, int> > v;

bool possible(long long num_study_hrs) {

  if(num_study_hrs == 0) {return (min_score >= 0);}

  long long num_complete = num_study_hrs / X;
  long long partial = num_study_hrs % X;

  if(partial == 0) {return ((csum[num_complete-1] + min_score) >= 0);}

  for(int i = 0; i < N;i++) {
    long long tsr = 0;

    if(partial <= B[v[i].second]) {
      tsr = partial*L[v[i].second];
    } else {
      tsr = B[v[i].second]*L[v[i].second]
               + (partial-B[v[i].second])*R[v[i].second];
    }

    if(num_complete != 0) {
      if(i < num_complete) {
        tsr = csum[num_complete] - v[i].first + tsr;
      } else {
        tsr = csum[num_complete-1]  + tsr;
      }
    }

    if((tsr + min_score) >= 0) {
      return true;
    }
  }

  return false;
}

