  while(lo < hi) {
    mid = (lo + hi) / 2;
    if(possible(mid)) {hi = mid;/*cout<<mid<<endl;*/}
    else {lo = mid + 1;}
  }

  cout << lo; // << v[0].first <<" "<<v[1].first<<endl;

  return 0;
}

