int N, X;

bool check(LL ans, LL sumB) {
     vector<pll> cand;
     for (int i = 0; i < N; i++) {
         LL tmp = (LL)(X - b[i]) * u[i] + (LL)b[i] * l[i];
         cand.push_back(make_pair(tmp, i));
     }
     sort(cand.rbegin(), cand.rend());
     LL full = ans / X, rmd = ans % X;
     if (full >= N) return true;

     LL sumA = 0, sum_full = 0;
     for (int i = 0; i < full; i++) {
         sum_full += cand[i].first;
     }
     for (int i = 0; i < N; i++) {
     	 int idx = cand[i].second;
         LL pt1 = (LL)(X - b[idx]) * u[idx] + (LL)b[idx] * l[idx];
         LL cur_sum = sum_full;
         if (i < full) cur_sum = cur_sum - pt1 + cand[full].first;
         LL base = min((LL)b[idx], rmd);
         LL exd = (rmd - b[idx]);
         if (exd <= 0) exd = 0;
         cur_sum += base * l[idx] + exd * u[idx];
         sumA = max(sumA, cur_sum);
	 }
     //printf("ans = %lld sumA = %lld sumB = %lld\n", ans, sumA, sumB);
     return sumA >= sumB;
}

