        if (s[i] >= 0) {
            int k = lower_bound(s, s+i, - l[j]*b[j] - u[j] * (x - b[j])) - s;
            if (s[k] + l[j] * b[j] >= 0) {
                add = b[j] + (- s[k] + l[j] - 1) / l[j];
