const int INF = 1e9;
const ll MOD = 1e9 + 7;

const int MAXN = 2e5 + 5;

struct triple {
	ll b, r, l;
} tt[MAXN];

ll x;

ll eval(const triple &tr) {
	return x * tr.r - tr.b * (tr.r - tr.l);
}

bool operator < (const triple &t1,const triple &t2) {
	return eval(t1) > eval(t2);
}

ll get_val(ll dif, const triple &tr) {
	ll val = INF;
	if (tr.b * tr.l >= dif) {
		val = (dif + tr.l - 1) / tr.l;
	} else if (eval(tr) >= dif) {
		ll tmp = dif + tr.b * (tr.r - tr.l);
		val = (tmp + tr.r - 1) / tr.r;
	}
	return val;
}

void solve(){
	int n;
	scanf("%d%lld", &n, &x);
	REP(i, 0, n) {
		scanf("%lld%lld%lld", &tt[i].b, &tt[i].l, &tt[i].r);
	}
	sort(tt, tt + n);
	ll cur = 0ll;
	REP(i, 0, n) {
		cur -= tt[i].b * tt[i].l;
	}
	ll ans = 0ll;
	int ind = 0;
	for(; ind < n; ind++) {
		ll dif = eval(tt[ind]);
		if (cur + dif >= 0) {
			break;
		}
		cur += dif;
		ans += x;
	}
	ll mn = INF;
	REP(i, ind, n) {
		ll dif = -cur;
		ll val = get_val(dif, tt[i]);
		mn = min(mn, val);
	}
	ans += mn;

	cur += eval(tt[ind]);
	ll ans2 = (ind + 1) * x;
	REP(i, 0, ind) {
		ll cur2 = cur - eval(tt[i]);
		ll dif = -cur2;
		ll val = get_val(dif, tt[i]);
		ans2 = min(ans2, ind * x + val);
	}
	ans = min(ans, ans2);

	cout << ans << endl;
}   

