const int maxn = 1e5 + 5;
int b[maxn], l[maxn], u[maxn];

int main() {
    int n, x; scanf("%d%d", &n, &x);
    for (int i = 0; i < n; ++i) scanf("%d%d%d", &b[i], &l[i], &u[i]);

    vector<int> v(n);
    iota(v.begin(), v.end(), 0);
    sort(v.begin(), v.end(), [&](int i, int j) {
        return u[i] * 1ll * (x - b[i]) + l[i] * 1ll * b[i] > 
               u[j] * 1ll * (x - b[j]) + l[j] * 1ll * b[j];
    });

    long long sum = 0;
    for (int i = 0; i < n; ++i) sum += l[i] * 1ll * -b[i];
    int z = -1;
    for (int i = 0; i <= n; ++i) {
        if (sum >= 0) {
            z = i;
            break;
        }
        if (i < n) {
            sum += l[v[i]] * 1ll * b[v[i]];
            sum += u[v[i]] * 1ll * (x - b[v[i]]);
        }
    }

    assert(z != -1);
    if (z == 0) {
        puts("0");
        return 0;
    }

    --z;
    sum = 0;
    long long tans = x * 1ll * z;
    for (int i = 0; i < z; ++i) sum += u[v[i]] * 1ll * (x - b[v[i]]);

    long long tsum = 0;
    for (int i = z; i < n; ++i) tsum -= l[v[i]] * 1ll * b[v[i]];

    long long ans = 1e18;
    for (int i = z; i < n; ++i) {
        tsum += l[v[i]] * 1ll * b[v[i]];     
        int p = x + 1;
        for (int d = 20; d >= 0; --d) {
            if (p - (1 << d) >= 0) {
                int q = p - (1 << d);
                long long add = max(u[v[i]] * 1ll * (q - b[v[i]]),
                                    l[v[i]] * 1ll * (q - b[v[i]]));

                if (tsum + add + sum >= 0) p -= (1 << d);
            }
        }
        if (p <= x) 
            ans = min(ans, tans + p);
        tsum -= l[v[i]] * 1ll * b[v[i]];     
    }

    printf("%lld\n", ans);
    return 0;
}

