bool check(int n, long long limit, long long taken) {
    if (1LL * n * x == taken)
        return sum[n] >= limit;
    int r = taken % x, c = taken / x;
    bool found = false;
    for (int i = 1; i <= n; i++)
        if (i <= c)
            found |= sum[c + 1] - v[i].total() + v[i].partial(r) >= limit;
        else
            found |= sum[c] + v[i].partial(r) >= limit;
    return found;
}

int main() {
    //ifstream cin("input.in");
    int n;
    cin >> n >> x;
    long long limit = 0;
    for (int i = 1; i <= n; i++) {
        cin >> v[i].b >> v[i].l >> v[i].u;
        limit += 1LL * v[i].b * v[i].l;
    }
    sort(v + 1, v + n + 1);
    for (int i = 1; i <= n; i++)
        sum[i] = sum[i - 1] + v[i].total();
    long long left = 0, right = 1LL * n * x, answer = 1LL * n * x;
    while (left <= right) {
        long long middle = (left + right) / 2;
        if (check(n, limit, middle)) {
            answer = middle;
            right = middle - 1;
        }
        else
            left = middle + 1;
    }
    cout << answer << "\n";
    return 0;
}

