void fast()
{ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);}

struct Exam {
	ll b, l, u;

	Exam() {

	}

	Exam(ll b, ll l, ll u) {
		this->b = b;
		this->l = l;
		this->u = u;
	}
};

ll n, x, b, l, u, bSum;

ll calculateGain(Exam exam) {
	ll examB = exam.b * exam.u;
	ll examA = x * exam.u;
	ll examLB = exam.b * exam.l;
	return examA - examB + examLB;
}

bool sorter(Exam exam1, Exam exam2) {
	return calculateGain(exam1) > calculateGain(exam2);
}

Exam exams[100001];

bool canWin(ll scores) {
	int idx = 0;
	ll bSumCopy = bSum;
	while (bSumCopy > 0 && scores >= x) {
		scores -= x;
		bSumCopy -= calculateGain(exams[idx]);
		++idx;
	}
	if (bSumCopy <= 0) {
		return true;
	}
	ll bestGain;
	for (int i = idx; i < n; ++i)
	{
		if (scores >= exams[i].b) {
			bestGain = exams[i].u * (scores - exams[i].b) + exams[i].b * exams[i].l;
		} else {
			bestGain = exams[i].l * scores;
		}
		if (bSumCopy - bestGain <= 0) {
			return true;
		}
	}
	return false;
}

ll binSer() {
	ll l = 0;
	ll r = n * x;
	ll mid;
	while (l <= r) {
		mid = (l + r) / 2;
		bool win = canWin(mid);
		if (win) {
			r = mid - 1;
		} else {
			l = mid + 1;
		}
	}
	for (ll i = max(0ll, mid - 1); i <= n * x; ++i)
	{
		if (canWin(i)) {
			return i;
		}
	}
	return 0;
}

int main() {
	fast();
	cin >> n >> x;
	bSum = 0;
	for (int i = 0; i < n; ++i)
	{
		cin >> b >> l >> u;
		exams[i] = Exam(b, l, u);
		bSum += l * b;
	}
	sort(exams, exams + n, sorter);
	cout << binSer() << endl;
}

