long long int BINARY_SEARCH(void) {

	long long int left = -1;
	long long int right = 9999999999999;

	while (right - left > 1) {
		long long int med = (right + left) / 2;
		//cout << "med= " << med << endl;
		if (CHECK(med) == 1) { right = med; }
		else { left = med; }
	}

	return right;
}

