#include <bits/stdc++.h>
using namespace std;
using lint = long long;
using pi = pair<lint, int>;
const int MAXN = 100005;

int n, x;
int b[MAXN], s[MAXN], e[MAXN];

bool trial(lint T){
	lint k = T / x, m = T % x;
	if(k == n) return 1;
	lint taken = 0ll;
	vector<pi> v;
	for(int i=0; i<n; i++){
		lint upCost = 1ll * (x - b[i]) * e[i] + 1ll * b[i] * s[i];
		taken -= 1ll * b[i] * s[i];
		v.emplace_back(upCost, i);
	}
	sort(v.rbegin(), v.rend());
	lint ksum = 0;
	lint kp1sum = 0;
	for(int i=0; i<n; i++){
		if(i < k) ksum += v[i].first;
		if(i <= k) kp1sum += v[i].first;
	}
	for(int i=0; i<n; i++){
		int j = v[i].second;
		if(i <= k){
			lint upV = kp1sum - v[i].first;
			upV += max((m - b[j]) * e[j], (m - b[j]) * s[j]) + 1ll * b[j] * s[j];
			if(upV + taken >= 0ll) return 1;
		}
		else{
			lint upV = ksum;
			upV += max((m - b[j]) * e[j], (m - b[j]) * s[j]);
			upV += 1ll * b[j] * s[j];
			if(upV + taken >= 0ll) return 1;
		}
	}
	return 0;
}

int main(){
	scanf("%d %d",&n,&x);
	for(int i=0; i<n; i++){
		scanf("%d %d %d",&b[i],&s[i],&e[i]);
	}
	lint s = 0, e = 1ll * n * x;
	while(s != e){
		lint m = (s+e)/2;
		if(trial(m)) e = m;
		else s = m+1;
	}
	cout << s << endl;
}

