// Problem Specific Parameter:

ll n, x;
const int limit = 100010;
ll b[limit], l[limit], u[limit];
ll init_val;


bool check(ll k){
	ll ret = init_val;

	vector<int> ord(n);
	iota(begin(ord), end(ord), 0);	

	auto cmp = [&](int i, int j) {
		const ll ci = 1LL * u[i] * (x - b[i]) + 1LL * l[i] * b[i];
		const ll cj = 1LL * u[j] * (x - b[j]) + 1LL * l[j] * b[j];
		return ci < cj;
	};

	sort(begin(ord), end(ord), cmp);

	rrep(i, n){
		const int p = ord[i];
		if(k < x) break;
		k -= x;
		ret += 1LL * u[p] * (x - b[p]) + 1LL * l[p] * b[p];
		ord.pop_back();
	}

	if(k > 0){
		auto cmp2 = [&](int i, int j) {
			const ll ci = 1LL * u[i] * max(k - b[i], 0LL) + 1LL * l[i] * min(k, b[i]);
			const ll cj = 1LL * u[j] * max(k - b[j], 0LL) + 1LL * l[j] * min(k, b[j]);
			return ci < cj;
		};
		sort(begin(ord), end(ord), cmp2);

		const int m = ord.back();
		ret += 1LL * u[m] * max(k - b[m], 0LL) + 1LL * l[m] * min(k, b[m]);
	}

	return (ret >= 0LL);
}

int main(void){
	cin >> n >> x;
	rep(i, n) cin >> b[i] >> l[i] >> u[i];

	init_val = 0LL;
	rep(i, n) init_val -= 1LL * l[i] * b[i];

	ll low = -1LL, high = n * x;

	while(high - low > 1){
		const ll mid = (low + high) / 2LL;
		if(check(mid))
			high = mid;
		else
			low = mid;
	}

	cout << high << endl;
	return 0;
}

