void _main()
{
    ll n; llin(n);
    ll max_a; llin(max_a);
    V<t3> blulist; llinl3(blulist, n);

    bool allmax = true;
    for (auto blu : blulist) {
        ll b = get<0>(blu);
        if (b < max_a) allmax = false;
    }
    if (allmax) {
        cout << max_a * n << endl;
        return;
    }

    ll aim = 0;
    for (auto blu : blulist) {
        ll b = get<0>(blu);
        ll left = get<1>(blu);
        ll right = get<2>(blu);
        aim += b * left;
    }
    debug_printf("---- aim = %lld\n", aim);

    V<t4> incr_blulist;
    rep (i, n) {
        ll b = get<0>(blulist[i]);
        ll left = get<1>(blulist[i]);
        ll right = get<2>(blulist[i]);
        incr_blulist.pb(t4(b * left + (max_a - b) * right, b, left, right));
    }
    sort_reverse(incr_blulist);

    ll base = 0;
    ll end = 0;

    for (auto item : incr_blulist) {
        ll incr = get<0>(item);
        ll b = get<1>(item);
        ll left = get<2>(item);
        ll right = get<3>(item);
        debug_printf("--- base=%lld incr=%lld b=%lld left=%lld right=%lld\n",
                     base, incr, b, left, right);

        if (base + incr <= aim) {
            base += incr;
            end++;
        }
        else break;
    }

    ll min_append = max_a;

    rep (i, n) {
        ll lbase = base;
        if (i < end) {
            lbase -= get<0>(incr_blulist[i]);
            lbase += get<0>(incr_blulist[end]);
        }
        ll incr = get<0>(incr_blulist[i]);
        ll b = get<1>(incr_blulist[i]);
        ll left = get<2>(incr_blulist[i]);
        ll right = get<3>(incr_blulist[i]);

        ll laim = aim - lbase;
        assert(laim >= 0);

        ll floor = 0;
        ll ceil = max_a;
        ll nowpos = (floor + ceil) / 2LL;
        ll append = max_a;
        for ( ; floor <= ceil; nowpos = (floor + ceil) / 2LL) {
            ll lincr = left * min(nowpos, b);
            lincr += right * max(0LL, nowpos - b);
            if (lincr < laim) {
                floor = nowpos + 1LL;
            }
            else {
                ceil = nowpos - 1LL;
                append = min(append, nowpos);
            }
        }

        min_append = min(min_append, append);
    }

    debug_printf("---- ans\n");
    cout << end * max_a + min_append << endl;
}

