typedef long long ll;
typedef pair<ll,ll> P;
ll apoint[100005]={0},lb[100005]={0},rb[100005]={0};
bool used[100005];
int main(){
  ll n,x;
  cin>>n>>x;
  vector<P> vec;
  ll kap=0;
  for(ll i=0;i<n;i++){
    used[i]=false;
    ll b,l,u;
    cin>>b>>l>>u;
    vec.push_back(P(b*l+(x-b)*u,i));
    apoint[i]=b;
    lb[i]=l;
    rb[i]=u;
    kap+=b*l;
  }
  sort(vec.begin(),vec.end(),greater<P>());
  ll mp=0;
  ll pos=0;
  ll ans=0;
  while(1){
    if(vec[pos].first+mp<=kap){
      mp+=vec[pos].first;
      used[vec[pos].second]=true;
      pos++;
      ans+=x;
    }
    else break;
  }
  vector<ll> svec;
  ll delta=kap-mp;
  for(int i=0;i<n;i++){
    if(!used[i]){
      ll sk=(delta+lb[i]-1)/lb[i];
      if(sk>apoint[i]){
        sk=apoint[i];
        sk+=(delta-apoint[i]*lb[i]+rb[i]-1)/rb[i];
      }
      if(sk>x) sk=1e16;
      svec.push_back(sk);
    }
  }
  sort(svec.begin(),svec.end());
  cout<<ans+svec[0]<<endl;
}

