using namespace std;

const int MOD = (ll)1000000000 + 7;
const ll INF = 1e17;
const double pi = acos(-1);
const double EPS = 1e-10;
typedef pair<int, int>P;
const int MAX = 200020;

vector<P>v;

int N, X;
int b[100010], l[100010], u[100010];
bool solve(int k) {
	//勝てる科目数
	int cnt = k / X;
	int rem = k - X * cnt;
	int res = 0;
	REP(i, N) {
		int j = v[i].second;
		//print(j);
		if (i < cnt) {
			res += (X - b[j])*u[j];
		}
		else {
			if (i == cnt) {
				if (rem >= b[i]) {
					res += (rem - b[j])*u[j];
				}
				else {
					res -= (b[j] - rem)*l[j];
				}
			}
			else {
				res -= b[j] * l[j];
			}
		}
	}
	//print(res);
	if (res >= 0) {
		return true;
	}
	else {
		return false;
	}
}
signed main() {
	/*cin.tie(0);
	ios::sync_with_stdio(false);*/
	cin >> N >> X;
	REP(i, N) {
		cin >> b[i] >> l[i] >> u[i];
		int scr = (X - b[i])*u[i];
		v.push_back(P(scr, i));
	}
	VSORT(v); VREVERSE(v);
	int ok = N * X;
	int ng = -1;
	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;

		if (solve(mid)) {
			ok = mid;
			//pe(mid);  print("Yes");
		}
		else {
			ng = mid;
			//pe(mid); print("No");
		}
	}
	print(ok);
}

