signed main() {
	INIT;

	VAR(int, n, x);
	VEC_ROW(int, n, b, l, u);

	auto cost = [&](int i) {
		return u[i] * (x - b[i]) - (-b[i] * l[i]);
	};

	V<int> o(n);
	std::iota(ALL(o), 0);
	std::sort(ALL(o), [&](int li, int ri) {
		return cost(li) > cost(ri);
		});

	int sum = 0;
	REP(i, n) {
		sum -= b[i] * l[i];
	}

	int ans = 0;
	int tsum = sum;
	V<bool> use(n, false);
	REP(i, n) {
		tsum += cost(o[i]);
		ans += x;
		use[o[i]] = true;
		if (tsum >= 0) break;
	}

	int mi = x;
	REP(i, n) {
		if (!use[i]) continue;
		int costi = cost(i);
		int ok = x, ng = 0;
		while (ok - ng > 1) {
			int me = (ok + ng) / 2;
			int c = 0;
			if (b[i] > me) c = l[i] * (me - b[i]);
			else c = u[i] * (me - b[i]);
			if (tsum + (c)-(u[i] * (x - b[i])) >= 0) ok = me;
			else ng = me;
		}
		CHMIN(mi, ok);
	}
	ans -= x - mi;
	OUT(ans)BR;

	return 0;
}

