int main() {
  long long n, x, i, difference = 0, ans = 0, c;
  cin >> n >> x;

  vector<vector<long>> a(n, vector<long>(4));
  for(i = 0; i < n; i++){
    cin >> a.at(i).at(1) >> a.at(i).at(2) >> a.at(i).at(3);
    a.at(i).at(0) = (x - a.at(i).at(1)) * a.at(i).at(3);
