  }

  sort(a.begin(), a.end());
  reverse(a.begin(), a.end());
  i = 0;

  while(difference > 0){
    difference -= a.at(i).at(1) * a.at(i).at(2);
    ans += a.at(i).at(1);

    c = (difference + a.at(i).at(3) - 1) / a.at(i).at(3);
