struct Test {
    int b;
    int l, r;

    int get_sum(int f) {
        assert(0 <= f && f <= x);
        return max((int)0, f - b) * r + min(f, b) * l;
    }

    Test() {}
};

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n >> x;
    vector<Test> a(n);
    int ndl = 0;
    for (auto &t : a) {
        cin >> t.b >> t.l >> t.r;
        ndl += t.b * t.l;
    } 
    cerr << ndl << endl;
    sort(a.rbegin(), a.rend(), [&](Test a, Test b) {
        return a.get_sum(x) < b.get_sum(x);
    });
    auto can = [&](int hv) {
        int ans = 0;
        int len = hv / x;
        int lf = hv % x;
        for (int i = 0; i < len; i++) {
            ans += a[i].get_sum(x);
            if (ans >= ndl) return true;
        }
        int mx = 0;
        for (int i = len; i < n; i++) {
            mx = max(mx, a[i].get_sum(lf));
        }
        return ans + mx >= ndl;
    };
    int l = -1;
    int r = n * x;
    while (r - l > 1) {
        int m = (r + l) >> 1;
        if (can(m)) r = m;
        else l = m;
    }
    cout << r << endl;
}

