using namespace std;

struct Sub {
    lint b, l, r;
    Sub(int b = 0, int l = 0, int r = 0) : b(b), l(l), r(r) {}
};

int main() {
    lint N, X;
    cin >> N >> X;

    vector<Sub> subs(N);
    for (auto& s : subs) {
        cin >> s.b >> s.l >> s.r;
    }

    lint ok = 1LL << 40, ng = -1;
    while (ok - ng > 1) {
        lint mid = (ok + ng) / 2;

        priority_queue<pair<lint, int>> que;
        for (int i = 0; i < N; ++i) {
            auto s = subs[i];
            que.emplace(s.r * (X - s.b) + s.l * s.b, i);
        }

        vector<bool> used(N, false);
        lint K = mid, score = 0;
        while (K >= X && !que.empty()) {
            lint g;
            int i;
            tie(g, i) = que.top();
            que.pop();
            score += subs[i].r * (X - subs[i].b);
            used[i] = true;
            K -= X;
        }

        for (int i = 0; i < N; ++i) {
            if (!used[i]) score -= subs[i].b * subs[i].l;
        }

        bool judge = (score >= 0);
        for (int i = 0; i < N; ++i) {
            if (used[i]) continue;
            if (score + K * subs[i].l >= 0) judge = true;
        }

        // cerr << mid << ":" << used << "," << score << endl;
        (judge ? ok : ng) = mid;
    }

    cout << ok << endl;
    return 0;
}

