int N, X;

struct Test {
    int b;
    int l;
    int u;

    Test(int b, int l, int u) : b(b), l(l), u(u) {}

    int maxGain() const {
        return u * (X - b);
    }

    int loss() const {
        return l * b;
    }

    bool operator< (const Test &a) const {
        return maxGain() + loss() < a.maxGain() + a.loss();
    }
};

vector<Test> tests;

int f(int idx, int left) {
    int ret = X;

    int minU = 10000000;
    rep(i, idx - 1) {
        minU = min(minU, tests[i].u);
    }

    REP(i, idx, N - 1) {
        left -= tests[i].b * tests[i].l;

        int low = -1;
        int high = X;
        int mid = (low + high) / 2;
        while (high - low > 1) {
            int gain = (mid - tests[i].b) * tests[i].l;
            if (gain >= left) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high + 1) / 2;
        }

        int tleft = (mid - tests[i].b) * tests[i].l - left;
        if (tleft > 0) mid -= min(X, tleft / minU);

        ret = min(ret, mid);

        left += tests[i].b * tests[i].l;
    }

    REP(i, idx, N - 1) {
        left -= tests[i].b * tests[i].l;

        int low = -1;
        int high = X;
        int mid = (low + high) / 2;
        while (high - low > 1) {
            int gain = (mid - tests[i].b) * tests[i].u;
            if (gain >= left) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high + 1) / 2;
        }

        int tleft = (mid - tests[i].b) * tests[i].u - left;
        if (tleft > 0) mid -= min(X, tleft / minU);

        ret = min(ret, mid);

        left += tests[i].b * tests[i].l;
    }

    // cerr << " ret:" << ret << endl;
    return ret;
}

signed main() {
    cin >> N >> X;

    rep(i, N) {
        int b, l, u;
        cin >> b >> l >> u;
        tests.push_back(Test(b, l, u));
    }

    sort(all(tests));
    reverse(all(tests));

    //for (auto &test : tests) {
    //    fprintf(stderr, "b:%lld l:%lld u:%lld  gain:%lld loss:%lld \t sum:%lld\n", test.b, test.l, test.u, test.maxGain(), test.loss(), test.maxGain() + test.loss());
    //}

    int left = 0;
    rep(i, N) {
        left += tests[i].loss();
    }

    int ret = 0;
    rep(i, N) {
        if (left <= tests[i].maxGain() + tests[i].loss()) {
            ret += f(i, left);
            break;
        } else {
            left -= tests[i].maxGain() + tests[i].loss();
            ret += X;
        }
    }

    cout << ret << endl;

    return 0;
}

