bool comp(T& l, T& r){
  return (X-l.b)*(l.u) > (X-r.b)*(r.u);
}

int main(void){
  cin >> N >> X;
  vector<T> v(N);
  ll A = 0,B = 0;

  int i;REP(i,N){
    cin >> v[i].b >> v[i].l >> v[i].u;
    B += v[i].b * v[i].l;
  }
  //X取った時にBのとるポイント(b*c)との差が大きい順にソート
