    // cout << behind << endl;
    if(behind==0){
        cout << 0 << endl;
        return 0;
    }

    ll lb=0, ub=N*X;
    while(ub-lb>1){
        ll x = (lb+ub)/2;
        ll q = x/X;
        ll r = x-q*X;
        ll sum = 0;
        for(int i=0; i<N; i++){
            int j=gain[i].second;
            ll sum_q = 0;
            if(q==0){
                sum_q += 0;
            } else if(i < q){
                sum_q += gain_cum[q] - gain[i].first;
            } else {
                sum_q += gain_cum[q-1];
            }
            ll sum_r = 0;
            if(r<=B[j]){
                sum_r += r*L[j];
            } else {
                sum_r += B[j]*L[j]+(r-B[j])*U[j];
            }
            sum = max(sum_q+sum_r, sum);
            // cout << x << " " << i << " " << q << " " << r << " " << sum_q << " " << sum_r << endl;
        }
        if(sum+behind>=0){
            ub = x;
        } else {
            lb = x;
        }
    }

    cout << ub << endl;
    return 0;
}

