const int MAXN = 105000;

int n, x;
int b[MAXN], low[MAXN], up[MAXN];
long long total;

bool can(long long mid) {
  if (mid == 0) {
    return total == 0;
  }

  long long takeX = mid / x;
  long long rem = mid - 1ll * takeX * x;

  vector < pair<long long, int> > v;
  for (int i = 0; i < n; i++) {
    v.push_back({1ll * b[i] * low[i] + 1ll * (x - b[i]) * up[i], i});
  }
  sort(all(v));
  reverse(all(v));

  vector <long long> sum;
  for (int i = 0; i < n; i++) {
    if (i == 0) {
      sum.push_back(v[i].first);
    } else {
      sum.push_back(sum[i - 1] + v[i].first);
    }
  }

  if (rem == 0) {
    return sum[takeX - 1] + total >= 0;
  }

  for (int i = 0; i < n; i++) {
    int idx = v[i].second;
    long long cur = 1ll * min(rem, 1ll * b[idx]) * low[idx];
    if (rem > b[idx]) {
      cur += 1ll * (rem - b[idx]) * up[idx];
    }
    if (takeX) {
      cur += sum[takeX - 1];
      if (i <= takeX - 1) {
        cur -= v[i].first;
        cur += v[takeX].first;
      }
    }
    if (cur + total >= 0) {
      return true;
    }
  }

  return false;
}

int main() { 

  scanf("%d %d", &n, &x);
  for (int i = 0; i < n; i++) {
    scanf("%d %d %d", &b[i], &low[i], &up[i]);
  }

  for (int i = 0; i < n; i++) {
    total -= 1ll * low[i] * b[i];
  }

  long long l = 0, r = 1ll * x * n;
  while (l < r) {
    long long mid = (l + r) / 2;
    if (can(mid)) {
      r = mid;
    } else {
      l = mid + 1;
    }
  }

  cout << l << endl;

  return 0;
}

