        V<T3> blulist;
        llinl3(blulist, n);

        V<T2> sumlist;
        rep (i, n) {
                ll b = blulist[i].t0;
                ll l = blulist[i].t1;
                ll u = blulist[i].t2;
                ll sum = l * b + u * (x - b);
                sumlist.pb({sum, i});
        }
        sort_reverse(sumlist);

        ll border = 0LL;
        rep (i, n) {
                ll b = blulist[i].t0;
                ll l = blulist[i].t1;
                border += l * b;
        }

        ll ans = pow(10LL, 16LL);

        for (ll low = 0LL, high = x * n, hours = (x * n) / 2LL; low <= high;
             hours = (low + high) / 2LL) {

                bool checked[n];
                rep (i, n) checked[i] = false;

                ll score = 0LL;
                ll hours_local = hours;

                for (auto sumi : sumlist) {
                        ll sum = sumi.t0;
                        int i = sumi.t1;
                        if (hours_local - x < 0LL) break;
                        score += sum;
                        hours_local -= x;
                        checked[i] = true;
                }

                ll part_max = 0LL;
                rep (i, n) {
                        if (checked[i]) continue;

                        ll b = blulist[i].t0;
                        ll l = blulist[i].t1;
                        ll u = blulist[i].t2;
                        ll part;

                        if (hours_local <= b) part = l * hours_local;
                        else part = l * b + u * (hours_local - b);

                        part_max = max(part_max, part);
                }

                score += part_max;

                if (score < border) {
                        low = hours + 1LL;
                }
                else {
                        high = hours - 1LL;
                        ans = min(ans, hours);
                }
        }

        cout << ans;

        return 0;
}

