int n, x;

struct node {
  ll b, l, u, sorce;
  friend bool operator < (const node& x, const node& y) {
    if (x.sorce == y.sorce) return 1;
    return x.sorce > y.sorce;
  }
} a[maxn];

ll check(ll t) {
  ll tim = t / x;
  ll res = t - tim * x;
  ll sum = 0;
  for (int i = 1; i <= tim; i++) {
    sum += a[i].sorce;
  }
  ll ans = 0;
  ans = sum;
  for (int i = 1; i <= n; i++) {
    ll now = 0;
    if (res <= a[i].b) 
      now = res * a[i].l;
    else 
      now = a[i].b * a[i].l + (res - a[i].b) * a[i].u;
    if (i <= tim) ans = max(ans, sum - a[i].sorce + now);
    else ans = max(ans, sum + now);
  }
  return ans;
}


