bool check (long long lim) {
    long long dist = 0;
    for (int i = 0; i < n; ++i) dist += 1LL * l[i] * b[i];
    vector<bool> used(n, 0);
    vector< pair<long long, int> > vec;
    for (int i = 0; i < n; ++i) vec.pb( { 1LL * (r[i] - l[i]) * b[i] - 1LL * x * r[i], i } );
    sort(vec.begin(), vec.end() );
    long long lst = lim / x;
    for (int i = 0; i < min( (long long)n, lst); ++i) if (vec[i].fi < 0) {
        used[ vec[i].se ] = 1;
        dist += vec[i].fi;
    }
    vec.clear();
    lim %= x;
    for (int i = 0; i < n; ++i) if (!used[i]) {
