vlong y(int i, int xx) {
    return (vlong)(xx - B[i]) * U[i] + (vlong)B[i] * L[i];
}

bool f(vlong can) {
    int q = can / x;
    sort(ALL(id), [&](int i, int j) {
        return y(i, x) > y(j, x);
    });
    vlong tot = 0;
    FOR(i, 0, n - 1) {
        tot -= (vlong)B[i] * L[i];
    }
    FOR(i, 0, q - 1) {
        tot += y(id[i], x);
