    int rem = can % x;
    if (rem) {
        vlong best = -SQ(inf);
        FOR(i, q, n - 1) {
            vlong now = rem >= B[id[i]] ? y(id[i], rem) : (vlong)rem * L[id[i]];
            xmax(best, now);
        }
        FOR(i, 0, q - 1) {
            vlong now = rem >= B[id[i]] ? y(id[i], rem) : (vlong)rem * L[id[i]];
            now -= y(id[i], x) - y(id[q], x);
            xmax(best, now);
        }
        tot += best;
    }
    return tot >= 0;
}

