    int N, X;
    cin >> N >> X;
    vector<tuple<long long, long long, long long>> blu(N);
    for(int i=0; i<N; ++i){
        cin >> get<0>(blu[i]) >> get<1>(blu[i]) >> get<2>(blu[i]);
    }
    sort(blu.begin(), blu.end(), [&](auto lhs, auto rhs){
        return get<0>(lhs) < get<0>(rhs);
    });
    vector<long long> sum_l(N, 0);
    vector<long long> sum_u(N, 0);
    sum_l[0] = get<0>(blu[0]) * get<1>(blu[0]);
    sum_u[0] = get<0>(blu[0]) * get<2>(blu[0]);
    for(int i=1; i<N; ++i){
        sum_l[i] = sum_l[i-1] + get<0>(blu[i]) * get<1>(blu[i]);
        sum_u[i] = sum_u[i-1] + get<0>(blu[i]) * get<2>(blu[i]);
    }
    int left = 0;
    int right = N;
    long long min_count = LONG_MAX;
    while(left<right){
        int mid = (left+right+1)/2;
        long long b = (mid==0? 0 : sum_u[mid-1]) + (sum_l[N-1] - (mid==0? 0 : sum_l[mid-1]));
        long long count = 0;
        bool possible = false;
        for(int i=mid-1; i>=0; --i){
            long long c = i<mid? get<2>(blu[i]) : get<1>(blu[i]);
            if(X*c>b){
                count += (b+c-1) / c;
                possible = true;
                break;
            }
            b -= X*c;
            count += X;
        }
        if(possible && count<min_count){
            right = mid;
            min_count = count;
        }
        else left = mid;
        cout << left << " " << mid << " " << right << endl;
    }
    cout << left << endl;
    cout << min_count << endl;
}

