        sm += b[i]*l[i];
    }
    vector<pair<pair<ll,ll>,pair<ll,ll> > > v;
    rep(i,n){
        v.push_back(MP(MP(l[i]*b[i]+u[i]*(x-b[i]),b[i]),MP(l[i],u[i])));
    }
    sort(v.begin(),v.end(),greater<pair<pair<ll,ll>,pair<ll,ll> > >());
    ll sk = 0;
    ll sk2 = 0;
    ll k = 0;
    rep(i,n){
        ll val = v[i].first.first;
        if(sk+val==sm){
            cout << x*(k+1) << endl;
            return 0;
        }
        if(sk+val>sm){
            sk2 = sk + val;
            break;
        }else{
            sk += val;
            k++;
        }
    }
    ll mi = inf;
    rep(i,n){
        ll res = x*k;
        ll val = v[i].first.first;
        ll B = v[i].first.second;
