int n, x;
vi B, L, U, id;

vlong y(int i, int xx) {
    return (vlong)(xx - B[i]) * U[i] + (vlong)B[i] * L[i];
}

bool f(vlong can) {
    int q = can / x;
    sort(ALL(id), [&](int i, int j) {
        return y(i, x) > y(j, x);
    });
    vlong tot = 0;
    FOR(i, 0, n - 1) {
        tot -= (vlong)B[i] * L[i];
    }
    FOR(i, 0, q - 1) {
        tot += y(id[i], x);
    }
    int rem = can % x;
    if (rem) {
        vlong best = -SQ(inf);
        FOR(i, q, n - 1) {
            vlong now = rem >= B[id[i]] ? y(id[i], rem) : (vlong)rem * L[id[i]];
            xmax(best, now);
        }
        tot += best;
    }
    return tot >= 0;
}

vlong search(vlong begin, vlong end) {
    while (begin < end) {
        vlong mid = (begin + end) / 2;
        if (f(mid)) {
            end = mid;
        } else {
            begin = mid + 1;
        }
    }
    return end;
}

