typedef long long ll;
const int maxn = 100000 + 5;
int n, X;
struct data
{
	int b, l, u;
	ll val;
	inline void init()
	{
		val = (ll)l * b + (ll)u * (X - b);
	}
	inline ll F(int x)
	{
		if(x <= b) return (ll)x * l;
		else return (ll)l * b + (ll)(x - b) * u;
	}
	inline bool operator < (const data &other) const
	{
		return val < other.val;
	}
} a[maxn];
inline ll judge(ll k)
{
	int q = k / X, r = k % X;
	ll re = 0;
	for(int i = 1; i <= n; ++i)
	{
		ll t = a[i].F(r);
		if(i <= q) t += a[i - 1].val + a[q + 1].val - a[i].val;
		else t += a[q].val;
		re = max(re, t);
	}
	return re;
}
int main()
{
	ll sum = 0;
	read(n), read(X);
	for(int i = 1; i <= n; ++i)
	{
		read(a[i].b), read(a[i].l), read(a[i].u);
		sum += (ll)a[i].b * a[i].l;
		a[i].init();
	}
	sort(a + 1, a + n + 1), reverse(a + 1, a + n + 1);
	for(int i = 2; i <= n; ++i)
	{
		a[i].val += a[i - 1].val;
	}
	ll l = 0, r = n * X, an = -1;
	while(l <= r)
	{
		ll mid = (l + r) >> 1;
		if(judge(mid) < sum) l = mid + 1;
		else r = mid - 1, an = mid;
	}
	printf("%lld\n", an);
	return 0;
}

