namespace Problem {
using namespace std;
template <typename T>
struct BIT {
  vector<T> bit;
  int size;
  BIT(int _size) : bit(vector<T>(_size + 1, 0)), size(_size) {}
  void add(int index, T value) {
    for (int i = index + 1; i <= size; i += (i & -i)) bit[i] += value;
  }
  T sum(int a, int b) {  //sum of[a,b)
    return sum(b) - sum(a);
  }
  T sum(int a) {  // sum of[0,a) = sum of bit[0]~bit[a]
    T ret = 0;
    for (int i = a; i > 0; i -= (i & -i)) ret += bit[i];
    return ret;
  }
};
class Solver {
 public:
  LL n, x;
  vector<LL> b, l, u;
  BIT<LL> bit;
  Solver(LL n, LL x) : n(n), x(x), b(n), l(n), u(n), bit(n + 2){};

  void solve() {
    for (int i = 0; i < n; ++i) {
      cin >> b[i] >> l[i] >> u[i];
    }
    vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
      idx[i] = i;
    }
    sort(idx.begin(), idx.end(), [&](int p, int q) {
      return l[p] * b[p] + u[p] * (x - b[p]) > l[q] * b[q] + u[q] * (x - b[q]);
    });
    LL aoki = 0;
    for (int i = 0; i < n; ++i) {
      aoki += l[i] * b[i];
    }
    for (int i = 0; i < n; ++i) {
      int id = idx[i];
      bit.add(i, calc(id));
    }
    LL ans = LINF;
    for (int i = 0; i < n; ++i) {
      int id = idx[i];
      bit.add(i, -calc(id));
      DBG(i, id, calc(id))
      int lb = bins(aoki - calc(id));
      DBG(lb)
      //int ub = bins(aoki);
      LL tmp = x * (lb + 1) - x * (i <= lb);
      DBG(tmp)
      if (inv(id, aoki - bit.sum(lb + 1)) >= 0) tmp += inv(id, aoki - bit.sum(lb + 1));

      ans = min(ans, tmp);
      DBG(tmp, lb)
      bit.add(i, calc(id));
    }
    cout << ans << endl;
  }
  LL calc(int p) {
    return l[p] * b[p] + u[p] * (x - b[p]);
  }
  int bins(LL x) {
    int lb = -1, ub = n - 1;
    while (ub - lb > 1) {
      int mid = (lb + ub) / 2;
      if (bit.sum(mid + 1) >= x) {
        ub = mid;
      } else {
        lb = mid;
      }
    }
    return ub;
  }
  LL inv(int i, LL x) {
    if (calc(i) < x) return LINF;
    if (l[i] * b[i] >= x) return (x + l[i] - 1) / l[i];
    x -= l[i] * b[i];
    return (x + u[i] - 1) / u[i] + b[i];
  }
};

