      }
      if(r>=b){
        sum += u*(r-b);
      }else{
        sum += l*(r-b);
      }
      isok |= sum>=0;
    }
    if(isok){
      high=mid;
    }else{
      low=mid;
    }
  }
  cout<<high<<endl;
  return 0;
}

