struct Exam {
    long b, l, u, x;
    bool operator<(const Exam& exam) {
        return (x - b) * u + b * l < (exam.x - exam.b) * exam.u + exam.b * exam.l;
    }
};

int main() {
    int n;
    long x;
    cin >> n >> x;
    long b_sum = 0;
    Exam exams[n];
    for (int i = 0; i < n; i++) {
        long b, l, u;
        cin >> b >> l >> u;
        exams[i] = Exam {b, l, u, x};
        b_sum += b;
    }

    long lb = -1, ub = b_sum;
    sort(exams, exams + n);
    while (ub - lb > 1) {
        long mid = (lb + ub) / 2;
        long diff = 0;
        int q = (int) (mid / x);
        long r = mid % x;
        for (int i = 1; i <= q; i++) {
            Exam e = exams[n - i];
            diff += e.u * (x - e.b);
        }
        Exam e = exams[n - q - 1];
        diff += ((r >= e.b) ? e.u : e.l) * (r - e.b);
        for (int i = 0; i < n - q - 1; i++) {
            Exam e = exams[i];
            diff -= e.l * e.b;
        }
        if (diff >= 0) {
            ub = mid;
        } else {
            lb = mid;
        }
