using namespace std;
using ll = long long;
int n,x;
struct Task
{
    ll b,l,r;
    ll merit()const
    {
        return (x-b)*r + b * l;
    }
    ll pure_merit()const
    {
        return (x-b)*r;
    }
    bool operator<(const Task& o)const
    {
        return o.merit()<merit();
    }
};
ll solve(int n,int x,vector<Task> tasks)
{
    ll ret = 0;
    sort(tasks.begin(),tasks.end());
    vector<ll> prefix_sum(n,0);
    prefix_sum[0] = tasks[0].l * tasks[0].b;
    for(int i=1;i<n;++i)
    {
        prefix_sum[i] = prefix_sum[i-1] + tasks[i].l * tasks[i].b;
    }
    ll acc = 0;
    ll rest;
    int p;
    for(int i=0;i<n;++i)
    {
        if(acc + tasks[i].pure_merit() >= prefix_sum[n-1] - prefix_sum[i])
        {
            p = i;
            if(i>0)
                rest = prefix_sum[n-1] - prefix_sum[i-1] - acc;
            else
            {
                rest = prefix_sum[n-1] - acc ;
            }

            break;
        }
        acc += tasks[i].pure_merit();
        ret += x;
    }
    ll min_add = INT_MAX;
    for(int i=p;i<n;++i)
    {
        ll num = rest / tasks[i].l + (rest % tasks[i].l > 0);
        if(num > tasks[i].b)
        {
            ll rest_tmp = rest + (tasks[i].r-tasks[i].l) * tasks[i].b;
            num = rest_tmp / tasks[i].r + (rest_tmp % tasks[i].r > 0);
        }
        min_add = min(min_add, num);
    }
    return ret + min_add;
}
int main()
{
    cin>>n>>x;
    vector<Task> t(n);
    for(int i=0;i<n;++i)
        cin>>t[i].b>>t[i].l>>t[i].r;
    cout<<solve(n,x,t);
}

