  for(int i = 0; i < N; i++) {
    cin >> A[i] >> B[i] >> C[i];
    loss += B[i] * A[i];
  }

  auto get_cost = [&](int idx, int64 sum) {
    int64 add = 0;
    add += B[idx] * min(sum, A[idx]);
    add += C[idx] * max(0LL, sum - A[idx]);
    return add;
  };
  PrioritySumStructure< int64 > tap(1, true);
  vector< int64 > tekitou;
  for(int i = 0; i < N; i++) {
    tap.add_element(get_cost(i, X));
    tekitou.emplace_back(get_cost(i, X));
  }
  sort(tekitou.rbegin(), tekitou.rend());
  int64 ok = -1, ng = -1;
  int64 choku = 0;
  for(int i = 0; i < N; i++) {
    choku += tekitou[i];
    if(choku >= loss) {
      ok = (i + 1) * X;
      break;
    }
  }


  auto check = [&](int64 sum) {
    int64 need = sum / X;
    while(need > tap.k) tap.increment_size();
    while(need < tap.k) tap.decrement_size();
    for(int i = 0; i < N; i++) {
      tap.delete_element(get_cost(i, X));
      bool f = tap.get_sum() + get_cost(i, sum % X) >= loss;
      tap.add_element(get_cost(i, X));
      if(f) return true;
    }
    return false;
  };
  while(ok - ng > 1) {
    auto mid = (ok + ng) / 2;
    if(check(mid)) ok = mid;
    else ng = mid;
  }
  cout << ok << endl;
}

