  ret += min(a.first, h) * a.second.first;
  ret += max(0, h - a.first) * a.second.second;
  return ret;
}

bool can(ll t) {
  ll need = 0;
  for(int i = 0; i < n; i++) {
    need += l[i].first * (ll)l[i].second.first;
  }
  vector<pipii> leftover;
  for(int i = 0; i < n; i++) {
    if(t >= x) {
      need -= gain(l[i], x);
      t -= x;
    }
    else {
      leftover.push_back(l[i]);
    }
  }
  if(t) {
    ll maxInc = 0;
    for(pipii out: leftover) {
      maxInc = max(maxInc, gain(out, t));
    }
    need -= maxInc;
  }
  return need <= 0;
}

bool cmp(pipii a, pipii b) {
  return gain(a, x) > gain(b, x);
}

