		else c[i] = l[i];
	}
	rep(i, n) B += c[i] * b[i];

	sort(c, c + n, greater<int>());

	int t = 0;
	rep(i, n) {
		if (A + c[i] * x >= B) {
			t += (B - A + c[i] - 1) / c[i];
			return t;
		}
		else {
			t += x;
			A += c[i] * x;
		}
	}
	return 1e+18;
}

