const int maxn = 1e5;

int n, X;
int b[maxn], l[maxn], u[maxn];
pair<li, li> p[maxn];

li Good(int m) {
  sort(p, p + n);
  li ans1 = 0, ans2 = 0;
  for (int i = 0; i < n - m; ++i) {
    ans1 = max(ans1, p[i].second);
  }
  for (int i = n - m; i < n; ++i) {
    ans1 += p[i].first;
  }
  if (m < n) {
    li sum = 0, extra = -1e12;
    for (int i = n - m - 1; i < n; ++i) {
      sum += p[i].first;
      extra = max(extra, p[i].second - p[i].first);
    }
    ans2 = sum + extra;
  }
  return max(ans1, ans2);
}

int main(void) {
  scanf("%d%d", &n, &X);
  li target = 0;
  for (int i = 0; i < n; ++i) {
    scanf("%d%d%d", b + i, l + i, u + i);
    target += (li)l[i] * b[i];
  }
  li low = 0, high = (li)n * X + 1;
  while (high - low > 1) {
    li mid = low + high >> 1;
    int whole = (mid - 1) / X, rest = (mid - 1) % X;
    for (int i = 0; i < n; ++i) {
      li p1 = (li)l[i] * b[i] + (li)u[i] * (X - b[i]);
      li p2 = rest <= b[i] ? (li)l[i] * rest            \
        : (li)l[i] * b[i] + (li)u[i] * (rest - b[i]);
      p[i] = {p1, p2};
    }
    if (Good(whole) >= target) {
      high = mid;
    } else {
      low = mid;
    }
  }
  printf("%lld\n", low);
  return 0;
}

