			score += S[p+1] - (X * get<3>(s[i]) - get<1>(s[i]) * (get<3>(s[i]) - get<2>(s[i])));
		}else{
			score += S[p];
		}
		if(score >= Asum) return 1;
  }
  return 0;
}

