            }
            if (pp >= b[ind] && pp <= x) {
                best = min(best, (where + 1) * x + pp);
            }
            continue;
        }
        int le = who - 1;
        int r = n - 1;
        if (pref[r + 1] - pref[who + 1] + total + f[who].first < S) continue;
        while (r - le > 1) {
            int mid = (le + r) / 2;
            if (mid >= who && pref[mid + 1] - pref[who + 1] + total + f[who].first >= S) r = mid;
            else le = mid;
        }
        int where = r;
        ll diff = S - (pref[where + 1] - pref[who + 1] + total) + b[ind] * u[ind] - b[ind] * l[ind];
        ll pp = ((diff + u[ind] - 1) / (u[ind]));
        if (diff < 0) {
            best = min(best, (where) * x + b[ind]);
            continue;
        }
        if (pp >= b[ind] && pp <= x) {
            best = min(best, (where) * x + pp);
        }
    }
    cout << best;
    return 0;
}

