#define T tuple<int, int, int, int>
const int MAX_N = 100000;
int N, X;
T data[MAX_N];
int S[MAX_N + 1];
int threshold = 0;

bool f(int x) {
    int full = min(N - 1, x / X); // いくつfullで選ぶか
    int remain = min(X, x - X * full); // 中途半端に選ぶのはいくつか

    for (int i = 0; i < N; i++) {
        int b = get<1>(data[i]);
        int l = get<2>(data[i]);
        int u = get<3>(data[i]);

        int remain_point = min(b, remain) * l + max(0LL, min(remain - b, X - b)) * u;
        int full_point;
        if (i + 1 > full) {
            full_point = S[full];
        } else {
            full_point = S[i] + (S[full + 1] - S[i + 1]);
        }

        if (remain_point + full_point >= threshold) return true;
    }

    return false;
}

signed main() {
    cin >> N >> X;
    for (int i = 0; i < N; i++) {
        int b, l, u;
        cin >> b >> l >> u;
        int s = b * l + (X - b) * u;
        data[i] = T(s, b, l, u);
        threshold += l * b;
    }
    sort(data, data + N, greater<>());
    for (int i = 0; i < N; i++) {
        S[i+1] = S[i];
        S[i+1] += get<0>(data[i]);
    }

    int lb = 0;
    int ub = X * N;
    while (ub - lb > 1) {
        int mid = (ub + lb) / 2;
        if (f(mid)) ub = mid;
        else lb = mid;
    }

    cout << ub << endl;
    return 0;
}

