    long long X;
    cin>>X;
    vector<long long> b(N), l(N), u(N);
    for (int i=0; i<N; i++)
        cin>>b[i]>>l[i]>>u[i];

    vector<tuple<long long, long long, long long, long long>> V;
    for (int i=0; i<N; i++)
        V.push_back(make_tuple(-(X*u[i]-b[i]*(u[i]-l[i])), b[i], l[i], u[i]));
    sort(V.begin(), V.end());
    for (int i=0; i<N; i++)
    {
        b[i] = get<1>(V[i]);
        l[i] = get<2>(V[i]);
        u[i] = get<3>(V[i]);
    }

    auto f = [&](long long x) -> bool
    {
        for (int i=0; i<N; i++)
        {
            long long imp = x%X>b[i] ? u[i] : l[i];
            long long A = x%X*imp;
            long long B = b[i]*imp;
            int c = 0;
            int j = 0;
            for (j=0; j<N; j++)
                if (j != i)
                {
                    if (c<x/X)
                    {
                        A += X*u[j];
                        B += b[j]*u[j];
                    }
                    else
                        B += b[j]*l[j];
                    c++;
                }
            if (A>=B)
                return true;
        }
        return false;
    };

    long long L = 0;
    long long R = N*X;
    while (R-L>1)
    {
        long long m = (L+R)/2;
        (f(m) ? R : L) = m;
    }
    cout<<L+1<<endl;
}

