ll get(int i, ll k){
    if(i > n) return 0;
    if(k <= op[i].f){
        //cout << "get " << i << " " << k << " " << op[i].s.f*k << "\n";
        return op[i].s.f*k;
    } else{
        //cout << "get " << i << " " << k << " " << op[i].s.f*op[i].f+op[i].s.s*(k-op[i].f) << "\n";
        return op[i].s.f*op[i].f+op[i].s.s*(k-op[i].f);
    }
}

bool calc(ll k){
    //cout << "doing " << k << "\n";
    ll amt = k/x;
    ll res = k%x;
    ll sm = 0;
    ll orz = get(amt+1, x);
    FOR(i, 1, amt){
        ll res = get(i, x);
        sm += res;
    }
    ll mx = 0;
    FOR(i, 1, amt){
        ll cur = sm-get(i, x)+orz + get(i, res);
        mx = max(mx, cur);
    }
    FOR(i, amt+1, n){
        ll cur = sm+get(i, res);
        mx = max(mx, cur);
    }
    //cout << "best ans is " << mx << " with " << amt << " " << res << "\n";
    return mx >= tot;
}

