    vector<ll> b(n);
    vector<ll> l(n),u(n);
    for(int i=0;i<n;i++) cin>>b[i]>>l[i]>>u[i];

    ll dist=0;
    for(int i=0;i<n;i++) dist+=l[i]*b[i];

    vector<int> ids(n);
    iota(ids.begin(),ids.end(),0);
    sort(ids.begin(),ids.end(),[&](int lhs,int rhs){return l[lhs]*b[lhs]+u[lhs]*(x-b[lhs])>l[rhs]*b[rhs]+u[rhs]*(x-b[rhs]);});
    multiset<int> ls;
    multiset<int> us;
    for(int i=0;i<n;i++) ls.insert(l[i]),us.insert(u[i]);
    int z;
    ll res=1e18;
    for(int i=0;i<n;i++){
        auto lv=*ls.begin();
        int id=ids[i];
        if(dist<=lv*x){
            ll t=dist/lv+(int)(dist%lv!=0);
            res=min(res,i*x+t);
        }
        auto it=ls.find(l[id]);
        ls.erase(it);

        ll nexdist=dist-l[id]*b[id]-u[id]*(x-b[id]);
        if(nexdist<=0){
            z=i;
            break;
        }
        dist=nexdist;
    }
    for(int i=z;i<n;i++){
        int id=ids[i];
        ll v=dist-l[id]*b[id]+u[id]*b[id];
        ll y=v/u[id]+(int)(v%u[id]!=0);
        res=min(res,x*z+y);
        v=dist;
        y=v/l[id]+(int)(v%l[id]!=0);
        res=min(res,x*z+y);
    }
    cout<<res<<endl;
    return 0;
}

