ll N, X;
vector<ll> b, l, u;

bool IsOK(ll total)
{
    vector<pair<ll, int>> v;
    rep(i, 0, N)
    {
        v.emplace_back(u[i] * (X - b[i]), i);
    }
    sort(v.begin(), v.end(), greater<pair<ll, int>>());

    const ll xNum = total / X;

    ll score = 0;
    rep(i, 0, N)
    {
        const int idx = v[i].second;

        if (i < xNum)
        {
            score += u[idx] * (X - b[idx]);
        }
        else
        {
            score += l[idx] * (0 - b[idx]);
        }
    }

    const ll remainder = total % X;

    ll best = - N * X;
    rep(i, 0, N)
    {
        const int idx = v[i].second;

        if (i < xNum)
        {
            ll tmp = score - (u[idx] * (X - b[idx]));
            tmp += (remainder > b[idx] ? u[idx] : l[idx]) * (remainder - b[idx]);
            const int idx2 = v[xNum].second;
            tmp -= l[idx2] * (0 - b[idx2]);
            chmax(best, tmp);
        }
        else
        {
            ll tmp = score - (l[idx] * (0 - b[idx]));
            tmp += (remainder > b[idx] ? u[idx] : l[idx]) * (remainder - b[idx]);
            chmax(best, tmp);
        }
    }

    return best >= 0;
}

