        long long lm = m;
        long long gp = 0,ep = 0;
        int g;
        for(i = n-1;i >= 0;i--){
            if(lm >= x){
                lm -= x;
                j = ps[i].second;
                gp += u[j]*x;
                lu[j] = 1;
            }
            if(lm > 0 && lm < x){
                g = ps[i-1].second;
                break;
            }
        }
        for(i = 0;i < n;i++){
            if(lu[i]) ep += b[i]*u[i];
