typedef long long ll;

ll n, x;

struct test {
    ll b, l, u;
    bool operator< (const test &o) const { return (b*l + (x - b)*u) > (o.b*o.l + (x - o.b)*o.u); }
};
vector<test> tests;

bool can(ll hrs) {
    ll score = 0;
    int i = 0;
    for(i = 0; i < n; i++)
        score -= tests[i].b * tests[i].l;
    for(i = 0; i < n; i++) {
        if(hrs < x) break;
        test t = tests[i];
        score += (t.b*t.l + (x - t.b)*t.u);
        hrs -= x;
    }
    ll bestEx = 0;
    for(int j = i; j < n; j++) {
        test t = tests[j];
        ll tmp = ((hrs >= t.b) ? (t.b*t.l + (hrs - t.b)*t.u) : hrs*t.l);
        bestEx = max(tmp, bestEx);
    }
    score += bestEx;
    return score >= 0ll;
}

