#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define N 100005

int b[N],l[N],r[N];
pair<ll,int> in[N];
int ind[N];
ll preSum[N];

ll getValue(int id,int x) {
  if(b[id]<=x) {
    return (ll)b[id]*l[id] + (ll)(x-b[id])*r[id];
  } else {
    return (ll)x*l[id];
  }
}

bool canDoit(ll D,ll m,int x,int n) {
  if(m%x==0) {
    if(D + preSum[m/x]>=0) {
      return true;
    } else {
      return false;
    }
  } else {
    int g = m/x;
    ll sum = preSum[g];
    int rem = m%x;
    for(int i=1;i<=n;++i) {
      ll tmp;
      int id = in[i].second;
      if(i<=g) {
        tmp = sum - in[i].first;
        tmp += getValue(id,rem);
        tmp += in[g+1].first;
      } else {
        tmp = sum + getValue(id,rem);
      }
      if(tmp+D>=0) {
        return true;
      }
    }
    return false;
  }
}

void solve() {
  int n,x;scanf("%d %d ", &n,&x);
  ll D = 0;
  for(int i=1;i<=n;++i) {
    scanf("%d %d %d ", &b[i],&l[i],&r[i]);
    long long ret = (ll)b[i]*l[i] + (ll)(x-b[i])*r[i];
    in[i] = make_pair(ret,i);
    D += -(ll)b[i]*l[i];
  }
  sort(in+1,in+n+1,greater<pair<ll,int> >());
  for(int i=1;i<=n;++i) {
    preSum[i] = preSum[i-1] + in[i].first;
    ind[in[i].second] = i;
  }
  ll l = 0,r = (ll)n*x,mid;
  while(l<r) {
    mid = (l+r)/2;
    if(canDoit(D,mid,x,n)) {
      r = mid;
    } else {
      l = mid+1;
    }
  }
  printf("%lld\n", l);
}

