struct dat {
  long long b, l, u;
  dat(long long _b = 0, long long _l = 0, long long _u = 0)
      : b(_b), l(_l), u(_u) {}
  bool operator<(const dat &r) const {
    return b * l + (x - b) * u > r.b * r.l + (x - r.b) * r.u;
  }
};

long long sum = 0;
vector<dat> v;

long long solve();
bool ch(long long p);

int main() {
  cin >> n >> x;
  v.resize(n);
  for (auto &p : v) {
    cin >> p.b >> p.l >> p.u;
