long long solve() {
  if (!sum) return 0;
  long long lef = 0, righ = n * x;
  while (righ - lef > 1) {
    long long mid = (lef + righ) / 2;
    if (ch(mid))
      righ = mid;
    else
      lef = mid;
  }
  return righ;
}

bool ch(long long p) {
  long long all = p / x, now = sum;
  p %= x;
  for (int i = 0; i < all; ++i) now -= v[i].u * (x - v[i].b) + v[i].l * v[i].b;
  if (now <= 0) return 1;
  for (int i = 0; i < n; ++i) {
    if (i < all) {
      now += v[i].u * (x - v[i].b) + v[i].l * v[i].b;
      now -= v[all].u * (x - v[all].b) + v[all].l * v[all].b;
    }
    now -= v[i].l * min(p, v[i].b) + v[i].u * (p - min(p, v[i].b));
    if (now <= 0) return 1;
    now += v[i].l * min(p, v[i].b) + v[i].u * (p - min(p, v[i].b));
    if (i < all) {
      now -= v[i].u * (x - v[i].b) + v[i].l * v[i].b;
      now += v[all].u * (x - v[all].b) + v[all].l * v[all].b;
    }
  }
  return 0;
}

