    }
    ll tot = 0;
    fr(i, 1, n) {
        ll now = tot - pre[n] + pre[i];
        int lx = -1, rx = X;
        while(rx - lx > 1) {
            int m = (lx + rx) >> 1;
            if(now + p[i].se.fi * 1LL * (m - p[i].fi) >= 0)
                rx = m;
            else
                lx = m;
        }
        if(now + p[i].se.fi * 1LL * (rx - p[i].fi) >= 0) {
            ans = min(ans, (i - 1) * 1LL * X + rx);
        }
        lx = -1, rx = X;
        while(rx - lx > 1) {
            int m = (lx + rx) >> 1;
            if(now + p[i].se.se * 1LL * (m - p[i].fi) >= 0)
