bool comp1(plll& a,plll& b){
  ll ab=a.first,al=a.second.first,au=a.second.second;
  ll bb=b.first,bl=b.second.first,bu=b.second.second;  
  return (X-ab)*au>(X-bb)*bu;
}
bool comp2(plll& a,plll& b){
  ll ab=a.first,al=a.second.first,au=a.second.second;
  ll bb=b.first,bl=b.second.first,bu=b.second.second;  
  return ab*al<bb*bl;
}

bool C(ll mid){
  ll tkhs=0,aok=0;
  rep(i,N){
    ll b=p[i].first,l=p[i].second.first,u=p[i].second.second;
    if(mid>=X){
      tkhs+=X*u;aok+=b*u;
      mid-=X;
    }
    else if(mid!=0){
      if(mid>b){
	tkhs+=mid*u;aok+=b*u;
      }
      else{
	std::sort(p+i,p+N,comp2);
	b=p[i].first;l=p[i].second.first;u=p[i].second.second;                  
	tkhs+=mid*l;aok+=b*l;
      }
      mid=0;
    }
    else{
      aok+=b*l;
    }
  }
  return tkhs>=aok;
}
ll upper(ll l,ll r){//条件を満たす中で最小のものを返す
  ll lb=l-1,ub=r+1;
  while(ub-lb>1){
    std::sort(p,p+N,comp1);
    ll mid=(lb+ub)/2;
    if(C(mid)) ub=mid;
    else lb=mid;
  }
  return ub;
}


