void margesort(long long int a[], int a_len, int left, int right)
{
	int i, j, mid, L, R;

	if (right <= left)
		return;

	mid = (left + right) / 2;
	margesort(a, mid, left, mid);
	margesort(a, a_len - mid, mid + 1, right);

	for (i = left; i <= mid; i++) {
		temp[i] = a[i];
		tempb[i] = b[i];
		templ[i] = l[i];
		tempu[i] = u[i];
	}
	for (i = mid + 1, j = right; i <= right; i++, j--) {
		temp[i] = a[j];
		tempb[i] = b[i];
		templ[i] = l[i];
		tempu[i] = u[i];
	}
	L = left;
	R = right;

	for (i = left; i <= right; i++)
	{
		if (temp[L] <= temp[R])
		{
			a[i] = temp[L];
			b[i] = tempb[L];
			l[i] = templ[L];
			u[i] = tempu[L];
			L++;
		}
		else
		{
			a[i] = temp[R];
			b[i] = tempb[R];
			l[i] = templ[R];
			u[i] = tempu[R];
			R--;
		}
	}
}

