int main() {
    ll N, X;
    cin >> N >> X;

    struct Test {
        ll b, l, r;
    };
    vector<Test> tests(N);
    for (ll i = 0; i < N; i++) {
        cin >> tests[i].b >> tests[i].l >> tests[i].r;
    }
    //sort(tests.begin(), tests.end(), [&](Test& lhs, Test& rhs) {
    //    return (X - lhs.b) * lhs.r + lhs.b * lhs.l >= (X - rhs.b) * rhs.r + rhs.b * rhs.l;
    //});

    struct Element {
        ll type, add, num, index;
        bool operator<(const Element& rhs) const {
            return add < rhs.add;
        }
    };

    ll ok = X * N, ng = -1;
    while (ok != ng + 1) {
        ll mid = (ok + ng) / 2;

        ll a = mid / X;
        ll b = mid % X;

        ll sum = 0;
        priority_queue<Element> pq;

        for (ll i = 0; i < N; i++) {
            if (i < a) {
                sum += (X - tests[i].b) * tests[i].r;
            } else {
                sum -= tests[i].b * tests[i].l;
                pq.push({ 0, tests[i].l, tests[i].b, i });
            }
        }

        while (sum < 0 && b > 0 && !pq.empty()) {
            auto t = pq.top();
            pq.pop();

            ll op_num = min(t.num, b);
            ll max_add = t.add * op_num;
            sum += max_add;
            b -= op_num;
            if (t.type == 0) {
                pq.push({ 1, tests[t.index].r, X - tests[t.index].b, t.index });
            }
        }

        (sum >= 0 ? ok = mid : ng = mid);
    }

    cout << ok << endl;
}

