    for (int n = 1; n <= N; ++n) Sum[n] = Sum[n-1]+S[n-1];
    ll TargetS = 0;
    for (int n = 0; n < N; ++n) {
        TargetS += L[n]*B[n];
    }

    ll l = -1, r = X*N;
    while (r - l > 1) {
        ll m = (l + r) / 2;
        ll Max = 0;

        ll q = m / X;
        ll r2 = m % X;
        for (int n = 0; n < N; ++n) {
            ll Tmp = r2 < B[n] ? r2*L[n] : B[n]*L[n]+(r2-B[n])*U[n];
            Tmp += Sum[q];
            if (Ind[n] < q) {
                Tmp -= S[Ind[n]];
                Tmp += S[q];
            }
            if (Max < Tmp) Max = Tmp;
        }

        if (Max >= TargetS) {
            r = m;
        } else {
            l = m;
        }
    }
    cout << r << endl;

    return 0;
}

