template<typename T> struct binary_indexed_tree {
    int S;
    vector<T> table;

    binary_indexed_tree<T>(int _S = 0) : S(_S) {
        table.resize(S+1);
    }

    // Adds v to the element at index i
    void add(int i, T v) {
        for (i++; i <= S; i += i&-i)
            table[i] = table[i] + v;
    }

    // Returns the sum of the elements at indices [0, i)
    T sum(int i) const {
        T res = T();
        for (; i; i -= i&-i)
            res = res + table[i];
        return res;
    }

    // Returns the sum of the elements at indices [l, r)
    T sum(int l, int r) const {
        return sum(r) - sum(l);
    }

    /*
     * Returns in O(logS) the first i in [0, S] such that comp(sum(i)) is true.
     * Returns -1 if no such i exists.
     * Requires that comp(sum(i)) is non-decreasing in i.
     * The empty prefix is considered to have sum equal to T's default value.
     */
    int lower_bound(const auto& comp) const {
        int inx = 0;
        T cur = T();
        if (comp(cur)) return 0;

        for (int i = 31 - __builtin_clz(S); i >= 0; i--) {
            int nxt = inx + (1 << i);
            if (nxt <= S && !comp(cur + table[nxt])) {
                inx = nxt;
                cur = cur + table[nxt];
            }
        }
        return inx < S ? inx + 1 : -1;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N, X;
    cin >> N >> X;

    ll cur = 0;
    vi b(N), l(N), u(N);
    for (int i = 0; i < N; i++) {
        cin >> b[i] >> l[i] >> u[i];
        cur += ll(l[i]) * b[i];
    }

    vll fval(N);
    vi order(N), index(N);
    for (int i = 0; i < N; i++) {
        fval[i] = l[i] * ll(b[i]) + u[i] * ll(X - b[i]);
        order[i] = i;
    }
    sort(all(order), [&](int i, int j) { return fval[i] > fval[j]; });
    for (int i = 0; i < N; i++) index[order[i]] = i;

    binary_indexed_tree<ll> full(N);
    for (int i = 0; i < N; i++) {
        full.add(i, fval[order[i]]);
    }

    ll ans = X * full.lower_bound([&](ll tot) { return tot >= cur; });

    for (int part = 0; part < N; part++) {
        full.add(index[part], -fval[part]);

        int usef = full.lower_bound([&](ll tot){ return tot + fval[part] >= cur; });

        assert(full.sum(usef) + fval[part] >= cur);
        if (usef) assert(full.sum(usef - 1) + fval[part] < cur);

        ll need = max(0ll, cur - full.sum(usef));
        ll usep = min((need + l[part] - 1) / l[part], ll(b[part]));
        need -= usep * l[part];
        usep += (need + u[part] - 1) / u[part];

        ans = min(ans, usep + ll(X) * (usef - (usef > index[part])));

        full.add(index[part], fval[part]);
    }

    cout << ans << endl;

    return 0;
}

