		v[i].value = v[i].l*v[i].b + v[i].u*(x-v[i].b);
		df -= v[i].b * v[i].l;
	}
	if(!(df && x)){
		cout << 0 << endl;
		return 0;
	}
	sort(v.begin(),v.end());
	ok = x*n; ng = 0ll;
	while(ok-ng>1ll){
		mid = ok+ng;
		mid >>= 1;
		if(judge(mid)){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	cout << ok << endl;
	return 0;
}

