	for(int i = 0; i < N; i++) noben += T[i].L * T[i].B; 
	if(noben == 0){
		cout << 0 << endl; return 0; 
	}
	long long S[100010] = {}; 
	S[0] = T[0].cost; 
	for(int i = 1; i < N; i++) S[i] = S[i-1] + T[i].cost; 
	long long ans = 1e18;
	for(int i = 0; i < N; i++){
		long long time = 0; long long nobenben = noben; 
