i64 f(vector<i64> c, i64 t) {
    i64 res = 0;

    sort(c.rbegin(), c.rend());

    for (int i = 0; i < n; i++) {
        if (t >= x) {
            res += c[i] * x;
            t -= x;
        } else {
            res += c[i] * t;
            t = 0;
        }
    }

    return res;
}

int main() {
    in(n, x);

    b.resize(n);
    l.resize(n);
    u.resize(n);

    for (int i = 0; i < n; i++) {
        in(b[i], l[i], u[i]);
    }

    {
        vector<tuple<i64, i64, i64>> a(n);
        for (int i = 0; i < n; i++) {
            a[i] = make_tuple(b[i], l[i], u[i]);
        }

        sort(a.begin(), a.end(), [](auto& lhs, auto& rhs) {
            return (x - get<0>(lhs)) * get<2>(lhs) + (get<0>(lhs) * get<1>(lhs)) < (x - get<0>(rhs)) * get<2>(rhs) + (get<0>(rhs) * get<1>(rhs));
        });

        for (int i = 0; i < n; i++) {
            tie(b[i], l[i], u[i]) = a[i];
        }
    }

    i64 ng = -1, ok = x * n;

    while(ok - ng > 1) {

        i64 mid = (ng + ok) / 2;

        bool win = false;

        vector<i64> c(n);

        int k = mid / x;
        i64 t = mid - x * k;

        for (int i = 0; i < n; i++) {
            if (i < k) {
                c[n - i - 1] = u[n - i - 1];
            } else {
                c[n - i - 1] = l[n - i - 1];
            }
        } 

        i64 aoki = 0;

        for (int j = 0; j < n; j++) {
            aoki += b[j] * c[j];
        }

        auto taka = f(c, mid);

        if (taka >= aoki) {
            win = true;
        }

        if (win) {
            ok = mid;
        } else {
            ng = mid;
        }
    }

    out(ok);

}

