int b[MAXN] , num[MAXN];
bool ch[MAXN];
ll get(int n1){
	return 1ll * b[n1] * l[n1] + 1ll * (x - b[n1]) * u[n1];
}

bool cmp(int n1 , int n2){
	return get(n1) > get(n2);
}

int main(){
	ios::sync_with_stdio(0);
	cin >> n >> x;
	for(int i = 1 ; i <= n ; ++ i)
		cin >> b[i] >> l[i] >> u[i];
	ll ans = 0 , tmp = 0;
	for(int i = 1 ; i <= n ; ++ i)
		tmp += 1ll * -b[i] * l[i];
	for(int i = 1 ; i <= n ; ++ i)
		num[i] = i;
	sort(num + 1 , num + n + 1 , cmp);
	if(tmp >= 0){
		cout << 0 << endl;
		return 0;
	}
	for(int i = 1 ; i <= n ; ++ i)
		if(tmp + get(num[i]) >= 0){
			int head = 1 , tail = x;
			while(head < tail){
				int mid = (head + tail) >> 1;
				bool flag = 0;
				for(int k = 1 ; k <= n ; ++ k)
					if(!ch[k]){
						ll cur = 0;
						if(mid <= b[k])
							cur = 1ll * mid * l[k];
						else
							cur = 1ll * b[k] * l[k] + 1ll * (mid - b[k]) * u[k];
						if(cur + tmp >= 0){
							flag = 1;
							break;
						}
					}
				if(flag)
					tail = mid;
				else
					head = mid + 1;
			}
			ans += head;
			break;
		}
		else{
			tmp += get(num[i]);
			ans += x;
			ch[num[i]] = 1;
		}
	cout << ans << endl;
	return 0;
}

