struct Subj {
  int64_t b, l, r;

  int64_t GetSum() const {
    return b * 1ll * l + r * 1ll * (x - b);
  }

  int64_t GetSum(int64_t cnt) const {
    if (cnt <= b) {
      return l * cnt;
    } else {
      return l * b + r * (cnt - b);
    }
  }
};
int64_t ans = 1e18;
void RelaxAnswer(int64_t d) {
  ans = min(ans, d);
}

int main() {
  std::ios_base::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n >> x;
