  }
  subj[n].b = 0;
  subj[n].l = 0;
  subj[n].r = 0;
  n++;

  sort(subj.begin(), subj.end(), [](const Subj& lhs, const Subj& rhs) {
      return lhs.GetSum() < rhs.GetSum();
  });
  for (int i = 0; i < n; i++) {
    if (i == 0) {
      sums[i] = subj[i].GetSum();
    } else {
      sums[i] = subj[i].GetSum() + sums[i - 1];
    }
  }
  auto get_on_on = [&](int l, int r) {
    if (l > r) {
      return (int64_t)0;
    }
    int64_t ll = l >= 1 ? sums[l - 1] : 0ll;
    return (int64_t)(sums[r] - ll);
  };
  auto get_on = [&](int l, int id, int64_t val, int r) {
    if (id < l || id > r) {
      return get_on_on(l, r) + val;
    }
    return get_on_on(l, id - 1) + get_on_on(id + 1, r) + val;
  };

  {

    auto can_m = [&](int64_t check_val) {

      for (int i = n - 1; i >= 0; i--) {

        auto i_sum = subj[i].GetSum((check_val % x));
        if (i_sum + cur_sum >= 0) {
          return true;
        }

        int l = 0;
        int r = n - 1;

        auto check_bin = [&](int m) {
          if (get_on(n - 1 - m, i, i_sum, n - 1) + cur_sum >= 0) {
            return true;
          } else {
            return false;
          }
        };

        while (r - l > 1) {
          int m = (l + r) / 2;
          if (check_bin(m)) {
            r = m;
          } else {
            l = m;
          }
        }
        for (int v : {l, r}) {
          if (check_bin(v)) {
            int64_t id_sum = (v + 1) * 1ll * x;
            if (n - v - 1 <= i) {
              id_sum -= (x - (check_val % x));
            }
            if (id_sum <= check_val) {
              return true;
            }
          }
        }
      }
      return false;
    };



    int64_t l = 0;
