struct item {
    long long b, l, r;
    item() = default;
    item(int b, int l, int r) : b(b), l(l), r(r) { }
};

int n;
long long X;
item f[N];

bool read() {
    if (!(cin >> n >> X))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> f[i].b >> f[i].l >> f[i].r;

    return true;
}

bool check(long long m) {
    if (m == n * X)
        return true;

    auto w = m / X;
    auto init = 0ll;

    auto add = [](long long a, item t) { return (a - t.b) * (a < t.b ? t.l : t.r); };

    for (int i = 0; i < n; ++i)
        init += add((i < w ? X : 0ll), f[i]);

    auto res = init;

    for (int i = 0; i < n; ++i) {
        auto cur = init;

        if (i < w) {
            cur -= add(X, f[i]) + add(0, f[w]);
            cur += add(m % X, f[i]) + add(X, f[w]);
        } else {
            cur -= add(0, f[i]);
            cur += add(m % X, f[i]);
        }

        res = max(res, cur);
    }

    return res >= 0;
}

void solve() {
    sort(f, f + n, [](const item& a, const item& b) {
