bool check(ll S)
{
    int k = S / X;
    ll sum = 0;
    for (int i = 0; i < k; ++i)
        sum += b[i] * 1LL * (X - y[i]);
    for (int i = k; i < n; ++i)
        sum -= a[i] * 1LL * y[i];

    int R = S % X;
    if (R == 0)
        return sum >= 0;

    ll mx = -1;
    for (int i = 0; i < k; ++i)
    {
        ll add;
        if (R > y[i])
            add = b[i] * 1LL * (R - y[i]);
        else
            add = a[i] * 1LL * (R - y[i]);
        mx = max(mx, sum - b[i] * 1LL * (X - y[i]) + add + b[k + 1] * 1LL * (X - y[k + 1]) + a[k + 1] * 1LL * y[k + 1]);
    }
    for (int i = k; i < n; ++i)
    {
        ll add;
        if (R > y[i])
            add = b[i] * 1LL * (R - y[i]);
        else
            add = a[i] * 1LL * (R - y[i]);
        mx = max(mx, sum + a[i] * 1LL * y[i] + add);
    }

    return mx >= 0;
}

ll calc(pair<pii,int> a)
{
    return a.second * 1LL * (a.first.first - a.first.second) + a.first.second * 1LL * X;
}

bool cmp(pair<pii,int> a, pair<pii,int> b)
{
    return calc(a) < calc(b);
}

