ll n, x;
struct T{
    ll b, l, r;
    ll can_win;
};
vector<T> a;
bool comp(T a, T b)
{
    return a.can_win > b.can_win;
}

bool can(ll t)
{
    ll full = t / x;
    ll more = t % x;
    for (int i = 0; i < a.size(); i++)
        a[i].can_win = (x - a[i].b) * a[i].r;
    sort(a.begin(), a.end(), comp);
    ll win = 0;
    for (int i = 0; i < full; i++)
    {
        win += a[i].can_win;
    }
    //cout << 99 << endl;
    ll he = 0;
    for (int i = full; i < n; i++)
    {
        he += a[i].l * a[i].b;
    }
    for (int i = full; i < n; i++)
    {
        he += (a[i].r - a[i].l) * a[i].b;
        win += a[i].r * more;
        if (win >= he)
            return 1;
        win -= a[i].r * more;
        he -= (a[i].r - a[i].l) * a[i].b;
    }
    return 0;
}

