		temp2.push_back(temp2.back() + a[i].l * (-a[i].b));

	temp.erase(temp.begin());
	temp2.erase(temp2.begin());

	auto get = [&](vector<ll> &q, int i, int j)
	{
		if (i > j) return 0LL;
		if (i == 0) return q[j];
		return q[j] - q[i-1];
	};

	ll l = 0, r = x*n;
	while (l < r)
	{
		ll m = (l+r) >> 1;

