    for (int i = 0; i < N; i++)
        full[i] = make_pair(L[i] * B[i] + (X - B[i]) * U[i], i);
    sort(full, full + N);
    reverse(full, full + N);

    ll cumsum[N];
    cumsum[0] = full[0].first;
    for (int i = 1; i < N; i++)
        cumsum[i] = cumsum[i - 1] + full[i].first;

    ll low = 0, high = X*N;
