void solve() {
  int N, X; cin >> N >> X;
  vi64 S(N);
  vector<tuple<i64, i64, i64>> t;
  i64 M = 0;
  i64 D = 0;
  i64 ok = 0, ng = -1;
  rep(i, N) {
    i64 b, l, u; cin >> b >> l >> u;
    t.push_back(make_tuple(b, l, u));
    S[i] = b * l + (X - b) * u;
    M += S[i];
    ok += b;
    D += -l * b;
  }
  vi32 ord(N);
  iota(all(ord), 0);
  sort(all(ord), [&](int i, int j) {
    return S[i] > S[j];
  });
  vi64 sums(N + 1);
  rep(i, N) sums[i + 1] = sums[i] + S[ord[i]]; 
  while (ok - ng > 1) {
    i64 k = (ok + ng) / 2;
    i64 ma = -1e18;
    i64 p = k / X, q = k - p * X;
    rep(i, N) {
      i64 MM;
      if (p > i) MM = sums[p + 1] - S[ord[i]];
      else MM = sums[p];
      i64 b, l, u;
      tie(b, l, u) = t[ord[i]];
      i64 T;
      if (q <= b) T = q * l;
      else T = b * l + (q - b) * u;
      amax(ma, MM + T);
    }
    if (ma + D >= 0) ok = k;
    else ng = k;
  }
  cout << ok << '\n';
}

