//long long int N, M, K, H, W, L, R;
long long int N, M, K, H, W, L, R;

struct Exam {
	long long int enemy, l, r;
	bool operator <(const Exam&e)const {
		return r * (K - enemy) + l * enemy < e.l*e.enemy + e.r*(K - e.enemy);
	}
	long long int getfull() {
		return r * (K - enemy) + l * enemy;
	}
	long long int get(int num) {
		if (num <= enemy) {
			return num * l;
		}
		else return  enemy*l + (num - enemy)*r;
	}
};


int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> K;
	vector<Exam>exam(N);
	for (auto &i : exam) {
		cin >> i.enemy >> i.l >> i.r;
	}
	long long int ret = 0;
	sort(exam.begin(), exam.end());
	reverse(exam.begin(), exam.end());
	long long box = 0;
	for (auto i : exam) {
		box -= i.l*i.enemy;
	}
	L = -1;
	R = K * N;
	while (R - L > 1) {
		long long int mid = (R + L) / 2;
		long long int sum = box;
		for (int i = 0; i < mid / K; i++) {
			sum += exam[i].getfull();
		}
		if (mid%K) {
			long long int add = 0;
			for (int i = 0; i < N; i++) {
				if (i < mid / K) {
					long long int tmp = exam[mid/K+1].getfull();
					tmp -= exam[i].getfull();
					tmp += exam[i].get(mid%K);
					add = max(add, tmp);
				}
				else {
					add = max(add, exam[i].get(mid%K));
				}
			}
			sum += add;
		}
	//	cout <<mid<<" "<< sum << endl;
		if (sum < 0)L = mid;
		else R = mid;
	}
	cout << R << endl;
}

