	{
		return v < a.v;
	}
}s[maxn];
int n, a;
long long mn = oo, ans = oo;
long long X, sum1 = 0;
void work(int x)
{
	if(s[x].u > mn)
	{
		long long sum2 = sum1 + s[a].v - s[x].v - s[a].l * s[a].b + s[a].u * s[a].b;
		long long c = (sum2 + s[a].u - 1) / s[a].u;
		if(c <= X)
			ans = min(ans, c);
	}
	else
	{
		long long sum2 = sum1 - s[x].l * s[x].b + s[x].u * s[x].b;
		long long c = (sum2 + s[x].u - 1) / s[x].u;
		if(c <= X)
			ans = min(ans, c);
	}
}
int main()
{
	std::ios::sync_with_stdio(false);
	cin >> n >> X;
	for(int i = 1; i <= n; i ++)
	{
		cin >> s[i].b >> s[i].l >> s[i].u;
		s[i].v = X * s[i].u - s[i].b * s[i].u + s[i].b * s[i].l;
		sum1 += s[i].b * s[i].l;
	}
	sort(s + 1, s + n + 1);
	int p;
	for(p = n; p >= 1; p --)
	{
		if(sum1 <= s[p].v)
			break;
		sum1 -= s[p].v;
		if(s[p].u <= mn)
		{
			a = p;
			mn = s[p].u;
		}
	}
	for(int i = 1; i <= p; i ++)
	{
		long long c = (sum1 + s[i].l - 1) / s[i].l;
		if(c <= X)
			ans = min(ans, c);
		work(i);
	}
	sum1 -= s[p].v;
	for(int i = p; i <= n; i ++)
	{
		long long sum2 = sum1 + s[i].v;
