    total[i] = ll(b[i]) * l[i] + ll(X - b[i]) * u[i];
  }
  set<vector<ll> > full_segments;
  set<int> left_segments;
  for (int i = 0; i < n; ++i) {
    vector<ll> segment;
    segment.push_back(-total[i]);
    segment.push_back(u[i]);
    segment.push_back(i);
    full_segments.insert(segment);
    left_segments.insert(i);
  }  
  while (sum < 0) {
    set<vector<ll> >::iterator it = full_segments.begin();
    ll tot = -it->at(0);
    int index = it->at(2);
    full_segments.erase(*it);
    if (sum + tot <= 0) {
      sum += tot;
      res += X;
      left_segments.erase(index);
    }
    else {
      break;
    }
  }
  ll curres = X;
  ll left = -sum;
  for (int i = 0; i < n; ++i) {
    if (left_segments.count(i)) {
      ll need;
      if (ll(l[i]) * b[i] >= left) {
        need = (left + l[i] - 1) / l[i];
      }
      else {
        need = b[i] + (left - ll(l[i]) * b[i] + u[i] - 1) / u[i];
      }
      if (need < curres) {
        curres = need;
      }
    }
  }
  res = res + curres;
  cout << res << endl;
  return 0;
}

