bool check(long long m)
{
    long long score_a = 0;
    long long score_b = 0;

    long long cnt = m / X;
    if(cnt >= N)
        return true;

    for(auto i = 0; i < cnt; ++i)
    {
        score_a += X * A[i][2];
        score_b += A[i][0] * A[i][2];   
    }

    long long max_val = -1;
    int max_idx = -1;
    for(auto i = cnt; i < N; ++i)
    {
        long long candi = (m % X) * A[i][1];
        if(m % X > A[i][0])
            candi = (m % X) * A[i][2] - A[i][0] * (A[i][2] - A[i][1]);

        if(candi > max_val) {
            max_val = candi;
            max_idx = i;
        }
    }

    for(auto i = cnt; i < N; ++i)
    {
        if(i == max_idx) {
            if(m % X > A[i][0]) {
                score_a += (m % X) * A[i][2];
                score_b += A[i][0] * A[i][2];
            }
            else {
                score_a += (m % X) * A[i][1];
                score_b += A[i][0] * A[i][1];
            }
        }
        else {
            score_b += A[i][0] * A[i][1];
        }
    }

    return score_a >= score_b;
}

void solve()
{
    cin >> N >> X;

    A = vector<vector<long long>>(N, vector<long long>(3));

    for(auto i = 0; i < N; ++i)
