vector<pair<ll, int>> uX(100010, {-INFL, -1});

bool win(ll canUse){
  if(canUse >= X * N) return 1;
  int r = canUse % X, p = canUse / X;
  for(int i = 0; i < N; i++){
    ll score = 0;
    if(r - B[i] >= 0){
      score += r * u[i] - B[i] * (u[i] - l[i]);
    }else{
      score += r * l[i];
    }
    if(score >= Asum) return 1;
    int cnt = 0;
    int s = 0;
    while(cnt < p){
      if(uX[s].second == i){
        s++;
      }else{
        score += uX[s++].first;
        cnt++;
        if(score >= Asum) return 1;
      }
    }
  }
  return 0;
}

