using namespace std;

int main() {
  int n;
  ll x;
  scan(n, x);
  vll b(n), l(n), u(n);
  rep (i, n) {
    scan(b[i], l[i], u[i]);
  }

  ll debt = 0;
  rep (i, n) {
    debt += b[i] * l[i];
  }

  vvll pred(n, vll(5));
  rep (i, n) {
    pred[i][0] = b[i] * l[i] + (x - b[i]) * u[i];
    pred[i][1] = i;
    pred[i][2] = b[i];
    pred[i][3] = l[i];
    pred[i][4] = u[i];
  }
  sort(all(pred), greater<vll>());
  debug(pred);

  int ind = -1;
  ll taka = 0;
  rep (i, n) {
    taka += pred[i][0];
    if (taka >= debt) {
      ind = i;
      break;
    }
  }

  assert(ind >= 0);
  ll exceed = taka - debt;
  ll rest_min = x;
  rep (i, ind+1) {
    ll rest = pred[i][0] - exceed;
    ll ng = 0;
    ll ok = x;
    while (ok - ng > 1) {
      ll mid = (ng + ok) / 2;
      ll plus = min(mid, pred[i][2]) * pred[i][3];
      plus += (max(mid, pred[i][2]) - pred[i][2]) * pred[i][4];
      if (plus >= rest) {
        ok = mid;
      } else {
        ng = mid;
      }
    }
    rest_min = min(rest_min, ok);
  }
  ll ans = x * ind + rest_min;
  print(ans);

  return 0;
}

