typedef long long ll;
const int Nmax = 1e5;
int N;
ll X, B[Nmax], L[Nmax], U[Nmax];

int main(){
    cin >> N >> X;
    for(int i=0; i<N; i++) cin >> B[i] >> L[i] >> U[i];

    ll behind = 0;
    for(int i=0; i<N; i++) behind += -L[i]*B[i];

    vector<pair<ll, int> > gain;
    for(int i=0; i<N; i++){
        gain.push_back({U[i]*(X-B[i])+L[i]*B[i], i});
    }
    sort(gain.begin(), gain.end());
    reverse(gain.begin(), gain.end());

    vector<bool> use(N);
    int n_use = 0;
    for(int i=0; i<N; i++){
        int x = gain[i].first;
        int j = gain[i].second;
        // cout << j << " " << gain[i].first << " " << behind << endl;
        if(behind + x > 0){
            break;
        }
        behind += x;
        use[j] = true;
        n_use++;
    }

    if(behind==0){
        cout << n_use*X << endl;
        return 0;
    }

    ll ans = 1e15;
    for(int i=0; i<N; i++){
        if(use[i]) continue;
        if(L[i]*B[i]+behind>=0){
            ans = min(n_use*X + -behind/L[i]+((-behind)%L[i]?1:0), ans);
        } else if(B[i]*(X-B[i])+L[i]*B[i]>=0){
            ll tmp = L[i]*B[i]+behind;
            ans = min(n_use*X + B[i] - tmp/U[i] + ((-tmp)%U[i]?1:0), ans);
        }
    }

    cout << ans << endl;

    return 0;
}

