#include<bits/stdc++.h>
using namespace std;
const int mx = 100005;
struct Test{ long long b, l, u, s;} t[mx];
long long n, x, b, l, u, score, ans;
int main(){
    scanf("%lld%lld", &n, &x);
    for(int i = 0; i < n; i++){
        scanf("%lld%lld%lld", &b, &l, &u);
        t[i] = Test{b, l, u, x*u - b*(u-l)};
        score += b*l;
    }
    sort(t, t+n, [](Test a, Test b){return a.s > b.s;});
    for(int i = 0; i < n; i++){
        if(score > t[i].s){
            score -= t[i].s;
            ans += x;

        }else{
            long long time = mx;
            for(int j = i; j < n && score <= t[i].s; j++){
                if(t[i].l * t[i].b >= score){
                    time = min(time, (score - 1) / t[i].l + 1);
                }else{
                    time = min(time, b + (score - t[i].l * t[i].b - 1) / t[i].u + 1);
                }
            }
            ans += time;
            break;
        }
    }
    printf("%lld\n", ans);
}

