			}
			else {
				del1 = (sum <= get<0>(values[i]) * get<1>(values[i])) ? (sum - 1 + get<1>(values[i])) / get<1>(values[i]) : (get<0>(values[i]) + (sum - get<0>(values[i]) * get<1>(values[i])) / get<2>(values[i]));
			}
			delta = min(delta, del1);
		}
	}
	else delta = 0;
	res += delta;
	cout << res << endl;
	return 0;
}

