	FOR(i,N) {
		cin>>B[i]>>L[i]>>R[i];
		P[i]={-(X-B[i])*R[i],i};
	}
	sort(P,P+N);

	ll ret=X*N;;
	for(i=40;i>=0;i--) if(ok(ret-(1LL<<i))) ret-=1LL<<i;

	cout<<ret<<endl;
}


