vector<int> ord;

bool win(ll M) {
    ll sumA = 0, sumB = 0;
    rep(i_,n){
        int i = ord[i_];
        if (M > b[i]) {
            sumA += r[i] * min(x,M);
            sumB += r[i] * b[i];
            M -= min(x,M);
        } else {
            sumA += l[i] * M;
            sumB += l[i] * b[i];
            M = 0;
        }
    }
    return sumA >= sumB;

}

double cosper(int i){
    return (double)(r[i]*(x-b[i])+b[i]*l[i]) / double(x);
}

int main(void){
    cin >> n >> x;
    b.resize(n);
    l.resize(n);
    r.resize(n);
    ord.resize(n);
    rep(i,n){
        cin >> b[i] >> l[i] >> r[i];
    }
    iota(all(ord), 0);
    sort(all(ord), [&](int i, int j){
        return cosper(i) >= cosper(j);
    });
    ll L = 0, R = x*n+1; // Lダメ, R勝利
    while(L+1<R){
        ll M = (L+R)/2;
        if (win(M)) {
            R = M;
        } else {
            L = M;
        }
    }
    cout << R << endl;

    return 0;
}

