using namespace std;

int b[100005];
int l[100005];
int u[100005];

int main() {
    int n, x;
    cin >> n >> x;
    long sum = 0;
    for (int i = 0; i < n; ++i) {
        cin >> b[i] >> l[i] >> u[i];
        sum += b[i] * l[i];
    }
    long answer = 0;
    while (true) {
        long m = 0, midx;
        for (int i = 0; i < n; ++i) {
            long d = (x - b[i]) * u[i];
            if (d > m) {
                m = d;
                midx = i;
            }
        }
        if (sum <= m + b[midx] * l[midx]) {
            break;
        }
        sum -= m + b[midx] * l[midx];
        answer += x;
        u[midx] = 0;
    }
    int m = x;
    for (int i = 0; i < n; ++i) {
        if (u[i] == 0) continue;
        long target = sum - b[i] * l[i];
        int ll = 0, rr = x;
        while (rr - ll > 1) {
            int m = (ll + rr) / 2;
            if (m >= sum || m * l[i] >= sum || (m - b[i]) * u[i] >= target) {
                rr = m;
            } else {
                ll = m;
            }
        }
        for (int j = ll; j <= x; ++j) {
            if (j >= sum || j * l[i] >= sum || (j - b[i]) * u[i] >= target) {
                m = min(m, j);
                break;
            }
        }
    }
    answer += m;
    cout << answer << endl;
}

