LL N, X;
LL B[100000];
LL L[100000];
LL R[100000];
bool ok(LL k) {
	LL num = k / X;
	LL sum = 0;
	REP(i, 0, N) {
		sum -= L[i] * B[i];
	}

	REP(i, 0, num) {
		sum += R[i] * (X - B[i]) + L[i] * B[i];
	}

	LL rem = k % X;
	LL mx = 0;
	REP(i, num, N) {
		LL val;
		if (rem < B[i]) {
			val = L[i] * rem;
		} else {
			val = R[i] * (rem - B[i]) + L[i] * B[i];
		}
		mx = max(mx, val);
	}
	sum += mx;
	return sum >= 0;
}

int main() {
	cin >> N >> X;
	vector<pair<LL, PP>> v;
	REP(i, 0, N) {
		LL b, l, r;
		cin >> b >> l >> r;
		v.push_back({ b, PP(l, r) });
	}

	auto score = [](auto a) -> LL {
		LL b = a.first;
		LL l = a.second.first;
		LL r = a.second.second;
		return r * (X - b) + l * b;
	};

	sort(v.begin(), v.end(), [&](auto a, auto b) {
		return score(a) > score(b);
	});

	REP(i, 0, N) {
		LL b = v[i].first;
		LL l = v[i].second.first;
		LL r = v[i].second.second;
		B[i] = b;
		L[i] = l;
		R[i] = r;
	}

	cout << findBoundary(ok, 0, N * X, true) << endl;
	return 0;
}

