const int N = 1e5 + 5;
typedef long long LL;

int n, x;
struct node {
	int b, l, r;
} t[N];
LL l, r, mid, sum[N], suf[N];

LL calc(node a) {
	return (x - a.b)*a.r;
}

bool check(LL s) {
	LL ans = -1e10;
	int k = s/x, r = s - k*x;
	if(k >= n) return true;
	for(int i = 1; i <= n; i++) {
		if(i <= k) ans = max(ans, sum[k + 1] - calc(t[i]) + suf[k + 2] + ((r >= t[i].b) ? t[i].r : t[i].l)*(r - t[i].b));
		else ans = max(ans, sum[k] + suf[k + 1] + t[i].b*t[i].l + ((r >= t[i].b) ? t[i].r : t[i].l)*(r - t[i].b));
	}
	return ans >= 0;
}

bool cmp(node a, node b) {
	return calc(a) > calc(b);
}

