void init() {
	for (int i = 1; i <= n; ++i) id[i] = i, pr -= l[i] * b[i];
	for (int i = 1; i <= n; ++i) all[i] = b[i] * l[i] + (X - b[i]) * u[i];
	sort(id + 1, id + 1 + n, cmp);
	for (int i = 1; i <= n; ++i) sum[i] = sum[i - 1] + all[id[i]];
}

bool check(ll mid) {
	ll t = mid / X;
 	ll ret = pr;
 	ret += sum[t];
 	int st = t + 1;
 	t = mid % X;
 	ll mx = 0LL;
 	for (int i = st; i <= n; ++i) mx = max(mx, min(b[id[i]], t) * l[id[i]] + max(0LL, t - b[id[i]]) * u[id[i]]);
 	ret += mx;
 	return ret >= 0;
}

