	sort(T+1, T+1+N, [&](t3 x, t3 y) {
		int bi, li, ri; tie(bi, li, ri) = x;
		int bj, lj, rj; tie(bj, lj, rj) = y;
		return (ll)ri * (X - bi) + (ll)li * bi > (ll)rj * (X - bj) + (ll)lj * bj;
	});
	ll sum = 0, ans = 0, rr = 1e18;
	for(int i=1;i<=N;i++) {
		int b, l, r;
		tie(b, l, r) = T[i];
