		ll add = (ll) r * X;
		if(sum + add >= del) {
			ll v1 = 1e18;
			for(int j=i;j<=N;j++) {
				ll dd = del - (ll)(r-l) * b - sum;
				int B, L, R; tie(B, L, R) = T[j];
				v1 = min(v1, ans + (dd + L - 1) / L);
				dd += (R - L) * (ll)B;
