			}
			rr = min(rr, v1);

			ll v2 = 1e18;
			for(int j=i;j;j--) {
				ll dd = (sum + add - del);
				int B, L, R; tie(B, L, R) = T[j];
				v2 = min(v2, ans + X - dd / R);
				dd -= (R - L) * (ll)(X - B);
				v2 = min(v2, ans + X - dd / L);
			}
			rr = min(rr, v2);
			break;
		}
