void *wmem;
void sortF_L(int N, unsigned A[], void *mem = wmem){
  int bt, i, m, *sz;
  unsigned *arr, c;
  if(N < 256){
    sort(A, A+N);
    return;
  }
  bt = sizeof(unsigned) * 8;
  arr = (unsigned*)mem;
  sz = (int*)(arr+N);
  for(m=0;m<bt;m+=8){
    for(i=0;i<257;i++){
      sz[i] = 0;
    }
    for(i=0;i<N;i++){
      sz[ 1+((A[i]>>m)&255u) ]++;
    }
    for(i=1;i<257;i++){
      sz[i] += sz[i-1];
    }
    for(i=0;i<N;i++){
      c = ((A[i]>>m)&255u);
      arr[sz[c]++] = A[i];
    }
    swap(A, arr);
  }
}
