using namespace std;

const int maxn = (int) 2e5 + 20;

#define LL long long

int n;
LL x, sum;
LL b[maxn], l[maxn], r[maxn];

LL s[maxn];
int rk[maxn];

int cmp(int lhs, int rhs)
{
    return s[lhs] > s[rhs];
}

bool vis[maxn];

bool gao(LL score)
{
    for(int i = 0; i < n; i++) vis[i] = 0;
    LL tmp = sum;

    for(int i = 0; i < n && score >= x; i++)
    {
        int id = rk[i];
        score -= x;

        tmp += s[id];
        vis[id] = 1;
    }



    LL mx = 0;

    for(int i = 0; i < n; i++)
    {
        if(vis[i]) continue;

        LL t;
        if(score >= b[i]) t = b[i] * l[i] + (score - b[i]) * r[i];
        else t = score * l[i];
        mx = max(mx, t);
    }

    tmp += mx;

    return tmp >= 0;
}

void work()
{
    cin >>n >>x;
    for(int i = 0; i < n; i++) cin >>b[i] >>l[i] >>r[i];

    sum = 0;
    for(int i = 0; i < n; i++)
    {
        sum -= b[i] * l[i];
        rk[i] = i;
        s[i] = (x - b[i]) * r[i] + b[i] * l[i];
    }
    sort(rk, rk + n, cmp);

    LL l = 0, r = x * n, mid, ans = -1;
    while(l <= r)
    {
        mid = (l + r) >> 1;

        if(gao(mid))
        {
            r = mid - 1;
            ans = mid;
        }
        else
        {
            l = mid + 1;
        }
    }

    cout <<ans <<endl;
}


