struct node{
	int l,r,b,id;
}z1[maxn],z2[maxn];
bool cmp(node aa,node bb) {
	if(aa.l!=bb.l) return aa.l > bb.l;
	return aa.r > bb.r;
}
int n,X;
bool cmp1(node aa,node bb) {
	return aa.b * aa.l + (X-aa.b)*aa.r > bb.b * bb.l + (X-bb.b) * bb.r;
}
int w[maxn];
bool mk[maxn];
bool ok(int SM) {
	int sm = 0;
	for(int i=1;i<=n;i++) sm -= z1[i].b*z1[i].l,mk[i]=0;
	for(int i=1;i<=SM/X;i++) {
		sm += z2[i].b * z2[i].l + (X-z2[i].b)*z2[i].r;
		mk[z2[i].id] = 1;
	}
	SM%=X;
	for(int i=1;i<=n;i++) {
		if(!mk[z1[i].id]) {
			int res = min(SM,z1[i].b);
			sm += res*z1[i].l;
			SM -= res;
			if(SM) sm += SM*z1[i].r;
		}
	}
	return sm>=0;
}

