  vector<T> v(N);
  ll A = 0,B = 0;

  int i;REP(i,N){
    cin >> v[i].b >> v[i].l >> v[i].u;
    B += v[i].b * v[i].l;
  }
  //X取った時にBのとるポイント(b*c)との差が大きい順にソート
  sort(v.begin(),v.end(),comp);

  //貪欲に取って行った時に初めて超えるインデックス
  int index = 0;

  REP(i,N){
    A += X*v[i].u;
    B += v[i].b*(v[i].u - v[i].l);
    if(A  >= B ){
      index = i;
      break;
    }
  }

  ll minimum = X;
  REP(i,N){
    int j = min(index,i);
    ll remain = (B - v[j].b*(v[j].u - v[j].l) ) - (A - X*v[j].u);
    ll s=0,e=X,c;
    if(v[i].b*v[i].l < remain){
      remain += v[i].b*(v[i].u - v[i].l);
      c = v[i].u;
    }else{
      c = v[i].l;
    }
    while(e-s>=2){
      if(s>minimum) break;
      ll mid = (s+e)/2;
      if(mid*c < remain) s = mid;
      else e = mid;
    }
    minimum = min(e,minimum);
  }
  ll ans = (ll)X * index + minimum;
  cout << ans << endl;
  return 0;
}

