    a[i] = make_tuple(1LL * (x - p) * r + 1LL * p * q, p, q, r);
    s += p;
  }
  sort(a.rbegin(), a.rend());
  long long low = -1, high = s + 1;
  while (low + 1 < high) {
    long long mid = (low + high) / 2;
    long long d = 0, k = mid;
    for (int i = 0; i < n; ++i) {
      int z = min(1LL * x, k);
      k -= z;
      int score, l, r;
