      if (z > score)
        d -= 1LL * r * score, d += 1LL * r * z;
      else
        d -= 1LL * l * score, d += 1LL * l * z;
    }
    if (d >= 0)
      high = mid;
    else
      low = mid;
  }
  printf("%lld\n", high);
