struct NODE{
  ll b,l,u;
  ll score;
};

ll n,x;
ll aoki;
bool isOK(ll mid, vector<NODE> &v){
  if(mid == 0) return false;
  ll full = mid/x;
  ll amari = mid % x;
  if(full == n) return true;
  // calc c_sum
  VLL c_sum(n+1,0);
  rep(i,n){
    if(i == 0) c_sum[i] = v[i].score;
    else c_sum[i] += v[i].score + c_sum[i-1];
  }
  c_sum[n] = c_sum[n-1];
  //あまりの場所を1箇所決める{
  rep(i,n){
    ll total = -aoki;
    if(full <= i){
      //満点を取るやつ
      if(full > 0) total += c_sum[full-1];
      //あまりを取るやつ
      total += v[i].b * v[i].l;
      if(v[i].b < amari){
        total += v[i].u * (amari - v[i].b);
      }else{
        total += v[i].l * (amari - v[i].b);
      }
    }else{
      //満点を取るやつ
      if(full > 0){
        total += c_sum[full];
        total -= v[i].score;
      }
      total += v[i].b * v[i].l;
      if(v[i].b < amari){
        total += v[i].u * (amari - v[i].b);
      }else{
        total += v[i].l * (amari - v[i].b);
      }
    }
    if(total >= 0) return true;
  }
  return false;
}

bool cmp(NODE a, NODE b){
  return a.score <= b.score;
}
