		a[i].read();

	LL treba = 0;
	sort(a, a + n, cmp);
	FOR(i, 0, n)
		treba += a[i].l * a[i].b;

	cout << min(solve1(treba), solve2(treba)) << endl;
	cerr << "Time elapsed: " << clock() / (double)CLOCKS_PER_SEC << endl;
	return 0;
}

