    }
    ll cur = sum[cc];
    ll diff = pre[n] - pre[cc];

    for(int i=1; i<=n; i++)
    {
        if(cc >= i)
        {
            if(cur - a[i].add + a[cc+1].add + a[i].l * mm >= diff - a[cc+1].total + a[i].l * a[i].b
               || cur - a[i].add + a[cc+1].add + a[i].r * mm >= diff - a[cc+1].total + a[i].r * a[i].b)
            {
                return true;
            }
        }
        else
        {
            if(cur + a[i].r*mm >= diff + (a[i].r - a[i].l) * a[i].b ||
               cur + a[i].l*mm >= diff)
            {
                return true;
            }
        }
    }
