    vector<pair<ll,pll>> A(n);
    cin>>A;
    ll sum=0;
    for(auto &I:A){sum+=I.F*I.S.F;}
    priority_queue<pll> Q1;
    vector<bool> used(n,false);
    ll ans=x*n;
    for(int i=0;i<n;i++){
        Q1.push({x*A[i].S.S-A[i].F*(A[i].S.S-A[i].S.F),i});
    }
    ll cnt=0;
    while(sum>0){
        pll W=Q1.top(); Q1.pop();
        ll i=W.S;
        ll s=sum-A[i].S.S*x-A[i].F*A[i].S.F+A[i].F*A[i].S.S;
        if(s<=0){
            ans=min(ans,cnt+x);
