        }
        sum=s;
        cnt+=x;
        used[i]=true;
    }
    for(int i=0;i<n;i++){
        if(!used[i]){
            if(A[i].F*A[i].S.F>=sum){
                ans=min(ans,cnt+(sum+A[i].S.F-1)/A[i].S.F);
            }
