                ll s=sum+A[i].F*(A[i].S.S-A[i].S.F);
                ans=min(ans,cnt+max(A[i].F,(s+A[i].S.S-1)/A[i].S.S));
            }
        }
    }
    cout<<ans<<endl;


    return 0;
}

