int main(){
    long long N, X; cin >> N >> X;
    vector<long long> b(N), l(N), u(N);
    for(int i=0;i<N;i++) cin >> b[i] >> l[i] >> u[i];
    vector<pair<long long, int>> vp;
    for(int i=0;i<N;i++) vp.emplace_back((X-b[i])*u[i] + b[i]*l[i], i);
    sort(vp.rbegin(), vp.rend());
    long long thr = 0;
    for(int i=0;i<N;i++) thr += b[i] * l[i];
    long long L = -1, R = N*X;
    while(R-L > 1){
        long long mid = (L+R)/2;
        long long sum = 0;
        for(int i=0;i<mid/X;i++) sum += vp[i].first;
        int div = mid/X;
        long long add = 0;
        long long m = mid%X;
        for(int i=0;i<N;i++){
            if(vp[i].first > vp[div].first) continue;
            int idx = vp[i].second;
            if(m < b[idx]) add = max(add, l[idx] * m);
            else add = max(add, b[idx] *  l[idx] + (m - b[idx]) * u[idx]);
        }
        if(sum + add >= thr) R = mid;
        else L = mid;
    }
    cout << R << endl;
}

