bool check(long long mid){
	long long maxj = mid / X, kkk = mid % X;
	if (maxj >= n) return 1;
	vector <pli> v;
	for (int i = 0; i < n; i++){
		v.push_back(mp((X - a[i].b) * a[i].u, i));
	}
	sort(v.rbegin(), v.rend());
	long long sum = 0, tot = 0;
	for (int i = 0; i < n; i++){
		if (i < maxj) sum += a[v[i].se].b * a[v[i].se].u, tot += X * a[v[i].se].u;
		else sum += a[v[i].se].b * a[v[i].se].l;
	}
	long long pos = v[maxj].se;
	if (kkk == 0) return tot >= sum;
	for (int i = 0; i < n; i++){
		int x = v[i].se;
		if (i < maxj){
			long long nsum = 0, ntot = 0;
			if (kkk < a[x].b){
				ntot = tot - X * a[x].u + kkk * a[x].l + X * a[pos].u;
				nsum = sum - a[x].b * a[x].u + a[x].b * a[x].l - a[pos].b * a[pos].l + a[pos].b * a[pos].u;
			} else {
				ntot = tot - X * a[x].u + kkk * a[x].u + X * a[pos].u;
				nsum = sum - a[pos].b * a[pos].l + a[pos].b * a[pos].u;
			}
			if (ntot >= nsum) return 1;
		} else {
			long long nsum = 0, ntot = 0;
			if (kkk < a[x].b){
				ntot = tot + kkk * a[x].l;
				nsum = sum;
			} else {
				ntot = tot + kkk * a[x].u;
				nsum = sum - a[x].b * a[x].l + a[x].b * a[x].u;
			}
			if (ntot >= nsum) return 1;
		}
	}
	return 0;
}

