struct Test {
    int b;
    int l;
    int u;

    Test(int b, int l, int u) : b(b), l(l), u(u) {}

    int maxGain() const {
        return u * (X - b);
    }

    int loss() const {
        return l * b;
    }

    bool operator< (const Test &a) const {
        return maxGain() + loss() < a.maxGain() + a.loss();
    }
};

vector<Test> tests;

int f(int idx, int left) {
    int ret = X;

    int minU = 10000000;
    rep(i, idx - 1) {
        minU = min(minU, tests[i].u);
    }

    REP(i, idx, N - 1) {
        left -= tests[i].b * tests[i].l;

        int low = -1;
        int high = X;
        int mid = (low + high) / 2;
        while (high - low > 1) {
            int gain = (mid - tests[i].b) * tests[i].l;
            if (gain >= left) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high + 1) / 2;
        }

        int tleft = (mid - tests[i].b) * tests[i].l - left;
        if (tleft > 0) mid -= min(X, tleft / minU);

        ret = min(ret, mid);

        left += tests[i].b * tests[i].l;
    }

    REP(i, idx, N - 1) {
        left -= tests[i].b * tests[i].l;

        int low = -1;
        int high = X;
        int mid = (low + high) / 2;
        while (high - low > 1) {
            int gain = (mid - tests[i].b) * tests[i].u;
            if (gain >= left) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high + 1) / 2;
        }

        int tleft = (mid - tests[i].b) * tests[i].u - left;
        if (tleft > 0) mid -= min(X, tleft / minU);

        ret = min(ret, mid);

        left += tests[i].b * tests[i].l;
    }

    return ret;
}

