/*
// 関数 func : int64_t -> Value(任意) に対して
// 二分探索で値が変化する点をすべて見つける O(min(range, 変化する点数 * log(range)))
// 探索区間 [lower, upper) 内で同じ値を返す区間が複数登場してはならない
// 戻り値は func(x) が等しい区間の左端の列 (args) とそれに対応する func の値の列 (vals) 
// (ただし lower を含み upper を含まない)
// 例えば区間 [0, 6) に対する func の値が { 4, 4, 4, 2, 2, 5 } なら
// (args, vals) = ( { 0, 3, 5 }, { 4, 2, 5 } ) を返す
*/
template <class Function>
auto findAllBoundaries(Function func, int64_t lower, int64_t upper) -> BoundariesResult<decltype(func(lower))> {
	using Value = decltype(func(lower));		// 値の型を推論
	struct Mapping {
		int64_t arg;
		Value val;
		Mapping(int64_t arg, Value val)
			: arg(arg), val(val) {
		}
	};
	using Range = std::pair<Mapping, Mapping>;

	/* 区間として正当かどうかチェック */
	if (upper <= lower) return BoundariesResult<Value>();

	/* 区間 [lower, upper - 1] の両端の値を計算し、戻り値用配列に追加 */
	int64_t lower_arg = lower;
	int64_t upper_arg = upper - 1;
	Value lower_val = func(lower_arg);
	Value upper_val = func(upper_arg);

	std::vector<int64_t> ret_args;
	std::vector<Value> ret_vals;
	ret_args.push_back(lower_arg);
	ret_vals.push_back(lower_val);

	/* 区間全体が同じ値を返すなら終了 */
	if (lower_val == upper_val) {
		BoundariesResult<Value> ret;
		ret.args = std::move(ret_args);
		ret.vals = std::move(ret_vals);
		return ret;
	}

	/* 区間 [lower, upper - 1] の両端の値が異なるなら stack に追加 */
	std::stack<Range> stack;
	stack.push(Range(
		Mapping(lower_arg, lower_val),
		Mapping(upper_arg, upper_val)
	));

	/* 両端の値が異なる限り二分探索で境界を探索 */
	while (!stack.empty()) {
		/* 区間 [l_arg, r_arg] に注目 */
		auto pair = stack.top(); stack.pop();
		Mapping l = pair.first;
		Mapping r = pair.second;
		int64_t l_arg = l.arg;
		int64_t r_arg = r.arg;
		Value l_val = l.val;
		Value r_val = r.val;

		/* 区間幅が 1 なら終了 (r_arg が境界) */
		if (r_arg - l_arg == 1) {
			ret_args.push_back(r_arg);
			ret_vals.push_back(r.val);
			continue;
		}

		/* 区間 [l_arg, m_arg] と [m_arg, r_arg] に分割 */
		int64_t m_arg = (l_arg + r_arg) / 2;
		Value m_val = func(m_arg);

		/* 各区間について、両端の値が異なるなら stack に追加 */
		/* stack から取り出す順序の都合上、区間 [m, r] -> 区間 [l, m] の順で追加 */
		if (m_val != r_val) {
			stack.push(Range(
				Mapping(m_arg, m_val),
				Mapping(r_arg, r_val)
			));
		}

		if (m_val != l_val) {
			stack.push(Range(
				Mapping(l_arg, l_val),
				Mapping(m_arg, m_val)
			));
		}
	}

	BoundariesResult<Value> ret;
	ret.args = std::move(ret_args);
	ret.vals = std::move(ret_vals);
	return ret;
}

