typedef long long Int;
typedef pair<Int, Int> P;

vector<P> points;
Int n, x;
Int b[216000];
Int l[216000];
Int u[216000];
Int val = 0;
bool ok(Int score){
    Int all = score / x;
    Int part = score % x;
    for(int i = 0;i < n;i++){
        Int V = 0;
        if(i < all) V += points[all].first - (points[i].first - (i?points[i-1].first:0)) ;
        else V += all?points[all-1].first:0;
        int id = points[i].second;
        V += l[id] * min(b[id], part);
        V += u[id] * max(0LL, part - b[id]);
        if(V >=val)return true;
    }
    return false;
}

int main(){
    cin >> n >> x;
    for(int i = 0;i < n;i++){
        cin >> b[i] >> l[i] >> u[i];
        val += b[i] * l[i];
        points.push_back(P(b[i] * l[i] + u[i] * (x-b[i]),i));
    }
    sort(points.rbegin(), points.rend());
    for(int i = 1;i < n;i++){
        points[i].first += points[i-1].first;
    }
    Int bottom = 0, top = n*x;
    while(top - bottom > 1){
        Int mid = (top + bottom) / 2;
        if(ok(mid))top = mid;
        else bottom = mid;
    }

    cout << top << endl;
    return 0;
}

