    ll eff; //p_maxまでやって何点縮まるか
};

bool cmp(const Points &a, const Points &b){
    return a.eff > b.eff;
}

ll minPoint(Points test, ll tar){
    tar += test.aoki * (test.c_max - test.c_min);
    ll p = tar / test.c_max;
    if(tar % test.c_max != 0) p ++;
    return p;
}

