int N,pos,id[MAXN];
int64 l[MAXN],u[MAXN],b[MAXN],val[MAXN],X,all;
bool vis[MAXN];
void Solve() {
    read(N);read(X);
    for(int i = 1 ; i <= N ; ++i) {
	read(b[i]);read(l[i]);read(u[i]);
	all -= b[i] * l[i];
	val[i] = (X - b[i]) * u[i] + b[i] * l[i];
    }
    for(int i = 1 ; i <= N ; ++i) id[i] = i;
    sort(id + 1,id + N + 1,[](int a,int b){return val[a] > val[b];});
    int64 sum = 0;
    for(int i = 1 ; i <= N ; ++i) {
	sum += val[id[i]];
	if(sum + all >= 0) {pos = i - 1;sum -= val[id[i]];break;}
	vis[id[i]] = 1;
    }
    all += sum;
    int64 ans = (pos + 1) * X; 
    for(int i = 1 ; i <= N ; ++i) {
	if(vis[i] && val[i] != val[id[pos + 1]]) continue;
	int L = 0,R = X + 1;
	while(L < R) {
	    int mid = (L + R) >> 1;
	    int64 sc = 0;
	    if(mid >= b[i]) sc = (mid - b[i]) * u[i];
	    else sc = (mid - b[i]) * l[i];
	    if(all + b[i] * l[i] + sc >= 0) R = mid;
	    else L = mid + 1;
	}
	if(R <= X) {
	    ans = min(ans,pos * X + R);
	}
    }
    out(ans);enter;

}
