	if(fin + Pr[forb].x < need) return 1e18 + x;
	if(fin + L[w] * B[w] >= need) {
		ll res = need - fin;
		return X * x + res / L[w] + (res % L[w] != 0);
	} else {
		ll res = need - fin - L[w] * B[w];
		return X * x + B[w] + res / U[w] + (res % U[w] != 0);
	} 
}

