bool f(ll k) {
  priority_queue<pair<ll, pair<ll,int>>> q;
  auto can = [&](int i) {
    return min(a[i] + k, max_score) - a[i];
  };
  for(int i = 1; i <= n; i++) {
    a[i] = 0;
    ll add = min(a[i] + k, max_score) - a[i];
    q.push({(a[i] + add) * rg[i], {add, i}});
  }
  while(q.size() and k) {
    ll val = q.top().first;
    ll add = q.top().second.first;
    int i = q.top().second.second;
    q.pop();
    if(add > can(i)) {
      q.push({(a[i] + can(i)) * rg[i], {can(i), i}});
      continue;
    }
    a[i] += add;
    k -= add;
    if(can(i))
      q.push({(a[i] + can(i)) * rg[i], {can(i), i}});
  }
  ll sum = 0;
  for(int i = 1; i <= n; i++) {
    if(a[i] >= b[i])
      sum += (a[i] - b[i]) * rg[i];
    else
      sum += (a[i] - b[i]) * lf[i];
