ll comp(int i, int j){
	ll p,q;
	p = (x-b[i])*u[i];
	q = (x-b[j])*u[j];
	return p>q;
}

bool judge(ll p){
	int i;
	ll tmp=0ll,mx=0ll;
	for(i=0; i<n; ++i){
		if(p<x){
			break;
		}else{
			tmp += (x-b[v[i]])*u[v[i]];
			p -= x;
		}
	}
	for(i=i; i<n; ++i){
		tmp -= b[v[i]]*l[v[i]];
		mx = max(mx,b[v[i]]*l[v[i]]+max((p-b[v[i]])*l[v[i]],(p-b[v[i]])*u[v[i]]));
	}
	tmp += mx;
	return (tmp>=0ll);
}

