pair<li, int> get(int x){
	int l = 0, r = n;
	while (l < r - 1){
		int m = (l + r) / 2;
		li tmp = pr[m];
		if (m - 1 < x)
			tmp += val[x].x;
		if (tmp >= sum)
			r = m;
		else
			l = m;
	}
	fore(i, l, r + 1){
		li tmp = pr[i];
		if (i - 1 < x)
			tmp += val[x].x;
		if (tmp >= sum)
			return mp(tmp - val[x].x, i - (i - 1 >= x));
	}
	return mp(INF64, INF64);
}

void solve() {
	sum = 0;
	forn(i, n)
		sum += a[i].b * li(a[i].l);

	if (sum == 0){
		puts("0");
		return;
	}

	forn(i, n)
		val[i] = mp(x * li(a[i].u) - a[i].b * li(a[i].u) + a[i].b * li(a[i].l), i);
	sort(val, val + n, greater<pair<li, int>>());
	pr[0] = 0;
	forn(i, n)
		pr[i + 1] = pr[i] + val[i].x;

	//cerr << vector<pair<li, int>>(val, val + n) << endl;
	//cerr << vector<li>(pr, pr + n + 1) << endl;
	//cerr << sum << endl;

	li ans = INF64;

	forn(i, n){
		auto tmp = get(i);
		li cur = tmp.x;
		int cnt = tmp.y;

		//cerr << tmp << " " << val[i].y << endl;

		if (cur == INF64)
			continue;
		int zi = val[i].y;

		li pr;
		if (cur + a[zi].b * li(a[zi].l) >= sum)
			pr = a[zi].l;
		else if (cur + val[i].x >= sum)
			pr = a[zi].u;
		else
			continue;

		int l = 0, r = x;
		while (l < r - 1){
			int m = (l + r) / 2;
			if (cur + m * li(pr) - a[zi].b * li(pr) + a[zi].b * li(a[zi].l) >= sum)
				r = m;
			else
				l = m;
		}

		if (cur + l * li(pr) - a[zi].b * li(pr) + a[zi].b * li(a[zi].l) >= sum)
			r = l;
		if (cur + r * li(pr) - a[zi].b * li(pr) + a[zi].b * li(a[zi].l) >= sum)
			ans = min(ans, cnt * li(x) + r);
	}

	printf("%lld\n", ans);
}

