		auto itr = m.end();
		--itr;
		if (needScore > itr->first) {
			res += X;
			needScore -= itr->first;
			m.erase(itr);
		}
		else {
			int min_ = INF;
			for (auto& one : m) {
				const auto M1_ = one.first;
				const auto M0_ = one.second.second;
				const auto B_ = one.second.first;
				int needTime = 0;
