struct S {
    LL b,l,u;
};

void solve() {
    LL n,x;
    cin >> n >> x;
    vector<S> t(n);
    REP(i,0,n) {
        cin >> t[i].b >> t[i].l >> t[i].u;
    }

    vector<pair<LL,int>> ps(n);
    REP(i,0,n) {
        ps[i] = MP((x-t[i].b) * t[i].u + t[i].b * t[i].l, i);
    }
    sort(all(ps));
    reverse(all(ps));
    VLL lru(n+1), rru(n+1);
    REP(i,0,n) lru[i+1] = lru[i] + (x - t[ps[i].second].b) * t[ps[i].second].u;
    REP(i,0,n) rru[i+1] = rru[i] + t[ps[n-i-1].second].b * t[ps[n-i-1].second].l; 
    VLL lrub(n+1), rrub(n+1);
    REP(i,0,n) lrub[i+1] = lrub[i] + (x - t[ps[i].second].b);
    REP(i,0,n) rrub[i+1] = rrub[i] + t[ps[n-i-1].second].b;
    LL bsum = 0;
    REP(i,0,n) bsum += t[i].b;

    LL ans = n * x;
    REP(i,0,n) {
        LL ll = lru[i]; // 0 - i-1
        LL rr = rru[n-i-1];

        LL diff = ll - rr;
        LL b = t[ps[i].second].b;
        LL l = t[ps[i].second].l;
        LL u = t[ps[i].second].u;

        if (diff == 0) {
            LL tmp = bsum + lrub[i] - rrub[n-i-1];
            ans = min(ans, tmp);
        } else if (diff > 0) {
            LL sub = diff / l;
            sub = min(sub, b);
            LL tmp = bsum + lrub[i] - rrub[n-i-1] - sub;
            ans = min(ans, tmp);
        } else if (diff < 0) {
            LL add = -diff / u;
            if (add > x - b) continue;
            LL tmp = bsum + lrub[i] - rrub[n-i-1] + add;
            ans = min(ans, tmp);
        }
    }
    cout << ans << endl;
}

