        int64_t r = n;
        int64_t l = -1;
        while (r - l > 1) {
            int mid = (l + r) >> 1;
            if (getsum(sums, mid, i) + cursum >= need)
                r = mid;
            else
                l = mid;
        }

        if (r < n) {
            int64_t curneed = need - getsum(sums, r, i);
            int64_t curadd = 0;
            if (curneed > 0) {
                if (curneed > a[i].l * a[i].b) {
                    curneed -= a[i].l * a[i].b;
                    curadd = a[i].b;
                    curadd += (curneed + a[i].r - 1) / a[i].r;
                } else {
                    curadd = (curneed + a[i].l - 1) / a[i].l;
                }
            }
            ans = min(ans, r * X + curadd);
        }
    }
