bool solve(ll T)
{
  int cnt = T / X;
  ll x = T % X;
  ll ans = sum[cnt];
  ll maxi = 0;
  for (auto i = cnt; i < N; i++)
  {
    ll t, b, l, u;
    tie(t, b, l, u) = V[i];
    ll tmp = 0;
    if (x >= b)
    {
      tmp = l * b + (x - b) * u;
    }
    else
    {
      tmp = l * x;
    }
    maxi = max(maxi, tmp);
  }
#if DEBUG == 1
  cerr << "T = " << T << ", cnt = " << cnt << ", ans = " << ans + maxi << endl;
#endif
  return (ans + maxi >= 0);
}

