constexpr int MN = 1e5+5;

ll b[MN], l[MN], u[MN];
bitset<MN> used;

int main() {
    if (fopen("in", "r")) freopen("in", "r", stdin), freopen("out", "w", stdout);
    ios_base::sync_with_stdio(0), cin.tie(0);

	int N, X; cin >> N >> X;
	for (int i = 0; i < N; ++i) cin >> b[i] >> l[i] >> u[i];

	ll sum = 0;
	for (int i = 0; i < N; ++i) sum += b[i]*l[i];

	priority_queue<ii> pq;
	for (int i = 0; i < N; ++i) pq.emplace(X*u[i]-b[i]*u[i]+b[i]*l[i], i);

	ll ans = 0;
	while (sum) {
		if (pq.top().f > sum) {
			int x = -1, y = X;
			for (int it = 0; it < 50; ++it) {
				int m = (x+y)/2;
				ll mx = 0;
				for (int i = 0; i < N; ++i) 
					if (!used[i]) mx = max(m*u[i]-b[i]*u[i]+b[i]*l[i], mx);
				mx >= sum ? y = m : x = m+1;
			}
			ans += y;
			sum = 0;
		}
