    ll Min = INF;
    while (!pq.empty()) {
        if (pq.top().first < Tmp) break;
        int n = pq.top().second;
        pq.pop();
        ll a;
        if (Tmp < L[n]*B[n]) {
            a = (Tmp + L[n]-1) / L[n];
        } else {
            a = B[n] + (Tmp - L[n]*B[n] + U[n]-1) / U[n];
        }
