struct stu{
    long long b,l,u;long long suml,sumu;
}s[100010];
long long n,x;
int cmp(stu aa,stu bb){
    return aa.u*((long long)x-aa.b)+aa.l*aa.b>bb.u*((long long)x-bb.b)+bb.l*bb.b;
}

int check(long long mid)
{

    long long p=mid%x, q=mid/x;

    for( int i=1;i<=q;i++ )
    {
        long long dis=0;
        dis += s[i-1].sumu;dis += (s[q+1].sumu-s[i].sumu);
        if(p>s[i].b) dis+=(p-s[i].b)*s[i].u;
        else dis += (p-s[i].b)*s[i].l;
        dis -= (s[n].suml-s[q+1].suml);
        if (dis>=0) return 1;
    }
    for ( int i=q+1;i<=n;i++)
    {
        long long dis=0;
        dis += s[q].sumu;
        dis -= (s[i-1].suml-s[q].suml);dis-= (s[n].suml-s[i].suml);
        if(p>s[i].b) dis+=(p-s[i].b)*s[i].u;
        else dis += (p-s[i].b)*s[i].l;
        if (dis>=0) return 1;
    }


    return 0;
}

int main()
{
