    for (int i=1;i<=n;i++)
    {
         scanf("%lld%lld%lld",&s[i].b,&s[i].l,&s[i].u);
         s[i].suml=s[i].sumu=0;
    }
    std::sort(s+1,s+n+1,cmp);
    s[0].suml=s[0].sumu=0;
    for (int i=1;i<=n;i++) {
        s[i].suml=s[i-1].suml+s[i].b*s[i].l;
        s[i].sumu=s[i-1].sumu+(x-s[i].b)*s[i].u;
    }
    long long ans=(long long)n*x,l=0,r=(long long)n*x;

    while(l<=r){
        long long mid=(l+r)/2;
        if (check(mid)){
            ans=mid;r=mid-1;
        }
        else l=mid+1;
    }
    printf("%lld",ans);



}

