bool compare(const pair<int64,int64>& r,const pair<int64,int64>& l){
    if(r.first>l.first){
        return true;
    }else if(r.first<l.first){
        return false;
    }else{
        if(b[r.second]<b[l.second]){
            return true;
        }else{
            return false;
        }
    }
}

