#include <cstdio>
#include <algorithm>
#include <numeric>

typedef long long ll;

const int MaxN = 100005;

inline int div_ceil(ll a, int b) {
	return (a + b - 1) / b;
}

int n, W;
struct node {
	int b, l, r; ll val;

	node() = default;
	node(int b, int l, int r): b(b), l(l), r(r) {
		val = (ll)r * (W - b) + (ll)l * b;
	}

	inline int calc(ll s) const {
		if (s >= val) return W;
		ll tmp = s - (ll)b * l;
		return tmp > 0 ? b + div_ceil(tmp, r) : div_ceil(s, l);
	}
} dat[MaxN];

ll solve() {
	scanf("%d%d", &n, &W);

	ll sum = 0;
	for (int i = 0; i < n; ++i) {
		int b, l, r;
		scanf("%d%d%d", &b, &l, &r);
		dat[i] = node(b, l, r);
		sum -= (ll)l * b;
	}

	std::sort(dat, dat + n, [](const node &a, const node &b) {
		return a.val > b.val;
	});

	for (int i = 0; i < n; ++i) {
		ll val = dat[i].val;
		if (sum + val >= 0) {
			int res = W;
			for (int j = 0; j < i; ++j) {
				res = std::min(res, dat[j].calc(-sum + dat[j].val - val));
			}
			for (int j = i; j < n; ++j) {
				res = std::min(res, dat[j].calc(-sum));
			}
			return (ll)i * W + res;
		}
		sum += val;
	}

	return (ll)n * W;
}

int main() {
	printf("%lld\n", solve());
	return 0;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;

typedef tuple<int,int,int,int> P;

int N, X;

signed main(){

  cin>>N>>X;

  int bS = 0;

  priority_queue<P,vector<P>,greater<P> > Q;

  for(int i=0;i<N;i++){

    int b, l, u;
    cin>>b>>l>>u;

    bS += b * l;

    Q.push(P( -((X-b)*u), b, l, u ));

  }

  int aS = 0;
  int ans = 0;

  while( !Q.empty() ){

    int A, b, l, u;

    tie( A, b, l, u ) = Q.top();

    A *= -1;
    //cout<<A<<' '<<b<<' '<<l<<' '<<u<<endl;
    int naS = aS + X * u;

    int nbS = bS - b * l + b * u;

    if( nbS <= naS ) break;

    aS = naS;
    bS = nbS;
    ans += X;

    Q.pop();

  }  
  //cout<<aS<<' '<<ans<<endl;
  if( !Q.empty() ){

    int minplus = X;

    while( !Q.empty() ){

      int A, b, l, u;

      tie( A, b, l, u ) = Q.top(); Q.pop();

      A *= -1;

      int naS = aS + X * u;

      int nbS = bS - b * l + b * u;

      if( naS < nbS ) continue;

      int L = 0, R = b + 1;

      while( L < R ){

	int M = ( L + R ) / 2;

	naS = aS + M * l;
	nbS = bS;

	if( naS < nbS ) L = M + 1;
	else R = M;

      }

      if( L != b + 1 ) minplus = min( minplus, L );

      L = b + 1, R = X + 1;

      while( L < R ){

	int M = ( L + R ) / 2;

	naS = aS + M * u;
	nbS = bS - b * l + b * u;

	if( naS < nbS ) L = M + 1;
	else R = M;

      }

      minplus = min( minplus, L );

    }

    ans += minplus;

  }

  cout<<ans<<endl;

  return 0;
}

