  });
  vector< int64 > B(N), L(N), R(N);
  vector< int64 > xs;
  for(int i = 0; i < N; i++) {
    tie(B[i], L[i], R[i]) = tap[i];
    xs.emplace_back(L[i]);
    xs.emplace_back(R[i]);
  }
  sort(begin(xs), end(xs));
  xs.erase(unique(begin(xs), end(xs)), end(xs));


  int64 ret = infll;

  AdditionalBIT< int64 > bit1(xs.size()), bit2(xs.size());

  vector< int64 > S(N + 1);
  for(int i = 0; i < N; i++) {
    S[i] = L[i] * B[i];
    L[i] = lower_bound(begin(xs), end(xs), L[i]) - begin(xs);
    R[i] = lower_bound(begin(xs), end(xs), R[i]) - begin(xs);
    bit1.add(xs.size() - L[i] - 1, xs[L[i]] * X);
    bit2.add(xs.size() - L[i] - 1, X);
  }
  for(int i = N - 1; i >= 0; i--) {
    S[i] += S[i + 1];
  }
  int64 tmp = 0;

  {
    int i = -1;
    int64 need = tmp + S[i + 1];
    int pos = bit1.lower_bound(need);
    need -= bit1.sum(pos - 1);
    int64 tap = bit2.sum(pos - 1);
    pos = xs.size() - pos - 1;
    tap += (need + xs[pos] - 1) / xs[pos];
    chmin(ret, tap);
  }


  for(int i = 0; i < N; i++) {

    bit1.add(xs.size() - L[i] - 1, -xs[L[i]] * X);
    bit2.add(xs.size() - L[i] - 1, -X);
    bit1.add(xs.size() - R[i] - 1, xs[R[i]] * X);
