    need -= bit1.sum(pos - 1);
    int64 tap = bit2.sum(pos - 1);
    pos = xs.size() - pos - 1;
    tap += (need + xs[pos] - 1) / xs[pos];
    chmin(ret, tap);


  }

  cout << ret << endl;
}

