  if(debt<=del)return true;
  FOR(j,fills,n){
    int i = v[j].first; 
    if(res < b[i]){
      debt-=(LL)res*(LL)l[i];
      if(debt<=del)return true;
      debt+=(LL)res*(LL)l[i];
    }else{
      debt-=(LL)(res-b[i])*(LL)u[i]+(LL)b[i]*(LL)l[i];
      if(debt<=del)return true;
      debt+=(LL)(res-b[i])*(LL)u[i]+(LL)b[i]*(LL)l[i];
