int x;

struct Test {
    int b;
    int l, r;

    int get_sum() {
        return b * l + (x - b) * r;
    }

    int get_sum_f(int f) {
        return max((int)0, f - b) * r + min(f, b) * l;
    }

    Test() {}
};

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n >> x;
    vector<Test> a(n);
    int ndl = 0;
    for (auto &t : a) {
        cin >> t.b >> t.l >> t.r;
        ndl += t.b * t.l;
    } 
    cerr << ndl << endl;
    sort(a.rbegin(), a.rend(), [&](Test a, Test b) {
        return a.get_sum() < b.get_sum();
    });
    // for (auto t : a) {
    //     cerr << t.get_sum() << ' ';
    // }
    // cerr << endl;
    auto can = [&](int hv) {
        int ans = 0;
        int len = hv / x;
        int lf = hv % x;
        for (int i = 0; i < len; i++) {
            ans += a[i].get_sum();
        }
        // cerr << "can" << endl;
        // cerr << len << ' ' << lf << endl;
        int mx = 0;
        for (int i = len; i < n; i++) {
            mx = max(mx, a[i].get_sum_f(lf));
        }
        // cerr << ans << ' ' << mx << endl;
        // cerr << ans + mx << endl; 
        return ans + mx >= ndl;
    };
    int l = 0;
    int r = n * x;
    while (r - l > 1) {
        int m = (r + l) >> 1;
        if (can(m)) r = m;
        else l = m;
    }
    cout << r << endl;
    // cerr << can(2540) << endl;
}

