#include "bits/stdc++.h"
using namespace std;
typedef long long ll;
const int INF = (1<<30);
const ll INFLL = (1ll<<60);
const ll MOD = (ll)(1e9+7);

#define l_ength size

void mul_mod(ll& a, ll b){
	a *= b;
	a %= MOD;
}

void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

struct subject{
	ll b,l,u,value;
	bool operator<(const subject &rhs){
		return value > rhs.value;
	}
};

int n;
ll x,df=0ll;
vector<subject> v;

bool judge(ll p){
	int i;
	ll q,r,tmp=-df,d=-INFLL,c,qv;
	q = p/x; r = p%x;
	if(q>=n){
		return true;
	}
	for(i=0; i<q; ++i){
		tmp += v[i].value;
	}
	for(i=0; i<n; ++i){
		if(v[i].b<r){
			c = v[i].l * r;
		}else{
			c = v[i].value - (x-r)*v[i].u;
		}
		if(i<q){
			d = max(d,tmp+c+v[q].value-v[i].value);
		}else{
			d = max(d,tmp+c);
		}
	}
	return (d>=0ll);
}

int main(void){
	int i,ok,ng,mid;
	cin >> n >> x;
	v.resize(n);
	for(i=0; i<n; ++i){
		cin >> v[i].b >> v[i].l >> v[i].u;
		v[i].value = v[i].l*v[i].b + v[i].u*(x-v[i].b);
		df += v[i].b * v[i].l;
	}
	if(!df){
		cout << "n" << endl;
		return 0;
	}
	sort(v.begin(),v.end());
	ok = x*n; ng = 0ll;
	while(ok-ng>1ll){
		mid = ok+ng;
		mid >>= 1;
		if(judge(mid)){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	cout << ok << endl;
	return 0;
}

