int main() {
	int n, x; reader(n, x);
	using P = tuple<ll, ll, ll>;
	vector<P> vp;
	FOR(i, n) {
		ll a, b, c; reader(a, b, c);
		vp.emplace_back(a, b, c);
	}

	ll sm = 0;
	vector<tuple<ll, ll, ll, ll>> vp2;
	FOR(i, n) {
		ll a, b, c; tie(a, b, c) = vp[i];
		sm -= a * b;
		vp2.emplace_back(c * (x - a) + b * a, a,b,c);
	}
	sort(vp2.rbegin(), vp2.rend());

	vector<ll> vp2sum = { 0 };
	FOR(i, n) {
		ll nxt = vp2sum.back() + get<0>(vp2[i]);
		vp2sum.push_back(nxt);
	}
	ll ans = ll(1e12);
	FOR(i, n) {
		ll maxAdd, a, b, c; tie(maxAdd, a, b, c) = vp2[i];
		int l = -1, r = n-1;
		while (r - l != 1) {
			int md = (l + r) / 2;
			ll curSum = vp2sum[md];
			if (md <= i) {
				curSum += maxAdd;
			}
			if (sm + curSum < 0) l = md;
			else r = md;
		}

		ll curSum = vp2sum[r];
		if (i < r) curSum -= maxAdd;
		ll curUsedMax = r;
		if (i < r) curUsedMax--;

		ll curAns = curUsedMax * x;
		ll more = max(0LL, -sm - curSum);
		ll add = 0;
		if (more <= a*b) {
			add = (more + b - 1) / b;
		} else {
			add = ((more - a*b) + c - 1) / c + a;
		}
		if (add > x) {
			continue;
		}
		curAns += add;

		ans = min(ans, curAns);
	}

	writerLn(ans);

	return 0;
}

