bool solve(int k) {
	//勝てる科目数
	int cnt = k / X;
	if (cnt >= N)return true;
	int rem = k - X * cnt;
	int res = 0;

	int idx = cnt;
	int mx = -INF;
	FOR(i, 0, N) {
		int j = v[i].second;
		int tmp=0;
		if (i < cnt) {
			tmp-=(X - b[j])*u[j]+b[j]*l[j];
			/*if (rem >= b[j]) {
				tmp += b[j] * l[j] + (rem - b[j])*u[j];
			}
			else {
				tmp += rem * l[j];
			}*/
			int pos = v[cnt].second;
			tmp += (X - b[pos])*u[pos] + b[pos] * l[pos];
		}
		if (rem >= b[j]) {
			tmp += b[j] * l[j] + (rem - b[j])*u[j];
		}
		else {
			tmp += rem * l[j];
		}
		if (tmp > mx) {
			mx = tmp;
			idx = i;
		}
		//cout << "cnt:" << cnt << endl;
		//pe(i)print(tmp);
	}
	int c = 0;
	//print(idx);
	FOR(i, 0, N) {
		int j = v[i].second;
		if (i == idx) {
			if (rem >= b[j]) {
				res += (rem - b[j])*u[j];
			}
			else {
				res -= (b[j] - rem)*l[j];
			}
		}
		else if (c < cnt) {
			res += (X - b[j])*u[j];
			c++;
		}
		else {
			res -= b[j] * l[j];
		}
	}
	//print(res);
	if (res >= 0) {
		return true;
	}
	else {
		return false;
	}
}
