using namespace std;

using i64 = long long int;
using ii = pair<int, int>;
using ii64 = pair<i64, i64>;

struct Study
{
	int idx;
	i64 hour;
	i64 reduce;
	i64 cut;
	i64 cutHour;

	bool operator<(const Study& r) const
	{
		if (reduce * r.hour == r.reduce * hour)
			return cut * r.cutHour > r.cut * cutHour;

		return reduce * r.hour < r.reduce* hour;
	}
};

int main()
{
	i64 n, x;
	scanf("%lld %lld", &n, &x);

	vector<i64> b(n), l(n), u(n);
	i64 need = 0;

	for (int i = 0; i < n; i++)
	{
		scanf("%lld %lld %lld", &b[i], &l[i], &u[i]);
		need += l[i] * b[i];
	}

	i64 hour = 0;
	i64 lo = 0, hi = x * n;

	while (lo <= hi)
	{
		i64 mid = (lo + hi) / 2;
		i64 remain = mid;
		i64 make = 0;

		priority_queue<Study> q;

		for (int i = 0; i < n; i++)
		{
			Study s;
			s.idx = i;
			s.hour = x;
			s.reduce = l[i] * b[i] + u[i] * (x - b[i]);
			s.cutHour = remain % x;

			if (s.cutHour >= b[i])
				s.cut = l[i] * b[i] + u[i] * (s.cutHour - b[i]);
			else
				s.cut = l[i] * s.cutHour;

			if (remain < x)
			{
				s.hour = s.cutHour;
				s.reduce = s.cut;
			}

			q.push(s);
		}

		while (!q.empty() && remain > 0)
		{
			auto now = q.top();
			q.pop();

			if (now.hour <= remain)
			{
				remain -= now.hour;
				make += now.reduce;
				continue;
			}

			// 이 경우, hour 만큼만 깎을 수 있을 때 거를 다시 넣어줌
			Study next;
			next.idx = now.idx;
			next.hour = now.cutHour;
			next.reduce = now.cut;
			next.cutHour = now.cutHour;
			next.cut = now.cut;

			q.emplace(next);
		}

		if (make >= need)
		{
			hour = mid;
			hi = mid - 1;
		}
		else
		{
			lo = mid + 1;
		}
	}

	printf("%lld\n", hour);

	return 0;
}

