int n;

ll X,ans;

ll getans(ll v)
{
	ll sum = 0,MAX = 0;
	for (int i = 1;i <= v / X;i++)
		sum += c[i].ans;
	for (int i = 1;i <= n;i++)
	{
		ll val = 0;
		if (v % X >= c[i].b)
			val = c[i].l * c[i].b + c[i].r * (v % X - c[i].b);
		else
			val = c[i].l * (v % X);
		if (i <= v / X)
			MAX = max(MAX,val + sum - c[i].ans + c[v / X + 1].ans);
		else
			MAX = max(MAX,val + sum);
	}
	return MAX;
}

int main()
{
	scanf("%d%lld",&n,&X);
	for (int i = 1;i <= n;i++)
	{
		scanf("%lld%lld%lld",&c[i].b,&c[i].l,&c[i].r);
		ans -= c[i].l * c[i].b;
		c[i].ans = c[i].l * c[i].b + c[i].r * (X - c[i].b);
	}
	sort(c + 1,c + n + 1);
	ll low = 0,high = n * X;
	while (low < high)
	{
		ll mid = low + high >> 1;
		if (getans(mid) + ans >= 0)
			high = mid;
		else
			low = mid + 1;
	}
	printf("%lld\n",low);
	return 0;
}

