// binary search result
struct BSR {
    bool found; // 条件を満たす範囲が見つかったか。falseの場合、begin,endは意味を持たない。
    long long begin; // [begin, end]で条件が成り立つ。
    long long end;

    BSR(bool found_in, long long begin_in, long long end_in) : found(found_in), begin(begin_in), end(end_in) {}
};

template<class Fn> BSR my_binary_search(long long L, long long R, Fn func) {
    if (func(L) && func(R)) {
        return BSR(true, L, R);
    } else if (!func(L) && !func(R)) {
        return BSR(false, 0, 0);
    } else {
        long long lb = L;
        long long ub = R;
        while (lb + 1 < ub) {
            long long mid = (lb + ub) / 2;
            if (func(L) == func(mid)) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        if (func(L)) {
            return BSR(true, L, lb);
        } else {
            return BSR(true, ub, R);
        }
    } 
}

const int MAX_N = 100050;
int N;
long long X;
long long b[MAX_N], l[MAX_N], u[MAX_N];

std::vector<int> pri_max, pri_l;
bool get_max[MAX_N];

bool can_win(long long T) {
    long long rest = 0;
    for (int i = 1; i <= N; i++) {
        rest += l[i] * b[i];
        get_max[i] = false;
    }

    if (X <= T) {
        for (int i : pri_max) {
            rest -= l[i] * b[i];
            rest -= u[i] * (X - b[i]);
            if (rest <= 0) {
                return true;
            }
            T -= X;
            get_max[i] = true;
            if (T < X) {
                break;
            }
        }
    }

    for (int i : pri_l) {
        if (!get_max[i]) {
            rest -= l[i] * T;
            if (rest <= 0) {
                return true;
            } else {
                return false;
            }
        }
    }

    return false;
}

int main(int argc, char **argv) {
