    ll rem = s - sum + v[ord[k - 1]];
    int j = ord[i];
    mi = min(mi, (k - 1) * X + f(b[j], l[j], u[j], rem));
  }
  for (int i = 0; i < k; ++i) {
    int j = ord[i];
    ll rem = s - sum + v[j];
    mi = min(mi, (k - 1) * X + f(b[j], l[j], u[j], rem));
  }
  cout << mi << endl;
  return 0;
}

