const int N = 100100;
const int MAGIC = 1000;
const long long mod = 998244353;

using namespace std;

int n;
long long X;
long long l[N];
long long r[N];
long long b[N];
bool used[N];

vector < pair < long long, int > > make(long long a)
{
        vector < pair < long long, int > > v;
        for(int i = 1; i <= n; i++){
                if(!used[i]){
                        long long cost = b[i] * l[i];
                        long long nb = a - b[i];
                        if(nb < 0){
                                cost += nb * l[i];
                        } else{
                                cost += nb * r[i];
                        }
                        v.push_back({cost, i});
                }
        }
        sort(v.begin(), v.end());
        reverse(v.begin(), v.end());
        return v;
}

bool can(long long m)
{
        long long res = 0;
        for(int i = 1; i <= n; i++){
                used[i] = false;
                res -= b[i] * l[i];
        }
        auto v = make(min(m, X));
        for(int i = 0; i < min(n, (int)(m / X)); i++){
                res += v[i].fi;
                used[v[i].se] = 1;
        }
        m %= X;
        v = make(m);
        if(!v.empty()){
                res += v[0].fi;
        }
        return res >= 0;
}

