int64_t X;

struct TItem {
    int64_t b;
    int64_t l;
    int64_t r;
    int64_t sum;
    TItem(int _b, int _l, int _r) : b(_b), l(_l), r(_r), sum(r * (X - b) + b * l)
    {}
};

inline int64_t getsum(const vector<int64_t>& sums, const int idx, const int my) {
    auto result = sums[idx];
    if (my < idx) {
        result = sums[idx + 1];
        result -= sums[my + 1] - sums[my];
    }
    return result;
}

int main()
{
//    freopen("in.txt","r", stdin);
//    freopen("out.txt", "w", stdout);
//    cin.tie(0);
//    cout << fixed << setprecision(20);
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n >> X;

    vector<TItem> a;
    int64_t need = 0;
    for (int i = 0; i < n; ++i) {
        int b,l,u;
        cin >> b >> l >> u;
        a.emplace_back(b, l, u);
        need += b * l;
    }

    sort(begin(a), end(a), [](const TItem& lhs, const TItem& rhs) {return lhs.sum > rhs.sum;});

    vector<int64_t> sums(n + 1, 0);
    for (int i = 1; i <= n; ++i)
        sums[i] = sums[i - 1] + a[i - 1].sum;

    int64_t l = -1;
    int64_t r = X * n;

    while (r - l > 1) {
        auto mid = (l + r) >> 1;
        int64_t rest = mid % X;
        int64_t best = 0;
        for (int i = 0; i < n; ++i) {
            int64_t cur = rest * a[i].l;
            if (rest > a[i].b)
                cur = a[i].r * (rest - a[i].b) + a[i].b * a[i].l;
            cur += getsum(sums, mid/X, i);
            best = max(best, cur);
        }
        if (best >= need)
            r = mid;
        else
            l = mid;
    }
    cout << r << endl;
}

