using namespace std;
const int N=1e5+100;
int n,x,ans,tot;
struct node
{
	int b,l,r,v;
}sh[N];
bool cmp(node a,node b){return a.v>b.v;}
signed main()
{
	scanf("%lld%lld",&n,&x);
	for (int i=1;i<=n;i++) scanf("%lld%lld%lld",&sh[i].b,&sh[i].l,&sh[i].r);
	for (int i=1;i<=n;i++) sh[i].v=(x-sh[i].b)*sh[i].r+sh[i].l*sh[i].b;
	for (int i=1;i<=n;i++) tot+=sh[i].l*sh[i].b;
	sort(sh+1,sh+1+n,cmp);
	int wh=0;ans=inf;
	for (int i=1;i<=n;i++)
	{
		if (sh[i].v>tot)
		{
			ans=i*x;
			wh=i-1;
			break;
		}
		tot-=sh[i].v;
	}
	for (int i=1;i<=n;i++)
	{
		int tmp=tot;
		if (i<=wh) tmp+=sh[i].v-sh[wh+1].v;
		if (tmp<=sh[i].b*sh[i].l)
		{
			int add=0;
			if (tmp%sh[i].l!=0) add=1;
			ans=min(ans,wh*x+tmp/sh[i].l+add); 
		}
		else
		{
			tmp-=sh[i].b*sh[i].l;
			int add=0;
			if (tmp%sh[i].r!=0) add=1;
			ans=min(ans,wh*x+tmp/sh[i].r+add+sh[i].b);
		}
	}
	printf("%lld\n",ans);
}

