int N, X, B[101010], L[101010], R[101010];
//---------------------------------------------------------------------------------------------------
ll f(int i, int a) {
	if (a < B[i]) return 1LL * L[i] * (a - B[i]);
	else return 1LL * R[i] * (a - B[i]);
}
//---------------------------------------------------------------------------------------------------
bool check(ll t) {
	ll x = t / X;
	ll y = t % X;

	vector<pair<ll, int>> v;
	rep(i, 0, N) v.push_back({ 1LL * R[i] * (X - B[i]) - 1LL * L[i] * (-B[i]), i });
	sort(all(v), greater<pair<ll, int>>());

	ll ma = -infl;
	ll tot = 0;
	rep(i, 0, x) tot += f(v[i].second, X);
	rep(i, x, N) tot += f(v[i].second, 0);
	rep(i, 0, x) {
		ll sm = tot - f(v[i].second, X) - f(v[x].second, 0) + f(v[x].second, X) + f(v[i].second, y);
		chmax(ma, sm);
	}
	rep(i, x, N) {
		ll sm = tot + f(v[i].second, y) - f(v[i].second, 0);
		chmax(ma, sm);
	}

	return 0 <= ma;
}
//---------------------------------------------------------------------------------------------------
void _main() {
	cin >> N >> X;
	rep(i, 0, N) cin >> B[i] >> L[i] >> R[i];

	ll ng = 0, ok = 1LL * X * N;
	while (ng + 1 != ok) {
		ll md = (ng + ok) / 2;
		if (check(md)) ok = md;
		else ng = md;
	}
	cout << ok << endl;
}

