vector<int> divisor(int n){
    vector<int> res(0);
    for(int i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}


int N, X;
struct test{ll b, l, u, up;};
vector<test> T;
ll need;
ll sum[100010];
bool comp_test(test a, test b){
  return a.up < b.up;
}

bool can(ll tar){
  ll all = tar / X;
  if(all >= N) return 1;
  ll rest = tar % X;
  //all個のテストで満点を取る
  rep(i, N){
    //i番目のテストは中途半端にとる
    ll get;
    if(i < all) get = sum[all+1] - T[i].up;
    else get = sum[all];
    get += max(rest * T[i].l, rest * T[i].u - T[i].b * (T[i].u - T[i].l));
    if(get >= need) return 1;
  }
  return 0;
}

void solve(){
  cin >> N >> X;
  rep(i, N){
    ll b, l, u;
    cin >> b >> l >> u;
