    T.pb({b, l, u, up});
    need += b * l;
  }
  sort(T.begin(), T.end(), comp_test);
  reverse(T.begin(), T.end());
  rep(i, N){
    sum[i+1] = sum[i] + T[i].up;
  }
  ll ng = -1, ok = INFL;
  while(ok - ng > 1){
    ll mid = (ok + ng) / 2;
    if(can(mid)) ok = mid;
    else ng = mid;
  }
  cout << ok << endl;
}

