// const ll MOD = 1000000007;

ll N, X;
ll b[100010], l[100010], u[100010];
ll base = 0;
typedef tuple<ll, ll, ll, ll> test;
vector<test> V;
ll sum[100010];

bool solve(ll T)
{
  ll cnt = T / X;
  ll x = T % X;
  ll ans = sum[cnt];
  ll maxi = -1000000000000000;
  for (auto i = cnt; i < N; i++)
  {
    ll t, b, l, u;
    tie(t, b, l, u) = V[i];
    ll tmp = 0;
    if (x >= b)
    {
      tmp = l * b + u * (x - b);
    }
    else
    {
      tmp = l * x;
    }
    maxi = max(maxi, tmp);
  }
#if DEBUG == 1
  cerr << "T = " << T << ", cnt = " << cnt << ", ans = " << ans + maxi << endl;
#endif
  return (ans + maxi >= 0);
}

int main()
{
  cin >> N >> X;
  for (auto i = 0; i < N; i++)
  {
    cin >> b[i] >> l[i] >> u[i];
  }
  for (auto i = 0; i < N; i++)
  {
    base -= l[i] * b[i];
  }
  for (auto i = 0; i < N; i++)
  {
    ll t = l[i] * b[i] + u[i] * (X - b[i]);
    V.emplace_back(t, b[i], l[i], u[i]);
  }
  sort(V.begin(), V.end());
  reverse(V.begin(), V.end());
  sum[0] = base;
  for (auto i = 0; i < N; i++)
  {
    sum[i + 1] = sum[i] + get<0>(V[i]);
  }
  ll ok = N * X + 1;
  ll ng = -1;
  while (abs(ok - ng) > 1)
  {
    ll t = (ok + ng) / 2;
    if (solve(t))
    {
      ok = t;
    }
    else
    {
      ng = t;
    }
  }
  cout << ok << endl;
}

