const int MAXNUM = 150005;
int n;ll x;
struct node{
    ll b,l,r;
    bool operator<(const node &nn)const
    {
        return x*r-b*(r-l)>x*nn.r-nn.b*(nn.r-nn.l);
    }
};
node alln[MAXNUM];
int main()
{
    scanf("%d%lld",&n,&x);ll sum=0;
    rep(i,1,n+1)scanf("%lld%lld%lld",&alln[i].b,&alln[i].l,&alln[i].r),sum+=alln[i].b*alln[i].l;
    sort(alln+1,alln+n+1);
    ll nownum=0,r=0;int k=0;
    rep(i,1,n+1)
    {
        if(nownum+x*alln[i].r-alln[i].b*(alln[i].r-alln[i].l)>sum){k=i;break;}
        nownum+=x*alln[i].r-alln[i].b*(alln[i].r-alln[i].l),r+=x;
    }
    if(nownum==sum){printf("%lld\n",r);return 0;}
    ll res=1e18;
    rep(i,1,k)
    {
        ll xx=sum-(nownum-x*alln[i].r-alln[i].b*(alln[i].r-alln[i].l));
        xx-=x*alln[k].r-alln[k].b*(alln[k].r-alln[k].l);
        res=min(res,r+(xx/alln[i].l+(xx%alln[i].l!=0)));
        xx+=alln[i].b*(alln[i].r-alln[i].l);
        res=min(res,r+(xx/alln[i].r+(xx%alln[i].r!=0)));
    }
    rep(i,k,n+1)
    {
        ll xx=sum-nownum;
        res=min(res,r+(xx/alln[i].l+(xx%alln[i].l!=0)));
        xx+=alln[i].b*(alln[i].r-alln[i].l);
        res=min(res,r+(xx/alln[i].r+(xx%alln[i].r!=0)));
    }
    printf("%lld\n",res);
}

