int main() {
  int n;
  ll x;
  scan(n, x);
  vll b(n), l(n), u(n);
  rep (i, n) {
    scan(b[i], l[i], u[i]);
  }

  ll debt = 0;
  rep (i, n) {
    debt += b[i] * l[i];
  }

  vvll pred(n, vll(5));
  rep (i, n) {
    pred[i][0] = b[i] * l[i] + (x - b[i]) * u[i];
    pred[i][1] = i;
    pred[i][2] = b[i];
    pred[i][3] = l[i];
    pred[i][4] = u[i];
  }
  sort(all(pred), greater<vll>());
  debug(pred);

  int ind = -1;
  ll ans = 0;
  ll taka = 0;
  rep (i, n) {
    if (taka + pred[i][0] < debt) {
      taka += pred[i][0];
      ans += x;
    } else {
      ind = i;
      break;
    }
  }

  assert(ind >= 0);
  ll rest = debt - taka;
  debug(ans);
  debug3(debt, taka, rest);
  ll rest_min = x;
  FOR (i, ind, n) {
    if (pred[i][0] < rest) {
      continue;
    }
    ll ng = 0;
    ll ok = x;
    while (ok - ng > 1) {
      ll mid = (ng + ok) / 2;
      ll plus = min(mid, pred[i][2]) * pred[i][3];
      plus += (max(mid, pred[i][2]) - pred[i][2]) * pred[i][4];
      if (plus >= rest) {
        ok = mid;
      } else {
        ng = mid;
      }
    }
    rest_min = min(rest_min, ok);
  }

  ans += rest_min;
  print(ans);

  return 0;
}

