long long p = 1000003;
vel kai(1000007, 1);
vel ink(1000007, 1);
template<typename T>
V<T> uni(V<T> &list) {
	if (list.size() == 0) { return list; }
	sort(list.begin(), list.end());
	V<T> ql(1, list[0]);
	rep(i, list.size() - 1) {
		if (list[i] != list[i + 1]) { ql.push_back(list[i + 1]); }
	}
	return ql;
}
int ru(int a, int r) {
	if (r == 0) { return 1; }
	int ans = ru(a, r / 2);
	ans *= ans; ans %= p;
	if (r % 2 == 1) { ans *= a; ans %= p; }
	return ans;
}
int inv(int a) {
	return ru(a, p - 2);
}
void make_kai() {
	rep(i, 1000006) { kai[i + 1] = (kai[i] * (i + 1)) % p; }
	rep(i, 1000007) { ink[i] = inv(kai[i]); }
}
int com(int n, int r) {
	int ans = kai[n] * ink[r];
	ans %= p;
	return ans;
}
signed main() {
	int n, x; cin >> n >> x;
	vel nb(n), nl(n), nu(n), nget(n); int goal = 0;
	V<pin> lis(n);
	rep(i, n) { cin >> nb[i] >> nl[i] >> nu[i]; goal += nb[i] * nl[i]; nget[i] = x * nl[i] + (x - nb[i])*(nu[i] - nl[i]); lis[i] = mkp(nget[i], i); }
	sor(lis); reverse(lis.begin(), lis.end());
	vel b(n), l(n), u(n), get(n);
	rep(i, n) { int ni = lis[i].second; b[i] = nb[ni]; l[i] = nl[ni]; u[i] = nu[ni]; get[i] = nget[ni]; }
	int ind = 0;
	int sum = 0;
	while (ind < n) {
		if (sum + get[ind] > goal) { break; }
		sum += get[ind]; ind++;
	}
	if (ind == n) { cout << x * n << endl; }
	int ans = x;
	int ex = goal - sum;
	for (int i = ind; i < n; i++) {
		int qa;
		if (b[i] * l[i] >= ex) {
			qa = (ex + l[i] - 1) / l[i];
		}
		else {
			int qex = ex-b[i] * l[i];
			qa = b[i] + (qex + u[i] - 1) / u[i];
		}
		mmin(ans, qa);
	}
	if (ind != n) {
		sum += get[ind];
		rep(i, ind) {
			int ne = goal - (sum - get[i]);
			int qa;
			if (b[i] * l[i] >= ne) {
				qa = (ne + l[i] - 1) / l[i];
			}
			else {
				int qex = ne - b[i] * l[i];
				qa = b[i] + (qex + u[i] - 1) / u[i];
			}
			mmin(ans, qa);
		}
	}
	cout << ans + ind * x << endl;
	return 0;
}

