int main() {
  long n,x,aokipt=0,ans=0;
  cin >> n >> x;
  vector<long> b(n),l(n),u(n);
  priority_queue<pair<long,long>> q;
  for(long i=0;i<n;i++) {
    cin >> b[i] >> l[i] >> u[i];
    aokipt+=b[i]*l[i];
    q.push({(b[i]*l[i]+(x-b[i])*u[i]),i});
  }
  while(aokipt>=q.top().first) {
    ans+=x,aokipt-=q.top().first;
    q.pop();
  }
  long aaa=99999999999999;
  if(aokipt==0) aaa=0;
  while(q.size()!=0) {
    if(b[q.top().second]*l[q.top().second]>=aokipt) {
      aaa=min(aaa,(aokipt+l[q.top().second]-1)/l[q.top().second]);
    } else {
      aaa=min(aaa,b[q.top().second]+(aokipt-b[q.top().second]*l[q.top().second]+u[q.top().second]-1)/u[q.top().second]);
    }
  	q.pop();
  }
  ans+=aaa;
  cout << ans << endl;
}

