int main() {
#ifdef DEBUG
	ifstream ifs("in.txt");
	cin.rdbuf(ifs.rdbuf());
#endif
	ll N, X;
	cin >> N >> X;
	//vector<tuple<ll, ll, ll> > T;
	vector<ll> Bi;
	vector<ll> Li;
	vector<ll> Ui;
	vector<ll> T_sums;

	ll init_score = 0; // この得点は、最初 Σ -Li Bi になる
	ll sum_bi = 0;
	FOR(i, N) {
		ll b, l, u;
		cin >> b >> l >> u;
		Bi.push_back(b); Li.push_back(l); Ui.push_back(u);
		init_score -= b * l;
		sum_bi += b;

		T_sums.push_back(b * l + (X - b) * u);
	}

	vector<ll> Li_large_index(N);
	iota(ALL(Li_large_index), 0);
	// 合計 が大きい順に並べる。
	sort(ALL(Li_large_index), [&](auto a, auto b) {  return T_sums[a] > T_sums[b];  });


	// Tsumの累積和, 合計が大きい順に
	vector<ll> T_sum_accumulate(N, 0);
	T_sum_accumulate[0] = T_sums[Li_large_index[0]];
	FOR(i, N - 1)
	{
		auto Lii = Li_large_index[i+1];
		T_sum_accumulate[i + 1] = T_sum_accumulate[i] + T_sums[Lii];
	}




	// 二分探索補助関数: kが与えられた時、k個で十分か
	auto check_kCounts_pickup = [&](auto k) {
		// k個で、init_score が越せるか
		ll q = k / X; // q個、大きい方からとる
		ll r = k - X * q; // r 個取る。
		if (q >= N) return true;
		bool ok = false;

		FOR(i, N) {
			// r個取るインデックスがi。
			ll tmp_init_score = init_score;
			if ( q-1 >= 0) tmp_init_score += T_sum_accumulate[q-1]; // まずq個取ってみる。

			// qが3の時、i が0,1,2 (合計が大きい順で) ならrが含まれてしまっているので飛ばす。
			if (i + 1 <= q) {
				tmp_init_score -= T_sums[Li_large_index[i]];
				tmp_init_score += T_sums[Li_large_index[q]];
			}

			// r個を足す
			if (r > 0) {
				auto Lii = Li_large_index[i];
				if (r >= Bi[Lii]) {
					tmp_init_score += (r - Bi[Lii]) * Ui[Lii];
					tmp_init_score += Bi[Lii] * Li[Lii];
				} else {
					tmp_init_score += r * Li[Lii];
				}
			}

			if (tmp_init_score >= 0) 
			{
				ok = true; break;
			}
		} // break

		// c_init_scoreが0を超えたら、勝ち。
		//if (init_score >= 0) return true;
		if (ok) return true;
		return false;

	};

	ll ok = N*sum_bi;
	ll ng = 0;
	ll mid = (ok + ng) / 2;
	while (abs(ok - ng) > 1) {
		if (check_kCounts_pickup(mid)) {
			ok = mid;
		}
		else ng = mid;
		mid = (ok + ng) / 2;
	}
	cout << ok << endl;


	return 0;
}

