const int N = 1 << 17;
LL n, x;

struct exam
{
	LL l, r, b;
	LL top;
	void read()
	{
		cin >> b >> l >> r;
		top = r * x - (r - l) * b;
	}
};

exam a[N];

int cmp(exam l, exam r)
{
	return l.top > r.top;
}

LL skiky(exam e, LL treba)
{
	if (treba > e.top)
		return INF;

	if (treba <= e.l * e.b)
		return (treba + e.l - 1) / e.l;

	return (treba + e.b * (e.r - e.l) + e.r - 1) / e.r;
}

LL solve1(LL treba)
{
	LL ans = 0;

	int last_full = -1;
	for(int i = 0; i < n && treba > 0; ++i)
	{
		if (treba >= a[i].top)
		{
			last_full = i;
			treba -= a[i].top;
			ans += x;
			continue;
		}

		break;				
	}

	LL tut = INF;

	FOR(i, last_full + 1, n)
		tut = min(tut, skiky(a[i], treba));

	if (last_full == n - 1)
		tut = 0;

	ans += tut;
	return ans;
}

LL get(exam e, LL vykyn)
{
	assert(e.top >= vykyn);
	if (vykyn <= e.r * (x - e.b))
		return vykyn / e.r;

	return x - (e.r * (x - e.b) + e.l * e.b - vykyn + e.l - 1) / e.l;
}

LL solve2(LL treba)
{
	LL ans = 0;

	int last_full = -1;
	for(int i = 0; i < n && treba > 0; ++i)
	{
		if (treba >= a[i].top)
		{
			last_full = i;
			treba -= a[i].top;
			ans += x;
			continue;
		}

		break;				
	}

	if (last_full == n - 1)
	{
		assert(treba <= 0);
		return ans;
	}

	treba -= a[last_full + 1].top;
	ans += x;

	LL vykyn = -treba;

	LL best = 0;
	FOR(i, 0, last_full + 1)	
		best = max(best, get(a[i], vykyn));

	assert(best < x);
	ans -= best;
	return ans;
}

int main()
{
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	//freopen("In.txt", "r", stdin);
	//freopen("In.txt", "w", stdout);

	cin >> n >> x;
	FOR(i, 0, n)
		a[i].read();

	LL treba = 0;
	sort(a, a + n, cmp);
	FOR(i, 0, n)
		treba += a[i].l * a[i].b;

	cout << min(solve1(treba), solve2(treba)) << endl;
	cerr << "Time elapsed: " << clock() / (double)CLOCKS_PER_SEC << endl;
	return 0;
}

