    auto can = [&](ll m){

        ll maxfull = m / x;
        ll rest = m % x;

        ll sum = 0;

        int i = 0;
        while (i < n && maxfull) {
            sum += 1ll * ::r[ord[i]] * (x - b[ord[i]]);
            i++;
            maxfull--;
        }

        if (i != n) {
            for (int j = i; j < n; j++) {
                sum -= 1ll * ::l[ord[j]] * b[ord[j]];
            }

            ll maxdelta = 0;
            for (int j = i; j < n; j++) {
                int y = ord[j];
                ll curdelta;
                if (rest >= b[y]) {
                    curdelta = 1ll * ::l[y] * b[y] + 1ll * (rest - b[y]) * ::r[y];
                    upmax(maxdelta, curdelta);
                }
            }


            vector<pair<int, int>> ord2;
            for (int j = i; j < n; j++) {
                ord2.push_back({ord[j], 0});
                ord2.push_back({ord[j], 1});
