            for (auto [i, tp] : ord2) {
                if (tp == 0) {
                    // l[i]
                    ll taken = min<ll>(b[i], rest);
                    rest -= taken;
                    delta2 += 1ll * ::l[i] * taken;
                } else {
                    // r[i]
                    if (rest >= b[i]) {
                        upmax(maxdelta, delta2 + 1ll * ::l[i] * b[i] + 1ll * (rest - b[i]) * ::r[i]);
                    }
                }
            }
            upmax(maxdelta, delta2);
            sum += maxdelta;
        }
        return sum >= 0;
    };

