template <typename T,typename Func> T satisfy_mini(Func P,T l ,T r){
	l -= EPS<T>();
	while(r-l > EPS<T>()){
		T m=(l+r)/2;
		(P(m)?r:l)=m;
	}
	return r;
}

class Main {
public:
  void run() {
    int N; ll X; cin >> N >> X;
    vector<tuple<int,int,int>> aos(N);
    cin >> aos;

    vector<pair<ll,int>> vs(N);
    for(int i:range(N)){
      int b,l,u;tie(b,l,u) = aos[i];
      vs[i] = {(ll)(X-b)*u,i};
    }
    sort(ALL(vs));
    reverse(ALL(vs));
    cerr << vs << endl;

    ll res = satisfy_mini([&](ll t){
      ll val = 0;ll restt = t;
      int j = -1;
      for(int i:range(N)){
        int b,l,u;tie(b,l,u) = aos[vs[i].second];
        if(restt >= X){
          ll uset = X;
          if(uset >= b){
            val += (uset - b) * u;
          }else{
            val += (uset - b) * l;
          }
          restt -= uset;
        }else{
          j = i;
          break;
        }
      }
      int Mi = -1, Mv = -1;
      for(int i:range(j, N)){
        int b,l,u;tie(b,l,u) = aos[vs[i].second];
        ll v = max<ll>(0,(restt - b)) * u + b*l;
        if(v > Mv){
          Mv = v;Mi = i;
        }
      }
      for(int i:range(j,N)){
        int b,l,u;tie(b,l,u) = aos[vs[i].second];
        ll uset = i == Mi? restt: 0;
        if(uset >= b){
          val += (uset - b) * u;
        }else{
          val += (uset - b) * l;
        }
      }
      return val >= 0;
    },0ll, N * X + 10);
    cout << res << endl;
  }
};

int main() {
  cout << fixed << setprecision(20);
  cin.tie(0);
  ios::sync_with_stdio(false);
  Main().run();
  return 0;
}

