void solve(long long N, long long X, std::vector<long long> b, std::vector<long long> l, std::vector<long long> u){
  ll lf=-1,rt=accumulate(b.begin(),b.end(),0);
  vector<int> m100(b.size());
  iota(m100.begin(),m100.end(),0);
  sort(m100.begin(),m100.end(),[&](int x,int y){
    return (l[x]*b[x]+u[x]*(X-b[x]))>(l[y]*b[y]+u[y]*(X-b[y]));
  });
  ll bsum=0;
  REP(N){
    bsum+=b[i]*l[i];
  }
  while(lf+1<rt){
    ll mid=(lf+rt)/2;
    ll cmid=mid;
    vector<int> points(N);
    REP(cmid/X){
      points[m100[i]]=X;
    }
    ll tmp=0,tmp2=0;
    if(cmid%X>0){REP(N){
      if(points[i]==0){
        if(b[i]<(cmid%X)){
          ll tmp3=b[i]*l[i]+(cmid%X-b[i])*u[i];
          if(tmp2<tmp3){
            tmp2=tmp3;
            tmp=i;
          }
        }else{
          ll tmp3=(cmid%X)*l[i];
          if(tmp2<tmp3){
            tmp2=tmp3;
            tmp=i;
          }
        }
      }
    }

      points[tmp]=cmid%X;
    }
    ll diff=0;
    REP(N){
      if(points[i]<=b[i]){
        diff+=points[i]*l[i];
      }else{
        diff+=(points[i]-b[i])*u[i]+b[i]*l[i];
      }
    }
    diff-=bsum;
    if(diff>=0){
      rt=mid;
    }else{
      lf=mid;
    }
  }
  cout<<rt<<endl;
}

