const int MAXN = 100111;

int64 N, X;
int64 B[MAXN], L[MAXN], R[MAXN];

int64 other;

vector<pair<int64, int64>> cand;

int64 Gain(int64 i, int64 t) {
    if (t <= B[i]) {
        return (int64)t * L[i];
    } else {
        return (int64)B[i] * L[i] + (int64)(t - B[i]) * R[i];
    }
}

bool Go(int64 T) {
    vector<bool> used(N);

    int64 cur = other;

    if (cur >= 0)
        return true;

    int64 rem = T % X;
    int64 full = T / X;

    int64 tot = 0;
    for (int i = 0; i < full; i++) {
        tot += cand[i].first;
        used[cand[i].second] = true;
    }

    if (full == N)
        return tot + cur >= 0;

    for (int i = 0; i < full; i++) {
        int64 tot_now = tot - cand[i].first;
        tot_now += Gain(cand[i].second, rem);
        tot_now += cand[full].first;

        if (cur + tot_now >= 0)
            return true;
    }

    for (int i = 0; i < N; i++) {
        if (!used[i]) {
            if (cur + tot + Gain(i, rem) >= 0) {
                return true;
            }
        }
    }

    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

