    for (int i = 0; i < N; i++) {
        cin >> B[i] >> L[i] >> R[i];
        other -= (int64)B[i] * L[i]; 
    }

    int64 l = 0, r = (int64)N * X, m(0), sol(0);

    for (int i = 0; i < N; i++) {
        cand.emplace_back(Gain(i, X), i);
    }

    sort(cand.begin(), cand.end());
    reverse(cand.begin(), cand.end());

    while (l <= r) {
        m = (l + r) >> 1;
        if (Go(m)) {
            sol = m;
            r = m - 1;
        } else {
            l = m + 1;
        }
