            res = max (res, ans + sum + (h - a[j].b) * a[j].l);
            res = max (res, ans + sum + (h - a[j].b) * a[j].r);
            sum -= a[j].l * a[j].b;
         }
         for (int j = 1; j < i; j ++) {
            int in = ans - (x - a[j].b) * a[i].r + sum - a[i].l * a[i].b;
            if (h < a[j].b) in -= (h - a[j].b) * a[j].l;
            else in += (h - a[j].b) * a[j].r;
            in += (x - a[i].b) * a[i].r;
            res = max (res, in);
         }
         break;
      }
   }
   if (!ok) res = ans;  
   return (res >= 0);
}

