int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    long long n, x;
    cin >> n >> x;

    vector<long long> B(n), L(n), U(n), O(n);

    for (int i = 0; i < n; ++i)
    {
        cin >> B[i] >> L[i] >> U[i];
        O[i] = i;
    }

    function<long long(long long, long long, long long, long long)> find = [&](long long c1, long long b1, long long c2, long long b2) {
        if (x * c1 >= c1 * b1 + c2 * b2)
        {
            return (c1 * b1 + c2 * b2 + c1 - 1) / c1;
        }
        else
        {
            return (c1 * b1 + c2 * b2 - x * c1 + c2 - 1) / c2 + x;
        }
    };

    auto cmp = [&](long long u, long long v) {
        long long bu = B[u], lu = L[u], uu = U[u];
        long long bv = B[v], lv = L[v], uv = U[v];

        auto f1 = find(uu, bu, lv, bv);
        auto f2 = find(uv, bv, lu, bu);

        return f1 < f2;
    };

    sort(O.begin(), O.end(), cmp);

    for (int i = 0; i + 1 < n; ++i)
        assert(!cmp(O[i + 1], O[i]));

    vector<long long> SL(n + 1);

    for (int i = n - 1; i >= 0; --i)
    {
        SL[i] = L[O[i]] * B[O[i]] + SL[i + 1];
    }

    long long sumU = 0, sumUB = 0, answer = 0;

    for (int i = 0; i < n; ++i)
    {
        answer += x;
        sumU += U[O[i]];
        sumUB += U[O[i]] * B[O[i]];

        if (x * sumU >= sumUB + SL[i + 1])
        {
            answer -= x;
            sumU -= U[O[i]];
            sumUB -= U[O[i]] * B[O[i]];

            if (x * sumU >= sumUB + SL[i + 1])
            {
                answer += (sumUB + SL[i + 1] + B[O[i]] * L[O[i]] - x * sumU + L[O[i]] - 1) / L[O[i]];
            }
            else
            {
                answer += (sumUB + SL[i + 1] + B[O[i]] * U[O[i]] - x * sumU + U[O[i]] - 1) / U[O[i]];
            }

            break;
        }
    }

    cout << answer << endl;

    return 0;
}

