};


bool comp(const info& l, const info& r){
    return l.d_max > r.d_max;
}

bool comp2(const info& l, const info& r){
    return l.l > r.l;
}

vector<info> info_vec;
vector<long long> sum_vec;


int main(int argc, char* argv[]){
    int N, X;
    cin >> N >> X;

    info_vec.resize(N);
//    sum_vec.resize(N);

    int b;
    int l;
    int u;

    long long cost_zero = 0;
    long long b_sum = 0;

    for(int i = 0; i < N; ++i){
        cin >> b >> l >> u;

        info_vec[i].b = b;
        info_vec[i].u = u;
        info_vec[i].l = l;
        info_vec[i].d_max = (X - b) * u + b * l;

        cost_zero -= l * b;
        b_sum += b * l;
    }

    std::sort(info_vec.begin(), info_vec.end(), comp);

    long long time_sum = 0;
    int i;
    long long last_time = 0;

    for(i = 0; i < N; ++i){
        if(b_sum < info_vec[i].d_max){
            if(b_sum < info_vec[i].b * info_vec[i].b){
                last_time = ceil(b_sum / (double)info_vec[i].l);
            }
            else{
                long long b_rest = b_sum - info_vec[i].b * info_vec[i].b;
                last_time = info_vec[i].b + ceil(b_rest / (double)info_vec[i].u);
            }

            break;
        }
        else{
            time_sum += X;
            b_sum -= info_vec[i].d_max;
            info_vec[i].check = true;
        }
    }

    if(b_sum != 0){
        std::sort(info_vec.begin(), info_vec.end(), comp2);
        for(i = 0; i < N; ++i){
            if(info_vec[i].check)continue;

            long long time_cand = ceil(b_sum / (double)info_vec[i].l);

            time_sum += min(time_cand, last_time);
            break;
        }
    }

    cout << time_sum;

}

