struct TFunction{
	int b, l, u;

	TFunction() {}
	TFunction(int b, int l, int u): b(b), l(l), u(u) {}

	long long get(int x){
		if (x <= b)
			return 1LL * l * (x - b);
		return 1LL * u * (x - b);
	}
}f[N];

int n, x;
