long long pre[N], suf[N];

bool check(long long k){
	long long div = k / x;
	long long rem = k % x;

	if (rem == 0){
		rem = x;
		div--;
	}

	long long mx = -(long long)1e18;

	for (int i = 1; i <= n; i++)
		if (i <= div)
			mx = max(mx, pre[div + 1] + suf[div + 2] - f[i].get(x) + f[i].get(rem));
		else
			mx = max(mx, pre[div] + suf[div + 1] - f[i].get(0) + f[i].get(rem));

	return mx >= 0;
}

