                ll b = blulist[i].t0;
                ll l = blulist[i].t1;
                ll u = blulist[i].t2;
                ll sum = l * b + u * (x - b);
                sumlist.pb({sum, i});
        }
        sort_reverse(sumlist);

        ll sumsumlist[n];
        rep (i, n) {
                if (i == 0) sumsumlist[i] = sumlist[0].t0;
                else sumsumlist[i] = sumsumlist[i-1] + sumlist[i].t0;
        }

        ll border = 0LL;
        rep (i, n) {
                ll b = blulist[i].t0;
                ll l = blulist[i].t1;
                border += l * b;
        }

        ll ans = pow(10LL, 16LL);

        for (ll low = 0LL, high = x * n, hours = (x * n) / 2LL; low <= high;
             hours = (low + high) / 2LL) {

                ll score_max = 0;

                rep (sum_idx, n) {
                        ll sum = sumlist[sum_idx].t0;
                        int i = sumlist[sum_idx].t1;
                        ll b = blulist[i].t0;
                        ll l = blulist[i].t1;
                        ll u = blulist[i].t2;
                        ll score = 0LL;
                        if (hours / x == 0) {
                                score = 0;
                        }
                        else if (hours / x == n) {
                                score = sumsumlist[n - 1];
                        }
                        else if (sum_idx < hours / x) {
                                score = sumsumlist[hours / x] - sum;
                        }
                        else {
                                score = sumsumlist[hours / x - 1LL];
                        }
                        if (hours % x <= b) {
                                score += l * (hours % x);
                        }
                        else {
                                score += l * b + u * (hours % x - b);
                        }
                        score_max = max(score_max, score);
                }

                if (score_max < border) {
                        low = hours + 1LL;
                }
                else {
                        high = hours - 1LL;
                        ans = min(ans, hours);
                }
        }

        cout << ans;

        return 0;
