const double EPS=1e-11;
#define EQ0(x) (abs((x))<EPS)
#define EQ(a, b) (abs((a)-(b))<EPS)

int n;
ll x, sum;
ll b[125252], l[125252], u[125252];

bool is_ok(ll mid){
	if(mid<=x){
		bool ok=false;
		REP(i, n){
			if(u[i]*mid>=sum+(u[i]-l[i])*b[i]){
				ok=true;
				break;
			}
		}
		return ok;
	}
	pair<ll, int> a[125252];
	REP(i, n){
		a[i]=make_pair(u[i]*x-(u[i]-l[i])*b[i], i);
	}
	sort(a, a+n);
	ll k=mid/x, k2=mid%x, tmp=0;
	int idx=-1;
	FORR(i, max(0ll, n-k), n){
		if(a[i].first==0){
			idx=i;
			break;
		}
		tmp+=a[i].first;
	}
	if(idx!=-1){
		ll ma=0;
		FORR(i, 0, idx){
			CHMAX(ma, l[i]*(mid-x*(n-idx)));
		}
		if(tmp+ma>=sum){
			return true;
		}
	}
	ll ma=0;
	FORR(i, 0, max(0ll, n-k)){
		int j=a[i].second;
		CHMAX(ma, u[j]*k2-(u[j]-l[j])*k2);
		CHMAX(ma, l[j]*k2);
	}
	if(tmp+ma>=sum){
		return true;
	}
	ll mi=1e12;
	FORR(i, max(0ll, n-k), n){
		int j=a[i].second;
		CHMIN(mi, u[j]*(x-k2));
		CHMIN(mi, u[j]*x-l[j]*k2-(u[j]-l[j])*b[j]);
	}
	tmp-=mi;
	if(n-k>0){
		tmp+=a[n-k-1].first;
	}
	return tmp>=sum;
}

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	// cout<<setprecision(10)<<fixed;
	cin>>n>>x;
	REP(i, n){
		cin>>b[i]>>l[i]>>u[i];
	}
	sum=0;
	REP(i, n){
		sum+=b[i]*l[i];
	}
	ll lb=-1, ub=1e12;
	while(ub-lb>1){
		ll mid=(lb+ub)/2;
		if(is_ok(mid)){
			ub=mid;
		}
		else{
			lb=mid;
		}
	}
	cout<<ub<<'\n';
	return 0;
}

#include <bits/stdc++.h>

typedef long long LL;
const int N = 100010;

struct Node {
    LL l, r, b, h;
    inline bool operator < (const Node &w) const {
        return h > w.h;
    }
}node[N];

LL X, D, sum[N];
int n;

inline LL cal(LL a, LL i) {
    if(a <= node[i].b) {
        return a * node[i].l;
    }
    return node[i].b * node[i].l + (a - node[i].b) * node[i].r;
}

inline bool check(LL k) {
    LL ans = 0, r = k % X, t = k / X;
    if(t >= n) {
        return sum[n];
    }
//    printf("r = %lld t = %lld \n", r, t);
    for(int i = 1; i <= n; i++) {
        if(i <= t) ans = std::max(ans, cal(r, i) + sum[t + 1] - node[i].h);
        else {
            ans = std::max(ans, cal(r, i) + sum[t]);
        }
    }
    //printf("k = %lld ans = %lld D = %lld \n", k, ans, D);
    return ans >= D;
}

int main() {

    scanf("%d%lld", &n, &X);
    for(int i = 1; i <= n; i++) {
        scanf("%lld%lld%lld", &node[i].b, &node[i].l, &node[i].r);
        node[i].h = node[i].b * node[i].l + (X - node[i].b) * node[i].r;
        D += node[i].b * node[i].l;
    }
    std::sort(node + 1, node + n + 1);
    for(int i = 1; i <= n; i++) {
        sum[i] = sum[i - 1] + node[i].h;
    }
    LL l = 0, r = 4e18;
    while(l < r) {
        LL mid = (l + r) >> 1;
        if(check(mid)) {
            r = mid;
        }
        else {
            l = mid + 1;
        }
    }
    printf("%lld\n", r);
    return 0;
}

