const int MAXN = 100228;


int n;
long long x;
int b[MAXN];
int ls[MAXN], u[MAXN];
vector<pair<long long, int> > g;


long long get(int i, int ost) {
	long long val = 1LL * (b[i] - ost) * ls[i];
	if (ost >= b[i]) {
		val = -1LL * (ost - b[i]) * u[i];
	}
	return val;
}	

bool check(long long mid) {
	long long ans = 0;
	long long cnt = mid / x;
	for (int i = 0; i < cnt; i++) {
		ans += 1LL * (x - b[g[i].second]) * u[g[i].second];
	}
	long long ost = mid % x;
	long long add = 4e18;
	for (int i = cnt; i < n; i++) {
		long long val = get(g[i].second, ost);
		chkmin(add, val - 1LL * b[g[i].second] * ls[g[i].second]);
	}
	ans -= add;
	for (int i = cnt; i < n; i++) {
		ans -= 1LL * b[g[i].second] * ls[g[i].second];
	}
	long long res = ans;
	ans = 0;
	add = 4e18;
	for (int i = 0; i <= cnt; i++) {
		ans += 1LL * (x - b[g[i].second]) * u[g[i].second];
		long long val = get(g[i].second, ost);
		chkmin(add, val + 1LL * (x - b[g[i].second]) * u[g[i].second]);
	}
	ans -= add;
	for (int i = cnt + 1; i < n; i++) {
		ans -= 1LL * b[g[i].second] * ls[g[i].second];
	}
	chkmax(res, ans);
	return res >= 0;
	//score[i] * (cnt - b[i]);
}


int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	//read("input");
	cin >> n >> x;
	for (int i = 0; i < n; i++) {
		cin >> b[i] >> ls[i] >> u[i];
	}
	for (int i = 0; i < n; i++) {
		g.pb({1LL * (x - b[i]) * u[i] + 1LL * b[i] * ls[i], i});
	}
	sort(all(g));
	reverse(all(g));
	long long l = 0;
	long long r = 1LL * x * n;
	while (l < r) {
		long long mid = (l + r) >> 1;
		if (check(mid)) {
			r = mid;
		} else {
			l = mid + 1;
		}
	}
	cout << l << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define all(V) (V).begin(),(V).end()

ll sum = 0, N, X;
vector<vector<ll>> A(100010);
vector<ll> Ru(100010, 0);

bool solve(ll a) {
	//a個選んだ時の結果
	ll p, q, cnt = 0, ans = 0;
	p = a / X;
	q = a % X;
	for (int i = 0;i < N;i++) {
		if (i > p)
			ans = Ru[p];
		else
			ans = Ru[p + 1] - A[i][0];

		if (A[i][1] > q) {
			//lowにする
			ans += q * A[i][2];
		}
		else {
			ans += q * A[i][3] - A[i][4];
		}
		cnt = max(cnt, ans);
	}
	return (cnt >= sum);
}

ll binary(ll ng, ll ok) {
	if (ng + 1 == ok)return ok;
	ll mid = (ng + ok) / 2;
	if (solve(mid)) {
		return binary(ng, mid);
	}
	else {
		return binary(mid, ok);
	}
}

int main() {
	ll b, l, u;
	cin >> N >> X;

	for (int i = 0;i < N;i++) {
		cin >> b >> l >> u;
		sum += b * l;
		A[i] = { u*X - (u - l)*b,b,l,u,(u - l)*b };
	}
	sort(all(A));
	reverse(all(A));
	for (int i = 1;i <= N;i++) {
		Ru[i] = Ru[i - 1] + A[i - 1][0];
	}
	cout << binary(-1, N*X) << endl;
}

