vector<vector<ll>>v;
ll N, X;

ll f(ll x, ll b, ll l, ll u) {
	if (x <= b) {
		return l * (x - b);
	}
	else {
		return u * (x - b);
	}
}
int check(ll mid) {
	ll sum = 0;

	vector<pair<ll,int>>mx;
	for (int i = 0; i < N; i++) {
		ll b = v[i][0];
		ll l = v[i][1];
		ll u = v[i][2];
		mx.pb({ f(X,b,l,u),i});
	}
	sort(all(mx));
	reverse(all(mx));

	set<int>ng;
	for (int i = 0; i < (mid / X); i++) {
		sum += mx[i].first;
		ng.insert(mx[i].second);
	}


	ll tempsum = 0;
	for (int i = 0; i < N; i++) {
		if (!ng.count(i)) {
			ll b = v[i][0];
			ll l = v[i][1];
			ll u = v[i][2];
			tempsum += f(0, b, l, u);
		}
	}

	ll ma = -inf;
	for (int i = 0; i < N;i++) {
		if (!ng.count(i)) {
			ll b = v[i][0];
			ll l = v[i][1];
			ll u = v[i][2];
			ll temp = tempsum - f(0, b, l, u) + f(mid % X, b, l, u);
			ma = max(temp, ma);
		}
	}
	sum += ma;
	return sum >= 0;
}

