#include<bits/stdc++.h>
using namespace std;
//allocation rule
//allocate to the highest low
//update the highest low to high
//keep
typedef long long ll;
ll n,x;
typedef struct T{
    ll b,l,u;
    ll getX(){return b*l+(x-b)*u;}
} T;
bool cmp(T a, T b){ return a.getX()>b.getX();}
ll cal(T a, ll h){
    if (h<=a.b) return h*a.l;
    else return a.b*a.l+(h-a.b)*a.u;
}
vector<T> t;
vector<ll> sum;
int main(void){
    cin >> n >> x;
    ll mx=0,mn=0,diff=0;
    for(int i=0;i<n;i++){
        ll b,l,u;
        cin >> b >> l >> u;
        T tmp={b,l,u};
        t.push_back(tmp);
        mx+=b;
        diff+=b*l;
    }
    ll ans=mx;
    mx++;
    sort(t.begin(),t.end(), cmp);
    sum.resize(t.size()+1);
    sum[0] = 0;
    for (int i=0;i<t.size();i++)
        sum[i+1]=sum[i]+t[i].getX();
    while(mn<mx){
        ll cur=(mn+mx)/2;
        ll buf=sum[cur/x];
        ll res=-1, tmp;
        if (cur%x!=0){
            for (int i=0;i<cur/x;i++){
                assert(cur/x<t.size());
                tmp=buf-t[i].getX()+cal(t[i],cur%x)+t[cur/x].getX();
                res=max(res,tmp);
            }
            for (int i=cur/x;i<t.size();i++){
                tmp=buf+cal(t[i],cur%x);
                res=max(res,tmp);
            }
        }else{
            res=buf;
        }
        if (res>=diff){
            ans=min(ans,cur);
            mx=cur;
        }else{
            mn=cur+1;
        }
    }
    cout << ans << endl;
}

