struct TopK {
    multiset<ll> ms1, ms2;
    ll sum = 0;
    int k;

    TopK(int _k) : k(_k) {}

    void insert(const ll x) {
        ms1.insert(x);
        sum += x;
        if (ms1.size() > k) {
            auto it = ms1.begin();
            ms2.insert(*it);
            sum -= *it;
            ms1.erase(it);
        }
    }
    void check() {
        assert(ms1.size() <= k);
        if(!ms2.empty()) {
            assert(ms1.size() == k);
            if(k)
                assert(*ms2.rbegin() >= *ms1.begin());
        }
    }

    void erase(const ll x) {
        auto it = ms2.find(x);
        if (it != ms2.end())
            ms2.erase(it);
        else {
            it = ms1.find(x);
            assert(it != ms1.end());
            sum -= *it;
            ms1.erase(it);
            if(!ms2.empty()) {
                auto it = --ms2.end();
                ms1.insert(*it);
                sum += *it;
                ms2.erase(it);
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr), cout.tie(nullptr);

    int n;
