    const function<int(int, int)> eval = [&](const int i, const ll c) {
        assert(0 <= i && i < n);
        assert(0 <= c && c <= X);
        if(c <= b[i])
            return c * l[i];
        return b[i] * l[i] + (c - b[i]) * u[i];
    };

    ll hisScore = 0;
    for (int i = 0; i < n; ++i) {
        cin >> b[i] >> l[i] >> u[i];
        hisScore += eval(i, b[i]);
    }

    ll k = 0;

    {
        vector<ll> v(n);
        for (int i = 0; i < n; ++i)
            v[i] = eval(i, X);
        sort(v.rbegin(), v.rend());
        partial_sum(v.begin(), v.end(), v.begin());
        auto it = lower_bound(v.begin(), v.end(), hisScore);
        assert(it != v.end());
        k = it - v.begin();
    }

    TopK topK(k);
    for(int i = 0; i < n; ++i)
        topK.insert(eval(i, X));

    ll lo = 0;
    ll hi = X;
    while(lo < hi) {
        const ll mid = (lo + hi) / 2;

        ll mx = 0;
        for(int i = 0; i < n; ++i) {
            topK.erase(eval(i, X));
            mx = max(mx, topK.sum + eval(i, mid));
            topK.insert(eval(i, X));
        }

        if(mx >= hisScore)
            hi = mid;
        else
            lo = mid + 1;
    }

    cout << k * X + lo;
