            if (f2(need, b, l, U) > 0) {
                down = U;
            } else if (f2(need, b, l, U) < 0) {
                up = U;
            } else {
                tmp = min(tmp, f(need, b, l, U));
                break;
            }
            prevU = U;
            U = (up + down) / 2;
            tmp = min(tmp, f(need, b, l, U));
            if (U == prevU) break;

        }
    }
    cout << ans + tmp<< endl;

    return 0;
}

#include <algorithm>
#include <cassert>
#include <iostream>
#include <vector>
using namespace std;

struct exam {
    long long B, L, U;
    long long change;

    bool operator<(const exam &other) const {
        return change > other.change;
    }
};

long long N, X, score;
vector<exam> exams;
vector<long long> prefix_sum;

bool possible(long long study) {
    long long full_count = study / X;
    long long remainder = study % X;
    long long best = 0;

    for (int i = 0; i < N; i++) {
        long long here = 0;
        here += min(exams[i].B, remainder) * exams[i].L;
        here += max(remainder - exams[i].B, 0LL) * exams[i].U;
        long long sum = 0;

        if (i >= full_count)
            sum = prefix_sum[full_count] + here;
        else
            sum = prefix_sum[full_count + 1] - exams[i].change + here;

        best = max(best, sum);
    }

    return best + score >= 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> X;
    score = 0;
    exams.resize(N);

    for (exam &ex : exams) {
        cin >> ex.B >> ex.L >> ex.U;
        ex.change = ex.B * ex.L + (X - ex.B) * ex.U;
        score -= ex.B * ex.L;
    }

    sort(exams.begin(), exams.end());
    prefix_sum.assign(N + 1, 0);

    for (int i = 0; i < N; i++)
        prefix_sum[i + 1] = prefix_sum[i] + exams[i].change;

    long long low = 0, high = N * X;

    while (low < high) {
        long long mid = (low + high) / 2;

        if (possible(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << '\n';
}

