#include <bits/stdc++.h>
#define M 200010
#define PLL pair <ll, ll>
#define x first
#define y second

using namespace std;

typedef long long ll;

int n, X;

ll B[M], L[M], U[M];

struct node {
	ll A, B;
	node() {A = 0, B = 1;}
	node(ll _1, ll _2) {A = _1, B = _2;}
};

ll need = 0;

PLL Pr[M];

ll Sum[M], W[M];

bool cmp(PLL A, PLL B) {return A.x > B.x;}

ll check(ll x, ll forb, ll w) {
	ll fin = 0;
	if(forb <= x) fin = Sum[x + 1] - Pr[forb].x; else fin = Sum[x];
	if(fin > need) return X * x;
	if(fin + Pr[forb].x < need) return 1e18 + x;
	if(fin + L[w] * B[w] >= need) {
		ll res = need - fin;
		return X * x + res / L[w] + (res % L[w] != 0);
	} else {
		ll res = need - fin - L[w] * B[w];
		return X * x + B[w] + res / U[w] + (res % U[w] != 0);
	} 
}

int main() {
	scanf("%d%d", &n, &X);
	for(int i = 1; i <= n; i++) scanf("%lld%lld%lld", &B[i], &L[i], &U[i]), need += B[i] * L[i], Pr[i] = PLL((U[i] * (X - B[i]) + L[i] * B[i]), i);
	sort(Pr + 1, Pr + n + 1, cmp);
	for(int i = 1; i <= n; i++) Sum[i] = Sum[i - 1] + Pr[i].x, W[Pr[i].y] = i;
	ll ans = 1e18;
	for(int i = 1; i <= n; i++) {
		int w = W[i];
		ll l = 0, r = n - 1, nw = 0;
		for(; l <= r; ) {
			int md = (l + r) / 2;
			ll fin = w <= md ? Sum[md + 1] - Pr[w].x : Sum[md];
			if(fin > need) r = md - 1; else nw = md, l = md + 1;
		}
		for(int j = max((int) nw - 3, 0); j <= min((int) nw + 3, n - 1); j++)
		ans = min(ans, check(j, w, i));
	}
	printf("%lld\n", ans);
	return 0;
}

