const int N=1e5+5;

int n,ord[N];
ll val[N],l[N],u[N],b[N],x;

bool cmp(int x,int y) {return val[x]>val[y];}

ll chk_mx(ll k) {
	ll sum=0,lim=k/x;
	fo(i,1,lim) sum+=val[ord[i]];
	ll mx=0,ret=k%x;
	if (val[ord[lim+1]]==val[ord[lim]]) while (lim&&val[ord[lim]]==val[ord[lim+1]]) lim--;
	fo(i,lim+1,n) {
		int z=ord[i];
		ll now=(ret<=b[z])?ret*l[z]:(b[z]*l[z]+(ret-b[z])*u[z]);
		mx=max(mx,now);
	}
	return sum+mx;
}

int main() {
	n=read();x=read();
	fo(i,1,n) b[i]=read(),l[i]=read(),u[i]=read();
	fo(i,1,n) val[i]=l[i]*b[i]+(x-b[i])*u[i];
	fo(i,1,n) ord[i]=i;sort(ord+1,ord+n+1,cmp);
	ll d=0;fo(i,1,n) d+=l[i]*b[i];
	ll L=0,R=0,ans=0;fo(i,1,n) R+=b[i];
	while (L<=R) {
		ll mid=L+R>>1;
		if (chk_mx(mid)>=d) ans=mid,R=mid-1;
		else L=mid+1;
	}
	printf("%lld\n",ans);
	return 0;
}

