      if (vis[i] == A + 1) {
        id = i;
      }
    }
  }
  for (int i = 1; i <= n; i++) {
    if (vis[i] <= A) {
      ll now = tmp - 1ll * (x - b[i]) * R[i] + 1ll * (x - b[id]) * R[id] + 1ll * b[id] * L[id];
      now += 1ll * (B - b[i]) * ((B >= b[i]) ? R[i] : L[i]);
      res = max(res, now);
    } else {
      ll now = tmp + 1ll * b[i] * L[i];
      now += 1ll * (B - b[i]) * ((B >= b[i]) ? R[i] : L[i]);
      res = max(res, now);  
    }
  }
