LL g(LL i, LL h) {
	return (h <= b[i] ? l[i] * h : l[i] * b[i] + u[i] * (h - b[i]));
}

bool f(LL t) {
	LL k = fl(t, x);

	LL A1 = 0;
	vector<bool> used(n, false);
	inc(i, k) { A1 += v[i].FI; used[v[i].SE] = true; }

	LL ma = 0;
	inc(i, n) {
		if(used[i]) { continue; }
		setmax(ma, g(i, mo(t, x)));
	}
	A1 += ma;


	LL A2 = 0;
	LL k2 = min(n, k + 1);
	inc(i, k2) { A2 += v[i].FI; }
	ma = -1e18;
	inc(i, k2) { setmax(ma, g(v[i].SE, mo(t, x)) - g(v[i].SE, x)); }
	A2 += ma;

	return (max(A1, A2) >= B);
}

