#include <bits/stdc++.h>

using namespace std;

int main() {
    cin.tie(nullptr); ios::sync_with_stdio(false);

    long N, X; cin>>N>>X;
    struct Data {
        long b, l, u;
        Data() {
            cin>>b>>l>>u;
        }
        long value(long x) {
            return b*l+(x-b)*u;
        }
    };
    vector<Data> datas(N);
    sort(datas.begin(), datas.end(), [X](auto l, auto r) {return l.value(X) > r.value(X);});
    vector<long> cvalue(N);
    cvalue[0] = datas[0].value(X);
    for (int i = 1; i < N; i++) {
        cvalue[i] = cvalue[i-1] + datas[i].value(X);
    }
    long B = 0;
    for (auto& data : datas) {
        B += data.b*data.l;
    }

    auto solve = [&](long k) {
        if (k == N*X)
            return cvalue.back() >= B;
        for (int n = 0; n < N; n++) {
            auto q = k/X;
            long sum = q > 0 ? cvalue[q-1] : 0;
            if (n < q)
                sum = sum - datas[n].value(X) + datas[q].value(X);
            auto r = k%X;
            auto& data = datas[n];
            if (r <= data.b) {
                sum += data.l*r;
            } else {
                sum += data.l*data.b + data.u*(r-data.b);
            }
            if (sum >= B)
                return true;
        }
        return false;
    };

    long l = 0, r = N*X;
    long ans = r;
    while (l <= r) {
        auto c = (l+r)/2;
        if (solve(c)) {
            r = c-1;
            ans = c;
        } else {
            l = c+1;
        }
    }
    cout << ans << endl;

    return 0;
}

