bool check2(int idx, int q, int r) {
    ll sum = cumsum[q];
    if (idx < q) {
        sum -= get<0>(tests[idx]);
        sum += get<0>(tests[q]);
    }
    if (r > get<1>(tests[idx])) {
        sum += get<1>(tests[idx]) * get<2>(tests[idx]);
        sum += (r - get<1>(tests[idx])) * get<3>(tests[idx]);
    } else {
        sum += r * get<2>(tests[idx]);
    }
    return sum >= offset;
}

bool check1(int num) {
    int q = num / X, r = num % X;
    assert(q >= 0);
    return true;
    rep(i, N) {
        if (check2(i, q, r)) {
            return true;
        }
    }
    return false;
}

