const int N = 1e5 + 5;
pair<int,pii> p[N];
ll pre[N];
int n, X;

inline bool cmp(const pair<int, pii> &a, const pair<int, pii> &b) {
    return a.fi * 1LL * a.se.fi + a.se.se * 1LL * (X - a.fi) > b.fi * 1LL * b.se.fi + b.se.se * 1LL * (X - b.fi);
}

void solve() {
    sc(n, X);
    ll ans = 0;
    fr(i, 1, n) {
        sc(p[i].fi, p[i].se.fi, p[i].se.se);
        ans += p[i].fi;
    }
    sort(p + 1, p + n + 1, cmp);
    fr(i, 1, n) {
        debug(p[i].fi, p[i].se.fi, p[i].se.se);
    }
    fr(i, 1, n) {
        pre[i] = pre[i - 1] + p[i].se.fi * 1LL * p[i].fi;
    }
    ll tot = 0;
    fr(i, 1, n) {
        ll now = tot - pre[n] + pre[i];
        debug(tot, now);
        int lx = -1, rx = X;
        while(rx - lx > 1) {
            int m = (lx + rx) >> 1;
            if(now + p[i].se.fi * 1LL * (m - p[i].fi) >= 0)
                rx = m;
            else
                lx = m;
        }
        if(now + p[i].se.fi * 1LL * (rx - p[i].fi) >= 0) {
            ans = min(ans, (i - 1) * 1LL * X + rx);
        }
        tot += (X - p[i].fi) * 1LL * p[i].se.se;
    }
    cout << ans;
}

