ll f(ll x, ll sub, T3 blu)
{
        ll takahashi, low = 0, high = x;
        ll b = blu.t0;
        ll l = blu.t1;
        ll u = blu.t2;
        ll ret = x;

        for (takahashi = x / 2 ; low <= high; takahashi = (low + high) / 2) {
                ll nowsub;
                if (takahashi < b) nowsub = (takahashi - b) * l;
                else nowsub = (takahashi - b) * u;
                if (nowsub < sub) {
                        low = takahashi + 1;
                }
                else {
                        high = takahashi - 1;
                        ret = takahashi;
                }
        }

        return x - takahashi;
}

int main()
{
        ll n, x;
        llin(n); llin(x);

        V<T3> blulist;
        llinl3(blulist, n);

        ll takahashi[n];
        rep (i, n) takahashi[i] = (x * blulist[i].t2);
        ll ans = x * n;

        ll aoki_low[n];
        ll aoki_high[n];
        rep (i, n) {
                aoki_low[i] = (blulist[i].t0 * blulist[i].t1);
                aoki_high[i] = (blulist[i].t0 * blulist[i].t2);
        }

        ll nowsub = 0;
        rep (i, n) nowsub += takahashi[i] - aoki_high[i];

        V<T2> sublist;
        rep (i, n) sublist.pb({takahashi[i] - aoki_high[i] + aoki_low[i], i});
        sort(sublist);

        bool checked[n];
        rep (i, n) checked[i] = false;

        rep (i, n) {
                if (nowsub < sublist[i].t0) break;
                nowsub -= sublist[i].t0;
                checked[sublist[i].t1] = true;
                ans -= x;
        }

        ll anssub = 0;
        rep (i, n) {
                if (checked[i]) continue;
                anssub = max(anssub, f(x, takahashi[i] - aoki_high[i] - nowsub,
                                       blulist[i]));
        }

        ans -= anssub;
        cout << ans + 1;

        return 0;
}

