struct S {
    i64 u, l, b;
    S(i64 u, i64 l, i64 b) : u(u), l(l), b(b) {}
};

int main() {
    constexpr i64 inf = std::numeric_limits<i64>::max() / 2;
    i64 n, x;
    std::cin >> n >> x;
    enum { key, upper, lower, score };
    std::vector<S> v;
    for (int i = 0; i < n; i++) {
        i64 b, l, u;
        std::cin >> b >> l >> u;
        v.emplace_back(u, l, b);
    }

    i64 ll = -1, rr = inf;
    while (rr - ll > 1) {
        auto k = (ll + rr) / 2;
        auto r = k % x;

        std::sort(v.begin(), v.end(), [&](S &lhs, S &rhs) {
            auto lp = (x - lhs.b) * lhs.u + lhs.b * lhs.l,
                rp = (x - rhs.b) * rhs.u + rhs.b * rhs.l,
                col = lhs.b < r ? lhs.u : lhs.l,
                cor = rhs.b < r ? rhs.u : rhs.l,
                ld = col * (r - lhs.b) + lhs.l * lhs.b,
                rd = cor * (r - rhs.b) + rhs.l * rhs.b;
            return lp > rp || (lp == rp && ld > rd);
        });

        i64 d = 0;
        for (int i = 0; i < std::min(k / x, n); i++) {
            d += v[i].u * (x - v[i].b);
        }

        i64 t = -inf;
        int j = -1;
        for (i64 i = k / x; i < n; i++) {
            auto co = v[i].b < r ? v[i].u : v[i].l;
            auto tmp = co * (r - v[i].b) + v[i].l * v[i].b;
            if (tmp > t) {
                t = tmp;
                j = i;
            }
            d -= v[i].l * v[i].b;
        }

        if (j >= 0) {
            d += t;
        }

        if (d >= 0) rr = k;
        else ll = k;
    }
    std::cout << rr << std::endl;

    return 0;
}

