    if(rest >= get<1>(test[i])) T += rest * get<3>(test[i]) - get<1>(test[i]) * (get<3>(test[i]) - get<2>(test[i]));
    else T += rest * get<2>(test[i]);
    if(T >= A) return 1;
  }
  return 0;
}

