	ll sum = 0;
	for (int i = 0; i < N; ++i) sum += b[i]*l[i];

	priority_queue<ii> pq;
	for (int i = 0; i < N; ++i) pq.emplace(X*u[i]-b[i]*u[i]+b[i]*l[i], i);

