LL sum,ans,l[mxn],r[mxn],f[mxn];
int n,X,sl,fh,b[mxn],rk[mxn];
int rd()
{
	sl=0;fh=1;
	char ch=getchar();
	while(ch<'0'||'9'<ch) {if(ch=='-') fh=-1; ch=getchar();}
	while('0'<=ch&&ch<='9') sl=sl*10+ch-'0',ch=getchar();
	return sl*fh;
}
bool cmp(const int &x,const int &y) {return f[x]>f[y];}
bool check(LL t)
{
	static LL S,nw;static int x,y;
	nw=sum;x=t/X,y=t%X;
	for(int i=1;i<=x;++i) nw+=f[rk[i]];
	for(int i=x+1;i<=n;++i)
	{
		S=nw;
		if(y<=b[rk[i]]) S+=y*l[rk[i]];
		else S+=b[rk[i]]*l[rk[i]]+(y-b[rk[i]])*r[rk[i]];
		if(S>=0) return 1;
	}
	nw+=f[rk[x+1]];
	for(int i=1;i<=x;++i)
	{
		S=nw-f[rk[i]];
		if(y<=b[rk[i]]) S+=y*l[rk[i]];
		else S+=b[rk[i]]*l[rk[i]]+(y-b[rk[i]])*r[rk[i]];
		if(S>=0) return 1;
	}
	return 0;
}
#define Mid ((L+R)>>1)
int main()
{
	n=rd();X=rd();LL L=0,R=0;
	for(int i=1;i<=n;++i)
	{
		b[i]=rd(),l[i]=rd(),r[i]=rd();R+=b[i];
		f[i]=r[i]*(X-b[i])+b[i]*l[i];rk[i]=i;sum-=b[i]*l[i];
	}
	sort(rk+1,rk+n+1,cmp);
	while(L<=R)
	{
		if(check(Mid)) ans=Mid,R=Mid-1;
		else L=Mid+1;
	}
	printf("%lld\n",ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
using LL = long long;
using PII = pair<int, int>;
#define FI(i, a, b) for (int i = (a); i <= (b); ++i)
#define FD(i, b, a) for (int i = (b); i >= (a); --i)
#define DEBUG(x) cerr << #x << ": " << (x) << endl;

const int N = 1e5 + 5;
int n, x, B[N], L[N], U[N];
LL Gain[N], margin = 0;
map<LL, vector<int>> M;

bool check(LL budget) {
  vector<int> I(n + 1);
  vector<LL> S(n + 1);
  iota(I.begin(), I.end(), 0);
  sort(I.begin() + 1, I.end(), [&](int i, int j) { return Gain[i] > Gain[j]; });
  FI(i, 1, n) S[i] = S[i - 1] + Gain[I[i]];
  int r = budget % x, q = budget / x;
  if (r == 0) {
    return S[q] >= margin;
  }
  LL ans = 0;
  FI(i, 1, n) {
    LL gain;
    if (r <= B[I[i]]) {
      gain = 1LL * L[I[i]] * r;
    } else {
      gain = 1LL * U[I[i]] * (r - B[I[i]]) + 1LL * L[I[i]] * B[I[i]];
    }
    gain += S[min(i - 1, q)];
    if (q + 1 > i) gain += S[q + 1] - S[i];
    ans = max(ans, gain);
  }
  return ans >= margin;
}

int main() {
  cin >> n >> x;
  FI(i, 1, n) scanf("%d%d%d", &B[i], &L[i], &U[i]);
  FI(i, 1, n) margin += 1LL * L[i] * B[i];
  FI(i, 1, n) Gain[i] = 1LL * U[i] * (x - B[i]) + 1LL * L[i] * B[i];
  FI(i, 1, n) M[Gain[i]].push_back(i);
  LL l = 0, r = 1LL * x * n;
  while (l + 1 < r) {
    LL m = (l + r + 1) / 2;
    if (check(m))
      r = m;
    else
      l = m;
  }
  cout << r << endl;
}

