int N, X;

struct Test {
    int b;
    int l;
    int u;

    Test(int b, int l, int u) : b(b), l(l), u(u) {}

    int maxGain() const {
        return u * (X - b);
    }

    int loss() const {
        return l * b;
    }

    bool operator< (const Test &a) const {
        return maxGain() + loss() < a.maxGain() + a.loss();
    }
};

vector<Test> tests;

int f(int idx, int left) {
    int ret = X;

    REP(i, idx, N - 1) {
        left -= tests[i].b * tests[i].l;

        int low = 0;
        int high = X;
        int mid = (low + high) / 2;
        while (high - low > 1) {
            int gain = (mid - tests[i].b) * tests[i].l;
            if (gain >= left) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high) / 2;
        }
        ret = min(ret, mid);

        left += tests[i].b * tests[i].l;
    }

    // cerr << " ret:" << ret << endl;
    return ret;
}

