    //}

    int left = 0;
    rep(i, N) {
        left += tests[i].b * tests[i].l;
    }

    int ret = 0;
    rep(i, N) {
        left -= tests[i].b * tests[i].l;

        int maxGain = tests[i].maxGain();
        // cerr << "i:" << i << " maxGain:" << maxGain << " left:" << left << endl;
        if (maxGain < left) {
            left -= maxGain;
            ret += X;
