int B[100002];
int L[100002];
int U[100002];

struct Test {
  int i; long long mx;

  bool operator< (Test &r) {
    return mx > r.mx;
  }
};

Test p[100002];
bool vs[100002];

int main(){
  int N, X; scanf("%d%d", &N, &X);

  for(int i = 1; i <= N; i++){
    scanf("%d%d%d", &B[i], &L[i], &U[i]);
  }

  long long now = 0;

  for(int i = 1; i <= N; i++){
    now -= 1LL * L[i] * B[i];
  }

  for(int i = 1; i <= N; i++){
    long long maxScore = 1LL * L[i] * B[i] + 1LL * U[i] * (X - B[i]);
    p[i] = { i, maxScore };
  }

  sort(p + 1, p + N + 1);

  long long ans = 0;

  for(int i = 1; i <= N; i++){
    if(now + p[i].mx < 0){
      ans += X; now += p[i].mx; vs[p[i].i] = true;
    }
    else break;
  }

  int lst = X;

  for(int i = 1; i <= N; i++){
    if(vs[i]) continue;

    if(now + 1LL * L[i] * B[i] >= 0){
      int res = (L[i] - 1 - now) / L[i];
      if(res < lst) lst = res;
    }
    else if(now + 1LL * L[i] * B[i] + 1LL * U[i] * (X - B[i]) >= 0){
      int res = B[i] + (U[i] - now - 1LL * L[i] * B[i] - 1) / U[i];
      if(res < lst) lst = res;
    }
  }

  printf("%lld\n", ans + lst);
  return 0;
