inline bool f(long long mid) {
    long long s = 0;
    vector<pair<long long, long long> > v;
    for (int i = 1; i <= n; ++i) {
        long long cur = a[i].first * b[i];
        s -= cur;
        cur += max(a[i].first * (mx - b[i]), a[i].second * (mx - b[i]));
        long long cur2 = a[i].first * b[i];
        cur2 += max(a[i].first * (mid % mx - b[i]), a[i].second * (mid % mx - b[i]));
        v.push_back({cur, cur2});
    }
    sort(v.begin(), v.end(), cmp);
    int cnt = (mid / mx);
    cnt = min(cnt, n);
    long long ss = s;
    for (int i = 0; i <= cnt && i < n; ++i) {
        if (i < cnt) ss += v[i].first;
        else ss += v[i].second;
    }
    if (ss >= 0) return true;
    ss = s;
    long long mx = -1e18;
    for (int i = 0; i < cnt; ++i) {
        ss += v[i].first;
        mx = max(mx, v[i].second - v[i].first);
    }
    ss += mx;
    if (cnt < n) ss += v[cnt].second;
    return (ss >= 0);
}

