ll N, X;
vector<tuple<ll, ll, ll, ll, ll>> sbluS;
ll lowerScore;


ll Smax(ll x){
	ll m = x / X;
	ll xx = x % X;

	ll smax = -INF;
	REP(i, N){
		ll s = get<0>(sbluS[i]);
		ll b = get<1>(sbluS[i]);
		ll l = get<2>(sbluS[i]);
		ll u = get<3>(sbluS[i]);

		ll score_i = (xx < b) ? l*xx : u*(xx-b)+l*b;

		ll sumScore = lowerScore;
		if (m > 0){
			sumScore += (i >= m) ? get<4>(sbluS[m-1]) : get<4>(sbluS[m])-s;
		}
		chmax(smax, sumScore + score_i);
	}
	return smax;
}

void solve()
{
	cin >> N >> X;
	auto blu = cinv3(N);

	sbluS.resize(N);

	lowerScore = 0;
	REP(i, N){
		ll b = get<0>(blu[i]);
		ll l = get<1>(blu[i]);
		ll u = get<2>(blu[i]);
		lowerScore -= l*b;
	}

	REP(i, N){
		ll b = get<0>(blu[i]);
		ll l = get<1>(blu[i]);
		ll u = get<2>(blu[i]);
		get<0>(sbluS[i]) = u*(X-b)+l*b;
		get<1>(sbluS[i]) = b;
		get<2>(sbluS[i]) = l;
		get<3>(sbluS[i]) = u;
	}
	std::sort(sbluS.begin(), sbluS.end(),
		[](auto &a, auto &b) {return a > b; }
	);

	REP(i, N){
		ll s = get<0>(sbluS[i]);
		if (i == 0) get<4>(sbluS[i]) = s;
		else        get<4>(sbluS[i]) = get<4>(sbluS[i-1]) + s;
	}

	ll ok = N*X, ng = -1;
	while (std::abs(ok - ng) > 1){
		ll mid = (ok + ng)/2;
		ll score = Smax(mid);
		if (score >= 0) ok = mid;
		else ng = mid;
	}

	cout << ok << '\n';
}

int main(){
	solve();
	return 0;
}

