/*!* [binsearch] *!*/
/*+* 二分探索 *+*/
// judge を満たすような下限を求める
// l:[X] 定義域外部の上限
// r:[X] 定義域外部の下限
// judge:[F = X -> bool] 値 X を評価する関数
// lower:[bool] false にすると代わりに上限を求める
// eps:[X] 終了距離

template <typename X, typename F>
X BinSearch(X l, X r, F judge, bool lower = true, X eps = 1) {
    while (r - l > eps) {
        X m = (r + l) / 2;
        if (judge(m) == lower) {
            r = m;
        } else {
            l = m;
        }
    }
    return lower ? r : l;
}

struct Data {
    i64 b, l, u;
};

using ValIdx = pair<i64, int>;

int main() {
    const i64 INF = 1e14;
    i64 N, X;
    cin >> N >> X;
    vector<Data> data(N);
    for(Data &d : data) {
        cin >> d.b >> d.l >> d.u;
    }

    vector<ValIdx> P;
    i64 S = 0;

    for(int i = 0; i < N; i++) {
        Data d = data[i];
        P.push_back({d.u * (X - d.b) + d.l * d.b, i});
        S += d.l * d.b;
    }

    // O(N log N)
    sort(REV_WHOLE(P));

    // O(N log NX)
    i64 ans = BinSearch<i64>(0, N * X, [&](i64 A) -> bool {
        // O(N)
        // (sum of a_i) <= A ?

        // evaluation of the inequation
        i64 e = 0;

        i64 m = A / X;
        i64 r = A - m * X;
        vector<bool> used(N, false);
        for(int i = 0; i < m; i++) {
            i64 v, p;
            tie(v, p) = P[i];
            e += v;
            used[p] = true;
        }
        {
            i64 v = -INF, p;
            for(int i = 0; i < N; i++) {
                if(used[i]) continue;
                Data d = data[i];
                for(i64 c : {d.l, d.u}) {
                    i64 v_ = c * (r - d.b) + d.l * d.b;
                    if(v_ >= v) {
                        v = v_;
                        p = i;
                    }
                }
            }
            e += v;
            used[p] = true;
        }
        e -= S;
        return e >= 0;
    });
    cout << ans << endl;
    return 0;
}

