int n,x;
bool less2(int a,int b)
{
	return calc[a]>calc[b];
}
inline ll check(ll K)
{
	int num=(int)(K/(1ll*x));
	int rem=(int)(K%x);
	ll res=-1,tmp;
	int j;
//	cout<<K<<" "<<num<<" "<<rem<<endl;
	for(int i=0;i<n;i++)
	{
		tmp=base;
		j=od[i];
		tmp+=li[j]*1ll*bi[j];
		if(rem>=bi[j])
		{
			tmp+=ri[j]*1ll*(rem-bi[j]);
		}
		else
		{
			tmp-=li[j]*1ll*(bi[j]-rem);
		}
		if(i<num)
		{
			tmp+=presum[num+1];
			tmp-=calc[j];
		}
		else
		{
			tmp+=presum[num];
		}
	//	cout<<res<<" "<<tmp<<endl;
		res=max(res,tmp);
	}
//	system("pause");
	return res;
}
