bool is_ok(ll mid){
	ll k=mid/x, k2=mid%x, tmp=0;
	FORR(i, max(0ll, n-k), n){
		tmp+=a[i].first;
	}
	ll ma=0;
	FORR(i, 0, max(0ll, n-k)){
		int j=a[i].second;
		CHMAX(ma, u[j]*k2-(u[j]-l[j])*k2);
		CHMAX(ma, l[j]*k2);
	}
	if(tmp+ma>=sum){
		return true;
	}
	ll mi=1e12;
	FORR(i, max(0ll, n-k), n){
		int j=a[i].second;
		CHMIN(mi, u[j]*(x-k2));
		CHMIN(mi, u[j]*x-l[j]*k2-(u[j]-l[j])*b[j]);
	}
	tmp-=mi;
	if(n-k>0){
		tmp+=a[n-k-1].first;
	}
	return tmp>=sum;
}

