using ll=long long ;
struct test{
  int id;
  ll b;
  ll l;
  ll u;

  ll get_plus(ll X)const{
    return (X-b)*u+l*b;
  }

  ll get_time(ll rest)const {
    if(b*l>=rest){
      return (rest-1)/l+1;
    }else{
      ll ans=b;
      rest-=b*l;
      return b+(rest-1)/u+1;
    }
  }
};

void solve(){
  int N;
  ll X;
  cin>>N>>X;
  vector<test>tests;

  ll rest=0;
  for(int i=0;i<N;++i){
    ll b,l,u;cin>>b>>l>>u;
    tests.push_back(test{i,b,l,u});
    rest+=b*l;
  }
 // cout<<rest<<endl;
 for(int i=0;i<tests.size();++i){
    //cout<<tests[i].get_plus(X)<<endl;
  }
  sort(tests.begin(),tests.end(),[&](const test&l,const test&r){
    ll l_plus=l.get_plus(X);
    ll r_plus=r.get_plus(X);
    return l_plus<r_plus;
  });

  ll answer=0;
  int id=tests.size()-1;
  while(true){
    if(id==-1)break;
    auto atest=tests[id];
    //cout<<atest.id<<endl;
    ll plus=atest.get_plus(X);
    if(rest>=plus){
      rest-=plus;
      answer+=X;
    }else{
      break;
    }
    id--;
  }
  //cout<<tests.size()<<endl;
  if(rest){
    //cout<<rest<<endl;
    //cout<<answer<<endl;
    ll min_time=1e18;
    assert(!tests.empty());
    for(int i=0;i<=id;++i){
      min_time=min(min_time,tests[i].get_time(rest));
      //cout<<tests[i].id<<" "<<tests[i].get_time(rest)<<endl;
    }
    if(id!=-1){
      auto atest=tests[id];
      //cout<<atest.id<<endl;
      ll plus=atest.get_plus(X);
      rest-=plus;

      assert(rest<0);
      for(int x=id;x<tests.size();++x){
        ll arest=rest+tests[x].get_plus(X);

        min_time=min(min_time,tests[x].get_time(arest));
      }
    }

    answer+=min_time;

  }

  cout<<answer<<endl;
}

int main(void){
  solve();


  return 0;
}

