          //中途半端な獲り方は高々１通りしかありえない
       ll cnt = mid;
      //利得差がでかいものから獲得していく
       vector<ll> vec; pair<ll,ll> r;
       while( cnt >= X){
        ll p = Q.top().first; ll q = Q.top().second; Q.pop();
        vec.push_back(q);} // q番目の科目は満点を目指す
       r = Q.top(); Q.pop(); //残った半端な時間cntをrに配分する
