        return 1LL * b * l + 1LL * (x - b) * u;
    }

    long long partial(long long a) {
        if (a <= b)
            return 1LL * a * l;
        else
            return 1LL * b * l + 1LL * (a - b) * u;
    }

    bool operator < (const Exam &other) const {
        return total() > other.total();
    }
};

