        sum[i] = sum[i - 1] + v[i].total();
    long long left = 0, right = 1LL * n * x, answer = 1LL * n * x;
    while (left <= right) {
        long long middle = (left + right) / 2;
        if (check(n, limit, middle)) {
            answer = middle;
            right = middle - 1;
        }
        else
            left = middle + 1;
    }
    cout << answer << "\n";
    return 0;
}

