typedef long long ll;
const ll maxn = 100000 + 10;
const ll DEBUG = 1;

ll n, X;
struct anode{
	ll b, l, r;
	anode() {}
	anode(ll _b, ll _l, ll _r):b(_b), l(_l), r(_r) {}
}a[maxn];

inline bool check(ll k) {
	ll t1 = k / X;
	ll t2 = k % X;
	ll tmp = 0;
	for(ll i = 1;i <= t1;i ++) {
		tmp = (ll)tmp + (X - a[i].b) * a[i].r;
	}
	for(ll i = t1 + 2;i <= n;i ++) {
		tmp = (ll)tmp - (ll)a[i].b * a[i].l;
	}
	if(t2 > a[t1 + 1].b) tmp = (ll)tmp + (t2 - a[t1 + 1].b) * a[t1 + 1].r;
	else tmp = (ll)tmp - (a[t1 + 1].b - t2) * a[t1 + 1].l;
	return tmp >= 0;
}

inline bool cmp(anode a, anode b) {
	ll t1 = (ll)(X - a.b) * a.r + (ll)a.b * a.l;
	ll t2 = (ll)(X - b.b) * b.r + (ll)b.b * b.l;
	return t1 > t2;
}

int main() {
//	freopen("data.in","r",stdin);
	scanf("%lld%lld", &n, &X);
	for(ll i = 1;i <= n;i ++) {
		ll x, y, z;
		scanf("%lld%lld%lld", &x, &y, &z);
		a[i] = anode(x,y,z);
	}
	sort(a + 1,a + n + 1,cmp);
	ll L = 0, R = 1LL * X * n, Ans = -1;
//	if(DEBUG) check(2540);
	while(L <= R) {
		ll mid = (L + R) / 2;
		if(check(mid)) R = mid - 1, Ans = mid;
		else L = mid + 1;
	}
	printf("%lld\n", Ans);
	return 0;
}

