void sortVecPair(vector<auto>& X, VI& idx, auto comparator) {
    VI idx2(SZ(idx));
    iota(ALL(idx2), 0);
    stable_sort(ALL(idx2), comparator);
    SORT(X);
    REP(i, SZ(idx)) idx2[i] = idx[idx2[i]];
    REP(i, SZ(idx)) idx[i] = idx2[i];
}

int main() {
    LL N, X;
    cin >> N >> X;
    VI b(N), l(N), u(N), loss(N), gain(N), s(N);
    LL s_loss = 0, s_gain = 0;
    //cout << endl;
    REP(i, N) {
        cin >> b[i] >> l[i] >> u[i];
        loss[i] = b[i] * l[i];
        gain[i] = (X - b[i]) * u[i];
        s[i] = loss[i] + gain[i];
        s_loss += loss[i];
        //cout << i << ": " << loss[i] << " " << gain[i] << endl;
    }

    VI idx(SZ(s));
    iota(ALL(idx), 0);
    sortVecPair(s, idx, [&] (auto& i, auto& j) {return s[i] > s[j];});
    SORT(s);

    LL ans = 0;
    REP(i, N) {
        LL next = idx[i];
        //$(next);
        if (s_loss - loss[next] <= s_gain + gain[next]) {
            /*cout << "last" << endl;
            $(s_loss);
            $(s_gain);*/
            LL s_diff = s_loss - s_gain;
            //$(s_diff);
            if (s_diff <= loss[next]) {
                ans += (LL)ceil((double)s_diff / l[next]);
            } else {
                ans += b[next] + (LL)ceil((double)(s_loss - loss[next]) / u[next]);
            }
            break;
        } else if (s_loss - loss[next] > s_gain + gain[next]) {
            //cout << "full" << endl;
            ans += X;
            s_loss -= loss[next];
            s_gain += gain[next];
        } else {
            break;
        }
    }
	cout << ans << endl;
    return 0;
}

