        return 1LL * b * l + 1LL * (x - b) * r;
    }
} a[N];

long long get_max(long long u) {
    int cnt = u / x;
    long long pre = 0, mx = 0;
    for (int i = 1; i <= cnt; i++) {
        pre += a[i].val();
    }
    u %= x;
    for (int i = 1; i <= n; i++) {
        long long cur = pre;
        if (i <= cnt) {
            cur -= a[i].val();
            cur += a[cnt + 1].val();
        }
        mx = max(mx, cur + min(1LL * a[i].b, u) * a[i].l + max(0LL, u - a[i].b) * a[i].r);
    }
    return mx;
}

