int chk(int w,int lim){
	if(!(w%x))return s[w/x]>=lim;
	int w1=w/x,w2=w%x;
	for(int i=1;i<=n;++i){
		int v=max(a[i].l*w2,a[i].r*w2-(a[i].r-a[i].l)*a[i].a);
		int val=v+(i<=w1?s[w1+1]-a[i].w:s[w1]);
