	vector<P> sum(n);
	rep(i, 0, n) {
		ll add;
		if (q >= b[i]) add = b[i] * l[i] + (q - b[i]) * u[i];
		else add = q * l[i];
		sum[i] = { l[i] * b[i] + (x - b[i]) * u[i],add };
