            else
                a = (bs-l[i]*b[i] - 1) / u[i] + 1 + b[i];
            //printf("%lld\n", a);
            if(a<k){
                k = a;
            }
        }
    }
    if(k!=INF){
        ans += k;
    }
    printf("%lld", ans);
    return 0;
}

