        i.first = i.second.first * i.second.second.first + (X - i.second.first) * i.second.second.second;
    }
    sort(lu.rbegin(), lu.rend());
    auto f = [&lu, &X](auto x){
        unsigned long ret{0};
        for(const auto& i : lu)if(i.first > x)ret += i.first;
        else if(i.second.second.first * X > x)ret += i.second.first * i.second.second.first;
        return ret;
    };
    unsigned long l = 0, r = numeric_limits<unsigned long>::max() / 5;
    while(l + 1 < r){
        auto m = (r + l) / 2;
        (f(m) < tap ? r : l) = m;
    }
    unsigned long ret{0}, ans{0};
    for(const auto& i : lu){
        if(i.first > r){
            ret += i.first;
            ans += X;
        }else if(i.second.second.first * X > r){
            ret += i.second.first * i.second.second.first;
            ans += i.second.first;
        }
    }
    unsigned long tmp{numeric_limits<unsigned long>::max()};
    for(const auto& i : lu)if(i.first <= r){
        if(i.second.second.first * X > r){
            if((X - i.second.first) * i.second.second.second + ret >= tap)tmp = min(tmp, (tap - ret + i.second.second.second - 1) / i.second.second.second);
        }else{
            if(i.second.first * i.second.second.first + ret >= tap)tmp = min(tmp, (tap - ret + i.second.second.first - 1) / i.second.second.first);
            else if(i.first + ret >= tap)tmp = min(tmp, i.second.first + (tap - ret - i.second.first * i.second.second.first + i.second.second.second - 1) / i.second.second.second);
        }
    }
    cout << ans + tmp << endl;
    return 0;
}

