  rep (i, n) {
    scan(b[i], l[i], u[i]);
  }

  ll debt = 0;
  rep (i, n) {
    debt += b[i] * l[i];
  }

  vvll pred(n, vll(5));
  rep (i, n) {
    pred[i][0] = b[i] * l[i] + (x - b[i]) * u[i];
    pred[i][1] = i;
    pred[i][2] = b[i];
    pred[i][3] = l[i];
    pred[i][4] = u[i];
  }
  sort(all(pred), greater<vll>());
  debug(pred);

  int ind = -1;
  ll ans = 0;
  ll taka = 0;
  rep (i, n) {
    if (taka + pred[i][0] < debt) {
      taka += pred[i][0];
      ans += x;
    } else {
      ind = i;
      break;
    }
  }

  if (ind > 0) {
    assert(pred[ind-1][0] != pred[ind][0]);
  }

  assert(ind >= 0);
  ll rest = debt - taka;
  debug(ans);
  debug3(debt, taka, rest);
  ll rest_min = x;
  FOR (i, ind, n) {
    if (pred[i][0] < rest) {
