bool check(int n, long long limit, long long taken) {
    if (1LL * n * x == taken)
        return sum[n] >= limit;
    long long r = taken % x, c = taken / x;
    bool found = false;
    for (int i = 1; i <= n; i++)
        if (i <= c)
            found |= sum[c + 1] - v[i].total() + v[i].partial(r) >= limit;
        else
            found |= sum[c] + v[i].partial(r) >= limit;
    return found;
}

