		cin >> a[i].b >> a[i].l >> a[i].u;
		p.push(C{ i,(x - a[i].b) * a[i].u });
		res += a[i].b * a[i].l;
	}
	int sum = 0, rer = 0;
	while (res > sum) {
		C t = p.top(); p.pop();
		int k = sum + a[t.pos].u * x;
		int r = res + a[t.pos].b * (a[t.pos].u - a[t.pos].l);
		if (r > k) {
			sum += a[t.pos].u * x;
			res += a[t.pos].b * (a[t.pos].u - a[t.pos].l);
			b[t.pos] = 1;
			rer += x;
		}
		else break;
	}
	int ok = x, ng = 0, t;
	while (ok - ng > 1) {
