		for (int i = 0; i < n; i++) {
			if (b[i]) continue;
			if ((t - a[i].b) * a[i].u >= res - a[i].b * a[i].l - sum) {
				ok = t;
				goto loop;
			}
			if ((t - a[i].b) * a[i].l >= res - a[i].b * a[i].l - sum) {
				ok = t;
				goto loop;
			}
		}
		ng = t;
	loop:;
	}
	cout << rer + ok << endl;
}

