int n,x;
struct Task
{
    ll b,l,r;
    ll merit()const
    {
        return (x-b)*r + b * l;
    }
    ll pure_merit()const
    {
        return (x-b)*r;
    }
    bool operator<(const Task& o)const
    {
        return o.merit()<merit();
    }
};
ll solve(int n,int x,vector<Task> tasks)
{
    ll ret = 0;
    sort(tasks.begin(),tasks.end());
    ll sum = 0;
    for(int i=0;i<n;++i)
        sum += tasks[i].l * tasks[i].b;
    int p;
    for(int i=0;i<n;++i)
    {
        if(sum - tasks[i].merit() <= 0)
        {
            p = i;
            break;
        }
        sum -= tasks[i].merit();
        ret += x;
    }
    ll min_add = INT_MAX;
    for(int i=p;i<n;++i)
    {
        ll num = sum / tasks[i].l + (sum % tasks[i].l > 0);
        if(num > tasks[i].b)
        {
            ll sum_tmp = sum + (tasks[i].r-tasks[i].l) * tasks[i].b;
            num = sum_tmp / tasks[i].r + (sum_tmp % tasks[i].r > 0);
        }
        min_add = min(min_add, num);
    }
    return ret + min_add;
}
