    return (x-b[i])*u[i];
  } else {
    return (x-b[i])*l[i];
  }
}

bool check(ll sumX) {
  ll p = sumX/X; // X点を取るテストの数
  ll r = N-p-1;  // 0点を取るテストの数
  ll q = sumX%X; // 1個のテストは、q点を取る

  vector<PLL> v(N); // {0点とX点での得点差、ID}
  for (int i=0; i<N; i++) {
    v[i] = make_pair(diff(i,X) - diff(i,0), i);
  }
  sort(begin(v),end(v));

  set<ll> smallIDs, largeIDs;

  // 0点をr個取る
  for (int i=0; i<r; i++) {
    smallIDs.insert(v[i].second);
  }

  // X点をp個取る
  for (int i=N-p; i<N; i++) {
    largeIDs.insert(v[i].second);
  }

  ll sumDiff = 0;
  for (auto id : largeIDs) {
    sumDiff += diff(id, X);
  }
  for (auto id : smallIDs) {
    sumDiff += diff(id, 0);
  }

  // p点を1回とる
  sumDiff += diff(v[r].second, q);

  for (int i=0; i<N; i++) {
    // i番目のテストでq点を取る。 v[r].second目と入れ替え
    ll ss = sumDiff;
    if (smallIDs.find(i) != smallIDs.end()) {
      ss += diff(i, q)           - diff(i, 0);
      ss += diff(v[r].second, 0) - diff(v[r].second, q);
    } else if (largeIDs.find(i) != largeIDs.end()) {
      ss += diff(i, q)           - diff(i, X);
      ss += diff(v[r].second, X) - diff(v[r].second, q);
