template <class T, class U>
inline bool chmin(T& lhs, const U& rhs) {
  if (lhs > rhs) {
    lhs = rhs;
    return true;
  }
  return false;
}

template <class T, class U>
inline bool chmax(T& lhs, const U& rhs) {
  if (lhs < rhs) {
    lhs = rhs;
    return true;
  }
  return false;
}

// [l, r) from l to r
struct range {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { ++i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr l, r;
  constexpr range(int l_, int r_): l(l_), r(std::max<int>(l_, r_)) { }
  constexpr itr begin() const { return l; }
  constexpr itr end() const { return r; }
};

// [l, r) from r to l
struct revrange {
  struct itr {
    int i;
    constexpr itr(int i_): i(i_) { }
    constexpr void operator ++ () { --i; }
    constexpr int operator * () const { return i; }
    constexpr bool operator != (itr x) const { return i != x.i; }
  };
  const itr r, l;
  constexpr revrange(int l_, int r_): l(l_ - 1), r(std::max<int>(l_, r_) - 1) { }
  constexpr itr begin() const { return r; }
  constexpr itr end() const { return l; }
};

template <class T>
inline T scan() {
  T res;
  std::cin >> res;
  return res;
}

int main() {
  const int N = scan<int>();
  const long long X = scan<long long>();
  long long worst = 0;
  std::vector<long long> aoki(N), lb(N), ub(N), get(N);
  for (int i: range(0, N)) {
    std::cin >> aoki[i] >> lb[i] >> ub[i];
    get[i] = lb[i] * aoki[i] + ub[i] * (X - aoki[i]);
    worst += lb[i] * aoki[i];
  }
  std::vector<int> order(N);
  std::iota(order.begin(), order.end(), 0);
  std::sort(order.begin(), order.end(), [&](int i, int j) {
    if (get[i] == get[j]) {
      return i < j;
    }
    return get[i] > get[j];
  });
  std::vector<long long> sum(N + 1);
  for (int i: range(0, N)) {
    sum[i + 1] = sum[i] + get[order[i]];
  }
  const auto score = [&](int i, long long p) {
    if (p > aoki[i]) {
      return ub[i] * (p - aoki[i]) + lb[i] * aoki[i];
    }
    return lb[i] * p;
  };
  long long ok = X * N, ng = -1;
  while (ok - ng > 1) {
    long long md = (ok + ng) / 2;
    ([&] {
      long long full = md / X, remain = md % X;
      long long max = 0;
      for (int i: range(0, N)) {
        int t = order[i];
        if (i < full) {
          chmax(max, sum[full + 1] + score(t, remain) - get[t]);
        }
        else {
          chmax(max, sum[full] + score(t, remain));
        }
      }
      return max >= worst;
    }() ? ok : ng) = md;
  }
  std::cout << ok << '\n';
  return 0;
}

