struct apple{
    long long b,l,r;
}no[N];
long long n,X;
bool cmp(apple a,apple b)
{
    return a.l*a.b+a.r*(X-a.b)>b.l*b.b+b.r*(X-b.b);
}
int judge(long long x)
{
    int i,cnt=0;
    long long ans=0,nowans,now;
    //cout<<x<<endl;
    for(i=1;i<=n;i++)
    {
        if(x<X)
            break;
        ans+=(X-no[i].b)*no[i].r;
        x-=X;
        cnt++;
    }
    for(i=cnt+1;i<=n;i++)
        ans-=no[i].b*no[i].l;
    nowans=ans;
    for(i=cnt+1;i<=n;i++)
    {
        if(x<no[i].b)
            now=ans+no[i].l*x;
        else
            now=ans+no[i].b*no[i].l+(x-no[i].b)*no[i].r;
        nowans=max(nowans,now);
    }
    //cout<<cnt<<endl;
   // cout<<x<<" "<<ans<<" "<<now<<" "<<nowans<<endl;
    if(nowans>=0)
        return 1;
    return 0;
}
int main()
{
    int i;
    long long l,r;
    cin>>n>>X;
    for(i=1;i<=n;i++)
        cin>>no[i].b>>no[i].l>>no[i].r;
    sort(no+1,no+n+1,cmp);
    l=mina;
    r=maxa;
    while(r-l>1)
    {
        long long midd=(l+r)/2;
        if(judge(midd))
            r=midd;
        else
            l=midd;
    }
    cout<<r;
    return 0;
}

