bool check(ll md){
	ll ret = 0, rem = md % x, quo = md / x;
	REP(i, 1, n){
		ll res = 0;
		if(rem >= t[i].b)
			res += 1ll * t[i].b * t[i].l + (rem - t[i].b) * t[i].r;
		else
			res += rem * t[i].l;
		//printf("md = %lld i = %d res = %lld\n", md, i, res);
		if(i > quo)
			res += sum[quo];
		else
			res += sum[quo + 1] - t[i].v;
		//printf("md = %lld i = %d res = %lld\n", md, i, res);
		if(res + aoki >= 0)
			return true;
	}
	return false;
}

