bool C(ll mid){
  ll q=mid/X,r=mid%X;
  ll tkhs=0,aok=0;
  for(ll i=0;i<q;i++){
    ll b=p[i].first,u=p[i].second.second;
    tkhs+=u*X;aok+=u*b;
  }
  for(ll i=q;i<N;i++){
    ll b=p[i].first,l=p[i].second.first;
    aok+=l*b;
  }
  bool f=false;
  ll bq=p[q].first,lq=p[q].second.first,uq=p[q].second.second;
  for(ll i=0;i<N;i++){
    ll b=p[i].first,l=p[i].second.first,u=p[i].second.second;
    if(i<q){
      if(r>=b){
	if(tkhs-u*(X-r)+uq*X>=aok+(uq-lq)*bq){
	  f=true;
	  break;
	}
      }
      else{
	if(tkhs+l*r-u*X+uq*X>=aok+b*(l-u)+(uq-lq)*bq){
	  f=true;
	  break;
	}
      }
    }
    else{
      if(r>=b){
	if(tkhs+r*u>=aok+(u-l)*b){
	  f=true;
	  break;
	}
      }
      else{
	if(tkhs+r*l>=aok){
