					add = max(add, tmp);
				}
				else {
					add = max(add, exam[i].get(mid%K));
				}
			}
			sum += add;
		}
		//	cout <<mid<<" "<< sum << endl;
		if (sum < 0)L = mid;
		else R = mid;
	}
	cout << R << endl;
}

