int N;
LL Z;
LL B[114514];
LL L[114514];
LL U[114514];
priority_queue<pll> que;

signed main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);

  cin >> N >> Z;

  LL target = 0;
  rep(i, N) {
    cin >> B[i] >> L[i] >> U[i];
    target += B[i] * L[i];
    que.push(pll(U[i]*(Z-B[i]) + B[i]*L[i], i));
  }

  LL cur = 0;
  LL ans = 0;
  vector<int> cons;
  LL prex = -1;
  while (!que.empty()) {
    pll p = que.top(); 
    if (cur + p.X >= target) {
      LL rem = target - cur;
      LL mc = MOD;
      while (!que.empty()) {
        pll q = que.top(); que.pop();
        if (q.X < rem) continue;
        int i = q.Y;
        if (B[i]*L[i] >= rem) {
          MN(mc, rem/L[i] + (rem%L[i] != 0));
        } else {
          LL z = rem-B[i]*L[i];
          MN(mc, B[i] + z/U[i] + (z%U[i] != 0));
        }
      }

      if (prex == p.X) {
        for (int i : cons) {
          if (B[i]*L[i] >= rem) {
            MN(mc, rem/L[i] + (rem%L[i] != 0));
          } else {
            LL z = rem-B[i]*L[i];
            MN(mc, B[i] + z/U[i] + (z%U[i] != 0));
          }
        }
      }

      assert(mc != MOD);
      ans += mc;
      cur = target;
      break;
    } else {
      ans += Z;
      cur += p.X;
    }
    if (prex != p.X) cons.clear();
    cons.eb(p.Y);
    prex = p.X;
    que.pop();
  }
  assert(cur >= target);
  cout << ans << endl;
}

