#define int long long

struct exam {
    int b, l, u, x;

    int potential() const {
        return l*b + u*(x-b);
    }

    bool operator<(const exam& other) const {
        return potential() > other.potential();
    }
};

bool ok(vector<exam>& exams, int hours, int n, int x, int ib) {
    int k = hours/x;
    int r = hours%x;

    int tot = 0;
    for(int i = 0; i < k; ++i) {
        tot += exams[i].potential();
    }
    if(r == 0) return tot;

    int ans = 0;
    for(int i = 0; i < n; ++i) {
        int cand = 0;
        cand = max(r - exams[i].b, 0LL)*exams[i].u + min(r, exams[i].b)*exams[i].l;
        if(i < k) {
            ans = max(ans, tot - exams[i].potential() + cand + exams[k+1].potential());
        } else {
            ans = max(ans, tot + cand);
        }
    }

    return ans >= ib;
}

