LL sum[maxn];
int rk[maxn];

LL tot;

int cmp(int x, int y)
{
    return sum[x] > sum[y];
}

bool vis[maxn];

int gao(LL score)
{
    LL tmp = tot;

    for(int i = 0; i < n; i++) vis[i] = 0;

    for(int i = 0; i < n && score >= x; i++)
    {
        int id = rk[i];

        score -= x;
        vis[id] = 1;
        tmp += sum[id];
    }

    LL mx = 0;
    for(int i = 0; i < n; i++)
    {
        if(vis[i]) continue;

        LL t = 0;
        if(score >= B[i]) t = (score - B[i]) * R[i] + B[i] * L[i];
        else t = score * L[i];

        mx = max(mx, t);
    }

    tmp += mx;
    return tmp >= 0;
}

