vector<pair<ll, int>> uX(100010, {-INFL, -1});

bool win(ll sum){
  ll Tsum = 0;
  int cnt = 0;
  while(sum >= X && cnt < N){
    Tsum += uX[cnt].first;
    cnt++;
    sum -= X;
    if(Tsum >= Asum){
      return 1;
    }
  }
  vector<int> xs;
  for(int i = cnt; i < N; i++){
    xs.push_back(uX[i].second);
  }
  ll rest = Asum - Tsum;
  for(int i = 0; i < xs.size(); i++){
    int I = xs[i];
    ll r = rest;
    r -= sum * l[I];
    if(r <= 0) return 1;
    r -= (sum - B[I]) * (u[I] - l[I]);
    if(r <= 0) return 1;
  }
  return 0;

}

