#include <bits/stdc++.h>

typedef long long LL;
const int N = 100010;

struct Node {
	LL l, r, b, h;
	inline bool operator < (const Node &w) const {
		return h > w.h;
	}
}node[N];

LL X, D, sum[N];
int n;

inline LL cal(LL a, LL i) {
	if(a <= node[i].b) {
		return a * node[i].l;
	}
	return node[i].b * node[i].l + (a - node[i].b) * node[i].r;
}

inline bool check(LL k) {
	LL ans = 0, r = k % X, t = k / X;
	if(t >= n) {
		return sum[n];
	}
//	printf("r = %lld t = %lld \n", r, t);
	for(int i = 1; i <= n; i++) {
		if(i <= t) ans = std::max(ans, cal(r, i) + sum[t + 1] - node[i].h);
		else {
			ans = std::max(ans, cal(r, i) + sum[t]);
		}
	}
	//printf("k = %lld ans = %lld D = %lld \n", k, ans, D);
	return ans >= D;
}

int main() {

	scanf("%d%lld", &n, &X);
	for(int i = 1; i <= n; i++) {
		scanf("%lld%lld%lld", &node[i].b, &node[i].l, &node[i].r);
		node[i].h = node[i].b * node[i].l + (X - node[i].b) * node[i].r;
		D += node[i].b * node[i].l;
	}
	std::sort(node + 1, node + n + 1);
	for(int i = 1; i <= n; i++) {
		sum[i] = sum[i - 1] + node[i].h;
	}
	LL l = 0, r = 4e18;
	while(l < r) {
		LL mid = (l + r) >> 1;
		if(check(mid)) {
			r = mid;
		}
		else {
			l = mid + 1;
		}
	}
	printf("%lld\n", r);
	return 0;
}

#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

int main() {
    ll N, X;
    cin >> N >> X;

    struct Test {
        ll b, l, r;
    };
    vector<Test> tests(N);
    for (ll i = 0; i < N; i++) {
        cin >> tests[i].b >> tests[i].l >> tests[i].r;
    }
    sort(tests.begin(), tests.end(), [&](Test& lhs, Test& rhs) {
        return (X - lhs.b) * lhs.r + lhs.b * lhs.l >= (X - rhs.b) * rhs.r + rhs.b * rhs.l;
    });

    struct Element {
        ll type, add, num, index;
        bool operator<(const Element& rhs) const {
            return add < rhs.add;
        }
    };

    ll ok = LLONG_MAX / 10, ng = -1;
    while (ok != ng + 1) {
        ll mid = (ok + ng) / 2;

        ll a = mid / X;
        ll b = mid % X;

        ll sum = 0;
        priority_queue<Element> pq;

        for (ll i = 0; i < N; i++) {
            if (i < a) {
                sum += (X - tests[i].b) * tests[i].r;
            } else {
                sum -= tests[i].b * tests[i].l;
                pq.push({ 0, tests[i].l, tests[i].b, i });
            }
        }

        while (sum < 0 && b > 0 && !pq.empty()) {
            auto t = pq.top();
            pq.pop();

            ll op_num = min(t.num, b);
            ll max_add = t.add * op_num;
            sum += max_add;
            b -= op_num;
            if (t.type == 0) {
                pq.push({ 1, tests[t.index].r, X - tests[t.index].b, t.index });
            }
        }

        (sum >= 0 ? ok = mid : ng = mid);
    }

    cout << ok << endl;
}

