struct Test {
	long long int b, l, u;
	long long int score_diff(const int &x) const {
		return u * (x - b) + l * b;
	}
	long long int default_score_b() const {
		return b * l;
	}
	long long int max_score_a(const int &x) const {
		return u * (x - b);
	}
	long long int need_time(long long int target_score) const {
		if (target_score < default_score_b()) {
			return ((target_score + l - 1) / l);
		}
		else {
			return ((target_score + u - 1 - l * b) / u) + b;
		}
	}
};
int main() {
	int n, x; std::cin >> n >> x;
	std::vector<Test> tests(n);
	for (auto& test : tests) std::cin >> test.b >> test.l >> test.u;
	std::sort(tests.begin(), tests.end(), [=](const Test& a, const Test& b) {return a.score_diff(x) > b.score_diff(x); });
	long long int default_score = 0;
	for (const auto& test : tests) default_score -= test.default_score_b();
	auto count = 0;
	while (count < n && default_score + tests[count].score_diff(x) <= 0) {
		default_score += tests[count].score_diff(x);
		++count;
	}
	long long int time = static_cast<long long int>(count) * x;
	if (default_score == 0) {
		std::cout << time << std::endl;
	}
	else {
		auto min_time = LLONG_MAX;
		while (count > 0 && tests[count - 1].score_diff(x) == tests[count].score_diff(x)) {
			--count;
		}
		for (auto i = count; i < n; ++i) {
			auto need_time = tests[i].need_time(-default_score);
			if (min_time > need_time) {
				min_time = need_time;
			}
		}
		std::cout << time + min_time << std::endl;
	}
}

