        q.insert({-(r[i] * X - r[i] * b[i] + l[i] * b[i]), i});
    }
    li ans = 0;
    memset(used, 0, sizeof used);
    while (-q.begin()->first < B) {
        li val = -q.begin()->first;
        int id = q.begin()->second;
        // cout << val << " " << id << endl;
        q.erase(q.begin());
        used[id] = 1;
        B -= val;
        ans += X;
    }
    li best = 1e9;
    for (int i = 0; i < n; ++i) {
        if (used[i])
            continue;
        li y = B / l[i] + (B % l[i] > 0);
        if (y <= b[i]) {
            best = min(y, best);
            continue;
        }

        li C = B - l[i] * b[i];
        y = C / r[i] + (C % r[i] > 0) + b[i];
        if (y <= X)
            best = min(y, best);
    } 
    cout << ans + best << "\n";
}

