ll get(int n1){
	return 1ll * b[n1] * l[n1] + 1ll * (x - b[n1]) * u[n1];
}

bool cmp(int n1 , int n2){
	return get(n1) > get(n2);
}

int main(){
	ios::sync_with_stdio(0);
	cin >> n >> x;
	for(int i = 1 ; i <= n ; ++ i)
		cin >> b[i] >> l[i] >> u[i];
	ll tmp = 0;
	for(int i = 1 ; i <= n ; ++ i)
		tmp += 1ll * -b[i] * l[i];
	for(int i = 1 ; i <= n ; ++ i)
		num[i] = i;
	sort(num + 1 , num + n + 1 , cmp);
	ll head = 0 , tail = 1ll * x * n;
	while(head < tail){
		ll mid = (head + tail) >> 1;
		int cnt1 = mid / x , cnt2 = mid % x;
		ll mx = 0; 
		for(int i = cnt1 + 1 ; i <= n ; ++ i){
			if(cnt2 > b[num[i]])
				mx = max(mx , 1ll * b[num[i]] * l[num[i]] + 1ll * (cnt2 - b[num[i]]) * u[num[i]]);
			else
				mx = max(mx , 1ll * cnt2 * l[num[i]]);
		}
		ll s1 = 0;
		for(int i = 1 ; i <= cnt1 ; ++ i)
			s1 += get(num[i]);
		bool flag = 0;
		for(int i = 1 ; i <= n ; ++ i)
			if(i <= cnt1){
				ll cur = 0;
				if(cnt2 > b[num[i]])
					cur = max(cur , 1ll * b[num[i]] * l[num[i]] + 1ll * (cnt2 - b[num[i]]) * u[num[i]]);
				else
					cur = max(cur , 1ll * cnt2 * l[num[i]]);
				if(cur + s1 + get(num[cnt1 + 1]) - get(num[i]) + tmp >= 0){
					flag = 1;
					break;
				}
			}
		if(s1 + mx + tmp >= 0)
			flag = 1;
		if(flag)
			tail = mid;
		else
			head = mid + 1;
	}
	cout << head << endl;
	return 0;
}

