            toribun[i]={hogee,i};
      }
      sort(toribun.begin(),toribun.end());
      reverse(toribun.begin(),toribun.end());
      ll accumtoribun[n+1];
      fill(accumtoribun,accumtoribun+n+1,0);
      ll mantenNoKosuu=0;
      bool v=false;
      rep0(i,n){
            accumtoribun[i+1]=accumtoribun[i]+toribun[i].first;
            if(accumtoribun[i+1]>aoki&&!v){
                  mantenNoKosuu=i;
                  v=true;
            }
      }
      ll benkyouzikan=longinf;
      rep0(hanpa,n){
            if(hanpa>=mantenNoKosuu){
                  ll postokuten=accumtoribun[mantenNoKosuu];
                  ll posbenkyouzikan=mantenNoKosuu*x;
                  ll j=toribun[hanpa].second;
                  ll nokori=(aoki-postokuten+b[j]*(u[j]-l[j])+u[j]-1)/u[j];
                  ll nokori2=(aoki-postokuten+l[j]-1)/l[j];
                  nokori=min(nokori,nokori2);
                  //cout<<nokori<<endl;
                  posbenkyouzikan+=nokori;
                  benkyouzikan=min(posbenkyouzikan,benkyouzikan);
            }
            else{
                  ll postokuten=accumtoribun[mantenNoKosuu+1]-toribun[hanpa].first;
                  ll posbenkyouzikan=mantenNoKosuu*x;
                  ll j=toribun[hanpa].second;
                  ll nokori=(aoki-postokuten+b[j]*(u[j]-l[j])+u[j]-1)/u[j];
                  ll nokori2=(aoki-postokuten+l[j]-1)/l[j];
                  nokori=min(nokori,nokori2);
                  posbenkyouzikan+=nokori;
                  //cout<<nokori<<endl;
                  benkyouzikan=min(posbenkyouzikan,benkyouzikan);
            }
      }
      cout<<benkyouzikan<<endl;
      return 0;
}

