int main()
{
  int N, X; cin >> N >> X;

  vector<int> L(N), U(N), B(N), M(N), num(N);

  long long  Bpoint = 0;
  for (int i = 0; i < N; i++)
  {
    cin >> B[i] >> L[i] >> U[i];

    M[i] = B[i] * L[i] + (X - B[i]) * U[i];
    Bpoint += L[i] * B[i];
    num[i] = i;
  }
  sort(num.begin(), num.end(),
    [M](const int &a, const int &b) {return M[a] > M[b]; }
  );

  //use = -1:maxまで　else useの数だけ:
  long long p = 0;
  int score = 0;
  int cnt = 0;
  for (int i = 0; i < N; i++)
  {
    int now = num[i];
    if (p + M[now] > Bpoint) break;
    p += M[now];
    score += X;
    cnt++;
  }
  int lest = Bpoint - p;

  if (lest > 0) {
    int ng = 0, ok = X;
    int mid;


    while (ng + 1 < ok) {
      bool check = true;
      mid = (ng + ok) / 2;

      for (int i = cnt; i < N; i++)
      {
        int now = num[i];
        int tmp;
        if (mid <= B[now]) tmp = mid * L[now];
        else tmp = B[now] * L[now] + (mid - B[now]) * U[now];

        if (tmp >= lest) {
          ok = mid;
          check = false;
          break;
        }
      }
      if (check) ng = mid;
    }
    score += ok;
  }

  cout << score << endl;
}

