// template

bool f(int time, vector<tuple<int, int, int> > & BLU, int X, vector<pii> & score_index, vector<int> & scores) {
	int N = BLU.size();

	int time_cnt = time / X;
	int time_rest = time % X;

	if (time_cnt >= N) {
		return true;
	}

	vector<bool> check(N);
	int temp_score = 0;

	REP(i, time_cnt) {
		check[score_index[i].second] = true;
		temp_score += score_index[i].first;
	}

	pii max_score;
	REP(tar, N) {
		int score = temp_score;
		int b, l, u; tie(b, l, u) = BLU[tar];
		int t = time_rest;
		if (t < b) {
			score += t * l;
		}
		else {
			score += (u * (t - b) + l * b);
		}

		if (check[tar]) {
			score -= scores[tar];
			score += score_index[time_cnt].first;
		}

		if (max_score.first < score) {
			max_score = make_pair(score, tar);
		}
	}

	vector<int> times(N);
	times[max_score.second] = time_rest;
	int cnt = 0;
	REP(i, N) {
		if (times[score_index[i].second] == 0) {
			if (cnt == time_cnt) {
				break;
			}
			times[score_index[i].second] = X;
			++cnt;
		}
	}

	int A = 0;
	int B = 0;
	REP(i, times.size()) {
		int b, l, u; tie(b, l, u) = BLU[i];
		if (b < times[i]) {
			A += u * times[i];
			B += u * b;
		}
		else {
			A += l * times[i];
			B += l * b;
		}
	}

	return A >= B;
}

void solve() {
	int N, X; cin >> N >> X;
	vector<tuple<int, int, int >> BLU;
	REP(i, N) {
		int b, l, u;
		cin >> b >> l >> u;
		BLU.emplace_back(b, l, u);
	}

	vector<pii> score_index;
	vector<int> scores;
	REP(i, N) {
		int b, l, u; tie(b, l, u) = BLU[i];
		score_index.emplace_back(u * (X - b) + l * b, i);
		scores.push_back(score_index.back().first);
	}
	sort(ALL(score_index), greater<pii>());

	int ng = -1;
	int ok = N * X;

	f(2540, BLU, X, score_index, scores);

	while (abs(ok - ng) > 1) {
		int mid = (ok + ng) / 2;
		if (f(mid, BLU, X, score_index, scores)) {
			ok = mid;
		}
		else {
			ng = mid;
		}
	}
	cout << ok << endl;
}

