struct Test {
	long long int b, l, u;
	long long int score_by(const int time) const {
		if (time > b) {
			return (time - b) * u;
		}
		else {
			return (time - b) * l;
		}
	}
	long long int need_time(long long int target_score) const {
		if (target_score < l * b) {
			return ((target_score + l - 1) / l);
		}
		else {
			return ((target_score + u - 1 - l * b) / u) + b;
		}
	}
};
int main() {
	int n, x; std::cin >> n >> x;
	std::vector<Test> tests(n);
	for (auto& test : tests) std::cin >> test.b >> test.l >> test.u;
	std::sort(tests.begin(), tests.end(), [=](const Test& a, const Test& b) {return (a.score_by(x) - a.score_by(0)) > (b.score_by(x) - b.score_by(0)); });
	long long int default_score = 0;
	for (const auto& test : tests) default_score += test.score_by(0);
	auto count = 0;
	while (count < n && default_score + tests[count].score_by(x) - tests[count].score_by(0) <= 0) {
		default_score += tests[count].score_by(x) - tests[count].score_by(0);
		++count;
	}
	long long int time = static_cast<long long int>(count) * x;
	if (default_score == 0) {
		std::cout << time << std::endl;
	}
	else {
		auto min_time = LLONG_MAX;
		while (count > 0 && (tests[count - 1].score_by(x) - tests[count - 1].score_by(0)) == (tests[count].score_by(x) - tests[count].score_by(0))) {
			--count;
		}
		for (auto i = count; i < n; ++i) {
			auto need_time = tests[i].need_time(-default_score);
			if (min_time > need_time) {
				min_time = need_time;
			}
		}
		std::cout << time + min_time << std::endl;
	}
}

