        ll k = m / x;
        ll r = m - k * x;

        iota(I.begin(), I.end(), 0);
        sort(I.begin(), I.end(), [&](auto a, auto b) {
            if (S[a] == S[b]) {
                ll ra = L[a] * min(B[a], r) + U[a] * max(0LL, r - B[a]);
                ll rb = L[b] * min(B[b], r) + U[b] * max(0LL, r - B[b]);
                return ra < rb;
            }
            return S[a] > S[b];
        });

        ll pnt = 0;
        loop (k, i) pnt += S[I[i]];

        ll rp = 0;
        loop (n - k, i) {
            int idx = I[i + k];
            ll rpp = L[idx] * min(B[idx], r) + U[idx] * max(0LL, r - B[idx]);
            rp = max(rp, rpp);
        }
        if (base <= pnt + rp) right = m;
        else left = m + 1;
    }
    cout << left << endl;
}

int main(){
    ll n, x;
    cin >> n >> x;
    vector<ll> B(n), L(n), U(n);
    loop (n, i) {
        cin >> B[i] >> L[i] >> U[i];
    }
    solve(n, x, move(B), move(L), move(U));
    return 0;
}

