Int N, X;
struct elem {
  Int L, U, B;
  Int val(Int x) const {
    return L * min(B, x) + U * max(0LL, x - B);
  }
  Int tot() const {
    return val(X);
  }
  Int lb(Int y) const {
    if (tot() < y) return INFLL;
    if (y <= 0) return 0;
    Int lo = 0, hi = X;
    while (hi - lo > 1) {
      const Int mid = (hi + lo) / 2;
      if (val(mid) >= y) {
        hi = mid;
      } else {
        lo = mid;
      }
    }
    return hi;
  }
} E[100050];

int main() {
  N = in();
  X = in();

  Int goal = 0;
  for (int i = 0; i < N; ++i) {
    E[i].B = in();
    E[i].L = in();
    E[i].U = in();
    goal += E[i].B * E[i].L;
  }
  if (goal == 0) {
    puts("0");
    return 0;
  }

  sort(E, E + N, [=] (const elem& a, const elem& b) {
    return a.tot() > b.tot();
  });

  Int alls = 0;
  Int csum = 0;
  for (int i = 0; i < N; ++i) {
    csum += E[i].tot();
    if (csum >= goal) {
      alls = i + 1;
      break;
    }
  }
  Int res = alls * X;

  for (int i = 0; i < alls; ++i) {
    Int rsum = csum - E[i].tot();
    chmin(res, (alls - 1) * X + E[i].lb(goal - rsum));
  }

  --alls;
  csum -= E[alls].tot();
  for (int i = alls + 1; i < N; ++i) {
    while (csum + E[i].tot() < goal) {
      csum += E[alls].tot();
      ++alls;
    }
    chmin(res, alls * X + E[i].lb(goal - csum));
  }

  printf("%lld\n", res);

  return 0;
}

