using namespace std;
typedef long long ll;
const int maxn = 100000 + 10;
const int DEBUG = 1;

int n, X;
struct anode{
	int b, l, r;
	anode() {}
	anode(int _b, int _l, int _r):b(_b), l(_l), r(_r) {}
}a[maxn];

inline bool check(ll k) {
	ll t1 = k / X;
	ll t2 = k % X;
	ll tmp = 0;
	for(int i = 1;i <= t1;i ++) {
		tmp = (ll)tmp + (X - a[i].b) * a[i].r;
	}
	for(int i = t1 + 2;i <= n;i ++) {
		tmp = (ll)tmp - (ll)a[i].b * a[i].l;
	}
	if(t2 > a[t1 + 1].b) tmp = (ll)tmp + (t2 - a[t1 + 1].b) * a[t1 + 1].r;
	else tmp = (ll)tmp - (a[t1 + 1].b - t2) * a[t1 + 1].l;
	return tmp >= 0;
}

inline bool cmp(anode a, anode b) {
	ll t1 = (ll)(X - a.b) * a.r + (ll)a.b * a.l;
	ll t2 = (ll)(X - b.b) * b.r + (ll)b.b * b.l;
	return t1 > t2;
}

int main() {
	scanf("%d%d", &n, &X);
	for(int i = 1;i <= n;i ++) {
		int x, y, z;
		scanf("%d%d%d", &x, &y, &z);
		a[i] = anode(x,y,z);
	}
	sort(a + 1,a + n + 1,cmp);
	ll L = 0, R = 1LL * X * n, Ans = -1;
//	if(DEBUG) check(2540);
	while(L <= R) {
		ll mid = (L + R) / 2;
		if(check(mid)) R = mid - 1, Ans = mid;
		else L = mid + 1;
	}
	printf("%lld\n", Ans);
	return 0;
}

#include <bits/stdc++.h>
#define Maxn 100007
using namespace std;
int n,x;
int b[Maxn],l[Maxn],r[Maxn];
bool flag[Maxn];
priority_queue<pair<long long,int> >pq;
long long solve(int id,long long tmp)
{
    if (tmp<=1LL*l[id]*b[id])
    {
        return (tmp+l[id]-1)/l[id];
    } else
    {
        tmp-=1LL*l[id]*b[id];
        return (tmp+r[id]-1)/r[id]+b[id];
    }
}
int main()
{
    scanf("%d%d",&n,&x);
    while (!pq.empty()) pq.pop();
    long long tmp=0LL;
    for (int i=1;i<=n;i++)
    {
        scanf("%d%d%d",&b[i],&l[i],&r[i]);
        tmp+=1LL*l[i]*b[i];
        pq.push(make_pair(1LL*r[i]*(x-b[i])+1LL*l[i]*b[i],i));
    }
    long long ans=1LL*x*n;
    int cnt=0;
    while ((!pq.empty())&&tmp>=0)
    {
        tmp-=pq.top().first;
        int id=pq.top().second;
        flag[id]=true;
        pq.pop();
        ++cnt;
    }
    ans=min(ans,1LL*cnt*x);
    --cnt;
    long long t=x;
    for (int i=1;i<=n;i++)
        if (flag[i])
        {
            tmp+=1LL*r[i]*(x-b[i])+1LL*l[i]*b[i];
            t=min(t,solve(i,tmp));
            tmp-=1LL*r[i]*(x-b[i])+1LL*l[i]*b[i];
        }
    ans=min(ans,1LL*cnt*x+t);
    while (!pq.empty()) pq.pop();
    tmp=0LL;
    for (int i=1;i<=n;i++)
    {
        tmp+=1LL*l[i]*b[i];
        pq.push(make_pair(1LL*r[i]*(x-b[i])+1LL*l[i]*b[i],i));
    }
    memset(flag,false,sizeof(flag));
    cnt=0;
    while ((!pq.empty())&&tmp>pq.top().first)
    {
        tmp-=pq.top().first;
        int id=pq.top().second;
        flag[id]=true;
        pq.pop();
        ++cnt;
    }
    t=x;
    for (int i=1;i<=n;i++)
        if (!flag[i])
        {
            tmp+=1LL*r[i]*(x-b[i])+1LL*l[i]*b[i];
            t=min(t,solve(i,tmp));
            tmp-=1LL*r[i]*(x-b[i])+1LL*l[i]*b[i];
        }
    ans=min(ans,1LL*cnt*x+t);
    printf("%lld\n",ans);
    return 0;
}

