using namespace std;
long long n,m,i,j,l,r,mid,ans,sum,pre[100005];
struct ii
{
	long long lim,c1,c2;
}a[100005];
bool cmp(ii x,ii y)
{
	return x.lim*x.c1+(m-x.lim)*x.c2>y.lim*y.c1+(m-y.lim)*y.c2;
}
bool check(long long mid)
{
	long long i,p=0;
	while(p<n&&(p+1)*m<=mid)p++;
	if(p>=n){
		return 1;
	}
	fz1(i,n){
		long long t=0;
		if(i>p){
			long long re=mid-m*p;
			t=pre[p];
			if(re<=a[i].lim){
				t+=a[i].c1*re;
			}
			else{
				t+=a[i].c1*a[i].lim+a[i].c2*min(m-a[i].lim,re-a[i].lim);
			}
		}
		else{
			t=pre[p]-(a[i].lim*a[i].c1+(m-a[i].lim)*a[i].c2);
			long long re=mid-m*(p-1);
			if(re>=m){
				t+=(a[p+1].lim*a[p+1].c1+(m-a[p+1].lim)*a[p+1].c2);
				re-=m;
			}
			if(re<=a[i].lim){
				t+=a[i].c1*re;
			}
			else{
				t+=a[i].c1*a[i].lim+a[i].c2*min(m-a[i].lim,re-a[i].lim);
			}
		}
		if(t>=sum)return 1;
	}
	return 0;
}
int main()
{
	scanf("%lld%lld",&n,&m);
	fz1(i,n){
		scanf("%lld%lld%lld",&a[i].lim,&a[i].c1,&a[i].c2);
		sum+=a[i].lim*a[i].c1;
	}
	sort(a+1,a+n+1,cmp);
	fz1(i,n){
		pre[i]=pre[i-1];
		pre[i]+=a[i].lim*a[i].c1+(m-a[i].lim)*a[i].c2;
	}
	l=-1;r=sum;ans=sum;
	while(l<r){
		mid=(l+r+1)/2;
		if(check(mid)){
			r=mid-1;ans=mid;
		}
		else l=mid;
	}
	cout<<ans<<endl;
	return 0;
}

