//vector<int> dy = {0,0,1,-1};
//vector<int> dx = {1,-1,0,0};
ll N, X;
vector<ll> B(100010), l(100010), u(100010);
ll Asum;

vector<pair<ll, int>> uX(100010, {-INFL, -1});

bool win(ll canUse){
  if(canUse >= X * N) return 1;
  int r = canUse % X, p = canUse / X;
  for(int i = 0; i < N; i++){
    ll score = 0;
    if(r - B[i] >= 0){
      score += r * u[i] - B[i] * (u[i] - l[i]);
    }else{
      score += r * l[i];
    }
    if(score >= Asum) return 1;
    int cnt = 0;
    int s = 0;
    while(cnt < p){
      if(uX[s].second == i){
        s++;
      }else{
        score += uX[s].first;
        s++;
        cnt++;
        if(score >= Asum) return 1;
      }
    }
  }
  return 0;
}

int main(void){
  cin >> N >> X;
  for(int i = 0; i < N; i++){
    cin >> B[i] >> l[i] >> u[i];
    Asum += B[i] * l[i];
    uX[i].first = X * u[i] - B[i] * (u[i] - l[i]);
    uX[i].second = i;
  }
  sort(uX.begin(), uX.end());
  reverse(uX.begin(), uX.end());
  ll ng = -1, ok = INFL;
  ll mid;
  while(ok - ng > 1){
    mid = (ng + ok) / 2;
    if(win(mid)){
      ok = mid;
    }else{
      ng = mid;
    }
  }
  cout << ok << endl;
}

