using namespace std;

typedef long long ll;

int n;
ll x;
ll b[100000];
ll l[100000];
ll u[100000];
ll sum[100000];

int main()
{
    ll goal = 0;
    cin >> n >> x;
    vector<int> idx(n);
    for (int i = 0; i < n; i++) {
        cin >> b[i] >> l[i] >> u[i];
        goal += b[i] * l[i];
        idx[i] = i;
    }

    auto score = [&](int i) {
        return x * u[i] - (u[i] - l[i]) * b[i];
    };

    sort(idx.begin(), idx.end(), [&](int i, int j) {
        return score(i) > score(j);
    });


    for (int i = 0; i < n; i++)
        sum[i] = (i? sum[i - 1]: 0) + score(i);


    ll ans = x * n;
    for (int i = 0; i < n; i++) {
        auto mx = max(score(i), l[i] * x);

        int bl = 0, br = n;
        if (mx >= goal)
            br = 0;

        while (bl + 1 < br) {
            int m = (bl + br) / 2;
            ll v = sum[m - 1];
            if (i < m)
                v -= sum[i];

            if (mx + v >= goal)
                br = m;
            else
                bl = m;
        }

        ll v = br? sum[br - 1]: 0;
        ll total = br * x;
        if (i < br)
            v -= sum[i], total -= x;

        ll mn = min((goal - v + (u[i] - l[i]) * b[i] + u[i] - 1) / u[i],
        (goal - v + l[i] - 1) / l[i]);
        if (mn < 0)
            mn = 0;

        total += mn;


        ans = min(ans, total);

    }

    cout << ans << endl;


}

