ll N, X;
vector<ll> b, l, u;

bool IsOK(ll total)
{
    const ll remainder = total % X;
    const ll xNum = total / X;

    vector<pair<ll, int>> v;
    rep(i, 0, N)
    {
        v.emplace_back(u[i] * (X - b[i]) + l[i] * b[i], i);
    }
    sort(v.begin(), v.end(), greater<pair<ll, int>>());

    rep(i, 0, N)
    {
        ll score = 0;
        rep(j, 0, N)
        {
            const int idx = v[j].second;

            if (j == i)
            {
                score += ((remainder > b[idx]) ? u[idx] : l[idx]) * (remainder - b[idx]);
            }
            else if (j < (xNum + (i < xNum)))
            {
                score += u[idx] * (X - b[idx]);
            }
            else
            {
                score += l[idx] * (0 - b[idx]);
            }
        }

        if (score >= 0)
        {
            return true;
        }
    }

    return false;
}

void _main()
{
    cin >> N >> X;
    b.resize(N); l.resize(N); u.resize(N);
    rep(i, 0, N) cin >> b[i] >> l[i] >> u[i];

    ll ng = -1;
    ll ok = N * X;
    while (abs(ng - ok) > 1)
    {
        const ll mid = (ng + ok) / 2;

        if (IsOK(mid))
        {
            ok = mid;
        }
        else
        {
            ng = mid;
        }
    }
    cout << ok << endl;
}

