int64_t N, X, B[100000], L[100000], U[100000];
int64_t target;
int64_t full[100000], full_sorted[100000];

bool check(int64_t S){
    int q = S/X, r = S%X;
    int64_t fix = 0;
    for(int i=0; i<q; i++) fix += full_sorted[i];
    for(int i=0; i<N; i++){
        int64_t res = fix;
        if(q > 0 && full[i] >= full_sorted[q-1]) res += full_sorted[q] - full[i];
        if(r <= B[i]){
            res += L[i]*r;
        }else{
            res += U[i]*r - (U[i]-L[i])*B[i];
        }
        if(res >= target) return true;
    }
    return false;
}

int main(){
    cin >> N >> X;
    for(int i=0; i<N; i++){
        cin >> B[i] >> L[i] >> U[i];
        target += B[i] * L[i];
        full[i] = full_sorted[i] = U[i]*X - (U[i]-L[i])*B[i];
    }
    sort(full_sorted, full_sorted+N, greater<>());

    int64_t ok = N*X, ng = -1;
    while(ok-ng>1){
        int64_t mid = (ok+ng)/2;
        (check(mid) ? ok : ng) = mid;
    }
    cout << ok << endl;
    return 0;
}

