int n, x;
pipii l[100005]; // <hours, <lower, upper>>

ll gain(pipii a, ll h) {
  assert(h <= x);
  ll ret = 0;
  ret += min(a.first, (int)h) * (ll)a.second.first;
  ret += max(0LL, h - a.first) * (ll)a.second.second;
  return ret;
}

bool can(ll t) {
  ll need = 0;
  for(int i = 0; i < n; i++) {
    need += l[i].first * (ll)l[i].second.first;
  }
  int guaranteed = t/x;
  int rem = t % x;
  ll forceGain = 0;
  for(int i = 0; i <= guaranteed; i++) {
    forceGain += gain(l[i], x);
  }
  if(rem == 0) return forceGain - gain(l[guaranteed], x) >= need;
  for(int i = 0; i < n; i++) {
    if(i < guaranteed) {
      ll realGain = forceGain - gain(l[i], x) + gain(l[i], rem);
      if(realGain >= need) return true;
    }
    else {
      ll realGain = forceGain - gain(l[guaranteed], x) + gain(l[i], rem);
      if(realGain >= need) return true;
    }
  }
  return false;
}

bool cmp(pipii a, pipii b) {
  return gain(a, x) > gain(b, x);
}

