		int mi = (aut + alt) / 2;
		int score = 0,ms=0,Ms=0;

		priority_queue<P>V,Q;
		unordered_set<int>S;
		rep(i, n) {
			S.insert(i);
			V.push(P(u[i] * (x - b[i]), i));
		}
		rep(i, mi / x) {
			P p = V.top();
			V.pop();
			score += p.first;
			S.erase(p.second);
		}

		for (auto itr = S.begin(); itr != S.end(); itr++) {
			int now = *itr;
			Q.push(P(l[now] * (- b[now]), now));
		}

		for (int i = mi / x + 1; i < n; i++) {
			P p = Q.top();
			Q.pop();
			score += p.first;
			S.erase(p.second);
		}

		if (S.size()) {
			int I = *S.begin();
			ms = ((mi%x) - b[I])*l[I];
			Ms = ((mi%x) - b[I])*u[I];
		}
		if (score + ms >= 0 || score + Ms >= 0)aut = mi;
		else alt = mi;

	}
	cout << aut << endl;
}

