int N, X;
struct T {int b; int l; int u;};
vector<T> input;
vector<int> testValue;
vector<int> testValueOrd;
ll defaultDiff = 0;


bool is_valid(int x){

    int comp_num = x / X;
    int res = x % X;

    ll diff = defaultDiff;

    vector<bool> used(N, false);
    REP(i, comp_num) {
        used[testValueOrd[i]] = true;
        diff -= testValue[testValueOrd[i]];
    }

    int tmp = 0;
    REP(i, N){
        if (used[i]) continue;

        if (res >= input[i].b){
            tmp = max(tmp, input[i].u * (res - input[i].b) - input[i].l * (- input[i].b));
        } else {
            tmp = max(tmp, input[i].l * res);
        }
    }

    diff -= tmp;

    return diff <= 0;
}

