// [[LIBRARY]]
ll max_score(const vector<tuple<ll, ll, ll>> &blu, const ll x, const ll s) {
    const ll n = blu.size();
    vector<int> vst(n, 0);
    vector<ld> cospa_x(n);
    ll result = 0;
    REP(i, n) {
        ll b, l, u; tie(b, l, u) = blu[i];
        cospa_x[i] = (ld)u * (x - b) / x;
    }
    vector<ll> rank_cospa(n);
    iota(ALL_OF(rank_cospa), 0LL);
    sort(ALL_OF(rank_cospa), [&](ll i, ll j) {
        return cospa_x[i] > cospa_x[j];
    });
    REP(t, min(s / x, n)) {
        ll i = rank_cospa[t];
        ll b, l, u; tie(b, l, u) = blu[i];
        result += u * (x - b);
    }
    if(s / x < n) {
        ll maxterm = -LINF;
        ll w = s % x;
        ll ss = 0;
        RANGE(t, s / x, n-1) {
            ll i = rank_cospa[t];
            ll b, l, u; tie(b, l, u) = blu[i];
            ss += l * -b;
        }
        RANGE(t, s / x, n-1) {
            ll i = rank_cospa[t];
            ll b, l, u; tie(b, l, u) = blu[i];
            chmax(maxterm, ss - (l * -b) + u * (w - b));
            chmax(maxterm, ss - (l * -b) + l * (w - b));
        }
        result += maxterm;
    }
    return result;
}

