bool check(ll h){
	ll ans = -INF;
	ll com = h / x;
	ll rem = h % x;
	ll s = 0;

	for(int i = 0; i < com; i++) s += val(ind[i], x);
	s += val(ind[com], rem);
	for(int i = com + 1; i < n; i++) s += val(ind[i], 0);
	ll sp;
	ans = s;
	for(int i = 0; i < com; i++){
		sp = s - val(ind[i], x) - val(ind[com], rem) + val(ind[i], rem) + val(ind[com], x);
		ans = max(ans, sp);
	}
	for(int i = com + 1; i < n; i++){
		sp = s - val(ind[i], 0) - val(ind[com], rem) + val(ind[i], rem) + val(ind[com], 0);
		ans = max(ans, sp);
	}
	return ans >= 0;
}

