int main(){

    ll N,X;cin>>N>>X;
    vector<ll> A(N),B(N),C(N);
    vector<int> seen(N,0);

    ll minsum=0,ans=0;
    priority_queue<pp> PQ;

    for(int i=0;i<N;i++){
        cin>>A[i]>>B[i]>>C[i];
        minsum+=A[i]*B[i];
        PQ.push(make_pair(make_pair(A[i]*B[i]+(X-A[i])*C[i],B[i]),i));
    }

    for(int i=0;i<N;i++){

        ll a=PQ.top().first.first;
        int b=PQ.top().second;

        if(minsum<a){

            ll mini=X;

            for(int j=0;j<N;j++){
                if(seen[j]) continue;
                ll c=A[j],d=B[j],e=C[j];
                if(c*d>=minsum){
                    mini=min(mini,(minsum+d-1)/d);
                }else if(c*d+(X-c)*e>=minsum){
                    mini=min(mini,c+(minsum-c*d+e-1)/e);
                }
            }

            ans+=mini;
            break;

        }else if(minsum==a){
            ans+=X;
            break;
        }else{
            ans+=X;
            minsum-=a;
            seen[b]=1;
            PQ.pop();
        }
    }

