};

bool comp(hoge &a, hoge &b){
    if(a.h0!=b.h0) return a.h0 > b.h0;
    if(a.l0!=b.l0) return a.l0 < b.l0;
    return a.num < b.num;
}

int N; ll X;
ll b[100100], l[100100], u[100100];
hoge h[100100]; 
ll st;

bool ok(ll s){
    int n=0;
    ll now=st;
    while(s >= X){
        now += h[n].h0;
        s -=X;
        n++;
    }
    //s増えた時のmaxを求める
    ll smax=0LL;
    for(int i=n; i<N; i++){
        int j=h[i].num;
        if(b[j] <s ){
            if( b[j]*l[j]+ (s-b[j])*u[j]  > smax ) smax=b[j]*l[j]+ (s-b[j])*u[j] ;
        }
        else{
            if(smax < s*l[j] ) smax=s*l[j];
        }
    }
    if(now+smax >=0LL) return true;
    return false;
}

