  Data (double x,int id,int t) :x(x),id(id),t(t) {}
  bool operator <(const Data& rhs) const {
    return x==rhs.x?t<rhs.t:x<rhs.x;
  }
};
priority_queue<Data> Q;
int vis[N];
bool Check(LL m) {
  LL res=0;
  for(int i=1;i<=n;++i) res-=B[i]*L[i];
