  }
  mem(vis,0);
  while(m>=X&&!Q.empty()) {
    Data A=Q.top(); Q.pop();
    if(vis[A.id]==2) continue;
    if(A.t==1) res+=B[A.id]*L[A.id],m-=B[A.id];
    else {
      LL gg=vis[A.id]?R[A.id]*(X-B[A.id]):L[A.id]*B[A.id]+R[A.id]*(X-B[A.id]);
      res+=gg;
      if(vis[A.id]) m-=X-B[A.id];
      else m-=X;
      vis[A.id]=2;
    }
  }
  if(m) {
    LL tmp=0;
    for(int i=1;i<=n;++i) {
      if(vis[i]==2) continue;
      if(vis[i]==1) {
        if(X-B[i]>=m) tmp=max(tmp,m*R[i]);
