int main() {
	int n; i64 x; scanf("%d%lld", &n, &x);
	std::vector<i64> b(n), l(n), r(n);
	for(int i = 0; i < n; i++) scanf("%lld%lld%lld", &b[i], &l[i], &r[i]);

	std::vector<std::pair<i64, int>> vec;
	for(int i = 0; i < n; i++) vec.push_back({(x - b[i]) * r[i], i});
	sort(begin(vec), end(vec), std::greater<>());

	std::function<bool (i64)> check = [&](i64 t) {
		i64 A = t / x, B = t % x;
		if(A >= n) return true;

		std::vector<bool> latte(n, false);
		for(int i = 0; i < A; i++) latte[vec[i].second] = true;

		i64 X = 0, Y = 0;
		for(int i = 0; i < n; i++) {
			if(latte[i]) {
				X += x * r[i];
				Y += b[i] * r[i];
			} else {
				Y += b[i] * l[i];
			}
		}

		bool ans = false;
		for(int i = 0; i < n; i++) {
			if(latte[i]) continue;
			if(X + B * l[i] >= Y) ans = true;
			i64 tmp = b[i] * r[i] - b[i] * l[i];
			if(X + B * r[i] >= Y + tmp) ans = true;
		}

		if(A < vec.size()) {
			for(int i = 0; i < A; i++) {
				int p = vec[i].second;
				i64 N = x * r[A] - x * r[p];
				i64 M = b[p] * l[p] + b[A] * r[A] - b[p] * r[p] - b[A] * l[A];
				if(X + N >= Y + M) ans = true;
			}
		}
		return ans;
	};
	i64 ok = x * n, ng = -1;
	while(std::abs(ok - ng) > 1) {
		i64 mid = (ok + ng) >> 1;

		if(check(mid)) ok = mid;
		else ng = mid;
	}
	printf("%lld\n", ok);
	return 0;
}

