const ll mod = 1000003;

ll __pow(ll a, ll b) { return b ? (b & 1 ? a : 1) * __pow(a * a % mod, b / 2) % mod : 1; }
ll rev(ll a) { return __pow(a, mod - 2); }

int main() {
    V<ll> fact(mod + 10, 1);
    for(ll i = 1; i < fact.size(); i++) fact[i] = i * fact[i - 1] % mod;

    ll Q;
    cin >> Q;
    while(Q--) {
        ll b, a, n;
        cin >> b >> a >> n;
        if(a == 0) {
            cout << __pow(b, n) << endl;
            continue;
        }
        ll b_div_a = b * rev(a) % mod;
        ll val = (n + b_div_a - 1) % mod;
        if(n / mod >= 1) {
            cout << 0 << endl;
            continue;
        }
        // [l, r]
        if(val - n > 0) {
            ll ans = fact[val] * rev(fact[val - n]) % mod;
            (ans *= __pow(a, n)) %= mod;
            cout << ans << endl;
        } else {
            cout << 0 << endl;
        }
    }
    return 0;
}

