int main(){
  long long N, X;
  cin >> N >> X;
  vector<long long> B(N), L(N), U(N);
  long long ans = 0, s = 0;
  vector<pair<long long,int>> V;
  for(int i = 0; i < N; ++i){
    cin >> B[i] >> L[i] >> U[i];
    ans += B[i];
    V.emplace_back(B[i]*L[i]+U[i]*(X-B[i]),i);
    s += U[i]*(X-B[i]);
  }
  sort(V.begin(), V.end());
  // for(auto p : V) cerr << p.first << " " << p.second << endl;
  // cerr << s << endl;
  long long ans_ = N*X;
  vector<bool> used(N,false);
  for(int i = 0; i < N; ++i){
    if(V[i].first <= s){
      //cerr << V[i].second << endl;
      s -= V[i].first;
      ans_ -= X;
      used[V[i].second] = true;
    }else{
      break;
    }
  }
  //cerr << "ans = " << ans << endl;
  long long t = 0;
  for(int i = 0; i < N; ++i){
    if(used[i]) continue;
    long long t_ = 0;
    if(s <= (X-B[i])*U[i]){
      t = max(t,s/U[i]);
      continue;
    }
    t_ = X - B[i] + (s-(X-B[i])*U[i])/L[i];
    t = max(t,t_);
  }
  ans = min(ans,ans_-t);
  vector<pair<long long,int>> A;
  for(int i = 0; i < N; ++i){
    if(used[i]) continue;
    A.emplace_back(U[i],i);
  }
