  for(size_t i = 0; i < A.size(); ++i){
    int idx = A[i].second;
    long long h = min(s,U[idx]*(X-B[idx]))/U[idx];
    t -= h;
    s -= h*U[idx];
  }
  ans = min(ans,ans_);
  cout << ans << endl;
}

