long long N, X, S, A[1 << 18], L[1 << 18], R[1 << 18];
vector<pair<long long, int>> E;

int main() {
	cin >> N >> X;
	for (int i = 1; i <= N; i++) {
		cin >> A[i] >> L[i] >> R[i];
		S += A[i] * L[i];
		E.push_back(make_pair(L[i] * A[i] + R[i] * (X - A[i]), i));
	}
	sort(E.begin(), E.end());
	reverse(E.begin(), E.end());

	long long shou = 0;
	for (int i = 0; i < E.size(); i++) {
		if (E[i].first <= S) { shou++; S -= E[i].first; }
		else break;
	}

	long long minx = X;
	for (int i = shou; i < E.size(); i++) {
		int id = E[i].second;
		if (S < A[id] * L[id]) minx = min(minx, (S + L[id] - 1LL) / L[id]);
		else {
			long long V = S - A[id] * L[id];
			minx = min(minx, A[id] + (V + R[id] - 1LL) / R[id]);
		}
	}

	if (shou < (int)E.size()) {
		S -= E[shou].first;
		for (int i = 0; i < shou; i++) {
			long long T = S + E[i].first;

			int id = E[i].second;
			if (T < A[id] * L[id]) minx = min(minx, (T + L[id] - 1LL) / L[id]);
			else {
				long long V = T - A[id] * L[id];
				minx = min(minx, A[id] + (V + R[id] - 1LL) / R[id]);
			}
		}
	}

	cout << 1LL * shou * X + minx << endl;
	return 0;
}

