int N, X;
vector<int> b, l, u;
vector<pli> diff;
vector<ll> sumX;
vector<ll> sum0;

bool is_win(ll A) {
	int q = (int)(A / X);
	int r = A % X;

	for (int i = 0; i < N; i++)
	{
		ll ans = 0;

		ans += r > b[i] ? u[i] * (r - b[i]) : -l[i] * (b[i] - r);

		if (i < q) {
			ans += sumX[q + 1];
			ans += sum0[q + 1];
			ans -= u[i] * (X - b[i]);
		}
		else {
			ans += sumX[q];
			ans += sum0[q];
			ans -= -l[i] * b[i];
		}

		if (ans >= 0)
			return true;
	}

	return false;
}

int main() {
	cin >> N >> X;
	b.assign(N, 0), l.assign(N, 0), u.assign(N, 0);
	for (int i = 0; i < N; i++)
		cin >> b[i] >> l[i] >> u[i];


	for (int i = 0; i < N; i++)
		diff.push_back(pli((ll)u[i] * (X - b[i]) - (ll)l[i] * b[i], i));
	sort(diff.rbegin(), diff.rend());

	{
		vector<int> dummyb, dummyl, dummyu;
		for (int i = 0; i < N; i++)
		{
			int ni = diff[i].second;
			dummyb.push_back(b[ni]);
			dummyl.push_back(l[ni]);
			dummyu.push_back(u[ni]);
		}
		b = dummyb;
		l = dummyl;
		u = dummyu;
	}

	sumX.push_back(0);
	sum0.push_back(0);
	for (int i = 0; i < N; i++) {
		sumX.push_back(sumX[i] + u[i] * (X - b[i]));
		sum0.push_back(sum0[i] - l[N - 1 - i] * b[N - 1 - i]);
	}
	reverse(sum0.begin(), sum0.end());

	ll lb = -1, rb = (ll)N * X; // (lb, rb]
	while (rb - lb > 1) {
		ll mid = (lb + rb) / 2;
		if (is_win(mid))
			rb = mid;
		else
			lb = mid;
	}

	cout << rb << endl;
	return 0;
}

