bool check(ll mid){
	ll t=mid/X,sy=mid%X,ans=0,mx=0;
	For(i,1,t)ans+=a[i].lj;
	For(i,t+1,n){
		if(sy>=a[i].b)mx=max(mx,a[i].b*a[i].l+(sy-a[i].b)*a[i].u);
		else mx=max(mx,sy*a[i].l);
	}
	For(i,1,t){
		if(sy>=a[i].b)mx=max(mx,a[i].b*a[i].l+(sy-a[i].b)*a[i].u+a[t+1].lj-a[i].lj);
		else mx=max(mx,sy*a[i].l+a[t+1].lj-a[i].lj);
	}
	//if(mid==100)cout<<ans<<" "<<B<<endl;
	return ans+mx>=B;
}
