bool used[112345];

int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  cin >> n >> x;
  ll d = 0;
  vector<pair<ll, int>> v;
  for(int i = 0; i < n; i++) {
    cin >> b[i] >> l[i] >> u[i];
    d += l[i] * b[i];
    v.emplace_back(l[i] * b[i] + u[i] * (x - b[i]), i);
  }

  LiChaoTree<ll, greater<ll>> cht;

  for(int i = 0; i <= x; i++) cht.x(i);
  cht.prebuild();

  sort(begin(v), end(v));

  ll ans = 1e18;
  ll res = 0;

  while(d > 0) {
    ll val; int i;
    tie(val, i) = v.back();
    v.pop_back();
    if(d >= val) {
      d -= val, used[i] = 1, res += x;
      cht.add(u[i], 0, 0, x - b[i]);
      cht.add(l[i], (u[i] - l[i]) * (x - b[i]), x - b[i], x);
    }
    else break;
  }

  vector<pair<ll, int>> w;
  for(int i = 0; i <= x; i++) {
    w.emplace_back(cht.query(i), i);
  }
  // sort(begin(w), end(w));
  assert(is_sorted(begin(w), end(w)));
  // dump(w);
  // dump(w.size());
  // for(int i = x - 2; i >= 0; i--) {
  //   w[i].second = min(w[i].second, w[i + 1].second);
  // }

  if(d == 0) ans = res;

  for(int i = 0; i < n; i++) if(used[i] == 0) {
    ll ok = x, ng = 0;
    while(abs(ok - ng) > 1) {
      ll mid = (ok + ng) >> 1;
      ll L = min(mid, b[i]);
      ll k = 0;
      k += L * l[i];
      k += u[i] * (mid - L);
      if(k >= d) ok = mid; else ng = mid;
    }
    ans = min(ans, res + ok);

    auto rr = res + x;
    {
      ll f = d - (l[i] * b[i] + u[i] * (x - b[i]));
      f *= -1;
      ll ok = 0, ng = x + 1;
      while(abs(ok - ng) > 1) {
        ll mid = (ok + ng) >> 1;
        if(w[mid].first <= f) ok = mid;
        else ng = mid;
      }
      rr -= w[ok].second;
    }
    ans = min(ans, rr);
    dump(rr);
  }

  cout << ans << endl;
  return 0;
}

