int N;
ll X;
vector<ll> B,L,R;

vector<pair<ll,int>> uv;
vector<pair<ll,int>> lv;
vector<pair<ll,int>> bv;

bool judge(ll lim){
  vector<int> used(N,0);


  ll aoki=0;
  ll taka=0;
  for(int i=0;i<N;i++){
    aoki+=L[i]*B[i];
  }

  ll opnum=lim;
  int uvnum=0;

  for(int i=0;i<N;i++){
      int now=uv[i].second;
      if(opnum>=X){
          used[now]=1;
          taka+=R[now]*X;
          aoki-=L[now]*B[now];
          aoki+=R[now]*B[now];
          opnum-=X;
      }else break;
  }

  vector<pair<ll,int>> v;
  for(int i=0;i<N;i++){
      if(used[i]) continue;
      if(B[i]>=opnum){
          v.push_back(mkp(opnum*L[i],B[i]));
      }else{
          v.push_back(mkp(R[i]*(opnum-B[i])+L[i]*B[i],B[i]));
      }
  }

  if(v.size()==0){
      if(taka>=aoki) return true;
      else return false;
  }

  sort(v.begin(),v.end());
  reverse(v.begin(),v.end());
  taka+=v[0].first;

  if(taka>=aoki) return true;
  else return false;
}

int main(){
  cin>>N>>X;
  B.resize(N);
  L.resize(N);
  R.resize(N);
  for(int i=0;i<N;i++) cin>>B[i]>>L[i]>>R[i];

  for(int i=0;i<N;i++){
    uv.push_back(mkp(R[i]*(X-B[i])+L[i]*B[i],i));
    lv.push_back(mkp(L[i],i));
    bv.push_back(mkp(B[i],i));
  }

  sort(uv.begin(),uv.end());
  reverse(uv.begin(),uv.end());
  sort(lv.begin(),lv.end());
  reverse(lv.begin(),lv.end());
  sort(bv.begin(),bv.end());

  ll ok=N*X,ng=-1;
  while(ok-ng>1){
    ll mid=(ok+ng)/2;
    if(judge(mid)) ok=mid;
    else ng=mid;
  }

  cout<<ok<<endl;

  return 0;
}

