using namespace std;

typedef long long ll;
#define rg register int

const int N = 100010;

int X, n;

struct data
{
    int b, l, r;
    friend bool operator <(const data &A, const data &B){return (ll) (X - A.b) * A.r + (ll) A.b * A.l > (ll) (X - B.b) * B.r + (ll) B.b * B.l;}
}A[N];

ll sc, L, R, s[N], val[N];

inline bool chk(ll x)
{
    int cy = x / X;
    x %= X;
    ll res = 0;
    for (rg i = 1; i <= n; i++)
    {
        ll tmp = 0;
        if(i <= cy)
        {
            tmp += s[cy + 1] - val[i];
            if(x <= A[i].b)tmp += (ll) x * A[i].l;
            else tmp += (ll) A[i].b * A[i].l + (ll) (x - A[i].b) * A[i].r; 
        }
        else
        {
            tmp += s[cy];
            if(x <= A[i].b)tmp += (ll) x * A[i].l;
            else tmp += (ll) A[i].b * A[i].l + (ll) (x - A[i].b) * A[i].r;   
        }
        res = max(res, tmp);
    }
    return res >= sc;
}

int main()
{
    scanf("%d%d", &n, &X);
    for (rg i = 1; i <= n; i++)
        scanf("%d%d%d", &A[i].b, &A[i].l, &A[i].r),
        sc += (ll) A[i].b * A[i].l, R += A[i].b;
    sort(A + 1, A + n + 1);
    for (rg i = 1; i <= n; i++)
        val[i] = (ll) (X - A[i].b) * A[i].r + (ll) A[i].b * A[i].l,
        s[i] = s[i - 1] + val[i];
    ll res = R;
    while(L <= R)
    {
        ll mid = (L + R) >> 1;
        if(chk(mid))res = mid, R = mid - 1;
        else L = mid + 1;
    }
    cout << res << endl;
}

