#include <bits/stdc++.h>
using namespace std;
int main(){
	int n, x; cin >> n >> x;
	vector<int> b(n), l(n), u(n), od(n), val(n);
	long long now = 0;
	for(int i = 0; i < n; i++){
		cin >> b[i] >> l[i] >> u[i];
		now += - 1ll * l[i] * b[i];
		val[i] = 1ll * l[i] * b[i] + 1ll * (x - b[i]) * u[i];
	}
	iota(od.begin(), od.end(), 0);
	sort(od.begin(), od.end(), [&](int a, int b){
		return val[a] > val[b];
	});
	long long lo = 0, hi = 1ll * n * x, ans = -1;
	while(lo <= hi){
		long long mid = (lo+hi)>>1;
		int tk = mid / x, stk = mid % x;
		long long cur = 0;
		for(int i = 0; i < tk; i++) cur += val[od[i]];
		long long best = 0;
		for(int i = tk; i < n; i++) {
			int pick = min(b[od[i]], stk);
			int rpic = stk - pick;
			best = max(best, 1ll * l[od[i]] * pick + 1ll * u[od[i]] * rpic);
		}
		cur += best;
		if(now + cur >= 0) ans = mid, hi = mid - 1;
		else lo = mid + 1;
	}
	cout << ans << endl;
	return 0;
}

