int main()
{
	ios_base::sync_with_stdio(0); cin.tie(0); 
	int n; ll x; cin>>n>>x;
	vector<pair<ll,ii> > vec;
	for(int i=0;i<n;i++)
	{
		ll b,l,r; cin>>b>>l>>r;
		vec.pb({b,{l,r}});
	}
	ll lo=0; ll hi=x*1LL*n-1;
	ll ans=x*1LL*n;
	while(lo<=hi)
	{
		ll mid=(lo+hi)>>1;
		//suppose i only study mid days
		ll full = mid/x;
		ll partial = mid%x;
		vector<ii> diff;
		ll sum=0;
		for(int i=0;i<n;i++)
		{
			sum+=-vec[i].fi*vec[i].se.fi;
			diff.pb({vec[i].se.se*(x-vec[i].fi)+vec[i].fi*vec[i].se.fi,i});
		}
		sort(diff.rbegin(),diff.rend());
		ll S = -ll(1e18);
		ll sumfirstfull = 0;
		ll sumsecondfull=0;
		for(int i=0;i<full;i++)
		{
			sumfirstfull+=diff[i].fi;
		}
		for(int i=0;i<full+1;i++)
		{
			sumsecondfull+=diff[i].fi;
		}
		for(int j=0;j<n;j++)
		{
			int i=diff[j].se;
			ll oricost=-vec[i].fi*vec[i].se.fi;
			ll newcost=max((partial-vec[i].fi)*vec[i].se.fi,(partial-vec[i].fi)*vec[i].se.se);
			if(j<full)
			{
				oricost=vec[i].se.se*(x-vec[i].fi);
				S=max(S,sum+sumsecondfull+newcost-oricost);
			}
			else
			{
				S=max(S,sum+sumfirstfull+newcost-oricost);
			}
		}
		if(S>=0)
		{
			ans=mid; hi=mid-1;
		}
		else lo=mid+1;
	}
	cout<<ans<<'\n';
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
const int N = 2e5+50;
int n, x;
typedef pair<int,pair<int,int> > ii;
ii b[N]; 
int c[N];
int sakiakali = 0, ans;
#define fi first
#define se second
bool cmp(ii a,ii b){
	int p = x*a.se.se - a.fi*(a.se.se-a.se.fi);
	int q = x*b.se.se - b.fi*(b.se.se-b.se.fi);
	return (p>q);
}
signed main(){
	cin >> n >> x;
	for(int i=1;i<=n;i++) cin >> b[i].fi >> b[i].se.fi >> b[i].se.se;
	sort(b+1,b+n+1,cmp);
	for(int i=1;i<=n;i++) c[i] = c[i-1] + x*b[i-1].se.se - b[i-1].fi*(b[i-1].se.se-b[i-1].se.fi);
	ans = n*x;
	for(int i=1;i<=n;i++) sakiakali += b[i].fi*b[i].se.fi;
	for(int i=1;i<=n;i++){
		int a = b[i].fi, L = b[i].se.fi, R = b[i].se.se;
        int l = 0, r = x*n, sum;
        while(l<r){
            int m = (l+r)>>1;
            sum = -sakiakali;
            sum += c[m/x+1];
            if(m/x+1>i&&m%x!=0) sum+=(c[m/x+2]-c[m/x+1])-(c[i+1]-c[i]);
            m%=x;
            if(m>a) sum+= (m-a)*R + a*L;
            else sum += m*L;
            m = (l+r)>>1;
         //   cout << sum << endl;
            if (sum<0) l = m + 1;
            else r = m;
        }
        ans = min(ans,l);
	} 
	cout << ans;
}

