    }

    // llで2ぶたん
    ll lb=0, ub = N * X + 1;
    while( ub-lb > 1 ){
        ll mid = (lb+ub)/2;
        if(C(mid, b, l, u, N, X)){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    cout << ub;
    return 0;
}

