		scanf("%d%d%d", b + i, l + i, u + i);
		all -= 1LL * b[i] * l[i];
		val[i] = 1LL * (X - b[i]) * u[i] + 1LL * b[i] * l[i];
	}

	for (int i = 1; i <= n; ++i) {
		id[i] = i;
	}
	std::sort(id + 1, id + n + 1, [&](const int &x, const int &y) { return val[x] > val[y]; });
	int64 sum = 0LL;
	for (int i = 1; i <= n; ++i) {
		sum += val[id[i]];
		if (sum + all >= 0) {
			pos = i - 1;
			sum -= val[id[i]];
			break;
		}
		in[id[i]] = true;
	}

	all = sum + all;
	int64 ans = (pos + 1) * X;
	for (int i = 1; i <= n; ++i) {
		int64 tmp = all;
		if (in[i]) {
			tmp -= val[i];
