using namespace std;

struct Test {
    long long b, l, u;
    long long get(long long X) const { return u*(X-b) + l*b; }
};

int main(){
    int N; long long X;
    while(cin >> N >> X){
        vector<Test> vt(N);
        for(auto& t : vt) cin >> t.b >> t.l >> t.u;
        sort(vt.rbegin(), vt.rend(), [&](const Test& a, const Test&b){return a.get(X) < b.get(X);});
        long long L = 0, R = N*X;
        while(R-L > 1){
            long long mid = (L+R)/2;
            int last = mid/X;
            int rest = mid%X;
            bool enableTie = (rest > 0 && last > 0 && vt[last-1].get(X) == vt[last].get(X));
            long long win = 0, maxIdx = N, maxVal = 0;
            for(int i=0;i<N;i++){
                if(i < last) win += vt[i].get(X) - vt[i].l * vt[i].b;
                if(rest > 0 && (i >= last || (enableTie && vt[last].get(X) == vt[i].get(X)))){
                    long long v = (rest <= vt[i].b ? vt[i].l * rest :  vt[i].l * vt[i].b + vt[i].u * (rest - vt[i].b)) ;
                    if(v > maxVal){ maxVal = v; maxIdx = i; } 
                }
            }
            if(maxIdx != N){
                win += (rest <= vt[maxIdx].b ? vt[maxIdx].l : vt[maxIdx].u) * (rest - vt[maxIdx].b);
            }
            for(int i=(maxIdx < last ? last+1 : last);i<N;i++){
                if(i == maxIdx) continue;
                win -= vt[i].b * vt[i].l;
            }            
            if(win >= 0) R = mid;
            else L = mid;
        }
        cout << R << endl;
    }
}

