#include <bits/stdc++.h>
using namespace std;

#define int int_fast64_t

struct exam {
  int l, u, b;
  int cost(int score) const {
    int c = score >= b ? u : l;
    return c*(score - b);
  }
  int gain(int score) const {
    return cost(score) - cost(0);
  }
  int score_for_mingain(int mingain, int x) const {
    assert(gain(0) < mingain && gain(x) >= mingain);

    // invariant: gain(l)<mingain, gain(r)>=mingain
    int l=0, r=x;
    while (r-l > 1) {
      int m = (l+r)/2;
      if (gain(m) < mingain)
        l = m;
      else
        r = m;
    }
    assert(gain(l)  < mingain);
    assert(gain(r) >= mingain);
    return r;
  }
};

signed main() {
  ios_base::sync_with_stdio(false), cin.tie(nullptr);

  int n, x; cin >> n >> x;
  vector<exam> exams;
  for (int i = 0; i < n; ++i) {
    exam e;
    cin >> e.b >> e.l >> e.u;
    exams.push_back(e);
  }
  int score=0;
  for (auto& e : exams) score += e.cost(0);

  // maximize gain (more=better)
  auto key = [&](exam const& e) { return e.gain(x); };
  sort(exams.begin(), exams.end(), [&](exam const& a, exam const& b) { return key(a) > key(b); });

  const int INF = numeric_limits<int>::max();
  int best=INF;

  int max_taken = 0;
  for (; score < 0 && max_taken < n; ++max_taken) {
    auto const& e = exams[max_taken];
    assert(score < 0);
    score += e.gain(x);
  }
  assert(score >= 0);

  if (score == 0) {
    best = n*x;
  } else {
    assert(max_taken >= 1);
    for (int i = 0; i < n; ++i) {
      auto const& e = exams[i];

      int base_score = score - exams[min(i, max_taken-1)].gain(x);
      assert(base_score < 0);
      if (base_score + e.gain(x) < 0)
        continue; // can't take it, not enough gain
      best = min(best, x*(max_taken-1) + e.score_for_mingain(-base_score, x));
    }
  }
  assert(best < INF);
  cout << best << '\n';
}

