struct Node{
	int c,s,t;LL val;
	Node(int x=0,int y=0,int z=0){c=x,s=y,t=z,val=c*1ll*s+(X-c)*1ll*t;}
	inline bool operator <(const Node &a)const{return val>a.val;}
}a[maxn];
inline LL HA(int x,int k){
	if(k<=a[x].c)return a[x].s*1ll*k;
	return a[x].val-(X-k)*1ll*a[x].t;
}
inline LL HAHA(LL xx){
	LL now=0,Max=0;
	int k=xx/X,q=xx%X;
	for(int i=1;i<=k+1;++i)now+=a[i].val;
	for(int i=1;i<=k;++i)
		Max=std::max(Max,now-a[i].val+HA(i,q));
	now-=a[k+1].val;
	for(int i=k+1;i<=n;++i)
		Max=std::max(Max,now+HA(i,q));
	return Max;
}
