    }
};


bool operator<(E a, E b) {
    return a.fpr() > b.fpr();
}

const int MX = 100 * 1000 + 7;

ll prof[MX];

int main() {
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
    int n;
    cin >> n >> X;

    vector<E> e(n);
    for (E& x : e) {
        cin >> x.b >> x.l >> x.u;
    }

    sort(e.begin(), e.end());

    ll score = 0;
    for (int i = n - 1; i >= 0; i--) {
        score -= e[i].l * e[i].b;
    }

    if (score == 0) {
        cout << 0 << "\n";
        return 0;
    }

    for (int i = 0; i < n; i++) {
        prof[i] = e[i].fpr();
        if (i) {
            prof[i] += prof[i - 1];
        }
    }

    ll lg = -1, rg = n * X;
    while (rg - lg > 1) {
        ll mg = (lg + rg) >> 1;
        int full = mg / X, more = mg % X;
        bool ok = false;
        for (int i = full; i < n; i++) {
            ll cp = 0;
            if (full > 0) {
                cp = prof[full - 1];
            }
            cp += 1ll * e[i].l * e[i].b;
            ll delta = more - e[i].b;
            ll cf = (delta > 0) ? e[i].u : e[i].l;
            cp += delta * cf;
            if (cp + score >= 0) {
                ok = true;
            }
        }
        if (ok) {
            rg = mg;
        } else {
            lg = mg;
