void solve()
{
    cin >> N >> X;

    for(auto i = 0; i < N; ++i)
    {
        long long b, l, u;
        cin >> b >> l >> u;
        A.emplace_back(BLU(b, l, u));
    }

    sort(A.begin(), A.end(), [](const BLU& lhs, const BLU& rhs) {
        return -(lhs.max_d - lhs.min_d) < -(rhs.max_d - rhs.min_d);
    });

    for(auto i = 0; i < N; ++i) {
        auto p = A[i].b * A[i].u;
        auto q = A[i].b * A[i].l;
        auto t = X * A[i].u;
        if(i > 0) {
            p += S_AU.back();
            q += S_AL.back();
            t += S_BU.back();
        }
        S_AU.emplace_back(p);
        S_AL.emplace_back(q);
        S_BU.emplace_back(t);
    }

    long long l = -1;
    long long r = N * X;

    while(l+1 < r) {
        long long m = (l+r) / 2;
        if(check(m))
            r = m;
        else
            l = m;
    }

    cout << r << endl;
}

