struct Test {
	long long int b, l, u;
	long long int gain_at(const int time) const {
		if (time > b) {
			return (time - b) * u;
		}
		else {
			return (time - b) * l;
		}
	}
	long long int need_time_from_zero(long long int target_score) const {
		if (target_score < l * b) {
			return ((target_score + l - 1) / l);
		}
		else {
			return ((target_score + u - 1 - l * b) / u) + b;
		}
	}
};
int main() {
	int n, x; std::cin >> n >> x;
	std::vector<Test> tests(n);
	for (auto& test : tests) std::cin >> test.b >> test.l >> test.u;
	std::sort(tests.begin(), tests.end(), [=](const Test& a, const Test& b) {return (a.gain_at(x) - a.gain_at(0)) > (b.gain_at(x) - b.gain_at(0)); });
	long long int default_score = 0;
	for (const auto& test : tests) {
		default_score += test.gain_at(0);
	}
	auto count = 0;
	while (count < n && default_score + tests[count].gain_at(x) - tests[count].gain_at(0) < 0) {
		default_score += tests[count].gain_at(x) - tests[count].gain_at(0);
		++count;
	}
	long long int time = static_cast<long long int>(count) * x;
	auto min_time = LLONG_MAX;
	while (count > 0 && (tests[count - 1].gain_at(x) - tests[count - 1].gain_at(0)) == (tests[count].gain_at(x) - tests[count].gain_at(0))) {
		--count;
	}
	for (auto i = count; i < n; ++i) {
		auto need_time = tests[i].need_time_from_zero(-default_score);
		if (min_time > need_time) {
			min_time = need_time;
		}
	}
	std::cout << time + min_time << std::endl;
}

