typedef long long ll;

ll n, x;

struct test {
    ll b, l, u;
    bool operator< (const test &o) const { return (b*l + (x - b)*u) > (o.b*o.l + (x - o.b)*o.u); }
};
vector<test> tests;

bool can(ll hrs) {
    ll score = 0;
    int i = 0;
    for(i = 0; i < n; i++) {
        if(hrs < x)
            break;
        score += (x - tests[i].b)*tests[i].u;
        hrs -= x;
    }
    for(int j = i; j < n; j++) {
        score -= tests[j].b * tests[j].l;
    }
    ll bestEx = 0;
    for(int j = i; j < n; j++) {
        ll tmp = (hrs >= tests[j].b ? (tests[j].b*tests[j].l + (hrs - tests[j].b)*tests[j].u) : hrs*tests[j].l);
        bestEx = max(tmp, bestEx);
    }
    score += bestEx;
    //cout << score << '\n';
    return score >= 0ll;
}

int main() {
    cin >> n >> x;
    for(int i = 0; i < n; i++) {
        ll b, l, u;
