        tests.push_back({b, l, u});
    }
    sort(tests.begin(), tests.end());
    ll lo = 0;
    ll hi = n*x;
    while(lo < hi) {
        ll mi = (lo + hi)/2ll;
        if(can(mi))
            hi = mi;
        else
            lo = mi + 1;
    }
