      int a = l[f[i].se]*min(b[f[i].se],r)+u[f[i].se]*max(0LL,r-b[f[i].se]);
      if(i<q) sum += f[i+1].fi - f[i].fi;
      maxs(mx,sum+a);
    }
    if(mx<d0) le = m;
    else ri = m;
  }
  cout << ri << endl;
}

