int B[MAX_N], L[MAX_N], U[MAX_N];

int main( int argc, char **argv )
{
    ll N, X;
    cin >> N >> X;

    for ( int i = 0; i < N; i++ ) cin >> B[i] >> L[i] >> U[i];

    priority_queue<P> que;
    ll S = 0;
    for ( int i = 0; i < N; i++ )
    {
        S += B[i] * L[i];

        que.push( P( U[i] * ( X - B[i] ), i ) );
    }

    ll ans = 0;
    ll score = 0;
    while ( score < S && !que.empty() )
    {
        auto p = que.top();
        que.pop();

        int i = p.second;

        S += B[i] * ( U[i] - L[i] );

        ll tmp = min( X, (ll)ceil( ( S - score ) / U[i] ) );
        ans += tmp;
        score += tmp * U[i];
    }

    cout << ans << endl;

    return 0;
}

