void chemthan() {
    int n, x; cin >> n >> x;
    vi b(n), l(n), u(n);
    FOR(i, 0, n) cin >> b[i] >> l[i] >> u[i];
    vi vals;
    FOR(i, 0, n) {
        vals.pb(i);
    }
    long long lo = 0, hi = LINF;
    while (lo < hi) {
        sort(all(vals), [&] (int i, int j) {
                return (long long) (x - b[i]) * u[i] > (long long) (x - b[j]) * u[j];
                }
            );
        long long mi = lo + hi >> 1;
        long long num = mi / x;
        long long r = mi % x;
        int found = 0;
        if (n <= num) {
            found = 1;
        }
        else {
            long long sum = 0;
            FOR(i, 0, num) {
                int j = vals[i];
                sum += (long long) (x - b[j]) * u[j];
            }
            long long mx = -LINF;
            FOR(it, 0, 2) {
                if (!it) {
                    sort(vals.begin() + num, vals.end(), [&] (int i, int j) {
                            return u[i] > u[j];
                            }
                        );
                }
                else {
                    sort(vals.begin() + num, vals.end(), [&] (int i, int j) {
                            return l[i] > l[j];
                            }
                        );
                }
                int j = vals[num];
                long long tmp = 0;
                if (b[j] <= r) {
                    tmp += (long long) (r - b[j]) * u[j];
                }
                else {
                    tmp += (long long) (r - b[j]) * l[j];
                }
                FOR(i, num + 1, n) {
                    int j = vals[i];
                    tmp -= (long long) b[j] * l[j];
                }
                chkmax(mx, sum + tmp);
            }
            if (0 <= mx) {
                found = 1;
            }
        }
        if (!found) {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
    cout << (lo + hi >> 1) << "\n";
}

