int binpow (int a, int n) {
    int res = 1;
    while (n) {
        if (n & 1)
            res = 1ll * res * a % mod;
        a = 1ll * a * a % mod;
        n >>= 1;
    }
    return res;
}

int b[maxn], l[maxn], r[maxn];

int main() {
    // files1;
    fast_io;

    int n;
    cin >> n;

    int x;
    cin >> x;

    for (int i = 0; i < n; i++) {
        cin >> b[i] >> l[i] >> r[i];
        // if not taking -b[i]l[i]
        // taking for b[i] gives r[i] for each point with max (X-b[i]) times
    }

    vector<int> ord(n);
    iota(all(ord), 0);
    sort(all(ord), [&](int i, int j){
        return 1ll * r[i] * (x - b[i]) + 1ll * l[i] * b[i] > 1ll * r[j] * (x - b[j]) + 1ll * l[j] * b[j];
    });

    ll l = 0, r = 1e10;

    auto can = [&](ll m){

        ll maxfull = m / x;
        ll rest = m % x;

        ll sum = 0;

        int i = 0;
        while (i < n && maxfull) {
            sum += 1ll * ::r[ord[i]] * (x - b[ord[i]]);
            i++;
            maxfull--;
        }

        if (i != n) {
            for (int j = i; j < n; j++) {
                sum -= 1ll * ::l[ord[j]] * b[ord[j]];
            }

            ll maxdelta = 0;
            for (int j = i; j < n; j++) {
                int y = ord[j];
                ll curdelta;
                if (rest >= b[y]) {
                    curdelta = 1ll * ::l[y] * b[y] + 1ll * (rest - b[y]) * ::r[y];
                    upmax(maxdelta, curdelta);
                }
            }


            vector<pair<int, int>> ord2;
            for (int j = i; j < n; j++) {
                ord2.push_back({ord[j], 0});
                ord2.push_back({ord[j], 1});
            }

            sort(all(ord2), [&](pair<int, int> a, pair<int, int> b){
                return (a.s ? ::r[a.f] : ::l[a.f]) > (b.s ? ::r[b.f] : ::l[b.f]);
            });

            ll delta2 = 0;
            for (auto [i, tp] : ord2) {
                if (tp == 0) {
                    // l[i]
                    ll taken = min<ll>(b[i], rest);
                    rest -= taken;
                    delta2 += 1ll * ::l[i] * taken;
                } else {
                    // r[i]
                    if (rest >= b[i]) {
                        upmax(maxdelta, delta2 + 1ll * ::l[i] * b[i] + 1ll * (rest - b[i]) * ::r[i]);
                    }
                }
            }
            upmax(maxdelta, delta2);
            sum += maxdelta;
        }
        return sum >= 0;
    };

    // cout << can(74);
    // return 0;

    while (r - l > 0) {
        ll m = (l + r) >> 1;

        if (can(m)) {
            r = m;
        } else {
            l = m + 1;
        }
    }
    cout << l;
    return 0;
}

