vec<tuple<ll, ll, ll, ll>> tests;
vll cumsum;
int N, X;
ll offset = 0;

bool check2(int idx, int q, int r) {
    ll sum = cumsum[q];
    if (idx < q) {
        sum -= get<0>(tests[idx]);
        sum += get<0>(tests[q]);
    }
    if (r > get<1>(tests[idx])) {
        sum += get<1>(tests[idx]) * get<2>(tests[idx]);
        sum += (r - get<1>(tests[idx])) * get<3>(tests[idx]);
    } else {
        sum += r * get<2>(tests[idx]);
    }
    return sum >= offset;
}

bool check1(int num) {
    assert(num >= 0);
    return true;
    int q = num / X, r = num % X;
    rep(i, N) {
        if (check2(i, q, r)) {
            return true;
        }
    }
    return false;
}

int main(void) {
    cin >> N >> X;
    tests = vec<tuple<ll, ll, ll, ll>>(N);
    cumsum = vll(N + 1, 0);
    ll bsum = 0;

    rep(i, N) {
        ll b, l, u;
        cin >> b >> l >> u;
        tests[i] = mt(b * l + (X - b) * u, b, l, u);
        offset += b * l;
        bsum += b;
    }
    sort(rall(tests));
    rep(i, N) {
        cumsum[i + 1] = cumsum[i] + get<0>(tests[i]);
    }

    int ng = -1, ok = bsum;
    while (ok - ng > 1) {
        int m = (ng + ok) / 2;
        if (check1(m)) {
            ok = m;
        } else {
            ng = m;
        }
    }
    cout << ok << endl;

    return 0;
}

