using namespace std;
typedef long long ll;
typedef unsigned long long ull;
typedef pair<int, int> pi;
typedef pair<ll, ll> pl;
const double EPS = 1e-9;
const ll mod = 1000000007;
const int inf = 1 << 30;
const ll linf = 1LL << 60;
const double PI = 3.14159265358979323846;

ll n, x;
ll b[100000], l[100000], u[100000];
pl ho[100000], ge[100000];
ll eg[100000];
bool saw[100000];
ll target;

bool solve(ll mid) {
    ll p = mid / x, q = mid % x;
    rep(i,n) {
        ho[i] = pl(x * u[i] - (u[i]-l[i]) * b[i], i);
        if (b[i] >= q) {
            ge[i] = pl(q * l[i], i);
        } else {
            ge[i] = pl(q * u[i] - (u[i]-l[i]) * b[i], i);
        }
    }
    sort(ho, ho+n, greater<pl>());
    sort(ge, ge+n, greater<pl>());
    rep(i,n) eg[ge[i].second] = i;
    ll val = 0, add = 0;
    memset(saw, 0, sizeof(saw));
    rep(i,p) {
        val += ho[i].first;
        saw[ho[i].second] = true;
    }
    rep(i,n) {
        if (saw[ge[i].second]) continue;
        val += ge[i].first;
        add = ge[i].first;
        break;
    }
    ll ret = val;
    rep(i,p) {
        ll tmp = val;
        tmp -= ho[i].first;
        tmp += ge[eg[ho[i].second]].first;
        tmp -= add;
        tmp += ho[p].first;
        ret = max(ret, tmp);
    }
    return (ret >= target);
}

int main() {
    cin >> n >> x;
    rep(i,n) cin >> b[i] >> l[i] >> u[i];
    rep(i,n) target += l[i] * b[i];
    ll le = -1, ri = x*n;
    while (ri-le > 1) {
        ll mid = (ri + le) / 2;
        if (solve(mid)) ri = mid;
        else le = mid;
    }
    cout << ri << endl;
}

