        tot += op[i].f*op[i].s.f;
    }
    //cout << "tot is " << tot << "\n";

    sort(op+1, op+1+n, comp);
    /*FOR(i, 1, n){
        cout << op[i].f << " " << op[i].s.f << " " << op[i].s.s << "\n";
    }*/

    ll l=0, r=n*x;
