using ll = long long;

struct T {
    ll b, l, u;
    T() {}
    T(ll b, ll l, ll u) : b(b), l(l), u(u) {}
};

ll N, X;
T A[101010];

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    cin >> N >> X;
    for (int i = 0; i < N; ++i) cin >> A[i].b >> A[i].l >> A[i].u;
    sort(A, A+N, [&](T y, T z) {
            return X * y.u - (y.u - y.l) * y.b > X * z.u - (z.u - z.l) * z.b;
    });

    ll rest = 0;
    for (int i = 0; i < N; ++i) rest += A[i].l * A[i].b;

    ll ans = 0;
    for (int i = 0; i < N; ++i) {
        if (rest <= 0) break;
        T& x = A[i];


        ll q = min(X, (rest + (x.u - x.l) * x.b + x.u - 1) / x.u);
        if (rest + (x.u - x.l) * x.b - x.u * q <= 0) {
            ll r = q;
            for (int j = i; j < N; ++j) {
                if (rest - x.l * x.b >= 0) {
                    r = min(r, (rest - x.l * x.b + x.u * x.b + x.u - 1) / x.u);
                } else {
                    r = min(r, (rest - x.l * x.b + x.l * x.b + x.l - 1) / x.l);
                }
            }
            ans += r;
            break;
        }
        ans += q;
        rest += (x.u - x.l) * x.b - x.u * q;
    }
    cout << ans << endl;

    return 0;
}

