typedef pair<int, pii> pipii;
typedef pair<pii, int> ppiii;
typedef vector<vector<ll>> matrix;

int n, x;
pipii l[100005]; // <hours, <lower, upper>>

ll gain(pipii a, ll h) {
  assert(h <= x);
  ll ret = 0;
  ret += min(a.first, (int)h) * (ll)a.second.first;
  ret += max(0LL, h - a.first) * (ll)a.second.second;
  return ret;
}

bool can(ll t) {
  ll need = 0;
  for(int i = 0; i < n; i++) {
    need += l[i].first * (ll)l[i].second.first;
  }
  vector<pipii> leftover;
  for(int i = 0; i < n; i++) {
    if(t >= x) {
      need -= gain(l[i], x);
      t -= x;
    }
    else {
      leftover.push_back(l[i]);
    }
  }
  if(t) {
    assert(t < x);
    ll maxInc = 0;
    for(pipii out: leftover) {
      maxInc = max(maxInc, gain(out, t));
    }
    need -= maxInc;
  }
  return need <= 0;
}

bool cmp(pipii a, pipii b) {
  return gain(a, x) > gain(b, x);
}

void solve() {
  cin >> n >> x;
  for(int i = 0; i < n; i++) {
    cin >> l[i].first >> l[i].second.first >> l[i].second.second;
  }
  sort(l, l+n, cmp);
  ll lhs = 0;
  ll rhs = n * (ll)x;
  while(lhs != rhs) {
    ll mid = (lhs+rhs)/2;
    if(can(mid)) rhs = mid;
    else lhs = mid+1;
  }
  cout << lhs << "\n";
}

