        border += b * l;
    }
    sort(maxLead.rbegin(), maxLead.rend());

    vector<long> sumMaxLead {};
    {
        long prevSum=0;
        for (int i=0; i<N; i++) {
            long curSum = prevSum + maxLead[i][0];
            sumMaxLead.push_back(curSum);
            prevSum = curSum;
        }
    }

    long min_e = LONG_MAX;
    for (int i=0; i<N; i++) {
        long s = maxLead[i][0];
        long b = maxLead[i][1];
