LL X;
struct Node {
	LL b, l, u;
};
bool operator<(Node A, Node B) {
	LL sA = A.u * X + A.b * A.l - A.u * A.b;
	LL sB = B.u * X + B.b * B.l - B.u * B.b;
	return sA < sB;
}

LL lefts[100005], rights[100005];
void solve(int ks) {
	int n;
	vector<Node> V;
	scanf("%d %lld", &n, &X);
	for (int i = 0; i < n; i++) {
		Node p;
		scanf("%lld %lld %lld", &p.b, &p.l, &p.u);
		V.push_back(p);
	}
	sort(ALL(V));
	LL ans = 0;
	for (int i = 0; i < n; i++) {
		auto& p = V[i];
		ans += p.b;
		LL cur = -p.b * p.l;
		lefts[i + 1] = lefts[i] + cur;
	}
	for (int i = n - 1; i >= 0; i--) {
		auto& p = V[i];
		LL cur = X * p.u - p.b * p.u;
		rights[i + 1] = rights[i + 2] + cur;
	}
	for (int i = 1; i <= n; i++) {
		auto& p = V[i - 1];
		LL left_cost = lefts[i - 1];
		LL right_cost = rights[i + 1];
		LL C = -(right_cost + left_cost);
		LL curA = 0;
		if (C >= 0) {
			curA = p.b + (C + p.u - 1) / p.u;
			if (curA > X) continue;
			LL candi = curA + (n - i) * X;
			ans = MIN(ans, candi);
		}
		else {
			curA = p.b + C / p.l;
			if (curA < 0) curA = 0;
			LL candi = curA + (n - i) * X;
			ans = MIN(ans, candi);
		}
	}
	printf("%lld\n", ans);
}

