ll calc(ll mid) {
    ll res = 0;
    int cnt1 = mid / x;
    int cnt2 = mid % x;
    for (int i = 1; i <= cnt1; ++i)
        res += aoki[i].val;
    if (cnt2 == 0) return res;
    ll sum = 0;
    for (ri i = 1; i <= n; ++i) {
        ll tmp = 0;
        if (cnt2 >= aoki[i].b) tmp = (cnt2 - aoki[i].b) * aoki[i].r + aoki[i].l * aoki[i].b;
        else tmp = cnt2 * aoki[i].l;
        if (i <= cnt1) sum = max(sum, res - aoki[i].val + tmp + aoki[cnt1 + 1].val);
        else sum = max(sum, res + tmp);
    }
    return sum;
}

