const int N = 1e5 + 5;
int n, x, B[N], L[N], U[N];
LL Gain[N], margin = 0;
map<LL, vector<int>> M;

bool check(LL budget) {
  auto p = M.end();
  LL ans = 0;
  while (true) {
    p = prev(p, 1);
    int sz = p->second.size();
    if (1LL * x * sz > budget) {
      LL cnt = budget / x, r = budget % x;
      ans += cnt * p->first;
      LL maxv = 0;
      for (auto i : p->second) {
        if (r <= B[i])
          maxv = max(maxv, 1LL * L[i] * r);
        else
          maxv = max(maxv, 1LL * U[i] * (r - B[i]) + 1LL * L[i] * B[i]);
      }
      ans += maxv;
      break;
    } else {
      budget -= 1LL * x * sz;
      ans += p->first * sz;
    }
    if (p == M.begin()) break;
  }
  return ans >= margin;
}

int main() {
  cin >> n >> x;
  FI(i, 1, n) scanf("%d%d%d", &B[i], &L[i], &U[i]);
  FI(i, 1, n) margin += 1LL * L[i] * B[i];
  FI(i, 1, n) Gain[i] = 1LL * U[i] * (x - B[i]) + 1LL * L[i] * B[i];
  FI(i, 1, n) M[Gain[i]].push_back(i);
  LL l = 0, r = 1e10;
  while (l + 1 < r) {
    LL m = (l + r + 1) / 2;
    if (check(m))
      r = m;
    else
      l = m;
  }
  cout << r << endl;
}

