#define FOR_LT(i, beg, end) for (int i = beg; i < end; i++)
#define FOR_LE(i, beg, end) for (int i = beg; i <= end; i++)
#define FOR_DW(i, beg, end) for (int i = beg; end <= i; i--)

using namespace std;

struct Test {
	int64_t b;
	int64_t l;
	int64_t u;
	int64_t pmin;
	int64_t gmax;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int64_t n, x; cin >> n >> x;

	int64_t penalty = 0;
	vector<Test> tests(n);
	{
		for (auto& test : tests) {
			cin >> test.b >> test.l >> test.u;
			test.pmin = test.b * test.l;
			test.gmax = (x - test.b) * test.u + test.pmin;

			penalty += test.pmin;
		}
	}

	sort(tests.begin(), tests.end(), [](const Test& lhs, const Test& rhs) {
		return lhs.gmax > rhs.gmax;
	});

	vector<int64_t> vals(n);
	{
		int64_t sum = 0;
		FOR_LT(i, 0, n) {
			sum += tests[i].gmax;
			vals[i] = sum;
		}
	}

	int64_t min_s = INT64_MAX;
	FOR_LT(i, 0, n) {
		auto rem = tests[i];

		int64_t cur_remp = penalty - rem.gmax;
		auto it = lower_bound(vals.begin(), vals.end(), cur_remp);
		int  bi = it - vals.begin();

		cur_remp -= *it;

		int64_t s = (bi + 1) * x;
		if (i <= bi) {
			cur_remp += rem.gmax;
			s -= x;

			int ai = bi + 1;
			while (ai < n && cur_remp >= 0) {
				s += x;
				cur_remp -= tests[ai].gmax;
				ai++;
			}
		}

		cur_remp += rem.gmax;

		if (cur_remp < 0) continue;

		if (cur_remp < rem.pmin) {
			s += (cur_remp + rem.l - 1) / rem.l;
		}
		else {
			s += rem.b + (cur_remp - rem.pmin + rem.u - 1) / rem.u;
		}

		min_s = min(min_s, s);
	}


	cout << min_s << endl;


	return 0;
}

