const int N = 2e6 + 5;
int n, k;
int Rank[N], Tmp[N];
char S[N];

bool compare_sa(int i, int j) {
    if (Rank[i] != Rank[j]) return Rank[i] < Rank[j];
    else {
        int ri = i + k <= n ? Rank[i + k] : -1;
        int rj = j + k <= n ? Rank[j + k] : -1;
        return ri < rj;
    }
}

void construct_sa(vector<int>& sa) {
    sa.resize(n + 1);
    for (int i = 0; i <= n; i++) {
        sa[i] = i;
        Rank[i] = i < n ? S[i] : -1;
    }
    for (k = 1; k <= n; k <<= 1) {
        sort(sa.begin(), sa.end(), compare_sa);
        Tmp[sa[0]] = 0;
        for (int i = 1; i <= n; i++) {
            Tmp[sa[i]] = Tmp[sa[i - 1]] + (compare_sa(sa[i - 1], sa[i]) ? 1 : 0);
        }
        for (int i = 0; i <= n; i++) Rank[i] = Tmp[i];
    }
}
void construct_lcp(vector<int>& sa, vector<int>& lcp) {
    lcp.resize(n + 1);
    for (int i = 0; i <= n; i++) Rank[sa[i]] = i;
    int h = 0;
    lcp[0] = 0;
    for (int i = 0; i < n; i++) {
        int j = sa[Rank[i] - 1];
        if (h > 0) h--;
        for (; j + h < n && i + h < n; h++) if (S[j + h] != S[i + h]) break;
        lcp[Rank[i] - 1] = h;
    }
}

vector<int> Sa, Lcp;

int main() {
    int a, b;
    while (~scanf("%s%d%d", S, &a, &b)) {
        n = strlen(S);
        construct_sa(Sa);
        construct_lcp(Sa, Lcp);
        LL ans = 0;
        deque<int> Q1, Q2;
        for (int i = n - 1; i >= 0; i--) {
            while (!Q1.empty() && Lcp[Q1.back()] >= Lcp[i]) Q1.pop_back();
            while (!Q2.empty() && Lcp[Q2.back()] >= Lcp[i]) Q2.pop_back();
            Q1.push_back(i);
            Q2.push_back(i);
            while (!Q1.empty() && Q1.front() - a > i) Q1.pop_front();
            while (!Q2.empty() && Q2.front() - b > i) Q2.pop_front();
            ans += Lcp[Q2.front()] - Lcp[Q1.front()] + 1;
        }
        printf("%lld\n", ans);
    }
    return 0;
}

