signed main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  ll n, x; cin >> n >> x;
  ll bsum = 0;
  vector<P> vec(n);
  vector<P> vec2(n);
  vector<ll> aoki(n);

  rep(i, n) {
    ll b, l, u; cin >> b >> l >> u;
    bsum += b;
    vec[i] = {(x-b)*u+b*l, i};
    vec2[i] = P(l, u);
    aoki[i] = b;
  }

  sort(vec.rbegin(), vec.rend());

  vector<ll> perm(n);
  vector<ll> sum(n+1);
  vector<ll> rsum(n+1);
  rep(i, n) {
    int pos = vec[i].second;
    perm[pos] = i;

    sum[i+1] = sum[i] + (x-aoki[pos])*vec2[pos].second;
    rsum[i] = aoki[pos]*vec2[pos].first;
  }
  for(int i=n-1; i>=0; i--) {
    rsum[i] += rsum[i+1];
  }

  ll mi = -1;
  ll ma = bsum;
  while(mi+1 < ma) {
    auto med = (mi+ma)/2;
    auto p = med/x;
    auto r = med%x;
    ll now = 0;
    bool flag = false;
    //debug(p); debugln(r);
    rep(i, n) {
      ll now = 0;
      if (r <= aoki[i]) {
        now -= (aoki[i]-r)*vec2[i].first;
      } else {
        now += (r-aoki[i])*vec2[i].second;
      }
      int pos = perm[i];

      if (pos < p) {
        now += sum[p+1];
        now -= rsum[p+1];
        now -= (x-aoki[i])*vec2[i].second;
      } else {
        now += sum[p];
        now -= rsum[p];
        now += aoki[i]*vec2[i].first;
      }
      //debug(i); debugln(now);
      if (now>=0) {
        flag = true;
        break;
      }
    }

    if (flag) {
      ma = med;
    } else {
      mi = med;
    }
  }
  cout << ma << endl;
}

