const int maxn = 100111;
int n;
ll X;
ll b[maxn], l[maxn], r[maxn];
ll sum[maxn], L;
int search(ll dlt)
{
	int l = 0, r = n;
	while (l<=r)
	{
		int m = l+r>>1;
		if (sum[m]+dlt<=L) l = m+1;
		else r = m-1;
	}
	return r;
}
int main()
{
	getii(n, X);
	vector<pair<ll,int> > v;
	for (int i=1; i<=n; i++)
	{
		geti(b[i]);
		getii(l[i], r[i]);
		v.PB(MP(1ll*l[i]*b[i]+1ll*r[i]*(X-b[i]), i));
		L += l[i]*b[i];
	}
	sort(v.begin(), v.end());
	reverse(v.begin(), v.end());
	sum[0] = 0;
	for (int i=1; i<=n; i++) sum[i] = sum[i-1]+v[i-1].FF;
	ll ans = 1e18;
	for (int t=0; t<v.size(); t++)
	{
		{
			int it = search(-v[t].FF);
			ll cur = L-(sum[it]-v[t].FF);
			int i = v[t].SS;
			if (cur<=l[i]*b[i]) ans = min(ans, 1ll*(it-(t<it))*X+(cur+l[i]-1)/l[i]);
		}
		{
			int i = v[t].SS;
			int it = search(-v[t].FF+l[i]*b[i]);
			ll cur = L-(sum[it]-v[t].FF+l[i]*b[i]);
			if (cur<=r[i]*(X-b[i])) ans = min(ans, 1ll*(it-(t<it))*X+b[i]+(cur+r[i]-1)/r[i]);
		}
	}
	cout<<ans<<endl;
	return 0;
}

