typedef long long ll;
typedef long double ld;
int main() {
	int n, X;
	scanf("%d%d", &n, &X);
	struct Exam {
		int b, l, u;
		ll add;
	};
	vector<Exam> E(n);
	vector<ll> psum(n + 1);
	ll base = 0;
	for (int i = 0; i < n; ++i) {
		scanf("%d%d%d", &E[i].b, &E[i].l, &E[i].u);
		E[i].add = (ll)E[i].u * (X - E[i].b) + (ll)E[i].l * E[i].b;
		base -= (ll)E[i].l * E[i].b;
	}
	sort(E.begin(), E.end(), [&](Exam a, Exam b) {
		return a.add > b.add;
	});
	for (int i = 0; i < n; ++i) {
		psum[i + 1] = psum[i] + E[i].add;
	}
	ll lo = 0, hi = (ll)n * X;
	while (lo < hi) {
		ll m = (lo + hi) >> 1;
		ll add = LLONG_MIN;
		int take = m / X;
		int extra = m % X;
		if (extra == 0) {
			add = psum[take];
		} else {
			assert(take < n);
			for (int i = 0; i < n; ++i) {
				ll single = (ll)E[i].l * min(E[i].b, extra);
				if (extra > E[i].b) single += (ll)E[i].u * (extra - E[i].b);
				ll v;
				if (i < take) {
					v = psum[take + 1] - E[i].add + single;
				} else {
					v = psum[take] + single;
				}
				add = max(add, v);
			}
		}
		if (add + base >= 0) hi = m;
		else lo = m + 1;
	}
	printf("%lld\n", lo);
}

