    ll n, x;
    cin >> n >> x;
    vector<ll> b(n), l(n), u(n);
    REP(i, n) cin >> b[i] >> l[i] >> u[i];

    vector<PII> vp(n);
    vector<ll> s(n), rank(n);
    REP(i, n) vp[i] = {b[i]*l[i] + (x-b[i])*u[i], i};
    sort(ALL(vp), greater<>());
    REP(i, n) s[i] = vp[i].first, rank[vp[i].second] = i;
    ll sumb = 0;
    REP(i, n) sumb += b[i] * l[i];

    auto check = [&](ll k) {
        ll q = k/x, r = k%x, sum1 = 0, sum2 = 0, ma = 0;
        if(q == n) return true;
        REP(i, q) sum1 += s[i];
        sum2 = sum1 - (q==0?0:s[q-1]) + s[q];
        REP(i, n) {
            ll score = 0;
            // i番目のテストはr時間
            if(r > b[i]) score += b[i]*l[i] + (r-b[i])*u[i];
            else score += r*l[i];
            // i番目のテストを除いてs[j]が大きい方からq個
            if(rank[i] < q) score += sum2;
            else score += sum1;
            chmax(ma, score);
        }
        return ma - sumb >= 0;
    };

    ll lb=-1, ub=n*x;
    while(ub-lb>1) {
        ll mid = (lb+ub)/2;
        if(check(mid)) ub = mid;
        else lb = mid;
    }
