bool judge(ll c){
    ll m = c/X;
    ll score = 0;
    for(int i = 0; i < m; i++){
        ll s = p[i].first;
        int idx = p[i].second;
        score += s;
    }
    if(c%X != 0){
        int rem = c%X;
        vector<P> v;
        for(int i = m; i < N; i++){
            int idx = p[i].second;
            v.push_back(P(u[idx]*(rem-b[idx]) + b[idx]*l[idx], idx));
            v.push_back(P(l[idx]*(rem-b[idx]) + b[idx]*l[idx], idx));
            //cout << (u[idx]*(rem-b[idx])) << endl;
        }
        sort(v.begin(), v.end(), greater<P>());
        int idx = v[0].second;
        score += v[0].first;
        m++;
    }
    //cout << base+score << endl;
    if(base+score >= 0) return true;
    else return false;
}

