long long cal(long long x, long long y)
{
    if(x <= a[y].b)
        return x * a[y].l;
    return a[y].b * a[y].l + (x - a[y].b) * a[y].r;
}

inline bool check(long long k)
{
    long long ans = 0, r = k % X, t = k / X;
    if(t >= n)
        return sum[n];
    for(int i = 1; i <= n; i++)
	{
        if(i <= t)
			ans = std::max(ans, cal(r, i) + sum[t + 1] - a[i].w);
        else
            ans = std::max(ans, cal(r, i) + sum[t]);
    }
    return ans >= D;
}

