int calc(int k) {
	int i;
	int A = 0, B = 0;
	static int c[100000];

	rep(i, n) {
		if (i < k) c[i] = u[i];
		else c[i] = l[i];
	}
	rep(i, n) B += c[i] * b[i];

	sort(c, c + n, greater<int>());

	int t = 0;
	rep(i, n) {
		if (A + c[i] * x >= B) {
			t += (B - A + c[i] - 1) / c[i];
			return t;
		}
		else {
			t += x;
			A += c[i] * x;
		}
	}
	return 1e+18;
}

