const int maxn = (int) 1e5 + 5;
int n, x;
int b[maxn], l[maxn], u[maxn];

bool read() {
  if (scanf("%d%d", &n, &x) < 2) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    scanf("%d%d%d", &b[i], &l[i], &u[i]);
  }
  return true;
}

int used[maxn];
pair<long long, int> tosort[maxn];

void solve() {
  for (int i = 0; i < n; i++) {
    used[i] = false;
    tosort[i] = make_pair((long long) x * u[i] - (long long) b[i] * (u[i] - l[i]), i);
  }
  sort(tosort, tosort + n, greater<pair<int, int>>());
  long long s = 0;
  for (int i = 0; i < n; i++) {
    s -= (long long) b[i] * l[i];
  }
  int pos = 0;
  long long val = 0;
  while (s + tosort[pos].first < 0) {
    s += tosort[pos].first;
    used[tosort[pos].second] = true;
    val += x;
    pos++;
  }
  long long res = infll;
  for (int i = 0; i < n; i++) {
    if (used[i]) {
      continue;
    }
    long long curs = s;
    long long cur = val;
    if (curs + (long long) b[i] * l[i] >= 0) {
      long long k = (-curs + l[i] - 1) / l[i];
      curs += k * l[i];
      cur += k;
      res = min(res, cur);
    } else {
      curs += (long long) b[i] * l[i];
      cur += b[i];
      if (curs + (long long) (x - b[i]) * u[i] >= 0) {
        long long k = (-curs + u[i] - 1) / u[i];
        curs += k * u[i];
        cur += k;
        res = min(res, cur);
      }
    }
  }
  printf("%lld\n", res);
}

