		df -= b[i]*l[i];
		ok += b[i];
	}
	sort(v.begin(),v.end(),comp);
	ng = 0ll;
	while(ok-ng>1){
		mid = (ok+ng)>>1;
		if(judge(mid)){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	cout << ok << endl;
	return 0;
}

