namespace {
  ll read() {
    ll x;
    cin >> x;
    return x;
  }

  string reads() {
    string s;
    cin >> s;
    return s;
  }

  template<class T>
  void write(T x) {
    cout << x << ' ';
  }

  void newline() {
    cout << '\n';
  }
}

int main() {
  int N = read();
  ll X = read();
  vector<ll> B(N), L(N), U(N);
  ll bottom = 0;
  for (int i = 0; i < N; i++) {
    B[i] = read();
    L[i] = read();
    U[i] = read();
    bottom -= L[i] * B[i];
  }
  vector<int> ord(N);
  for (int i = 0; i < N; i++) {
    ord[i] = i;
  }
  auto f = [&](int i) {
    return U[i] * (X - B[i]) + L[i] * B[i];
  };
  sort(ord.begin(), ord.end(), [&](int i, int j) {
    return f(i) > f(j);
  });
  ll l = -1;
  ll r = X * N;
  while (r - l > 1) {
    ll m = (l + r) / 2;
    ll top = 0;
    ll top2 = 0;
    vector<bool> used(N);
    for (int ii = 0; ii < m / X; ii++) {
      int i = ord[ii];
      top += f(i);
      used[i] = true;
    }
    for (int ii = 0; ii < m / X + 1; ii++) {
      int i = ord[ii];
      top2 += f(i);
    }
    ll mx = -1;
    for (int i = 0; i < N; i++) {
      ll val = bottom;
      if (!used[i]) {
        val += top;
      } else {
        val += top2 - f(i);
      }
      val += min(B[i], m % X) * L[i];
      val += max(0LL, m % X - B[i]) * U[i];
      mx = max(mx, val);
    }
    (mx >= 0 ? r : l) = m;
  }
  write(r);
  newline();
}

