int main(){
  ini(N,X);
  vi b(N),l(N),u(N);
  ll must = 0;
  rep(i,N){
    in(b[i],l[i],u[i]);
    must += b[i] * l[i];
  }
  vi ord(N);
  iota(all(ord) , 0);
  sort(all(ord) , [&](int left,int right){
    return l[left]*b[left]+(X-b[left])*u[left]>l[right]*b[right]+(X-b[right])*u[right];
  } );
  int idx = 0; ll ans = 0;
  while(1){
    int cur = ord[idx];
    ll maxcur = l[cur]*b[cur]+(X-b[cur])*u[cur];
    if(must > maxcur){
      must -= maxcur; idx++; ans += X;
    }
    else {
      int m = inf;
      while(idx != N){
        int a = (must > l[idx] * X ? inf : (must + l[idx] - 1) / l[idx]);
        int b =  (must + (u[idx] - l[idx]) * X + u[idx] - 1 )  / u[idx];
        amin( m , min(a,b));
        idx++;
      }
      ans += m; break;
    }
  }
  out(ans);
}

