  }

  sort(vec.begin(), vec.end(), greater<pair<ll,int> >());

  while(l < r){
    ll mid = (l+r)/2;

    if(check(mid)) {
      r = mid;
    } else {
      l = mid + 1;
    }
  }

  cout << l << endl;

  return 0;
}

