  ll lf=-1,rt=accumulate(b.begin(),b.end(),0);
  vector<int> m100(b.size());
  iota(m100.begin(),m100.end(),0);
  sort(m100.begin(),m100.end(),[&](int x,int y){
    return u[x]*(X-b[x])>u[y]*(X-b[y]);
  });
  while(lf+1<rt){
    ll mid=(lf+rt)/2;
    ll cmid=mid;
    vector<int> points(N);
    REP(cmid/X){
      points[m100[i]]=X;
