        exams[i] = Exam {b, l, u, x};
        b_sum += b;
    }

    long long lb = -1, ub = b_sum;
    sort(exams, exams + n);
    while (ub - lb > 1) {
        long long mid = (lb + ub) / 2;
        long long diff = 0;
        int q = (int) (mid / x);
        long long r = mid - x * q;
        for (int i = 1; i <= q; i++) {
            Exam e = exams[n - i];
            diff += e.u * (x - e.b);
        }
        Exam e = exams[n - q - 1];
        diff += ((r >= e.b) ? e.u : e.l) * (r - e.b);
        for (int i = 0; i < n - q - 1; i++) {
            Exam e = exams[i];
            diff -= e.l * e.b;
        }
