vector<int> ord, pos;
vector<ll> csum;

void init(){
	ord = vector<int>(n);
	iota(begin(ord), end(ord), 0);	

	auto cmp = [&](int i, int j) {
		const ll ci = 1LL * u[i] * (x - b[i]) + 1LL * l[i] * b[i];
		const ll cj = 1LL * u[j] * (x - b[j]) + 1LL * l[j] * b[j];
		return ci < cj;
	};	

	sort(rbegin(ord), rend(ord), cmp);

	pos = vector<int>(n);
	rep(i, n) pos[ord[i]] = i;

	csum = vector<ll>(n + 1, 0LL);
	rep(i, n){
		const int p = ord[i];
		csum[i + 1] += csum[i];
		csum[i + 1] += 1LL * u[p] * (x - b[p]) + 1LL * l[p] * b[p];
	}
}

bool check(ll k){
	rep(i, n){
		const ll p = k / x;
		const ll q = k % x;

		const ll xval = 1LL * u[i] * (x - b[i]) + 1LL * l[i] * b[i];
		const ll qval = 1LL * u[i] * max(q - b[i], 0LL) + 1LL * l[i] * min(q, b[i]);

		if(q == 0){
			if(init_val + csum[p] >= 0) return true;
		} else if(p < pos[i]){
			if(init_val + csum[p] + qval >= 0) return true;
		} else {
			if(init_val + csum[p + 1] - xval + qval >= 0) return true;
		}
	}

	return false;
}

