const int MAXN = 100010;
const int MAXK = 18;

int n, x;
int b[MAXN], l[MAXN], u[MAXN];
pll w[MAXN];
int used[MAXN];

bool check(ll m)
{
	for (int i = 1; i <= n; ++ i)
	{
		w[i] = pll((ll)(x-b[i])*u[i], i);
		used[i] = 0;
	}
	sort(w+1, w+n+1);
	reverse(w+1, w+n+1);
	ll c = m/x;
	ll val = 0;
	for (int i = 1; i <= c; ++ i)
	{
		val += w[i].X;
		used[w[i].Y] = 1;
	}

	ll best = -1000000000000000000LL;
	int choose = 0;

	for (int i = 1; i <= n; ++ i)
		if (!used[i])
		{
			ll cur;
			if (m%x-b[i] >= 0)
			{
				cur = (ll)(m%x)*u[i]-(ll)b[i]*(u[i]-l[i]);
			}
			else
			{
				cur = (ll)(m%x)*l[i];
			}
			if (cur > best)
			{
				best = cur;
				choose = i;
			}
		}

	if (m%x-b[choose] >= 0)
	{
		val += (ll)(m%x-b[choose])*u[choose];
		used[choose] = 1;
	}
	else
	{
		val += best;
	}


	for (int i = 1; i <= n; ++ i)
		if (!used[i]) val -= (ll)l[i]*b[i];

	return val >= 0;
}

int main()
{

	scanf("%d%d", &n, &x);
	for (int i = 1; i <= n; ++ i)
	{
		scanf("%d%d%d", &b[i], &l[i], &u[i]);
	}


	ll L = 0, R = (ll)x*n;
	ll ans = R;
	while (L <= R)
	{
		ll m = (L+R)/2;
		if (check(m))
		{
			ans = m;
			R = m-1;
		}
		else
			L = m+1;
	}
	cout << ans << endl;

	return 0;
}

