inline bool check(ll k) {
	ll t1 = k / X;
	ll t2 = k % X;
	ll tmp = 0;
	for(ll i = 1;i <= t1;i ++) {
		tmp = (ll)tmp + (X - a[i].b) * a[i].r;
	}
	for(ll i = t1 + 1;i <= n;i ++) {
		tmp = (ll)tmp - (ll)a[i].b * a[i].l;
	}
	if(t2 == 0) return tmp >= 0;
	ll mx = 0;
	for(int i = 1;i <= t1;i ++) {
		ll now = (X - a[t1 + 1].b) * a[t1 + 1].r - (X - a[i].b) * a[i].r + a[t1 + 1].b * a[t1 + 1].l;
		if(t2 > a[i].b) now += (t2 - a[i].b) * a[i].r;
		else now += (t2 - a[i].b) * a[i].l;
		mx = max(mx,now);
	}
	for(int i = t1 + 1;i <= n;i ++) {
		ll now = 0;
		if(t2 > a[i].b) now = (t2 - a[i].b) * a[i].r;
		else now = (t2 - a[i].b) * a[i].l;
		now += (ll)a[i].b * a[i].l;
		mx = max(mx,now);
	}
	tmp += mx;
	return tmp >= 0;
}

