int ok(ll v) {
	if(v<0) return 0;
	ll A=0,C=0;
	ll num=v/X;
	ll lef=v%X;
	int i,j;
	FOR(i,N) {
		j=P[i].second;
		if(i<num) {
			A+=X*R[j];
			C+=B[j]*R[j];
		}
		else {
			C+=B[j]*L[j];
		}
	}
	if(lef==0) return A>=C;

	FOR(i,N) {
		if(i<num) {
			int x=P[i].second;
			int y=P[num].second;
			ll A2=A-X*R[x]+X*R[y];
			ll C2=C-B[x]*(R[x]-L[x])+B[y]*(R[y]-L[y]);
			if(B[x]<=lef) {
				if(A2+lef*R[x]>=C2+B[x]*(R[x]-L[x])) return 1;
			}
			else {
				if(A2+lef*L[x]>=C2) return 1;
			}
		}
		else {
			j=P[i].second;
			if(B[j]<=lef) {
				if(A+lef*R[j]>=C+B[j]*(R[j]-L[j])) return 1;
			}
			else {
				if(A+lef*L[j]>=C) return 1;
			}
		}
	}
	return 0;
}

