  ll bottom = 0;
  for (int i = 0; i < N; i++) {
    B[i] = read();
    L[i] = read();
    U[i] = read();
    bottom -= L[i] * B[i];
  }
  vector<int> ord(N);
  for (int i = 0; i < N; i++) {
    ord[i] = i;
  }
  sort(ord.begin(), ord.end(), [&](int i, int j) {
    ll x = U[i] * (X - B[i]);
    ll y = U[j] * (X - B[j]);
    return x > y;
  });
  ll l = 0;
  ll r = X * N;
  while (r - l > 1) {
    ll m = (l + r) / 2;
    ll top = 0;
    ll top2 = 0;
    vector<bool> used(N);
    for (int ii = 0; ii < m / X; ii++) {
      int i = ord[ii];
      top += U[i] * (X - B[i]) + L[i] * B[i];
