	vector<ll> temp(1);
	for (int i = 0; i < n; ++i)
		temp.push_back(temp.back() + a[i].u * (x - a[i].b));

	vector<ll> temp2(1);
	for (int i = 0; i < n; ++i)
		temp2.push_back(temp2.back() + a[i].l * (-a[i].b));

	temp.erase(temp.begin());
	temp2.erase(temp2.begin());

