    for (int i = 0; i < n; ++i) {
        cin >> bs[i] >> ls[i] >> us[i];
    }

    li v = 0;
    li ans = 0;
    vector<pair<li, li>> ubis(n);
    vector<li> ubs(n);
    for (int i = 0; i < n; ++i) {
        v += bs[i] * ls[i];
        ans += bs[i];
        ubis[i] = make_pair(bs[i] * ls[i] + (x - bs[i]) * us[i], i);
        ubs[i] = ubis[i].first;
    }
    sort(ubis.rbegin(), ubis.rend());

    li acc = 0;
    set<li> used;
    li next;
    for (int i = 0; i < n; ++i) {
        li nacc = acc + ubis[i].first;
        if (nacc >= v) {
            next = ubis[i].second;
            break;
        }
        acc = nacc;
        used.insert(ubis[i].second);
    }

    for (int i = 0; i < n; ++i) {
        li target;
        li cost = x * used.size();
        if (used.find(i) != used.end()) {
            target = v - (acc - ubs[i] + ubs[next]);
