struct ts
{
	long long b, l, u, p;
	bool operator<(const ts &r) const {
		return p > r.p;
	}
};

ts a[100009];

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0); cout.tie(0);
	int n; long long x; cin >> n >> x;
	long long cs = 0;
	for (int i = 0; i < n; i++) {
		cin >> a[i].b >> a[i].l >> a[i].u; 
		a[i].p = a[i].b * a[i].l + (x - a[i].b) * a[i].u;
		cs += a[i].b * a[i].l;
	}
	sort(a, a + n);
	long long ans = 0;
	for (int i = 0; i < n; i++) { 
		if (cs - a[i].p <= 0) {
			long long mn = 1000000000000000000LL;
			int t = i;
			while (t > 0 && a[t - 1].p == a[t].p) t--;
			for (int j = t; j < n; j++) {
				if (a[j].p < cs) continue;
				if (a[j].b * a[j].l >= cs) mn = min(mn, (cs + a[j].l - 1) / a[j].l);
				else mn = min(mn, (cs - a[j].b * a[j].l + a[j].u - 1) / a[j].u + a[j].b);
			}
			ans += mn;
			break;
		}
		cs -= a[i].p; ans += x;
	}
	cout << ans << '\n';
	return 0;
}

