bool solve(int k) {
	//勝てる科目数
	int cnt = k / X;
	if (cnt >= N)return true;
	int rem = k - X * cnt;
	int res = 0;
	REP(i, cnt) {
		int j = v[i].second;
		//print(j);
		if (i < cnt) {
			res += (X - b[j])*u[j];
		}
		/*else {
		if (i == cnt) {
		if (rem >= b[j]) {
		res += (rem - b[j])*u[j];
		}
		else {
		res -= (b[j] - rem)*l[j];
		}
		}
		else {
		res -= b[j] * l[j];
		}
		}*/
	}
	int idx = cnt;
	int mx = -INF;
	FOR(i, cnt, N) {
		int j = v[i].second;
		int tmp;
		if (rem >= b[j]) {
			tmp = b[j] * l[j] + (rem - b[j])*u[j];
		}
		else {
			tmp = rem * l[j];
		}
		if (tmp > mx) {
			mx = tmp;
			idx = i;
		}
	}
	FOR(i, cnt, N) {
		int j = v[i].second;
		if (i == idx) {
			if (rem >= b[j]) {
				res += (rem - b[j])*u[j];
			}
			else {
				res -= (b[j] - rem)*l[j];
			}
		}
		else {
			res -= b[j] * l[j];
		}
	}
	//print(res);
	if (res >= 0) {
		return true;
	}
	else {
		return false;
	}
}
