int N, X;
int b[100010];
int l[100010];
int u[100010];

long int ma[100010];
pii minus[100010];

long int target;

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  cin >> N >> X;
  rep(i,N) {
    cin >> b[i] >> l[i] >> u[i];
    ma[i] = l[i] * b[i] + u[i] * (X-b[i]);
    target += l[i] * b[i];
  }

  vi ind(N);
  rep(i, N) ind[i] = i;
  sort(&ind[0], &ind[N], [](int i1, int i2) {return ma[i1] > ma[i2];});

  int lasti;
  long int score = 0;
  rep(i,N) {
    if (score + ma[ind[i]] < target) {
      score += ma[ind[i]];
    } else {
      lasti = i;
      break;
    }
  }
  long int remain = target - score;
  int tmin = X;
  for (int i=lasti; i<N; ++i) {
    int t_remain = 0;
    if (ma[ind[i]] < remain) break;
    else if (l[ind[i]] * b[ind[i]] >= remain) t_remain = (remain-1) / l[ind[i]] + 1;
    else t_remain = b[ind[i]] + (remain - l[ind[i]]*b[ind[i]] - 1) / u[ind[i]] + 1;
    tmin = min(tmin, t_remain);
  }
  long int ans1 = lasti * X + tmin;

  long int over = score + ma[ind[lasti]] - target;
  int tmax = 0;
  for (int i=0; i<=lasti; ++i) {
    int t_over = 0;
    if (u[ind[i]] * (X-b[ind[i]]) < over) t_over = over / u[ind[i]];
    else t_over = (X-b[ind[i]]) + (over - u[ind[i]]*(X-b[ind[i]])) / l[ind[i]];
  }
  long int ans2 = (lasti + 1) * X - tmax;

  long int ans = min(ans1, ans2);

  cout << ans << "\n";

  return 0;
}

