long long N, X;
vector<vector<long long>> A;

bool check(long long m)
{
    long long score_a = 0;
    long long score_b = 0;

    long long cnt = m / X;
    if(cnt >= N)
        return true;

    for(auto i = 0; i < cnt; ++i)
    {
        score_a += X * A[i][2];
        score_b += A[i][0] * A[i][2];   
    }

    long long max_val = -1;
    int max_idx = -1;
    for(auto i = cnt; i < N; ++i)
    {
        long long candi = (m % X) * A[i][1];
        if(m % X > A[i][0])
            candi = (m % X) * A[i][2] - A[i][0] * (A[i][2] - A[i][1]);

        if(candi > max_val) {
            max_val = candi;
            max_idx = i;
        }
    }

    for(auto i = cnt; i < N; ++i)
    {
        if(i == max_idx) {
            if(m % X > A[i][0]) {
                score_a += (m % X) * A[i][2];
                score_b += A[i][0] * A[i][2];
            }
            else {
                score_a += (m % X) * A[i][1];
                score_b += A[i][0] * A[i][1];
            }
        }
        else {
            score_b += A[i][0] * A[i][1];
        }
    }

    return score_a >= score_b;
}

void solve()
{
    cin >> N >> X;

    A = vector<vector<long long>>(N, vector<long long>(3));

    for(auto i = 0; i < N; ++i)
    {
        cin >> A[i][0] >> A[i][1] >> A[i][2];
    }

    sort(A.begin(), A.end(), [](const vector<long long>& lhs, const vector<long long>& rhs) {
        return -(X - lhs[0]) * lhs[2] + lhs[0] * lhs[1] < -(X - rhs[0]) * rhs[2] + rhs[0] * rhs[1];
    });

    long long l = -1;
    long long r = N * X;

    while(l+1 < r) {
        long long m = (l+r) / 2;
        if(check(m))
            r = m;
        else
            l = m;
    }

    cout << r << endl;
}

