	for (int i = 0; i < n; i++) {
		t& dd = d[max[i].second];
		long long w = 0;
		if (dd.b*dd.l >= min) {
			if (min%dd.l == 0) {
				w = min / dd.l;
			}
			else {
				w = min / dd.l + 1;
			}
		}
		else {
			if ((min + (dd.u - dd.l)*dd.b) % dd.l == 0) {
				w = (min + (dd.u - dd.l)*dd.b) / dd.l;
			}
			else {
				w = (min + (dd.u - dd.l)*dd.b) / dd.l + 1;
			}
		}
		if (b > w)b = w;
	}
	r += b;
	printf("%lld", r);
}

