struct Test {
    i64 i;
    i64 b;
    i64 l;
    i64 u;
    Test(i64 ii, i64 bb, i64 ll, i64 uu) : i(ii), b(bb), l(ll), u(uu) {}
};

template<>
struct Formatter<Test> {
    static ostream& write_str(ostream& out, const Test& t) {
        return WRITE_STR(out, TUPLE(t.i,t.b,t.l,t.u));
    }
    static ostream& write_repr(ostream& out, const Test& t) {
        return WRITE_REPR(out, TUPLE(t.i,t.b,t.l,t.u));
    }
};

void solve() {
    i64 N = RD();
    i64 X = RD();

    vector<Test> ts;
    ts.reserve(N);
    REP(i, N) {
        i64 b = RD();
        i64 l = RD();
        i64 u = RD();
        ts.emplace_back(i, b, l, u);
    }
    DBG(ts);

    i64 bsum = 0;
    for(const auto& t : ts) {
        bsum += t.l * t.b;
    }
    DBG(bsum);

    auto comp1 = LT_ON([X](const Test& t) {
        return (X-t.b) * t.u;
    });
    auto comp2 = LT_ON([](const Test t) {
        return t.l;
    });

    priority_queue<Test,vector<Test>,decltype(comp1)> que1(begin(ts), end(ts), comp1);
    priority_queue<Test,vector<Test>,decltype(comp2)> que2(begin(ts), end(ts), comp2);
    BoolArray used(N, false);

    i64 ans = 0;
    i64 asum = 0;
    for(;;) {
        DBG(asum, bsum);

        while(used[que2.top().i]) que2.pop();
        const auto t2 = que2.top();
        i64 cand2 = div_ceil(bsum-asum,t2.l);
        if(cand2 > X) cand2 = INF;
        DBG(t2, cand2);

        const auto t1 = que1.top();
        i64 cand1 = MIN(X, div_ceil(bsum-asum+(t1.u-t1.l)*t1.b,t1.u));
        DBG(t1, cand1);

        if(cand2 < cand1) {
            ans += cand2;
            break;
        }
        else {
            ans += cand1;
            asum += t1.u * cand1;
            bsum += (t1.u-t1.l) * t1.b;
            if(asum >= bsum) break;
            used[t1.i] = true;
            que1.pop();
        }
    }

    PRINTLN(ans);

    // * 小さいケースで試した?
    // * 不可能なケースはチェックした?
    // * MOD はとった?
    // * メモ化忘れてない?
    // * 入出力の 0-based/1-based 確認した?
    // * 時間/メモリ制限は確認した?
    // * 違うやつ提出してない?
    // * 違うやつテストしてない?
}

signed main() {


    solve();

    EXIT();
}

