#define all(x) x.begin(),x.end()
typedef tuple<int, int, int> t3;

int N, X;
t3 T[100010];

int main() {
	scanf("%d%d", &N, &X);
	ll del = 0;
	for(int i=1;i<=N;i++) {
		int b, l, r;
		scanf("%d%d%d", &b, &l, &r);
		del += (ll)l*b;
		T[i] = t3(b, l, r);
	}
	if(del == 0) {
		puts("0");
		return 0;
	}
	sort(T+1, T+1+N, [&](t3 x, t3 y) {
		int bi, li, ri; tie(bi, li, ri) = x;
		int bj, lj, rj; tie(bj, lj, rj) = y;
		return (ll)ri * (X - bi) + (ll)li * bi > (ll)rj * (X - bj) + (ll)lj * bj;
	});
	ll sum = 0, ans = 0, rr = 1e18;
	for(int i=1;i<=N;i++) {
		int b, l, r;
		tie(b, l, r) = T[i];
		del += (r - l) * (ll)b;
		ll add = (ll) r * X;
		if(sum + add >= del) {
			ll mx_l = 0, v1 = 0;
			for(int j=i;j<=N;j++) {
				mx_l = max(mx_l, (ll)get<1>(T[j]));
			}
			ll del2 = del - (ll)(r - l) * b;
			v1 = (del2 - sum + mx_l - 1) / mx_l;
			rr = ans + v1;

			ll mn_r = 1e18;
			for(int j=i;j;j--) mn_r = min(mn_r, (ll)get<2>(T[j]));
			ll dd = (sum + add - del);
			ll v2 = dd / mn_r;
			rr = min(rr, ans + X - v2);
			break;
		}
		else {
			sum += add;
			ans += X;
		}
	}
	printf("%lld\n", rr);
	return 0;
}

