using namespace std;

#define int int_fast64_t

struct exam {
  int l, u, b;
  int cost(int score) const {
    int c = score >= b ? u : l;
    return c*(score - b);
  }
};

signed main() {
  ios_base::sync_with_stdio(false), cin.tie(nullptr);

  int n, x; cin >> n >> x;
  vector<exam> exams;
  for (int i = 0; i < n; ++i) {
    exam e;
    cin >> e.b >> e.l >> e.u;
    exams.push_back(e);
  }
  int score=0;
  for (auto& e : exams) score += e.cost(0);

  auto key = [&](exam const& e) { return e.cost(x) - e.cost(0); };
  sort(exams.begin(), exams.end(), [&](exam const& a, exam const& b) { return key(a) > key(b); });
  int ans=0;
  for (auto& e : exams) {
    if (score == 0) break;
    assert(score < 0);
    const int cost0 = e.cost(0);
    auto gain = [&](int x) { return e.cost(x) - cost0; };

    if (score + gain(x) <= 0) {
      score += gain(x);
      ans += x;
      continue;
    }
    assert(score < 0);
    // invariant: score+gain(l)<0, score+gain(r)>=0
    int l=0, r=x;
    while (r-l > 1) {
      int m = (l+r)/2;
      if (score + gain(m) < 0)
        l = m;
      else
        r = m;
    }
    assert(score + gain(r) >= 0);
    assert(score + gain(l) < 0);
    score += gain(r);
    ans += r;
    break;
  }
  cout << ans << '\n';
}

