//!    88   88   88  .d8888b.  dP  88d888b.    !//
//!    88   88   88  88'  '88  88  88'  '88    !//
//!    88   88   88  88.  .88  88  88    88    !//
//!    dP   dP   dP  '88888P8  dP  dP    dP    !//
//!============================================!//
int main()
{
    const int N = read<int>();
    const ll X = read<ll>();
    std::vector<ll> b(N), l(N), u(N);
    ll ans = 0;
    for (int i = 0; i < N; i++) { std::cin >> b[i] >> l[i] >> u[i], ans += b[i]; }
    std::vector<int> ind(N);
    std::iota(ind.begin(), ind.end(), 0);
    std::sort(ind.begin(), ind.end(), [&](const int i, const int j) { return l[i] * b[i] + u[i] * (X - b[i]) > l[j] * b[j] + u[j] * (X - b[j]); });
    auto ok = [&](const ll U) -> bool {
        std::vector<ll> a(N, 0LL);
        ll R = U;
        int p = -1;
        for (int i = 0; i < N; i++) {
            a[ind[i]] = std::min(X, R), R -= a[ind[i]];
            if (R == 0) { p = i; }
        }
        ll score = 0;
        for (int i = 0; i < N; i++) { score += (a[ind[i]] < b[ind[i]] ? l[ind[i]] : u[ind[i]]) * (a[ind[i]] - b[ind[i]]); }
        for (int i = 0; i < N; i++) {
            ll S = score;
            S -= (a[ind[p]] < b[ind[p]] ? l[ind[p]] : u[ind[p]]) * (a[ind[p]] - b[ind[p]]);
            S -= (a[ind[i]] < b[ind[i]] ? l[ind[i]] : u[ind[i]]) * (a[ind[i]] - b[ind[i]]);
            S += (a[ind[i]] < b[ind[p]] ? l[ind[p]] : u[ind[p]]) * (a[ind[i]] - b[ind[p]]);
            S += (a[ind[p]] < b[ind[i]] ? l[ind[i]] : u[ind[i]]) * (a[ind[p]] - b[ind[i]]);
            if (S >= 0) { return true; }
        }
        return false;
    };
    ll inf = -1, sup = X * (ll)N + 1LL;
    while (sup - inf > 1) {
        const ll mid = (inf + sup) / 2LL;
        (ok(mid) ? sup : inf) = mid;
    }
    std::cout << sup << std::endl;
    return 0;
}

