int lu[100000];

void solve(){
    int i,j;
    string str;
    cin >> n >> x;
    vector<long long> b(n),l(n),u(n);
    for(i = 0;i < n;i++){
        cin >> b[i] >> l[i] >> u[i];
        ls.push_back(make_pair(l[i],i));
        us.push_back(make_pair(u[i],i));
        ps.push_back(make_pair(x*u[i]-b[i]*(u[i]-l[i]),i));
    }
    sort(ls.begin(),ls.end());
    sort(us.begin(),us.end());
    sort(ps.begin(),ps.end());
    long long mi = -1,ma = x*n;
    while(ma-mi > 1){
        long long m = (ma+mi)/2;
        memset(lu,0,sizeof(lu));
        long long lm = m;
        long long gp = 0,ep = 0;
        int g;
        for(i = n-1;i >= 0;i--){
            if(lm >= x){
                lm -= x;
                j = ps[i].second;
                gp += u[j]*x;
                lu[j] = 1;
            }
            if(lm > 0 && lm < x){
                g = ps[i-1].second;
                break;
            }
        }
        for(i = 0;i < n;i++){
            if(lu[i]) ep += b[i]*u[i];
            else ep += b[i]*l[i];
        }
        int f = 0;
        for(i = 0;i < n;i++){
            if(lm == 0){
                if(ep <= gp) f = 1;
                break;
            }
            if(lu[i]){
                if(lm > b[i]){
                    if(ep+b[g]*(u[g]-l[g]) <= gp-(x-lm)*u[i]+x*u[g]){
                        f = 2;
                        break;
                    }
                }
                else{
                    if(ep+b[g]*(u[g]-l[g])-b[i]*(u[i]-l[i]) <= gp-x*u[i]+lm*l[i]+x*u[g]){
                        f = 3;
                        break;
                    }
                }
            }
            else{
                if(lm > b[i]){
                    if(ep+b[i]*(u[i]-l[i]) <= gp+lm*u[i]){
                        f = 4;
                        break;
                    }
                }
                else{
                    if(ep <= gp+lm*l[i]){
                        f = 5;
                        break;
                    }
                }
            }
        }
        if(f) ma = m;
        else mi = m;
    }
    cout << ma << endl;
}

