    vector<ll> s(n), rank(n);
    REP(i, n) vp[i] = {b[i]*l[i] + (x-b[i])*u[i], i};
    sort(ALL(vp), greater<>());
    REP(i, n) s[i] = vp[i].first, rank[vp[i].second] = i;
    ll sumb = 0;
    REP(i, n) sumb += b[i]*l[i];

    auto check = [&](ll k) {
        ll q = k/x, r = k%x;
        if(q == n) return true;
        ll sum1 = 0;
        REP(i, q) sum1 += s[i];
        ll ma = 0;
        REP(i, n) {
            ll score = 0;
            // i番目のテストはr時間
            if(r > b[i]) score += b[i]*l[i] + (r-b[i])*u[i];
            else score += r*l[i];
            // i番目のテストを除いてs[j]が大きい方からq個
            if(rank[i] < q) score += sum1 - (b[i]*l[i] + (x-b[i])*u[i]) + s[q];
            else score += sum1;
            chmax(ma, score);
        }
        return ma >= sumb;
    };

