const ll N = (int)1e5 + 9;
ll n;
ll X;

ll b[N], l[N], r[N];
bool ok[N];

bool is(ll T){
    ll k = T/(ll)X;
    ll sum = 0;
    for(ll i = 0 ; i < n ; i ++ )
        ok[i] = false;
    vector<pii> vls;
    for(ll i = 0 ; i < n; i ++ ){
        vls.push_back(mp((X-b[i]) * r[i] + l[i] * b[i], i));
    }
    sort(vls.begin(), vls.end());
    ll rem = T % (ll)X;
    reverse(vls.begin(), vls.end());
    int id;
    for(ll i = 0 ; i < k ; i ++ ){
        id = vls[i].se;
        sum += (X - b[id]) * r[id];
        ok[id] = true;
    }
    ll ddd = 0;
    for(ll i = 0 ; i < n ; i ++ ){
        if(ok[i])
            continue;
        ddd += -b[i] * l[i];
    }
    ll mx = 0;
    ll cur;
    for(ll i = 0 ; i < n ; i ++ ){
        if(ok[i])
            continue;
        cur = b[i] * l[i];
        if(rem != b[i]){
            if(rem < b[i]){
                cur += (rem - b[i]) * l[i];
            }
            else{
                cur += (rem - b[i]) * r[i];
            }
        }
        mx = max(mx, cur);
    }
    ddd += mx;
    sum += ddd;
    return sum >= 0;
}

