ll comp(int i, int j){
	ll p,q;
	p = (x-b[i])*u[i];
	q = (x-b[j])*u[j];
	if(p==q){
		q = max((r-b[i])*u[i],(r-b[i])*l[i]);
		p = max((r-b[j])*u[j],(r-b[j])*l[j]);
	}
	return p>q;
}

bool judge(ll p){
	int i;
	ll tmp=0ll,mx=0ll;
	r = p%x;
