#define ll long long 
int n, x;

struct e{
	ll b, l, r;
	e(){}
	e(ll _b, ll _l, ll _r){
		b = _b; l = _l; r = _r;
	}
};

const int MAXN = 1e5 + 5;

bool cmp(e a, e b){
	// Sort by sulprus potential
	ll pA = (x-a.b), pB = (x-b.b);
	pA *= a.r; pB *= b.r;
	return pA > pB;
}

e a[MAXN];
ll lastBit[MAXN];

bool isPossible(ll tmpAns){
	// Put X on highest potential first
	ll selisih = 0, rem = tmpAns, bestWorth = -1e11, w;
	for(int i = 0; i < n; ++i){
		if(rem >= x){
			selisih += (x-a[i].b)*a[i].r;
			rem -= x;
		}else{
			selisih -= a[i].l*a[i].b;
			// Check the worthiness
			ll tmpWorth = a[i].l*rem;
			if(bestWorth < tmpWorth){
				bestWorth = tmpWorth;
				w = tmpWorth;
			}
			tmpWorth = a[i].r*(rem-a[i].b) + a[i].l*a[i].b;
			if(bestWorth < tmpWorth){
				bestWorth = tmpWorth;
				w = tmpWorth;
			}
		}
	}
	selisih += w;
	return (selisih >= 0);
}

int main(){
	scanf("%d %d", &n, &x);
	for(int i = 0; i < n; ++i){
		ll b, l, r;
		scanf("%lld %lld %lld", &b, &l, &r);
		a[i] = e(b, l, r);
	}
	// Sort
	sort(a, a+n, cmp);
	//for(int i = 0; i < n; ++i) printf("[%lld, %lld, %lld]\n", a[i].b, a[i].l, a[i].r);
	// Determine highest importance
	for(int i = n-1; i >= 0; --i){
		lastBit[i] = max(lastBit[i+1], a[i].l);
	}
	ll l = 0, r = 1e10;
	while(l < r){
		ll mid = (l+r)/2;
		if(isPossible(mid))
			r = mid;
		else
			l = mid+1;
	}
	//isPossible(2540);
	printf("%lld\n", l);
}

