struct item {
  int b, l, u;
  ll score;
};

int main() {
#ifdef LOCAL
  freopen("c.in", "r", stdin);
  freopen("c.out", "w", stdout);
#endif

  int n, x;
  while (scanf("%d%d", &n, &x) == 2) {
    ll target = 0;
    vector<item> v(n);
    for (int i = 0; i < n; i++) {
      scanf("%d%d%d", &v[i].b, &v[i].l, &v[i].u);
      target += v[i].b * 1LL * v[i].l;
      v[i].score = v[i].b * 1LL * v[i].l + (x - v[i].b) * 1LL * v[i].u;
    }

    sort(v.begin(), v.end(), [](const item& a, const item& b) { return a.score > b.score;});

    auto best = [&](ll hours) {
      int full = hours / x;
      int extra = hours % x;
      ll sum = 0;
      for (int i = 0; i < full; i++) {
        sum += v[i].score;
      }
      if (extra == 0) return sum;
      sum += v[full].score;
      ll ans = 0;
      for (int i = 0; i < n; i++) {
        ll cur = sum - v[min(i, full)].score;
        int small = min(extra, v[i].b);
        int big = extra - small;
        cur += small * 1LL * v[i].l + big * 1LL * v[i].u;
        ans = max(ans, cur);
      }
      return ans;
    };

    ll lf = -1;
    ll rg = n * 1LL * x;

    while (rg - lf > 1) {
      ll mid = (lf + rg) / 2;
      if (best(mid) >= target) {
        rg = mid;
      } else {
        lf = mid;
      }
    }

    printf("%lld\n", rg);
  }

  return 0;
}

