int main() {
    ll inf = 99999999;
    ll n,x;
    cin >> n >> x;

    ll b[n],l[n],u[n];
    ll count = 0;
    priority_queue<pair<ll,ll>> que;
    rep(i,n){
        cin >> b[i] >> l[i] >> u[i];
        count += b[i]*l[i];
        pair<ll,ll> p;
        p.first = b[i]*l[i] + (x-b[i])*u[i];
        p.second = i;
        que.push(p);
    }

    ll flag[n] = {};
    ll ans = 0;
    while(que.size()>0&&count>=que.top().first){
        count -= que.top().first;
        flag[que.top().second] = 1;
        ans += x;
        que.pop();
    }

    ll mi = inf;

    rep(i,n){
        if(flag[i]==0){
            ll tmp = 0;
            ll c = count;
            if(b[i]*l[i]+(x-b[i])*u[i]<c){
                tmp = inf;
            }else if(c<=b[i]*l[i]){
                tmp += c/l[i];
                c -= (c/l[i])*l[i];
                if(c>0){
                    tmp++;
                }
            }else{
                tmp += b[i];
                c -= b[i]*l[i];
                tmp += c/u[i];
                c -= (c/u[i])*u[i];
                if(c>0){
                    tmp++;
                }
            }
            mi = min(mi,tmp);
        }
    }

    ans += mi;

    cout << ans << endl;
    return 0;
}

