#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define N 300010
ll n,x;
struct ver{
	ll b,l,r;
	ll allsum(){
		return b*l+(x-b)*r;
	}
	ll opp(){
		return b*l;
	}

	ver(ll b,ll l,ll r){
		this->b=b,this->l=l,this->r=r;
	}
};
bool operator<(const ver&a,const ver&b){
	ll vl=a.b*a.l+(x-a.b)*a.r;
	ll vr=b.b*b.l+(x-b.b)*b.r;
	return vl>vr;
};
vector<ver> v;
ll cs[N],oppsum;
bool judge(ll k,ll t){
	ll cost=k/x; if(cost>=n)return 1;
	ll res=min(k%x,v[t].b)*v[t].l+max(0LL,k%x-v[t].b)*v[t].r;
	res+=cs[min(t,cost)]-cs[0];
	res+=max(0LL,cs[cost+1]-cs[t+1]);
	return oppsum<=res;
}
bool solve(ll k){
	for(int i=0;i<n;i++){
		if(judge(k,i))return 1;
	}
	return 0;
}
int main(){
	cin>>n>>x;
	for(int i=0;i<n;i++){
		ll b,l,r; cin>>b>>l>>r;
		v.push_back(ver(b,l,r));
	}
	sort(v.begin(),v.end());
	oppsum=0;
	for(auto t:v)oppsum+=t.opp();
	cs[0]=0;
	for(int i=0;i<v.size();i++){
		cs[i+1]=cs[i]+v[i].allsum();
	}
	ll l=-1,r=1e17,m;
	while(l<r-1){
		m=(l+r)>>1;
		if(solve(m))r=m;
		else l=m;
	}
	cout<<r<<endl;
	return 0;	
}

