ll f(ll m, int id, int sp) {
  ll ret = 0;
  for (int i = id; i < n; i++) {
    if (m >= ns[i].b) {
      ret = max(ret, ns[i].u * m - (ns[i].u - ns[i].l) * ns[i].b);
    } else {
      ret = max(ret, ns[i].l * m);
    }
  }
  ret = max(ret, ns[sp].u * m - (ns[sp].u - ns[sp].l) * ns[sp].b);
  return ret;
}

