    cin >> N >> X;

    ll cur = 0;
    vector<array<ll, 4>> exams(N);

    for (int i = 0, b, l, r; i < N; i++) {
        cin >> b >> l >> r;
        cur += ll(b) * ll(l);
        exams[i] = { ll(l) * b + ll(r) * (X - b), b, l, r };
    }

    sort(all(exams), [](auto e1, auto e2) {
        if (e1[0] != e2[0]) return e1[0] > e2[0];
        return e1[2] < e2[2];
    });

    int used = 0;
    ll partial = 0;
    while (cur > 0) {
        if (exams[used][0] <= cur) {
            partial += X;
            cur -= exams[used][0];
            used++;
        } else break;
    }

    if (cur == 0) {
        cout << partial << endl;
        return 0;
    }

    ll best = LLONG_MAX;
    for (int last = used; last < N; last++) {
        auto ex = exams[last];
        ll mv = ex[0], b = ex[1], l = ex[2], r = ex[3];
        if (mv <= cur) break;

        ll take = min((cur + l - 1) / l, b);
        if (take * l < cur) {
            ll more = (cur - take * l + r - 1) / r;
            assert(more <= X - b);
            assert(cur - take * l - more * r <= 0);
            take += more;
        }
        best = min(best, partial + take);
    }

    cout << best << endl;

    return 0;
}

