struct TopKSum {
    vector<ll> v;
    int k;
    ll sum;

    TopKSum(vector<ll> &_v, int _k) : v(_v), k(_k) {
        sum = accumulate(v.begin(), v.end(), 0LL);
    }

    ll eval(ll x) const {
        if ((int) v.size() == k) {
            assert(!v.empty());
            return sum - x;
        }
        if (x <= v[k])
            return sum - v[k];
        return sum - x;
    }
};

struct TopKSumBuilder {
    vector<ll> v;
    int k;

    explicit TopKSumBuilder(int _k) : k(_k) {
        assert(k >= 0);
    }

    void insert(ll x) {
        v.push_back(x);
    }

    TopKSum build() {
        assert((int) v.size() >= k);
        sort(v.rbegin(), v.rend());
        if ((int) v.size() != k)
            v.resize(k + 1);
        return TopKSum(v, k);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr), cout.tie(nullptr);

    int n;
    ll X;
    cin >> n >> X;
    vector<ll> b(n), l(n), u(n);

    const function<ll(int, ll)> eval = [&](const int i, const ll c) {
        assert(0 <= i && i < n);
        assert(0 <= c && c <= X);
        if (c <= b[i])
            return c * l[i];
        return b[i] * l[i] + (c - b[i]) * u[i];
    };

    ll hisScore = 0;
    for (int i = 0; i < n; ++i) {
        cin >> b[i] >> l[i] >> u[i];
        hisScore += eval(i, b[i]);
    }

    ll k = 0;

    {
        vector<ll> v(n);
        for (int i = 0; i < n; ++i)
            v[i] = eval(i, X);
        sort(v.rbegin(), v.rend());
        partial_sum(v.begin(), v.end(), v.begin());
        auto it = lower_bound(v.begin(), v.end(), hisScore);
        assert(it != v.end());
        k = it - v.begin();
    }

    const TopKSum topKSum = [&]() {
        TopKSumBuilder builder(k);
        for (int i = 0; i < n; ++i)
            builder.insert(eval(i, X));
        return builder.build();
    }();

    ll lo = 0;
    ll hi = X;
    while (lo < hi) {
        const ll mid = (lo + hi) / 2;

        ll mx = 0;
        for (int i = 0; i < n; ++i)
            mx = max(mx, topKSum.eval(eval(i, X)) + eval(i, mid));

        if (mx >= hisScore)
            hi = mid;
        else
            lo = mid + 1;
    }

    const ll mid = (lo + hi) / 2;

    ll mx = 0;
    for (int i = 0; i < n; ++i)
        mx = max(mx, topKSum.eval(eval(i, X)) + eval(i, mid));
    assert(mx >= hisScore);

    cout << k * X + lo;
    return 0;
}

