		int b, l, r;
		tie(b, l, r) = T[i];
		del += (r - l) * (ll)b;
		ll add = (ll) r * X;
		if(sum + add >= del) {
			ll v1 = (del - sum + r - 1) / r;
			ll del2 = del - (r - l) * (ll)b;
			ll v2 = (del2 - sum + l - 1) / l;
			printf("%lld\n", ans + min(v1, v2));
			return 0;
		}
		else {
			sum += add;
			ans += X;
		}
	}
	return 0;
}

