		l = _l;
		u = _u;
	}
};

int n, x;
test t[N];

bool cmp(test fir, test sec) {
	int value1 = fir.u * (x - fir.b) + fir.l * fir.b;
	int value2 = sec.u * (x - sec.b) + sec.l * sec.b;
	return value1 > value2;
}

int pref1[N], pref2[N];

bool check(int h) {
	int r = h % x;
	int bal = 0;
	if (r) {
		for (int i = 1; i <= n; ++i) {
			bal = 0;
			int R = h / x;
			if (i <= h / x) ++R;
			bal += pref1[R];
			if (i <= R) bal -= (pref1[i] - pref1[i - 1]);
			if (r - t[i].b >= 0) bal += t[i].u * (r - t[i].b);
			else bal += t[i].l * (r - t[i].b);
			bal += pref2[n] - pref2[R];
			if (i > R) bal -= (pref2[i] - pref2[i - 1]);
			if (bal >= 0) return 1;
		}
		return 0;
	} else {
		bal = pref1[h / x] + pref2[n] - pref2[h / x];
	}
	return bal >= 0;
}

