ll maxi = 0;
ll now = 0;
ll ans = 0;

typedef tuple<ll, ll, ll, ll> card; // maxi, b, l, u;

vector<card> V;

int main()
{
  cin >> N >> X;
  for (auto i = 0; i < N; i++)
  {
    cin >> b[i] >> l[i] >> u[i];
  }
  for (auto i = 0; i < N; i++)
  {
    maxi += b[i] * l[i];
  }
  for (auto i = 0; i < N; i++)
  {
    ll t = (l[i] * b[i] + u[i] * (X - b[i]));
    V.emplace_back(t, b[i], l[i], u[i]);
  }
  sort(V.begin(), V.end());
  reverse(V.begin(), V.end());
  int ind = 0;
  while (true)
  {
    ll t, b, l, u;
    tie(t, b, l, u) = V[ind];
    if (now + t >= maxi)
    {
      break;
    }
    now += t;
    ind++;
  }
  ans = X;
  ll dx = maxi - now;
#if DEBUG == 1
  cerr << "dx = " << maxi << " - " << now << " = " << dx << endl;
#endif
  for (auto i = ind; i < N; i++)
  {
    ll t, b, l, u;
    tie(t, b, l, u) = V[i];
    ll tmp = 0;
    if (dx >= l * b)
    {
      tmp = b + (dx - l * b + u - 1) / u;
    }
    else
    {
      tmp = (dx + l - 1) / l;
    }
    ans = min(tmp, ans);
  }
  cout << ans + X * ind << endl;
}

