#define ALL(x) x.begin(), x.end()
#define SZ(x) (ll)x.size()
#define f first
#define s second
#define MAXN 100100

typedef pair<ll,pi> pip;

ll N,K;
ll b,l,u;
vector<pip> V;

bool cmp(pip a, pip b){
	// Choose the overall biggest
	return (K-a.f)*a.s.s > (K-b.f)*b.s.s;
}

bool mem[MAXN];
ll val[MAXN];
ll offset;

ll ask(ll X){
	ll num_complete = X/K;
	ll leftover = X%K;
	// cout<<num_complete<<'\n';

	if (num_complete >= N)return 1;

	memset(mem,0,sizeof(mem));
	ll cur = 0;

	for (int i=0;i<num_complete;++i){
		auto x = V[i];
		cur += val[i];
		mem[i] = 1;
	}
	ll extra = val[num_complete];
	// cout<<cur<<' '<<extra<<'\n';
	ll res = -1e15;

	for (int i=0;i<N;++i){
		auto x = V[i];
		ll of = x.f*x.s.f;
		ll tmp = 0;
		if (mem[i] == 1){
			tmp -= val[i];
			tmp += extra;
		}
		if (leftover > V[i].f){
			tmp += (leftover - x.f) * x.s.s + of;
		}else{
			tmp += leftover * x.s.s;
		}
		res = max(res, tmp);
	}

	cur -= offset;
	return cur+res;
}

int main(){
	cin>>N>>K;
	for (int i=1;i<=N;++i){
		cin>>b>>l>>u;
		V.pb(b,mp(l,u));
	}
	sort(ALL(V), cmp);

	for (int i=0;i<N;++i){
		auto x= V[i];
		val[i] = x.f*x.s.f + (K-x.f)*x.s.s;
		offset += x.f*x.s.f;
		// cout<<val[i]<<' '<<x.f*x.s.f<<'\n';
	}
	// cout<<'\n';cout<<'\n';

	ll lb = 0;
	ll ub = K*N;
	while (ub > lb){
		ll mid = (lb+ub)/2;
		ll t = ask(mid);
		// cout<<"query "<<mid<<' '<<t<<'\n';
		if (t >= 0)ub = mid;
		else lb = mid+1;
	}
	cout<<lb;
}

