typedef pair <ll, int> P;

int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ll n, x;
    cin >> n >> x;

    ll b[n], l[n], u[n];
    ll sm = 0;
    for (int i = 0; i < n; i++) {
        cin >> b[i] >> l[i] >> u[i];
        sm += b[i] * l[i];
    }

    vector <P> benefit(n);
    for (int i = 0; i < n; i++) {
        benefit[i] = P((x - b[i]) * u[i], i);
    }

    sort(benefit.begin(), benefit.end(), greater<P>());

    ll ret = 1LL << 60;
    for (int i = 0; i < n; i++) {
        // 一番最後に除く奴を全探索

        ll ans = 0;
        ll tmp = sm;
        ll mx = b[i] * l[i] + (x - b[i]) * u[i];

        int idx = 0;
        while (tmp > mx) {
            int index = benefit[idx].second;
            if (i == index) {
                idx++;
                continue;
            }

            tmp -= b[index] * l[index];
            tmp -= benefit[idx].first;
            idx++;
            ans += x;
            if (ans >= ret) break;
        }

        if (tmp < 0) continue;

        if (tmp <= b[i] * l[i]) {
            ans += tmp / l[i];
            if (tmp % l[i] > 0) ans++;
        } else {
            tmp -= b[i] * l[i];
            ans += b[i];

            ans += tmp / u[i];
            if (tmp % u[i] > 0) ans++;
        }

        ret = min(ret, ans);
    }

    cout << ret << "\n";
    return 0;
}

