int main() {
	int n = nxt(), x = nxt();
	vector<int> b(n), l(n), r(n);
	for (int i = 0; i < n; ++i) {
		b[i] = nxt(), l[i] = nxt(), r[i] = nxt();
	}

	long long cur = 0;
	for (int i = 0; i < n; ++i) {
		cur -= 1ll * l[i] * b[i];
	}

	vector<pair<long long, int>> can(n);
	for (int i = 0; i < n; ++i) {
		can[i] = {1ll * r[i] * (x - b[i]) + 1ll * l[i] * b[i], i};
	}
	sort(all(can));
	vector<int> c(n);
	long long ans = 0;
	while (!can.empty() && cur + can.back().first <= 0) {
		cur += can.back().first;
		c[can.back().second] = x;
		ans += x;
		can.pop_back();
	}

	long long tmp = x;
	for (int i = 0; i < n; ++i) {
		if (c[i]) {
			continue;
		}
		if (1ll * r[i] * (x - b[i]) + 1ll * l[i] * b[i] + cur < 0) {
			continue;
		}
		if (cur + b[i] * l[i] >= 0) {
			tmp = min(tmp, (-cur + l[i] - 1) / l[i]);
		} else {
			tmp = min(tmp, b[i] + (-cur - l[i] * 1ll * b[i] + r[i] - 1) / r[i]);
		}
	}
	if (cur >= 0) {
		tmp = 0;
	}

	cout << ans + tmp << "\n";

	return 0;
}

