        _pararell_input(i, forward<Types>(args)...);
}


bool solve(){
    i64 n, x;
    input(n, x);
    vector<i64> b(n), l(n), u(n);
    pararell_input(n, b, l, u);

    i64 b_sum = 0;
    for(i64 i = 0; i < n; ++i)
        b_sum += b[i] * l[i];

    vector<i64> ful_adv(n);
    vector<pair<pair<i64,i64>,i64>> ful_adv_p;
    for(i64 i = 0; i < n; ++i){
        ful_adv[i] = u[i] * (x - b[i]) + l[i] * b[i];
        ful_adv_p.emplace_back(make_pair(ful_adv[i], l[i]), i);
    }
    sort(ful_adv_p.begin(), ful_adv_p.end(), greater<pair<pair<i64,i64>,i64>>());

    auto f = [&](i64 val){
        i64 cnt = min(val / x, n);
        i64 mod = (cnt == n ? 0 : val % x);
        i64 adv = 0;
        i64 dif = b_sum;
        i64 mod_adv = 0;
        bitset<100007> bs;

        for(i64 i = 0; i < cnt; ++i){
            adv += ful_adv_p[i].first.first;
            if(adv >= dif)
                return true;
            bs.set(ful_adv_p[i].second);
        }
        for(i64 i = 0; i < n; ++i){
            if(bs[i])
                continue;
            if(b[i] >= mod){
                chmax(mod_adv, l[i] * mod);
            }else{
                chmax(mod_adv, u[i] * (mod - b[i]) + l[i] * b[i]);
            }
        }
        adv += mod_adv;
        return adv >= dif;
    };

    i64 ok = 4e18, ng = -1;
    while(ok - ng > 1){
        i64 mid = (ok + ng) >> 1;
        (f(mid) ? ok : ng) = mid;
    }
    cout << ok << endl;

    return false;
}

signed main(){

    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(20);

    solve();
}

