#include<bits/stdc++.h>
#include<ext/pb_ds/assoc_container.hpp>
#include<ext/pb_ds/tree_policy.hpp>
#include<ext/pb_ds/priority_queue.hpp>
#define MAXN 100005
#define INF 1000000000000000000LL
#define MOD 1000000007
#define F first
#define S second
using namespace std;
using namespace __gnu_pbds;
typedef long long ll;
typedef pair<int,int> P;
typedef tree<int,null_type,less<int>,rb_tree_tag,tree_order_statistics_node_update> ordered_set;
typedef __gnu_pbds::priority_queue<int,greater<int>,pairing_heap_tag> pq;
ll N,X;
ll b[MAXN],l[MAXN],u[MAXN];
vector<ll> v;
struct segtree
{
    ll sum[4*MAXN];
    ll cnt[4*MAXN];
    void pushup(ll k)
    {
        cnt[k]=cnt[k*2]+cnt[k*2+1];
        sum[k]=sum[k*2]+sum[k*2+1];
    }
    void build(ll k,ll l,ll r)
    {
        sum[k]=0; cnt[k]=0;
        if(l==r) return;
        ll mid=(l+r)/2;
        build(k*2,l,mid); build(k*2+1,mid+1,r);
    }
    void update(ll k,ll l,ll r,ll p,ll val)
    {
        if(l==r)
        {
            cnt[k]+=val;
            sum[k]=1LL*cnt[k]*v[l];
            return;
        }
        ll mid=(l+r)/2;
        if(p<=mid) update(k*2,l,mid,p,val); else update(k*2+1,mid+1,r,p,val);
        pushup(k);
    }
    pair<ll,ll> query(ll k,ll l,ll r,ll s)
    {
        if(s<=0) return make_pair(0LL,0LL);
        if(l==r) 
        {
            ll need=max(0LL,(s-1)/v[l]+1);
            assert(need<=cnt[k]);
            return make_pair(need,1LL*need*v[l]);
        }
        ll mid=(l+r)/2;
        if(sum[k*2+1]>=s) return query(k*2+1,mid+1,r,s);
        else
        {
            P p=query(k*2,l,mid,s-sum[k*2+1]);
            p.F+=cnt[k*2+1]; p.S+=sum[k*2+1];
            return p;
        }
    }
}seg;
int main()
{
    ll need=0,ans=INF;
    scanf("%lld%lld",&N,&X);
    for(ll i=1;i<=N;i++) 
    {
        scanf("%lld%lld%lld",&b[i],&l[i],&u[i]);
        need+=1LL*b[i]*l[i];
        v.push_back(1LL*X*u[i]-1LL*b[i]*(u[i]-l[i]));
    }
    v.push_back(0);
    sort(v.begin(),v.end());
    v.erase(unique(v.begin(),v.end()),v.end());
    ll sz=(int)v.size();
    seg.build(1,1,sz);
    for(ll i=1;i<=N;i++)
    {
        ll res=1LL*X*u[i]-1LL*b[i]*(u[i]-l[i]);
        ll id=lower_bound(v.begin(),v.end(),res)-v.begin();
        seg.update(1,1,sz,id,1);
    }
    for(ll i=1;i<=N;i++)
    {
        ll res=1LL*X*u[i]-1LL*b[i]*(u[i]-l[i]);
        ll id=lower_bound(v.begin(),v.end(),res)-v.begin();
        seg.update(1,1,sz,id,-1);
        ll r=X*l[i];
        pair<ll,ll> ret=seg.query(1,1,sz,need-r);
        ll more=min(X,(ret.S+r-need)/l[i]);
        ans=min(ans,X-more+1LL*ret.F*X);
        ll cost=b[i]*(u[i]-l[i]);
        r=X*u[i];
        ret=seg.query(1,1,sz,need+cost-r);
        more=min(X,(ret.S+r-need-cost)/u[i]);
        ans=min(ans,X-more+1LL*ret.F*X);
        seg.update(1,1,sz,id,1);
    }
    printf("%lld\n",ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

bool C(ll t, vector<ll>b, vector<ll>l, vector<ll>u, ll N, ll X){
    // 重要度はl_iかu_iの2択
    // 点数は端数が1個で他は満点か0点
    // 満点を取るのに必要な時間は一定
    vector<pair<ll,int>> effect(N);
    for (int i = 0; i < N; ++i) {
        ll temp = ((X - b[i]) * u[i]) + (b[i] * l[i]);
        effect[i] = make_pair(temp, i);
    }
    sort(effect.begin(), effect.end(), greater<pair<ll,int>>());

    vector<int> flag(N,0); // 満点を取ったら1にする
    ll score = 0;
    for (int i = 0; i < N; ++i) {
        score -= b[i] * l[i];
    }

    // 上から満点の個数だけ満点と仮定
    int perfect = t / X;
    for (int i = 0; i < perfect; ++i) {
        score += effect[i].first;
        flag[effect[i].second] = 1;
    }
    t %= X;
    if(score >= 0) return true;
    if(t == 0) return false;

    // まずは今0点と仮定した中から端数を選んで探索
    for (int i = 0; i < N; ++i) {
        if(flag[i] == 0){
            ll temp;
            if(t <= b[i]) {
                temp = t * l[i];
            } else {
                temp = ((t - b[i]) * u[i]) + (b[i] * l[i]);
            }
            if(temp + score >= 0) return true;
        }
    }

    // 無理なら effect[perfect].second を満点にして満点→端数をどれにするかで線形全探索
    score += effect[perfect].first;
    for (int i = 0; i < N; ++i) {
        if(flag[i] == 1){
            ll temp; // 減る効果
            if(t <= b[i]) {
                temp = ((X - b[i]) * u[i]) + ((b[i] - t) * l[i]);
            } else {
                temp = (X - t) * u[i];
            }
            if(score - temp >= 0) return true;
        }
    }

    return false;
}

int main() {
    ll N, X;
    cin >> N >> X;
    vector<ll>b(N);
    vector<ll>l(N);
    vector<ll>u(N);
    for (int i = 0; i < N; ++i) {
      cin >> b[i] >> l[i] >> u[i];
    }

    // llで2ぶたん
    ll lb=0, ub = N * X + 1;
    while( ub-lb > 1 ){
        ll mid = (lb+ub)/2;
        if(C(mid, b, l, u, N, X)){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    cout << ub;
    return 0;
}

