using namespace std;

int n, x;
int tim;


class test {
public:
	int b, l, u;
	int dif() const {
		int mt = min(tim, x);
		int r1 = (mt * u + l * b - u * b);
		int r2 = (mt * l);
		return max(r1, r2);
	}
	bool operator<(const test& e) const {
		return dif() > e.dif();
	}
};

vector<test> t;

int maxdiff(int time) {
	tim = time;
	sort(t.begin(), t.end());
	int ret = 0;
	int time_remain = time;
	auto itr = t.begin();
	for (; itr != t.end() && time_remain >= x; itr++) {
		time_remain -= x;
		ret += itr->dif();
	}
	if (itr == t.end()) return ret;
	tim = time_remain;
	sort(itr, t.end());
	ret += itr->dif();
	return ret;
}

int main() {
	cin >> n >> x;
	test tt;

	int needed = 0;
	for (int i = 0; i < n; i++) {
		cin >> tt.b >> tt.l >> tt.u;
		t.push_back(tt);
		needed += tt.b * tt.l;
	}
	int l = 0;
	int r = x * n;
	while (r != l) {
		int m = (l + r) / 2;
		if (maxdiff(m) < needed) l = m + 1;
		else r = m;
	}
	cout << r << endl;
}

