    long R = x * n;
    while (R > L + 1) {
        long M = (L + R) / 2;
        vector<pair<long, int>> z(n);
        for (int i = 0; i < n; i++) {
            z[i] = {x * r[i] - (r[i] - l[i]) * b[i], i};
        }
        sort(z.begin(), z.end());
        int full = M / x;
        int rest = M % x;
        long ss = 0;
        vector<bool> tk(n);
        for (int i = n - full; i < n; i++) {
            ss += z[i].first;
            tk[z[i].second] = true;
        }
        bool ok = false;
        for (int i = 0; i < n; i++) {
            long sss;
            if (!tk[i]) {
                sss = ss + max(
                        rest * l[i],
                        rest * r[i] - (r[i] - l[i]) * b[i]);
