const int maxn = 1e5 + 5;

struct m {
    int b, l, u;
}mark[maxn];

bool cmp(m a, m b) {
    if (a.u != b.u) return a.u > b.u;
    return 1LL * a.b * a.l > 1LL * b.b * b.l;
}

int main() {
    int n, x;
    cin >> n >> x;
    for (int i = 0; i < n; i++) cin >> mark[i].b >> mark[i].l >> mark[i].u;
    sort(mark, mark + n, cmp);
    long long lScore[maxn];
    lScore[n] = 0;
    for (int i = n - 1; i >= 0; i--) lScore[i] = lScore[i + 1] + (1LL * mark[i].b * mark[i].l);
    long long curAScore = 0, curBUScore = 0, totalMarks = 0;
    // automata initial state: (curScore, totalMarks)
    for (int i = 0; i < n; i++) {
        curBUScore += 1LL * mark[i].b * mark[i].u;
        long long curBScore = curBUScore + lScore[i + 1];
        int lo = 0, hi = x;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2; // lower bound since it has chances of being invalid
            if (curAScore + 1LL * mid * mark[i].u >= curBScore)
                hi = mid;
            else
                lo = mid + 1;
        }
        totalMarks += hi;
        curAScore += 1LL * hi * mark[i].u;
        if (curAScore >= curBScore) break;
    }
    cout << totalMarks;
    return 0;
}

