bool is_ok(ll mid){
	pair<ll, int> a[125252];
	REP(i, n){
		a[i]=make_pair(u[i]*x-(u[i]-l[i])*b[i], i);
	}
	sort(a, a+n);
	ll k=mid/x, k2=mid%x, tmp=0;
	FORR(i, max(0ll, n-k), n){
		tmp+=a[i].first;
	}
	ll ma=0;
	FORR(i, 0, max(0ll, n-k)){
		int j=a[i].second;
		CHMAX(ma, u[j]*k2-(u[j]-l[j])*k2);
		CHMAX(ma, l[j]*k2);
	}
	if(tmp+ma>=sum){
		return true;
	}
	ll mi=1e12;
	FORR(i, max(0ll, n-k), n){
		int j=a[i].second;
		CHMIN(mi, u[j]*(x-k2));
		CHMIN(mi, u[j]*x-l[j]*k2-(u[j]-l[j])*b[j]);
	}
	tmp-=mi;
	if(n-k>0){
		tmp+=a[n-k-1].first;
	}
	return tmp>=sum;
}

