				min_time = min( min_time, t );
			}
			else
			{
				ll ss = leftScore;
				ss -= k[now].first;
				ss += l[i]*b[i]+u[i]*(x-b[i]);
				ll t=0;
				if( l[i] * b[i] >= leftScore )
				{
					t = div( leftScore, l[i] );
				}
				else
				{
					t = b[i];
					ll ss = leftScore - l[i]*b[i];
					t += div( ss, u[i] );
				}
				min_time = min( min_time, t );
			}
		}
	}
	cout << time+min_time << endl;
	return 0;
}

