bool check(LL mid){
	LL cnt=mid/fullmark,rem=mid-fullmark*cnt;
	rin(i,1,n){
		LL ext=0;
		if(i<=n-cnt)ext=sum[n]-sum[n-cnt];
		else ext=sum[n]-sum[n-cnt-1]-s[i].tot;
		if(rem<=s[i].b)if(rem*s[i].l+ext>=B)return true;
		if(rem>s[i].b)if(1ll*s[i].b*s[i].l+(rem-s[i].b)*s[i].r+ext>=B)return true;
	}
	return false;
}

