         [](auto l, auto r) { return l.sum() > r.sum(); });
    VL psum(N + 1);
    REP(i, N) { psum[i + 1] = psum[i] + datas[i].sum(); }
    ll bsum = 0;
    FOREACH(d, datas) { bsum += d.b * d.l; }
    auto check = [&](ll k) {
        if(k == N * X) return psum.back() >= bsum;
        REP(n, N) {
            auto q = k / X;
            ll sum = psum[q];
            if(n < q) sum = sum - datas[n].sum() + datas[q].sum();
            auto r = k % X;
            auto &data = datas[n];
            if(r <= data.b) {
                sum += data.l * r;
            } else {
                sum += data.l * data.b + data.u * (r - data.b);
            }
            if(sum >= bsum) return true;
        }
        return false;
    };

    ll l = 0, r = N * X;
    while(r - l > 1) {
        ll mid = (l + r) / 2;
        if(check(mid)) {
            r = mid;
        } else {
            l = mid;
        }
    }
    cout << r << endl;
    return 0;
}

