struct Exam {
    long b, l, u, x;
    bool operator<(const Exam& exam) {
        return (x - b) * u + b * l < (exam.x - exam.b) * exam.u + exam.b * exam.l;
    }
};

int main() {
    int n;
    long x;
    cin >> n >> x;
    long b_sum = 0;
    Exam exams[n];
    for (int i = 0; i < n; i++) {
        long b, l, u;
        cin >> b >> l >> u;
        exams[i] = Exam {b, l, u, x};
        b_sum += b;
    }

    long lb = -1, ub = b_sum, ans = b_sum;
    while (ub - lb > 1) {
        long mid = (lb + ub) / 2;
        long rest_time = mid;
        long aoki_score = 0, takahashi_score = 0;
        int i;
        sort(exams, exams + n);
        for (i = n - 1; i >= 0; i--) {
            Exam e = exams[i];
            if (rest_time >= e.b) {
                aoki_score += e.u * e.b;
                if (rest_time >= x) {
                    takahashi_score += e.u * x;
                    rest_time -= x;
                } else {
                    takahashi_score += e.u * rest_time;
                    rest_time = 0;
                }
            } else {
                break;
            }
        }
        for (; i >= 0; i--) {
            Exam e = exams[i];
            aoki_score += e.l * e.b;
            if (rest_time >= x) {
                takahashi_score += e.l * x;
                rest_time -= x;
            } else {
                takahashi_score += e.l * rest_time;
                rest_time = 0;
            }
        }
        if (aoki_score <= takahashi_score) {
            ans = ub = mid;
        } else {
            lb = mid;
        }
    }
    cout << ans << endl;
    return 0;
}

