bool solve(ll a) {
	//a個選んだ時の結果
	ll p, q, cnt=0,ans = 0;
	p = a / X;
	q = a % X;
	for (int i = 0;i < N;i++) {
		if (i > p)
			ans = Ru[p];
		else
			ans = Ru[p + 1] - A[i][0];

		if (A[i][1] > q) {
			//lowにする
			ans += q * A[i][2];
		}
		else {
			ans += q * A[i][3] - A[i][4];
		}
		cnt = max(cnt, ans);
	}
	return (cnt >= sum);
}

ll binary(ll ng, ll ok) {
	if (ng + 1 == ok)return ok;
	ll mid = (ng + ok) / 2;
	if (solve(mid)) {
		return binary(ng, mid);
	}
	else {
		return binary(mid, ok);
	}
}

