				long long t = ss - (w[j].e - w[j].b)*(X - w[j].a);
				if (t > 0) {
					Mx = max(Mx, t / w[j].b);
				}
			}
			rr = min(rr, res - Mx);
			break;
		}
	}
	printf("%lld\n", rr);
}

#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const int N=100100;
LL n,x;
struct E{
	LL b,l,u;
	E(){}
	E(LL _b,LL _l,LL _u){
		b=_b;
		l=_l;
		u=_u;
	}
	inline LL val()const{
		return b*l+u*(x-b);
	}
	inline LL de(LL rest)const{
		if(rest<=0)return 0;
		if(l*b>=rest)return (rest-1)/l+1;
		else return b+(rest-l*b-1)/u+1;
	}
	bool operator<(const E o)const{
		return val()>o.val();
	}
};

E es[N];
LL pf[N];

int main(){
	scanf("%lld%lld",&n,&x);
	LL delta=0;
	LL ans=LONG_LONG_MAX;
	for(int i=0;i<n;i++){
		LL b,l,u;
		scanf("%lld%lld%lld",&b,&l,&u);
		es[i]=E(b,l,u);
		delta+=(LL)b*l;
	}
	sort(es,es+n);
	for(int i=0;i<n;i++){
		pf[i]=es[i].val();
		if(i)pf[i]+=pf[i-1];
	}
	for(int i=0;i<n;i++){
		int l=-1,r=n-1;
		LL qq=delta-es[i].val();
		LL cc;
		// cerr<<i<<endl;
		while(l<r){
			int mid=(l+r)>>1;
			// cerr<<l<<" "<<r<<endl;
			cc=mid==-1?0:pf[mid]-(mid>=i?es[i].val():0);
			// cerr<<cc<<endl;
			if(cc>=qq){
				r=mid;
			}else{
				l=mid+1;
			}
		}
		// cerr<<"l "<<l<<endl;
		cc=l==-1?0:pf[l]-(l>=i?es[i].val():0);
		// cerr<<"cc "<<cc<<endl;
		ans=min(ans,es[i].de(delta-cc)+(l+(l<i?1:0))*x);
	}
	printf("%lld\n",ans);
	return 0;
}

