bool check(long long k){

    long long complete = k / x;
    long long other = k - complete * x;
    long long cursum = cur;

    if(complete >= n) return 1;

    for(int i = 0 ; i < n; ++i){

        if(i < complete){
            cursum += x * tests[i][3] - tests[i][1] * (tests[i][3] - tests[i][2]);
            if(cursum >= 0) return 1;
        } else {
            if(other > tests[i][1]){
                if(cursum + tests[i][3] * other - tests[i][1] * (tests[i][3] - tests[i][2]) >= 0)
                    return 1;
            } else {
                if(cursum + tests[i][2] * other >= 0)
                    return 1;
            }
        }
    }

    return cursum >= 0;

}

