{
	return a.v-a.u>b.v-b.u;
}

int main()
{
	n=getint(),k=getint();
	rep(i,1,n) b[i]=getint(),L[i]=getint(),R[i]=getint(),Ans+=b[i];
	rep(i,1,n) dat[i].u=-L[i]*b[i],dat[i].v=R[i]*(k-b[i]),dat[i].id=i;
	sort(dat+1,dat+1+n,cmp);
	rep(i,1,n) tot+=dat[i].u;
	rep(i,1,n)
	{
		if(tot-dat[i].u+dat[i].v>=0)
		{
			rep(j,i+1,n) if(tot-dat[j].u+dat[j].v>=0)
			{
				int p=dat[j].id;
				ans=k*(i-1);
				if(tot-dat[i].u>=0)
					ans+=(-tot-1)/L[p]+1;
				else ans+=b[p]+min(k-b[p],(-(tot-dat[i].u)-1)/R[p]+1);
				Ans=min(Ans,ans);
			}
			tot=tot-dat[i].u+dat[i].v;
			rep(j,1,i)
			{
				int p=dat[j].id;
				ans=k*i;
				if(tot-dat[i].v>=0) ans-=(k-b[p])+min((tot-dat[i].v)/L[p],b[p]);
				else ans-=tot/R[p];
				Ans=min(Ans,ans);
			}	
			break;
		}	
		tot-=dat[i].u;
		tot+=dat[i].v;
	}
	printf("%lld\n",Ans);
	return 0;
}

