priority_queue<aoki, vector<aoki>, cmp1> p;//最大收益优先队列
//priority_queue<aoki, vector<aoki>, cmp1> q;//最小损失优先队列，可不可以只靠损失就能赢


//如果一个损失救不了，那肯定不如先搞收益高的
bool visit[MAXN] = { false };//认为我们有没有拜访过

signed main() {
	int n, x;
	scanf("%lld%lld", &n, &x);
	int loseall = 0;
	int ans1 = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%lld%lld%lld", &ao[i].b, &ao[i].l, &ao[i].u);
		ao[i].canget = x * ao[i].u - (ao[i].u - ao[i].l)*ao[i].b;
		//ao[i].lose = ao[i].l*ao[i].b;
		ao[i].id = i;
		loseall += ao[i].l*ao[i].b;
		p.push(ao[i]);
		//q.push(ao[i]);
	}
	while (!p.empty()) {
		aoki temp = p.top();
		p.pop();
		if (loseall < temp.canget) {
			break;
		}
		else {
			ans1 += x;
			loseall -= temp.canget;
			visit[temp.id] = true;
		}
	}
	int ans2 = x;
	for (int i = 1; i <= n; i++) {
		if (visit[i]) continue;
		int temp1 = ao[i].l*ao[i].b;
		if (temp1 > loseall) {
			int temp2 = (loseall / ao[i].l);
			if (temp2* ao[i].l < loseall) temp2++;
			ans2 = min(ans2, temp2);
		}
		else {
			int temp2 = ((loseall-temp1) / ao[i].u);
			if (temp2* ao[i].u < loseall-temp1) temp2++;
			ans2 = min(ans2, ao[i].b + temp2);
		}
	}
	printf("%lld", ans1 + ans2);
	return 0;
}

