#define ll long long int

ll const MOD = 1000000007;
ll const INF = (long long int)1 << 61;

ll mypow(ll x,ll n){
    ll ret = 1;
    while(n > 0){
        if(n&1){
            ret = (ret*x)%MOD;
        }
        x = (x*x)%MOD;
        n >>= 1;
    }
    return ret;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n,x;
    cin >> n >> x;

    vector<ll> b(n),l(n),u(n);
    for(int i = 0; i < n; i++){
        cin >> b[i] >> l[i] >> u[i];
    }

    vector<pair<ll,ll>> s;
    for(int i = 0; i < n; i++){
        s.push_back(make_pair((x - b[i])*u[i] + b[i]*l[i],(ll)i));
    }

    sort(s.begin(),s.end(),greater<pair<ll,ll>>());

    vector<ll> lsum(n,0),usum(n,0);

    lsum[0] = b[s[0].second]*l[s[0].second];
    usum[0] = b[s[0].second]*u[s[0].second];

    for(int i = 1; i < n; i++){
        lsum[i] = lsum[i-1] + b[s[i].second]*l[s[i].second];
        usum[i] = usum[i-1] + b[s[i].second]*u[s[i].second];
    }

    ll mynum = 0;
    ll ans = 0;

    for(int i = 0; i < n; i++){
        if(mynum+x*u[s[i].second] >= usum[i] + lsum[n-1] - lsum[i]){
            ll m = INF;
            for(int y = i; y < n; y++){
                ll ok = x+1;
                ll ng = -1;
                ll ok2 = x+1;
                ll ng2 = -1;
                ll sle1 = u[s[y].second];
                ll sle2 = l[s[y].second];
                while(abs(ok - ng) > 1){
                    ll middle = (ok+ng)/2;
                    if(middle*sle1 + mynum >= (y > 0 ? usum[y-1]:0) + lsum[n-1] - lsum[y] + b[s[y].second]*sle1){
                        ok = middle;
                    }else{
                        ng = middle;
                    }
                }
                while(abs(ok2 - ng2) > 1){
                    ll middle = (ok2+ng2)/2;
                    if(middle*sle2 + mynum >= (y > 0 ? usum[y-1]:0) + lsum[n-1] - lsum[y] + b[s[y].second]*sle2){
                        ok2 = middle;
                    }else{
                        ng2 = middle;
                    }
                }
                m = min(m,min(ok2,ok));
            }
            ans += m;
            break;
        }else{
            mynum += x*u[s[i].second];
            ans += x;
        }
    }

    cout << ans << endl;

    return 0;
}

