int n,Max;
int b[100005],l[100005],r[100005];
int a[100005];
bool cmp(int x,int y){
	int tx=x,ty=y;
	int vx=(Max-b[tx])*r[tx],vy=(Max-b[ty])*r[ty];
	int v2x=b[tx]*l[tx],v2y=b[ty]*l[ty];
	return (vx+v2x)>(vy+v2y);
}
bool ok(int t){
	for(int i=1;i<=n;i++)a[i]=i;
	sort(a+1,a+n+1,cmp);
	int times=t/Max,rest=t-times*Max;
	int more=0;
	for(int i=1;i<=times;i++){
		more+=(Max-b[a[i]])*r[a[i]];
	}
	int best=-1e18,pos=-1;
	for(int i=times+1;i<=n;i++){
		int tmp=rest-b[a[i]];
		if(l[a[i]]*tmp>best||r[a[i]]*tmp>best)best=max(l[a[i]]*tmp,r[a[i]]*tmp),pos=i;
	}
	int less=0;
	for(int i=times+1;i<=n;i++)if(i!=pos)less+=l[a[i]]*b[a[i]];
//	cerr<<t<<" "<<more<<" "<<best<<" "<<less<<endl;
	return more+best>=less;
}
