long long l[100000];
long long u[100000];
long long s[100001];

long long get(int p, long long r) {
    if (r <= 0) return 0;
    if ((x - b[p]) * u[p] + b[p] * l[p] < r) return 1e18;
    if (b[p] * l[p] >= r) return (r + l[p] - 1) / l[p];
    return b[p] + (r - b[p] * l[p] + u[p] - 1) / u[p];
}

int main() {
    int n, p = -1, i;
    long long ans = 1e18, sum = 0;
    vector <pair<long long, int>> v;

    scanf("%d %lld", &n, &x);

    for (i = 0; i < n; i++) {
        scanf("%lld %lld %lld", &b[i], &l[i], &u[i]);

        sum += b[i] * l[i];
        v.push_back(make_pair((x - b[i]) * u[i] + b[i] * l[i], i));
    }

    if (sum == 0) {
        puts("0");

        return 0;
    }

    sort(v.begin(), v.end());
    reverse(v.begin(), v.end());

    for (i = 0; i < n; i++) s[i + 1] = s[i] + v[i].first;

    for (i = 1; i <= n; i++) {
        if (s[i] >= sum) break;
        p++;
    }

    for (i = 0; i < n; i++) {
        if (i <= p) {
            int q = lower_bound(s, s + n + 1, sum + v[i].first) - s - 1;
            long long c = (q - 1) * x;
            long long r = sum + v[i].first - s[q];

            ans = min(ans, c + get(v[i].second, r));
        } else {
            long long c = (p + 1) * x;
            long long r = sum - s[p + 1];

            ans = min(ans, c + get(v[i].second, r));
        }
    }

    printf("%lld\n", ans);

    return 0;
}

