	}

	sort(p+1,p+n+1);

	lint taka=0,ans=0;int loc=0;
	for(int i=1;i<=n;i++)
	{
		if(taka+p[i].val>=riva){loc=i;break;}
		taka+=p[i].val,ans+=lim;
	}

	lint sans=ans+lim;
	for(int i=loc;i<=n;i++)
	{
		lint l=0,r=lim,ret=lim+1;
		while(r>=l)
		{
			lint mid=(l+r)>>1,dlt=0;
			if(mid<=p[i].bas)dlt=p[i].l*mid;
			else dlt=(p[i].l-p[i].r)*p[i].bas+p[i].r*mid;
			if(taka+dlt>=riva)ret=mid,r=mid-1;
			else l=mid+1;
		}
		if(ret<=lim)sans=min(sans,ans+ret);
	}

	printf("%lld\n",sans);

	return 0;
}

