ll comp(int i, int j){
	ll p,q;
	p = (x-b[i])*u[i]+b[i]*l[i];
	q = (x-b[j])*u[j]+b[j]*l[j];
	return p>q;
}

bool judge(ll p){
	int i;
	ll q,r,tmp=df,d=-INFLL,c,qv;
	q = p/x; r = p%x;
	for(i=0; i<q; ++i){
		tmp += (x-b[v[i]])*u[v[i]]+b[v[i]]*l[v[i]];
	}
	qv = (x-b[v[q]])*u[v[q]]+b[v[q]]*l[v[q]];
	for(i=0; i<n; ++i){
		c = min(r,b[v[i]])*l[v[i]]+max(r-b[v[i]],0ll)*u[v[i]];
		if(i<q){
			c -= (x-b[v[i]])*u[v[i]]+b[v[i]]*l[v[i]];
			d = max(d,tmp+qv+c);
		}else{
			d = max(d,tmp+c);
		}
	}
	return (d>=0ll);
}

