struct Node {
	LL l, r, b, h;
	inline bool operator < (const Node &w) const {
		return h > w.h;
	}
}node[N];

LL X, D;
int n;

inline LL cal(LL a, LL i) {
	if(a <= node[i].b) {
		return a * node[i].l;
	}
	return node[i].b * node[i].l + (a - node[i].b) * node[i].r;
}

inline bool check(LL k) {
	LL ans = 0, temp = 0;
	for(int i = 1; i <= n; i++) {
		if(k >= X) {
			ans += node[i].h;
			k -= X;
		}
		else {
			temp = std::max(temp, cal(k, i));
		}
	}
	return ans + temp >= D;
}

