using namespace std;
using ll = long long;
template <class T>
using V = vector<T>;
using P = pair<ll, ll>;


void solve(ll n, ll x, vector<ll> B, vector<ll> L, vector<ll> U) {
    ll base = 0;
    loop (n, i) base += B[i] * L[i];

    V<ll> S(n);
    loop (n, i) S[i] = B[i] * L[i] + (x - B[i]) * U[i];

    V<int> I(n);
    iota(I.begin(), I.end(), 0);
    sort(I.begin(), I.end(), [&S](auto a, auto b) {
        return S[a] > S[b];
    });

    ll left = 0, right = x * n + 1;
    while (left < right) {
        ll m = (left + right) / 2;

        ll k = m / x;
        ll r = m - k * x;

        ll pnt = 0;
        loop (k, i) pnt += S[I[i]];

        ll rp = 0;
        loop (n - k, i) {
            int idx = I[i + k];
            ll rpp = L[idx] * min(B[idx], r) + U[idx] * max(0LL, r - B[idx]);
            rp = max(rp, rpp);
        }
        if (base <= pnt + rp) right = m;
        else left = m + 1;
    }
    cout << right << endl;
}

