    ll n, x;
    cin >> n >> x;
    vector<ll> B(n), L(n), U(n);
    loop (n, i) {
        cin >> B[i] >> L[i] >> U[i];
    }
    solve(n, x, move(B), move(L), move(U));
    return 0;
}

