void _input(int, T& x){

    for(auto& elm : x)
        _input(0, elm);
}

template <typename T>
void input_single(T& x){
    _input(0, x);
}

auto input(){}

template <typename T, typename... Types>
void input(T& value, Types&&... args){
    input_single(value);
    input(forward<Types>(args)...);
};

void _pararell_input(size_t){}

template <typename T, typename... Types>
void _pararell_input(size_t index, T& value, Types&&... args){
    input(value[index]);
    _pararell_input(index, forward<Types>(args)...);
}

template <typename... Types>
void pararell_input(size_t count, Types&&... args){
    for(const auto& i : Range<>(count))
        _pararell_input(i, forward<Types>(args)...);
}


bool solve(){
    int nn, xx;
    input(nn, xx);
    vector<int> bb(nn), ll(nn), uu(nn);
    pararell_input(nn, bb, ll, uu);

    i64 n = nn;
    i64 x = xx;
    vector<i64> b, l, u;
    for(int i = 0; i < n; ++i){
        b.emplace_back(bb[i]);
        l.emplace_back(ll[i]);
        u.emplace_back(uu[i]);
    }
    i64 b_sum = 0;
    for(i64 i = 0; i < n; ++i)
        b_sum += b[i] * l[i];

    vector<i64> ful_adv(n);
    vector<pair<pair<i64,i64>,i64>> ful_adv_p;
    for(i64 i = 0; i < n; ++i){
        ful_adv[i] = u[i] * (x - b[i]) + l[i] * b[i];
        ful_adv_p.emplace_back(make_pair(ful_adv[i], l[i]), i);
    }
    sort(ful_adv_p.begin(), ful_adv_p.end(), greater<pair<pair<i64,i64>,i64>>());

    auto f = [&](i64 val){
        i64 cnt = min(val / x, n);
        i64 mod = (cnt == n ? 0 : val % x);
        i64 adv = 0;
        i64 dif = b_sum;
        i64 mod_adv = 0;
        bitset<100007> bs;

        for(i64 i = 0; i < cnt; ++i){
            adv += ful_adv_p[i].first.first;
            if(adv >= dif)
                return true;
            bs.set(ful_adv_p[i].second);
        }
        for(i64 i = 0; i < n; ++i){
            if(bs[i])
                continue;
            if(b[i] >= mod){
                chmax(mod_adv, l[i] * mod);
            }else{
                chmax(mod_adv, u[i] * (mod - b[i]) + l[i] * b[i]);
            }
        }
        adv += mod_adv;
        return adv >= dif;
    };

    i64 ok = 2e18, ng = -1;
    while(ok - ng > 1){
        i64 mid = (ok + ng) >> 1;
        (f(mid) ? ok : ng) = mid;
    }
    cout << (long long)(ok) << endl;

    return false;
}

