		cur+=max(0LL,rem-z[i].opp)*z[i].r;
		if(cur>=need) return true;
	}
	return false;
}

ll solve() {
	ll need=0; REP(i,n) need+=(ll)z[i].opp*z[i].l;
	REP(i,n) z[i].full=(ll)z[i].opp*z[i].l+(ll)(lim-z[i].opp)*z[i].r;
	sort(z,z+n);
	zfullsum[0]=0; REP(i,n) zfullsum[i+1]=zfullsum[i]+z[i].full;

	ll l=-1,h=(ll)lim*n;
	while(l+1<h) {
		ll m=l+(h-l)/2;
		if(can(m,need)) h=m; else l=m;
	}
	return h;
