	long long now = 0;
	for(int i = 0; i < n; i++){
		cin >> b[i] >> l[i] >> u[i];
		now += - 1ll * l[i] * b[i];
		val[i] = 1ll * l[i] * b[i] + 1ll * (x - b[i]) * u[i];
	}
	iota(od.begin(), od.end(), 0);
	sort(od.begin(), od.end(), [&](int a, int b){
		return val[a] > val[b];
	});
	long long lo = 0, hi = 1ll * n * x - 1, ans = 1ll * n * x;
	vector<long long> pref(n + 1, 0);
	for(int i = 0; i < n; i++) pref[i + 1] = pref[i] + val[od[i]];
	while(lo <= hi){
		long long mid = (lo+hi)>>1;
		int tk = mid / x, stk = mid % x;
		auto apply = [&](int id){
			int p = min(stk, b[id]);
			return 1ll * p * l[id] + 1ll * (stk - p) * u[id];
		};
		bool good = false;
		for(int i = 0; i < n; i++){
			long long cur = pref[tk + (i < tk)];
			if(i < tk) cur -= val[od[i]];
			if(cur + apply(od[i]) + now >= 0) good = true;
		}
