Int N;
Int X;
vector<Int> b;
vector<Int> l;
vector<Int> u;

void solve(){
	vector<pair<Int,int> > v;
	REP(i,N){
		v.push_back({u[i]*X - u[i]*b[i] + l[i]*b[i], i});
	}
	sort(ALL(v));
	reverse(ALL(v));
	Int sum = 0, ans = inf<Int>(), study_time = 0;
	REP(i,N)sum += - l[i] * b[i];
	for(auto &&p:v){
		Int d = p.first;
		int i = p.second;
		do{
		// x - b[i] : negative, c[i] = l[i]
			Int study_time0;
			if(sum>=0){
				study_time0 = study_time;
			}else{
				Int x = ceil_div(-sum,l[i]);
				if(b[i]<x)break;
				study_time0 = study_time + x;
				assert(0<=x and x<=b[i]);
			}
			ans = min(ans,study_time0);
		}while(0);
		do{
		// x - b[i] : positive, c[i] = u[i]
			Int study_time0;
			Int sum0 = sum + l[i] * b[i];//study b[i] hour
			if(sum0>=0){
				study_time0 = study_time + b[i];
			}else{
				Int x = max(b[i],ceil_div(- sum + (u[i]-l[i])*b[i], u[i]));
				if(X<x)break;
				assert(b[i]<=x and x<=X);
				study_time0 = study_time + x;
			}
			ans = min(ans,study_time0);
		}while(0);
		sum += d;
		study_time += X;
	}
	assert(ans!=inf<Int>());
	cout<<ans<<endl;
}

