    while (lo < hi) {
        long long mi = lo + hi >> 1;
        long long num = mi / x;
        long long r = mi % x;
        int found = 0;
        if (n <= num) {
            found = 1;
        }
        else {
            sort(all(vals), [&] (int i, int j) {
                    long long dif = (long long) (x - b[i]) * u[i] - (long long) (x - b[j]) * u[j];
                    if (dif) return dif > 0;
                    return u[i] > u[j];
