                    int k = vals[num];
                    sum -= (long long) (x - b[k]) * u[k];
                    sum2 += (long long) -b[k] * l[k];
                }
                else {
                    sum2 += (long long) -b[j] * l[j];
                }
            }
            if (0 <= mx) {
                found = 1;
            }
        }
        if (!found) {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
