        cin >> b[i] >> l[i] >> u[i];
        b_sum += b[i];
        base -= b[i]*l[i];
        p[i] = P(u[i]*X-u[i]*b[i]+l[i]*b[i], i);
    }
    if(b_sum == 0){
        cout << 0 << endl;
        return 0;
