ll n,x;
struct ver{
	ll b,l,r;
	ll allsum(){
		return b*l+(x-b)*r;
	}
	ll opp(){
		return b*l;
	}

	ver(ll b,ll l,ll r){
		this->b=b,this->l=l,this->r=r;
	}
};
bool operator<(const ver&a,const ver&b){
	ll vl=a.b*a.l+(x-a.b)*a.r;
	ll vr=b.b*b.l+(x-b.b)*b.r;
	return vl>vr;
};
vector<ver> v;
ll cs[N],oppsum;
bool judge(ll k,ll t){
	ll cost=k/x; if(cost>=n)return cs[n];
	ll res=min(k%x,v[t].b)*v[t].l+max(0LL,k%x-v[t].b)*v[t].r;
	res+=cs[min(t,cost)]-cs[0];
	if(t+1<=cost)res+=cs[cost]-cs[t+1];
	return oppsum<=res;
}
ll solve(ll t){
	ll l=0,r=1e17,m;
	while(l<r-1){
		m=(l+r)>>1;
		if(judge(m,t))r=m;
		else l=m;
	}
	//cout<<t<<":"<<r<<endl;
	return r;
}
