}s[100010];
int n,x;
int cmp(stu aa,stu bb){
    return aa.u*(x-aa.b)>bb.u*(x-bb.b);
}

int check(long long mid)
{

    int p=mid%x;int q=mid/x;
    for (int i=0;i<n;i++)
    {
        long long dis=0;
        if (p!=0){
        if(p>s[i].b){
            dis+=p*s[i].u;
            dis-=s[i].b*s[i].u;
        }else{
            dis+=p*s[i].l;
            dis-=s[i].b*s[i].l;
        }
        }
        int tmp=q;int now=0;
        while(tmp){
            if (p!=0 && now==i){now++;continue;}
            tmp--;
            dis+=x*s[now].u;
            dis-=s[now].b*s[now].u;
            now++;
        }
        for (int j=now;j<n;j++)
        {
            if(p!=0 && j==i) continue;
            dis-=s[j].b*s[j].l;
        }
        if (dis>=0)
        {
            return 1;
        }
    }


    return 0;
}

