using namespace std;
typedef long long ll;

int main() {
	ll i, j;
	ll N, X;
	ll b[nmax_def], l[nmax_def], u[nmax_def];
	pair<ll,ll> diff[nmax_def];
	ll diff_sum = 0;
	cin >> N >> X;
	for (i = 0; i < N; i++)
	{
		cin >> b[i] >> l[i] >> u[i];
		ll Atmp = (X - b[i]) * u[i];
		ll Btmp = b[i] * l[i];
		diff_sum -= Btmp;
		diff[i].first = Atmp + Btmp;
		diff[i].second = i;
	}
	sort(diff, diff + N, greater <pair<ll, ll>>());
	ll ans = 0;
	i = 0;
	while (1)
	{
		diff_sum += diff[i].first;
		ans += X;
		if (diff_sum >= 0)
			break;
		i++;
	}

	ll ansans = ans;
	diff_sum -= diff[i].first;
	ans -= X;

	for (i = i; i < N; i++)
	{
		ll diff_sum_tmp = diff_sum;
		ll ans_tmp = ans;
		int i_inv = diff[i].second;
		diff_sum_tmp += b[i_inv] * l[i_inv];
		ans_tmp += b[i_inv];
		if (diff_sum_tmp >= 0)
		{
			ans_tmp -= diff_sum_tmp / l[i_inv];
		}
		else
		{
			diff_sum_tmp *= -1;
			ans_tmp += (diff_sum_tmp - 1) / u[i_inv] + 1;
		}
		ansans = min(ansans, ans_tmp);
	}


	cout << ansans << endl;
	return 0;
}

