const ll MOD = 1000000007LL;
typedef pair <ll, int> P;

int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ll n, x;
    cin >> n >> x;

    ll b[n], l[n], u[n];
    ll sm = 0;
    for (int i = 0; i < n; i++) {
        cin >> b[i] >> l[i] >> u[i];
        sm += b[i] * l[i];
    }

    vector <P> benefit(n);
    for (int i = 0; i < n; i++) {
        benefit[i] = P(b[i] * l[i] + (x - b[i]) * u[i], i);
    }

    sort(benefit.begin(), benefit.end(), greater<P>());

    vector <ll> benefit_sm(n);
    for (int i = 0; i < n; i++) {
        benefit_sm[i] = benefit[i].first;
        if (i) benefit_sm[i] += benefit_sm[i-1];
    }

    ll ret = 1LL << 60;
    for (int i = 0; i < n; i++) {
        // 一番最後に除く奴を全探索

        ll mx = b[i] * l[i] + (x - b[i]) * u[i];

        if (sm <= mx) {
            ll tmp = sm;
            ll ans = 0;
            if (tmp <= b[i] * l[i]) {
                ans += tmp / l[i];
                if (tmp % l[i] > 0) ans++;
            } else {
                tmp -= b[i] * l[i];
                ans += b[i];
                ans += tmp / u[i];
                if (tmp % u[i] > 0) ans++;
            }

            ret = min(ret, ans);
        }

        int idx = lower_bound(benefit_sm.begin(), benefit_sm.end(), sm) - benefit_sm.begin();
        idx--;
        if (idx < 0) continue;

        if (benefit[idx].first <= mx) {
            ll tmp = sm - benefit_sm[idx] + mx;
            ll ans = (ll)idx * x;

            while (tmp > mx) {
                idx++;
                tmp -= benefit[idx].first;
                ans += x;
            }

            if (tmp < 0) continue;

            if (tmp <= b[i] * l[i]) {
                ans += tmp / l[i];
                if (tmp % l[i] > 0) ans++;
            } else {
                tmp -= b[i] * l[i];
                ans += b[i];

                ans += tmp / u[i];
                if (tmp % u[i] > 0) ans++;
            }

            ret = min(ret, ans);
        }

        ll tmp = sm - benefit_sm[idx];
        ll ans = (ll)(idx + 1) * x;

        if (tmp < 0) continue;

        if (tmp <= b[i] * l[i]) {
            ans += tmp / l[i];
            if (tmp % l[i] > 0) ans++;
        } else {
            tmp -= b[i] * l[i];
            ans += b[i];

            ans += tmp / u[i];
            if (tmp % u[i] > 0) ans++;
        }

        ret = min(ret, ans);
    }

    cout << ret << "\n";
    return 0;
}

