ll sum[N];
bool cmp(int x,int y) { return sum[x]>sum[y]; }
ll get(int i,int y) {
	if(b[i]>=y) return l[i]*(ll)y;
	return l[i]*(ll)b[i]+u[i]*(ll)(y-b[i]);
}
ll cal(ll k) {
	int x=k/X,y=k%X;
	ll tot=0,ans=0;
	for(int i=1;i<=x;++i) tot+=sum[id[i]];
	if(!y) return tot;
	for(int i=1;i<=n;++i) {
		if(i<=x) ans=max(ans,tot-sum[id[i]]+sum[id[x+1]]+get(id[i],y));
		else ans=max(ans,tot+get(id[i],y));
	}
	return ans;
}
int main() {
	rd(n),rd(X);
	ll tot=0;
	for(int i=1;i<=n;++i) {
		rd(b[i]),rd(l[i]),rd(u[i]);
		tot-=l[i]*(ll)b[i];
		sum[i]=l[i]*(ll)b[i]+u[i]*(ll)(X-b[i]);
		id[i]=i;
	}
	sort(id+1,id+n+1,cmp);
