		return 1;


	for(int i = 0; i < n; i++){
		int cur = value[i].se;
		ll aoki_cur = aoki;
		ll ans_cur = ans;

		if(i < num){
			if(num < n){
				ans_cur -= value[i].fi;
				ans_cur += value[num].fi;
				ans_cur += r * l[cur];

				aoki_cur += (l[cur] - u[cur]) * b[cur];
				aoki_cur += (u[num] - l[num]) * b[num];
			}
		}
		else
			ans_cur += l[cur] * r;

		if(ans_cur >= aoki_cur)
			return 1;
	}

	return 0;
