const int MAX_N = 100 * 1000 + 5;
int n, X, b[MAX_N], l[MAX_N], u[MAX_N], id[MAX_N];

void read_input() {
	cin >> n >> X;
	for (int i = 0; i < n; i++)
		cin >> b[i] >> l[i] >> u[i];
}

long long get(int i) {
	return u[i] * (X - b[i]) + b[i] * l[i];
}

bool cmp(int i, int j) {
	return get(i) > get(j);
}

void solve() {
	iota(id, id + n, 0);
	sort(id, id + n, cmp);
	long long sum = 0;
	for (int i = 0; i < n; i++)
		sum += b[i] * l[i];
	long long ans = 0;
	for (int j = 0; j < n && sum; j++) {
		int i = id[j];
		long long tmp = (X - b[i]) * u[i] + b[i] * l[i];
		if (sum >= tmp) {
			sum -= tmp;
			ans += X;
		}
		else {
			ans += min((sum + l[i] - 1) / l[i], (sum - l[i] * b[i] + u[i] - 1) / u[i] + b[i]);
			break;
		}
	}
	cout << ans;
}

int32_t main() {
	ios::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	read_input();
	solve();
}

