using namespace std;
const int N=100007;
int n,m;
struct P {
	LL x,l,r,sc;
	bool operator < (const P &_) const {
		return sc+l*x>_.sc+_.l*_.x;
	}
}A[N];
int win(LL s) {
	int x=s/m,y=s%m;
	LL t=0;
	For(i,1,x) t+=A[i].sc;
	For(i,x+1,n) t-=A[i].l*A[i].x;
	if(t>=0) return 1;
	For(i,1,n) {
		LL w;
		if(y<A[i].x) w=-A[i].l*(A[i].x-y);
		else w=A[i].r*(y-A[i].x);
		if(i<=x) {
			LL r=t+A[x+1].l*A[x+1].x+A[x+1].sc-A[i].sc+w;
			if(r>=0) return 1;
		}
		else {
			LL r=t+A[i].l*A[i].x+w;
			if(r>=0) return 1;
		}
	}
	return 0;
}
int main() {
	scanf("%d%d",&n,&m);
	For(i,1,n) {
		scanf("%lld%lld%lld",&A[i].x,&A[i].l,&A[i].r);
		A[i].sc=(m-A[i].x)*A[i].r;
	}
	sort(A+1,A+1+n);
	LL l=0,r=0;
	For(i,1,n) r+=A[i].x;
	while(l<=r) {
		LL mi=(l+r)>>1;
		if(win(mi)) r=mi-1;
		else l=mi+1;
	}
	printf("%lld",l);
	return 0;
}

