    rep(i, N) {
        ll b, l, u;
        cin >> b >> l >> u;
        tests[i] = mt(b * l + (X - b) * u, b, l, u);
        offset += b * l;
        bsum += b;
    }
    sort(rall(tests));
    rep(i, N) {
        cumsum[i + 1] = cumsum[i] + get<0>(tests[i]);
    }

    int ng = -1, ok = bsum;
    while (ok - ng > 1) {
