bool judge(const V<t4> &sblulist, ll n, ll limit, ll aim, ll cnt)
{
    ll limit_cnt = cnt / limit;
    ll rem = cnt % limit;

    debug_printf("cnt=%lld limit=%lld limit_cnt=%lld\n",
                 cnt, limit, limit_cnt);

    ll limit_sum = 0LL;
    rep (i, limit_cnt) limit_sum += get<0>(sblulist[i]);

    if (!rem) return limit_sum >= aim;

    limit_sum += get<0>(sblulist[limit_cnt]);

    ll sum = 0LL;

    rep (rem_idx, n) {
        ll lsum = limit_sum;
        lsum -= ((rem_idx < limit_cnt) ?
                 get<0>(sblulist[rem_idx]) :
                 get<0>(sblulist[limit_cnt]));

        debug_printf("  limit_sum=%lld lsum=%lld\n",
                     limit_sum, lsum);

        auto sblu = sblulist[rem_idx];
        ll b = get<1>(sblu);
        ll low = get<2>(sblu);
        ll high = get<3>(sblu);

        ll incr = 0LL;
        incr += ((rem < b) ? rem * low : b * low);
        incr += ((rem < b) ? 0LL : (rem - b) * high);

        lsum += incr;

        sum = max(sum, lsum);
    }

    debug_printf("  cnt=%lld limit_sum=%lld sum=%lld\n",
                 cnt, limit_sum, sum);

    return sum >= aim;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    ll limit; llin(limit);
    S V<t3> blulist; llinl3(blulist, n);

    ll aim = 0LL;
    for (auto blu : blulist) {
        ll b = get<0>(blu);
        ll low = get<1>(blu);
        aim += b * low;
    }

    S V<t4> sblulist;
    for (auto blu : blulist) {
        ll b = get<0>(blu);
        ll low = get<1>(blu);
        ll high = get<2>(blu);
        ll sum = b * low + (limit - b) * high;
        sblulist.pb(t4(sum, b, low, high));
    }

    sort_reverse(sblulist);

    ll left = 0LL;
    ll right = limit * n;
    ll now = (left + right) / 2LL;
    ll ans = right;

    for ( ; left <= right; now = (left + right) / 2LL) {
        if (judge(sblulist, n, limit, aim, now)) {
            ans = min(ans, now);
            right = now - 1LL;
        }
        else {
            left = now + 1LL;
        }
    }

    cout << ans << endl;

}

