    if(k >= B[who]){return U[who];}
    return L[who];
}

vector <pair <long long, int> > G;

bool check(int n, int m, int k){
    //cout << m << endl;
    for(int i = 1; i <= m; i++){
        int p = G[i - 1].second;
        int multi = mult(p, k);
        long long a1 = sum[m + 1] - sum[i] + sum[i - 1] + (long long)(k - B[p]) * multi;
        long long a2 = pre[n] - pre[m + 1];
        if(a1 >= a2){return true;}
        //cout << multi << endl;
    }
    for(int i = m + 1; i <= n; i++){
        int p = G[i - 1].second;
        int multi = mult(p, k);
        long long a1 = sum[m] + (k - B[p]) * multi;
        long long a2 = pre[n] - pre[i] + pre[i - 1] - pre[m];
        if(a1 >= a2){return true;}
    }
    return false;
}

