#include <bits/stdc++.h>
using namespace std;

long long N, X;
class BLU {
public :
    long long b, l, u;
    long long max_d, min_d;

    BLU(long long b, long long l, long long u)
    :b(b), l(l), u(u)
    {
        max_d = X * u - b * u;
        min_d = - b * l;
    }
};
vector<BLU> A;
vector<long long> S_AU, S_AL, S_BU;

bool check(long long m)
{
    long long cnt = m / X;
    if(cnt >= N) return true;
    long long score_a = cnt ? S_AU[cnt-1] + S_AL.back() - S_AL[cnt-1] : S_AL.back();
    long long score_b = cnt ? S_BU[cnt-1]:0;
    long long k = m % X;
    for(auto i = 0; i < N; ++i)
    {
        long long c = k > A[i].b ? A[i].u : A[i].l;
        long long s_a = score_a;
        long long s_b = score_b;
        if(i < cnt) {
            s_a -= A[i].b * A[i].u;
            s_b -= X * A[i].u;

            s_a += A[cnt].max_d - A[cnt].min_d;
            s_b += X * A[cnt].u;
        }
        else {
            s_a -= A[i].b * A[i].l;
            s_b -= 0;
        }

        s_a += c * A[i].b;
        s_b += c * k;

        if(s_a <= s_b)
            return true;
    }

    return false;
}

void solve()
{
    cin >> N >> X;

    for(auto i = 0; i < N; ++i)
    {
        long long b, l, u;
        cin >> b >> l >> u;
        A.emplace_back(BLU(b, l, u));
    }

    sort(A.begin(), A.end(), [](const BLU& lhs, const BLU& rhs) {
        return -(lhs.max_d - lhs.min_d) < -(rhs.max_d - rhs.min_d);
    });

    for(auto i = 0; i < N; ++i) {
        auto p = A[i].b * A[i].u;
        auto q = A[i].b * A[i].l;
        auto t = X * A[i].u;
        if(i > 0) {
            p += S_AU.back();
            q += S_AL.back();
            t += S_BU.back();
        }
        S_AU.emplace_back(p);
        S_AL.emplace_back(q);
        S_BU.emplace_back(t);
    }

    long long l = -1;
    long long r = N * X;

    while(l+1 < r) {
        long long m = (l+r) / 2;
        if(check(m))
            r = m;
        else
            l = m;
    }

    cout << r << endl;
}

int main()
{
    cin.sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    solve();
}

