const int N = 1e5 + 7;
const int INF = 1e12 + 7;
struct Ex {
    int b, l, r, w;
};  
int n, x;
Ex a[N];
bool comp(Ex a, Ex b) {
    return a.w > b.w;
}
int pr[N], ps[N];
bool check(int i, int m) {
    int r = m % x;
    int d = m / x;
    int c;
    if (r <= a[i].b) c = a[i].l;
    else c = a[i].r;
    if (d <= i) {
        return pr[d] + c * r >= ps[i + 1] + (ps[d] - ps[i]) + c * a[i].b;
    }
    else {
        return (pr[d + 1] - a[i].w) + c * r >= ps[d + 1] + c * a[i].b;
    }   
}   
bool check_(int i, int m) {
    int r = x;
    int d = m;
    int c;
    if (r <= a[i].b) c = a[i].l;
    else c = a[i].r;
    if (d <= i) {
        return pr[d] + c * r >= ps[i + 1] + (ps[d] - ps[i]) + c * a[i].b;
    }
    else {
        return (pr[d + 1] - a[i].w) + c * r >= ps[d + 1] + c * a[i].b;
    }   
}   
signed main() {
    #ifdef HOME
    freopen("input.txt", "r", stdin);
    #else
    ios_base::sync_with_stdio(0); cin.tie(0);
    #endif
    cin >> n >> x;
    for (int i = 0; i < n; ++i) {
        cin >> a[i].b >> a[i].l >> a[i].r;
        a[i].w = a[i].r * (x - a[i].b);
    }
    sort(a, a + n, comp);
    int s = 0;
    for (int i = 0; i < n; ++i) s += a[i].b;
    if (s == 0) {
        cout << "0\n";
        exit(0);
    }   
    for (int i = n - 1; i >= 0; --i) {
        ps[i] = ps[i + 1] + a[i].l * a[i].b;
    }   
    for (int i = 0; i < n; ++i) {
        pr[i + 1] = pr[i] + a[i].w;
    }
    int ans = INF;
    /*
    for (int i = 0; i < n; ++i) {
        if (pr[i + 1] >= ps[i + 1]) ans = min(ans, (i + 1) * x);
    }
    */  
    for (int i = 0; i < n; ++i) {
        int l, r;

        l = -1; r = n;
        while (l < r - 1) {
            int m = (l + r) >> 1;
            if (check_(i, m)) r = m;
            else l = m;
        }   
        int t = r;

        l = 0; r = x;
        while (l < r - 1) {
            int m = (l + r) >> 1;
            if (check(i, t * x + m)) r = m;
            else l = m;
        }   
        ans = min(ans, t * x + r);
    }   
    cout << ans << '\n';
}

