struct Data {
	ll b, l, r;
	int used = 0;
};

const int MAXN = (int)1e5 + 7;
Data a[MAXN];
int n;
ll X;

struct SortFulls {
	bool operator()(const Data& lhs, const Data& rhs) const {
		ll left = (X - lhs.b) * lhs.r - (0 - lhs.b) * lhs.l;
		ll right = (X - rhs.b) * rhs.r - (0 - rhs.b) * rhs.l;
		return left > right;
	}
};

int check(ll days) {
	for(int i = 0; i < n; ++i) a[i].used = 0;
	ll fulls = days / X;
	ll rem  = days % X;
	DBG(fulls); DBG(rem);
	ll cur = 0;
	for(int i = 0; i < n; ++i) {
		cur += (0 - a[i].b) * a[i].l;
	}
	sort(a, a + n, SortFulls());
	int last = NIL;
	for(int i = 0; i < n; ++i) {
		ll change = (X - a[i].b) * a[i].r - (0 - a[i].b) * a[i].l;
		if(change > 0 && fulls > 0) {
			cur += change;
			--fulls;
			a[i].used = 1;
			last = i;
		}
	}
	ll mx = 0;
	for(int i = 0; i < n; ++i) {
		if(a[i].used) {
			ll change = (rem - a[i].b) * a[i].r - (0 - a[i].b) * a[i].l;
			change -= (X - a[i].b) * a[i].r - (0 - a[i].b) * a[i].l;
			if(last + 1 < n) {
				change += max(0LL, (X - a[last + 1].b) * a[last + 1].r - (0 - a[last + 1].b) * a[last + 1].l);
			}

			mx = max(mx, change);
		} else {
			ll change = (rem - a[i].b) * a[i].r - (0 - a[i].b) * a[i].l;
			mx = max(mx, change);
		}
	}

	for(int i = 0; i < n; ++i) {
		if(a[i].used) {
			ll change = (rem - a[i].b) * a[i].l - (0 - a[i].b) * a[i].l;
			change -= (X - a[i].b) * a[i].r - (0 - a[i].b) * a[i].l;
			if(last + 1 < n) {
				change += max(0LL, (X - a[last + 1].b) * a[last + 1].r - (0 - a[last + 1].b) * a[last + 1].l);
			}

			mx = max(mx, change);
		} else {
			ll change = (rem - a[i].b) * a[i].l - (0 - a[i].b) * a[i].l;
			mx = max(mx, change);
		}
	}

	cur += mx;
	return cur >= 0;
}

void solve() {
	cin >> n >> X;
	for(int i = 0; i < n; ++i) {
		cin >> a[i].b >> a[i].l >> a[i].r;
	}

	ll low = 0, high = X * n;
	if(check(low)) {
		cout << low << '\n';
	} else {
		while(high - low > 1) {
			ll mid = (low + high) / 2;
			if(check(mid)) {
				high = mid;
			} else {
				low = mid;
			}
		}
		cout << high << '\n';
	}
}

int main() {
	fast_io();
	solve();

	return 0;
}

