#define int long long

int x;

struct Test {
    int b;
    int l, r;

    int get_sum(int f) {
        assert(0 <= f && f <= x);
        return max((int)0, f - b) * r + min(f, b) * l;
    }

    Test() {}
};

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n >> x;
    vector<Test> a(n);
    int ndl = 0;
    for (auto &t : a) {
        cin >> t.b >> t.l >> t.r;
        ndl += t.b * t.l;
    }
    sort(a.rbegin(), a.rend(), [&](Test a, Test b) {
        return a.get_sum(x) < b.get_sum(x);
    });
    auto can = [&](int hv) {
        int fl = hv / x;
        int lf = hv % x;
        int ans = 0;
        if (lf) {
            int sf = 0;
            int sb = 0;
            for (int i = 0; i < fl; i++) {
                sf += a[i].get_sum(x);
            }
            for (int i = 0; i < fl + 1; i++) {
                sb += a[i].get_sum(x);
            }
            for (int tk = 0; tk < n; tk++) {
                if (tk >= fl) {
                    ans = max(ans, sf + a[tk].get_sum(lf));
                } else {
                    ans = max(ans, sb - a[tk].get_sum(x) + a[tk].get_sum(lf));
                }
            }
        } else {
            for (int i = 0; i < fl; i++) {
                ans += a[i].get_sum(x);
            }
        }
        return ans >= ndl;
    };
    int l = -1;
    int r = n * x;
    while (r - l > 1) {
        int m = (r + l) >> 1;
        if (can(m)) r = m;
        else l = m;
    }
    cout << r << endl;
}

