    i64 n, x;
    std::cin >> n >> x;
    enum { key, upper, lower, score };
    std::vector<std::tuple<i64, i64, i64, i64>> v;
    for (int i = 0; i < n; i++) {
        i64 b, l, u;
        std::cin >> b >> l >> u;
        v.emplace_back((x - b) * u + l * b, u, l, b);
    }

    std::sort(v.begin(), v.end(), std::greater<>());

    i64 ll = -1, rr = inf;
    while (rr - ll > 1) {
        auto k = (ll + rr) / 2;
        i64 d = 0;
        for (int i = 0; i < std::min(k / x, n); i++) {
            d += std::get<upper>(v[i]) * (x - std::get<score>(v[i]));
        }
        auto r = k % x;
        i64 t = -inf;
        int j = -1;
        for (i64 i = k / x; i < n; i++) {
            i64 co = std::get<score>(v[i]) < r ? std::get<upper>(v[i]) : std::get<lower>(v[i]);
            auto tmp = co * (r - std::get<score>(v[i])) + std::get<lower>(v[i]) * std::get<score>(v[i]);
            if (tmp > t) {
                t = tmp;
                j = i;
            }
            d -= std::get<lower>(v[i]) * std::get<score>(v[i]);
        }
        if (j >= 0) {
            d += t;
        }

        if (d >= 0) rr = k;
        else ll = k;
    }
    std::cout << rr << std::endl;

    return 0;
}

