const int MX=100100;
int n,i,ii,it,j,ww,le,ri,h,l[MX],u[MX],k[MX],e[MX],w[MX],was[MX];
long long m,s,ss,cur,cnt,best,b[MX],c[MX];
bool cmpc(int i, int j) { return c[i]>c[j]; }
bool cmpd(int i, int j) {
  int di=(w[i]==it)?u[i]:l[i];
  int dj=(w[j]==it)?u[j]:l[j];
  return di>dj;
}
int main() {
  scanf("%d%lld",&n,&m);
  for (i=0; i<n; i++) {
    scanf("%lld%d%d",&b[i],&l[i],&u[i]);
    k[i]=e[i]=i;
    s+=(cur=b[i]*l[i]);
    c[i]=(m-b[i])*u[i]+cur;
    best+=b[i];
  }
  if (s==0) { puts("0"); return 0; }
  sort(k,k+n,cmpc);
  le=0; ri=n; ss=s;
  while (true) {
    h=(le+ri)/2; ++it; s=ss;
    for (i=0; i<h; i++) w[k[i]]=it;
    sort(e,e+n,cmpd);
    for (cnt=ww=ii=0; ii<n; ii++) {
      i=k[ii];
      if (s-c[i]<=0) {
        cur=m;
        for (j=0; j<n; j++) if (was[j]!=it && s-c[j]<=0)
          cur=min(cur,(l[j]*b[j]>=s)?
                      (s+l[j]-1LL)/l[j]:
                      (b[j]+(s-l[j]*b[j]+u[j]-1LL)/u[j]));
        cnt+=cur;
        break;
      } else {
        was[i]=it;
        s-=c[i];
        cnt+=m;
      }
      if (w[i]==it) ww++;
    }
    best=min(best,cnt);
    if (le==ri) break;
    if (ww==h) ri=h; else le=h+1;
  }
  printf("%lld\n",best);
  return 0;
}

