		sum1[i]=sum1[i-1]+1LL*(k-a[i].x)*a[i].r;
	for (i=n;i;i--)
		sum2[i]=sum2[i+1]-1LL*a[i].x*a[i].l;
	for (mid=(l+r)>>1LL;l<=r;mid=(l+r)>>1LL)
