using namespace std;
typedef long long ll;
typedef pair<ll, ll> P;

ll N;
ll X;
ll b[100000], l[100000], u[100000];
ll base = 0;
P p[100000];

bool judge(ll c){
    ll m = c/X;
    ll score = 0;
    for(int i = 0; i < m; i++){
        ll s = p[i].first;
        int idx = p[i].second;
        score += s;
    }
    if(c%X != 0){
        ll rem = c%X;
        vector<P> v;
        for(int i = m; i < N; i++){
            int idx = p[i].second;
            v.push_back(P(u[idx]*(rem-b[idx]) + b[idx]*l[idx], idx));
            v.push_back(P(l[idx]*(rem-b[idx]) + b[idx]*l[idx], idx));
            //cout << (u[idx]*(rem-b[idx])) << endl;
        }
        sort(v.begin(), v.end(), greater<P>());
        score += v[0].first;

        //もうひとパターン
        ll score1 = 0, score2 = 0;
        vector<P> v1, v2;
        for(int i = 0; i <= m; i++){
            score1 += p[i].first;
            score2 += p[i].first;
        }
        for(int i = 0; i <= m; i++){
            int idx = p[i].second;
            v1.push_back(P(-u[idx]*X+u[idx]*rem, idx));
            v2.push_back(P(-u[idx]*X+l[idx]*rem+u[idx]*b[idx]-l[idx]*b[idx], idx));
        }
        sort(v1.begin(), v1.end(), greater<P>());
        score1 += v1[0].first;
        sort(v2.begin(), v2.end(), greater<P>());
        score2 += v2[0].first;
        score = max({score, score1, score2});
    }
    //cout << base+score << endl;
    if(base+score >= 0) return true;
    else return false;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> N >> X;
    ll b_sum = 0;
    for(int i = 0; i < N; i++){
        cin >> b[i] >> l[i] >> u[i];
        b_sum += b[i];
        base -= b[i]*l[i];
        p[i] = P(u[i]*X-u[i]*b[i]+l[i]*b[i], i);
    }
    if(b_sum == 0){
        cout << 0 << endl;
        return 0;
    }
    sort(p, p+N, greater<P>());
    // for(int i = 0; i < N; i++){
    //     cout << p[i].second << ' ' << p[i].first << endl;
    // }
    ll l = 0, r = N*X;
    while(r-l > 1){
        ll c = (l+r)/2;
        if(judge(c)) r = c;
        else l = c;
    }
    cout << r << endl;
}

