bool check(ll x){
  bool used[SIZE] = {};
  ll sum = 0;

  for(int i=0;i<x/X;i++){
    used[vec[i].second] = true;
    sum += vec[i].first;
  }

  for(int i=0;i<N;i++){
    sum -= B[i] * L[i];
  }

