    if (x >= B[i]) {
      y = max(y, (ll)B[i] * L[i] + (ll)U[i] * (x - B[i]));
    } else {
      y = max(y, (ll)x * L[i]);
    }
  }

  sum += y;

  return sum >= 0;
}

