int n, x;
int b[MAXN], l[MAXN], u[MAXN];
pll w[MAXN];
int used[MAXN];

bool check(ll m)
{
	for (int i = 1; i <= n; ++ i)
	{
		w[i] = pll((ll)(x-b[i])*u[i], i);
		used[i] = 0;
	}
	sort(w+1, w+n+1);
	reverse(w+1, w+n+1);
	ll c = m/x;
	ll val = 0;
	for (int i = 1; i <= c; ++ i)
	{
		val += w[i].X;
		used[w[i].Y] = 1;
	}

	ll best = -1000000000000000000LL;
	int choose = 0;

	for (int i = 1; i <= n; ++ i)
		if (!used[i])
		{
			ll cur;
			if (m%x-b[i] >= 0)
			{
				cur = (ll)(m%x-b[i])*u[i]-(ll)b[i]*l[i];
			}
			else
			{
				cur = (ll)(m%x)*l[i];
			}
			if (cur > best)
			{
				best = cur;
				choose = i;
			}
		}

	if (m%x-b[choose] >= 0)
	{
		val += (ll)(m%x-b[choose])*u[choose];
		used[choose] = 1;
	}
	else
	{
		val += best;
	}


	for (int i = 1; i <= n; ++ i)
		if (!used[i]) val -= (ll)l[i]*b[i];

	return val >= 0;
}

