	for (int i = 1; i <= n; ++ i)
	{
		scanf("%d%d%d", &b[i], &l[i], &u[i]);
	}


	ll L = 0, R = (ll)x*n;
	ll ans = R;
	while (L <= R)
	{
		ll m = (L+R)/2;
		if (check(m))
		{
			ans = m;
			R = m-1;
		}
		else
			L = m+1;
	}
	cout << ans << endl;

	return 0;
}

