ll getans(ll v)
{
	ll sum = 0;
	for (int i = 1;i <= n;i++)
		if (v >= X)
		{
			v -= X;
			sum += c[i].ans;
		}
		else
		{
			ll MAX = 0;
			int j = i;
			while (j <= n && c[j].ans == c[i].ans)
			{
				if (v >= c[j].b)
					MAX = max(MAX,c[j].l * c[j].b + c[j].r * (v - c[j].b));
				else
					MAX = max(MAX,c[j].l * v);
				j++;
			}
			sum += MAX;
			break;
		}
	return sum;
}

