const int N = 1 << 17;
LL n, x;

struct exam
{
	LL l, r, b;
	LL top;
	void read()
	{
		cin >> b >> l >> r;
		top = r * x - (r - l) * b;
	}
};

exam a[N];

int cmp(exam l, exam r)
{
	return l.top > r.top;
}

int skiky(exam e, LL treba)
{
	if (treba > e.top)
		return INF;

	if (treba <= e.l * e.b)
		return (treba + e.l - 1) / e.l;

	return (treba + e.b * (e.r - e.l) + e.r - 1) / e.r;
}

LL solve1(LL treba)
{
	LL ans = 0;

	int last_full = -1;
	for(int i = 0; i < n && treba > 0; ++i)
	{
		if (treba >= a[i].top)
		{
			last_full = i;
			treba -= a[i].top;
			ans += x;
			continue;
		}

		break;				
	}

	int tut = INF;

	FOR(i, last_full + 1, n)
		tut = min(tut, skiky(a[i], treba));

	if (last_full == n - 1)
		tut = 0;

	ans += tut;
	return ans;
}

int get(exam e, LL vykyn)
{
	assert(e.top >= vykyn);
	if (vykyn <= e.r * (x - e.b))
		return vykyn / e.r;

	return x - (e.r * (x - e.b) + e.l * e.b - vykyn + e.l - 1) / e.l;
}

LL solve2(LL treba)
{
	LL ans = 0;

	int last_full = -1;
	for(int i = 0; i < n && treba > 0; ++i)
	{
		if (treba >= a[i].top)
		{
			last_full = i;
			treba -= a[i].top;
			ans += x;
			continue;
		}

		break;				
	}

	if (last_full == n - 1)
		return ans;

	treba -= a[last_full + 1].top;
	ans += x;

	LL vykyn = -treba;

	int best = 0;
	FOR(i, 0, last_full)	
		best = max(best, get(a[i], vykyn));

	ans -= best;
	return ans;
}

