signed main() {
	int n, x;
	scanf("%lld%lld", &n, &x);
	int loseall = 0;
	int ans1 = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%lld%lld%lld", &ao[i].b, &ao[i].l, &ao[i].u);
		ao[i].canget = x * ao[i].u - (ao[i].u - ao[i].l)*ao[i].b;
		ao[i].lose = ao[i].l*ao[i].b;
