using namespace std;
typedef long long ll;

ll N, X;
ll b[100000], l[100000], u[100000];
ll up[100000], low[100000];
ll sum[100000], sum2[100000], numu[100000];

bool isOK(ll x){
	int index = x % X;
	int q = (x-index)/X;
	for(int i=0; i<N; i++){
		ll cnt = 0;
		if(index < b[i]){
			cnt = l[i] * (index - b[i]);
		}else{
			cnt = u[i] * (index - b[i]);
		}
		if(q == 0){
			cnt += sum2[0];
			cnt -= low[q];
		}else{
		if(numu[i] < q){
			cnt += sum[q];
			cnt += sum2[q+1];
			cnt -= up[numu[i]];
		}else{
			cnt += sum[q-1] + sum2[q];
			cnt -= low[numu[i]];
		}}
		if(cnt >= 0) return true;
	}
	return false;
}

ll search(void){
	ll ok = N * X, ng = -1;
	while(ok - ng > 1){
		ll mid = (ok + ng)/2;
		if(isOK(mid)){
			ok = mid;
		}else{
			ng = mid;
		}
	}
	return ok;
}

int main(){
	cin >> N >> X;
	vector<pair<ll, ll>> gap(N);
	for(int i=0; i<N; i++){
		cin >> b[i] >> l[i] >> u[i];
		up[i] = (X - b[i]) * u[i];
		low[i] = -b[i] * l[i];
		gap[i].first = up[i] - low[i];
		gap[i].second = i;
	}
	sort(gap.begin(), gap.end(), greater<pair<ll, ll>>() );
	for(int i=0; i<N; i++){
		int r = gap[i].second;
		numu[r] = i;
		if(i == 0){
			sum[i] = up[r];
		}else{
			sum[i] = sum[i-1] + up[r];
		}
	}
	for(int i=0; i<N; i++){
		int r = gap[N-1-i].second;
		if(i == 0){
			sum2[N-1-i] = low[r];
		}else{
			sum2[N-1-i] = sum2[N-i] + low[r];
		}
	}
	cout << search() << endl;
	return 0;
}

