    for (int i=0; i<N; i++)
        V.push_back(make_tuple(-(X*u[i]-b[i]*(u[i]-l[i])), b[i], l[i], u[i]));
    sort(V.begin(), V.end());
    for (int i=0; i<N; i++)
    {
        b[i] = get<1>(V[i]);
        l[i] = get<2>(V[i]);
        u[i] = get<3>(V[i]);
    }

    auto f = [&](long long x) -> bool
    {
        int c = (int)(x/X);
        long long A = 0;
        long long B = 0;
        for (int i=0; i<c; i++)
        {
            A += X*u[i];
            B += b[i]*u[i];
        }
        for (int i=c; i<N; i++)
            B += b[i]*l[i];

        for (int i=0; i<N; i++)
        {
            long long imp = x%X>b[i] ? u[i] : l[i];
            long long A2 = A + x%X*imp;
