LL read(){
  LL x=0,F=1;char c=getchar();
  while(c<'0'||c>'9'){if(c=='-')F=-1;c=getchar();}
  while(c>='0'&&c<='9'){x=(x<<3)+(x<<1)+c-'0';c=getchar();}
  return x*F;
}
int add(int a,int b){return (a+b>=MOD)?a+b-MOD:a+b;}
int dec(int a,int b){return (a-b<0)?a-b+MOD:a-b;}
int mul(LL a,int b){return a*b%MOD;}

int n;LL x;
LL D,ans,sum[MAXN+5];
struct node{
    LL b,l,r,h;
}p[MAXN+5];
bool cmp(node s1,node s2){
    return s1.h>s2.h;
}

LL calc(int i,LL pv){
    if(pv<=p[i].b)return pv*p[i].l;
    return p[i].b*p[i].l+(pv-p[i].b)*p[i].r;
}

bool check(LL v){
    LL res=0,rm=v%x,cnt=v/x;
    if(cnt>=n)return sum[n];
    for(int i=1;i<=n;i++){
        if(i<=cnt)res=max(res,calc(i,rm)+sum[cnt+1]-p[i].h);
        else res=max(res,calc(i,rm)+sum[cnt]);
    }
    return res>=D;
}

int main(){
    //freopen("homework.in","r",stdin);
    //freopen("homework.out","w",stdout);
    n=read(),x=read();
    for(int i=1;i<=n;i++){
        p[i]=(node){read(),read(),read(),0};
        p[i].h=p[i].b*p[i].l+(x-p[i].b)*p[i].r;
        D+=p[i].b*p[i].l;
    }
    sort(p+1,p+n+1,cmp);
    for(int i=1;i<=n;i++)sum[i]=sum[i-1]+p[i].h;
    LL l=0,r=INF;
    while(l<=r){
        LL mid=(l+r)>>1;
        if(check(mid))r=mid-1,ans=mid;
        else l=mid+1;
    }
    printf("%lld",ans);
}

