using namespace std;
int main() {
	int N; long long X;
	cin >> N >> X;
	vector<long long> B(N), L(N), R(N);
	for (int i = 0; i < N; ++i) {
		cin >> B[i] >> L[i] >> R[i];
	}
	long long ini = 0;
	vector<long long> sum(N);
	for (int i = 0; i < N; ++i) {
		sum[i] = B[i] * L[i] + (X - B[i]) * R[i];
		ini += B[i] * L[i];
	}
	vector<int> irank(N);
	for (int i = 0; i < N; ++i) {
		irank[i] = i;
	}
	sort(irank.begin(), irank.end(), [&](int i, int j) { return sum[i] > sum[j]; });
	vector<int> rank(N);
	for (int i = 0; i < N; ++i) rank[irank[i]] = i;
	vector<long long> s(N + 1);
	for (int i = 0; i < N; ++i) s[i + 1] = s[i] + sum[irank[i]];
	long long l = 0, r = N * X + 1;
	while (r - l > 1) {
		long long m = (l + r) >> 1;
		bool ok = false;
		for (int i = 0; i < N; ++i) {
			long long score = s[m / X + (rank[i] < m / X ? 1 : 0)];
			if (rank[i] < m / X) score -= sum[i];
			score += L[i] * min(B[i], m % X);
			score += R[i] * max(0LL, m % X - B[i]);
			if (score >= ini) ok = true;
		}
		if (ok) r = m;
		else l = m;
	}
	cout << r << endl;
	return 0;
}

