const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = (LL)INF * INF;

const int MAX = 1 << 17;

int n, x;
LL b[MAX], l[MAX], u[MAX];
int idxes[MAX];

bool cmp(int idx1, int idx2)
{
	return u[idx1] * (x - b[idx1]) + l[idx1] * b[idx1] >
		u[idx2] * (x - b[idx2]) + l[idx2] * b[idx2];
}

LL score(int idx, int a)
{
	return (a >= b[idx] ? u[idx] : l[idx]) * (a - b[idx]) + l[idx] * b[idx];
}

int main()
{
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	//freopen("In.txt", "r", stdin);
	cin >> n >> x;
	LL sum = 0;
	FOR(i, 0, n)
	{
		cin >> b[i] >> l[i] >> u[i];
		sum -= (LL)l[i] * b[i];
		idxes[i] = i;
	}
	sort(idxes, idxes + n, cmp);
	int ptr = 0;
	while(true)
	{
		LL cur = score(idxes[ptr], x);
		if(sum + cur < 0)
		{
			sum += cur;
			ptr++;
		}
		else
			break;
	}
	int best = INF;
	FOR(i, ptr, n)
	{
		int idx = idxes[ptr];
		int low = 0, high = x + 1;
		while(high - low > 1)
		{
			int mid = (low + high) >> 1;
			if(sum + score(idx, mid) >= 0)
				high = mid;
			else
				low = mid;
		}
		best = min(best, high);
	}
	assert(best <= x);
	cout << (LL)ptr * x + best;
	return 0;
}

