constexpr long long MOD = /** 1000000007;  //*/ 998244353;

void solve() {
  inl(N, X);
  vl b(N), l(N), u(N);
  in3(b, l, u);

  // p X点と0点の差
  vl p(N);
  rep(i, N) p[i] = (X - b[i]) * u[i] + b[i] * l[i];
  vi ord = mkord(N, [&](int x, int y) { return p[x] > p[y]; });
  vl rui(N + 1);
  rep(i, N) rui[i + 1] = rui[i] + p[ord[i]];

  ll thres = 0;
  rep(i,N) thres += b[i] * l[i];

  auto val = [&](int idx,ll tim){
    if(tim <= b[idx]) return l[idx] * tim;
    else return l[idx] * b[idx] + u[idx] * (tim - b[idx]);
  };
  auto f = [&](ll tim){
    ll full = tim / X;
    ll rest = tim % X;
    if(rest == 0) return rui[full];

    ll ret = -infLL;
    rep(i,N){
      ll cur;
      if(i < full){
        cur = rui[full + 1] - p[ord[i]] + val(ord[i], rest);
      }
      else{
        cur = rui[full] + val(ord[i], rest);
      }
      amax(ret, cur);
    }
    return ret;
  };

  ll ng = -1, ok = N * X;
  while(ng + 1 < ok){
    ll med = (ng + ok) / 2;
    (f(med) >= thres ? ok : ng) = med;
  }
  out(ok);

}

