bool check(int k)
{
   int q = k / X, p = k % X;

   LL sumx = 0;
   LL idx = 0;
   vector<bool> used(N, false);

   for (int i = 0; i < q; ++i) {
      sumx += x[ord[i]];
      used[ord[i]] = true;
   }

   LL y = sumb - sumx;

   if (y <= 0) {
      return true;
   }

   for (int i = 0; i < N; ++i) {
      LL tmpy = y;
      if (used[i]) {
         tmpy += x[i];
         tmpy -= x[ord[q]];
      }

      LL z = 0;
      if (p <= b[i]) {
         z = p * l[i];
      } else {
         z = b[i] * l[i] + (p - b[i]) * u[i];
      }

      if (z >= tmpy) {
         return true;
      }
   }

   return false;
}


int binary_search(int MIN, int MAX)
{
   int l = MIN-1, r = MAX;
   while (r - l > 1) {
      int m = (l + r) / 2;
      if (check(m)) {
         r = m;
      } else {
         l = m;
      }
   }
   return r;
}

