void solve() {
  inl(N, X);
  vl b(N), l(N), u(N);
  in3(b, l, u);
  vl p(N);
  rep(i, N) p[i] = (X - b[i]) * u[i] + b[i] * l[i];

  auto ord = mkord(N, [&](int x, int y) { return p[x] > p[y]; });
  vl rui(N + 1);
  rep(i, N) rui[i + 1] = rui[i] + p[ord[i]];

  ll ascore = 0;
  rep(i, N) ascore += b[i] * l[i];
  if(ascore == 0) die(0);

  int id = lb(rui, ascore);

  auto f = [&](int idx, ll val){
    // val点取るのに何時間要る？
    if(val <= b[idx] * l[idx]) return (val + l[idx] - 1) / l[idx];
    else return b[idx] + (val - b[idx] * l[idx] + u[idx] - 1) / u[idx];
  };

  // id - 1
  ll rest = ascore - rui[id - 1];
  // 
  ll rtime = infLL;
  for(ll i = id - 1, is = id - 1; i >= 0 ; i--){
    if(p[ord[i]] != p[ord[is]]) break;
    amin(rtime, f(ord[i], rest));
  }
  ll ans = X * (id - 1) + rtime;
  out(ans);

}

