            int gain = (mid - tests[i].b) * tests[i].l;
            if (gain >= left) {
                high = mid;
            } else {
                low = mid;
            }
            mid = (low + high) / 2;
        }
        ret = min(ret, mid);

        left += tests[i].b * tests[i].l;
    }

    REP(i, idx, N - 1) {
