struct hoge {
    ll h0; int num, l0;
};

bool comp(hoge &a, hoge &b){
    if(a.h0!=b.h0) return a.h0 > b.h0;
    if(a.l0!=b.l0) return a.l0 < b.l0;
    return a.num < b.num;
}

int N, X;
int b[100100], l[100100], u[100100];
hoge h[100100]; 
ll st;

bool ok(ll s){
    int n=0;
    ll now=st;
    while(s >= X){
        now += h[n].h0;
        s -=X;
        n++;
    }
    //s増えた時のmaxを求める
    ll smax=0;
    for(int i=n; i<N; i++){
        int j=h[i].num;
        if(b[j] <s ){
            smax =max(smax,(ll) b[j]*l[j]+ (ll) (s-b[j])*u[j] );
        }
        else{
            smax =max(smax, (ll) l[j]*s);
        }
    }
    if(now+smax >=0) return true;
    return false;
}

int main(){
    cin  >> N >> X;
    for(int i=0; i<N; i++){
        cin >> b[i] >> l[i] >> u[i];
