ll chk_mx(ll k) {
	ll mx=0;
	ll p=k/x,q=k%x;
	fo(i,1,n) {
		int z=ord[i];
		ll tmp=(q<=b[z])?q*l[z]:b[z]*l[z]+(q-b[z])*u[z];
