ll max_score(const vector<tuple<ll, ll, ll>> &blu, const ll x, const ll s) {
    const ll n = blu.size();
    vector<int> vst(n, 0);
    vector<ld> cospa_x(n);
    ll result = 0;
    REP(i, n) {
        ll b, l, u; tie(b, l, u) = blu[i];
        cospa_x[i] = (ld)u * (x - b) / x;
    }
    vector<ll> rank_cospa(n);
    iota(ALL_OF(rank_cospa), 0LL);
    sort(ALL_OF(rank_cospa), [&](ll i, ll j) {
        return cospa_x[i] > cospa_x[j];
    });
    vector<ll> scd(n);
    REP(t, n) {
        ll i = rank_cospa[t];
        ll b, l, u; tie(b, l, u) = blu[i];
        if (t < s/x) {
            result += u * (x - b);
        } else {
            result += l * -b;
        }
    }
    if (s/x < n) {
        ll maxterm = -LINF;
        ll w = s % x;
        ll ss = 0;
        ll rc = rank_cospa[s/x];
        ll rcb, rcl, rcu; tie(rcb, rcl, rcu) = blu[rc];
        ll rr = rcu * (x - rcb) - rcl * -rcb;
        REP(t, n) {
            ll i = rank_cospa[t];
            ll b, l, u; tie(b, l, u) = blu[i];
            if (t < s/x) {
                chmax(maxterm, u * (w - b) - u * (x - b) + rr);
                chmax(maxterm, l * (w - b) - u * (x - b) + rr);
            } else {
                chmax(maxterm, u * (w - b) - l*-b);
                chmax(maxterm, l * (w - b) - l*-b);
            }
        }
        result += maxterm;
    }
    // DUMP(make_tuple(s, result));
    return result;
}

