using namespace std;
typedef long long ll;

ll N, X;

struct Test {
    ll b, l, u;
    Test(int b = 0, int l = 0, int u = 0) : b(b), l(l), u(u) {}

    ll score() const {
        return u * (X - b) + l * b;
    }

    bool operator>(const Test &t) const {
        return score() > t.score();
    }
};

int main() {
    cin >> N >> X;

    vector<Test> tests(N);
    for (auto& t : tests) {
        cin >> t.b >> t.l >> t.u;
    }
    sort(tests.begin(), tests.end(), greater<Test>());

    ll ok = N * X, ng = -1;
    while (ok - ng > 1) {
        ll mid = (ok + ng) / 2;
        ll n = mid / X;
        ll R = mid % X;

        ll score = 0;
        for (int i = 0; i < N; ++i) {
            if (i < n) {
                score += tests[i].u * (X - tests[i].b);
            } else {
                score -= tests[i].l * tests[i].b;
            }
        }

        bool judge = (score >= 0);

        if (R > 0) {
            for (int r = 0; r < N; r++) {
                ll nscore = score;
                if (r < n) {
                    nscore -= tests[r].score();
                    nscore += tests[r].l * min(tests[r].b, R) + tests[r].u * max(0LL, R - tests[r].b);
                    nscore += tests[n].score();
                } else {
                    nscore += tests[r].l * min(tests[r].b, R) + tests[r].u * max(0LL, R - tests[r].b);
                }
                if (nscore >= 0) judge = true;
            }
        }

        (judge ? ok : ng) = mid;
    }

    cout << ok << endl;
    return 0;
}

