void solve(long long N, long long X, std::vector<long long> b, std::vector<long long> l, std::vector<long long> u){
  ll lf=-1,rt=accumulate(b.begin(),b.end(),0);
  vector<int> m100(b.size());
  iota(m100.begin(),m100.end(),0);
  sort(m100.begin(),m100.end(),[&](int x,int y){
    return (l[x]*b[x]+u[x]*(X-b[x]))>(l[y]*b[y]+u[y]*(X-b[y]));
  });
  ll bsum=0;
  REP(N){
    bsum+=b[i]*l[i];
  }
  while(lf+1<rt){
    ll mid=(lf+rt)/2;
    ll cmid=mid;
    ll diff=0;
    vector<int> points(N);
    fill(points.begin(),points.end(),0);
    REP(cmid/X){
      points[m100[i]]=X;
      diff+=l[m100[i]]*b[m100[i]]+u[m100[i]]*(X-b[m100[i]]);
    }
    ll cdiff=diff;
    if(cmid%X>0){
      REP(N){
        ll tmp=diff;
        if(points[i]!=0){
          tmp-=l[i]*b[i]+u[i]*(X-b[i]);
          tmp+=l[m100[cmid/X]]*b[m100[cmid/X]]+u[m100[cmid/X]]*(X-b[m100[cmid/X]]);
        }
        if(cmid%X<=b[i]){
          tmp+=cmid%X*l[i];
        }else{
          tmp+=(cmid%X-b[i])*u[i]+b[i]*l[i];
        }
        cdiff=max(cdiff,tmp);
      }
    }
    diff=max(diff,cdiff);
    diff-=bsum;
    if(diff>=0){
      rt=mid;
    }else{
      lf=mid;
    }
  }
  cout<<rt<<endl;
}

