pl ho[100000], ge[100000];
ll eg[100000];
bool saw[100000];
ll target;

bool solve(ll mid) {
    ll p = mid / x, q = mid % x;
    rep(i,n) {
        ho[i] = pl(x * u[i] - (u[i]-l[i]) * b[i], i);
        if (b[i] >= q) {
            ge[i] = pl(q * l[i], i);
        } else {
            ge[i] = pl(q * u[i] - (u[i]-l[i]) * b[i], i);
        }
    }
    sort(ho, ho+n, greater<pl>());
    sort(ge, ge+n, greater<pl>());
    rep(i,n) eg[ge[i].second] = i;
    ll val = 0, add = 0;
    memset(saw, 0, sizeof(saw));
    rep(i,p) {
        val += ho[i].first;
        saw[ho[i].second] = true;
    }
    rep(i,n) {
        if (saw[ge[i].second]) continue;
        val += ge[i].first;
        add = ge[i].first;
        break;
    }
    ll ret = val;
    rep(i,p) {
        ll tmp = val;
        tmp -= ho[i].first;
        tmp += ge[eg[ho[i].second]].first;
        tmp -= add;
        tmp += ho[p].first;
        ret = max(ret, tmp);
    }
    return (ret >= target);
}

