typedef long long LL;

LL n, x;
struct Node {
	LL b, l, r, c;
} a[100010];

inline bool cmp(Node a, Node b) {
	return a.c > b.c;
}

bool check(LL m)
{
	register LL ret1 = 0, ret2 = 0;
	for (register int i = 1; i <= n; ++i) {
		if (m >= x) {
			ret1 += x * a[i].r;
			ret2 += a[i].b * a[i].r;
			m -= x;
		} else if (m > a[i].b) {
			ret1 += m * a[i].r;
			ret2 += a[i].b * a[i].r;
			m = 0;
		} else {
			ret1 += m * a[i].l;
			ret2 += a[i].b * a[i].l;
			m = 0;
		}
	}
	if (ret1 >= ret2) return true;
	else return false;
}

int main()
{
	scanf("%lld %lld", &n, &x);
	for (register int i = 1; i <= n; ++i) {
		scanf("%lld %lld %lld", &a[i].b, &a[i].l, &a[i].r);
		a[i].c = (x - a[i].b) * a[i].r + a[i].b * a[i].l;
	}
	sort(a + 1, a + n + 1, cmp);
	register LL l = 0, r = n * x, mid;
	while (l <= r) {
		mid = (l + r) >> 1;
		if (check(mid) == true) r = mid - 1;
		else l = mid + 1;
	}
	printf("%lld\n", l);
