struct NODE{
  ll b,l,u;
  ll score;
};

ll n,x;
ll aoki;
bool isOK(ll mid, vector<NODE> &v){
  if(mid == 0) return false;
  ll full = mid/x;
  ll amari = mid % x;
  if(full == n) return true;
  // calc c_sum
  VLL c_sum(n,0);
  rep(i,n){
    if(i == 0) c_sum[i] = v[i].score;
    else c_sum[i] += v[i].score + c_sum[i-1];
  }

  //あまりの場所を1箇所決める{
  rep(i,n){
    ll total = -aoki;
    if(full <= i){
      //満点を取るやつ
      if(full > 0) total += c_sum[full-1];
      //あまりを取るやつ
      total += v[i].b * v[i].l;
      if(v[i].b < amari){
        total += v[i].u * (amari - v[i].b);
      }else{
        total += v[i].l * (amari - v[i].b);
      }
    }else{
      //満点を取るやつ
      if(full > 0){
        total += c_sum[full];
        total -= v[i].score;
      }
      total += v[i].b * v[i].l;
      if(v[i].b < amari){
        total += v[i].u * (amari - v[i].b);
      }else{
        total += v[i].l * (amari - v[i].b);
      }
    }
    if(total >= 0) return true;
  }
  return false;
}

bool cmp(NODE a, NODE b){
  return a.score < b.score;
}
int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> n >> x;
  vector<NODE> v(n);

  rep(i,n){
    cin >> v[i].b >> v[i].l >> v[i].u;
    v[i].score = v[i].l * v[i].b + v[i].u * (x - v[i].b);
    aoki += v[i].b * v[i].l;
  }
  if(aoki == 0){
    cout << 0 << endl;
    return 0;
  }
  sort(all(v),cmp);
  reverse(all(v));

  ll ok = x*n;
  ll ng = -1;
  while(ok - ng > 1){
    ll mid = (ok + ng)/2;
    if(isOK(mid,v)) ok = mid;
    else ng = mid;
  }
  cout << ok << endl;
  return 0;
}

