             // return (u[i] - l[i]) * b[i] - u[i] * x > (u[j] - l[j]) * b[j] - u[j] * x;
             return u[i] * (x - b[i]) - l[j] * b[j] < u[j] * (x - b[j]) - l[i] * b[i];
         });
    long long sum = 0, ans = 0;
    for (int i = n-1; i >= 0; i--) sum -= l[i] * b[i];
    // cerr << sum << endl;
    for (int i = n-1; i >= 0; i--) {
        int j = v[i];
