inline ll read()
{
	ll x=0; char c=getchar(),f=1;
	for(;c<'0'||'9'<c;c=getchar())if(c=='-')f=-1;
	for(;'0'<=c&&c<='9';c=getchar())x=x*10+c-'0';
	return x*f;
}
inline void write(ll x)
{
	static int buf[20],len; len=0;
	if(x<0)x=-x,putchar('-');
	for(;x;x/=10)buf[len++]=x%10;
	if(!len)putchar('0');
	else while(len)putchar(buf[--len]+'0');
}
inline void writeln(ll x){write(x); putchar('\n');}
inline void writesp(ll x){write(x); putchar(' ');}
struct Data{
	int id;
	ll val;
}a[maxn];
ll b[maxn],d[maxn],u[maxn];
int n,m;
bool cmp(Data a,Data b){return a.val>b.val;}
int main()
{
	n=read(); m=read();
	for(int i=1;i<=n;i++)
		b[i]=read(),d[i]=read(),u[i]=read();
	for(int i=1;i<=n;i++)
		a[i].id=i,a[i].val=(ll)u[i]*(m-b[i]);
	std::sort(a+1,a+n+1,cmp);
	ll l=0,r=n*m;
	while(l<r){
		ll mid=(l+r)>>1,sum=0;
		// printf("%lld %lld %lld ****\n",l,r,mid);
		int k=mid%m,cnt=mid/m;
		for(int i=1;i<=n;i++)
			if(i<=cnt)sum+=(ll)u[a[i].id]*(m-b[a[i].id]);
			else sum-=(ll)d[a[i].id]*b[a[i].id];
		// printf(": %lld\n",sum);
		ll mx=sum;
		if(k){
			for(int i=1;i<=n;i++){
				ll t=sum;
				if(i<=cnt)t+=(a[cnt+1].val+(ll)d[cnt+1]*b[cnt+1])-(a[i].val+(ll)d[a[i].id]*b[a[i].id]);
				else t+=(ll)d[a[i].id]*b[a[i].id];
				// printf("%d %lld\n",i,t);
				if(k>b[a[i].id])t+=(ll)u[a[i].id]*(k-b[a[i].id]);
				else t+=(ll)d[a[i].id]*(k-b[a[i].id]);
				// printf("%d %lld\n",i,t);
				mx=std::max(mx,t);
			}
		}
		if(mx>=0)r=mid;
		else l=mid+1;
	}
	writeln(l);
	return 0;
}

