		ssum[it] = ssum[it + 1] + L[i - 1] * b[i - 1];
	}
	int l = -1, r = x * n;
	while(r - l > 1) {
		int tm = (l + r) / 2;
		int m = tm;
		int div = m / x;
		int rem = m % x;
		bool ok = false;
		for(int it = 0; it < n; it++) {
			int i = p[it];
			int sum = (rem >= b[i] ? R[i] * (rem - b[i]) : L[i] * (rem - b[i]));
			sum += (it < div ? psum[div + 1] - R[i] * (x - b[i]) : psum[div]);
			sum -= (it < div ? ssum[div + 2] : ssum[div + 1] - L[i] * b[i]);
			ok |= sum >= 0;
		}
		if(ok) {
			r = tm;
		} else {
			l = tm;
		}
	}
	cout << r << endl;
	return 0;
}

