    for (int i = 0; i < N; i++)
        cin >> B[i] >> L[i] >> U[i];

    ll base = 0;
    for (int i = 0; i < N; i++)
        base -= B[i] * L[i];

    pair<ll, int> full[N];
    for (int i = 0; i < N; i++)
        full[i] = make_pair(L[i] * B[i] + (X - B[i]) * U[i], i);
    sort(full, full + N);
    reverse(full, full + N);

    ll cumsum[N];
    cumsum[0] = full[0].first;
    for (int i = 1; i < N; i++)
        cumsum[i] = cumsum[i - 1] + full[i].first;

    ll low = 0, high = X*N;
    while (low != high)
    {
        ll total = base;
        ll mid = (high + low) / 2;

        // if (mid >= X)
        //     total += cumsum[mid / X - 1];

        // ll best = 0;
        // ll resi = mid % X;
        ll best = base;
        for (int i = 0; i < N; i++)
        {
            ll num_full = mid / X;
            ll now = base;
            if (num_full == N)
                now += cumsum[N - 1];
            else if (i <= num_full - 1)
                now += cumsum[min(num_full, N - 1)] - full[i].first;
            else
                now += cumsum[num_full - 1];

            int k = full[i].second;
            ll left = mid % X;
            if (left > B[k])
                now += (left - B[k]) * U[k] + B[k] * L[k];
            else
                now += left * L[k];

            if (now > best)
                best = now;
