int main(){
    long long int n, x;
    cin >> n >> x;

    vector<pair<long long int, 
                pair<long long int, 
                     pair<long long int, long long int>>>> test(n);

    for(int i=0; i<n; i++){
        long long int b, l, u;
        cin >> b >> l >> u;

        test[i] = {(x-b) * u + b * l, {b, {l,u}}};
    }
    sort(test.begin(), test.end());
    reverse(test.begin(), test.end());

    // cumulative sum
    vector<long long int> csum1(n+1), csum2(n+1);
    for(long long int i=0; i<n; i++){
        long long int b = test[i].second.first;
        long long int l = test[i].second.second.first;
        long long int u = test[i].second.second.second;

        csum1[i+1] = csum1[i] + (x-b) * u;
        csum2[i+1] = csum2[i] + b * l;
    }

    long long int lower = -1, upper = x * n, mid;
    while(upper - lower > 1){
        mid = (upper + lower) / 2;
        long long int score = -1;

        for(long long int i=0; i<n; i++){
            long long int diff = 0;
            long long int a = mid % x;
            if(a == 0) diff = csum1[mid/x] + (csum2[n] - csum2[mid/x]);
            else{
                long long int b = test[i].second.first;
                long long int l = test[i].second.second.first;
                long long int u = test[i].second.second.second;
                if(a < b) diff = l * (a - b);
                if(a > b) diff = u * (a - b);

                if(i >  mid/x) diff += csum1[mid/x] - (csum2[n] - csum2[mid/x] - b * l);
                if(i <= mid/x) diff += (csum1[mid/x + 1] - (x-b) * u) - (csum2[n] - csum2[mid/x + 1]);
            }
            score = max(score, diff);
        }
        if(score <  0) lower = mid;
        if(score >= 0) upper = mid;
    }
    cout << upper << endl;
    return 0;
}

