struct Test {
    long long b, l, u;
    long long get(long long X) const { return u*(X-b) + l*b; }
};

int main(){
    int N; long long X;
    while(cin >> N >> X){
        vector<Test> vt(N);
        for(auto& t : vt) cin >> t.b >> t.l >> t.u;
        sort(vt.rbegin(), vt.rend(), [&](const Test& a, const Test&b){return a.get(X) < b.get(X);});
        long long L = -1, R = N*X;
        while(R-L > 1){
            long long mid = (L+R)/2;
            int last = mid/X;
            int rest = mid%X;
            long long win = 0, maxIdx = N, maxVal = 0;
            if(rest > 0){
                long long border = vt[last].get(X);
                for(int i=0;i<N;i++){
                    long long v = (rest <= vt[i].b ? vt[i].l * rest :  vt[i].l * vt[i].b + vt[i].u * (rest - vt[i].b)) ;
                    v -= max(0LL, vt[i].get(X) - border);
                    if(v > maxVal){ maxVal = v; maxIdx = i; }
                }
            }
            if(maxIdx != N){
                win += (rest <= vt[maxIdx].b ? vt[maxIdx].l : vt[maxIdx].u) * (rest - vt[maxIdx].b);
            }
            int fullCnt = 0;
            for(int i=0;i<N;i++){
                if(i == maxIdx) continue;
                if(fullCnt < last){
                    win += vt[i].get(X);
                    ++fullCnt;
                }
                win -= vt[i].b * vt[i].l;
            }
            if(win >= 0) R = mid;
            else L = mid;
        }
        cout << R << endl;
    }
}

