using namespace std;
typedef long long LL;

LL n,x;
struct E{
	LL b,l,u;
	E(){}
	E(LL _b,LL _l,LL _u){
		b=_b;
		l=_l;
		u=_u;
	}
	inline LL val()const{
		return b*l+u*(x-b);
	}
	inline LL de(LL rest)const{
		if(rest<=0)return 0;
		if(l*b>=rest)return (rest-1)/l+1;
		else return b+(rest-l*b-1)/u+1;
	}
	bool operator<(const E o)const{
		return val()>o.val();
	}
};

vector<E> es;

int main(){
	scanf("%lld%lld",&n,&x);
	LL delta=0;
	LL ans=0;
	LL de=x+1;
	for(int i=0;i<n;i++){
		LL b,l,u;
		scanf("%lld%lld%lld",&b,&l,&u);
		es.push_back(E(b,l,u));
		delta+=(LL)b*l;
	}
	sort(es.begin(),es.end());
	bool st=false;
	for(vector<E>::iterator it=es.begin();it!=es.end();++it){
		if(!st&&it->val()<=delta){
			ans+=x;
			delta-=it->val();
		}else{
			st=true;
			de=min(de,it->de(delta));
		}
	}
	ans+=de;
	printf("%lld\n",ans);
	return 0;
}

