bool ok(int h){
    int fe = h / x;
    fe = min(fe, n);
    int res = 0;
    int c = 0;
    for (int i = 1; i <= fe; i++){
        res += a[i].F.F;
    }
    h = h % x;
    for (int i = fe + 1; i <= n; i++){
        if (h <= a[i].F.S){
            c = max(c, a[i].S.F * h);
        } else{
            c = max(c, a[i].S.F * a[i].F.S + a[i].S.S * (h - a[i].F.S));;
        }
    }
    //cout << res << " -- " << c << endl;
    res += c;
    return (res >= s);
}
