const double pi = acos(-1.0);

vector<vector<ll>> es;
vector<bool> visited;
vector<ll> c;


T dfs(ll now, ll root, ll dist) {
	visited[now] = true;
	ll okstone = 0;
	ll ans = dist * c[now];
	ll top = 0;
	ll sum = 0;
	ll restiikanji = 0;
	ll topiikanji = 0;
	ll totalstone = c[now];
	for (auto &&e : es[now]) {
		if (!visited[e]) {
			ll one, ok, step, total;
			tie(one, ok, step, total) = dfs(e, root, dist + 1);
			totalstone += total;
			ans += step;
			okstone += ok;
			if (top < one) {
				sum += top;
				restiikanji = topiikanji;
				top = one;
				topiikanji = ok;
			}
			else {
				restiikanji += ok;
				sum += one;
			}
		}
	}
	ll iikanji;
	if (top <= sum + restiikanji) {
		iikanji = (sum + top) - ((sum + top) % 2);
	}
	else
		iikanji = sum * 2 + restiikanji;
	if (now == root) {
		if (sum + top - iikanji == 0)
			return T(ans, 0, 0, 0);
		else
			return T(INF, 0, 0, 0);
	}
	return T(sum + top - iikanji + totalstone, okstone + iikanji, ans, totalstone);
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll N, X;
	cin >> N >> X;
	vector<T> problem(N);
	ll now = 0;
	for (int i = 0;i < N;i++) {
		ll b, l, r;
		cin >> b >> l >> r;
		now -= l*b;
		ll value = r * (X - b) + l * b;
		problem[i] = T(value, b, l, r);
	}
	sort(problem.begin(), problem.end());
	ll ans = 0;
	for (int i = N-1;i >= 0;i--) {
		ll valuet, bt, lt, rt;
		tie(valuet, bt, lt, rt) = problem[i];
		if (now + valuet < 0) {
			ans += X;
			now += valuet;
			continue;
		}
		i++;
		ll saigo = INF;
		while (i > 0 && get<0>(problem[i - 1]) + now >= 0) {
			i--;
			ll value, b, l, r;
			tie(value, b, l, r) = problem[i];
			ll left = 0;
			ll right = X;
			while (right - left > 1) {
				ll m = (left + right) / 2;
				ll can;
				if (m > b)
					can = now + b * l + (m - b) * r;
				else
					can = now + l * m;
				if (can >= 0)
					right = m;
				else
					left = m;
			}
			saigo = min(saigo, right);
		}
		cout << ans + saigo << endl;
		break;
	}
	return 0;
}

