using namespace std;

#define pb push_back
#define mp make_pair
#define fi first
#define se second
#define INF (1LL << 55)
#define MOD (1000 * 1000 * 1000 + 7)
#define maxn 200111

typedef long long ll;
typedef long double ld;
typedef pair<ll, ll> pll;

ll n, x;
ll l[maxn], u[maxn], b[maxn];
vector<pll> value;

bool check(ll mid){
	ll num = mid / x;
	ll r = mid % x;
	ll aoki = 0;
	ll ans = 0;

	for(int i = 0; i < num; i++){
		int cur = value[i].se;
		ans += value[i].fi;
	}

	for(int i = 0; i < n; i++){
		int cur = value[i].se;
		aoki += b[cur] * l[cur];
	}

	if(ans >= aoki)
		return 1;


	for(int i = 0; i < n; i++){
		int cur = value[i].se;
		ll aoki_cur = aoki;
		ll ans_cur = ans;

		if(i < num){
			if(num < n){
				ans_cur -= value[i].fi;
				ans_cur += value[num].fi;

				if(r > b[cur]){
					ans_cur += b[cur] * l[cur];
					ans_cur += (r - b[cur]) * u[cur];
				}
				else
					ans_cur += r * l[cur];
			}
		}
		else{
			if(r > b[cur]){
				ans_cur += b[cur] * l[cur];
				ans_cur += (r - b[cur]) * u[cur];
			}
			else
				ans_cur += r * l[cur];
		}

		if(ans_cur >= aoki_cur)
			return 1;
	}

	return 0;
}


int main(){
	scanf("%lld%lld", &n, &x);
	for(int i = 0; i < n; i++){
		scanf("%lld%lld%lld", b + i, l + i, u + i);
		ll cur = b[i] * l[i] + (x - b[i]) * u[i];
		value.pb(mp(cur, i));
	}

	sort(value.begin(), value.end());
	reverse(value.begin(), value.end());

	ll left = 0, right = n * x, ans = -1;
	while(left <= right){
		ll mid = (left + right) / 2;
		if(check(mid)){
			ans = mid;
			right = mid - 1;
		}
		else
			left = mid + 1;
	} 

	printf("%lld\n", ans);	
	return 0;
}

