      }
      else {
         int mx = -mod * 10, pos = -1;
         for (int j = i; j <= n; j ++) {
            if ((h - a[j].b) * a[j].r > mx)
               mx = (h - a[j].b) * a[j].r, pos = j;
            if ((h - a[j].b) * a[j].l > mx)
               mx = (h - a[j].b) * a[j].l, pos = j;
         }
         ans += mx;
         for (int j = i; j <= n; j ++)
            if (pos != j)
               ans -= a[j].b * a[j].l;
         break;
      }
   }   
   return (ans >= 0);
}

