template <typename T,typename Func> T satisfy_mini(Func P,T l ,T r){
	l -= EPS<T>();
	while(r-l > EPS<T>()){
		T m=(l+r)/2;
		(P(m)?r:l)=m;
	}
	return r;
}

class Main {
public:
  void run() {
    int N; ll X; cin >> N >> X;
    vector<tuple<ll,ll,ll>> aos(N);
    cin >> aos;

    auto get_val =[&](tuple<ll,ll,ll> tup, ll t)->ll{
      ll b, l, u; tie(b,l,u) = (tup);
      return max(t - b, 0ll) * u + min(t, b) * l;
    };

    sort(ALL(aos),[&](auto p, auto q){
      return get_val(p,X) > get_val(q,X);
    });

    vector<ll> imos(N+1);
    for(int i:range(N)){
      imos[i+1] = imos[i] + get_val(aos[i],X);
    }

    ll iv = 0;
    for(int i:range(N)){
      ll b,l,u;tie(b,l,u) = aos[i];
      iv -= b*l;
    }

    ll res = satisfy_mini([&](ll t){
      ll Mv = 0;
      ll Xc = min<ll>(t/X,N-1);
      for(int i:range(N)){
        if(i < Xc){
          Mv = max(Mv,get_val(aos[i],t%X) + imos[Xc+1] - get_val(aos[i],X));
        }else{
          Mv = max(Mv,get_val(aos[i],t%X) + imos[Xc]);
        }
      }
      return Mv + iv >= 0;
    },0ll, N * X + 10);
    cout << res << endl;
  }
};

