bool check(ll m)
{
	for (int i = 1; i <= n; ++ i)
	{
		w[i] = pll((ll)(x-b[i])*u[i]+(ll)b[i]*l[i], i);
	}
	sort(w+1, w+n+1);
	reverse(w+1, w+n+1);
	for (int i = 1; i <= n; ++ i)
	{
		r[w[i].Y] = i;
	}

	int c = m/x;
	m %= x;

	ll earn = 0;
	for (int i = 1; i <= n; ++ i)
		earn -= (ll)b[i]*l[i];
	for (int i = 1; i <= c; ++ i)
		earn += w[i].X;

	for (int i = 1; i <= n; ++ i)
	{
		ll val = 0;
		if (m-b[i] > 0)
			val = (ll)(m-b[i])*u[i]+(ll)b[i]*l[i];
		else
			val = m*l[i];
		if (r[i] > c)
			val = val+earn;
		else
			val = val+earn-w[r[i]].X+w[c+1].X;
		if (val >= 0) return true;
	}
	return false;
}

