int N, X;

struct node
{
	int b;
	int l;
	int u;
	node(int v1, int v2, int v3) : b(v1), l(v2), u(v3) {}
	node() {}
	bool operator<(const node r) const {
		return u * (X - b) + l * b > r.u * (X - r.b) + r.l * r.b;
	}
	bool operator>(const node r) const {
		return r < *this;
	}
	bool operator>=(const node r) const {
		return !(*this < r);
	}
	bool operator<=(const node r) const {
		return !(r < *this);
	}
	bool operator==(const node r) const {
		return !(r < *this) && !(*this < r);
	}
	bool operator!=(const node r) const {
		return (r < *this) || (*this < r);
	}
	int calcma() {
		return u * (X - b);
	}
	int calc() {
		return u * (X - b) + l * b;
	}
};

