	while (x > 0 && A[x].calc() == A[x-1].calc()) x--;
	reps(i, x, N) {
		int t = hi - A[i].l * A[i].b + A[i].u * A[i].b;
		t = (t + A[i].u - 1) / A[i].u;
		if (t <= X) {
			chmin(mi, t);
		}
		t = hi;
		t = (t + A[i].l - 1) / A[i].l;
		if (t <= A[i].b) {
			chmin(mi, t);
		}
	}
	if (mi == 1e9) return false;
	res = min(res, mi + x * X);
	return true;
}

