int main()
{
    int N, X;
    cin >> N >> X;
    ll B[N], L[N], U[N];
    for (int i = 0; i < N; i++)
        cin >> B[i] >> L[i] >> U[i];

    ll base = 0;
    for (int i = 0; i < N; i++)
        base -= B[i] * L[i];

    pair<ll, int> full[N];
    for (int i = 0; i < N; i++)
        full[i] = make_pair(L[i] * B[i] + (X - B[i]) * U[i], i);
    sort(full, full + N);
    reverse(full, full + N);

    ll cumsum[N];
    cumsum[0] = full[0].first;
    for (int i = 1; i < N; i++)
        cumsum[i] = cumsum[i - 1] + full[i].first;

    ll low = 0, high = X*N;
    while (low != high)
    {
        ll total = base;
        ll mid = (high + low) / 2;

        if (mid >= X)
            total += cumsum[mid/X - 1];

        ll best = 0;
        ll resi = mid % X;
        for (int i = mid/X; i < N; i++)
        {
            int p = full[i].second;
            ll c;
            if (resi > B[p])
                c =  (resi - B[p]) * U[p] + B[p] * L[p];
            else
                c = resi * L[p];
            if (c > best)
                best = c;
        }
        total += best;
        cout << low << ' ' << mid << ' ' << high << ' ' << total << endl;

        if (total >= 0)
            high = mid;
        else
            low = mid + 1;
    }
    cout << low << endl;
   	return 0;
