int N, X;
ll B[MAX_N], L[MAX_N], R[MAX_N];
int idx[MAX_N];
int fid[MAX_N];
ll RS[MAX_N], LS[MAX_N];

bool ok(ll m) {
	int q = m / X;
	if(q == N) return true;
	int r = m % X;
	rep(i, 0, N) {
		ll tmp = 0;
		if(B[i] > r) tmp += L[i] * (r - B[i]);
		else tmp += R[i] * (r - B[i]);

		if(fid[i] < q) {
			tmp -= R[i] * (X - B[i]);
			tmp += RS[q + 1];
			tmp += LS[N] - LS[q + 1];
		}
		else {
			tmp -= -L[i] * B[i];
			tmp += RS[q];
			tmp += LS[N] - LS[q];
		}
		if(tmp >= 0) return true;
	}
	return false;
}

