        if (!used[i])
            continue;
        li C = -B;
        li y = C / r[i];
        if (y <= X - b[i])
            best = max(y, best);
        C = C - r[i] * (X - b[i]);
        y = C / l[i];
        if (y <= b[i] && C >= 0)
            best = max(y, best);        
    }
    li ans2 = ans - best;



    cout << min(ans1, ans2) << "\n";
}

