typedef long long LL;
#define FOR(i,a,b) for(LL i=(a);i<(b);++i)
#define REP(i,n) FOR(i,0,n)

using namespace std;
LL p = 1000000007ll;

int main(void)
{
  LL n,x;
  cin >> n >> x;
  vector<LL> b(n),l(n),u(n);
  REP(i,n) cin >> b[i] >> l[i] >> u[i];
  LL ao = 0;
  REP(i,n) ao += b[i] * l[i];
  vector<pair<LL,LL> > gain;
  REP(i,n) gain.emplace_back(x*u[i]-b[i]*(u[i]-l[i]), i);
  sort(gain.rbegin(),gain.rend());
  LL tmp = ao;
  LL subs = 0;
  while(tmp>gain[subs].first) {
    tmp -= gain[subs].first;
    ++subs;
  }
  LL lst = x;
  FOR(i, subs, n) {
    LL index = gain[i].second;
    lst = min(lst, (tmp-1)/l[index]+1);
    LL ttt = tmp - b[index]*l[index];
    if(ttt >= 0) lst = min(lst, (ttt-1)/u[index]+1+b[index]);
  }
  LL answer = subs*x + lst;
  tmp -= gain[subs].first;
  ++subs;
  LL amari = -tmp;
  LL amat = 0;
  REP(i, subs) {
    LL index = gain[i].second;
    amat = max(amat, amari/u[index]);
  }
  answer = min(answer,subs*x-amat);

  cout << answer << endl;
  return 0;
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define N 300010
ll n,x;
struct ver{
	ll b,l,r;
	ll allsum(){
		return b*l+(x-b)*r;
	}
	ll opp(){
		return b*l;
	}

	ver(ll b,ll l,ll r){
		this->b=b,this->l=l,this->r=r;
	}
};
bool operator<(const ver&a,const ver&b){
	ll vl=a.b*a.l+(x-a.b)*a.r;
	ll vr=b.b*b.l+(x-b.b)*b.r;
	return vl>vr;
};
vector<ver> v;
ll cs[N],oppsum;
bool judge(ll k,ll t){
	ll cost=k/x; if(cost>=n)return 1;
	ll res=min(k%x,v[t].b)*v[t].l+max(0LL,k%x-v[t].b)*v[t].r;
	res+=cs[min(t,cost)]-cs[0];
	res+=max(0LL,cs[cost+1]-cs[t+1]);
	return oppsum<=res;
}
bool solve(ll k){
	for(int i=0;i<n;i++){
		if(judge(k,i))return 1;
	}
	return 0;
}
int main(){
	cin>>n>>x;
	for(int i=0;i<n;i++){
		ll b,l,r; cin>>b>>l>>r;
		v.push_back(ver(b,l,r));
	}
	sort(v.begin(),v.end());
	oppsum=0;
	for(auto t:v)oppsum+=t.opp();
	cs[0]=0;
	for(int i=0;i<v.size();i++){
		cs[i+1]=cs[i]+v[i].allsum();
	}
	ll l=-1,r=1e17,m;
	while(l<r-1){
		m=(l+r)>>1;
		if(solve(m))r=m;
		else l=m;
	}
	cout<<r<<endl;
	return 0;	
}

