    v[i].score = v[i].l * v[i].b + v[i].u * (x - v[i].b);
    aoki += v[i].b * v[i].l;
  }

  sort(all(v),cmp);
  reverse(all(v));

  ll ok = x*n;
  ll ng = 0;
  while(ok - ng > 1){
    ll mid = (ok + ng)/2;
    if(isOK(mid,v)) ok = mid;
    else ng = mid;
  }
  cout << ok << endl;
  return 0;
}

