long long bscore[100001];
long long lbound[100001];
long long rbound[100001];
pair <long long, long long> totalearn[100001];

long long rem(int i, int am) {
	if (am <= bscore[i])
		return lbound[i] * am;
	else return lbound[i] * bscore[i] + (am - bscore[i]) * rbound[i];
}

int main() {
	int n;
	long long x;
	long long bwork = 0;
	cin >> n >> x;
	for (int i = 0; i < n; i++) {
		cin >> bscore[i] >> lbound[i] >> rbound[i];
		bwork += (bscore[i] * lbound[i]);
		totalearn[i] = make_pair(bscore[i] * lbound[i] + (x - bscore[i]) * rbound[i], i);
	}
	sort(totalearn, totalearn + n);
	for (int i = n - 2; i >= 0; i--)
		totalearn[i].first += totalearn[i + 1].first;
	long long bestans = n * x;
	for (int i = 0; i < n; i++) {
		long long curbest = n * x; 
		int s = 0;
		int e = x * n;
		while (s <= e) {
			int m = (s + e) / 2;
			long long totsum = totalearn[n - m / x].first;
			if (n - m / x <= i && e != x * n) {
				totsum -= (totalearn[i].first - totalearn[i + 1].first);
				totsum += (totalearn[n - m / x - 1].first - totalearn[n - m / x].first);
			}
			totsum += rem(totalearn[i].second, m % x);
			if (totsum >= bwork) {
				e = m - 1;
				curbest = m;
			}
			else s = m + 1;
		}
		bestans = min(bestans, curbest);
	}
	cout << bestans << '\n';
}

