    maxx += a[i].b;
    goal += a[i].b * a[i].l;
    a[i].sorce = a[i].b * a[i].l + (x - a[i].b) * a[i].u;
  }
  sort(a + 1, a + n + 1);
  ll l = 0, r = (long long)n * x;
  while (l < r) {
    ll mid = (l + r) / 2;
    if (check(mid) >= goal) r = mid;
    else l = mid + 1;
  }
  printf("%lld\n", l);
}

