int main() {
    int N, X;
    cin >> N >> X;
    struct Test {
        int b;
        int l;
        int u;
    };
    vector<Test> tests;
    for (int i = 0; i < N; i++) {
        int bi, li, ui;
        cin >> bi >> li >> ui;
        tests.push_back({bi, li, ui});
    }
    ll score_diff = 0;
    for (int i = 0; i < tests.size(); i++) {
        score_diff += tests[i].l * tests[i].b;
    }
    sort(tests.begin(), tests.end(), [X](const Test& lhs, const Test& rhs) -> bool {
        ll left = (X * lhs.u - 0 * lhs.l) - (lhs.b * lhs.u - lhs.b * lhs.l);
        ll right = (X * rhs.u - 0 * rhs.l) - (rhs.b * rhs.u - rhs.b * rhs.l);
        return left < right;
    });
    ll study_time = 0;
    while (true) {
        Test test = tests.back();
        ll score_inc = (X * test.u - 0 * test.l) - (test.b * test.u - test.b * test.l);
        if (score_inc >= score_diff) {
            break;
        }
        tests.pop_back();
        study_time += X;
        score_diff -= score_inc;
    }
    assert(score_diff >= 0);
    ll min_additional_time = numeric_limits<ll>::max();
    for (Test test : tests) {
        ll score_inc_0 = (test.b * test.l - 0 * test.l) - (test.b * test.l - test.b * test.l);
        if (score_inc_0 >= score_diff) {
            ll min_time = (ll)ceil((double)score_diff / (double)test.l);
            min_additional_time = min(min_additional_time, min_time);
        }
        ll score_inc_1 = (X * test.u - 0 * test.l) - (test.b * test.u - test.b * test.l);
        if (score_inc_1 >= score_diff) {
            ll min_time = (ll)ceil((double)(score_diff + (test.b * test.u - test.b * test.l)) / (double)test.u);
            min_additional_time = min(min_additional_time, min_time);
        }
    }
    study_time += min_additional_time;
    cout << study_time << endl;
    return 0;
}

