}

#include<bits/stdc++.h>
#define ll long long
using namespace std;

int main()
{
    ll N, X;
    cin >> N >> X;
    ll B[N], L[N], U[N];
    for (int i = 0; i < N; i++)
        cin >> B[i] >> L[i] >> U[i];

    ll base = 0;
    for (int i = 0; i < N; i++)
        base -= B[i] * L[i];

    pair<ll, int> full[N];
    for (int i = 0; i < N; i++)
        full[i] = make_pair(L[i] * B[i] + (X - B[i]) * U[i], i);
    sort(full, full + N);
    reverse(full, full + N);

    ll cumsum[N];
    cumsum[0] = full[0].first;
    for (int i = 1; i < N; i++)
        cumsum[i] = cumsum[i - 1] + full[i].first;

    ll low = 0, high = X*N;
    while (low != high)
    { 
        ll mid = (high + low) / 2;
        ll best = base;
        for (int i = 0; i < N; i++)
        {
            ll num_full = mid / X;
            ll now = base + cumsum[num_full - 1];
            if (num_full != N and i <= num_full - 1)
                now += full[num_full].first - full[i].first;

            int k = full[i].second;
            ll left = mid % X;
            if (left > B[k])
                now += (left - B[k]) * U[k] + B[k] * L[k];
            else
                now += left * L[k];

            if (now > best)
                best = now;
        }

        if (best >= 0)
            high = mid;
        else
