using namespace std;
struct data{int b, l, r;};
int K, n;
ll calc(data x) {return x.r * ((ll)K - x.b) + (ll)x.l * x.b;}
bool cmp(data x, data y) {return calc(x) > calc(y);}
data A[maxn];
ll pre[maxn];
bool check(ll x)
{
	ll mx = -INF, need = 0;
	int able = x / K;
	for (int i = 1; i <= n; i++)
		need -= (ll)A[i].l * A[i].b;
	for (int i = 1; i <= n; i++)
	{
		ll sum = need + x % K * A[i].l;
		if (i <= able) sum += pre[able + 1] - calc(A[i]);
		else sum += pre[able];
		mx = max(mx, sum);
	}
	return mx >= 0;
}
int main()
{
	scanf("%d%d", &n, &K);
	for (int i = 1; i <= n; i++)
		scanf("%d%d%d", &A[i].b, &A[i].l, &A[i].r);
	sort(A + 1, A + n + 1, cmp);
	for (int i = 1; i <= n; i++)
		pre[i] = pre[i - 1] + calc(A[i]);
	ll lef = 0, righ = (ll)n * K - 1, ch = (ll)n * K;
	while (lef <= righ)
	{
		ll mid = (lef + righ) / 2;
		if (check(mid)) {ch = mid; righ = mid - 1;}
		else lef = mid + 1;
	}
	printf("%lld\n", ch);
	return 0;
}

