  Vll b(n), l(n), u(n);
  rep(i, n) cin >> b[i] >> l[i] >> u[i];

  Vll d1(n);
  rep(i, n) d1[i] = u[i]*(X-b[i]) - l[i]*(0-b[i]);
  Vll d1s = d1;
  sort(all(d1s));
  reverse(all(d1s));


  auto f = [&] (ll K) {
    if (K < 0) return false;
    ll m = K / X;
    ll x = K % X;
    if (m >= n) return true;

    Vll d2(n);
    rep(i, n) d2[i] = ((x < b[i]) ? l[i] : u[i]) * (x-b[i]) - l[i]*(0-b[i]);

    ll g = 0;
    rep(i, n) g += l[i]*(0-b[i]);
    rep(i, m) g += d1s[i];

    ll cmax = -INFll;
    rep(i, n) {
      ll h = d2[i];
      if (d1[i] > d1s[m]) h += d1s[m] - d1[i];
      chmax(cmax, h);
    }
    return (g + cmax >= 0);
  };


  ll ok = ll(1e10) + 5;
  ll ng = -1;
  while (llabs(ok - ng) > 1) {
    ll mid = (ok + ng) / 2;
    if (f(mid)) ok = mid;
    else ng = mid;
  }
