}A[N];

int ls[N << 1], rs[N << 1], seg, num[N << 1], posl[N], posr[N], n, tot;
ll s[N << 1], size[N << 1];

inline void build(int &x, int L, int R)
{
    x = ++seg;
    s[x] = size[x] = 0;
    if(L == R)return ;
    int mid = (L + R) >> 1;
    build(ls[x], L, mid), build(rs[x], mid + 1, R);
}

inline void ins(int x, int L, int R, int y, int z)
{
    s[x] += (ll) num[y] * z, size[x] += z;
    if(L == R)return ;
    int mid = (L + R) >> 1;
    if(y <= mid)ins(ls[x], L, mid, y, z);
    else ins(rs[x], mid + 1, R, y, z);
}

inline ll get(int x, int L, int R, ll y)
{
    if(L == R)return (ll) num[L] * min(y, size[x]) ;
    int mid = (L + R) >> 1;
    if(size[rs[x]] >= y) return get(rs[x], mid + 1, R, y);
    else return s[rs[x]] + get(ls[x], L, mid, y - size[rs[x]]);
}

ll R, score;
int rt;

inline bool chk(ll x)
{
    ll res = 0;
    build(rt, 1, tot);
    for (rg i = 1 ; i <= n; i++)
        ins(rt, 1, tot, posl[A[i].id], A[i].b);
    res = get(rt, 1, tot, x);
    ll tmp = 0, pre = 0;
    for (rg i = 1; i <= n; i++)
    {
        ins(rt, 1, tot, posl[A[i].id], - A[i].b);
        ins(rt, 1, tot, posr[A[i].id], X - A[i].b);
        tmp += (ll) A[i].l * A[i].b, pre += A[i].b;
        res = max(res, tmp + get(rt, 1, tot, x - pre));
       // if(x == 115)cerr << pre << " " << x - pre << " " << get(rt, 1, tot, x - pre) << endl;
    }
    //if(x == 115)cout << res << " " << score << endl;
    return res >= score;
}

