    for (rg i = 1; i <= n; i++)
        read(A[i].b), read(A[i].l), read(A[i].r), A[i].id = i,
        num[++tot] = A[i].r, num[++tot] = A[i].l,
        R += A[i].b, score += (ll) A[i].b * A[i].l;
    sort(num + 1, num + tot + 1);
    tot = unique(num + 1, num + tot + 1) - num - 1;
    for (rg i = 1; i <= n; i++)
