        posl[i] = lower_bound(num + 1, num + tot + 1, A[i].l) - num;
    sort(A + 1, A + n + 1);
    ll L = 0, res = R;
    while(L <= R)
    {
        ll mid = (L + R) >> 1;
        if(chk(mid))res = mid, R = mid - 1;
        else L = mid + 1;
    }
   // chk(115);
