using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)


struct Problem {

	void Solve() {
		UL N, X; cin >> N >> X;
		LL leaved = 0;
		vector<pair<LL, pair<LL, LL>>> Test;
		vector<pair<LL, UL>> Best;
		rep(i, N) {
			LL b, l, u; cin >> b >> l >> u;
			leaved += b * l;
			Test.push_back({ b, {l, u} });
			Best.push_back({ b * l + (X - b) * u, i });
		}
		ULL ans = 0;
		sort(Best.begin(), Best.end());
		while (leaved > 0) {
			LL pt = Best.back().first;
			UL i = Best.back().second;
			if (leaved <= pt) break;
			leaved -= pt;
			Best.pop_back();
			ans += X;
		}
		ULL tmp = X;
		rep(i, Best.size()) {
			LL pt = Best.back().first;
			UL p = Best.back().second;
			if (leaved > pt) continue;
			ULL t = 0;
			LL b, l, u;
			b = Test[p].first;
			l = Test[p].second.first;
			u = Test[p].second.second;
			if (leaved == 0) {}
			else if (b * l >= leaved) {
				t = (leaved + l - 1) / l;
			}
			else {
				LL nleaved = leaved - b * l;
				t += b;
				t += (nleaved + u - 1) / u;
			}
			tmp = min(tmp, t);
		}
		ans += tmp;
		cout << ans << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

