        ll b, l, u;
        cin >> b >> l >> u;
        p[i] = P_(P(X*u-b*u, b*l), P(u, l));
        sum_l += b*l;
    }

    sort(p, p+N, greater<P_>());
    ll ans = 0;
    ll sum_r = 0;
    int idx;
    for(int i = 0; i < N; i++){
        sum_l -= p[i].first.second;
        sum_r += p[i].first.first;
        if(sum_r >= sum_l){
            idx = i;
            sum_l += p[i].first.second;
            sum_r -= p[i].first.first;
            break;
        }
        ans += X;
