    ll l_max = 0;
    for(int i = idx; i < N; i++){
        l_max = max(l_max, p[i].second.second);
    }
    ll ans_tmp = -1;
    for(int i = idx; i < N; i++){
        sum_l -= p[i].first.second;
        sum_r += p[i].first.first;
        ll u = p[i].second.second;
        if(sum_r >= sum_l){
            if(ans_tmp == -1) ans_tmp = ans+X-(sum_r - sum_l)/u;
