  }

  sort(all(v),cmp);
  reverse(all(v));

  ll ok = x*n;
  ll ng = -1;
  while(ok - ng > 1){
    ll mid = (ok + ng)/2;
    if(isOK(mid,v)) ok = mid;
    else ng = mid;
  }
