long long pre[maxn] = {0}, sum[maxn] = {0};

int mult(int who, int k){
    if(k >= b[who]){return u[who];}
    return l[who];
}

pair <long long, int> a[maxn];

bool check(int n, int m, int k){
    for(int i = 1; i <= m; i++){
        int p = a[i].second;
        //int p = G[i - 1].second;
        int multi = mult(p, k);
        long long a1 = sum[m + 1] - sum[i] + sum[i - 1] + (long long)(k - b[p]) * multi;
        long long a2 = pre[n] - pre[m + 1];
        if(a1 >= a2){
            return true;
        }
    }
    for(int i = m + 1; i <= n; i++){
        int p = a[i].second;
        //int p = G[i - 1].second;
        int multi = mult(p, k);
        long long a1 = sum[m] + (long long)(k - b[p]) * multi;
        long long a2 = pre[n] - pre[i] + pre[i - 1] - pre[m];
        if(a1 >= a2){return true;}
    }
    return false;
}

int main(){
    int n, x;
    scanf("%d%d", &n, &x);
    for(int i = 1; i <= n; i++){
        scanf("%d%d%d", &b[i], &l[i], &u[i]);
        long long anw = (long long)b[i] * l[i] + (long long)(x - b[i]) * u[i];
        a[i] = make_pair(anw, i);
    }
    sort(a + 1, a + 1 + n);
    reverse(a + 1, a + 1 + n);
    for(int i = 1; i <= n; i++){
        int j = a[i].second;
        pre[i] = pre[i - 1] + (long long)b[j] * l[j];
        sum[i] = sum[i - 1] + (long long)(x - b[j]) * u[j];
    }
    long long L1 = 0, R = (long long)n * x;
    while(L1 < R){
        long long mid = (L1 + R) >> 1;
        if(check(n, mid / x, mid % x)){
            R = mid;
        }
        else{
            L1 = mid + 1;
