ll power(ll x, ll n, ll mod) {
  ll res = 1;
  x %= mod;
  while (n) {
    if (n & 1)
      res = (res * x) % mod;
    x = (x * x) % mod;
    n >>= 1;
  }
  return res;
}

struct node {
  ll b, l, u;
};
ll x;
bool comp(node &a, node &b) { return (a.u * (x - a.b)) > (b.u * (x - b.b)); }
int32_t main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);

  ll n;
  cin >> n >> x;

  node arr[n + 5];
  for (ll i = 1; i <= n; i++) {
    cin >> arr[i].b >> arr[i].l >> arr[i].u;
  }

  sort(arr + 1, arr + n + 1, comp);

  ll low = 0, high = n;

  ll res = inf;
  while (low <= high) {
    ll mid = (low + high) >> 1;
    ll indx = mid;

    ll firstAns = 0;
    ll c[n + 5];

    ll secondAns = 0;
    for (ll i = 1; i <= indx; i++) {
      c[i] = arr[i].u;
      firstAns += x * c[i];
      secondAns += arr[i].b * c[i];
    }

    ll temp = firstAns;
    ll low1 = 0, high1 = x;
    while (low1 <= high1) {

      firstAns = temp;
      ll mid1 = (low1 + high1) >> 1;
      ll rem = mid1;
      ll curr = 0;
      if (indx != n) {
        for (ll i = indx + 1; i <= n; i++) {
          c[i] = arr[i].l;
          curr -= arr[i].l * arr[i].b;
        }

        pair<ll, ll> which;
        ll max1 = -inf;
        for (ll i = indx + 1; i <= n; i++) {
          ll currVal = curr + rem * arr[i].l;
          if (currVal > max1) {
            max1 = currVal;
            which = {i, 0};
          }
          currVal =
              curr + arr[i].l * arr[i].b - arr[i].u * arr[i].b + rem * arr[i].u;
          if (currVal > max1) {
            max1 = currVal;
            which = {i, 1};
          }
        }

        if (which.second == 0) {
          c[which.first] = arr[which.first].l;
        } else
          c[which.first] = arr[which.first].u;

        firstAns += c[which.first] * rem;
      }
      ll secondAns = 0;
      for (ll i = 1; i <= n; i++) {
        secondAns += c[i] * arr[i].b;
      }
      // cout << firstAns << " " << secondAns << en;
      if (firstAns < secondAns)
        low1 = mid1 + 1;
      else
        high1 = mid1 - 1;
    }

    if (low1 > x) {
      low = mid + 1;
    } else {
      res = min(res, mid * x + low1);
      high = mid - 1;
    }
  }

  cout << res << en;
  return 0;
}

