#include <bits/stdc++.h>
using namespace std;
using ll = long long;

bool C(ll t, vector<ll>b, vector<ll>l, vector<ll>u, ll N, ll X){
    // 重要度はl_iかu_iの2択
    // 点数は端数が1個で他は満点か0点
    // 満点を取るのに必要な時間は一定
    vector<pair<ll,int>> effect(N);
    for (int i = 0; i < N; ++i) {
        ll temp = ((X - b[i]) * u[i]) + (b[i] * l[i]);
        effect[i] = make_pair(temp, i);
    }
    sort(effect.begin(), effect.end(), greater<pair<ll,int>>());

    vector<int> flag(N,0); // 満点を取ったら1にする
    ll score = 0;
    for (int i = 0; i < N; ++i) {
        score -= b[i] * l[i];
    }

    // 上から満点の個数だけ満点と仮定
    int perfect = t / X;
    for (int i = 0; i < perfect; ++i) {
        score += effect[i].first;
        flag[effect[i].second] = 1;
    }
    t %= X;
    if(score >= 0) return true;
    if(t == 0) return false;

    // まずは今0点と仮定した中から端数を選んで探索
    for (int i = 0; i < N; ++i) {
        if(flag[i] == 0){
            ll temp; // 増える効果
            if(t <= b[i]) {
                temp = t * l[i];
            } else {
                temp = ((t - b[i]) * u[i]) + (b[i] * l[i]);
            }
            if(score + temp >= 0) return true;
        }
    }

    // 無理なら effect[perfect].second を満点にして満点→端数をどれにするかで探索
    score += effect[perfect].first;
    for (int i = 0; i < N; ++i) {
        if(flag[i] == 1){
            ll temp; // 減る効果
            if(t <= b[i]) {
                temp = ((X - b[i]) * u[i]) + ((b[i] - t) * l[i]);
            } else {
                temp = (X - t) * u[i];
            }
            if(score - temp >= 0) return true;
        }
    }

    return false;
}

int main() {
    ll N, X;
    cin >> N >> X;
    vector<ll>b(N);
    vector<ll>l(N);
    vector<ll>u(N);
    for (int i = 0; i < N; ++i) {
      cin >> b[i] >> l[i] >> u[i];
    }

    // llで二分探索して最小値
    ll lb=-1, ub = N * X + 1;
    while( ub-lb > 1 ){
        ll mid = (lb+ub)/2;
        if(C(mid, b, l, u, N, X)){
            ub = mid;
        }else{
            lb = mid;
        }
    }
    cout << ub;
    return 0;
}

