  line(ll _a, ll _b, int _idx) {
    a = _a, b = _b, idx = _idx;
  }
  ll eval(ll x) {
    return a * x + b;
  }
  bool operator<( line &rhs) {
    if(eval(x) == rhs.eval(x))
      return a > rhs.a;
    return eval(x) < rhs.eval(x);
  }
