bool check(llint m)
{
	llint sum = 0;
	for(int i = 1; i <= n; i++) sum -= l[i]*b[i];
	for(int i = 1; i <= n; i++) used[i] = false;

	llint full = m/x, rem = m%x;
	if(m/x >= n) return true;

	//cout << sum << endl;
	//cout << full << endl;

	llint fsum = 0;
	for(int i = 0; i < full; i++){
		used[vec[i].second] = true;
		fsum += vec[i].first.first;
	}
	llint ret = 0;
	for(int i = 1; i <= n; i++){
		llint tmp = fsum + min(rem, b[i]) * l[i];
		if(b[i] < rem) tmp += (rem-b[i]) * u[i];
		if(used[i]){
			tmp -= l[i]*b[i]+u[i]*(x-b[i]);
			tmp += vec[full].first.first;
		}
		ret = max(ret, tmp);
	}
	return ret+sum >= 0;
}

