const int N = 1e5 + 5;
int n, x, b[N], l[N], r[N];

bool check (int lim) {
    int dist = 0;
    for (int i = 0; i < n; ++i) dist += 1LL * l[i] * b[i];
    vector<bool> used(n, 0);
    vector< pair<int, int> > vec;
    for (int i = 0; i < n; ++i) vec.pb( { 1LL * (r[i] - l[i]) * b[i] - 1LL * x * r[i], i } );
    sort(vec.begin(), vec.end() );
    int lst = lim / x;
    for (int i = 0; i < min(n, lst); ++i) {
        used[ vec[i].se ] = 1;
        dist += vec[i].fi;
    }
    vec.clear();
    lim %= x;
    for (int i = 0; i < n; ++i) if (!used[i]) {
        if (lim >= b[i]) vec.pb( { 1LL * (r[i] - l[i]) * b[i] - 1LL * lim * r[i], i } );
        else vec.pb( { - 1LL * lim * l[i], i } );
    }
    sort(vec.begin(), vec.end() );
    if (vec.size() ) dist += vec[0].fi;
    return dist <= 0;
}

