int N, X;

signed main(){

  cin>>N>>X;

  int bS = 0;

  priority_queue<P,vector<P>,greater<P> > Q;

  for(int i=0;i<N;i++){

    int b, l, u;
    cin>>b>>l>>u;

    bS += b * l;

    Q.push(P( -((X-b)*u), b, l, u ));

  }

  int aS = 0;
  int ans = 0;

  while( !Q.empty() ){

    int A, b, l, u;

    tie( A, b, l, u ) = Q.top();

    A *= -1;
    //cout<<A<<' '<<b<<' '<<l<<' '<<u<<endl;
    int naS = aS + X * u;

    int nbS = bS - b * l + b * u;

    if( nbS <= naS ) break;

    aS = naS;
    bS = nbS;
    ans += X;

    Q.pop();

  }  
  //cout<<aS<<' '<<ans<<endl;
  if( !Q.empty() ){

    int minplus = X;

    while( !Q.empty() ){

      int A, b, l, u;

      tie( A, b, l, u ) = Q.top(); Q.pop();

      A *= -1;

      int naS = aS + X * u;

      int nbS = bS - b * l + b * u;

      int naS2 = aS + b * l;

      if( naS2 < nbS && naS < nbS ) continue;

      int L = 0, R = b + 1;

      while( L < R ){

	int M = ( L + R ) / 2;

	naS = aS + M * l;
	nbS = bS;

	if( naS < nbS ) L = M + 1;
	else R = M;

      }

      if( L != b + 1 ) minplus = min( minplus, L );

      L = b + 1, R = X + 1;

      while( L < R ){

	int M = ( L + R ) / 2;

	naS = aS + M * u;
	nbS = bS - b * l + b * u;

	if( naS < nbS ) L = M + 1;
	else R = M;

      }
      assert( L != X + 1 );
      minplus = min( minplus, L );

    }

    ans += minplus;

  }

  cout<<ans<<endl;

  return 0;
}

