	if(m>=n)return true;
	ll S=0;
	rep(i,m)S+=s[i].first;
	ll r=t%x;
	ll Max=0;
	rep(i,n){
		ll d=(id[i]<m?S-s[id[i]].first+s[m].first:S);
		if(r<=b[i])d+=r*l[i];
		else d+=b[i]*l[i]+(r-b[i])*u[i];
		Max=max(Max,d);
	}
	return sum+Max>=0;
}

int main(){
	cin>>n>>x;
	rep(i,n){
		scanf("%lld%lld%lld",&b[i],&l[i],&u[i]);
		sum-=b[i]*l[i];
		s[i]=P(b[i]*l[i]+(x-b[i])*u[i],i);
		//cout<<s[i].first<<" "<<s[i].second<<endl;
	}
	sort(s,s+n);reverse(s,s+n);
		//rep(i,n){ cout<<s[i].first<<" "<<s[i].second<<endl;}
	rep(i,n)id[s[i].second]=i;
	ll ok=n*x,ng=0;
	while(ok>ng){
		ll md=(ok+ng)/2;
		if(C(md))ok=md;
		else ng=md+1;
	}
	cout<<ok<<endl;
}

