using namespace std;

#define int int_fast64_t

struct exam {
  int l, u, b;
  int cost(int score) const {
    int c = score >= b ? u : l;
    return c*(score - b);
  }
  int score_for_mincost(int mingain, int x) const {
    const int cost0 = cost(0);
    auto gain = [&](int x) { return cost(x) - cost0; };
    assert(gain(0) < mingain && gain(x) >= mingain);

    // invariant: gain(l)<mingain, gain(r)>=mingain
    int l=0, r=x;
    while (r-l > 1) {
      int m = (l+r)/2;
      if (gain(m) < mingain)
        l = m;
      else
        r = m;
    }
    assert(gain(l)  < mingain);
    assert(gain(r) >= mingain);
    return r;
  }
};

signed main() {
  ios_base::sync_with_stdio(false), cin.tie(nullptr);

  int n, x; cin >> n >> x;
  vector<exam> exams;
  for (int i = 0; i < n; ++i) {
    exam e;
    cin >> e.b >> e.l >> e.u;
    exams.push_back(e);
  }
  int score=0;
  for (auto& e : exams) score += e.cost(0);

  auto key = [&](exam const& e) { return make_pair(e.cost(x) - e.cost(0), e.l); };
  sort(exams.begin(), exams.end(), [&](exam const& a, exam const& b) { return key(a) > key(b); });
  int ans=0;

  const int INF = numeric_limits<int>::max();
  int best=INF;

  bool partial_mode=false;
  for (auto const& e : exams) {
    if (score == 0) { best = min(best, ans); break; }
    assert(score < 0);
    const int cost0 = e.cost(0);
    auto gain = [&](int x) { return e.cost(x) - cost0; };

    if (!partial_mode && score + gain(x) <= 0) {
      // take it fully
      score += gain(x);
      ans += x;
      continue;
    }
    partial_mode = true;
    assert(score < 0);
    if (gain(x) >= -score)
      best = min(best, ans + e.score_for_mincost(-score, x));
  }
  if (score == 0) { best = min(best, ans); }
  assert(best < INF);
  cout << best << '\n';
}

