    memset(used, 0, sizeof used);
    while (1) {
        int id = q.begin()->second;
        li val = (r[id] * X - r[id] * b[id] + l[id] * b[id]);
        if (val >= B)
            break;
        // cout << val << " " << id << endl;
        q.erase(q.begin());
        used[id] = 1;
        B -= val;
        ans += X;
    }
    li best = 1e9;
    for (int i = 0; i < n; ++i) {
        if (used[i])
            continue;
        li y = B / l[i] + (B % l[i] > 0);
        if (y <= b[i]) {
            best = min(y, best);
            continue;
        }

        li C = B - l[i] * b[i];
        y = C / r[i] + (C % r[i] > 0) + b[i];
        if (y <= X)
            best = min(y, best);
    }
    li ans1 = ans + best;

    int id = q.begin()->second;
    li val = (r[id] * X - r[id] * b[id] + l[id] * b[id]);
    q.erase(q.begin());
    used[id] = 1;
    B -= val;
    ans += X;

    // cout << B << endl;
    best = -1e9;
    for (int i = 0; i < n; ++i) {
        if (!used[i])
            continue;
        li C = -B;
        li y = C / r[i];
        if (y <= X - b[i])
            best = max(y, best);
        C = C - r[i] * (X - b[i]);
        y = C / l[i];
        if (y <= b[i] && C >= 0)
            best = max(y, best);        
    }
    li ans2 = ans - best;



    cout << min(ans1, ans2) << "\n";
}

