	long long sum=0,na=a;
	for (int i=0;i<idx;i++)
	{
		sum+=1LL*u[perm[i]]*x;
		na+=1LL*(u[perm[i]]-l[perm[i]])*b[perm[i]];
	}
	if (sum>=na)
	return 1;
	for (int i=idx;i<n;i++)
	{
		if (sum+1LL*l[perm[i]]*(h%x)>=na || sum+1LL*u[perm[i]]*(h%x)>=na+1LL*(u[perm[i]]-l[perm[i]])*b[perm[i]])
		return 1;
	}
	sum+=1LL*u[perm[idx]]*x;
	na+=1LL*(u[perm[idx]]-l[perm[idx]])*b[perm[idx]];
	for (int i=0;i<idx;i++)
	{
		if (sum+1LL*u[perm[i]]*(h%x-x)>=na || sum-1LL*u[perm[i]]*x+1LL*l[perm[i]]*(h%x)>=na-1LL*(u[perm[i]]-l[perm[i]])*b[perm[i]])
