#include<bits/stdc++.h>

using namespace std;

#define int long long
#define pb push_back
#define fi first
#define se second

const int N = 1e5 + 5;
int n, x, b[N], l[N], r[N];

bool check (int lim) {
    int dist = 0;
    for (int i = 0; i < n; ++i) dist += 1LL * l[i] * b[i];
    vector<bool> used(n, 0);
    vector< pair<int, int> > vec;
    for (int i = 0; i < n; ++i) vec.pb( { 1LL * (r[i] - l[i]) * b[i] - 1LL * x * r[i], i } );
    sort(vec.begin(), vec.end() );
    int lst = lim / x;
    for (int i = 0; i < min(n, lst); ++i) {
        used[ vec[i].se ] = 1;
        dist += vec[i].fi;
    }
    vec.clear();
    lim %= x;
    for (int i = 0; i < n; ++i) if (!used[i]) {
        if (lim > b[i]) vec.pb( { 1LL * (r[i] - l[i]) * b[i] - 1LL * lim * r[i], i } );
        else vec.pb( { - 1LL * lim * l[i], i } );
    }
    sort(vec.begin(), vec.end() );
    if (vec.size() ) dist += vec[0].fi;
    return dist <= 0;
}

int32_t main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    cin >> n >> x;
    for (int i = 0; i < n; ++i) cin >> b[i] >> l[i] >> r[i];

    int L = 0, R = 1LL * N * N;
    while (L < R) {
        int mid = (L + R) >> 1;
        if (check(mid) ) R = mid;
        else L = mid + 1;
    }

    cout << L;

    return 0;
}

