void add_mod(ll& a, ll b){
	a = (a<MOD)?a:(a-MOD);
	b = (b<MOD)?b:(b-MOD);
	a += b;
	a = (a<MOD)?a:(a-MOD);
}

struct subject{
	ll b,l,u,value;
	bool operator<(const subject &rhs){
		return value > rhs.value;
	}
};

int n;
