vector<subject> v;

bool judge(ll p){
	int i;
	ll q,r,tmp=df,d=-INFLL,c,qv;
	q = p/x; r = p%x;
	if(q>=n){
		return true;
	}
	for(i=0; i<q; ++i){
		tmp += v[i].value;
	}
	for(i=0; i<n; ++i){
		if(v[i].b<r){
			c = v[i].l * r;
		}else{
			c = v[i].value - (x-r)*v[i].u;
		}
		if(i<q){
			d = max(d,tmp+c+v[q].value-v[i].value);
		}else{
			d = max(d,tmp+c);
		}
	}
	return (d>=0ll);
}

