// min{2^r | n < 2^r}
template <typename T> inline T upper_pow2(T n) {
  T res = 1;
  while (res < n)
    res <<= 1;
  return res;
}
// max{d | 2^d  <= n}
template <typename T> inline T msb(T n) {
  int d = 62;
  while ((1LL << d) > n)
    d--;
  return d;
}

template <typename T, typename U> T pmod(T v, U M) { return (v % M + M) % M; }

template <typename T,typename Func> T satisfy_mini(Func P,T l ,T r){
	l -= EPS<T>();
	while(r-l > EPS<T>()){
		T m=(l+r)/2;
		(P(m)?r:l)=m;
	}
	return r;
}

class Main {
public:
  void run() {
    int N; ll X; cin >> N >> X;
    vector<tuple<ll,ll,ll>> aos(N);
    cin >> aos;

    auto get_val =[&](tuple<ll,ll,ll> tup, ll t)->ll{
      ll b, l, u; tie(b,l,u) = (tup);
      return max(t - b, 0ll) * u + min(t, b) * l;
    };

    sort(ALL(aos),[&](auto p, auto q){
      return get_val(p,X) > get_val(q,X);
    });

    vector<ll> imos(N+1);
    for(int i:range(N)){
      imos[i+1] = imos[i] + get_val(aos[i],X);
    }

    ll iv = 0;
    for(int i:range(N)){
      ll b,l,u;tie(b,l,u) = aos[i];
      iv -= b*l;
    }

    ll res = satisfy_mini([&](ll t){
      ll Mv = 0;
      ll Xc = min<ll>(t/X,N);
      if(Xc == N){
        Mv = max(Mv, imos[N]);
      }else{
        for(int i:range(N)){
          if(i < Xc){
            Mv = max(Mv,get_val(aos[i],t%X) + imos[Xc+1] - get_val(aos[i],X));
          }else{
            Mv = max(Mv,get_val(aos[i],t%X) + imos[Xc]);
          }
        }
      }
      return Mv + iv >= 0;
    },0ll, N * X + 10);
    cout << res << endl;
  }
};

int main() {
  cout << fixed << setprecision(20);
  cin.tie(0);
  ios::sync_with_stdio(false);
  Main().run();
  return 0;
}

