ll d[125252];
ll e[125252];
int ids[125252];

int main(){
    scanf("%d%d",&n,&x);
    REP(i,n){
        scanf("%d%d%d",b+i,l+i,u+i);
    }
    ll rest = 0;
    REP(i,n)rest += (ll)l[i]*b[i];
    REP(i,n){
        d[i] = (ll)(u[i]-l[i])*b[i];
        e[i] = (ll)u[i]*x-d[i];
        ids[i] = i;
    }
    sort(ids,ids+n,[&](int i, int j){
        if(e[i] != e[j])return e[i] > e[j];
        return u[i] > u[j];
    });
    ll ans = 0;
    int last = 0;
    {
        ll tmp = 0;
        REP(i,n){
            tmp += e[ids[i]];
            ans += x;
            if(tmp>=rest){
                last = i;
                break;
            }
        }
    }
    // last ~ n-1
    {
        ll add = (ll)x*last;
        ll sum = 0;
        REP(i,last)sum += e[ids[i]];
        FOR(i,last,n){
            int id = ids[i];
            if(sum + e[id]<rest)continue;
            int ok = x, ng = 0;
            while(abs(ok-ng)>1){
                int v = (ok+ng)/2;
                ll val = sum + (ll)u[id]*v - d[id];
                (val >= rest ? ok : ng) = v;
            }
            CHMIN(ans, add+ok);
        }
    }
    // 0 ~ last-1
    {
        ll add = (ll)x*last;
        ll sum = 0;
        REP(i,last+1)sum += e[ids[i]];
        REP(i,last){
            int id = ids[i];
            sum -= e[id];
            int ok = x, ng = -1;
            while(abs(ok-ng)>1){
                int v = (ok+ng)/2;
                ll val = sum + (ll)u[id]*v - d[id];
                (val >= rest ? ok : ng) = v;
            }
            CHMIN(ans, add+ok);
            sum += e[id];
        }
    }
    sort(ids,ids+n,[&](int i, int j){
        if(e[i] != e[j])return e[i] > e[j];
        return l[i] > l[j];
    });
    // last ~ n-1
    {
        ll add = (ll)x*last;
        ll sum = 0;
        REP(i,last)sum += e[ids[i]];
        FOR(i,last,n){
            int id = ids[i];
            if(sum + (ll)l[id]*x<rest)continue;
            int ok = x, ng = 0;
            while(abs(ok-ng)>1){
                int v = (ok+ng)/2;
                ll val = sum + (ll)l[id]*v;
                (val >= rest ? ok : ng) = v;
            }
            CHMIN(ans, add+ok);
        }
    }
    // 0 ~ last-1
    {
        ll add = (ll)x*last;
        ll sum = 0;
        REP(i,last+1)sum += e[ids[i]];
        REP(i,last){
            int id = ids[i];
            if(sum + (ll)l[id]*x<rest)continue;
            sum -= e[id];
            int ok = x, ng = -1;
            while(abs(ok-ng)>1){
                int v = (ok+ng)/2;
                ll val = sum + (ll)l[id]*v;
                (val >= rest ? ok : ng) = v;
            }
            CHMIN(ans, add+ok);
            sum += e[id];
        }
    }
    printf("%lld\n",ans);
    return 0;
}

