  int64_t score_a = 0;
  vector< tuple< int64_t, int64_t,int64_t,int64_t > > T;
  cin >> N >> X;

  for (int64_t i=0;i<N;i++ ) {
    cin >> bin >> lin >> uin;
    score_a += lin * bin;
    T.push_back( make_tuple( (X-bin)*uin + bin*lin, bin, lin, uin ) );
  }
  sort(T.begin(),T.end());
  reverse(T.begin(),T.end());

  int flg = 0;
  int64_t dif_l_min = 0;
  int64_t dif = 0;
  for ( auto a: T ) {
    int64_t d;
    int64_t b,l,u;
    tie(d,b,l,u) = a;
    if (flg != 1) {
	  score_t += X * u;
      score_a += b * (u-l);
    }
//    cout << d << " " << b << " " << l << " " << u << endl;
//    cout << " " << score_t << " " << score_a << endl;
    if (flg == 1) {
      int64_t dif_l = (dif+l-1) / l;
      if (dif_l > b) dif_l = X;
      int64_t dif_u = (dif+(b*(u-l))+u-1) / u;
      if (dif_u < b) dif_u = X;
//      cout << " " << dif << " " << dif_l << " " << dif_u << endl;
      dif_l_min = min( dif_u, dif_l_min );
      dif_l_min = min( dif_l_min, dif_l );
    } else if (score_t > score_a) {
      flg = 1;
      score_t -= X * u;
      score_a -= b * (u-l);
      dif = score_a - score_t;
      int64_t dif_l = (dif+l-1) / l;
      if (dif_l > b) dif_l = X;
      int64_t dif_u = (dif+(b*(u-l))+u-1) / u;
      if (dif_u < b) dif_u = X;
//      cout << " " << dif << " " << dif_l << " " << dif_u << endl;
      dif_l_min = min( dif_u, dif_l );
    } else {
      total += X;
      if (score_t == score_a) break;
    }
  }
  total += dif_l_min;

  cout << total << endl;
}

