long long n, x;

struct dat {
  long long b, l, u;
  dat(long long _b = 0, long long _l = 0, long long _u = 0)
      : b(_b), l(_l), u(_u) {}
  bool operator<(const dat &r) const { return u * (x - b) > r.u * (x - r.b); }
};

vector<dat> v;
vector<long long> sum, ml;

long long solve();

int main() {
  cin >> n >> x;
  v.resize(n);
  for (auto &p : v) cin >> p.b >> p.l >> p.u;
  sort(v.begin(), v.end());
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long res = inf, now = 0;
  sum.assign(n + 1, 0);
  ml.assign(n + 1, 0);
  for (int i = n - 1; i >= 0; --i) {
    sum[i] = sum[i + 1] + v[i].l * v[i].b;
    ml[i] = max(ml[i + 1], v[i].l);
  }
  for (int i = 0; i < n; ++i) {
    auto [b, l, u] = v[i];
    {  // l pattern
      long long dif = sum[i] - now;
      if (dif >= 0 && dif <= ml[i] * x)
        res = min(res, x * i + (dif + ml[i] - 1) / ml[i]);
    }
    {  // r pattern
      long long dif = sum[i + 1] - now;
      if (dif > 0 && dif <= u * (x - b))
        res = min(res, x * i + b + (dif + u - 1) / u);
    }
    now += u * (x - b);
  }
  return res;
}

