            }
            int id = takeval[i].second;
            curr+=1LL*min(over, arr[i])*lr[id][0] + 1LL*max(0, over-arr[i])*lr[i][1];
            deficit = max(deficit, bad+curr);
        }
        if(deficit>=0) {
            r = mid;
        }else {
            l = mid+1;
        }
    }
    cout<<l<<"\n";
    return 0;
}

