    item() = default;
    item(int b, int l, int r) : b(b), l(l), r(r) { }
};

int n, X;
item f[N];

bool read() {
    if (!(cin >> n >> X))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> f[i].b >> f[i].l >> f[i].r;

    return true;
}

bool check(long long m) {
    if (m == 1ll * n * X)
        return true;

    auto w = m / X;
    auto init = 0ll;

    for (int i = 0; i < n; ++i)
        i <= w - 1 ? init += (X - f[i].b) * f[i].r : init -= f[i].b * f[i].l;

    auto res = init;

    for (int i = 0; i < n; ++i) {
        auto cur = init;

        if (i <= w - 1) {
            cur -= (X - f[i].b) * f[i].r;
            auto a = m % X >= f[i].b ? f[i].r : f[i].l;
            cur += (m % X - f[i].b) * a;
            cur += f[w].b * f[w].l;
            cur += (X - f[w].b) * f[w].r;
        } else {
            cur += f[i].b * f[i].l;
            auto a = m % X >= f[i].b ? f[i].r : f[i].l;
            cur += (m % X - f[i].b) * a;
        }

        res = max(res, cur);
    }

    return res >= 0;
}

void solve() {
    sort(f, f + n, [](const item& a, const item& b) {
        return (X - a.b) * a.r > (X - b.b) * b.r;
    });

    auto l = 0ll;
    auto r = 1ll * n * X;

    for (; l < r; ) {
        auto m = (l + r) / 2;

        if (check(m))
            r = m;
        else
            l = m + 1;
    }

    cout << l << endl;
}

