int solve(){
  int n,x;cin>>n>>x;
  vector<int> b(n, 0);
  vector<int> l(n, 0);
  vector<int> r(n, 0);

  int minimum = 0;
  rep(i, n){
    cin>>b[i]>>l[i]>>r[i];
    minimum += b[i]*l[i];
  }

  vi scores(n,0);
  rep(i, n){
    int score=0;
    score += x*r[i];
    score -= b[i]*(r[i]-l[i]);
    scores[i] = score;
  }
  vi ord(n);
  iota(all(ord), 0);
  sort(all(ord), [&](auto &left, auto &right){
      return scores[left]>scores[right];
      }
      );

  int left = -1;
  int right =  x*n;
  auto isright = [&](int k) {
    int vk = k;
    int myscore = 0;
    int now = 0;
    while(vk>=x and now<n){
      myscore += scores[ord[now]];
      vk -= x;
      now++;
    }

    int remMax = 0;
    rep(i, n){
      int score=0;
      if (i>=now){
        chmax(remMax, vk*l[ord[i]]);
        score += vk*r[ord[i]];
        score -= b[ord[i]]*(r[ord[i]]-l[ord[i]]);
        chmax(remMax, score);
      }
      else{
        score -= scores[ord[i]];
        score += max(vk*l[ord[i]], vk*r[ord[i]]-(b[ord[i]]*(r[ord[i]]-l[ord[i]])));
        chmax(remMax, scores[ord[now]]+score);
      }
    }
    myscore += remMax;

    if (myscore>=minimum) return true;
    else return false;
  };
  while (right-left>1){
    int mid = (right+left)/2;
    if (isright(mid)) { right = mid;}
    else{ left = mid; }
  }

  cout << right << endl;
  return 0;
}

