    vector<vector<long>> maxLead {};
    long border = 0;
    for (int i=0; i<N; i++) {
        int b, l, u;
        cin >> b >> l >> u;
        long s = b * l + (X - b) * u;
        maxLead.push_back(vector<long> {s, b, l, u});
        border += b * l;
    }
    sort(maxLead.rbegin(), maxLead.rend());

    vector<long> sumMaxLead {};
    {
        long prevSum=0;
        for (int i=0; i<N; i++) {
            long curSum = prevSum + maxLead[i][0];
            sumMaxLead.push_back(curSum);
            prevSum = curSum;
        }
    }

    long min_e = LONG_MAX;
    for (int i=0; i<N; i++) {
        long s = maxLead[i][0];
        int b = maxLead[i][1];
        int l = maxLead[i][2];
        int u = maxLead[i][3];

        int num_line = 0;
        long left_s = 0;
        // Case 0
        if (s >= border) {
            num_line = 0;
            left_s = border;
        } else {
            // Case pos left
            long q = border - s;
            int p = lower_bound(sumMaxLead.begin(), sumMaxLead.end(), q) - sumMaxLead.begin();
            num_line = p + 1;
            left_s = border - sumMaxLead[p];
            // Case pos right
            if (p >= i) {
                q = border;
                p = lower_bound(sumMaxLead.begin(), sumMaxLead.end(), q) - sumMaxLead.begin();
                num_line = p;
                left_s = border - (sumMaxLead[p] - s);
            }
        }
        long e = num_line * X;
        if (left_s < 0) {
            e = e;
        } else if (left_s <= b * l) {
            e += (left_s-1)/l + 1;
        } else {
            e += (left_s-1)/u + 1;
        }
        min_e = min(min_e, e);

        //cout << "i: " << i << ", s: " << s << endl;
    }

    cout << min_e << endl;
}

