long long X;
long long N;


int checkX(long long S){
    long long num = S / X;
    long long rest = S % X;

    if(rest == 0){
        return sum_vec[num];
    }

    long long ret = -1;

    for(int i = num; i < N; ++i){
        long long val;

//        if(i < num){
//            val = sum_vec[num + 1];
//            val -= info_vec[i].d_max;
//        }
//        else{
            val = sum_vec[num];
//        }

        if(rest < info_vec[i].b){
            val += info_vec[i].l * rest;
        }
        else{
            val += info_vec[i].l * info_vec[i].b + info_vec[i].u * (rest - info_vec[i].b);
        }

        ret = max(ret, val);
    }

    return ret;
}


