  sort(begin(idx), end(idx), [&](int i, int j) { return l[i] * b[i] + u[i] * (X - b[i]) > l[j] * b[j] + u[j] * (X - b[j]); });
  auto chk = [&](lint T) -> bool {
    lint s = 0, mx = -1e18;
    for (int i : idx) {
      if (T >= X) {
        s += u[i] * (X - b[i]);
        T -= X;
      } else {
        s -= l[i] * b[i];
        lint curr = T < b[i] ? l[i] * T : l[i] * b[i] + u[i] * (T - b[i]);
        mx = max(mx, curr);
      }
    }
    s += mx;
    return s >= 0;
  };
  lint ng = -1, ok = n * X;
  while (ok - ng > 1) {
    lint mid = ng + ok >> 1;
    (chk(mid) ? ok : ng) = mid;
  }
  cout << ok << '\n';
}

