				if(k>b[a[i].id])t+=(ll)u[a[i].id]*(k-b[a[i].id]);
				else t+=(ll)d[a[i].id]*(k-b[a[i].id]);
				// printf("%d %lld\n",i,t);
				mx=std::max(mx,t);
			}
		}
		if(mx>=0)r=mid;
		else l=mid+1;
	}
	writeln(l);
	return 0;
}

