int main() {
  int n;
  ll x;
  scan(n, x);
  vll b(n), l(n), u(n);
  rep (i, n) {
    scan(b[i], l[i], u[i]);
  }

  ll debt = 0;
  rep (i, n) {
    debt += b[i] * l[i];
  }

  vvll pred(n, vll(5));
  rep (i, n) {
    pred[i][0] = b[i] * l[i] + (x - b[i]) * u[i];
    pred[i][1] = i;
    pred[i][2] = b[i];
    pred[i][3] = l[i];
    pred[i][4] = u[i];
  }
  sort(all(pred), greater<vll>());
  debug(pred);

  int ind = -1;
  ll taka = 0;
  rep (i, n) {
    taka += pred[i][0];
    if (taka >= debt) {
      ind = i;
      break;
    }
  }
  sort(begin(pred), begin(pred) + ind+1, [](auto x, auto y) {
      return (x[4] == y[4] && x[1] < y[1]) || x[4] > y[4];
      });
  debug(ind);
  debug(pred);

  assert(ind >= 0);
  ll exceed = taka - debt;
  ll rest_min = x+1;
  int min_index = 0;
  rep (i, ind+1) {
    ll rest = pred[i][0] - exceed;
    ll ng = 0;
    ll ok = x;
    while (ok - ng > 1) {
      ll mid = (ng + ok) / 2;
      ll plus = min(mid, pred[i][2]) * pred[i][3];
      plus += (max(mid, pred[i][2]) - pred[i][2]) * pred[i][4];
      if (plus >= rest) {
        ok = mid;
      } else {
        ng = mid;
      }
    }
    if (ok < rest_min) {
      rest_min = ok;
      min_index = i;
    }
  }
  for (int i = ind ; i >= 0; --i) {
    if (i == min_index) {
      continue;
    }
    ll sum = pred[i][0];
    sum += min(rest_min, pred[min_index][2]) * pred[min_index][3];
    sum += (max(rest_min, pred[min_index][2]) - pred[min_index][2]) * pred[min_index][4];
    ll vmax = pred[min_index][0];
    ll rest = sum - vmax;
    ll ng = 0;
    ll ok = x;
    while (ok - ng > 1) {
      ll mid = (ng + ok) / 2;
      ll plus = min(mid, pred[i][2]) * pred[i][3];
      plus += (max(mid, pred[i][2]) - pred[i][2]) * pred[i][4];
      if (plus >= rest) {
        ok = mid;
      } else {
        ng = mid;
      }
    }
    rest_min = min(rest_min, ok);
    break;
  }
  ll ans = x * ind + rest_min;
  print(ans);

  return 0;
}

