int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n; long long x; cin >> n >> x;
    long long b[n], l[n], u[n];
    long long req = 0;
    vector<pair<long long, int>> vp; 
    for (int i = 0; i < n; i++) {
        cin >> b[i] >> l[i] >> u[i];
        req += l[i] * b[i];
        vp.emplace_back(u[i]*x-(u[i]-l[i])*b[i], i);
    }
    sort(vp.rbegin(), vp.rend());
    vector<long long> sum(n+1, 0);
    for (int i = 0; i < n; i++) {
        sum[i+1] = sum[i] + vp[i].first;
    }
    long long ans = 1e18;
    for (int i = 0; i < n; i++) {
        long long remain, curr;
        if (sum[i+1] < req) {
            auto j = upper_bound(sum.begin(), sum.end(), req+vp[i].first) - sum.begin();
            j--;
            remain = req - (sum[j] - vp[i].first);
            curr = (j - 1) * x;
        } else {
            auto j = upper_bound(sum.begin(), sum.end(), req) - sum.begin();
            j--;
            remain = req - sum[j];
            curr = j * x;
        }
        int j = vp[i].second;
        long long d = min(b[j], (remain+l[j]-1)/l[j]);
        remain -= d * l[j], curr += d;
        if (remain > 0) {
            d = min(x-b[j], (remain+u[j]-1)/u[j]);
            remain -= d * u[j], curr += d;
        }
        if (remain <= 0) ans = min(ans, curr);
    }
    cout << ans << "\n";
    return 0;
}

