            tmp += (remainder > b[idx] ? u[idx] : l[idx]) * (remainder - b[idx]);
            if (xNum < N)
            {
                const int idx2 = v[xNum].second;
                tmp -= l[idx2] * (0 - b[idx2]);
                tmp += u[idx2] * (X - b[idx2]);
            }
            chmax(best, tmp);
        }
        else
        {
            ll tmp = score;
            tmp -= (l[idx] * (0 - b[idx]));
            tmp += (remainder > b[idx] ? u[idx] : l[idx]) * (remainder - b[idx]);
            chmax(best, tmp);
        }
    }

    return best >= 0;
}

