struct TopK {
    multiset<ll> ms1, ms2;
    ll sum = 0;
    int k;

    TopK(int k) : k(k) {}

    void insert(const ll x) {
        ms1.insert(x);
        sum += x;
        if (ms1.size() > k) {
            auto it = ms1.begin();
            ms2.insert(*it);
            sum -= *it;
            ms1.erase(it);
        }
    }

    void erase(const ll x) {
        auto it = ms2.find(x);
        if (it != ms2.end())
            ms2.erase(it);
        else {
            it = ms1.find(x);
            assert(it != ms1.end());
            sum -= *it;
            ms1.erase(it);
        }
    }
};

