        hisScore += 1LL * b[i] * l[i];
    }

    ll lo = 0;
    ll hi = 1LL * n * X;

    {
        vector<ll> v(n);
        for (int i = 0; i < n; ++i)
            v[i] = b[i] * l[i] + (X - b[i]) * u[i];
        sort(v.rbegin(), v.rend());
        partial_sum(v.begin(), v.end(), v.begin());
        auto it =lower_bound(v.begin(), v.end(), hisScore);
        assert(it != v.end());
        const ll c = ll(it - v.begin());
        lo = c * X;
        hi = (c + 1) * X;
    }



    while (lo < hi) {
        const ll mid = (lo + hi) / 2;

        TopK topK(mid / X);
        for (int i = 0; i < n; ++i)
            topK.insert(b[i] * l[i] + (X - b[i]) * u[i]); // copy/paste

        ll mx = 0;
        for (int i = 0; i < n; ++i) {
            topK.erase(b[i] * l[i] + (X - b[i]) * u[i]); // copy/paste

            const ll here = mid % X < b[i] ? (mid % X) * l[i] : b[i] * l[i] + (mid % X - b[i]) * u[i];
            mx = max(mx, topK.sum + here);

            topK.insert(b[i] * l[i] + (X - b[i]) * u[i]); // copy/paste
        }

        if (mx >= hisScore)
            hi = mid;
