template <class T>
T lower_gauss(T num, T den) {
    assert(den != 0);
    if (num == 0) return 0;
    if (num > 0 and den > 0) return num / den;
    if (num < 0 and den > 0) return (num - den + 1) / den;
    return lower_gauss(-num, -den);
}

template <class T>
T upper_gauss(T num, T den) {
    return lower_gauss(num, den) + (num % den == 0 ? 0 : 1);
}



void solve() {
    //const i64 mod = 1'000'000'007;

    i64 N,X;
    cin >> N >> X;

    vector<i64> b(N),l(N),u(N);
    rep(i,0,N){
        cin >> b[i] >> l[i] >> u[i];
    }

    {
        bool zero=true;
        rep(i, 0, N) {
            if(b[i]>0){
                zero=false;
                break;
            }
        }
        if(zero){
            cout << 0 << endl;
            return;
        }
    }

    vector<tuple<i64,i64,i64,i64>> blu;
    rep(i,0,N){
        blu.emplace_back(make_tuple(u[i]*(X-b[i]),b[i],l[i],u[i]));
    }
    sort(rbegin(blu),rend(blu));

    vector<i64> acc(N);
    rep(i,0,N){
        i64 score,b,l,u;
        tie(score,b,l,u)=blu[i];
        acc[i]=score;
        if(i>0) acc[i]+=acc[i-1];
    }

    auto sum=[&](i64 l,i64 r){
        // [l, r]
        if(l>r) return i64(0);
        if(r<0) return i64(0);
        if(l>=N) return i64(0);
        i64 res=acc[r];
        if(l>0) res-=acc[l-1];
        return res;
    };

    vector<i64> acc2(N);
    rep(i,0,N){
        i64 score,b,l,u;
        tie(score,b,l,u)=blu[i];
        acc2[i]=l*-b;
        if(i>0) acc2[i]+=acc2[i-1];
    }

    auto sum2=[&](i64 l,i64 r){
        if(l>r) return i64(0);
        if(r<0) return i64(0);
        if(l>=N) return i64(0);
        i64 res=acc2[r];
        if(l>0) res-=acc2[l-1];
        return res;
    };

    auto ok=[&](i64 s){
        if(s>=N*X) return true;

        i64 num=s/X,rem=s%X;

        rep(i,0,num){
            i64 score,b,l,u;
            tie(score,b,l,u)=blu[i];

            i64 sum_score=sum(0,i-1)+(rem<b?l*(rem-b):u*(rem-b));
            sum_score+=sum(i+1,num);
            sum_score+=sum2(num+1,N-1);
            if(sum_score>=0){
                return true;
            }
        }

        rep(i,num,N){
            i64 score,b,l,u;
            tie(score,b,l,u)=blu[i];

            i64 sum_score=sum(0,num-1)+sum2(num,i-1)+(rem<b?l*(rem-b):u*(rem-b))+sum2(i+1,N-1);

            if(sum_score>=0){
                return true;
            }
        }

        return false;
    };

    i64 lb=0,ub=inf64;
    while(ub-lb>1){
        i64 mid=(lb+ub)/2;
        if(ok(mid)) ub=mid;
        else lb=mid;
    }

    cout << ub << endl;
}

