struct hoge {
    ll h0; ll num, l0;
};

bool comp(hoge &a, hoge &b){
    if(a.h0!=b.h0) return a.h0 > b.h0;
    if(a.l0!=b.l0) return a.l0 < b.l0;
    return a.num < b.num;
}

ll N, X;
ll b[100100], l[100100], u[100100];
hoge h[100100]; 
ll st;

bool ok(ll s){
    ll n=0LL;
    ll now=st;
    while(s >= X){
        now += h[n].h0;
        s -=X;
        n++;
    }
    //s増えた時のmaxを求める
    ll smax=0;
    for(ll i=n; i<N; i++){
        ll j=h[i].num;
        if(b[j] <s ){
            smax =max(smax,b[j]*l[j]+ (s-b[j])*u[j] );
        }
        else{
            smax =max(smax, l[j]*s);
        }
    }
    if(now+smax >=0) return true;
    return false;
}

