                sum+=(e-b[nx])*u[nx];
                if(sum>=0) return true;
                sum-=(e-b[nx])*u[nx];
            }
            else{
                sum+=(e-b[nx])*l[nx];
                if(sum>=0) return true;
                sum-=(e-b[nx])*l[nx];
            }
            sum-=l[nx]*b[nx];
        }
    }
    return false;
}


