lint N, X;
vector<lint> full, zero, highest_sum;
lint zero_sum = 0;

lint prefix_highest(lint r, lint now){ // [0, r)
    lint ret = highest_sum[r] + zero_sum;
    if(now < r){
        return ret - full[now];
    }else{
        return ret - zero[now];
    }
}

int main(){
    cin >> N >> X;
    lint b_in[N], l_in[N], u_in[N];
    for(int i = 0; i < N; i++){
        cin >> b_in[i] >> l_in[i] >> u_in[i];
    }
    pair<lint, int> highest[N];
    for(int i = 0; i < N; i++){
        highest[i] = {u_in[i] * (X - b_in[i]) + l_in[i] * b_in[i], i};
    }
    sort(highest, highest + N, greater<>());
    full.resize(N), zero.resize(N);
    lint b[N], l[N], u[N];
    for(int i = 0; i < N; i++){
        int x = highest[i].second;
        b[i] = b_in[x];
        l[i] = l_in[x];
        u[i] = u_in[x];
        full[i] = u[i] * (X - b[i]);
        zero[i] = -l[i] * b[i];
        zero_sum += zero[i];
    }
    highest_sum.resize(N + 1, 0);
    for(int i = 0; i < N; i++){
        highest_sum[i + 1] = highest_sum[i] + full[i] - zero[i];
    }
    lint ans = 1e18;
    for(int i = 0; i < N; i++){
        lint low = -1, high = N; // (low, high]
        while(low + 1 < high){
            lint mid = (low + high) / 2;
            if(prefix_highest(mid, i) + full[i] >= 0){
                high = mid;
            }else{
                low = mid;
            }
        }
        lint this_ans = high * X;
        if(i < high){
            this_ans -= X;
        }
        lint score = -prefix_highest(high, i);
        if(score >= 0){
            this_ans += (score + u[i] - 1) / u[i] + b[i];
        }else{
            this_ans += max(0ll, b[i] - (-score) / l[i]);
        }
        ans = min(ans, this_ans);
    }
    cout << ans << endl;
}

