	if(len <= b[day]) return len * l[day];
	return b[day] * l[day] + (len - b[day]) * r[day];
}
ll calc(ll h){
	ll q = h / X;
	ll r = h % X;
	vector <pair <ll, ll> > c;
	for(ll i = 0 ; i < n ; i++){
		c.emplace_back(sum(i, X), i);
