		s += c[i].first;
	}
	if(r == 0) return s;
	ll ret = 0;
	for(ll i = 0 ; i < q ; i++){
		ret = max(ret, s - sum(c[i].second, X) + sum(c[i].second, r) + sum(c[q].second, X));
	}
	ret = max(ret, s + sum(c[q].second, r));
	return ret;
