    scanf("%d%d%d", &b[i], &l[i], &u[i]);
  }
  vi x(n, 0);
  ll res = 0;
  ll sum = 0;
  for (int i = 0; i < n; ++i) {
    sum += -ll(l[i]) * ll(b[i]);
  }
  vl total(n);
  for (int i = 0; i < n; ++i) {
    total[i] = ll(b[i]) * l[i] + ll(X - b[i]) * u[i];
  }
  set<vector<ll> > full_segments;
  set<int> left_segments;
  for (int i = 0; i < n; ++i) {
    vector<ll> segment;
    segment.push_back(-total[i]);
    segment.push_back(u[i]);
    segment.push_back(i);
    full_segments.insert(segment);
    left_segments.insert(i);
  }
  vector<bool> used(n, false);
  while (sum < 0) {
    set<vector<ll> >::iterator it = full_segments.begin();
    ll tot = -it->at(0);
    int index = it->at(2);
    used[index] = true;
    full_segments.erase(*it);
    if (sum + tot <= 0) {
      sum += tot;
      res += X;
      left_segments.erase(index);
    }
    else {
