  for (int i = 0; i < n; ++i) {
    if (left_segments.count(i)) {
      ll need;
      if (ll(l[i]) * b[i] >= left) {
        need = (left + l[i] - 1) / l[i];
      }
      else {
        need = b[i] + (left - ll(l[i]) * b[i] + u[i] - 1) / u[i];
      }
      if (need < curres) {
        curres = need;
      }
      if (total[i] > max_total) {
        max_total = total[i];
      }
    }
  }
  for (int i = 0; i < n; ++i) {
    if (used[i] && total[i] == max_total) {
      ll need;
      if (ll(l[i]) * b[i] >= left) {
        need = (left + l[i] - 1) / l[i];
      }
      else {
        need = b[i] + (left - ll(l[i]) * b[i] + u[i] - 1) / u[i];
      }
      if (need < curres) {
        curres = need;
      }
    }
  }
  res = res + curres;
  cout << res << endl;
  return 0;
}

