struct mll{
	static ll MOD;
	ll val;
	mll(ll v = 0): val(v % MOD){ if (val < 0) val += MOD; }
	mll operator - () const { return -val; }
	mll operator + (const mll &b) const { return val + b.val; }
	mll operator - (const mll &b) const { return val - b.val; }
	mll operator * (const mll &b) const { return val * b.val; }
	mll operator / (const mll &b) const { return mll(*this) /= b; }
	mll operator + (ll b) const { return *this + mll(b); }
	mll operator - (ll b) const { return *this - mll(b); }
	mll operator * (ll b) const { return *this * mll(b); }
	friend mll operator + (ll a, const mll &b) { return b + a; }
	friend mll operator - (ll a, const mll &b) { return -b + a; }
	friend mll operator * (ll a, const mll &b) { return b * a; }
	mll &operator += (const mll &b) { val=(val+b.val)%MOD; return *this; }
	mll &operator -= (const mll &b) { val=(val+MOD-b.val)%MOD; return *this; }
	mll &operator *= (const mll &b) { val=(val*b.val)%MOD; return *this; }
	mll &operator /= (const mll &b) {
		ll c=b.val, d=MOD, u=1, v=0;
		while (d){
			ll t = c / d;
			c -= t * d; swap(c, d);
			u -= t * v; swap(u, v);
		}
		val = val * u % MOD;
		if (val < 0) val += MOD;
		return *this;
	}
	mll &operator += (ll b) { return *this += mll(b); }
	mll &operator -= (ll b) { return *this -= mll(b); }
	mll &operator *= (ll b) { return *this *= mll(b); }
	mll &operator /= (ll b) { return *this /= mll(b); }
	bool operator == (const mll &b) { return val == b.val; }
	bool operator != (const mll &b) { return val != b.val; }
	bool operator == (ll b) { return *this == mll(b); }
	bool operator != (ll b) { return *this != mll(b); }
	friend bool operator == (ll a, const mll &b) { return mll(a) == b.val; }
	friend bool operator != (ll a, const mll &b) { return mll(a) != b.val; }
	friend ostream &operator << (ostream &os, const mll &a) { return os << a.val; }
	friend istream &operator >> (istream &is, mll &a) { return is >> a.val; }
	static mll Combination(ll a, ll b){
		chmin(b, a-b);
		if (b<0) return mll(0);
		mll c = 1;
		REP(i, b) c *= a-i;
		REP(i, b) c /= i+1;
		return c;
	}
};
ll mll::MOD = 998244353LL;// (ll)(1e9 + 7);



void solve()
{
	ll N, X;
	cin >> N >> X;
	auto blu = cinv3(N);

	vector<tuple<ll, ll, ll, ll, ll>> sblu(N);

	ll sumScore=0;
	REP(i, N){
		ll b = get<0>(blu[i]);
		ll l = get<1>(blu[i]);
		ll u = get<2>(blu[i]);
		sumScore -= l*b;
	}

	REP(i, N){
		ll b = get<0>(blu[i]);
		ll l = get<1>(blu[i]);
		ll u = get<2>(blu[i]);
		get<0>(sblu[i]) = u*(X-b)+l*b;
		get<1>(sblu[i]) = b;
		get<2>(sblu[i]) = l;
		get<3>(sblu[i]) = u;
	}
	std::sort(sblu.begin(), sblu.end());

	ll ii;
	DEP(i, N){
		ll s = get<0>(sblu[i]);
		if (sumScore + s < 0) sumScore += s;
		else {
			ii = i;
			break;
		}
	}

	ll rs = -sumScore;

	ll minx = INF;
	DEPS(i, 0, ii){
		ll s = get<0>(sblu[i]);
		ll b = get<1>(sblu[i]);
		ll l = get<2>(sblu[i]);
		ll u = get<3>(sblu[i]);

		ll x = CEIL(rs, l);
		if (x > b) x = b + CEIL(rs-l*b, u);
		chmin(minx, x);
	}

	cout << (N-1-ii)*X + minx << '\n';
}

int main(){
	solve();
	return 0;
}

