#include <bits/stdc++.h>
using namespace std;
struct tests{
	long long cost; 
	long long L; 
	long long U; 
	long long B; 
}; 
bool cmp(const tests &a, const tests &b){
    return a.cost > b.cost;
}
int main(){
	int N; long long X; cin >> N >> X; 
	tests T[100010] = {}; 
	for(int i = 0; i < N; i++){
		cin >> T[i].B >> T[i].L >> T[i].U; 
		T[i].cost = T[i].U * (X - T[i].B) + T[i].L * T[i].B; 
	}
	sort(T, T+N, cmp); 
	long long noben = 0; 
	long long time = 0; 
	int idx = 0; 
	for(int i = 0; i < N; i++) noben -= T[i].L * T[i].B; 
	if(noben == 0){
		cout << 0 << endl; return 0; 
	}
	for(int i = 0; i < N; i++){
		if(noben + T[i].cost >= 0){
			idx = i; break; 
		}
		time += X; noben += T[i].cost; 
	}
	long long nokori = -noben;
	long long add = X; 
	for(int i = idx; i < N; i++){
		long long tmp = 0; long long nownokori = nokori; 
		if(T[i].L * T[i].B >= nownokori){
			tmp = (nownokori + T[i].L - 1) / T[i].L; 
		}
		else{
			nownokori -= T[i].L * T[i].B;
			tmp += T[i].B; 
			tmp += (nownokori + T[i].U - 1) / T[i].U; 
		}
		add = min(add, tmp); 
	}
	cout << time + add << endl;
}

