#include<vector>
template<typename T>
struct BIT{
	int n;
	vector<T>bit;
	BIT(int n_=0,T a=0):n(n_),bit(n_+1,a){}
	T sum(int i)
	{
		T ans=0;
		for(;i>0;i-=i&-i)ans+=bit[i];
		return ans;
	}
	void add(int i,T a)
	{
		if(i==0)return;
		for(;i<=n;i+=i&-i)bit[i]+=a;
	}
};
int N;
long X,b[1<<17],l[1<<17],u[1<<17];
long sumb;
main()
{
	cin>>N>>X;
	vector<pair<long,int> >A;
	for(int i=0;i<N;i++)
	{
		cin>>b[i]>>l[i]>>u[i];
		sumb+=b[i];
		A.push_back(make_pair((X-b[i])*u[i],i));
	}
	sort(A.begin(),A.end());
	reverse(A.begin(),A.end());
	long Lsum=0;
	BIT<long>P(N);
	for(int i=0;i<N;i++)
	{
		Lsum+=b[i]*l[i];
		int id=A[i].second;
		P.add(i+1,X*u[id]-b[id]*(u[id]-l[id]));
	}
	long ans=sumb;
	for(int i=0;i<N;i++)
	{
		long tmp=P.sum(i+1)-P.sum(i);
		P.add(i+1,-tmp);
		long L=-1,R=sumb;
		while(R-L>1)
		{
			long M=(L+R)/2;
			int can=M/X;
			long nowsum=-Lsum;
			nowsum+=P.sum(can+(can>i));
			int id=A[i].second;
			nowsum+=max(M%X*l[id],M%X*u[id]-b[id]*(u[id]-l[id]));
			if(nowsum>=0)R=M;
			else L=M;
		}
		P.add(i+1,tmp);
		ans=min(ans,R);
	}
	cout<<ans<<endl;
}

