int x;

struct test {
  int b, l, u;
  ll area, low, high;

  test(int b, int l, int u) : b(b), l(l), u(u) {
    low = 1LL * b * l;
    high = 1LL * (x - b) * u;
    area = low + high;
  }

  bool operator<(test a) {
    return area < a.area;
  }
};

void solve() {
  int n; cin >> n >> x;
  int b, l, u;
  ll target = 0;
  vector<test> tests;
  rep(i,n) {
    cin >> b >> l >> u;
    tests.emplace_back(b, l, u);
    target += 1LL * b * l;
  }

  if (target == 0) {
    cout << 0 << endl;
    return;
  }

  sort(RALL(tests));

  vl sum(n+1, 0);
  rep(i,n) sum[i+1] = sum[i] + tests[i].area;

  auto base = --upper_bound(ALL(sum), target);
  int idx = base - sum.begin();

  ll ans = 1e12;

  rep(i,n) {
    auto itr = base;
    ll score = *itr;
    ll cnt = idx;
    if (i < idx) {
      itr = --upper_bound(ALL(sum), target + tests[i].area);
      score = *itr - tests[i].area;
      cnt = itr - sum.begin() - 1;
    }

    if (score + tests[i].low >= target) {
      int tmp = (target - score - 1) / tests[i].l + 1;
      chmin(ans, x * cnt + tmp);
    } else if (score + tests[i].area >= target) {
      int tmp = (target - (score + tests[i].low) - 1) / tests[i].u + tests[i].b + 1;
      chmin(ans, x * cnt + tmp);
    }
  }

  cout << ans << endl;
}


