void chemthan() {
    int n, x; cin >> n >> x;
    vi b(n), l(n), u(n);
    FOR(i, 0, n) cin >> b[i] >> l[i] >> u[i];
    vi vals;
    FOR(i, 0, n) {
        vals.pb(i);
    }
    long long lo = 0, hi = LINF;
    while (lo < hi) {
        sort(all(vals), [&] (int i, int j) {
                return (long long) (x - b[i]) * u[i] > (long long) (x - b[j]) * u[j];
                }
            );
        long long mi = lo + hi >> 1;
        long long num = mi / x;
        long long r = mi % x;
        int found = 0;
        if (n <= num) {
            found = 1;
        }
        else {
            long long sum = 0;
            FOR(i, 0, num) {
                int j = vals[i];
                sum += (long long) (x - b[j]) * u[j];
            }
            sort(vals.begin() + num, vals.end(), [&] (int i, int j) {
                    return u[i] > u[j];
                    }
                );
            int j = vals[num];
            if (b[j] <= r) {
                sum += (long long) (r - b[j]) * u[j];
            }
            else {
                sum += (long long) (r - b[j]) * l[j];
            }
            FOR(i, num + 1, n) {
                int j = vals[i];
                sum -= (long long) b[j] * l[j];
            }
            if (0 <= sum) {
                found = 1;
            }
        }
        if (!found) {
            lo = mi + 1;
        }
        else {
            hi = mi;
        }
    }
    cout << (lo + hi >> 1) << "\n";
}

