typedef vector<pl> vpl;
const int MN = 100100;
ll pr[MN];
ll sid[MN];
ll sz;
ll sc[MN],pot[MN];
pl get(ll tar, int id) {
	int st = 0,ed = sz;
	int ls = -1;
	while(st <= ed) {
		int m = (st+ed)/2;
		ll val = pr[m];
		if(m > sid[id]) {
			val -= pot[id];
		}
		if(val >= tar) {
			ed = m-1;
			ls = m;
		} else {
			st = m+1;
		}
	}
	if(ls == -1) {
		return mmp(-1,-1);
	}
	ll ret = pr[ls];
	if(ls > sid[id]) {
		ls--;
		ret -= pot[id];
	}
	return mmp(ls,ret);
}

pl lr[MN];
int main() {
vpl pa;
	ios::sync_with_stdio(0);cin.tie(0);
	memset(pr,0,sizeof(pr));
	ll n,x;
	cin >> n >> x;
	sz = n;
	ll tot = 0;
	ll res = 0;
	for(int i=0;i<n;i++) {
		ll a,b,c;
		cin >> a >> b >> c;
		tot += a*b;
		res += a;
		sc[i] = a;
		lr[i] = mmp(b,c);
		pot[i] = c*x+a*b-a*c;
		pa.push_back(mmp(pot[i],i));
	}
	sort(pa.begin(),pa.end(),greater<pl>());
	for(int i=0;i<pa.size();i++) {
		sid[pa[i].second] = i;
		pr[i+1] = pr[i]+pa[i].first;
	}
	for(int rev=0;rev<2;rev++) {
		for(int i=0;i<n;i++) {
			ll gol;
			ll val;
			ll a = sc[i];
			ll b = lr[i].first,c = lr[i].second;
			ll co;
			ll tar;
			if(rev) {
				gol = tot-b*x;
				val = 0;
				co = b;
				tar = tot;
			} else {
				tar = tot+a*c-a*b;
				ll a = sc[i];
				ll b = lr[i].first;
				val = 0;
				gol = tot-c*(x-a)-a*b;
				co = c;
			}
			ll ls = n;
			pl dat = get(gol,i);
			if(dat.first == -1) {
				continue;
			}
			ll run = dat.second;
			ls = dat.first;
			val += ls*x+max((tar-run+co-1)/co,0LL);
			res = min(val,res);
		}
	}
	cout << res << '\n';
}

