typedef long long ll;

ll X;
struct elem {
  ll b, l, u;

  ll key () {
    return u * (X - b) + l * b;
  }
};

bool byopt (elem p, elem q) {
  return p.key() > q.key();
}

const int MAX_N = 1e5 + 5;

elem elems [MAX_N];

int n;
bool can (int rem, ll cur, ll xc) {
  // can we get above 0?
  for (int i = 0; i < n; i++) {
    ll ccur = cur;
    if (i < xc) {
      ccur -= elems[i].key();
      ccur += elems[xc].key();
    }
    ccur += elems[i].l * elems[i].b;
    if (rem - elems[i].b < 0) {
      ccur += elems[i].l * (rem - elems[i].b);
    } else {
      ccur += elems[i].u * (rem - elems[i].b);
    }

    if (ccur >= 0) return true;
  }
  return false;
}

