using namespace std;
typedef long long ll;
#define DBG(v) cerr << #v << " = " << (v) << endl;

struct TopK {
    multiset<ll> ms1, ms2;
    ll sum = 0;
    int k;
    int sz =0 ;

    TopK(int _k) : k(_k) {}

    void insert(const ll x) {
        ms1.insert(x);
        sum += x;
        if (ms1.size() > k) {
            auto it = ms1.begin();
            ms2.insert(*it);
            sum -= *it;
            ms1.erase(it);
        }
        ++sz;
        check();
    }
    void check() {
        assert(ms1.size() <= k);
        if(!ms2.empty()) {
            assert(ms1.size() == k);
            if(k)
                assert(*ms2.rbegin() <= *ms1.begin());
        }
        assert(int(ms1.size()) + int(ms2.size()) == sz);
    }

    void erase(const ll x) {
        auto it = ms2.find(x);
        if (it != ms2.end())
            ms2.erase(it);
        else {
            it = ms1.find(x);
            assert(it != ms1.end());
            sum -= *it;
            ms1.erase(it);
            if(!ms2.empty()) {
                auto it = --ms2.end();
                ms1.insert(*it);
                sum += *it;
                ms2.erase(it);
            }
        }
        --sz;
        check();
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr), cout.tie(nullptr);

    int n;
    ll X;
    cin >> n >> X;
    vector<ll> b(n), l(n), u(n);

    const function<int(int, int)> eval = [&](const int i, const ll c) {
        assert(0 <= i && i < n);
        assert(0 <= c && c <= X);
        if(c <= b[i])
            return c * l[i];
        return b[i] * l[i] + (c - b[i]) * u[i];
    };

    ll hisScore = 0;
    for (int i = 0; i < n; ++i) {
        cin >> b[i] >> l[i] >> u[i];
        hisScore += eval(i, b[i]);
    }

    ll k = 0;

    {
        vector<ll> v(n);
        for (int i = 0; i < n; ++i)
            v[i] = eval(i, X);
        sort(v.rbegin(), v.rend());
        partial_sum(v.begin(), v.end(), v.begin());
        auto it = lower_bound(v.begin(), v.end(), hisScore);
        assert(it != v.end());
        k = it - v.begin();
    }

    TopK topK(k);
    for(int i = 0; i < n; ++i)
        topK.insert(eval(i, X));

    ll lo = 0;
    ll hi = X;
    while(lo < hi) {
        const ll mid = (lo + hi) / 2;

        ll mx = 0;
        for(int i = 0; i < n; ++i) {
            topK.erase(eval(i, X));
            mx = max(mx, topK.sum + eval(i, mid));
            topK.insert(eval(i, X));
        }

        if(mx >= hisScore)
            hi = mid;
        else
            lo = mid + 1;
    }

    cout << k * X + lo;
    return 0;
}

