using namespace std;
ll n, x;
struct T{
    ll b, l, r;
    pair<ll, ll> tt;
};
vector<T> a;
bool comp(T a, T b)
{
    return a.tt > b.tt;
}

bool can(ll t)
{
    ll full = t / x;
    ll more = t % x;
    for (int i = 0; i < a.size(); i++)
        a[i].tt = {(x - a[i].b) * a[i].r + a[i].l * a[i].b, a[i].b * a[i].l + max(0LL, more - a[i].b) * a[i].r};
    sort(a.begin(), a.end(), comp);
    ll we = 0, he = 0;
    for (int i = 0; i < full; i++)
    {
        we += x * a[i].r;
        he += a[i].b * a[i].r;
    }
    for (int i = full; i < n; i++)
    {
        he += a[i].l * a[i].b;
    }
    for (int i = full; i < n; i++)
    {
        he += (a[i].r - a[i].l) * a[i].b;
        we += a[i].r * more;
        if (we >= he)
            return 1;
        we -= a[i].r * more;
        he -= (a[i].r - a[i].l) * a[i].b;

        we += a[i].l * more;
        if (we >= he)
            return 1;
        we -= a[i].l * more;
    }
    we += x * a[full].r;
    he += a[full].b * (a[full].r - a[full].l);
    for (int i = 0; i < full; i++)
    {
        we -= x * a[i].r;
        we += more * a[i].r;
        if (we >= he)
            return 1;
        we -= more * a[i].r;
        we += x * a[i].r;

        we -= x * a[i].r;
        we += more * a[i].l;
        he -= (a[i].r - a[i].l) * a[i].b;
        if (we >= he)
            return 1;
        we += x * a[i].r;
        we -= more * a[i].l;
        he += (a[i].r - a[i].l) * a[i].b;
    }
    return 0;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> x;
    for (int i = 0; i < n; i++)
    {
        int b, l, r;
        cin >> b >> l >> r;
        a.push_back({b, l, r});
    }
    ll l = -1, r = n * x;
    while (l + 1 < r)
    {
        ll mid = (l + r) / 2;
        if (can(mid))
            r = mid;
        else
            l = mid;
    }
    cout << r;
}

