	sort(input.begin(), input.end());
	reverse(input.begin(), input.end());
	long long ans = LONG_INF;
	long long now = 0;
	priority_queue<pair<long long, long long>> gea;
	for (int i = 0; i < input.size(); ++i) {
		gea.push(make_pair(get<2>(input[i]), i));
		now += get<1>(input[i]) * get<2>(input[i]);//驥崎ｦ∝ｺｦ菴弱ａ
	}
	long long taken = 0;
	for (int i = 0; i <= input.size(); ++i) {
		if (i == input.size()) break;
		now -= get<1>(input[i]) * get<2>(input[i]);//蜆ｪ蜈亥ｺｦ菴弱ａ
		now += get<1>(input[i]) * get<3>(input[i]);//蜆ｪ蜈亥ｺｦ鬮倥ａ
		if (now <= x * get<3>(input[i])) {
			now -= get<1>(input[i]) * get<3>(input[i]);//蜆ｪ蜈亥ｺｦ鬮倥ａ
			now += get<1>(input[i]) * get<2>(input[i]);
			for (int q = i; q < input.size(); ++q) {
				now -= get<1>(input[q]) * get<2>(input[q]);
				long long bot = get<2>(input[q]);
				long long top = get<3>(input[q]);
				while (top - bot > 2) {
					long long mid1 = (bot + bot + top) / 3;
					long long mid2 = (bot + top + top) / 3;
					now += get<1>(input[q]) * mid1;
					int geko = (now + mid1 - 1) / mid1;
					now -= get<1>(input[q]) * mid1;
					if (geko <= x) {
						ans = min(ans, geko + taken);
					}
					else {
						bot = mid1;
						continue;
					}
					now += get<1>(input[q]) * mid2;
					int popo = (now + mid2 - 1) / mid2;
					now -= get<1>(input[q]) * mid2;
					if (popo > x) {
						top = mid2;
						continue;
					}
					else {
						ans = min(ans, popo + taken);
						if (geko <= popo) {
							top = mid2;
						}
						else {
							bot = mid1;
						}
					}
				}
				for (long long j = bot; j <= top; ++j) {
					now += get<1>(input[q]) * j;
					int popo = (now + j - 1) / j;
					now -= get<1>(input[q]) * j;
					if (popo <= x) {
						ans = min(ans, popo+taken);
					}
				}
				now += get<1>(input[q]) * get<2>(input[q]);
			}
