bool check(ll s) {
  ll y = s/x, m = s%x;
  tsum = 0;
  for (ll i = 0; i < y; i++) tsum += p[i].first;
  if (m == 0) return tsum >= asum;
  ll temp = 0;
  for (ll i = y; i < n; i++) {
    ll num = p[i].second;
    temp = max(temp, u[num] * m - (u[num]-l[num])*b[num]);
    temp = max(temp, l[num] * m);
  }
  if (tsum + temp >= asum) return true;
  if (y == n) return false;
  tsum += p[y].first;
  ll temp2 = -INF;
  for (ll i = 0; i < y; i++) {
    ll num = p[i].second;
    temp2 = max(temp2, u[num] * m - (u[num]-l[num])*b[num] - p[i].first);
    temp2 = max(temp2, l[num] * m - p[i].first);
  }
  return tsum + temp2 >= asum;
}

