using Int = long long;
int main()
{
    Int N, X; cin >> N >> X;
    vector<Int> B(N), L(N), U(N);
    for (int i = 0; i < N; i++) cin >> B[i] >> L[i] >> U[i];
    Int start = 0;
    for (int i = 0; i < N; i++) start -= B[i] * L[i];
    vector<pair<Int, int>> A(N);
    for (int i = 0; i < N; i++) A[i] = make_pair(U[i] * (X - B[i]) + L[i] * B[i], i);
    sort(rbegin(A), rend(A));
    vector<Int> S(N+1), order(N);
    for (int i = 0; i < N; i++) order[A[i].second] = i;
    for (int i = 0; i < N; i++) S[i+1] = S[i] + A[i].first;
    Int ok = X * N, ng = -1;
    while (ok - ng > 1) {
        Int mid = (ok + ng) / 2;
        int s = mid / X;
        int t = mid % X;
        Int maxval = start;
        for (int i = 0; i < N; i++) {
            Int val = start + (t > B[i] ? U[i] : L[i]) * (t - B[i]) + L[i] * B[i];
            if (order[i] < s) {
                val += S[s+1] - (U[i] * (X - B[i]) + L[i] * B[i]);
            } else {
                val += S[s];
            }
            maxval = max(maxval, val);
        }
        (maxval >= 0 ? ok : ng) = mid;
    }
    cout << ok << '\n';
    return 0;
}

