        LL cur_0 = -1ll*E[i].b*E[i].l;
        LL D = 0;
        if(i <= full) D += pre_X[full+1] - cur_X + pre_0[full+2];
        else D += pre_X[full] + pre_0[full+1] - cur_0;
        if(extra <= E[i].b) D += 1ll*(extra-E[i].b)*E[i].l;
        else D += 1ll*(extra-E[i].b)*E[i].r;
        if(D >= 0) return 1;
    }
    return 0;
}

int main() {
    // freopen("in.txt", "r", stdin);
    ios::sync_with_stdio(0);
    cin.tie(0);
    cin >> n >> X;
    for(int i = 1; i <= n; i++) cin >> E[i].b >> E[i].l >> E[i].r;
    sort(E+1, E+n+1);
    for(int i = 1; i <= n; i++) {
        pre_X[i] = pre_X[i-1] + 1ll*(X-E[i].b)*E[i].r;
    }
    for(int i = n; i >= 1; i--) {
        pre_0[i] = pre_0[i+1] - 1ll*E[i].b*E[i].l;
    }
    LL lo = 0, hi = 1ll*n*X;
    while(hi > lo) {
        LL mid = (lo+hi)/2;
        if(ok(mid)) hi = mid;
        else lo = mid+1;
    }
    cout << lo << endl;
    return 0;
}

