	}
}

int check(ll mid) {
	ll sum = 0;
	vector<pair<ll,int>>mx;
	for (int i = 0; i < N; i++) {
		ll b = v[i][0];
		ll l = v[i][1];
		ll u = v[i][2];
		mx.pb({ f(X,b,l,u),i});
	}
	sort(all(mx));
	reverse(all(mx));

	vector<int>ng(N);
	for (int i = 0; i < (mid / X); i++) {
		sum += mx[i].first;
		ng[mx[i].second] = 1;
	}

	ll tempsum = 0;
	for (int i = 0; i < N; i++) {
		if (ng[i]) {
			ll b = v[i][0];
			ll l = v[i][1];
			ll u = v[i][2];
			tempsum += f(0, b, l, u);
		}
	}

	ll ma = -inf;
	for (int i = 0; i < N;i++) {
		if (ng[i]) {
			ll b = v[i][0];
			ll l = v[i][1];
			ll u = v[i][2];
			ll temp = tempsum - f(0, b, l, u) + f(mid % X, b, l, u);
			ma = max(temp, ma);
		}
	}
	sum += ma;
	return sum >= 0;
}

