int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N,X;
  IN(N,X);
  vll b(N), l(N), u(N);
  vpll VP(N);
  REP(i,N){
    IN(b[i], l[i], u[i]);
    VP[i].first = u[i]*b[i] - l[i]*b[i] - u[i]*X;
    VP[i].second = i;
  }

  sort(ALL(VP));

  /*
  REP(i,N){
    printf("%d %d\n", i, VP[i].first);
  }
  */

  ll T_point=0, A_point=0;

  REP(i,N){
    A_point += b[i]*l[i];
  }

  ll ans = 0;
  vll flag(N, true);

  ll pos = 0;
  while(T_point<A_point){
    ll i = VP[pos].second;

    //printf("%d %d %d\n", i, T_point, A_point);
    A_point += b[i]*(u[i]-l[i]);
    T_point += u[i]*X;
    if(T_point<A_point){
      ans += X;
      flag[i] = false;
    }else{
      A_point -= b[i]*(u[i]-l[i]);
      T_point -= u[i]*X;

      ll X_add_min = X;

      for(int j=0; j<N; ++j){
        if(flag[j]==false) continue;
        ll coef = b[i]*(u[i]-l[i]);
        if(T_point+u[i]*X < A_point+coef) continue;
        ll X_tmp = (A_point - T_point + coef)/u[i];
        while(T_point+u[i]*X_tmp < A_point+coef) X_tmp++;
        X_add_min = min(X_add_min, X_tmp);

        if(T_point+l[i]*X < A_point) continue;
        ll X_tmp2 = (A_point - T_point) / l[i];
        while(T_point+l[i]*X_tmp2 < A_point) X_tmp2++;
        X_add_min = min(X_add_min, X_tmp2);

      }

      ans += X_add_min;

      break;
    }
    pos++;
  }

  OUT(ans);

  return 0;
}

