const int maxn = 123456;
int b[maxn], l[maxn], u[maxn], od[maxn];
int main(){
	int n, x; cin >> n >> x;
	for(int i = 0; i < n; i++) cin >> b[i] >> l[i] >> u[i];
	iota(od, od + n, 0);
	auto enh = [&](int p){
		return 1ll * u[p] * x - 1ll * b[p] * (u[p] - l[p]);
	};
	sort(od, od + n, [&](int x, int y){
		return enh(x) > enh(y);
	});
	long long in = 0;
	for(int i = 0; i < n; i++) in -= 1ll * b[i] * l[i];
	long long res = 0;
	int inc = 1<<30;
	bool doit = false;
	for(int i = 0; i < n; i++){
		int now = od[i];
		if(doit || in + enh(now) >= 0){
			int lo = 0, hi = x, ans = -1;
			while(lo <= hi){
				int mid = (lo + hi)>>1;
				bool good = false;
				if(mid < b[now]){
					if(in + 1ll * l[now] * mid >= 0) good = true;
				} else {
					if(in + 1ll * u[now] * mid - 1ll * b[now] * (u[now] - l[now]) >= 0) good = true;
				}
				if(good) ans = mid, hi = mid - 1;
				else lo = mid + 1;
			}
			if(ans != -1)
				inc = min(inc, ans);
			doit = true;
		} else {
			res += x;
			in += enh(now);
		}
	}
	cout << res + inc << endl;
	return 0;
}

