lint n,x,b[100010],l[100010],u[100010];
std::vector<P> diff;
bool used[100010];
int main(){
	std::cin>>n>>x;
	int cost=0;
	rep(i,n){
		std::cin>>b[i]>>l[i]>>u[i];
		cost-=b[i]*l[i];
		diff.emplace_back((x-b[i])*u[i]+b[i]*l[i],i);
	}
	std::sort(all(diff),std::greater<P>());
	int min=-1,max=n*x;
	while(min+1<max){
		int mid=(min+max)/2;
		int full=mid/x,rem=mid%x,cnt=cost;
		memset(used,false,sizeof(used));
		rep(i,full){
			cnt+=diff[i].first;
			used[diff[i].second]=true;
		}
		rep(i,n){
			int score=cnt;
			score+=b[i]*l[i];
			if(rem>b[i])score+=u[i]*(rem-b[i]);
			else score-=l[i]*(b[i]-rem);
			if(used[i]){
				score-=(x-b[i])*u[i]+b[i]*l[i];
				score+=diff[full].first;
			}
