     for (int i = 0; i < N; i++) {
         LL tmp = (LL)(X - b[i]) * u[i] + (LL)b[i] * l[i];
         cand.push_back(make_pair(tmp, i));
     }
     sort(cand.rbegin(), cand.rend());
     LL full = ans / X, rmd = ans % X;
     if (full >= N) return true;
     LL sumA = 0, sum = 0;
     for (int i = 0; i < full; i++) {
         int idx = cand[i].second;
         sum += cand[i].first;
         vis[idx] = 1;
     }
     sumA = sum;
     for (int i = 0; i < N; i++) {
         LL tmp = sum;
         LL pt1 = (LL)(X - b[i]) * u[i] + (LL)b[i] * l[i];
         if (vis[i]) tmp = tmp - pt1 + cand[full].second;
         LL base = min((LL)b[i], rmd);
         LL exd = (rmd - b[i]);
         if (exd <= 0) exd = 0;
         LL pt2 = base * l[i] + exd * u[i];
         tmp += pt2;
         sumA = max(sumA, tmp);
     }
     //printf("ans = %lld sumA = %lld sumB = %lld\n", ans, sumA, sumB);
     return sumA >= sumB;
}

