class Problem_Solver{
private:
    using LLi = long long int;
    using datum = std::tuple<int, LLi, LLi>;
    const int n, X;
    lli sum_lost_score;
    std::vector<datum> D;
    // S[i] := i個まで全て選んだ時の増加得点
    std::vector<LLi> S;
public:
    Problem_Solver(int nn, int XX):n(nn),X(XX){
        D.resize(n); S.resize(n);
    };
    // 入力を行う
    void input(){
        sum_lost_score = 0;
        REP(i, n){
            // 得点は -bl => uX - ubに変化
            int b, l, u; scanf("%d%d%d", &b, &l, &u);
            D[i] = {b, l, u};
            sum_lost_score += static_cast<LLi>(b) * l;
        }
        // ついでにソート
        std::sort(D.begin(), D.end(), [&](datum a, datum b){
            int aB, bB; lli aL, aU, bL, bU;
            std::tie(aB, aL, aU) = a;
            std::tie(bB, bL, bU) = b;
            // 増加得点は uX - b(u-l)
            return aU*X-aB*(aU-aL) > bU*X-bB*(bU-bL);
        });
    }
    // 前処理
    void previous(){
        S[0] = 0;
        REP(i, n){
            int b; lli l, u;
            std::tie(b, l, u) = D[i];
            // 増加得点は uX - b(u-l)
            S[i+1] = S[i] + u * X - b * (u - l);
        }
    }
    // k個で可能か判定
    bool possible(lli k)const{
        int idx = k / X; int amari = k - idx * X;
        if(S[idx] >= sum_lost_score) return true;
        lli need = sum_lost_score - S[idx];
        for(; idx < n; ++idx){
            int b; lli l, u;
            std::tie(b, l, u) = D[idx];
            // 余り個使ってできる増加得点
            lli MakeScore_WithAmari = (amari > b) ? u * amari - b * (u-l) : l * amari;
            //std::max(u * amari - b * (u-l), l * amari);
            if(MakeScore_WithAmari >= need){
                return true;
            }
        }
        return false;
    }
    // 答えを見つける
    LLi findAns()const{
        lli ng = -1, ok = n; ok *= X;
        while(ok - ng > 1){
            lli m = (ng + ok) / 2;
            if(possible(m)) ok = m;
            else ng = m;
        }
        return ok;
    }
    // 出力
    void solve(){
        this->previous();
        printf("%lld\n", this->findAns());
    }
};


int main(void){
    int n, X; scanf("%d%d", &n, &X);
    Problem_Solver AtCoder(n, X);
    AtCoder.input();
    AtCoder.solve();
    return 0;
}

