    struct Data {
        long b, l, u;
        Data(long b, long l, long u) : b(b), l(l), u(u) {}
        long max_score(long x) const {
            return (x-b)*u;
        }
    };
    vector<Data> datas;
    for (int i = 0; i < N; i++) {
        long b,l,u; cin>>b>>l>>u;
        datas.emplace_back(b,l,u);
    }
    sort(datas.begin(), datas.end(), [&](auto l, auto r) {return l.max_score(X) > r.max_score(X);});
    vector<long> uscore(N), lscore(N);
    uscore[0] = datas[0].b*datas[0].u;
    for (int i = 1; i < N; i++) {
        uscore[i] = uscore[i-1]+datas[i].b*datas[i].u;
    }
    lscore[N-1] = datas[N-1].b*datas[N-1].l;
    for (int i = N-2; i >= 0; i--) {
        lscore[i] = lscore[i+1]+datas[i].b*datas[i].l;
    }
    auto oppscore = [&](long i) {
        if (i == 0)
            return lscore[0];
        else if (i == N)
            return uscore[N-1];
        else
            return uscore[i-1] + lscore[i];
    };
    long ans = 0;
    long score = 0;
    for (int i = 0; i < N; i++) {
        auto needs = double(oppscore(i+1)-score)/datas[i].u;
        cerr << oppscore(i+1) << ' ' << score << endl;
        if (needs > X) {
            ans += X;
            score += X * datas[i].u;
        } else if (needs > datas[i].b) {
            ans += needs;
            break;
        } else {
            needs = double(oppscore(i)-score)/datas[i].l;
            cerr << oppscore(i) << ' ' << score << endl;
            ans += needs;
            break;
        }
        cerr << endl;
    }
    cout << ans << endl;

    return 0;
}

