struct BLU{
	int b;
	int l;
	int u;
};

int X;

int OtoX(BLU v){
	return v.l * v.b + v.u * (X - v.b);
}

auto compair(BLU a, BLU b){
	return OtoX(a) > OtoX(b);
}

int time(BLU v, int a){
	if(a < 0 || OtoX(v) < a){
		return inf;
	}
	int b = v.b, l = v.l, u = v.u;
	if(a <= l * b){
		return (a + l - 1) / l;
	}
	else{
		return b + (a - l * b + u - 1) / u;
	}
}

