void solve(long long N, long long X, std::vector<long long> b, std::vector<long long> l, std::vector<long long> u){
  ll lf=-1,rt=accumulate(b.begin(),b.end(),0LL);
  vector<pll> p;
  REP(N){
    p.push_back(pll(l[i]*b[i]+u[i]*(X-b[i]),i));
  }
  sort(p.begin(),p.end(),greater<pll>());
  vector<ll> sump;
  sump.push_back(0);
  REP(N){
    sump.push_back(sump.back()+p[i].first);
  }
  dump(p);
  dump(sump);
  ll bsum=0;
  REP(N){
    bsum+=b[i]*l[i];
  }
  while(lf+1<rt){
    ll mid=(lf+rt)/2;
    ll ans=0;
    if(mid%X)REP(N){
      ll sum=0;

      if(i<mid/X){
        sum=sump[mid/X+1]-p[i].first;
      }else{
        sum=sump[mid/X];
      }
      ll idx=p[i].second;
      if(mid%X<b[idx]){
        sum+=(mid%X)*l[idx];
      }else{
        sum+=(mid%X-b[idx])*u[idx]+b[idx]*l[idx];
      }
      ans=max(ans,sum);
      if(ans>=bsum)break;
    }
    else{
      ans=sump[mid/X];
    }
    if(ans>=bsum){
      rt=mid;
    }else{
      lf=mid;
    }
  }
  cout<<rt<<endl;
}

