int main(){
	LL n, x; cin >> n >> x;
	for (int i = 0; i < n; i++){
		cin >> b[i] >> l[i] >> u[i];
		totals[i] = l[i] * b[i] + (x - b[i]) * u[i];
	}
	LL target = 0;
	for (int i = 0; i < n; i++){
		target += l[i] * b[i];
	}

	//how many exams
	vector<score> scores;
	for (int i = 0; i < n; i++){
		scores.push_back(make_pair(totals[i], i));
	}
	sort(scores.begin(), scores.end());
	reverse(scores.begin(), scores.end());
	LL running_tot = 0;
	LL how_many = 0; 
	int cnt = 0;
	for (int i = 0; i < scores.size(); i++){
		running_tot += scores[i].first;
		if (running_tot > target){
			running_tot -= scores[i].first;
			break;
		}
		how_many += x;
		++cnt;
	}
	LL finres;
	LL resid = target - running_tot;
	if (resid == 0){
		cout << how_many << endl;
		return 0;
	}
	LL leftover = (x + 1);
	for (int i = cnt; i < n; i++){
		//how many do I need to get over resid
		if (totals[scores[i].second] < resid){
			continue;
		}
		else{
			if (resid <= l[scores[i].second] * b[scores[i].second]){
				LL needed = (resid - 1) / l[scores[i].second] + 1;
				leftover = min(leftover, needed);
			}
