				LL needed = b[scores[i].second] + 1 + (resid - (l[scores[i].second] * b[scores[i].second]) - 1) / (u[scores[i].second]);
				leftover = min(leftover, needed);
			}
		}
	}
	finres = leftover + how_many;

	running_tot += scores[cnt].first;
	assert(running_tot > target);
	//what's the most you can remove and keep it above x, so you want it low
	resid = running_tot - target;
	LL rem = 0;
	for (int i = 0; i <= cnt; i++){
		if (resid <= (x - b[scores[i].second]) * u[scores[i].second]){
			rem = max(rem, resid / u[scores[i].second]);
		}
		else{
			rem = max(rem, (resid - (x - b[scores[i].second]) * u[scores[i].second]) / l[scores[i].second] + (x - b[scores[i].second]));
		}
	}

	cout << min(finres, how_many + x - rem) << endl;


	//Case 1: be greedy, but get on the departing train

	//Case 2: only the largest k + 1 totals. 


}

