int main(){
  int N,X;
  cin >> N >> X;
  int b[N];
  int min[N];
  int max[N];
  int sum = 0;
  int count = 0;
  for(int i = 0;i < N;i++){
    cin >> b[i] >> min[i] >> max[i];
    sum += min[i] * b[i];
  }
  int num=0;
  int keep=0;
  while(1){
    for(int i=0;i<N;i++){
      if(keep < max[i]){
        num = i;
        keep = max[i];
      }
    }
    if(sum < sum - max[num] * X + b[num] * (max[num] -  min[num])){
      count += (sum + b[num] * (max[num] -  min[num])) / max[num]  + 1;
      break;
    }else{
      sum = sum - max[num] * X + b[num] * (max[num] -  min[num]);
      max[num] = 0;
      count += X;
      keep = 0;
    }
  }
  cout  << count;
}

