int main(){
	ans=Inf;
	scanf("%d%d",&n,&x);
	REP(i,n){
		scanf("%d%d%d",&b[i],&l[i],&r[i]);
		base+=1LL*l[i]*b[i];
		pq.push(mp(1LL*r[i]*(x-b[i])+1LL*l[i]*b[i],i)); 
