        sum[it] = sum[it - 1] + val(i);
    }
    llong s = 0, e = (llong)n * X;
    while (s < e) {
        llong m = (s + e) / 2;
        if (check(m)) e = m;
        else s = m + 1;
    }
    printf("%lld\n", s);
    return 0;
