inline bool check(ll k){
	int i,p,t;
	bool ok=0;
	ll ans=0;
	for(i=1;i<=n&&k>=(ll)x;++i){
		ans+=(ll)(x-a[i].b)*a[i].r;
		k-=x;
	}
	if(i>n)return 1;
	for(t=p=i++,ok=k>(ll)a[p].b;i<=n;++i)if(k>(ll)a[i].b){
		if(!ok||ok&&(k-a[i].b)*a[i].r>(k-a[p].b)*a[p].r)p=i;
		ok=1;
	}
	else if(a[i].l>a[p].l)p=i;
	if(k>(ll)a[p].b){
		int pp=1,j;
		for(j=2;j<=t;++j)if(a[pp].r>a[j].r)pp=j;
      	ans-=(ll)(x-a[pp].b)*a[pp].r;
