  std::vector<int64_t> b(n), l(n), u(n);

  std::set<std::pair<int64_t, int64_t>> q;

  int64_t dif = 0;
  for (int64_t i = 0; i < n; i++) {
    std::cin >> b[i] >> l[i] >> u[i];
    dif += l[i] * b[i];
    q.insert(std::make_pair(u[i] * (x - b[i]) + l[i] * b[i], i));
  }

  int64_t hour = 0;

  std::vector<bool> flag(n, false);

  for (auto itr = q.crbegin(); itr != q.crend(); itr++) {
    if (0 < dif) {
      dif -= itr->first;
      hour += x;
      flag[itr->second] = true;
    } else {
      break;
    }
  }

  if (dif != 0) {
    dif = -dif;
