using namespace std;

typedef pair<int, int> P;

class CTests {
public:
    static constexpr int kStressIterations = 0;

    static void generateTest(std::ostream& test) {
    }

    int N, X;
    int b[100005];
    int l[100005];
    int u[100005];
    int aoki = 0;
    vector<P> v;

    bool check(int p) {
        int k = p / X;
        int d = p % X;

        int sum = 0;
        REP(i, min(k, N)) {
            sum += v[i].first;
        }

        if (d > 0 && k < N) {
            int tmp = -INF;
            FOR(t, k, v.size() - 1) {
                int i = v[t].second;
                if (d > b[i]) {
                    tmp = max(tmp, u[i] * (d - b[i]) + l[i] * b[i]);
                } else {
                    tmp = max(tmp, l[i] * d);
                }
            }
            sum += tmp;
        }

        return sum >= aoki;
    }

    void solve(std::istream& cin, std::ostream& cout) {
        cin >> N >> X;

        REP(i, N) {
            cin >> b[i] >> l[i] >> u[i];
            aoki += l[i] * b[i];
        }
        v.resize(N);
        REP(i, N) {
            v[i] = {u[i] * (X - b[i]) + l[i] * b[i], i};
        }
        sort(v.begin(), v.end(), greater<P>());

        int low = 0;
        int high = INF;
        while (high - low > 1) {
            int mid = (high + low) / 2;
            if (check(mid)) {
                high = mid;
            } else {
                low = mid;
            }
        }
        cout << high << endl;
    }
};


