template< typename T >
struct PrioritySumStructure {
  static const bool INCREASE = false;
  static const bool DECREASE = true;

  bool order;
  int k, sz;
  T sum;
  multiset< T > add, pend;

  PrioritySumStructure(int k, bool order = INCREASE) : k(k), sum(0), sz(0), order(order) {}

  void sweep() {
    while(sz < k && !pend.empty()) {
      auto p = order ? --pend.end() : pend.begin();
      sum += *p;
      ++sz;
      add.emplace(*p);
      pend.erase(p);
    }
    while(sz > k) {
      auto p = order ? add.begin() : --add.end();
      sum -= *p;
      --sz;
      pend.emplace(*p);
      add.erase(p);
    }
  }

  T get_sum() {
    if(sz < k) throw ("Get Sum Exception");
    return sum;
  }

  void add_element(T x) {
    ++sz;
    add.emplace(x);
    sum += x;
    sweep();
  }

  void delete_element(T x) {
    if(pend.count(x)) {
      pend.erase(pend.find(x));
    } else if(add.count(x)) {
      --sz;
      sum -= x;
      add.erase(add.find(x));
      sweep();
    } else {
      throw ("Delete Element Exception");
    }
  }

  void increment_size() {
    ++k;
    sweep();
  }

  void decrement_size() {
    if(k == 0) throw ("Decrement Size Exception");
    --k;
    sweep();
  }
};


int main() {
  int N, X;
  cin >> N >> X;
  int64 loss = 0;
  vector< int64 > A(N), B(N), C(N);
  for(int i = 0; i < N; i++) {
    cin >> A[i] >> B[i] >> C[i];
    loss += B[i] * A[i];
  }

  auto get_cost = [&](int idx, int64 sum) {
    int64 add = 0;
    add += B[idx] * min(sum, A[idx]);
    add += C[idx] * max(0LL, sum - A[idx]);
    return add;
  };
  PrioritySumStructure< int64 > tap(1, true);
  vector< int64 > tekitou;
  for(int i = 0; i < N; i++) {
    tap.add_element(get_cost(i, X));
    tekitou.emplace_back(get_cost(i, X));
  }
  sort(tekitou.rbegin(), tekitou.rend());
  int64 ok = -1, ng = -1;
  int64 choku = 0;
  for(int i = 0; i < N; i++) {
    choku += tekitou[i];
    if(choku >= loss) {
      ng = 1LL * i * X;
      ok = 1LL * (i + 1) * X;
      break;
    }
  }


  auto check = [&](int64 sum) {
    int64 need = sum / X;
    while(need > tap.k) tap.increment_size();
    while(need < tap.k) tap.decrement_size();
    for(int i = 0; i < N; i++) {
      tap.delete_element(get_cost(i, X));
      bool f = tap.get_sum() + get_cost(i, sum % X) >= loss;
      tap.add_element(get_cost(i, X));
      if(f) return true;
    }
    return false;
  };
  while(ok - ng > 1) {
    auto mid = (ok + ng) / 2;
    if(check(mid)) ok = mid;
    else ng = mid;
  }
  cout << ok << endl;
}

