int main() {
    scanf("%d%d", &n, &x);
    ll need = 0;
    for(int i = 1; i <= n; i++) scanf("%d%d%d", &a[i].b, &a[i].l, &a[i].u), need += 1ll * a[i].b * a[i].l;
    // cerr << need << endl;
    if(need == 0) return puts("0"), 0;
    sort(a + 1, a + 1 + n, [&](query a, query b) {
        return 1ll * a.u * (x - a.b) + 1ll * a.l * a.b > 1ll * b.u * (x - b.b) + 1ll * b.l * b.b;
    });
    for(int i = 1; i <= n; i++) sum[i] = sum[i - 1] + 1ll * a[i].u * (x - a[i].b) + 1ll * a[i].l * a[i].b;
    ll ANS = 1e18;
    for(int i = 1; i <= n; i++) {
        int l = 0, r = n, ans;
        while(l <= r) {
            int mid = l + r >> 1;
            ll now = sum[mid];
            if(mid >= i) now -= 1ll * a[i].u * (x - a[i].b) + 1ll * a[i].l * a[i].b;
            if(now >= need - 1ll * a[i].u * (x - a[i].b) - 1ll * a[i].l * a[i].b) ans = mid, r = mid - 1;
            else l = mid + 1;
        }
        ll now = (ans - (ans >= i)) * x;
        ll rest = need - sum[ans];
        if(ans >= i) rest += 1ll * a[i].u * (x - a[i].b) + 1ll * a[i].l * a[i].b;
        ll tmp = min(1ll * a[i].b, (rest + a[i].l - 1) / a[i].l);
        tmp = max(0ll, tmp);
        now += tmp;
        rest -= tmp * a[i].l;
        if(rest > 0) tmp = min(1ll * x - a[i].b, (rest + a[i].u - 1) / a[i].u);
        else tmp = 0;
        now += tmp;
        rest -= tmp * a[i].u;
        // cerr << a[i].b << ' ' << now << ' ' << rest << ' ' << ans << endl;
        assert(rest <= 0);
        // if(rest > 0) continue;
        ANS = min(ANS, now);
    }
    assert(ANS <= 1e15);
    // cerr << sum[1] << endl;
    return cout << ANS << endl, 0;
}

