using T=tuple<int64_t,int>;

int main(){
    int N,X;
    cin>>N>>X;
    vector<int> B(N),L(N),U(N);
    for(int i=0;i<N;i++){
        cin>>B[i]>>L[i]>>U[i];
    }
    function<bool(int)> test = [&](int64_t sum){
        vector<T> V;
        for(int i=0;i<N;i++){
            V.emplace_back(U[i]*(X-B[i])+L[i]*B[i],i);
        }
        sort(V.begin(), V.end(),greater<T>());
        int64_t total=0;
        for(int i=0;i<N;i++){
            int idx;
            tie(ignore,idx)=V[i];
            if(i<sum/X){
                total+=U[idx]*(X-B[idx]);
            }else if(sum%X&&i==sum/X){
                total+=max(U[idx]*(sum%X-B[idx]),L[idx]*(sum%X-B[idx]));
            }else{
                total+=-L[idx]*B[idx];
            }

        }
        return total>=0;
    };
    int64_t lb=0,ub=X*N;
    while(ub-lb>1){
        int64_t mid=(lb+ub)/2;
        if(test(mid)){
            ub=mid;
        }else{
            lb=mid;
        }
    }
    cout<<ub<<endl;
    return 0;
}

