inline bool check(ll x){
	ll a=x/X,b=x%X;
	if(a == n) return ans+sf[a] >= 0;
	go(i,n+1,1){
		ll ss=ans;
		if(i <= a){
			if(b <= p[i].b) ss=ss+sf[a+1]-p[i].f+b*p[i].l;
			else ss=ss+sf[a+1]-p[i].f+p[i].b*p[i].l+(b-p[i].b)*p[i].r;
		}
		else{
			if(b <= p[i].b) ss=ss+sf[a]+b*p[i].l;
			else ss=ss+sf[a]+p[i].b*p[i].l+(b-p[i].b)*p[i].r;
		}
		if(ss >= 0) return 1;
	}
	return 0;
}

void pre(){
	go(i,n+1,1) p[i].f=(ll)(X-p[i].b)*p[i].r+p[i].b*p[i].l,ans=ans-p[i].b*p[i].l;
	sort(p+1,p+n+1);
	go(i,n+1,1) sf[i]=sf[i-1]+p[i].f;
}

