	go(i,n+1,1)
		p[i].b=rd(),p[i].l=rd(),p[i].r=rd(),r=r+p[i].b;
	pre();
	while(l <= r){
		ll mid=l+r>>1;
		if(check(mid)) res=mid,r=mid-1;
		else l=mid+1;
	}
	printf("%lld",res);
	return 0;
}

