                tmp = sum_d[sub_x];
            }
            int j = d[i-1].second;
            if(b[j] < rem){
                tmp += (rem-b[j])*u[j] + b[j]*l[j];
            }else{
                tmp += rem*l[j];
            }
            if(tmp >= sum_bl){
                f = 1;
                break;
            }
        }
        // cout << mid << " : " << tmp << " " << sum_bl << endl;
        if(f) ok = mid;
        else ng = mid;
    }
    cout << ok << endl;

}

