    Exam exams[n];
    for (int i = 0; i < n; i++) {
        long b, l, u;
        cin >> b >> l >> u;
        exams[i] = Exam {b, l, u, x};
        b_sum += b;
    }

    long lb = -1, ub = b_sum;
    sort(exams, exams + n);
    long plus_acc[n + 1], minus_acc[n + 1];
    plus_acc[0] = minus_acc[0] = 0;
    for (int i = 1; i <= n; i++) {
        Exam e = exams[i - 1];
        plus_acc[i]  = plus_acc[i - 1]  + (x - e.b) * e.u;
        minus_acc[i] = minus_acc[i - 1] - e.b * e.l;
    }
    while (ub - lb > 1) {
