ll read() {
  ll res = 0, w = 1; char c = getchar();
  while (!isdigit(c) && c != '-') c = getchar();
  if (c == '-') c = getchar(), w = -1;
  while (isdigit(c)) res = (res << 1) + (res << 3) + c - '0', c = getchar();
  return res * w;
}

const ll N = 1e5 + 10;

ll n, x, L[N], R[N], b[N], vis[N];

priority_queue<pi> q; 

bool check(ll mid) {
  ll A = mid / x, B = mid % x, id = 0;
  if (!B) A--, B = x;
  ll res = -1e12, tmp = 0; 
  for (ll i = 1; i <= n; i++) {
    if (vis[i] <= A) {
      tmp += 1ll * (x - b[i]) * R[i];
    } else {
      tmp -= 1ll * b[i] * L[i];
      if (vis[i] == A + 1) {
        id = i;
      }
    }
  }
  for (ll i = 1; i <= n; i++) {
    if (vis[i] <= A) {
      ll now = tmp - 1ll * (x - b[i]) * R[i] + 1ll * (x - b[id]) * R[id] + 1ll * b[id] * L[id];
      now += 1ll * (B - b[i]) * ((B >= b[i]) ? R[i] : L[i]);
      res = max(res, now);
    } else {
      ll now = tmp + 1ll * b[i] * L[i];
      now += 1ll * (B - b[i]) * ((B >= b[i]) ? R[i] : L[i]);
      res = max(res, now);  
    }
  }
//  cout << mid << " " << A << " " << B << " " << res << endl;
  return res >= 0;
}

