#endif
  n = read(), x = read();
  for (ll i = 1; i <= n; i++) {
    b[i] = read(), L[i] = read(), R[i] = read();
  }
  for (ll i = 1; i <= n; i++) {
    q.push(pi(1ll * (x - b[i]) * R[i], i));
  }
  for (ll i = 1; i <= n; i++) {
    pi cur = q.top(); q.pop();
    vis[cur.second] = i;
//    cout << cur.second << " " << i << endl;
  }
  ll l = 0, r = 1ll * n * x - 1, res = r + 1;
