using ar3 = array<ll, 3>;

int main()
{
	int N, X;
	cin >> N >> X;
	vector<ar3> info(N);
	REP(i, N)REP(j, 3)cin >> info[i][j];

	priority_queue<pll> pq;
	REP(i, N) {
		auto ar = info[i];
		ll b = ar[0];
		ll l = ar[1];
		ll u = ar[2];
		ll score = X * u - b * u;// - b * l;
		pq.push({ score, i });
	}

	ll mlevel = 0;
	ll level = 0;
	for (auto ar : info) {
		level += ar[0] * ar[1];
	}

	ll res = 0;
	vector<int> cands;
	while (true) {
		auto now = pq.top(); pq.pop();
		ll idx = now.second;
		ll b = info[idx][0];
		ll l = info[idx][1];
		ll u = info[idx][2];

		ll me = mlevel + X * u;
		ll tlevel = level + b * (u - l);
		if (me < tlevel) {
			res += X;
			mlevel = me;
			level = tlevel;
		}
		else {
			cands.push_back(idx);
			while (!pq.empty()) {
				cands.push_back(pq.top().second);
				pq.pop();
			}
			break;
		}
	}

	ll best = INF;
	for (auto cand : cands) {
		ll b = info[cand][0];
		ll l = info[cand][1];
		ll u = info[cand][2];

		ll opp = level + b * (u - l);
		ll tmp = (opp - mlevel);
		ll me = tmp / u + (tmp%u == 0 ? 0 : 1);
		best = min(best, me);
	}

	for (auto cand : cands) {
		ll b = info[cand][0];
		ll l = info[cand][1];
		ll u = info[cand][2];

		ll opp = level;
		ll tmp = (opp - mlevel);
		ll me = tmp / l + (tmp%l == 0 ? 0 : 1);
		best = min(best, me);
	}

	cout << res + best << endl;
	return 0;
}

