struct st{
	long long int b;
	long long int l;
	long long int u;
	inline long long int calc(long long int x){
		if(x<=b){
			return l*x;
		}
		long long int add=l*b;
		x-=b;
		return add+u*x;
	}
};

vector<st> v;

long long int cur;



inline bool check(long long int cnt){
	//long long int need=cur;
	long long int choose=cnt%x;
	vector<pair<long long int,int> > vv;
	for(int i=0;i<n;i++){
		vv.push_back(make_pair(v[i].b*v[i].l+(x-v[i].b)*v[i].u,i));
	}
	sort(vv.begin(),vv.end(),greater<pair<long long int,int> >() );
	long long int complete=cnt/x;
	if(choose==0LL){
		long long int ret=0;
		for(int j=0;j<complete;j++){
			ret+=vv[j].first;
		}
		return ret>=cur;
	}
	long long int ret=0;
	for(int j=0;j<complete;j++){
		ret+=vv[j].first;
	}
	for(int i=0;i<vv.size();i++){
		long long int tmp=ret;
		if(i<complete){
			tmp-=vv[i].first;
			tmp+=vv[complete].first;
		}
		int idx=vv[i].second;
		tmp+=v[idx].calc(choose);
		if(tmp>=cur)return true;
	}
	return false;
}

