long long gao(const int &id, const long long &v)
{
	if(v < 0)
		return oo;
	if(b[id] * l[id] >= v)
		return v == 0 ? 0 : (v - 1) / l[id] + 1;
	long long nv = v + b[id] * u[id] - b[id] * l[id];
	if(x * u[id] > nv)
		return oo;
	return nv == 0 ? 0 : (nv - 1) / u[id] + 1;
}
