int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n, x; cin >> n >> x;
    vector<tuple<ll, ll, ll>> blu(n);
    REP(i, n) {
        ll b, l, u; cin >> b >> l >> u;
        blu[i] = make_tuple(b, l, u);
    }

    ll ng = -1, ok = 1e11;
    while (ok - ng > 1) {
        ll md = (ok + ng) / 2;
        (max_score(blu, x, md) >= 0 ? ok : ng) = md;
    }
    say(ok);

}

