    }
    std::sort(s,s+n,cmp);
    long long ans=n*x,l=0,r=n*x;

    while(l<=r){
        int mid=(l+r)/2;
        if (check(mid)){
            ans=mid;r=mid-1;
        }
        else l=mid+1;
    }
