using namespace std;
#define rep(i,n) for(int i=0;i<int(n);++i)
#define all(a) (a).begin(),(a).end()
typedef long long ll;

int main(void){
    int n;
    ll x;
    cin >> n >> x;
    vector<ll> b(n),l(n),r(n);
    rep(i,n){
        cin >> b[i] >> l[i] >> r[i];
    }

    vector<int> ord(n);
    iota(all(ord), 0);
    auto cosper = [&](int i){
        return r[i]*(x-b[i]) + b[i]*l[i];
    };
    sort(all(ord), [&](int i, int j){
        return cosper(i) > cosper(j);
    });

    ll L = -1, R = x*n+1;
    while (L+1 < R) {
        ll M = (L+R)/2;
        auto win = [&](ll m) {
            ll sumA = 0, sumB = 0;
            rep(i_,n){
                int i = ord[i_];
                if (m >= b[i]) {
                    sumA += r[i] * min(x,m);
                    sumB += r[i] * b[i];
                    m -= min(x,m);
                } else {
                    sumA += l[i] * m;
                    sumB += l[i] * b[i];
                    m = 0;
                }
            }
            return sumA >= sumB;
        };

        if (win(M)) {
            R = M;
        } else {
            L = M;
        }
    }
    cout << R << endl;

    return 0;
}

