int main() {
	int n, x;
	ignore = scanf("%d %d", &n, &x);
	for (int i = 0; i < n; i++) ignore = scanf("%d %d %d", b + i, l + i, u + i);

	vector<pair<long long, int>> vec;
	for (int i = 0; i < n; i++) {
		vec.emplace_back((x - b[i]) * 1ll * u[i] + b[i] * 1ll * l[i], i);
	}

	sort(vec.begin(), vec.end());
	reverse(vec.begin(), vec.end());

	long long ans = -1;
	for (long long p = (1LL << 40); p > 0; p /= 2) {
		long long full = (ans + p) / x;
		int leftover = (ans + p) % x;

		if (full >= n) continue;

		fill(c, c + n, -1);

		long long sum = 0;
		for (int i = 0; i < full; i++) {
			int j = vec[i].second;
			c[j] = u[j];
			sum += u[j] * 1ll * (x - b[j]);
		}

		for (int i = 0; i < n; i++) {
			if (c[i] != -1) continue;
			sum -= l[i] * 1ll * b[i];
		}

		if (leftover == 0) {
			if (sum < 0) ans += p;
			continue;
		}

		bool win = false;
		for (int i = 0; i < n; i++) {
			long long cur = 0;
			if (c[i] != -1) {
				int j = vec[full].second;

				cur -= c[i] * 1ll * (x - b[i]);
				cur += l[j] * 1ll * b[j];
				cur += u[j] * 1ll * (x - b[j]);
			}
			else {
				cur += l[i] * 1ll * b[i];
			}

			c[i] = leftover > b[i] ? u[i] : l[i];
			cur += c[i] * 1ll * (leftover - b[i]);
			if (sum + cur >= 0) win = true;
		}

		if (win == false) ans += p;
	}

	printf("%lld\n", ans + 1);

	return 0;
}

