int main() {
	ios_base::sync_with_stdio(0);
	cin.tie(0);

	int n, x;
	cin >> n >> x;
	vector<int> his(n), lower(n), upper(n);
	REP(i, n)
		cin >> his[i] >> lower[i] >> upper[i];
	D << I(n) << I(x) << I(his) << I(lower) << I(upper);

	auto gain = [&](int i, int h) -> L {
		return max(lower[i] * L(h), L(lower[i] - upper[i]) * his[i] + h * L(upper[i]));
	};
	REP(i, n)
		D << I(i) << I(gain(i, x));

	L initScore = 0;
	REP(i, n)
		initScore -= lower[i] * L(his[i]);
	D << I(initScore);
	vector<int> bestPerm(n);
	iota(bestPerm.begin(), bestPerm.end(), 0);
	sort(bestPerm.rbegin(), bestPerm.rend(), [&](int i, int j) {
		if(gain(i, x) == gain(j, x))
			return i < j;
		return gain(i, x) < gain(j, x);
	});
	D << I(bestPerm);

	auto goodScore = [&](L mxH) {
		int pref = int(mxH / x);
		int remainder = int(mxH % x);

		L gainSum = 0;
		REP(i, pref)
			gainSum += gain(bestPerm[i], x);
		L mx = 0;
		FOR(i, pref, n - 1)
			mx = max(mx, gain(bestPerm[i], remainder));
		gainSum += mx;
		D << I(mxH) << I(initScore + gainSum) << I(mx);
		return initScore + gainSum >= 0;
	};

	L l = 0, r = n * L(x);
	while(l != r) {
		L m = (l + r) / 2;
		if(goodScore(m))
			r = m;
		else
			l = m + 1;
	}
	cout << r << '\n';
}

