#define int long long

struct blu{
	int b;
	int l;
	int u;
};

int X;

bool comp(const blu &x, const blu &y){
	if((x.u * (X - x.b) + x.l * x.b) != (y.u * (X - y.b) + y.l * y.b)){
		return (x.u * (X - x.b) + x.l * x.b) < (y.u * (X - y.b) + y.l * y.b);
	}
	else if(x.l != y.l){
		return x.l > y.l;
	}
	else{
		return x.b < y.b;
	}
}

signed main(){
	int N, i, j;
	scanf("%lld%lld", &N, &X);
	vector<blu> blus(N);
	for(i = 0; i < N; i++){
		scanf("%lld%lld%lld", &blus[i].b, &blus[i].l, &blus[i].u);
	}
	sort(blus.begin(), blus.end(), comp);
	vector<int> sum(N + 1, 0), val(N + 1, 0);
	for(i = N - 1; i >= 0; i--){
		int b = blus[i].b, l = blus[i].l, u = blus[i].u;
		val[i] = u * (X - b) + l * b;
		sum[i] = sum[i + 1] + u * (X - b) + l * b;
	}
	int now = 0;
	for(i = 0; i < N; i++){
		now -= blus[i].l * blus[i].b;
	}
//	printf("now = %lld\n", now);
	int ans = 0;
	for(i = 0; i < N; i++){
		int ll = 0, rr = N, h, v;
		while(rr - ll > 1){
			h = (ll + rr) / 2;
			v = sum[h];
			if(h <= i){
				v -= val[i];
			}
			if(v + val[i] + now >= 0){
				ll = h;
			}
			else{
				rr = h;
			}
		}
		int b = blus[i].b, l = blus[i].l, u = blus[i].u;
		v = sum[rr];
		if(rr <= i){
			v -= val[i];
		}
		int d = v;
		int mini = X;
		if(now + l * b >= 0){
			mini = min(mini, (d + l - 1) / l);
		}
		else{
			int dd = d - l * b;
			mini = min(mini, b + (dd + u - 1) / u);
		}
		int nn = N - rr;
		if(rr <= i){
			nn--;
		}
		ans = min(ans, nn * X + mini);
	}

	printf("%lld\n", ans);
	return 0;
}

