    for(int i=1;i<=N;i++){
        sum[i]=sum[i-1]+S[i-1].r*(X-S[i-1].b)+S[i-1].b*S[i-1].l;
    }

    ll ans=INF;
    for(int i=0;i<N;i++){
        ll diff=S[i].r*(X-S[i].b)+S[i].b*S[i].l;
        auto it=upper_bound(all(sum),need);
        ll re=it-sum.begin()-1;
        if(re<i) continue;

        if(S[i].b*S[i].l>=need-((*it)-diff)){
            ans=min(ans,re*X+(need-((*it)-diff)+S[i].l-1)/S[i].l);
            //cout<<re<<" "<<(need-((*it)-diff)+S[i].l-1)/S[i].l<<endl;
        }else{
            ans=min(ans,re*X+(need+S[i].b*(S[i].r-S[i].l)-((*it)-diff)+S[i].r-1)/S[i].r);
        }
    }

    cout<<ans<<endl;
}

