      if(keep < max[i]){
        num = i;
        keep = max[i];
      }
    }
    if(sum < sum - max[num] * X + b[num] * (max[num] -  min[num])){
      count += (sum + b[num] * (max[num] -  min[num])) / max[num]  + 1;
      break;
    }else{
      sum = sum - max[num] * X + b[num] * (max[num] -  min[num]);
      max[i] =0;
      count += X;
    }
  }
}

