int N;
LL X;
struct node {
    LL b;
    LL lb;
    LL ub;
    LL mx;
} input[112345];
LL mxs[112345];
LL MX(int l, int r) { return mxs[r] - mxs[l]; }
LL border = 0;
bool check(LL num) {
    LL ret     = 0;
    const LL K = num / X;
    const LL k = num % X;
    for (int i : range(K)) {
        LL ans = MX(0, K + 1) - MX(i, i + 1);
        if (k >= input[i].b) {
            ans += input[i].lb * input[i].b + input[i].ub * (k - input[i].b);
        }
        else {
            ans += input[i].lb * k;
        }
        chmax(ret, ans);
    }
    for (int i : range(K, N)) {
        LL ans = MX(0, K);
        if (k >= input[i].b) {
            ans += input[i].lb * input[i].b + input[i].ub * (k - input[i].b);
        }
        else {
            ans += input[i].lb * k;
        }
        chmax(ret, ans);
    }

    return ret >= border;
}
int main() {
    cin >> N >> X;
    LL ok = 0, ng = -1;
    for (int i : range(N)) {
        cin >> input[i].b >> input[i].lb >> input[i].ub;
        border += input[i].b * input[i].lb;
        ok += input[i].b;
        input[i].mx = input[i].b * input[i].lb + (X - input[i].b) * input[i].ub;
    }
    sort(input, input + N,
         [](const node& l, const node& r) { return l.mx > r.mx; });
    for (int i : range(N)) {
        mxs[i + 1] = mxs[i] + input[i].mx;
    }
    while (ok - ng > 1) {
        const LL md           = (ok + ng) / 2;
        (check(md) ? ok : ng) = md;
    }
    cout << ok << endl;
    return 0;
}

