using namespace std;
using ll = long long;
using ii = pair<int, int>;
using pl = pair<ll, ll>;
constexpr int MN = 1e5+5;

ll N, X, goal, b[MN], l[MN], u[MN];
bitset<MN> used;

bool solve(int M) {
	priority_queue<pl> pq;
	for (int i = 0; i < N; ++i) pq.emplace(X*u[i]-b[i]*u[i]+b[i]*l[i], i);

	ll sum = 0, cost = 0;
	used.reset();
	for (int i = 0; i < M/X; ++i) {
		sum += pq.top().f;
		cost += X;
		used[pq.top().s] = 1;
		pq.pop();
	}
	for (int i = 0; i < N; ++i) {
		if (used[i]) {
			if (sum-(X*u[i]-b[i]*u[i]+b[i]*l[i])+((M-cost)*u[i]-b[i]*u[i]+b[i]*l[i])+pq.top().f >= goal
			 || sum-(X*u[i]-b[i]*u[i]+b[i]*l[i])+(M-cost)*l[i]+pq.top().f >= goal) return 1;
		}
		else {
			if (sum+(M-cost)*u[i]-b[i]*u[i]+b[i]*l[i] >= goal
			 || sum+(M-cost)*l[i] >= goal) return 1;
		}
	}
	return 0;
}

int main() {
    if (fopen("in", "r")) freopen("in", "r", stdin), freopen("out", "w", stdout);
    ios_base::sync_with_stdio(0), cin.tie(0);

	cin >> N >> X;
	for (int i = 0; i < N; ++i) cin >> b[i] >> l[i] >> u[i];

	for (int i = 0; i < N; ++i) goal += b[i]*l[i];

	ll x = 0, y = N*X;
	while (x < y) {
		ll m = (x+y)/2;
		solve(m) ? y = m : x = m+1;
	}
	cout << y;
}

