long long int p[1005];
int asc(const void* a, const void* b)
{
	if (p[*(int*)a] < p[*(int*)b])return 1;
	if (p[*(int*)a] > p[*(int*)b])return -1;
	return 0;
}
int main()
{
	long long int n, x;
	scanf("%lld %lld", &n, &x);
	long long int i;
	long long int b[1005], l[1005], u[1005];
	for (i = 0; i < n; i++)
		scanf("%lld %lld %lld", &b[i], &l[i], &u[i]);
	int c[1005];
	for (i = 0; i < n; i++)
		c[i] = i;
	long long int sum = 0;
	for (i = 0; i < n; i++)
		sum -= b[i] * l[i];
	for (i = 0; i < n; i++)
		p[i] = u[i] * (x - b[i]) + l[i] * b[i];
	qsort(c, n, sizeof(int), asc);
	long long int ans = 0;
	i = 0;
	while (sum < 0)
	{
		if (sum + p[c[i]] < 0)
		{
			sum += p[c[i]];
			ans += x;
		}
