    val (b, l, u) = readLine()!!.split(" ").map { it.toLong() }
    Test(b, l, u)
  })
  var currentDiff = tests.map { -it.l * it.b }.sum()
  fun maxGain(test: Test): Long = test.l * test.b + test.u * (x - test.b)
  tests.sortByDescending { maxGain(it) }

  var ans = 0L
  for (i in 0 until n) {
    if (currentDiff + maxGain(tests[i]) <= 0) {
      ans += x
      currentDiff += maxGain(tests[i])
    } else {
      val min1 = (i until n).filter { currentDiff + maxGain(tests[it]) >= 0 }
          .map {
            if (tests[i].l * tests[i].b >= -currentDiff) {
              (-currentDiff + tests[i].l - 1) / tests[i].l
            } else {
              tests[i].b + (-currentDiff - tests[i].l * tests[i].b + tests[i].u - 1) / tests[i].u
            }
          }
          .min()!!
      if (min1 < 0) throw RuntimeException()
      var min2 = x
      for (k in 0 until i) {
        val tmpDiff = currentDiff + maxGain(tests[i]) - maxGain(tests[k])
        val a = if (tests[k].l * tests[k].b >= -tmpDiff) {
          (-tmpDiff + tests[k].l - 1) / tests[k].l
        } else {
          tests[k].b + (-tmpDiff - tests[k].l * tests[k].b + tests[k].u - 1) / tests[k].u
        }
        if (a <= x) {
          min2 = Math.min(min2, a)
        }
      }
      if (min2 < 0) throw RuntimeException()
      ans += Math.min(min1, min2)
      break
    }
  }

  // if (currentScore < 0) throw RuntimeException()

  println(ans)
}

import java.util.*;
import java.io.*;

public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        long x = sc.nextLong();

        Long[][] t = new Long[n][4]; // b, l, u
        long aSum = 0;      // sum b * l
        for(int i=0; i<n; i++){
            t[i][0] = sc.nextLong();
            t[i][1] = sc.nextLong();
            t[i][2] = sc.nextLong();
            t[i][3] = x * t[i][2] - t[i][0] * (t[i][2] - t[i][1]);
            aSum += t[i][0] * t[i][1];
        }

        Arrays.sort(t, new Comparator<Long[]>() {
            @Override
            public int compare(Long[] a, Long b[]){
                int ret = 0;
                if(a[3] > b[3]) ret = -1;
                else if(a[3] < b[3]) ret = 1;

                return ret;
            }

        });

        long ans = 0;

        int i;
        for(i = 0; i<n; i++){
            aSum -= t[i][3];
            ans += x;
            if(aSum <= 0){
                aSum += t[i][3];
                ans -= x;
                break;
            }
        }

        long min = x;
        for(int j=0; j<n; j++){
            long masum = aSum;
            if(j < i){
                masum += t[j][3] -t[i][3];
            }
            long mmin = x;
            if(t[j][0] * t[j][1] >= aSum){
                mmin = aSum / t[j][1];
                if(aSum % t[j][1] > 0) mmin++;
            }else{
                mmin = (aSum + t[j][0] * (t[j][2] - t[j][1])) / t[j][2];
                if((aSum + t[j][0] * (t[j][2] - t[j][1])) % t[j][2] > 0) mmin++;
            }

            min = Math.min(min, mmin);
        }

        ans += min;

        System.out.println(ans);


    }

    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }else{
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }else if(b == -1 || !isPrintableChar(b)){
                    return minus ? -n : n;
                }else{
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
    }
}

