public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		C_Tests solver = new C_Tests();
		solver.solve(1, in, out);
		out.close();
	}

	static class C_Tests {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			long x = in.nextInt();
			Test[] tests = new Test[n];
			long need = 0;
			for (int i = 0; i < n; i++) {
				Test t = new Test();
				t.b = in.nextInt();
				t.l = in.nextInt();
				t.u = in.nextInt();
				tests[i] = t;

				need += t.b * t.l;
			}

			Arrays.sort(tests, (u, v) -> (-Long.compare(u.profitAt(x), v.profitAt(x))));
			long[] prefix = new long[n + 1];
			for (int i = 0; i < n; i++) {
				prefix[i + 1] = prefix[i] + tests[i].profitAt(x);
			}
			long l = -1;
			long r = x * n;
			while (r - l > 1) {
				long m = l + (r - l) / 2;
				long best = 0;
				for (int fixed = 0; fixed < n; fixed++) {
					long cur = tests[fixed].profitAt(m % x);
					int other = (int) (m / x);
					cur += prefix[other];
					if (fixed < other) {
						cur -= tests[fixed].profitAt(x);
						if (other < n) {
							cur += tests[other].profitAt(x);
						}
					}
					best = Math.max(best, cur);
				}
				if (need <= best) {
					r = m;
				} else {
					l = m;
				}
			}
			out.println(r);
		}

		class Test {
			long b;
			long l;
			long u;

			long profitAt(long n) {
				long ls = Math.min(n, b);
				long us = n - ls;
				return ls * l + us * u;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

