    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int x = in.readInt();
            int[] b = new int[n];
            int[] l = new int[n];
            int[] u = new int[n];
            in.readIntArrays(b, l, u);
            long aokiScore = 0;
            for (int i = 0; i < n; i++) {
                aokiScore += (long) l[i] * b[i];
            }
            long[] takaScore = new long[n];
            for (int i = 0; i < n; i++) {
                takaScore[i] = (long) l[i] * b[i] + (long) (x - b[i]) * u[i];
            }
            long answer = (long) x * n;
            int[] order = ArrayUtils.order(takaScore);
            ArrayUtils.reverse(order);
            long[] cumScore = new long[n + 1];
            int at = 0;
            for (int i : order) {
                cumScore[at + 1] = cumScore[at] + takaScore[i];
                at++;
            }
            int[] pos = ArrayUtils.reversePermutation(order);
            long add = x;
            int specialPos = Arrays.binarySearch(cumScore, aokiScore);
            if (specialPos < 0) {
                specialPos = -specialPos - 2;
            }
            answer = (long) specialPos * x;
            if (cumScore[specialPos] == aokiScore) {
                out.printLine(answer);
                return;
            }
            for (int i = 0; i < n; i++) {
                long current;
                if (pos[i] < specialPos) {
                    current = cumScore[specialPos + 1] - takaScore[i];
                } else {
                    current = cumScore[specialPos];
                }
                long curScore = aokiScore - current;
                long cand;
                if (curScore <= (long) l[i] * b[i]) {
                    cand = (curScore + l[i] - 1) / l[i];
                } else {
                    cand = b[i] + (curScore - (long) l[i] * b[i] + u[i] - 1) / u[i];
                }
                add = Math.min(add, cand);
            }
            answer += add;
            out.printLine(answer);
        }

    }

    static abstract class IntAbstractStream implements IntStream {
        public String toString() {
            StringBuilder builder = new StringBuilder();
            boolean first = true;
            for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
