public class Main {

  static FastScanner sc = new FastScanner();

  static int[] dx = {0, 1, 0, -1};
  static int[] dy = {-1, 0, 1, 0};

  static long MOD = (long) (1e9 + 7);

  int N;
  long X;

  public static void main(String[] args) {

    new Main().run();

  }

  public void run() {

    N = sc.nextInt();
    X = sc.nextLong();

    Test[] tests = new Test[N];
    for (int i=0; i<N; i++) {
      tests[i] = new Test(sc.nextLong(), sc.nextLong(), sc.nextLong());
    }

    Arrays.sort(tests, (o1, o2) -> o2.fullContribute - o1.fullContribute > 0 ? 1 : -1);

    long[] fullContributes = new long[N+1];
    fullContributes[0] = 0;
    for (int i=1; i<=N; i++) {
      fullContributes[i] = fullContributes[i-1] + tests[i-1].fullContribute;
    }

    long defaultScore = 0;
    for (int i=0; i<N; i++) {
      defaultScore -= tests[i].b * tests[i].l;
    }

    long high = N * X + 1;
    long low = -1;
    long mid = (high + low) / 2;

    while (high - low > 1) {
      long maxScore = defaultScore;
      if (mid % X == 0) {
        maxScore = defaultScore + fullContributes[(int)(mid / X)];
      } else {
        for (int i = 0; i < N; i++) {
          long score = defaultScore;
          score += tests[i].contribute(mid % X);
          if (mid >= X) {
            score += fullContributes[(int)(mid / X)];
            if (i <= mid / X - 1) {
              score -= tests[i].fullContribute;
              score += tests[(int)(mid / X)].fullContribute;
            }
          }
          maxScore = Math.max(maxScore, score);
        }
      }
      if (maxScore >= 0) {
        high = mid;
      } else {
        low = mid;
      }
      mid = (high + low) / 2;
    }

    System.out.println(high);

  }

  public class Test {
    long b, l, u;
    long fullContribute;
    public Test(long b, long l, long u) {
      this.b = b;
      this.l = l;
      this.u = u;
      fullContribute = contribute(X);
    }
    public long contribute(long a) {
      if (a <= b) {
        return l * a;
      } else {
        return l * b + u * (a - b);
      }
    }
  }

