public class Main {
    private static FastScanner sc = new FastScanner();
    private static boolean DEBUG_FLG = false;

    public static void main(String[] args) {
    	int N = sc.nextInt();
    	long X = sc.nextLong();
    	Test[] test = new Test[N];
    	long bsum = 0;
    	for(int i=0; i<N; i++) {
    		test[i] = new Test(sc.nextLong(), sc.nextLong(), sc.nextLong());
    		test[i].maxDim = test[i].u * X - (test[i].u - test[i].l) * test[i].b;
    		bsum += test[i].l * test[i].b;
    	}
    	Arrays.sort(test, (a, b) -> b.maxDim - a.maxDim > 0 ? 1 : -1);
    	long ans = 0;
    	for(int i=0; i<N; i++) {
    		if(test[i].maxDim <= bsum) {
    			bsum -= test[i].maxDim;
    			ans += X;
    		} else {
    			long mintime = X;
    			for(int j=i; j<N; j++) {
    				if(test[j].maxDim < bsum) break;
    				long t1 = (long)Math.ceil((double)bsum / (double)test[j].l);
    				if(t1 < mintime) {
    					mintime = t1;
    				}
    				long t2 = (long)Math.ceil((double)(bsum + (test[j].u - test[j].l) * test[j].b) / (double)test[j].u);
    				if(t2 < mintime) {
    					mintime = t2;
    				}
    			}

    			bsum -= test[i].maxDim;
    			for(int j=i-1; j>=0; j--) {
    				long bsumtmp = bsum +  test[j].maxDim;
    				long t1 = (long)Math.ceil((double)bsumtmp / (double)test[j].l);
    				if(t1 < mintime) {
    					mintime = t1;
    				}
    				long t2 = (long)Math.ceil((double)(bsumtmp + (test[j].u - test[j].l) * test[j].b) / (double)test[j].u);
    				if(t2 < mintime) {
    					mintime = t2;
    				}
    			}

    			ans += mintime;
    			break;
    		}

    		if(bsum == 0) break;
    	}

    	System.out.println(ans);
    }

    static class Test {
    	long b;
    	long l;
    	long u;
    	long maxDim;
