    static class CTests {
        long[] b;
        long[] l;
        long[] u;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int x = in.nextInt();
            b = new long[n];
            l = new long[n];
            u = new long[n];
            for (int i = 0; i < n; i++) {
                b[i] = in.nextLong();
                l[i] = in.nextLong();
                u[i] = in.nextLong();
            }

//        Score[] score = new Score[n];
//        for (int i = 0; i < n; i++) {
//            score[i] = new Score(i, (x - b[i]) * u[i]);
//        }
//        Arrays.sort(score);

            long low = -1, high = x * (long) n;
            while (high - low > 1) {
                long mid = (low + high) / 2;
                long sum = 0;
                int max = (int) (mid / x);

                Score[] scores = new Score[n];
                Score[] scores2 = new Score[n];
                for (int i = 0; i < n; i++) {
                    scores[i] = new Score(i, f(i, x) - f(i, 0));
                    scores2[i] = new Score(i, f(i, mid % x) - f(i, 0));
                    sum += f(i, 0);
                }

                Arrays.sort(scores);
                Arrays.sort(scores2);

                boolean[] vis = new boolean[n];
                for (int i = 0; i < max; i++) {
                    vis[scores[i].index] = true;
                    sum += scores[i].score;
                }
                for (int i = 0; i < n; i++) {
                    if (!vis[scores2[i].index]) {
                        sum += scores2[i].score;
                        break;
                    }
                }

                if (sum >= 0) high = mid;
                else low = mid;
            }
            out.println(high);
        }

        long f(int index, long a) {
            long d = a - b[index];
            if (d > 0) return d * u[index];
            return d * l[index];
        }

        class Score implements Comparable<Score> {
            final int index;
            final long score;

            Score(int index, long score) {
                this.index = index;
                this.score = score;
            }

            public int compareTo(Score o) {
                return -Long.compare(score, o.score);
            }

        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

