    long[][] p = new long[n][3];

    for (int i = 0; i < n; i++) {
      p[i][0] = ni(); // b
      p[i][1] = ni(); // l
      p[i][2] = ni(); // u
    }


    Arrays.sort(p, (o1, o2) -> {
      long v1 = (x - o1[0]) * o1[2] + o1[0] * o1[1];
      long v2 = (x - o2[0]) * o2[2] + o2[0] * o2[1];
      return Long.compare(v2, v1);
    });

     long ok = Long.MAX_VALUE / 20;
     long ng = -1;

    while (ok - ng > 1) {
      long k = (ok + ng) / 2;

      if (ok(k, x, p)) {
        ok = k;
      } else {
        ng = k;
      }
    }
    System.out.println(ok);
  }

  private static boolean ok(long y, long x, long[][] p) {
    int n = p.length;

    long maxL = 0;
    long score = 0;
    for (int i = 0; i < n; i++) {
      if (y >= x) {
        score += (x - p[i][0]) * p[i][2];
        y -= x;
