        score += -p[i][0] * p[i][1];

        long nowL = (y - p[i][0]) * (y < p[i][0] ? p[i][1] : p[i][2]) + (p[i][0] * p[i][1]);
        if (maxL < nowL) {
          maxL = nowL;
        }
      }

    }
    score += maxL;
    return score >= 0;

