    long dif = 0;
    for (int i=0; i<N; i++) {
      tests[i] = new Test(sc.nextInt(), sc.nextInt(), sc.nextInt());
      dif -= tests[i].b * tests[i].l;
    }

    Arrays.sort(tests, new Comparator<Test>() {
      @Override
      public int compare(Test o1, Test o2) {
        return o2.calc(Test.X) - o1.calc(Test.X);
      }
    });

    long[] sum = new long[N+1];
    sum[0] = 0;
    for (int i=0; i<N; i++) {
      sum[i+1] = sum[i] + tests[i].calc(Test.X);
    }

    int high = Test.X * N;
    int low = 0;

    int ans = (high + low) / 2;

    while (high - low > 1) {
      int q = ans / Test.X;
      int r = ans - q*Test.X;

      long maxD = Integer.MIN_VALUE;
      for (int i=0; i<N; i++) {
        long d = dif;
        d += tests[i].calc(r);
        if (i < q) {
          d += sum[q+1] - tests[i].calc(Test.X);
        } else {
          d += sum[q];
        }
        maxD = Math.max(maxD, d);
      }

      if (maxD >= 0) {
        high = ans;
      } else {
        low = ans;
      }

      ans = (high + low) / 2;
    }

    System.out.println(high);

  }

  public static class Test {
    public static int X;
    int b, l, u;
    Test(int b, int l, int u) {
      this.b = b;
      this.l = l;
      this.u = u;
    }
    int calc(int len) {
      if (len < b) {
        return l * len;
      } else {
        return l * b + u * (len - b);
      }
    }
  }

