/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CTests solver = new CTests();
        solver.solve(1, in, out);
        out.close();
    }

    static class CTests {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            long x = in.nextInt();

//        long[] b = new long[n];
//        long[] l = new long[n];
//        long[] u = new long[n];
            CTests.Test[] tests = new CTests.Test[n];
            for (int i = 0; i < n; i++) {
//            b[index] = in.nextInt();
//            l[index] = in.nextInt();
//            u[index] = in.nextInt();
                tests[i] = new CTests.Test(in.nextInt(), in.nextInt(), in.nextInt());
            }

            long startingScore = 0;
            for (CTests.Test t : tests) {
                startingScore += -t.l * t.b;
            }

            long finalStartingScore = startingScore;
            Function<Long, Boolean> canWin = studyHours -> {
                Function<CTests.Test, Long> gainX = t -> (t.u * (x - t.b) - (-t.l * t.b));
                PriorityQueue<CTests.Test> q = new PriorityQueue<>(Comparator.comparingLong(t -> -gainX.apply(t)));

                long score = finalStartingScore;

                for (CTests.Test t : tests) {
                    q.add(t);
                }

                while (!q.isEmpty() && studyHours >= x) {
                    CTests.Test t = q.poll();
                    score += gainX.apply(t);
                    studyHours -= x;
//                System.out.println(score);
                }

                if (q.isEmpty()) {
                    return score >= 0;
                }

                final long lastStudyHours = studyHours;
                Function<CTests.Test, Long> gainPerPoint = t -> t.l;
                Function<CTests.Test, Long> gainIfDumpAll = t -> (t.u * (lastStudyHours - t.b) - (-t.l * t.b));
                PriorityQueue<CTests.Test> q2 = new PriorityQueue<>(Comparator.comparingLong(t -> -gainPerPoint.apply(t)));

                CTests.Test dumpItAll = q.peek();
                long dumpingGain = gainIfDumpAll.apply(dumpItAll);

                for (CTests.Test t : q) {
                    q2.add(t);
                    if (gainIfDumpAll.apply(t) > dumpingGain) {
                        dumpItAll = t;
                        dumpingGain = gainIfDumpAll.apply(t);
                    }
                }

                long salvagingGain = 0;
                while (!q2.isEmpty() && studyHours > 0) {
                    CTests.Test t = q2.poll();
                    salvagingGain += gainPerPoint.apply(t) * Math.min(studyHours, t.b);
                    studyHours -= Math.max(studyHours, t.b);
                }

                score += Math.max(salvagingGain, dumpingGain);
//            System.out.println(score + " " + salvagingGain + " " + dumpingGain);

                return score >= 0;
            };

            long answer = binarySearch(canWin);

            if (canWin.apply(0L)) {
                answer = 0;
            }

//        System.out.println(canWin.apply(101L));

            out.println(answer);
        }

        long binarySearch(Function<Long, Boolean> bigEnough) {
            long tooSmall = 0, tooBig;
            for (tooBig = 1; !bigEnough.apply(tooBig); tooBig *= 2) ;

            if (!bigEnough.apply(tooBig - 1)) {
                return tooBig;
            }

            while (tooBig - tooSmall > 1) {
                long center = (tooBig + tooSmall) / 2;
                if (!bigEnough.apply(center)) {
                    tooSmall = center;
                } else {
                    if (!bigEnough.apply(center - 1)) {
                        return center;
                    }
                    tooBig = center;
                }
            }

            return tooBig;
        }

        static class Test {
            final long b;
            final long l;
            final long u;

            Test(long b, long l, long u) {
                this.b = b;
                this.l = l;
                this.u = u;
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;


    class Exam implements Comparable<Exam> {
        int hisScore;
        int minCost, maxCost;
        long totalAdd;

        @Override
        public String toString() {
            return "Exam{" +
                    "hisScore=" + hisScore +
                    ", minCost=" + minCost +
                    ", maxCost=" + maxCost +
                    ", totalAdd=" + totalAdd +
                    '}';
        }

        public Exam(int hisScore, int minCost, int maxCost, int maxScore) {
            this.hisScore = hisScore;
            this.minCost = minCost;
            this.maxCost = maxCost;
            totalAdd = hisScore * 1L * minCost + (maxScore - hisScore) * 1L * maxCost;
        }

        @Override
        public int compareTo(Exam exam) {
            if (totalAdd != exam.totalAdd) {
                return -Long.compare(totalAdd, exam.totalAdd);
            }
            return -Integer.compare(minCost, exam.minCost);
        }

        long getCost(long needPoints) {
            if (needPoints > totalAdd) {
                throw new AssertionError();
            }
            if (needPoints == 0) {
                return 0;
            }
            if (minCost * 1L * hisScore >= needPoints) {
                return 1 + (needPoints - 1) / minCost;
            }
            needPoints -= hisScore * 1L * minCost;
            if (needPoints == 0) {
                return hisScore;
            }
            return hisScore + 1 + (needPoints - 1) / maxCost;
        }
    }

    void solve() {
        int n = in.nextInt();
        int maxScore = in.nextInt();
        Exam[] a = new Exam[n];
        long sumHisScore = 0;
        for (int i = 0; i < n; i++) {
            a[i] = new Exam(in.nextInt(), in.nextInt(), in.nextInt(), maxScore);
            sumHisScore += a[i].minCost * 1L * a[i].hisScore;
        }
        Arrays.sort(a);
//        System.err.println(Arrays.toString(a));
//        System.err.println("him = " + sumHisScore);
        long[] prefSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefSum[i + 1] = prefSum[i] + a[i].totalAdd;
        }
        long res = Long.MAX_VALUE;
        for (int notFully = 0; notFully < n; notFully++) {
            if (prefSum[notFully] + a[notFully].totalAdd < sumHisScore) {
                continue;
            }
//            System.err.println(notFully +"!");
            int l = -1, r = notFully;
            while (r - l > 1) {
                int mid = (l + r) >> 1;
                if (prefSum[mid + 1] <= sumHisScore) {
                    l = mid;
                } else {
                    r = mid;
                }
            }
            if (prefSum[r] + a[notFully].totalAdd < sumHisScore) {
                continue;
            }
            long needMore = sumHisScore - prefSum[r];
            long alreadyCost = maxScore * 1L * r;
            long cost = alreadyCost + a[notFully].getCost(needMore);
            res = Math.min(res, cost);
        }
        out.println(res);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {

        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                st = new StringTokenizer(s);
            }
            return st.nextToken();
        }

        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                st = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

import java.util.*;
import java.io.*;

public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();
        long x = sc.nextLong();

        Long[][] t = new Long[n][4]; // b, l, u
        long aSum = 0;      // sum b * l
        for(int i=0; i<n; i++){
            t[i][0] = sc.nextLong();
            t[i][1] = sc.nextLong();
            t[i][2] = sc.nextLong();
            t[i][3] = x * t[i][2] - t[i][0] * (t[i][2] - t[i][1]);
            aSum += t[i][0] * t[i][1];
        }

        Arrays.sort(t, new Comparator<Long[]>() {
            @Override
            public int compare(Long[] a, Long b[]){
                int ret = 0;
                if(a[3] > b[3]) ret = -1;
                else if(a[3] < b[3]) ret = 1;

                return ret;
            }

        });

        long lans = 0;
        long rans = n * x;
        out: while(rans > lans+1){
            long mans = (lans + rans) / 2;
            long rem = mans % x;
            for(int i=0; i<n; i++){
                long masum = aSum;
                if(rem <= t[i][0]){
                    masum -= rem * t[i][1];
                }else{
                    masum -= rem * t[i][2] - t[i][0] * (t[i][2] - t[i][1]);
                }
                long count = mans / x;
                for(int j=0; j<count; j++){
                    if(i == j){
                        count++;
                    }else{
                        masum -= t[j][3];
                    }
                }
                if(masum <= 0){
                    rans = mans;
                    continue out;
                }
            }

            lans = mans;
        }

        System.out.println(rans);

    }

    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }else{
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }else if(b == -1 || !isPrintableChar(b)){
                    return minus ? -n : n;
                }else{
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
    }
}

