import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		C_Tests solver = new C_Tests();
		solver.solve(1, in, out);
		out.close();
	}

	static class C_Tests {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			long x = in.nextInt();
			Test[] tests = new Test[n];
			long need = 0;
			for (int i = 0; i < n; i++) {
				Test t = new Test();
				t.b = in.nextInt();
				t.l = in.nextInt();
				t.u = in.nextInt();
				tests[i] = t;

				need += t.b * t.l;
			}

			long ans = 0;
			Arrays.sort(tests, (u, v) -> (-Long.compare(u.profitAt(x), v.profitAt(x))));
			for (int i = 0; i < n; i++) {
				if (need <= 0) {
					break;
				}
				if (need > tests[i].profitAt(x)) {
					need -= tests[i].profitAt(x);
					ans += x;
					continue;
				}
				long best = Long.MAX_VALUE;
				for (int j = i; j < n; j++) {
					long l = -1;
					long r = x;
					while (r - l > 1) {
						long m = l + (r - l) / 2;
						if (need <= tests[j].profitAt(m)) {
							r = m;
						} else {
							l = m;
						}
					}
					if (need <= tests[j].profitAt(r)) {
						best = Math.min(best, r);
					}
				}
				ans += best;
				break;
			}
			out.println(ans);
		}

		class Test {
			long b;
			long l;
			long u;

			long profitAt(long n) {
				long ls = Math.min(n, b);
				long us = n - ls;
				return ls * l + us * u;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.util.Scanner;
import java.util.Arrays;
import java.util.Comparator;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n =sc.nextInt();
		int x = sc.nextInt();
		long goal=0;
		long ans=0;
		th[] tt=new th[n];
		for(int i=0; i<n; i++){
			int b= sc.nextInt();
			int l=sc.nextInt();
			int u=sc.nextInt();
			tt[i]=new th(l,u,b);
			goal+=b*l;
		}
		Arrays.sort(tt,Comparator.comparing(th::getU).reversed());
		for(int i=0; i<n; i++){
			if((x-tt[i].b)*tt[i].u<goal-tt[i].b*tt[i].l){
				ans+=x;
				goal-=tt[i].b*tt[i].l+(x-tt[i].b)*tt[i].u;
			}else{
				goal-=tt[i].b*tt[i].l;
				goal+=tt[i].b*tt[i].u;
				ans+=goal/tt[i].u;
				if(goal%tt[i].u!=0){
					ans++;
				}
				break;
			}
		}
		System.out.println(ans);
	}
	static class th{
		public int l;
		public int u;
		public int b;
		th(int l,int u,int b){
			this.l=l;
			this.u=u;
			this.b=b;
		}
		public int getU(){
			return this.u;
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

public class Main {
	static long X;

	public static void main(String[] args) throws IOException {
		MyScanner sc = new MyScanner();
		PrintWriter out = new PrintWriter(System.out);
		int N = sc.nextInt();
		X = sc.nextInt();
		List<Exam> all = new ArrayList<>(N);
		long target = 0;
		for (int i = 0; i < N; i++) {
			long tmpb = sc.nextInt();
			long tmpl = sc.nextInt();
			long tmpu = sc.nextInt();
			all.add(new Exam(tmpb, tmpl, tmpu));
			target += tmpb * tmpl;
		}
		Collections.sort(all);
		long[] acums = new long[N+1];
		for (int i = 1; i <= N; i++) {
			acums[i] = acums[i-1] + all.get(i-1).tot;
		}
		long left = -1, right = X * N;
		while (left + 1 < right) {
			long med = (left + right) / 2;
			long complete = med / X;
			long got = acums[(int)complete];
			long rem = med % X;
			long best = got;
			if (rem > 0) {
				long extra = all.get((int)complete).tot;
				long real;
				for (int i = 0; i < N; i++) {
					Exam cur = all.get(i);
					real = got + cur.getVal(rem);
					if (i < complete) real += extra - cur.tot;
					best = Math.max(best, real);
				}
			}
			if (best >= target) right = med;
			else left = med;
		}
		out.println(right);

		out.flush();
	}

	static class Exam implements Comparable<Exam> {
		long b, l, u, tot;

		public Exam(long b, long l, long u) {
			this.b = b;
			this.l = l;
			this.u = u;
			tot = b * l + (X - b) * u;
		}

		public long getVal(long hours) {
			long ret = hours * l;
			if (hours > b) {
				ret += (hours - b) * (u - l);
			}
			return ret;
		}

		@Override
		public int compareTo(Exam o) {
			return Long.compare(o.tot, tot);
		}
	}

	static class MyScanner {
		private BufferedReader br;
		private StringTokenizer tokenizer;

		public MyScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() {
			while (tokenizer == null || !tokenizer.hasMoreTokens()) {
				try {
					tokenizer = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return tokenizer.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

		public long nextLong() {
			return Long.parseLong(next());
		}
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		long x = in.nextInt();
		long[] b = new long[n];
		long[] l = new long[n];
		long[] u = new long[n];
		long B = 0;
		for(int i=0;i<n;i++) {
			b[i] = in.nextInt();
			l[i] = in.nextInt();
			u[i] = in.nextInt();
			B += b[i] * l[i];
		}
		List<long[]> list = new ArrayList<>();
		for(int i=0;i<n;i++) {
			long[] tmp = new long[3];
			tmp[0] = i;
			tmp[1] = l[i]*b[i] + u[i]*(x-b[i]);
			list.add(tmp);
		}
		list.sort((e1,e2)->e1[1]>e2[1]?-1:1);
		long ans = 0;
		int idx = 0;
		while(idx<n&&B>list.get(idx)[1]) {
			B -= list.get(idx)[1];
			list.get(idx)[2] = x;
			ans += x;
			idx++;
		}
		for(;idx<n;idx++) {
			long[] tmp = list.get(idx);
			if(tmp[1]<B) {
				tmp[2] = x;
			}
			if(B<b[(int) tmp[0]]*l[(int) tmp[0]]) {
				tmp[2] = B/l[(int) tmp[0]];
				tmp[2] += B%l[(int) tmp[0]]==0?0:1;
			}else {
				tmp[2] = b[(int) tmp[0]] + (B-b[(int) tmp[0]]*l[(int) tmp[0]])/u[(int) tmp[0]];
				tmp[2] += (B-b[(int) tmp[0]]*l[(int) tmp[0]])%u[(int) tmp[0]]==0?0:1;
			}
		}
		list.sort((e1,e2)->e1[2]<e2[2]?-1:1);
		ans += list.get(0)[2];
		System.out.println(ans);
		in.close();

