 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		C_Tests solver = new C_Tests();
		solver.solve(1, in, out);
		out.close();
	}

	static class C_Tests {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			long x = in.nextInt();
			Test[] tests = new Test[n];
			long need = 0;
			for (int i = 0; i < n; i++) {
				Test t = new Test();
				t.b = in.nextInt();
				t.l = in.nextInt();
				t.u = in.nextInt();
				tests[i] = t;

				need += t.b * t.l;
			}

			long ans = 0;
			Arrays.sort(tests, (u, v) -> (-Long.compare(u.profitAt(x), v.profitAt(x))));
			for (int i = 0; i < n; i++) {
				if (need <= 0) {
					break;
				}
				if (need >= tests[i].profitAt(x)) {
					ans += x;
					need -= tests[i].profitAt(x);
					continue;
				}
				long best = Long.MAX_VALUE;
				for (int j = i; j < n; j++) {
					long l = -1;
					long r = x;
					while (r - l > 1) {
						long m = l + (r - l) / 2;
						if (need <= tests[j].profitAt(m)) {
							r = m;
						} else {
							l = m;
						}
					}
					if (need <= tests[j].profitAt(r)) {
						best = Math.min(best, r);
					}
				}
				ans += best;
				break;
			}
			out.println(ans);
		}

		class Test {
			long b;
			long l;
			long u;

			long profitAt(long n) {
				long ls = Math.min(n, b);
				long us = n - ls;
				return ls * l + us * u;
			}

		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

