                    for (long c : new long[]{tests[i].u, tests[i].l}) {
                        long required = -(b - c * tests[i].t);
                        long cnt = (required + c - 1) / c;
                        if (cnt > x || cnt < 0) continue;
                        ans = Math.min(ans, baseCost + cnt);
                    }
                }
                for (int i = margin; i < n; i++) {
                    long b = base + tests[i].t * tests[i].l;
                    for (long c : new long[]{tests[i].u, tests[i].l}) {
                        long required = -(b - c * tests[i].t);
                        long cnt = (required + c - 1) / c;
                        if (cnt > x || cnt < 0) continue;
                        ans = Math.min(ans, baseCost + cnt);
                    }
                }
            }

