                this.index = index;
                this.t = t;
                this.l = l;
                this.u = u;
            }

            long positive(int x) {
                return (x - t) * u;
            }

            long negative(int x, int type) {
                return type == 0 ? t * l : u * l;
            }

            long priority(int x, int type) {
                return positive(x) + negative(x, type);
