      this.b = b;
      this.l = l;
      this.u = u;
      fullContribute = contribute(X);
    }
    public long contribute(long a) {
      if (a <= b) {
        return l * a;
      } else {
        return l * b + u * (a - b);
      }
    }
  }

  public static class Mathf {

    public static int max(int[] a) {
