import java.io.BufferedReader;
import java.io.Reader;
import java.util.Comparator;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CTests solver = new CTests();
        solver.solve(1, in, out);
        out.close();
    }

    static class CTests {
        long[] b;
        long[] l;
        long[] u;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int x = in.nextInt();
            b = new long[n];
            l = new long[n];
            u = new long[n];
            for (int i = 0; i < n; i++) {
                b[i] = in.nextLong();
                l[i] = in.nextLong();
                u[i] = in.nextLong();
            }

            long[][] diff = new long[n][2];
            long sum = 0;
            for (int i = 0; i < n; i++) {
                diff[i][0] = f(i, x) - f(i, 0);
                diff[i][1] = i;
                sum += f(i, 0);
            }

            Arrays.sort(diff, Comparator.comparingLong(y -> -y[0]));

            long low = -1, high = x * (long) n;
            while (high - low > 1) {
                long mid = (low + high) / 2;
                int max = (int) (mid / x);
                long y = (int) (mid % x);

                long sumMax = 0;
                for (int i = 0; i < max; i++) {
                    sumMax += diff[i][0];
                }
                long ans = Long.MIN_VALUE;
                for (int i = 0; i < n; i++) {
                    if (i < max) {
                        int j = (int) diff[i][1];
                        long d = f(j, y) - f(j, 0);
                        ans = Math.max(ans, sum + sumMax - diff[i][0] + d + diff[max][0]);
                    } else {
                        int j = (int) diff[i][1];
                        long d = f(j, y) - f(j, 0);
                        ans = Math.max(ans, sum + sumMax + d);
                    }
                }

                if (ans >= 0) high = mid;
                else low = mid;
            }
            out.println(high);
        }

        long f(int index, long a) {
            long d = a - b[index];
            if (d > 0) return d * u[index];
            return d * l[index];
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.Scanner;
import java.util.Arrays;
import java.util.Comparator;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n =sc.nextInt();
		int x = sc.nextInt();
		long goal=0;
		long ans=0;
		th[] tt=new th[n];
		for(int i=0; i<n; i++){
			int b= sc.nextInt();
			int l=sc.nextInt();
			int u=sc.nextInt();
			tt[i]=new th(l,u,b);
			goal+=b*l;
		}
		Arrays.sort(tt,Comparator.comparing(th::getU).reversed());
		for(int i=0; i<n; i++){
			if((x-tt[i].b)*tt[i].u<goal-tt[i].b*tt[i].l){
				ans+=x;
				goal-=tt[i].b*tt[i].l+(x-tt[i].b)*tt[i].u;
			}else{
				goal-=tt[i].b*tt[i].l;
				goal+=tt[i].b*tt[i].u;
				ans+=goal/tt[i].u;
				break;
			}
		}
		System.out.println(ans);
	}
	static class th{
		public int l;
		public int u;
		public int b;
		th(int l,int u,int b){
			this.l=l;
			this.u=u;
			this.b=b;
		}
		public int getU(){
			return this.u;
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static long X;

	public static void main(String[] args) {
		int N = sc.nextInt();
		X = sc.nextInt();
		Exam[] exs = new Exam[N];
		for (int i = 0; i < N; i++) {
			long B = Long.parseLong(sc.next());
			long L = Long.parseLong(sc.next());
			long U = Long.parseLong(sc.next());
			exs[i] = new Exam(B, L, U);
		}
		Arrays.sort(exs);
		long point = 0;
		for (int i = 0; i < N; i++) {
			point += exs[i].b * exs[i].l;
		}
		int t = N;
		while (point > 0) {
			t--;
			point -= exs[t].value();
		}
		point += exs[t].value();
		t++;
		long base = (N - t) * X;
		long ans = Long.MAX_VALUE;
		for (int i = 0; i < t; i++) {
			long use = (point + exs[i].l - 1) / exs[i].l;
			ans = Math.min(ans, base + use);
			use = (point + exs[i].b * (exs[i].u - exs[i].l) + exs[i].u - 1) / exs[i].u;
			ans = Math.min(ans, base + use);
		}
		System.out.println(ans);
	}

	static class Exam implements Comparable<Exam> {
		long b, l, u;

		public Exam(long b, long l, long u) {
			this.b = b;
			this.l = l;
			this.u = u;
		}

		@Override
		public int compareTo(Exam o) {
			return Long.compare(this.value(), o.value());
		}

		long value() {
			return this.u * X - (this.u - this.l) * this.b;
		}
	}

}

