import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Comparator;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;
import java.util.PriorityQueue;

public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int n = ir.nextInt();
		long x = ir.nextLong();
		long[][] a = new long[n][];
		for (int i = 0; i < n; i++)
			a[i] = ir.nextLongArray(3);
		long lb = 1, ub = (long) 1e6;
		while (ub > lb + 1) {
			long mid = (ub + lb) / 2;
			if (ok(mid, n, x, a))
				lb = mid;
			else
				ub = mid;
		}
		PriorityQueue<long[]> pq = new PriorityQueue<>(new Comparator<long[]>() {
			public int compare(long[] A, long[] B) {
				return -Long.compare(A[1] - A[0], B[1] - B[0]);
			}
		});
		// tr(lb);
		long ct = 0, ct2 = 0;
		long mi = (long) 1e9, res = 0;
		for (int i = 0; i < n; i++) {
			if (a[i][2] < lb) {
				ct += a[i][0] * a[i][1];
			} else if (a[i][1] >= lb) {
				ct += a[i][0] * a[i][2];
				ct2 += x * a[i][2];
				mi = Math.min(mi, a[i][2]);
				res += x;
			} else {
				ct += a[i][0] * a[i][1];
				pq.add(new long[] { a[i][0] * (a[i][2] - a[i][1]), x * a[i][2], a[i][2], a[i][1] });
			}
		}
		// tr(lb, ct, ct2, res, mi);
		long r = 0;
		while (!(ct <= ct2)) {
			long[] m = pq.poll();
			if (ct + m[0] <= ct2 + m[1]) {
				r = res + ((ct - ct2) % m[3] == 0 ? (ct - ct2) / m[3] : (ct - ct2) / m[3] + 1);
			}
			ct += m[0];
			ct2 += m[1];
			res += x;
			mi = Math.min(mi, m[2]);
		}
		// tr(mi);
		out.println(Math.min(r, res - (ct2 - ct) / mi));
	}

	static boolean ok(long t, int n, long x, long[][] a) {
		long ct = 0, ct2 = 0;
		for (int i = 0; i < n; i++) {
			if (a[i][2] < t) {
				ct += a[i][0] * a[i][1];
			} else if (a[i][1] >= t) {
				ct += a[i][0] * a[i][2];
				ct2 += x * a[i][2];
			} else {
				ct += a[i][0] * a[i][2];
				ct2 += x * a[i][2];
			}
		}
		return ct <= ct2;
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		out.println(Arrays.deepToString(o));
	}
}

