    class C
    {
        static void Main(string[] args)
        {
            Method(args);
        }

        static void Method(string[] args)
        {
            int[] nx = ReadInts();
            long n = nx[0];
            long x = nx[1];

            long[][] blus = new long[n][];
            for (int i = 0; i < n; i++) blus[i] = ReadLongs();
            blus = blus.OrderBy(a => -((x - a[0]) * a[2] + a[0] * a[1])).ToArray();

            decimal need = 0;
            for (int i = 0; i < n; i++) need += blus[i][0] * blus[i][1];

            decimal[] sums = new long[n];
            sums[0] = blus[0][0] * blus[0][1] + (x - blus[0][0]) * blus[0][2];
            for (int i = 1; i < n; i++)
            {
                sums[i] = sums[i - 1]
                    + blus[i][0] * blus[i][1] + (x - blus[i][0]) * blus[i][2];
            }

            long bottom = -1;
            long top = n * x;
            while (bottom+1 < top)
            {
                long mid = (bottom+1 + top) / 2;
                long fullCnt = mid / x;
                long remain = mid % x;
                decimal now = fullCnt > 0 ? sums[fullCnt - 1] : 0;

                bool ok = now >= need;
                for (long i = fullCnt; i < n; i++)
                {
                    if (remain <= blus[i][0])
                    {
                        if (now + remain * blus[i][1] >= need)
                        {
                            ok = true;
                        }
                    }
                    else
                    {
                        if (now + (remain - blus[i][0]) * blus[i][2]
                            + blus[i][0] * blus[i][1] >= need)
                        {
                            ok = true;
                        }
                    }
                    if (ok) break;
                }

                if (ok) top = mid;
                else bottom = mid;
            }

            WriteLine(top);
        }

