    {
        return u * x - u * b + b * l;
    }
}
class Program
{
    static int n;
    static long x;
    static List<Test> tes;
    static void Main()
    {
        string[] input = Console.ReadLine().Split();
        n = int.Parse(input[0]);
        x = long.Parse(input[1]);
        tes = new List<Test>();
        for (int i = 0; i < n; i++)
        {
            input = Console.ReadLine().Split();
            long b = long.Parse(input[0]);
            long l = long.Parse(input[1]);
            long u = long.Parse(input[2]);
            tes.Add(new Test(b, l, u, x));
        }
        tes.Sort((p, q) => (p.Good() - q.Good() > 0) ? -1 : 1);
        //foreach (var t in tes)
        //{
        //    Console.Write("{0} {1} {2} {3}", t.b, t.l, t.u, t.Good());
        //    Console.WriteLine();
        //}
        long lost = 0;
        foreach (var t in tes)
            lost += t.l * t.b;
        long ans = 0;
        for (int i = 0; i < n; i++)
        {
            if (lost - tes[i].Good() > 0)
            {
                lost -= tes[i].Good();
                ans += x;
                continue;
            }
            long c = (lost + tes[i].u * tes[i].b - tes[i].l * tes[i].b) / tes[i].u;
            c += (lost + tes[i].u * tes[i].b - tes[i].l * tes[i].b) % tes[i].u != 0 ? 1 : 0;
            if (c >= tes[i].b)
            {
                ans += c;
                break;
            }
            c = lost / tes[i].l;
            c += lost % tes[i].l != 0 ? 1 : 0;
            ans += c;
            break;
        }
        Console.WriteLine(ans);
    }
}

