namespace Competitive
{
    internal class Solution
    {
        public long N, X;
        public long[] B, L, U;
        public long MOD = 1000000007;
        private Data[] D;

        private Data[] DU, DL;

        public void Run()
        {
            {
                var line = Input.ReadIntArray();
                N = line[0];
                X = line[1];
            }

            B = new long[N];
            L = new long[N];
            U = new long[N];

            var lst = new List<Data>();

            for (int i = 0; i < N; i++)
            {
                var line = Input.ReadIntArray();
                B[i] = line[0];
                L[i] = line[1];
                U[i] = line[2];

                Data D = new Data(B[i], L[i], U[i]);
                lst.Add(D);
            }

            D = lst.ToArray();
            DU = D.ToArray();
            DL = D.ToArray();
            Array.Sort(DU, (d1, d2) => d1.u.CompareTo(d2.u) * (-1));
            Array.Sort(DL, (d1, d2) => d1.l.CompareTo(d2.l) * (-1));

            long ret = Search();

            Console.WriteLine(ret);
        }

        public bool CanWin(long target)
        {
            long opponent = 0;
            long x = target;

            for (int i = 0; i < D.Length; i++)
            {
                D[i].used = false;
            }

            for (int i = 0; i < D.Length; i++)
            {
                // 相手
                opponent += D[i].b * D[i].l;
            }

            // Z個はフルでとれるのなら、Uの候補は(Z+1)個
            // ある候補を落とすのなら、それのLか、別のL

            int z = (int)(target / X + 1);
            z = Math.Min(z, D.Length);

            long over = z * X - target;
            long residual = X - over;

            // 候補はN個、うち1個はresidualにする
            // Console.Error.WriteLine($"target:{target} {z} {residual}");

            if(z == D.Length)
            {
                // いずれかを中途半端にする
                Data[] cand = DU.ToArray();
                long player = 0;

                long deduction = Int64.MaxValue;
                foreach (Data d in cand)
                {
                    long scoreX = d.b * d.l + (X - d.b) * d.u;
                    long scoreR = Math.Min(d.b, residual) * d.l + Math.Max(residual - d.b, 0) * d.u;
                    deduction = Math.Min(deduction, scoreX - scoreR);
                    player += scoreX;
                }

                player -= deduction;
                return player >= opponent;
            }
            else
            {

                Data[] cand = DU.Take(z).ToArray();
                foreach (var d in cand)
                {
                    d.used = true;
                }

                // Lが大きいもののうち、使っていないもの
                Data dl = null;
                foreach (Data d in DL)
                {
                    if (!d.used)
                    {
                        dl = d;
                        break;
                    }
                }

                // いずれかを中途半端にする
                long player = 0;
                long deduction = Int64.MaxValue;
                foreach (Data d in cand)
                {
                    long scoreX = Math.Min(d.b, X) * d.l + Math.Max(X - d.b, 0) * d.u;
                    long scoreR = Math.Min(d.b, residual) * d.l + Math.Max(residual - d.b, 0) * d.u;
                    long scoreL = Math.Min(dl.b, residual) * dl.l + Math.Max(residual - dl.b, 0) * dl.u;
                    deduction = Math.Min(deduction, scoreX - scoreR);
                    deduction = Math.Min(deduction, scoreX - scoreL);
                    player += scoreX;
                }

                player -= deduction;
                return player >= opponent;
            }

        }

        public long Search()
        {
            long left = 0;
            long right = N * X;

            if (CanWin(0)) return 0;
            if (!CanWin(N * X)) return N * X;

            while (left + 1 < right)
            {
                long mid = (left + right) / 2;
                // Console.Error.WriteLine($"MID {mid}");
                if (!CanWin(mid))
                {
                    left = mid;
                }
                else
                {
                    right = mid;
                }
            }
            return right;
        }

    }

