    Scanner cin;

    void calc()
    {
        cin = new Scanner();
        int N = cin.nextInt();
        long X = cin.nextInt();
        long[] b = new long[N];
        long[] l = new long[N];
        long[] u = new long[N];
        for (int i = 0; i < N; i++)
        {
            b[i] = cin.nextInt();
            l[i] = cin.nextInt();
            u[i] = cin.nextInt();
        }

        long need = 0;

        List<Tuple<long, int>> tp = new List<Tuple<long, int>>();
        for (int i = 0; i < N; i++)
        {
            need += b[i] * l[i];
            tp.Add(Tuple.Create((X - b[i]) * u[i] + b[i] * l[i], i));
        }

        long ans = 0;
        tp.Sort();
        tp.Reverse();

        bool[] used = new bool[N];
        int nexti = 0;
        foreach (var item in tp)
        {
            if (need < item.Item1) break;
            need -= item.Item1;
            ans += X;
            used[item.Item2] = true;
            nexti++;
        }


        if(need > 0)
        {
            long best = long.MaxValue / 10;

            for (int i = 0; i < N; i++)
            {
                long myNeed = need;

                if (used[i])
                {
                    myNeed -= tp[nexti].Item1;
                    myNeed += (X - b[i]) * u[i] + b[i] * l[i];
                }

                long tmp;
                if(myNeed <= l[i] * b[i])
                {
                    tmp = (myNeed + l[i] - 1) / l[i];
                }
                else
                {
                    long n2 = myNeed - l[i] * b[i];
                    tmp = b[i] + (n2 + u[i] - 1) / u[i];
                }
                best = Math.Min(best, tmp);
            }

            ans += best;
        }

        Console.WriteLine(ans);
    }
}




