            for (var i = 0; i < N; i++) pt += l[i] * b[i];

            var all = new List<Tuple<long, int>>();
            var allm = new long[N];
            all.Add(new Tuple<long, int>(0, -1));
            for(var i = 0; i < N; i++)
            {
                all.Add(new Tuple<long, int>(l[i] * b[i] + u[i] * (X - b[i]), i));
                allm[i] = l[i] * b[i] + u[i] * (X - b[i]);
            }
            all.Sort();
            for(var i = 0; i < N; i++)
            {
                int ind = all[i + 1].Item2;
                all[i + 1] = new Tuple<long, int>(all[i].Item1 + l[ind] * b[ind] + u[ind] * (X - b[ind]), ind);
            }

