                        nx = l[i] * b[i] + u[i] * (res - b[i]);
                    }
                    else
                    {
                        nx = l[i] * res;
                    }

                    if (used[i])
                    {
                        ret = Max(ret, sum - allm[i] + allm[all[N - (int)num].Item2] + nx);
                    }
                    else
                    {
                        ret = Max(ret, sum + nx);
                    }
                }
                if (ret >= pt) { R = mid; }
