                sums[i] = sums[i - 1]
                    + blus[i][0] * blus[i][1] + (x - blus[i][0]) * blus[i][2];
            }

            long bottom = 0;
            long top = n * x;
            long res = 0;
            while (bottom <= top)
            {
                long mid = (bottom + top) / 2;
                long fullCnt = mid / x;
                long remain = mid % x;
                long now = fullCnt > 0 ? sums[fullCnt - 1] : 0;

                bool ok = false;
                for (long i = fullCnt; i < n; i++)
                {
                    if (remain <= blus[i][0])
                    {
                        if (now + remain * blus[i][1] >= need)
                        {
                            ok = true;
                        }
                    }
                    else
                    {
                        if (now + (remain - blus[i][0]) * blus[i][2]
                            + blus[i][0] * blus[i][1] >= need)
                        {
                            ok = true;
                        }
                    }
                    if (ok) break;
