            }

            long player = 0;
            long over = cand.Count * X - target;

            long deduction = Int64.MaxValue;
            for (int i = 0; i < cand.Count; i++)
            {
                Data d = cand[i];
                long scoreX = d.b * d.l + (X - d.b) * d.u;
                long red = X - over;
                long scorex = Math.Min(d.b, red) * d.l + Math.Max(red - d.b, 0) * d.u;
                deduction = Math.Min(scoreX - scorex, deduction);
                player += scoreX;
            }

            if (over > 0)
            {
                player -= deduction;
            }

            return player >= opponent ? true : false;
        }

        public long Search()
        {
            long left = 0;
            long right = N * X;

            if (CanWin(0)) return 0;
            if (!CanWin(N * X)) return N * X;

            while (left + 1 < right)
            {
                long mid = (left + right) / 2;
                if (!CanWin(mid))
                {
                    left = mid;
                }
                else
                {
                    right = mid;
                }
            }
            return right;
        }

    }

