        }
        long ans = 0;
        long currentDiff = 0;
        for (int i = 0; i < N; i++) currentDiff += CalcBestDiff(l[i], u[i], b[i], 0); // all zero-point
        var p = E.Range(0, N)
            .Select(i => new { Value = CalcBestDiff(l[i], u[i], b[i], X) - CalcBestDiff(l[i], u[i], b[i], 0), Index = i })
            .OrderByDescending(a => a.Value)
            .ToArray();
        var rank = new int[N];
        for (int i = 0; i < p.Length; i++)
        {
            rank[p[i].Index] = i;
        }
        var sumUp = p.Select(a => a.Value).ToList();
        for (int i = 1; i < N; i++)
        {
            sumUp[i] += sumUp[i - 1];
        }

        long lower = 0, upper = 1L * X * N;
        while (lower <= upper)
        {
            var mid = (lower + upper) / 2;

            var maxUp = 0L;
            var all = (int)(mid / X);
            var remain = mid % X;

            if (remain == 0)
            {
                if (all > 0)
                {
                    maxUp = sumUp[all - 1];
                }
            }
            else
            {
                for (int i = 0; i < N; i++)
                {
                    var up = CalcBestDiff(l[i], u[i], b[i], remain) - CalcBestDiff(l[i], u[i], b[i], 0);
