                        {
                            up += sumUp[all] - (CalcBestDiff(l[i], u[i], b[i], X) - CalcBestDiff(l[i], u[i], b[i], 0));
                        }
                        else
                        {
                            up += sumUp[all - 1];
                        }
                    }
                    maxUp = Math.Max(maxUp, up);
                }
            }

            if (currentDiff + maxUp >= 0)
            {
                ans = mid;
                upper = mid - 1;
            }
            else
            {
                lower = mid + 1;
            }
        }

        cout.WriteLine(ans);
    }

    public long CalcBestDiff(long l, long u, long b, long x)
    {
        if (b == x) return 0;
        if (b < x) return u * (x - b);
        return l * (x - b);
    }
