            var tgtScore = 0L;
            foreach (var item in list)
            {
                pot.Add(Tuple.Create(((long)X - (long)item[0]) * (long)item[2], (long)item[1]));
                tgtScore += (long)item[0] * (long)item[1];
            }
            var rand = new Random();
            var potIdx = pot.Select((x, i) => new { x, i }).OrderBy(_ => rand.Next()).OrderByDescending(e => e.x).ToList();

