partial class Solver
{
    public void Run()
    {
        var N = ni();
        var X = ni();
        var b = new int[N];
        var l = new int[N];
        var u = new int[N];
        for (int i = 0; i < N; i++)
        {
            b[i] = ni();
            l[i] = ni();
            u[i] = ni();
        }
        long ans = 0;
        long currentDiff = 0;
        for (int i = 0; i < N; i++) currentDiff += CalcBestDiff(l[i], u[i], b[i], 0); // all zero-point
        if (currentDiff < 0)
        {
            var p = E.Range(0, N).ToArray();
            Array.Sort(p, (i, j) =>
            {
                var ip = CalcBestDiff(l[i], u[i], b[i], X) - CalcBestDiff(l[i], u[i], b[i], 0);
                var jp = CalcBestDiff(l[j], u[j], b[j], X) - CalcBestDiff(l[j], u[j], b[j], 0);
                return -ip.CompareTo(jp);
            });
            long lower = 0, upper = 1L * X * N;
            while (lower <= upper)
            {
                var mid = (lower + upper) / 2;

                var maxUp = 0L;
                var remain = mid;
                var isDone = new bool[N];

                foreach (var i in p)
                {
                    if (remain - X < 0) break;
                    var up = CalcBestDiff(l[i], u[i], b[i], X) - CalcBestDiff(l[i], u[i], b[i], 0);
                    remain -= X;
                    maxUp += up;
                    isDone[i] = true;
                }

                for (int i = 0; i < N; i++)
                {
                    if (isDone[i]) continue;
                    var up = CalcBestDiff(l[i], u[i], b[i], remain) - CalcBestDiff(l[i], u[i], b[i], 0);
                    if (currentDiff + maxUp + up >= 0)
                    {
                        maxUp += up;
                        break;
                    }
                }

                if (currentDiff + maxUp >= 0)
                {
                    ans = mid;
                    upper = mid - 1;
                }
                else
                {
                    lower = mid + 1;
                }
            }
        }

        cout.WriteLine(ans);
    }

    public long CalcBestDiff(long l, long u, long b, long x)
    {
        if (b == x) return 0;
        if (b < x) return u * (x - b);
        return l * (x - b);
    }
}

