            sums[0] = blus[0][0] * blus[0][1] + (x - blus[0][0]) * blus[0][2];
            for(int i = 1; i < n; i++)
            {
                sums[i] = sums[i - 1]
                    + blus[i][0] * blus[i][1] + (x - blus[i][0]) * blus[i][2];
            }

            long bottom = -1;
            long top = n * x;
            while (bottom + 1 < top)
            {
                long mid = (bottom + top + 1) / 2;
                long fullCnt = mid / x;
                long remain = mid % x;
                long now = fullCnt > 0 ? sums[fullCnt - 1] : 0;

                bool ok = false;
                for (long i = fullCnt; i < n; i++)
                {
                    if (ok) break;
                    if (remain <= blus[i][0])
                    {
                        if (now + remain * blus[i][1] >= need)
                        {
                            ok = true;
                        }
                    }
                    else
                    {
                        if (now + (remain - blus[i][0]) * blus[i][2]
                            + blus[i][0] * blus[i][1] >= need)
                        {
                            ok = true;
                        }
                    }
                }

                if (ok) top = mid;
                else bottom = mid;
            }

            WriteLine(top);
        }

