			A[i][2] = long.Parse(str2[2]);
		}
		Array.Sort(A,(x,y)=>((y[0]*y[1]+(X-y[0])*y[2])).CompareTo(x[0]*x[1]+(X-x[0])*x[2]));
		long[]S1 = new long[N+1];
		long[]S2 = new long[N+1];
		long[]S3 = new long[N+1];
		long[]S4 = new long[N+1];
      	long[]S5 = new long[N+1];
		long[]C = new long[N+1];
		for(var i=0;i<N;i++){
			S1[i+1] = S1[i]+X*A[i][2];
			C[i+1] = C[i]+X;
			S2[i+1] = S2[i]+A[i][0]*A[i][2];
			S4[i+1] = S4[i]+A[i][0]*A[i][1]+(X-A[i][0])*A[i][2];
          	S5[i+1] = S5[i]+A[i][0]*A[i][1];
		}
		for(var i=N-1;i>=0;i--){
			S3[i] = S3[i+1]+A[i][0]*A[i][1];
		}
		long ans = 999999999999999999;
		for(var i=0;i<N;i++){
			int min = 0;
			int max = N-1;
			while(min<max){
				int m = (min+max)/2;
				long sum;
				if(m>i){
					sum = S4[m+1]-S5[N];
				} else {
					sum = S4[m]-S5[N];
					sum += A[i][0]*A[i][1]+(X-A[i][0])*A[i][2];
				}
				if(sum>=0){
					max = m;
				} else {
					min = m+1;
				}
			}
			long s;
			if(min>i){
				s = S4[min+1]-S5[N] - (A[i][0]*A[i][1]+(X-A[i][0])*A[i][2]);
			} else {
				s = S4[min]-S5[N];
			}
			long cs = X*min;
			if(s<0){
				if(-s>A[i][0]*A[i][1]){
					cs += A[i][0]+(-s-A[i][0]*A[i][1]-1)/A[i][2]+1;
				} else {
					cs += (-s-1)/A[i][1]+1;
				}
			}
			ans = Math.Min(cs,ans);
		}
		Console.WriteLine(ans);
	}
}

