class Program
{
static string[] input = Console.ReadLine().Split(' ');
static int n = int.Parse(input[0]);
static int x = int.Parse(input[1]);
static long[,] vertexes = new long[n,3];
static long moreScore = 0;
static long[][] distincts = new long[n][];

	static void Main()
	{
    for(long i = 0; i < n; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      vertexes[i,0] = nums[0];
      vertexes[i,1] = nums[1];
      vertexes[i,2] = nums[2];
      distincts[i] = new long[2];
      distincts[i][0] = nums[2]*(x-nums[0]) + nums[1]*nums[0];
      distincts[i][1] = i;
    }
    Array.Sort(distincts, (a, b) => b[0].CompareTo(a[0]));

		Console.WriteLine(Search(0, n*x));
	}

  static long Search(long min, long max)//二分探索法で最小値を求める
  {
    while (true)
    {
      long mid = min + (max - min) / 2;
      if(Check(mid)) max = mid;//さらに小さくても成り立つかも
      else min = mid;

      if(max - min <= 1)
      {
        if(Check(min)) 
        {
          return min;//最小値で成り立つかの確認を優先
        }
        else
        {
          return max;
        }
      break;
      }  
    }
  }

  static bool Check(long testNum)
  {
    moreScore = 0;
    //Console.WriteLine(testNum+"?");

    for(int i = 0; i < n; i++)
    {  
      if(testNum >= x)
      {
        testNum -= x;
        moreScore += vertexes[distincts[i][1],2]*x;
        moreScore -= vertexes[distincts[i][1],2]*vertexes[distincts[i][1],0];
      }else if(testNum == 0)
      {
        moreScore -= vertexes[distincts[i][1],1]*vertexes[distincts[i][1],0];
      }else
      {
        if(vertexes[distincts[i][1],0] <= testNum)
        {
          moreScore += vertexes[distincts[i][1],2]*testNum;
          moreScore -= vertexes[distincts[i][1],2]*vertexes[distincts[i][1],0];
        }else
        {
          moreScore += vertexes[distincts[i][1],1]*testNum;
          moreScore -= vertexes[distincts[i][1],1]*vertexes[distincts[i][1],0];
        }

        testNum = 0;
      }
    }

    //Console.WriteLine(moreScore);

    if(moreScore >= 0) return true;
    return false;

  }

}

using System;
using System.Linq;

namespace CTests
{
    class Program
    {
        static void Main(string[] args)
        {
            // 入力の取得
            var inputNX = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int n = inputNX[0], x = inputNX[1];

            long totalMinScore = 0;
            Test[] tests = new Test[n];
            for (var i = 0; i < n; i++)
            {
                var test = Console.ReadLine().Split().Select(int.Parse).ToArray();
                tests[i] = new Test(test[0], x, test[1], test[2]);
                totalMinScore += tests[i].EnemyMinScore();
            }

            Array.Sort(tests);
            Array.Reverse(tests);

            long fullMarksCount = 0;
            while (fullMarksCount < n && tests[fullMarksCount].MaxAdvantage() <= totalMinScore)
            {
                totalMinScore -= tests[fullMarksCount].MaxAdvantage();
                fullMarksCount++;
            }

            long minScore = fullMarksCount == n ? 0 : int.MaxValue;
            for (var i = fullMarksCount; i < n; i++)
            {
                var necessary = tests[i].CalcNecessaryScore(totalMinScore);
                if (necessary < minScore) minScore = necessary;
            }

            var answer = fullMarksCount * x + minScore;

            // 解答の出力
            Console.WriteLine(answer);
        }
    }

    class Test : IComparable<Test>
    {
        readonly int baseScore, fullMarks, min, max;

        public Test(int baseScore, int fullMarks, int min, int max)
        {
            this.baseScore = baseScore;
            this.fullMarks = fullMarks;
            this.min = min;
            this.max = max;
        }

        public long EnemyMinScore()
        {
            return (long)baseScore * min;
        }

        public long MaxAdvantage()
        {
            return EnemyMinScore() + (long)(fullMarks - baseScore) * max;
        }

        public long CalcNecessaryScore(long requiredScore)
        {
            if (requiredScore <= EnemyMinScore())
            {
                return (long)Math.Ceiling((double)requiredScore / min);
            }
            else
            {
                var requiredAdvantage = requiredScore - EnemyMinScore();
                return (long)Math.Ceiling((double)requiredAdvantage / max) + baseScore;
            }
        }

        public int CompareTo(Test other)
        {
            return MaxAdvantage().CompareTo(other.MaxAdvantage());
        }
    }
}

