            (l, r) =>
            {
                    var comp = r.u.CompareTo(l.u);
                    if (comp == 0)
                    {
                        comp = r.l.CompareTo(l.l);
                        if (comp == 0)
                            comp = l.b.CompareTo(r.b);
                    }
                return comp;
            }
        );

        ulong score = 0;
        ulong time = 0;

        for (int i = 0; i < types.Length; ++i)
        {
            var t = types[i];
            var add_score = (ulong)x * t.u;
            var add_min = (ulong)t.b * (t.u - t.l);
            if (score + add_score < min + add_min)
            {
                score += add_score;
                min += add_min;
                time += x;
                continue;
            }
            var diff = min + add_min - score;
            time += (ulong)Math.Ceiling(diff / (double)t.u);
            break;
        }

        Console.WriteLine(time);
    }

    private static int Comb(int m, int n)
    {
        var t = m - n;
        if (n > t)
            n = t;

        long numerator = 1;
        for (int i = 0; i < n; ++i)
        {
            numerator *= m - i;
            numerator %= MOD_N;
        }
        long denominator = 1;
        for (; n != 0; --n)
        {
            denominator *= n;
            denominator %= MOD_N;
        }

        var inv_denominator = ModInv((int)denominator, MOD_N);
        var ret = (int)(numerator * inv_denominator % MOD_N);

        return ret >= 0 ? ret : ret + MOD_N;
    }

    private static int ModInv(int a, int m)
    {
        int b = m, x = 1, y = 0;
        while (b != 0)
        {
            var t = a / b;
            a -= t * b;
            Swap(ref a, ref b);
            x -= t * y;
            Swap(ref x, ref y);
        }
        x %= m;
        return x >= 0 ? x : x + m;
    }

    private static void Swap<T>(ref T a, ref T b)
    {
        var t = a;
        a = b;
        b = t;
    }
}

