static class P
{
    static void Main()
    {
        var n = Read();
        var X = Read();
        //捨てるテストは重要度l、勉強するテストは重要度uとする
        //取っていきたい勉強を決める
        //勉強する勉強を決め打つと楽になる
        //勉強するテストは全てbより多く勉強することは確定?いいえ
        //まず、限界までテストは勉強する(最後除く)bが点と同じなので
        //b未満の場合、重要度はuよりはlの方が良いことが分かる
        //もし他の勉強でuがl以上のものがあった場合はそれを優先したい
        //捨てたときのペナ-(b*l)と取ったときのコスト((x-b)*u)の差が大きい方から取り、全ペナの合計ギリギリまで詰める
        //最後はどれで詰めるかは全探索で良い(lで負の状態ながらケチケチ詰めるケースもあれば、uで正に飛ばしてぶっ飛ばすケースもある)
        var b = new long[n];
        var l = new long[n];
        var u = new long[n];
        for (int i = 0; i < n; i++)
        {
            b[i] = Read();
            l[i] = Read();
            u[i] = Read();
        }
        var penaltySum = Enumerable.Range(0, n).Sum(i => b[i] * l[i]);
        var ordered = Enumerable.Range(0, n).OrderByDescending(i => (X - b[i]) * u[i] + b[i] * l[i]).ToArray();
        bool[] used = new bool[n];

        //最後にmaxまで取らないケースは確実にorderedのスコアよりは低くなるが、スコアはpenaltySum以上なために(何故ならばn*lなので)それが網羅されないことはない
        long res = 0;
        for (int i = 0; i < ordered.Length; i++)
        {
            //X点まで勉強したときの削減可能点差
            var score = (X - b[ordered[i]]) * u[ordered[i]] + b[ordered[i]] * l[ordered[i]];
            if (penaltySum < score) break;
            used[ordered[i]] = true;
            penaltySum -= score;
            res += X;
        }
        if (penaltySum != 0)
        {
            long minTime = long.MaxValue;
            for (int i = 0; i < n; i++)
            {
                if (used[i]) continue;
                long time = 0;
                if (penaltySum <= b[i] * l[i])
                {
                    time = (penaltySum + l[i] - 1) / l[i];
                }
                else
                {
                    time = b[i] + ((penaltySum - b[i] * l[i]) + u[i] - 1) / u[i];
                }
                minTime = Min(minTime, time);
            }
            res += minTime;
        }
        Console.WriteLine(res);
    }

    static readonly TextReader In = Console.In;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    static int Read()
    {
        int res = 0;
        int next = In.Read();
        while (48 > next || next > 57) next = In.Read();
        while (48 <= next && next <= 57)
        {
            res = res * 10 + next - 48;
            next = In.Read();
        }
        return res;
    }

}

