        static void Method(string[] args)
        {
            int[] nx = ReadInts();
            long n = nx[0];
            long x = nx[1];

            long[][] blus = new long[n][];
            for (int i = 0; i < n; i++) blus[i] = ReadLongs();
            blus = blus.OrderBy(a => -(x - a[0]) * a[2]).ToArray();

            long[] deltaSums = new long[n];
            long[] otherSum = new long[n];
            deltaSums[0] = (x - blus[0][0]) * blus[0][2];
            otherSum[0] = blus[0][0] * blus[0][1];
            for(int i = 1; i < n; i++)
            {
                deltaSums[i] = deltaSums[i - 1] + (x-blus[i][0]) * blus[i][2];
                otherSum[i] = otherSum[i - 1] + blus[i][0] * blus[i][1];
            }

            long bottom = -1;
            long top = n * x;
            while (bottom + 1 < top)
            {
                long mid = (bottom + top + 1) / 2;
                long fullCnt = mid / x;
                long remain = mid % x;
                long tmpDelta = 0;
                long tmpRemain = otherSum[n - 1];
                if (fullCnt > 0)
                {
                    tmpDelta += deltaSums[fullCnt - 1];
                    tmpRemain -= otherSum[fullCnt - 1];
                }

                bool ok = tmpDelta >= tmpRemain;
                for (long i = fullCnt; i < n; i++)
                {
                    if (remain <= blus[i][0])
                    {
                        if (tmpDelta >= tmpRemain - remain * blus[i][1])
                        {
                            ok = true;
                            break;
                        }
                    }
                    else
                    {
                        if (tmpDelta >= tmpRemain - remain * blus[i][2]
                            + blus[i][0] * (blus[i][2] - blus[i][1]))
                        {
                            ok = true;
                            break;
                        }
                    }
                }

                if (ok) top = mid;
                else bottom = mid;
            }

            WriteLine(top);
        }

