namespace Competitive
{
    internal class Solution
    {
        public long N, X;
        public long[] B, L, U;
        public long MOD = 1000000007;
        private Data[] D;

        private Data[] DU, DL;

        public void Run()
        {
            {
                var line = Input.ReadIntArray();
                N = line[0];
                X = line[1];
            }

            B = new long[N];
            L = new long[N];
            U = new long[N];

            var lst = new List<Data>();

            for (int i = 0; i < N; i++)
            {
                var line = Input.ReadIntArray();
                B[i] = line[0];
                L[i] = line[1];
                U[i] = line[2];
                Data D = new Data(B[i], L[i], U[i]);
                lst.Add(D);
            }

            D = lst.ToArray();
            DU = D.ToArray();
            DL = D.ToArray();
            Array.Sort(DU, (d1, d2) => d1.u.CompareTo(d2.u) * (-1));
            Array.Sort(DL, (d1, d2) => d1.l.CompareTo(d2.l) * (-1));

            long ret = Search();

            Console.WriteLine(ret);
        }

        public bool CanWin(long target)
        {
            long opponent = 0;
            long x = target;

            for (int i = 0; i < D.Length; i++)
            {
                D[i].used = false;
            }

            for (int i = 0; i < D.Length; i++)
            {
                // 相手
                opponent += D[i].b * D[i].l;
            }

            // Z個はフルでとれるのなら、Uの候補は(Z+1)個
            // ある候補を落とすのなら、それのLか、別のL
            int Z = (int)(target / X);
            long R = target - Z * X;

            // 候補はN個、うち1個はresidualにする
            // Console.Error.WriteLine($"target:{target} {z} {residual}");
            Data[] cand = DU.ToArray();
            long player = 0;

            // 上からZ個とる
            for (int i = 0; i < Z; i++)
            {
                Data d = DU[i];
                long scoreX = d.b * d.l + (X - d.b) * d.u;
                player += scoreX;
            }

            long addition = 0;

            // 中途半端なものを決める
            for (int i = 0; i < DU.Length; i++)
            {
                if (R == 0) break;

                if (i < Z)
                {
                    Data d = DU[i];
                    Data dsub = DU[Z];
                    long scoreX = d.b * d.l + (X - d.b) * d.u;
                    long scoreR = Math.Min(d.b, R) * d.l + Math.Max(R - d.b, 0) * d.u;
                    long scoreS = dsub.b * dsub.l + (X - dsub.b) * dsub.u;
                    addition = Math.Max(addition, scoreR - scoreX + scoreS);
                }
                else
                {
                    Data d = DU[i];
                    long scoreR = Math.Min(d.b, R) * d.l + Math.Max(R - d.b, 0) * d.u;
                    addition = Math.Max(addition, scoreR);
                }
            }

            player += addition;
            return player >= opponent;

        }

        public long Search()
        {
            long left = 0;
            long right = N * X;

            if (CanWin(0)) return 0;
            if (!CanWin(N * X)) return N * X;

            while (left + 1 < right)
            {
                long mid = (left + right) / 2;
                // Console.Error.WriteLine($"MID {mid}");
                if (!CanWin(mid))
                {
                    left = mid;
                }
                else
                {
                    right = mid;
                }
            }
            return right;
        }

    }

