partial class Solver
{
    public void Run()
    {
        var N = ni();
        var X = ni();
        var b = new int[N];
        var l = new int[N];
        var u = new int[N];
        for (int i = 0; i < N; i++)
        {
            b[i] = ni();
            l[i] = ni();
            u[i] = ni();
        }
        long ans = 0;
        long currentDiff = 0;
        for (int i = 0; i < N; i++) currentDiff += CalcBestDiff(l[i], u[i], b[i], 0); // all zero-point
        var isDone = new bool[N];
        if (currentDiff < 0)
        {
            var p = E.Range(0, N).ToArray();
            Array.Sort(p, (i, j) =>
            {
                var ip = CalcBestDiff(l[i], u[i], b[i], X) - CalcBestDiff(l[i], u[i], b[i], 0);
                var jp = CalcBestDiff(l[j], u[j], b[j], X) - CalcBestDiff(l[j], u[j], b[j], 0);
                return -ip.CompareTo(jp);
            });
            foreach (var i in p)
            {
                var a = CalcBestDiff(l[i], u[i], b[i], X) - CalcBestDiff(l[i], u[i], b[i], 0);
                if (currentDiff + a <= 0)
                {
                    isDone[i] = true;
                    currentDiff += a;
                    ans += X;
                }
                else
                {
                    break;
                }
            }
            if (currentDiff < 0)
            {
                long lower = 0, upper = X;
                var bestX = 0L;
                while (lower <= upper)
                {
                    var mid = (lower + upper) / 2;

                    var maxUp = long.MinValue;
                    for (int i = 0; i < N; i++)
                    {
                        if (isDone[i]) continue;
                        var up = CalcBestDiff(l[i], u[i], b[i], mid) - CalcBestDiff(l[i], u[i], b[i], 0);
                        maxUp = Math.Max(maxUp, up);
                    }
                    if (currentDiff + maxUp >= 0)
                    {
                        bestX = mid;
                        upper = mid - 1;
                    }
                    else
                    {
                        lower = mid + 1;
                    }
                }
                ans += bestX;
            }
        }

        cout.WriteLine(ans);
    }

    public long CalcBestDiff(long l, long u, long b, long x)
    {
        if (b == x) return 0;
        if (b < x) return u * (x - b);
        return l * (x - b);
    }
}

