package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"sort"
	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)

type data struct {
	b, l, u int
}

type inputs struct {
	data []*data
	x    int
}

func (in inputs) Less(i, j int) bool {
	if (in.x-in.data[i].b)*in.data[i].u < (in.x-in.data[j].b)*in.data[j].u {
		return true
	}
	return false
}
func (in inputs) Swap(i, j int) {
	in.data[i], in.data[j] = in.data[j], in.data[i]
}
func (in inputs) Len() int {
	return len(in.data)
}

func main() {
	//defer profile.Start(profile.ProfilePath(".")).Stop()
	buf := make([]byte, 0)
	sc.Buffer(buf, 1000000009)
	sc.Split(bufio.ScanWords)

	n, x := oneInt(), oneInt()

	in := inputs{x: x}

	for i := 0; i < n; i++ {
		d := &data{}
		d.b = oneInt()
		d.l = oneInt()
		d.u = oneInt()
		in.data = append(in.data, d)
	}

	aite := 0
	ans := 0

	sort.Sort(in)

	for _, d := range in.data {
		aite += d.b * d.u
	}

	for _, d := range in.data {
		point := 0
		for {
			ans += 1
			aite -= d.u
			point++
			if aite <= 0 || point >= x {
				break
			}
		}
		if aite <= 0 {
			break
		}
	}
	fmt.Println(ans)
}

func oneInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func oneStr() string {
	sc.Scan()
	return sc.Text()
}

func scanNums(len int) (nums []int) {
	for i := 0; i < len; i++ {
		nums = append(nums, oneInt())
	}
	return nums
}

func scanStrings(len int) (strs []string) {
	for i := 0; i < len; i++ {
		strs = append(strs, oneStr())
	}
	return strs
}

func abs(a int) int {
	if a >= 0 {
		return a
	} else {
		return -a
	}
}

func pow(p, q int) int {
	return int(math.Pow(float64(p), float64(q)))
}

func min(nums ...int) int {
	if len(nums) == 0 {
		panic("funciton min() requires at least one argument.")
	}
	res := nums[0]
	for i := 0; i < len(nums); i++ {
		res = int(math.Min(float64(res), float64(nums[i])))
	}
	return res
}

func max(nums ...int) int {
	if len(nums) == 0 {
		panic("funciton max() requires at least one argument.")
	}
	res := nums[0]
	for i := 0; i < len(nums); i++ {
		res = int(math.Max(float64(res), float64(nums[i])))
	}
	return res
}

func strSearch(a []string, b string) bool {
	for i := 0; i < len(a); i++ {
		if a[i] == b {
			return true
		}
	}
	return false
}

func sortAsc(a []int) []int {
	sort.Ints(a)
	return a
}

func sortDesc(a []int) []int {
	sort.Sort(sort.Reverse(sort.IntSlice(a)))
	return a
}

func gcd(a, b int) int {
	if b == 0 {
		return a
	}
	return gcd(b, a%b)
}

func lcm(a, b int) int {
	if a == 0 && b == 0 {
		return 0
	}
	return a * b / gcd(a, b)
}

func cumSum(nums []int) []int {
	sums := []int{0}

	for i := 0; i < len(nums); i++ {
		sums = append(sums, sums[i]+nums[i])
	}
	return sums
}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric, std.bigint;

alias DF = Tuple!(size_t, "idx", BigInt, "up");

BigInt[10^^5] BS, LS, US, LOW_PS;
DF[10^^5] DFS;

void main()
{
    auto nx = readln.split.to!(int[]);
    auto N = nx[0];
    auto X = nx[1];

    BigInt b_sum;
    foreach (i; 0..N) {
        auto blu = readln.split.to!(long[]);
        BigInt b = blu[0];
        BigInt l = blu[1];
        BigInt u = blu[2];
        BS[i] = b;
        LS[i] = l;
        US[i] = u;
        LOW_PS[i] = b * l;
        b_sum += b * l;
        DFS[i] = DF(i, X * u - b * u);
    }
    sort!"a.up > b.up"(DFS[0..N]);
    BigInt a_sum;
    size_t i;
    BigInt r;
    while (a_sum < b_sum) {
        auto d = DFS[i++];
        auto idx = d.idx;
        auto b = b_sum - LOW_PS[idx] + BS[idx] * US[idx];
        auto a = a_sum + X * US[idx];
        if (a < b) {
            b_sum = b;
            a_sum = a;
            r += X;
        } else {
            BigInt rr = long.max;
            --i;
            for (; i < N; ++i) {
                idx = DFS[i].idx;
                auto r1 = (b_sum - a_sum + LS[idx] - 1) / LS[idx];
                if (r1 > X) r1 = long.max;
                auto r2 = (b_sum - LOW_PS[idx] + BS[idx] * US[idx] - a_sum + US[idx] - 1) / US[idx];
                if (r2 > X) r2 = long.max;

                rr = min(rr, r1);
                rr = min(rr, r2);
            }
            r += rr;
            break;
        }
    }
    writeln(r);
}

