    int p = -1;

    foreach (i ; 0 .. n) {
        auto plus = 1L * ds[i].l * ds[i].b + 1L * ds[i].u * (x - ds[i].b);
        if (v < plus) {
            p = i;
            break;
        }
        else {
            ans += x;
            v -= plus;
        }
    }

    debug {
        writeln("rem v:", v);
    }

    long mic = inf3;

    foreach (i ; p .. n) {
        auto bi = ds[i].b;
        auto li = ds[i].l;
        auto ui = ds[i].u;
        long t;
        debug {
            writeln(bi, " ", li, " ", ui);
        }
        if (1L * bi * li >= v) {
            t = (v + li - 1) / li;
        }
        else {
            long vv = v - 1L * bi * li;
            t = bi + (vv + ui - 1) / ui;
        }
        debug {
            writeln("t:", t);
        }
        mic = min(mic, t);
    }

    ans += mic;
    writeln(ans);
}























int[][] readGraph(int n, int m, bool isUndirected = true, bool is1indexed = true) {
    auto adj = new int[][](n, 0);

    foreach (i; 0 .. m) {
        int u, v;
        scan(u, v);
        if (is1indexed) {
            u--, v--;
        }
        adj[u] ~= v;
        if (isUndirected) {
            adj[v] ~= u;
        }
    }

    return adj;
}

alias Edge = Tuple!(int, "to", int, "cost");

Edge[][] readWeightedGraph(int n, int m, bool isUndirected = true, bool is1indexed = true) {
    auto adj = new Edge[][](n, 0);

    foreach (i; 0 .. m) {
        int u, v, c;
        scan(u, v, c);
        if (is1indexed) {
            u--, v--;
        }
        adj[u] ~= Edge(v, c);
        if (isUndirected) {
            adj[v] ~= Edge(u, c);
        }
    }

    return adj;
}

