void main() {
  long N, X;
  scanln(N, X);
  struct P {
    long index;
    long b, l, u;
    long g(long a) {
      if (a < b) {
        return l*(a - b);
      } else {
        return u*(a - b);
      }
    }
  }
  P[] ps = new P[N];
  foreach(i; 0..N) {
    ps[i].index = i;
    scanln(ps[i].b, ps[i].l, ps[i].u);
