def solve(N, X, BLUs):
    vs = [(L*B + U*(X-B), i) for i, (B, L, U) in enumerate(BLUs)]
    vs.sort(reverse=True)

    accVs = list(accumulate([0] + vs, lambda accX, X: accX + X[0]))
    D0 = -sum([L*B for B, L, U in BLUs])

    def isOK(k):
        q = k // X
        r = k % X
        accV = accVs[q+1]
        for v, i in vs[:q]:
            B, L, U = BLUs[i]
            d = D0 + accV - v
            if r <= B:
                d += L*r
            else:
                d += L*B + U*(r-B)
            if d >= 0:
                return True
        accV = accVs[q]
        for v, i in vs[q:]:
            B, L, U = BLUs[i]
            d = D0 + accV
            if r <= B:
                d += L*r
            else:
                d += L*B + U*(r-B)
            if d >= 0:
                return True
        return False

    ng, ok = -1, N*X
    while abs(ok-ng) > 1:
        mid = (ng+ok) // 2
        if isOK(mid):
            ok = mid
        else:
            ng = mid

    return ok


