import sys
INF = float("inf")
import heapq


def solve(N: int, X: int, b: "List[int]", l: "List[int]", u: "List[int]"):

    # i番目のテストで高橋くんがx点とったとき、A-Bに加える量
    def f(i, x):
        if x <= b[i]:
            return l[i]*(x-b[i])
        else:
            return u[i]*(x-b[i])

    # あらかじめ、0点とった時とX点とった時の効果が大きい順に並べておく
    mh = [[f(i, X)-f(i, 0), i] for i in range(N)]
    mh.sort(reverse=True)

    def isOK(index, key):
        # 勉強時間Tとしてスコア(A-B)を最大化するよう勉強時間を配分する
        T = index
        num = -(-T//X)          # 点をとるテストの個数
        # いったんX点とらせる
        D = sum([f(i, X) for _, i in mh[:num]])\
            + sum([f(i, 0) for _, i in mh[num:]])
        # 点を取るテストの中で、点数をT%X点に変更した時、
        # 最も減少の小さいものを選ぶ
        v, i = min([[f(i, X)-f(i, T % X), i] for _, i in mh[:num]])
        D += -v
        return D >= key

    def binary_search(key):
        ng = -1
        ok = N*X
        while abs(ok - ng) > 1:
            mid = (ok + ng)//2
            if isOK(mid, key):
                ok = mid
            else:
                ng = mid
        return ok

    ans = binary_search(0)
    print(ans)
    return


def main():

    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    X = int(next(tokens))  # type: int
    b = [int()] * (N)  # type: "List[int]"
    l = [int()] * (N)  # type: "List[int]"
    u = [int()] * (N)  # type: "List[int]"
    for i in range(N):
        b[i] = int(next(tokens))
        l[i] = int(next(tokens))
        u[i] = int(next(tokens))
    solve(N, X, b, l, u)


if __name__ == '__main__':
    main()

