class TestObj(object):
    def __init__(self, b: int, l: int, u: int, x: int):
        self.maxval = u
        self.minval = l
        self.aoki = b
        self.maxp = l * b + u * (x-b)

    def cum(self, time: int):
        return self.minval * min(self.aoki, time) + self.maxval * max(0, time - self.aoki)


def find_max_cum(tests):
    cum = [0]
    for ti in tests:
        cum.append(cum[-1] + ti.maxp)

    return cum


def find_aokip(tests):
    ans = 0
    for ti in tests:
        ans += ti.minval * ti.aoki

    return ans


def takahashiWin(tests, k: int, x: int, max_cum: list, aokip: int):
    n = len(tests)
    maxcnt = k // x
    rest = k % x

    if maxcnt >= n:
        return True

    if max_cum[maxcnt] + tests[maxcnt].cum(rest) >= aokip:
        return True
    else:
        return False


def binary_search(tests: list, x: int):
    low = 0
    high = 10**10 + 1
    max_cum = find_max_cum(tests)
    aokip = find_aokip(tests)

    while high - low > 1:
        mid = (high + low) // 2

        if takahashiWin(tests, mid, x, max_cum, aokip):
            high = mid
        else:
            low = mid

    return high

