use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn calc(mid: i64, x: i64, bs: &Vec<i64>, ls: &Vec<i64>, rs: &Vec<i64>) -> bool {
    let n = bs.len();
    let mut total = 0;
    let mut values = vec![(0, 0); n];
    let cnt = (mid / x) as usize;
    let rest = mid % x;
    for i in 0..n {
        total -= ls[i] * bs[i];
        values[i].0 = ls[i] * bs[i] + rs[i] * (x - bs[i]);
        values[i].1 = if rest < bs[i] {
            ls[i] * rest
        } else {
            ls[i] * bs[i] + rs[i] * (rest - bs[i])
        };
        values[i].1 *= -1;
    }
    values.sort();
    values.reverse();
    for i in 0..cnt {
        total += values[i].0;
    }
    let mut max_value = 0;
    for i in cnt..n {
        max_value = std::cmp::max(max_value, -values[i].1);
    }
    total += max_value;
    return total >= 0;
}

fn main() {
    let n = read::<usize>();
    let x = read::<i64>();
    let mut bs = vec![0; n];
    let mut ls = vec![0; n];
    let mut us = vec![0; n];
    for i in 0..n {
        bs[i] = read::<i64>();
        ls[i] = read::<i64>();
        us[i] = read::<i64>();
    }
    let mut l = -1;
    let mut r = x * n as i64;
    while r - l > 1 {
        let mid = (l + r) / 2;
        if calc(mid, x, &bs, &ls, &us) {
            r = mid;
        } else {
            l = mid;
        }
    }
    println!("{}", r);
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

