use std::cmp::max;

fn main() {
    input!{
        n: usize,
        x: usize,
        v: [(usize, usize, usize); n]
    }
    let mut maxes: Vec<(usize, usize)> = vec![(0, 0); n];
    let mut score: usize = 0;
    for i in 0..n {
        score += v[i].0 * v[i].1;
        maxes[i] = (v[i].0 * v[i].1 + (x - v[i].0) * v[i].2, i);
    }
    maxes.sort_by(|x, y| y.0.cmp(&x.0));
    let mut ac: Vec<usize> = vec![0; n + 1];
    for i in 0..n {
        ac[i + 1] = ac[i] + maxes[i].0;
    }
    let mut order = vec![0; n];
    for i in 0..n {
        order[maxes[i].1] = i;
    }
    let mut l: usize = 0;
    let mut r: usize = v.iter().map(|x| x.0).sum();
    while l + 1 < r {
        let m = (l + r) / 2;
        let k = m % x;
        let q = m / x;
        let mut smax = 0;
        for i in 0..n {
            let mut s = ac[q];
            if order[i] < q {
                s -= maxes[order[i]].0 - maxes[q].0;
            }
            if k > v[i].0 {
                s += v[i].0 * v[i].1 + (k - v[i].0) * v[i].2;
            } else {
                s += k * v[i].1;
            }
            smax = max(smax, s);
        }
        if smax >= score {
            r = m;
        } else {
            l = m;
        }
    }
    println!("{}", r);
}

