        ans += x;
        used[t.1] = true;
    }
    if score > 0 {
        let mut m = score;
        for i in 0..n {
            if used[i] {
                continue;
            }
            if v[i].0 * v[i].1 >= score {
                m = min(m, (score - 1) / v[i].1 + 1);
            } else {
                m = min(m, (score - v[i].0 * v[i].1 - 1) / v[i].2 + 1 + v[i].0);
            }
        }
        ans += m;
    }
    println!("{}", ans);
}

