        blu: [(i64, i64, i64); n],
    }
    let mut pass = n as i64 * x;
    let mut fail = -1;
    let mut eff = vec![(0, 0); n];
    for i in 0..n {
        let (b, l, u) = blu[i];
        eff[i] = (l * b + (x - b) * u, i);
    }
    eff.sort();
    eff.reverse();
    while pass - fail > 1 {
        let mid = (pass + fail) / 2;
        let q = (mid / x) as usize;
        let r = mid % x;
        let mut diff = 0;
        for i in 0..n {
            let (_, idx) = eff[i];
            let (b, l, u) = blu[idx];
            if i < q {
                diff += (x - b) * u;
            } else {
                diff -= b * l;
            }
        }
        let mut ok = false;
        for i in 0..n {
            let (ben, idx) = eff[i];
            let (b, l, u) = blu[idx];
            let mut newdiff = diff;
            if i < q {
                newdiff -= ben;
                newdiff += eff[q].0;
            }
            newdiff += if r < b {
                l * r
            } else {
                l * b + u * (r - b)
            };
            if newdiff >= 0 {
                ok = true;
                break;
            }
        }
        if ok {
            pass = mid;
        } else {
            fail = mid;
        }
    }
    puts!("{}\n", pass);
}

