fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let x: i64 = sc.read();
    let mut b: Vec<i64> = vec![0; n];
    let mut l: Vec<i64> = vec![0; n];
    let mut u: Vec<i64> = vec![0; n];
    for i in 0..n {
        b[i] = sc.read();
        l[i] = sc.read();
        u[i] = sc.read();
    }

    if b.iter().all(|&b| b == 0) {
        println!("0");
        return;
    }

    let mut ok = (n as i64) * x;
    let mut ng = 0;
    while ok - ng > 1 {
        let total = (ok + ng) / 2;
        if solve(total, x, &b, &l, &u) {
            ok = total;
        } else {
            ng = total;
        }
    }

    println!("{}", ok);
}

fn solve(total: i64, x: i64, b: &Vec<i64>, l: &Vec<i64>, u: &Vec<i64>) -> bool {
    let n = b.len();
    let mut lower_sum = 0;
    let mut affect = vec![];
    for i in 0..n {
        lower_sum += l[i] * b[i];
        affect.push((x * u[i] - b[i] * (u[i] - l[i]), b[i], l[i], u[i]));
    }
    affect.sort();
    affect.reverse();

    let head = (total / x) as usize;
    let remain = total - total / x * x;

    let mut head_sum = 0;
    for i in 0..head {
        head_sum += affect[i].0;
    }
    let last = affect[head].0;
    for i in 0..n {
        let (_, b, l, u) = affect[i];
        let e = if remain >= b {
            remain * u - b * (u - l)
        } else {
            remain * l
        };
        if i < head {
            if head_sum + last - affect[i].0 + e >= lower_sum {
                return true;
            }
        } else {
            if head_sum + e >= lower_sum {
                return true;
            }
        }
    }
    false
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

