use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: i64,
        xs: [(i64,i64,i64); n],
    }
    let mut ys = vec![];
    for (i, &(b, l, u)) in xs.iter().enumerate() {
        ys.push((m * u - b * (u - l), i));
    }
    // eprintln!("ys = {:?}", ys);
    ys.sort();
    ys.reverse();
    let mut rem = 0;
    for &(b, l, u) in &xs {
        rem += b * l;
    }
    // eprintln!("rem = {}", rem);
    let mut res = 0;
    let mut used = vec![false; n];
    for &(v, i) in &ys {
        let (b, l, u) = xs[i];
        if rem >= v {
            // eprintln!("select i={}, v={}", i, v);
            rem -= v;
            res += m;
            used[i] = true;
        } else {
            // eprintln!("res = {}, rem = {}", res, rem);
            let mut max_l = 0;
            let mut max_l_k = 0;
            for k in 0..n {
                let (b2, l2, u2) = xs[k];
                if !used[k] {
                    if max_l < l2 {
                        max_l = l2;
                        max_l_k = k;
                    }
                }
            }
            // eprintln!("max_l = {}, max_l_k = {}", max_l, max_l_k);
            let mut w = (rem + max_l - 1) / max_l;
            if w > xs[max_l_k].0 {
                panic!();
            }
            res += w;
            // eprintln!("w = {}, res = {}", w, res);
            break;
        }
    }
    writeln!(buf, "{}", res);
    buf
}

