use std::cmp::min;

fn main() {
    input!{
        n: usize,
        x: usize,
        v: [(usize, usize, usize); n]
    }
    let mut maxes: Vec<(usize, usize)> = vec![(0, 0); n];
    let mut score: usize = 0;
    for i in 0..n {
        score += v[i].0 * v[i].1;
        maxes[i] = (v[i].0 * v[i].1 + (x - v[i].0) * v[i].2, i);
    }
    maxes.sort_by_key(|x| x.0);
    let mut used: Vec<bool> = vec![false; n];
    let mut ans = 0;
    while let Some(t) = maxes.pop() {
        if t.0 > score {
            break;
        }
        score -= t.0;
        ans += x;
        used[t.1] = true;
    }
    if score > 0 {
        let mut m = score;
        for i in 0..n {
            if used[i] {
                continue;
            }
            if v[i].0 * v[i].1 >= score {
                m = min(m, (score - 1) / v[i].1 + 1);
            } else {
                m = min(m, (score - v[i].0 * v[i].1 - 1) / v[i].2 + 1 + v[i].0);
            }
        }
        ans += m;
    }
    println!("{}", ans);
}

