type Test = (i64, i64, i64);

fn isok(time: i64, x: i64, tests: &Vec<Test>) -> bool {
    let n = tests.len();
    let ocnt = (time / x) as usize;
    let md = time % x;
    if ocnt >= n {
        return true;
    }

    let mut ok = false;

    let mut ls = 0;
    for i in 0..n {
        ls += tests[i].0 * tests[i].1;
    }
    let mut rs0 = 0;
    let mut rs1 = 0;
    for i in 0..ocnt+1 {
        let w = tests[i].0 * tests[i].1 + (x - tests[i].0) * tests[i].2;
        if i < ocnt {
            rs0 += w;
        }
        rs1 += w;
    }

    for i in 0..n {
        let mut rs = rs0;
        if ocnt > i {
            rs = rs1;
            rs -= tests[i].0 * tests[i].1 + (x - tests[i].0) * tests[i].2;
        }
        if md < tests[i].0 {
            rs += md * tests[i].1;
        } else {
            rs += tests[i].0 * tests[i].1 + (md - tests[i].0) * tests[i].2;
        }
        ok |= rs >= ls;
    }
    ok
}

fn main() {
    input! {
