    };

    let mut tests = tests;
    tests.sort_by(|t0, t1| {
        let a = (x - t0.0) * t0.2 + t0.0 * t0.1;
        let b = (x - t1.0) * t1.2 + t1.0 * t1.1;
        return b.partial_cmp(&a).unwrap();
    });


    let mut ok = n as i64 * x;
    let mut ng = -1;
    while ok - ng > 1 {
        let med = (ok + ng) / 2;
        if isok(med, x, &tests) {
            ok = med;
        } else {
            ng = med;
        }
    }
    println!("{}", ok);
}

