#[derive(Clone, Debug)]
struct Test {
    enemy_time: u64,
    lower_weight: u64,
    upper_weight: u64
}

impl Test {
    fn score(&self, time: u64) -> u64 {
        if self.enemy_time >= time {
            self.lower_weight * time
        } else {
            self.upper_weight * time - (self.upper_weight - self.lower_weight) * self.enemy_time
        }
    }

    fn enemy_score(&self) -> u64 {
        self.lower_weight * self.enemy_time
    }
}

readable!(Test, 3, |ws| Test {
    enemy_time: ws[0].read::<u64>(),
    lower_weight: ws[1].read::<u64>(),
    upper_weight: ws[2].read::<u64>()
});

fn main() {
    read!(_ = (), full_time = u64);
    let mut tests = readx::<Test>();
    tests.sort_desc_by_key(|t| {
        t.enemy_time * t.lower_weight + (full_time - t.enemy_time) * t.upper_weight
    });

    let my_scores: Vec<u64> = tests.iter()
        .lscan(0, |&acc, next| acc + (full_time - next.enemy_time) * next.upper_weight)
        .collect();
    let enemy_scores: Vec<u64> = tests.iter()
        .lscan(0, |&acc, next| acc + next.enemy_time * next.lower_weight)
        .collect();

    let ans = (0..full_time * tests.len() as u64 + 1).bsearch_right_min(|&time| {
        let full_count = (time / full_time) as usize;
        let time_rest = time % full_time;
        (0..tests.len()).any(|i| {
            if time_rest == 0 || i >= full_count {
                let my_score = my_scores[full_count];
                let enemy_score = *enemy_scores.last().unwrap() - enemy_scores[full_count];
                my_score + tests[i].score(time_rest) >= enemy_score
            } else  {
                let my_score = my_scores[full_count+1] - (tests[i].score(full_time) - tests[i].enemy_score());
                let enemy_score = *enemy_scores.last().unwrap() - enemy_scores[full_count+1] + tests[i].enemy_score();
                my_score + tests[i].score(time_rest) >= enemy_score
            }
        })
    }).unwrap().unwrap();

    println!("{}", ans);
}

use std::io::Read;

fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).ok();
    let mut it = buf.split_whitespace();
    let n = it.next().unwrap().parse::<i64>().unwrap();
    let x = it.next().unwrap().parse::<i64>().unwrap();
    let mut t = Vec::new();
    let mut aoki = 0;
    for _ in 0..n {
        let b = it.next().unwrap().parse::<i64>().unwrap();
        let l = it.next().unwrap().parse::<i64>().unwrap();
        let u = it.next().unwrap().parse::<i64>().unwrap();
        let mx = b * l + (x - b) * u;
        aoki += b * l;
        t.push((b, l, u, mx));
    }
    t.sort_by_key(|a| -a.3);
    let mut low = -1;
    let mut high = n * x;
    while high - low > 1 {
        let mid = (low + high) / 2;
        let thr = (mid / x) as usize;
        let y = mid % x;
        let mut sum = 0;
        for i in 0..thr { sum += t[i].3 }
        let mut best = 0;
        for i in 0..n as usize {
            let mut cur = sum;
            if i < thr {
                cur += t[thr].3 - t[i].3;
            }
            cur += std::cmp::min(t[i].0, y) * t[i].1 + std::cmp::max(0, y - t[i].0) * t[i].2;
            best = std::cmp::max(best, cur);
        }
        if best >= aoki {
            high = mid;
        } else {
            low = mid;
        }
    }
    println!("{}", high);
}

