use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: i64,
        xs: [(i64,i64,i64); n],
    }
    let mut ys = vec![];
    for (i, &(b, l, u)) in xs.iter().enumerate() {
        ys.push((m * u - b * (u - l), l, i));
    }
    // eprintln!("ys = {:?}", ys);
    ys.sort();
    ys.reverse();
    let mut rem = 0;
    for &(b, l, u) in &xs {
        rem += b * l;
    }
    // eprintln!("rem = {}", rem);
    let mut res = 0;
    let mut used = vec![false; n];
    for &(v, _, i) in &ys {
        let (b, l, u) = xs[i];
        if rem >= v {
            // eprintln!("select i={}, v={}", i, v);
            rem -= v;
            res += m;
            used[i] = true;
        } else {
            // eprintln!("res = {}, rem = {}", res, rem);
            let mut min = 1i64 << 40;
            for k in 0..n {
                let (b2, l2, u2) = xs[k];
                if !used[k] {
                    // l
                    let t = (rem + l2 - 1) / l2;
                    // eprintln!("k={}, t={}", k, t);
                    if min > t {
                        min = t;
                    }
                    // u
                    let t = (rem + b2 * (u2 - l2) + u2 - 1) / u2;
                    if min > t {
                        min = t;
                    }
                }
            }
            // eprintln!("min = {}", min);
            res += min;
            // // eprintln!("w = {}, res = {}", w, res);
            break;
        }
    }
    writeln!(buf, "{}", res);
    buf
}

