use std::cmp::Reverse;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let x: i64 = sc.read();

    let blu = (0..n)
        .map(|_| (sc.read::<i64>(), sc.read::<i64>(), sc.read::<i64>()))
        .collect::<Vec<_>>();

    if blu.iter().all(|&(b, _, _)| b == 0) {
        println!("0");
        return;
    }
    let mut ng = 0;
    let mut ok = x * (n as i64);
    while ok - ng > 1 {
        let m = (ok + ng) / 2;
        if solve(m, &blu, x) {
            ok = m;
        } else {
            ng = m;
        }
    }
    println!("{}", ok);
}

fn solve(time: i64, blu: &[(i64, i64, i64)], x: i64) -> bool {
    let head = (time / x) as usize;
    let remain = time % x;
    let n = blu.len();
    if head >= n {
        return true;
    }

    let mut lower = 0;
    let mut effect = vec![];
    for i in 0..n {
        let (b, l, u) = blu[i];
        lower += b * l;
        let gain = x * u - b * (u - l);
        effect.push((gain, i));
    }
    effect.sort_by_key(|&(g, _)| Reverse(g));
    for i in 0..head {
        let (gain, _) = effect[i];
        if lower < gain {
            return true;
        }
        lower -= gain;
    }

    let (next, _) = effect[head];
    for (k, &(removed_gain, i)) in effect.iter().enumerate() {
        let in_head = k < head;
        let (b, l, u) = blu[i];

        let gain = if remain >= b {
            remain * u - b * (u - l)
        } else {
            remain * l
        };
        if in_head {
            if gain + next >= lower + removed_gain {
                assert!(next <= removed_gain);
                return true;
            }
        } else {
            if gain >= lower {
                return true;
            }
        }
    }
    false
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write_all(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

