#[derive(Clone, Debug)]
struct Test {
    enemy_score: u64,
    lower_weight: u64,
    upper_weight: u64
}

readable!(Test, 3, |ws| Test {
    enemy_score: ws[0].read::<u64>(),
    lower_weight: ws[1].read::<u64>(),
    upper_weight: ws[2].read::<u64>()
});

fn max_score(tests: &[Test], time: u64) -> u64 {
    tests.iter().map(|t| {
        if t.enemy_score >= time {
            t.lower_weight * time
        } else {
            t.upper_weight * time - (t.upper_weight - t.lower_weight) * t.enemy_score
        }
    }).max().unwrap_or(0)
}

fn main() {
    read!(_ = (), full_score = u64);
    let mut tests = readx::<Test>();
    tests.sort_desc_by_key(|t| (full_score - t.enemy_score) * t.upper_weight);

    let my_scores: Vec<u64> = tests.iter()
        .lscan(0, |&acc, next| acc + (full_score - next.enemy_score) * next.upper_weight)
        .collect();
    let enemy_scores: Vec<u64> = tests.iter()
        .lscan(0, |&acc, next| acc + next.enemy_score * next.lower_weight)
        .collect();

    let mut l = 0;
    let mut r = full_score * tests.len() as u64;

    while r - l > 1 {
        let time = (l + r) / 2;

        let full_count = (time / full_score) as usize;
        let time_rest = time % full_score;
        let my_score = my_scores[full_count];
        let enemy_score = *enemy_scores.last().unwrap() - enemy_scores[full_count];

        if my_score + max_score(&tests[full_count..], time_rest) >= enemy_score {
            r = time;
        } else {
            l = time;
        }
    }
    println!("{}", r);
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

