fn compute(b: isize, l: isize, r: isize, cost: isize) -> isize {
    if cost >= b {
        l * b + r * (cost - b)
    } else {
        l * cost
    }
}

fn find(b: isize, l: isize, r: isize, x: isize, target: isize) -> isize {
    let mut lb = -1;
    let mut ub = x;
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        let val = compute(b, l, r, mid);
        if val >= target {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    ub
}

fn solve(end: usize, maxim: isize, x: isize, target: isize, ps: &[(isize, isize, isize)]) -> isize {
    let mut answer = isize::max_value();
    dbg!(end);
    dbg!(maxim);
    dbg!(target);
    for i in 0..ps.len() {
        let (b, l, r) = ps[i];
        dbg!(i);
        let now = if i < end {
            maxim - compute(b, l, r, x)
        } else {
            maxim
        };
        dbg!(now);
        let base_cost = if i < end {
            (end as isize - 1) * x
        } else {
            (end as isize) * x
        };
        dbg!(base_cost);
        let rest = target - now;
        dbg!(rest);
        let cost = find(b, l, r, x, rest);
        dbg!(cost);
        dbg!(compute(b, l, r, cost));
        if compute(b, l, r, cost) >= rest {
            let all_cost = base_cost + cost;
            dbg!(all_cost);
            answer = min(answer, all_cost);
        }
    }
    answer
}

fn run() {
    input! {
        n: usize,
        x: isize,
        ps: [(isize, isize, isize); n],
    }

    let target = ps.iter().map(|&(b, l, _)| b * l).sum::<isize>();
    dbg!(target);

    let mut ps = ps.clone();
    ps.sort_by_key(|&(b, l, r)| compute(b, l, r, x));
    ps.reverse();
    dbg!(&ps);

    let mut maxim = 0;
    for i in 0..n {
        let (b, l, r) = ps[i];
        let add = compute(b, l, r, x);
        dbg!(i);
        dbg!(add);
        dbg!(maxim);
        if maxim + add >= target {
            let A = solve(i, maxim, x, target, &ps);
            let B = solve(i + 1, maxim + add, x, target, &ps);
            dbg!(A);
            dbg!(B);
            println!("{}", min(A, B));
            break;
        }
        maxim += add;
    }
}

