fn main() {
    let v = read_vec::<i64>();
    let (n, x) = (v[0] as usize, v[1]);
    let mut tests = vec![];
    for _ in 0..n {
        let v = read_vec::<i64>();
        let (b, l, u) = (v[0], v[1], v[2]);
        let gain = (x - b) * u + b * l;
        tests.push((gain, b, l, u));
    }
    tests.sort();
    tests.reverse();
    let mut lost_sum = vec![0; n + 1];
    for i in 0..n {
        lost_sum[i + 1] = lost_sum[i] + tests[i].1 * tests[i].2;
    }
    let mut gain_sum = vec![0; n + 1];
    for i in 0..n {
        gain_sum[i + 1] = gain_sum[i] + (x - tests[i].1) * tests[i].3;
    }
    let criterion = |x| gain_sum[x] < lost_sum[n] - lost_sum[x];
    let should_win_num = binary_search(0, n + 1, criterion) + 1;
    let initial_gain = gain_sum[should_win_num - 1];
    let initial_lost = lost_sum[n] - lost_sum[should_win_num - 1];
    debug!(should_win_num, initial_gain, initial_lost);

    let mut min_point = x;
    for i in should_win_num - 1..n {
        let (b, l, u) = (tests[i].1, tests[i].2, tests[i].3);
        let current_lost = b * l;

        let residual = (initial_lost - current_lost) - initial_gain;

        let mut point: i64 = x + 1;
        if residual <= 0 {
            point = b + (residual) / l;
        } else if (x - b) * u >= residual {
            // must win so we use u
            point = b + (residual + (u - 1)) / u;
        }
        // debug!(residual, point);
        min_point = min(min_point, point);
    }
    assert!(min_point <= x);
    println!("{:?}", (should_win_num as i64 - 1) * x + min_point);
}

fn binary_search<F>(lb: usize, ub: usize, criterion: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut lb = lb;
    let mut ub = ub;
    while ub - lb > 1 {
        let mid = (ub + lb) / 2;
        if criterion(mid) {
            lb = mid;
        } else {
            ub = mid;
        }
    }
    lb
}

