fn main() {
    let n = read::<usize>();
    let x = read::<i64>();
    let mut bs = vec![0; n];
    let mut ls = vec![0; n];
    let mut us = vec![0; n];
    for i in 0..n {
        bs[i] = read::<i64>();
        ls[i] = read::<i64>();
        us[i] = read::<i64>();
    }
    let mut total = 0;
    let mut values = vec![(0, 0); n];
    for i in 0..n {
        total -= ls[i] * bs[i];
        values[i].0 = ls[i] * bs[i] + us[i] * (x - bs[i]);
        values[i].1 = i;
    }
    values.sort();
    values.reverse();
    let mut sum = 0;
    let mut last_index = n - 1;
    let mut used = vec![false; n];
    for i in 0..n {
        if total + values[i].0 >= 0 {
            last_index = i;
            break;
        }
        total += values[i].0;
        used[values[i].1] = true;
        sum += x;
    }
    let mut ans = sum + x;
    for i in 0..n {
        let mut lsum = sum;
        let mut rest = -total;
        if used[i] {
            rest += ls[i] * bs[i] + us[i] * (x - bs[i]);
            rest -= values[last_index].0;
        }
        if rest <= ls[i] * bs[i] {
            lsum += (rest + ls[i] - 1) / ls[i];
        } else {
            lsum += bs[i];
            rest -= ls[i] * bs[i];
            lsum += (rest + us[i] - 1) / us[i];
        }
        ans = std::cmp::min(ans, lsum);
    }
    println!("{}", ans);
}

