use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: i64,
        xs: [(i64,i64,i64); n],
    }
    let mut ys = vec![];
    for (i, &(b, l, u)) in xs.iter().enumerate() {
        ys.push((m * u - b * (u - l), i));
    }
    // eprintln!("ys = {:?}", ys);
    ys.sort();
    ys.reverse();
    let mut rem = 0;
    for &(b, l, u) in &xs {
        rem += b * l;
    }
    // eprintln!("rem = {}", rem);
    let mut res = 0;
    for &(v, i) in &ys {
        let (b, l, u) = xs[i];
        if rem >= v {
            // eprintln!("select i={}, v={}", i, v);
            rem -= v;
            res += m;
        } else {
            // eprintln!("res = {}, rem = {}", res, rem);
            let w = (rem + l - 1) / l;
            res += w;
            // eprintln!("w = {}, res = {}", w, res);
            break;
        }
    }
    writeln!(buf, "{}", res);
    buf
}

