fn solve(time: i64, blu: &[(i64, i64, i64)], x: i64) -> bool {
    let head = (time / x) as usize;
    let remain = time % x;
    let n = blu.len();
    if head >= n {
        return true;
    }

    let mut lower = 0;
    let mut effect = vec![];
    for i in 0..n {
        let (b, l, u) = blu[i];
        lower += b * l;
        let gain = x * u - b * (u - l);
        effect.push((gain, i));
    }
    effect.sort_by_key(|&(g, _)| Reverse(g));
    for i in 0..head {
        let (gain, _) = effect[i];
        if lower < gain {
            return true;
        }
        lower -= gain;
    }

    let (next, _) = effect[head];
    for &(removed_gain, i) in effect.iter() {
        let in_head = i < head;
        let (b, l, u) = blu[i];

        let gain = if remain >= b {
            remain * u - b * (u - l)
        } else {
            remain * l
        };
        if in_head {
            if gain + next >= lower + removed_gain {
                assert!(next <= removed_gain);
                return true;
            }
        } else {
            if gain >= lower {
                return true;
            }
        }
    }
    false
}

