    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, [ $t:tt ]) => {{
        let len = read_value!($next, usize);
        (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    }};

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

trait Bisect<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}

impl<T: Ord> Bisect<T> for [T] {
    fn lower_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] >= val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
    fn upper_bound(&self, val: &T) -> usize {
        let mut pass = self.len() + 1;
        let mut fail = 0;
        while pass - fail > 1 {
            let mid = (pass + fail) / 2;
            if &self[mid - 1] > val {
                pass = mid;
            } else {
                fail = mid;
            }
        }
        pass - 1
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, x: i64,
        blu: [(i64, i64, i64); n],
    }
    let mut pass = n as i64 * x;
    let mut fail = 0;
    let mut eff = vec![(0, 0); n];
    for i in 0..n {
        let (b, l, u) = blu[i];
        eff[i] = (l * b + (x - b) * u, i);
    }
    eff.sort();
    eff.reverse();
    while pass - fail > 1 {
        let mid = (pass + fail) / 2;
        let q = (mid / x) as usize;
        let r = mid % x;
        let mut diff = 0;
        for i in 0..n {
            let (_, idx) = eff[i];
            let (b, l, u) = blu[idx];
            if i < q {
                diff += (x - b) * u;
            } else {
                diff -= b * l;
            }
        }
        let mut ok = false;
        for i in 0..n {
            let (ben, idx) = eff[i];
            let (b, l, u) = blu[idx];
            let mut newdiff = diff;
            if i < q {
                newdiff -= ben;
                newdiff += eff[q].0;
            }
            newdiff += if r < b {
                l * r
            } else {
                l * b + u * (r - b)
            };
            if newdiff >= 0 {
                ok = true;
                break;
            }
        }
        if ok {
            pass = mid;
        } else {
            fail = mid;
        }
    }
    puts!("{}\n", pass);
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn calc(mid: i64, x: i64, bs: &Vec<i64>, ls: &Vec<i64>, rs: &Vec<i64>) -> bool {
    let n = bs.len();
    let mut total = 0;
    let mut values = vec![(0, 0); n];
    for i in 0..n {
        total -= bs[i] * ls[i];
        values[i].0 = ls[i] * bs[i] + rs[i] * (x - bs[i]);
        values[i].1 = i;
    }
    values.sort();
    values.reverse();
    let mut used = vec![false; n];
    let mut rest = mid;
    for i in 0..n {
        if rest < x {
            break;
        }
        total += values[i].0;
        used[values[i].1] = true;
        rest -= x;
    }
    values = vec![(0, 0); n];
    for i in 0..n {
        values[i].1 = i;
        if used[i] {
            continue;
        }
        values[i].0 = if rest < bs[i] {
            ls[i] * rest
        } else {
            ls[i] * bs[i] + rs[i] * (rest - bs[i])
        }
    }
    values.sort();
    values.reverse();
    total += values[0].0;
    used[values[0].1] = true;
    return total >= 0;
}

fn main() {
    let n = read::<usize>();
    let x = read::<i64>();
    let mut bs = vec![0; n];
    let mut ls = vec![0; n];
    let mut us = vec![0; n];
    for i in 0..n {
        bs[i] = read::<i64>();
        ls[i] = read::<i64>();
        us[i] = read::<i64>();
    }
    let mut l = -1;
    let mut r = x * n as i64;
    while r - l > 1 {
        let mid = (l + r) / 2;
        if calc(mid, x, &bs, &ls, &us) {
            r = mid;
        } else {
            l = mid;
        }
    }
    println!("{}", r);
}

use std::cmp;
use std::cmp::{min, Reverse};
use std::io::Write;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let x: i64 = sc.read();

    let blu = (0..n)
        .map(|_| (sc.read::<i64>(), sc.read::<i64>(), sc.read::<i64>()))
        .collect::<Vec<_>>();

    if blu.iter().all(|&(b, _, _)| b == 0) {
        println!("0");
        return;
    }
    let mut ng = 0;
    let mut ok = x * (n as i64);
    while ok - ng > 1 {
        let m = (ok + ng) / 2;
        if solve(m, &blu, x) {
            ok = m;
        } else {
            ng = m;
        }
    }
    println!("{}", ok);
}

fn solve(time: i64, blu: &[(i64, i64, i64)], x: i64) -> bool {
    let head = time / x;
    let remain = time % x;
    let n = blu.len();

    let mut lower = 0;
    let mut effect = vec![];
    for i in 0..n {
        let (b, l, u) = blu[i];
        lower += b * l;
        let gain = x * u - b * (u - l);
        effect.push((gain, i));
    }
    effect.sort_by_key(|&(g, _)| Reverse(g));
    for i in 0..(head as usize) {
        let (gain, _) = effect[i];
        if lower < gain {
            return true;
        }
        lower -= gain;
    }

    for i in (head as usize)..n {
        let (_, i) = effect[i];
        let (b, l, u) = blu[i];

        if remain >= b {
            let gain = remain * u - b * (u - l);
            if gain >= lower {
                return true;
            }
        } else {
            let gain = remain * l;
            if gain >= lower {
                return true;
            }
        }
    }
    false
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write_all(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}
